const THREE_ADDON_LOADER_IMPORTS = Object.freeze({
    fbx: 'three/addons/loaders/FBXLoader.js',
    gltf: 'three/addons/loaders/GLTFLoader.js',
    obj: 'three/addons/loaders/OBJLoader.js',
    stl: 'three/addons/loaders/STLLoader.js'
});
const threeAddonLoaderPromises = new Map();

function importThreeAddonLoader(kind) {
    const specifier = THREE_ADDON_LOADER_IMPORTS[kind];
    if (!specifier) return Promise.reject(new Error(`Unsupported Three.js loader: ${kind}`));
    if (!threeAddonLoaderPromises.has(kind)) {
        threeAddonLoaderPromises.set(kind, import(specifier).catch((error) => {
            threeAddonLoaderPromises.delete(kind);
            throw error;
        }));
    }
    return threeAddonLoaderPromises.get(kind);
}

function uiText(value) {
    return window.InoRobotI18n ? window.InoRobotI18n.translate(String(value)) : String(value);
}

function uiFormat(value, replacements = {}) {
    return uiText(value).replace(/\{([A-Za-z0-9_]+)\}/g, (match, key) => (
        Object.prototype.hasOwnProperty.call(replacements, key) ? String(replacements[key]) : match
    ));
}

const NUMERIC_INPUT_SELECTOR = 'input[type="number"], input[data-numeric-input="true"]';
const NUMERIC_INPUT_CONTROL_KEYS = new Set([
    'Backspace', 'Delete', 'Tab', 'Enter', 'Escape',
    'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown',
    'Home', 'End'
]);

function isNumericInputTarget(target) {
    return target instanceof HTMLInputElement && target.matches(NUMERIC_INPUT_SELECTOR);
}

function prepareNumericInputForEditing(input) {
    if (!(input instanceof HTMLInputElement) || input.type !== 'number') return;
    if (!input.dataset.numericInputType) input.dataset.numericInputType = 'number';
    if (input.dataset.numericInputOriginalMode === undefined) {
        input.dataset.numericInputOriginalMode = input.inputMode || '';
    }
    input.dataset.numericInput = 'true';
    input.type = 'text';
    input.inputMode = 'decimal';
}

function restoreNumericInputType(input) {
    if (!(input instanceof HTMLInputElement)
        || input.dataset.numericInputType !== 'number'
        || input.type !== 'text') return;
    input.type = 'number';
    input.inputMode = input.dataset.numericInputOriginalMode || '';
}

function isNumericInputValue(value) {
    return value === ''
        || value === '-'
        || value === '.'
        || value === '-.'
        || /^-?(?:\d+\.?\d*|\.\d+)$/.test(value);
}

function getNumericInputCandidateValue(input, insertedText) {
    const value = input.value || '';
    const start = input.selectionStart ?? value.length;
    const end = input.selectionEnd ?? start;
    return `${value.slice(0, start)}${insertedText}${value.slice(end)}`;
}

function getNumericInputSelection(input) {
    const value = input.value || '';
    const start = Number.isInteger(input.selectionStart)
        ? Math.max(0, Math.min(value.length, input.selectionStart))
        : value.length;
    const end = Number.isInteger(input.selectionEnd)
        ? Math.max(start, Math.min(value.length, input.selectionEnd))
        : start;
    return { start, end };
}

function setNumericInputSelection(input, start, end = start) {
    const restoreNumberType = input.type === 'number';
    try {
        if (restoreNumberType) input.type = 'text';
        input.setSelectionRange(start, end);
    } catch (_) {
        // Number inputs can reject selection APIs in some browsers.
    } finally {
        if (restoreNumberType) input.type = 'number';
    }
}

function prependNumericInputMinus(input) {
    const value = input.value || '';
    const { start, end } = getNumericInputSelection(input);
    if (!value || value.startsWith('-') || start !== end) return false;

    input.value = `-${value}`;
    input.dispatchEvent(new Event('input', { bubbles: true }));
    setNumericInputSelection(input, start + 1, end + 1);
    return true;
}

function sanitizeNumericInputValue(input) {
    const raw = String(input.value || '');
    const hasLeadingMinus = raw.startsWith('-');
    const unsigned = raw.replace(/-/g, '').replace(/[^\d.]/g, '');
    const firstDecimal = unsigned.indexOf('.');
    const normalized = firstDecimal < 0
        ? unsigned
        : `${unsigned.slice(0, firstDecimal + 1)}${unsigned.slice(firstDecimal + 1).replace(/\./g, '')}`;
    const nextValue = `${hasLeadingMinus ? '-' : ''}${normalized}`;
    if (nextValue !== raw) input.value = nextValue;
}

function handleNumericInputKeyDown(event) {
    const input = event.target;
    if (!isNumericInputTarget(input) || event.ctrlKey || event.metaKey || event.altKey) return;
    if (NUMERIC_INPUT_CONTROL_KEYS.has(event.key)) return;
    if (event.key.length !== 1) return;
    if (event.key === '-' && prependNumericInputMinus(input)) {
        event.preventDefault();
        return;
    }
    if (!isNumericInputValue(getNumericInputCandidateValue(input, event.key))) {
        event.preventDefault();
    }
}

function handleNumericInputBeforeInput(event) {
    const input = event.target;
    if (!isNumericInputTarget(input) || !event.data) return;
    if (event.data === '-' && prependNumericInputMinus(input)) {
        event.preventDefault();
        return;
    }
    if (!isNumericInputValue(getNumericInputCandidateValue(input, event.data))) {
        event.preventDefault();
    }
}

function handleNumericInputPaste(event) {
    const input = event.target;
    const text = event.clipboardData?.getData('text') || '';
    if (!isNumericInputTarget(input) || !text) return;
    if (!isNumericInputValue(getNumericInputCandidateValue(input, text))) {
        event.preventDefault();
    }
}

function handleNumericInputDrop(event) {
    const input = event.target;
    const text = event.dataTransfer?.getData('text') || '';
    if (!isNumericInputTarget(input) || !text) return;
    if (!isNumericInputValue(getNumericInputCandidateValue(input, text))) {
        event.preventDefault();
    }
}

function handleNumericInputChange(event) {
    if (isNumericInputTarget(event.target)) sanitizeNumericInputValue(event.target);
}

function handleNumericInputPointerDown(event) {
    prepareNumericInputForEditing(event.target);
}

function handleNumericInputFocus(event) {
    prepareNumericInputForEditing(event.target);
}

function handleNumericInputBlur(event) {
    const input = event.target;
    if (!isNumericInputTarget(input)) return;
    queueMicrotask(() => restoreNumericInputType(input));
}

function setupNumericInputGuards() {
    document.addEventListener('pointerdown', handleNumericInputPointerDown, { capture: true });
    document.addEventListener('focus', handleNumericInputFocus, { capture: true });
    document.addEventListener('blur', handleNumericInputBlur, { capture: true });
    document.addEventListener('keydown', handleNumericInputKeyDown, { capture: true });
    document.addEventListener('beforeinput', handleNumericInputBeforeInput, { capture: true });
    document.addEventListener('paste', handleNumericInputPaste, { capture: true });
    document.addEventListener('drop', handleNumericInputDrop, { capture: true });
    document.addEventListener('input', handleNumericInputChange, { capture: true });
    document.addEventListener('change', handleNumericInputChange, { capture: true });
}

function getDefaultMotionSpeed(robot, motion) {
    if (motion === 'MOVJ') return DEFAULT_MOVJ_SPEED;
    const maximum = Number(robot?.userData?.manifest?.cartesianMotion?.maxSpeed);
    return Math.min(
        DEFAULT_MOVL_SPEED,
        Number.isFinite(maximum) && maximum > 0 ? maximum : DEFAULT_MOVL_SPEED
    );
}

