function isPrimitiveShapeModel(model) {
    return Boolean(model?.userData?.primitiveShape)
        && Boolean(normalizePrimitiveShapeType(model.userData.primitiveShapeType));
}

function normalizePrimitiveShapeNameIndex(value) {
    const number = Number(value);
    return Number.isSafeInteger(number) && number > 0 ? number : null;
}

function parsePrimitiveShapeNameIndex(value) {
    const match = String(value || '').trim().match(/(\d+)\s*$/);
    return normalizePrimitiveShapeNameIndex(match?.[1]);
}

function getPrimitiveShapeNameIndex(model) {
    return normalizePrimitiveShapeNameIndex(model?.userData?.primitiveShapeNameIndex)
        || parsePrimitiveShapeNameIndex(model?.userData?.modelName || model?.name);
}

function getPrimitiveShapeName(type, index) {
    return `${uiText(primitiveShapeDisplayName(type))} ${index}`;
}

function getNextPrimitiveShapeNameIndex(type) {
    const normalizedType = normalizePrimitiveShapeType(type);
    const usedIndexes = new Set(state.models
        .filter((model) => isPrimitiveShapeModel(model)
            && normalizePrimitiveShapeType(model.userData.primitiveShapeType) === normalizedType)
        .map((model) => getPrimitiveShapeNameIndex(model))
        .filter((index) => index !== null));
    let index = 1;
    while (usedIndexes.has(index)) index += 1;
    return index;
}

function refreshPrimitiveShapeNames() {
    const usedIndexesByType = new Map();
    let changed = false;
    state.models.filter((model) => isPrimitiveShapeModel(model)).forEach((model) => {
        const type = normalizePrimitiveShapeType(model.userData.primitiveShapeType);
        if (!type) return;
        const usedIndexes = usedIndexesByType.get(type) || new Set();
        let index = getPrimitiveShapeNameIndex(model);
        if (!index || usedIndexes.has(index)) {
            index = 1;
            while (usedIndexes.has(index)) index += 1;
        }
        usedIndexes.add(index);
        usedIndexesByType.set(type, usedIndexes);

        const modelName = getPrimitiveShapeName(type, index);
        const mesh = getPrimitiveShapeMesh(model);
        if (model.userData.primitiveShapeNameIndex !== index
            || model.userData.modelName !== modelName
            || model.name !== `Primitive: ${modelName}`
            || mesh?.name !== `${modelName} geometry`) {
            changed = true;
        }
        model.userData.primitiveShapeNameIndex = index;
        model.userData.modelName = modelName;
        model.name = `Primitive: ${modelName}`;
        if (mesh) mesh.name = `${modelName} geometry`;
    });
    if (changed) scheduleMotionProjectSave();
    return changed;
}

function isSimulationSnapModel(model) {
    return Boolean(model?.userData?.uploaded || isPrimitiveShapeModel(model)
        || isSketchFeatureModel(model) || isCad2dModel(model));
}

function getPrimitiveShapeDimensions(model) {
    if (!isPrimitiveShapeModel(model)) return null;
    try {
        return normalizePrimitiveShapeDimensions(
            model.userData.primitiveShapeType,
            model.userData.primitiveShapeDimensions
        );
    } catch (_) {
        return null;
    }
}

function isSketchDimensionShapeModel(model) {
    return isSketchFeatureModel(model) && !model.userData.cadExtrudeFeature;
}

function isDimensionEditableShapeModel(model) {
    return isPrimitiveShapeModel(model) || isSketchDimensionShapeModel(model);
}

function getSketchFeatureDimensionBounds(model) {
    if (!isSketchDimensionShapeModel(model)) return null;
    const bounds = (model.userData.sketchProfiles || [])
        .map(normalizeSketchEntityRecord)
        .filter(Boolean)
        .reduce((result, profile) => {
            const entries = [profile, ...(profile.holes || [])];
            entries.forEach((entry) => {
                const entryBounds = getSketchEntityBounds(entry);
                if (!entryBounds) return;
                result.minX = Math.min(result.minX, entryBounds.minX);
                result.maxX = Math.max(result.maxX, entryBounds.maxX);
                result.minY = Math.min(result.minY, entryBounds.minY);
                result.maxY = Math.max(result.maxY, entryBounds.maxY);
            });
            return result;
        }, { minX: Infinity, maxX: -Infinity, minY: Infinity, maxY: -Infinity });
    if (![bounds.minX, bounds.maxX, bounds.minY, bounds.maxY].every(Number.isFinite)) return null;
    return bounds;
}

function getSketchFeatureDimensions(model) {
    const bounds = getSketchFeatureDimensionBounds(model);
    const depth = Number(model?.userData?.sketchExtrudeDepth);
    if (!bounds || !Number.isFinite(depth)) return null;
    return {
        x: Math.max(SKETCH_MIN_SIZE, bounds.maxX - bounds.minX),
        y: Math.max(SKETCH_MIN_SIZE, bounds.maxY - bounds.minY),
        z: Math.max(SKETCH_MIN_SIZE, depth)
    };
}

function getDimensionEditableShapeDimensions(model) {
    if (isPrimitiveShapeModel(model)) return getPrimitiveShapeDimensions(model);
    if (isSketchDimensionShapeModel(model)) return getSketchFeatureDimensions(model);
    return null;
}

function updateDimensionEditableShapeDimension(model, dimensions, axis, value) {
    if (!isDimensionEditableShapeModel(model) || !['x', 'y', 'z'].includes(axis)) {
        throw new TypeError('Unsupported generated shape dimension axis.');
    }
    if (isPrimitiveShapeModel(model)) {
        return updatePrimitiveShapeDimension(model.userData.primitiveShapeType, dimensions, axis, value);
    }
    const next = { ...dimensions, [axis]: value };
    const profiles = getSketchFeatureProfiles(model);
    const circlesOnly = profiles.length > 0 && profiles.every((profile) => profile.type === 'circle');
    if (circlesOnly && (axis === 'x' || axis === 'y')) {
        next.x = value;
        next.y = value;
    }
    const normalized = ['x', 'y', 'z'].reduce((result, key) => {
        const number = Number(next[key]);
        if (!Number.isFinite(number) || number < SKETCH_MIN_SIZE || number > SKETCH_MAX_SIZE) {
            throw new RangeError('Sketch feature dimensions are out of range.');
        }
        result[key] = number;
        return result;
    }, {});
    return normalized;
}

function getPrimitiveShapeMesh(model) {
    if (!isPrimitiveShapeModel(model)) return null;
    return model.children.find((child) => child.userData?.primitiveShapeMesh && child.isMesh)
        || model.children.find((child) => child.isMesh)
        || null;
}

function getPrimitiveShapeBrepFaces(mesh) {
    if (!mesh?.userData?.primitiveShapeMesh || !mesh.geometry) return null;
    // Three.js primitives are rendered as indexed triangles, but BoxGeometry,
    // CylinderGeometry, and ConeGeometry retain groups for their real CAD
    // faces. Preserve those groups for snapping so a planar face is not
    // treated as one arbitrary tessellation triangle.
    const groups = Array.isArray(mesh.geometry.groups) ? [...mesh.geometry.groups] : [];
    const indexCount = mesh.geometry.index?.count
        ?? mesh.geometry.getAttribute?.('position')?.count
        ?? 0;
    if (!groups.length || indexCount < 3) return null;
    const faces = [];
    let expectedStart = 0;
    for (const group of groups.sort((left, right) => Number(left.start) - Number(right.start))) {
        const start = Number(group.start);
        const count = Number(group.count);
        if (!Number.isInteger(start) || !Number.isInteger(count)
            || start !== expectedStart || start < 0 || count < 3 || count % 3 !== 0) {
            return null;
        }
        faces.push({ first: start / 3, last: (start + count) / 3 - 1 });
        expectedStart += count;
    }
    return expectedStart === indexCount ? faces : null;
}

function nextPrimitiveShapeName(type) {
    return getPrimitiveShapeName(type, getNextPrimitiveShapeNameIndex(type));
}

function createPrimitiveShapeGeometry(type, dimensions) {
    const spec = primitiveShapeGeometrySpec(type, dimensions);
    let geometry;
    if (spec.type === 'box') {
        geometry = new THREE.BoxGeometry(spec.width, spec.depth, spec.height);
        geometry.translate(0, 0, spec.height / 2);
    } else if (spec.type === 'cylinder') {
        geometry = new THREE.CylinderGeometry(spec.radius, spec.radius, spec.height, 32);
        geometry.rotateX(Math.PI / 2);
        geometry.translate(0, 0, spec.height / 2);
    } else if (spec.type === 'cone') {
        geometry = new THREE.ConeGeometry(spec.radius, spec.height, 32);
        geometry.rotateX(Math.PI / 2);
        geometry.translate(0, 0, spec.height / 2);
    } else {
        geometry = new THREE.SphereGeometry(spec.radius, 32, 20);
        geometry.translate(0, 0, spec.radius);
    }
    geometry.computeBoundingBox();
    geometry.computeBoundingSphere();
    return geometry;
}

function createPrimitiveShapeRoot(type, dimensions, options = {}) {
    const primitiveShapeType = normalizePrimitiveShapeType(type);
    const primitiveShapeDimensions = normalizePrimitiveShapeDimensions(
        primitiveShapeType,
        dimensions || PRIMITIVE_SHAPE_DEFAULT_DIMENSIONS[primitiveShapeType]
    );
    const primitiveShapeNameIndex = normalizePrimitiveShapeNameIndex(options.primitiveShapeNameIndex)
        || parsePrimitiveShapeNameIndex(options.name)
        || getNextPrimitiveShapeNameIndex(primitiveShapeType);
    const modelName = getPrimitiveShapeName(primitiveShapeType, primitiveShapeNameIndex);
    const root = new THREE.Group();
    root.name = `Primitive: ${modelName}`;
    root.userData = {
        primitiveShape: true,
        primitiveShapeType,
        primitiveShapeDimensions,
        primitiveShapeDimensionUnit: 'mm',
        primitiveShapeSchemaVersion: PRIMITIVE_SHAPE_SCHEMA_VERSION,
        primitiveShapeNameIndex,
        modelName,
        placement: 'scene',
        collisionEnabled: true
    };
    ensureWorkspaceModelId(root, options.workspaceModelId);
    ensureModelTreeId(root);

    const material = new THREE.MeshStandardMaterial({
        color: options.materialColor || '#bfc7d5',
        roughness: 0.58,
        metalness: 0.08
    });
    const mesh = new THREE.Mesh(
        createPrimitiveShapeGeometry(primitiveShapeType, primitiveShapeDimensions),
        material
    );
    mesh.name = `${modelName} geometry`;
    mesh.userData.primitiveShapeMesh = true;
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    root.add(mesh);
    root.visible = options.visible !== false;
    if (options.transform) applyClipboardTransform(root, options.transform);
    if (options.sketchCutFeature) applySketchCutFeature(
        root,
        options.sketchCutFeature.profiles
            || options.sketchCutFeature.profile
            || options.sketchCutFeature,
        options.sketchCutFeature.depth,
        options.sketchCutFeature.direction
    );
    root.updateMatrixWorld(true);
    return root;
}

function applyPrimitiveShapeDimensions(model, dimensions, {
    recordHistoryChange = true,
    status = true
} = {}) {
    if (!isPrimitiveShapeModel(model)) return false;
    let normalized;
    try {
        normalized = normalizePrimitiveShapeDimensions(model.userData.primitiveShapeType, dimensions);
    } catch (_) {
        if (status) setStatus('도형 치수는 0보다 크고 유효한 숫자여야 합니다.', '#ef4444');
        return false;
    }
    const previous = getPrimitiveShapeDimensions(model);
    if (previous && ['x', 'y', 'z'].every((axis) => Math.abs(previous[axis] - normalized[axis]) < 1e-9)) {
        renderPrimitiveShapePanel();
        updatePrimitiveDimensionOverlay();
        return false;
    }
    const historyBefore = recordHistoryChange && !state.historySuspended
        ? captureSceneSnapshot()
        : null;
    rebuildPrimitiveShapeVisual(model, model.userData.primitiveShapeType, normalized);
    model.userData.primitiveShapeDimensions = normalized;
    model.userData.primitiveShapeDimensionUnit = 'mm';
    model.userData.primitiveShapeSchemaVersion = PRIMITIVE_SHAPE_SCHEMA_VERSION;
    model.updateMatrixWorld(true);
    syncModelOutlines();
    if (state.collision.enabled) state.collision.system?.prepare([model]);
    markSceneCollisionDirty(model);
    refreshCollisionDebugOverlays();
    renderPrimitiveShapePanel();
    updatePrimitiveDimensionOverlay();
    requestRender();
    scheduleMotionProjectSave();
    if (historyBefore) recordHistory('도형 치수 변경', historyBefore, captureSceneSnapshot());
    if (status) setStatus('도형 치수가 적용되었습니다.', '#22c55e');
    return true;
}

function applyDimensionEditableShapeDimensions(model, dimensions, options = {}) {
    if (isPrimitiveShapeModel(model)) return applyPrimitiveShapeDimensions(model, dimensions, options);
    if (isSketchDimensionShapeModel(model)) return applySketchFeatureDimensions(model, dimensions, options);
    return false;
}

function renderPrimitiveShapePanel() {
    updatePanelLauncher('shape-panel');
    renderSketchEditorUi();
    renderCadPanel();
    const selected = state.selectedModel;
    const isShapePanelOpen = Boolean(el.shapePanel)
        && !el.shapePanel.classList.contains('panel-user-hidden');
    if (el.shapeSelectedEditor) el.shapeSelectedEditor.hidden = state.sketch.active || !isDimensionEditableShapeModel(selected);
    if (!isDimensionEditableShapeModel(selected)) {
        if (el.shapeSelectedName) el.shapeSelectedName.textContent = '-';
        if (el.shapeSelectedType) el.shapeSelectedType.textContent = '-';
        return;
    }
    const dimensions = getDimensionEditableShapeDimensions(selected);
    if (!dimensions) return;
    if (el.shapeSelectedName) el.shapeSelectedName.textContent = localizedGeneratedModelName(selected);
    if (el.shapeSelectedType) {
        el.shapeSelectedType.textContent = isPrimitiveShapeModel(selected)
            ? uiText(primitiveShapeDisplayName(selected.userData.primitiveShapeType))
            : uiText('스케치 돌출');
    }
    Object.entries(el.shapeSelectedDimensions || {}).forEach(([axis, input]) => {
        if (!input || input === document.activeElement) return;
        input.value = formatJogValue(dimensions[axis]);
    });
    const type = selected.userData.primitiveShapeType;
    const linked = isSketchDimensionShapeModel(selected)
        ? (getSketchFeatureProfiles(selected).every((profile) => profile.type === 'circle')
            ? '원형 스케치는 X/Y 지름이 연결되고 Z는 돌출 높이입니다.'
            : '스케치 돌출은 X/Y/Z를 독립적으로 설정합니다.')
        : type === 'sphere'
            ? '구는 X/Y/Z가 연결됩니다.'
            : type === 'cylinder' || type === 'cone'
                ? '원통형과 원뿔형은 X/Y 지름이 연결됩니다.'
                : '사각형은 X/Y/Z를 독립적으로 설정합니다.';
    if (el.shapeDimensionHelp) el.shapeDimensionHelp.textContent = uiText(linked);
    if (el.shapeSelectedStatus) {
        el.shapeSelectedStatus.textContent = isShapePanelOpen
            ? uiText('치수 라벨을 클릭하면 장면에서 바로 편집할 수 있습니다.')
            : '';
    }
}

function syncPrimitiveShapeDimensionInputs(inputs, type, axis) {
    const value = inputs?.[axis]?.value;
    if (value === undefined) return;
    try {
        const dimensions = updatePrimitiveShapeDimension(
            type,
            Object.fromEntries(Object.entries(inputs).map(([key, input]) => [key, input.value])),
            axis,
            value
        );
        Object.entries(inputs).forEach(([key, input]) => {
            if (input !== document.activeElement) input.value = formatJogValue(dimensions[key]);
        });
    } catch (_) {
        // Keep incomplete number input editable until blur/change validates it.
    }
}

function handlePrimitiveShapeCreate() {
    if (!el.shapeType) return;
    let dimensions;
    try {
        dimensions = normalizePrimitiveShapeDimensions(
            el.shapeType.value,
            Object.fromEntries(Object.entries(el.shapeCreateDimensions || {}).map(([axis, input]) => [axis, input.value]))
        );
    } catch (_) {
        if (el.shapeCreateError) el.shapeCreateError.textContent = uiText('도형 치수는 0보다 크고 유효한 숫자여야 합니다.');
        return;
    }
    if (el.shapeCreateError) el.shapeCreateError.textContent = '';
    const historyBefore = !state.historySuspended ? captureSceneSnapshot() : null;
    const model = createPrimitiveShapeRoot(el.shapeType.value, dimensions);
    state.scene.add(model);
    state.models.push(model);
    if (state.collision.enabled) state.collision.system?.prepare([model]);
    markSceneCollisionDirty(model);
    updateModelRenderComplexity(model);
    updateUIStatus();
    selectSceneModel(model);
    if (historyBefore) recordHistory('도형 생성', historyBefore, captureSceneSnapshot());
    setStatus('도형이 생성되었습니다.', '#22c55e');
}

const SKETCH_MIN_SIZE = 0.5;
const SKETCH_MAX_SIZE = 100000;
const SKETCH_TOOL_TYPES = Object.freeze(['select', 'line', 'rectangle', 'circle', 'chamfer', 'polyline']);
const SKETCH_COMMAND_TOOL_TYPES = Object.freeze([...SKETCH_TOOL_TYPES, 'dimension']);
const SKETCH_POINTER_STEP_MM = 1;
const SKETCH_DIMENSION_GREEN = 0x4ade80;
const SKETCH_SNAP_TOLERANCE = 12;

const normalizeCutDirection = normalizeExtrudeCutDirection;

function sketchToolDisplayName(type) {
    return uiText(type === 'select'
        ? '선택'
        : type === 'dimension'
            ? '치수 기입'
        : type === 'line'
            ? '선'
            : type === 'circle'
                ? '원'
                : type === 'chamfer'
                    ? '모따기'
                    : '스케치 사각형');
}

function isSketchCommandTool(type) {
    return SKETCH_COMMAND_TOOL_TYPES.includes(type);
}

function isSketchFeatureModel(model) {
    return Boolean(model?.userData?.sketchFeature)
        && ['extrude', 'sketch'].includes(model.userData.sketchFeatureType);
}

function isSketchOnlyModel(model) {
    return isSketchFeatureModel(model)
        && model.userData.sketchFeatureType === 'sketch';
}

function isSketchExtrusionModel(model) {
    return isSketchFeatureModel(model)
        && model.userData.sketchFeatureType === 'extrude';
}

function isEditableSketchFeatureModel(model) {
    return isSketchFeatureModel(model)
        && !model.userData.cadExtrudeFeature
        && (isSketchOnlyModel(model)
            ? getStoredSketchFeatureDocument(model).entities.length > 0
            : getSketchFeatureProfiles(model).length > 0);
}

function isGeneratedShapeModel(model) {
    return Boolean(isPrimitiveShapeModel(model)
        || isSketchFeatureModel(model)
        || model?.userData?.cadExtrudeFeature);
}

function isCad2dModel(model) {
    return Boolean(model?.userData?.cad2d)
        && Boolean(model.userData.cadDocument);
}

function getCadDocumentEntry(documentId = state.cad2d.activeDocumentId) {
    if (!documentId) return null;
    return state.cad2d.documents.get(documentId) || null;
}

function getCadDocumentModel(documentId = state.cad2d.activeDocumentId) {
    return getCadDocumentEntry(documentId)?.root || null;
}

function isCadOriginSnapPicking() {
    return Boolean(state.cad2d.originEdit?.snapMode && getCadDocumentModel());
}

function normalizeCadOriginOffset(value) {
    const source = Array.isArray(value)
        ? value
        : [value?.x, value?.y, value?.z];
    return new THREE.Vector3(...['x', 'y', 'z'].map((axis, index) => {
        const number = Number(source[index]);
        return Number.isFinite(number) ? number : 0;
    }));
}

function syncCadOriginEditRoot(root) {
    const edit = state.cad2d.originEdit;
    if (edit.root === root) return edit;
    edit.root = root || null;
    edit.candidates = [];
    edit.hoveredCandidate = null;
    edit.selectedCandidate = null;
    edit.originOffset.copy(normalizeCadOriginOffset(root?.userData?.cadOriginOffset));
    return edit;
}

function setCadOriginSnapReadout(message) {
    const edit = state.cad2d.originEdit;
    edit.snapReadoutMessage = message;
    if (!el.cadOriginSnapReadout) return;
    el.cadOriginSnapReadout.dataset.sourceMessage = message;
    el.cadOriginSnapReadout.textContent = uiText(message);
}

function getCadCandidateWorldPoint(candidate, root = getCadDocumentModel()) {
    if (!candidate || !root || !candidate.sourcePoint) return null;
    const layerGroup = candidate.layerGroup || root;
    layerGroup.updateMatrixWorld(true);
    const worldPoint = candidate.sourcePoint.clone().applyMatrix4(layerGroup.matrixWorld);
    return [worldPoint.x, worldPoint.y, worldPoint.z].every(Number.isFinite) ? worldPoint : null;
}

function getSelectedCadCandidateWorldPoint(root = getCadDocumentModel()) {
    return getCadCandidateWorldPoint(state.cad2d.originEdit?.selectedCandidate, root);
}

function updateCadPointPlacementUi() {
    const edit = state.cad2d.originEdit;
    const worldPoint = getSelectedCadCandidateWorldPoint();
    if (el.cadPointPlacementSummary) {
        el.cadPointPlacementSummary.textContent = worldPoint && edit.selectedCandidate
            ? uiFormat('선택한 CAD 스냅점 · {type} · X {x}, Y {y}, Z {z} mm', {
                type: uiText(snapTypeInfo(edit.selectedCandidate.type).label),
                x: formatCadNumber(worldPoint.x),
                y: formatCadNumber(worldPoint.y),
                z: formatCadNumber(worldPoint.z)
            })
            : uiText('선택한 스냅점 없음');
    }
    if (el.cadPointMove) el.cadPointMove.disabled = !worldPoint;
}

function clearCadSnapCandidate({ clearInputs = true } = {}) {
    const edit = state.cad2d.originEdit;
    edit.selectedCandidate = null;
    if (clearInputs) {
        [el.cadPointTargetX, el.cadPointTargetY, el.cadPointTargetZ].forEach((input) => {
            if (input) input.value = '';
        });
    }
    updateCadPointPlacementUi();
}

function selectCadSnapCandidate(snap) {
    const edit = state.cad2d.originEdit;
    const root = getCadDocumentModel();
    const worldPoint = getCadCandidateWorldPoint(snap, root);
    if (!worldPoint) {
        clearCadSnapCandidate();
        setCadOriginSnapReadout('선택 가능한 CAD 스냅 지점을 가리켜 주세요.');
        return false;
    }
    edit.selectedCandidate = snap;
    [
        [el.cadPointTargetX, worldPoint.x],
        [el.cadPointTargetY, worldPoint.y],
        [el.cadPointTargetZ, worldPoint.z]
    ].forEach(([input, value]) => {
        if (input) input.value = formatCadNumber(value);
    });
    setCadOriginSnapReadout(uiFormat('선택한 CAD 스냅점 · {type} · X {x}, Y {y}, Z {z} mm', {
        type: uiText(snapTypeInfo(snap.type).label),
        x: formatCadNumber(worldPoint.x),
        y: formatCadNumber(worldPoint.y),
        z: formatCadNumber(worldPoint.z)
    }));
    updateCadPointPlacementUi();
    return true;
}

function updateCadOriginEditorUi() {
    const root = getCadDocumentModel();
    const edit = syncCadOriginEditRoot(root);
    if (el.cadOriginSnapType) {
        el.cadOriginSnapType.value = edit.snapType;
        el.cadOriginSnapType.disabled = edit.snapMode;
    }
    if (el.cadOriginReset) {
        const hasOriginOffset = edit.originOffset.lengthSq() > 1e-8;
        el.cadOriginReset.hidden = !hasOriginOffset;
        el.cadOriginReset.disabled = !hasOriginOffset;
    }
    if (el.cadOriginSnapReadout && !edit.snapMode) {
        const offset = edit.originOffset;
        const hasOffset = offset.lengthSq() > 1e-8;
        const selectedPoint = getSelectedCadCandidateWorldPoint(root);
        const message = selectedPoint && edit.selectedCandidate
            ? uiFormat('선택한 CAD 스냅점 · {type} · X {x}, Y {y}, Z {z} mm', {
                type: uiText(snapTypeInfo(edit.selectedCandidate.type).label),
                x: formatCadNumber(selectedPoint.x),
                y: formatCadNumber(selectedPoint.y),
                z: formatCadNumber(selectedPoint.z)
            })
            : hasOffset
            ? uiFormat('현재 기준점 오프셋 · X {x}, Y {y}, Z {z} mm', {
                x: formatCadNumber(offset.x),
                y: formatCadNumber(offset.y),
                z: formatCadNumber(offset.z)
            })
            : uiText('기준점 스냅 안내');
        el.cadOriginSnapReadout.dataset.sourceMessage = selectedPoint || hasOffset ? '' : '기준점 스냅 안내';
        el.cadOriginSnapReadout.textContent = message;
    }
    updateCadPointPlacementUi();
}

function getCadOriginSnapSourcePoints(entity) {
    const sourcePoints = Array.isArray(entity?.geometry?.vertices)
        ? entity.geometry.vertices.map((vertex) => vertex?.point)
        : ['ARC', 'ELLIPSE'].includes(entity?.type)
        ? [entity.renderPoints?.[0], entity.renderPoints?.at(-1)]
        : entity?.renderPoints;
    const rawPoints = Array.isArray(sourcePoints)
        ? sourcePoints
            .map((point) => [Number(point?.[0]) || 0, Number(point?.[1]) || 0])
            .filter((point) => point.every(Number.isFinite))
        : [];
    const points = rawPoints.length > 1
        && Math.hypot(rawPoints[0][0] - rawPoints.at(-1)[0], rawPoints[0][1] - rawPoints.at(-1)[1]) <= 1e-7
        ? rawPoints.slice(0, -1)
        : rawPoints;
    return points;
}

function getCadOriginSnapCandidates(root = getCadDocumentModel()) {
    const edit = state.cad2d.originEdit;
    if (!root || edit.root !== root) syncCadOriginEditRoot(root);
    if (edit.candidates.length) return edit.candidates;

    const candidates = [];
    const seen = new Set();
    const addCandidate = (entity, layerGroup, type, point, suffix) => {
        if (entity?.selectable === false || !Array.isArray(point) || point.length < 2) return;
        const x = Number(point[0]);
        const y = Number(point[1]);
        if (![x, y].every(Number.isFinite)) return;
        const key = `${entity.id}:${type}:${x.toFixed(6)}:${y.toFixed(6)}:${suffix || ''}`;
        if (seen.has(key)) return;
        seen.add(key);
        candidates.push({
            id: `cad-origin-${key}`,
            entityId: entity.id,
            entity,
            type,
            sourcePoint: new THREE.Vector3(x, y, 0),
            layerGroup: layerGroup || root
        });
    };

    root.updateMatrixWorld(true);
    (root.userData.cadDocument?.entities || []).forEach((entity) => {
        const layerGroup = root.userData.cadLayerGroups?.get(entity.layerId) || root;
        const sourcePoints = getCadOriginSnapSourcePoints(entity);
        const points = sourcePoints.length
            ? sourcePoints
            : entity.geometry?.point
            ? [entity.geometry.point]
            : [];
        const isClosed = Boolean(entity.closed);
        if (entity.renderType === 'point' || entity.type === 'POINT') {
            addCandidate(entity, layerGroup, 'endpoint', entity.geometry?.point || points[0], 'point');
            return;
        }

        if (entity.type === 'CIRCLE' || entity.type === 'ARC') {
            addCandidate(entity, layerGroup, 'circle-center', entity.geometry?.center, 'center');
        }
        if (entity.type === 'CIRCLE') return;
        if (isClosed && points.length >= 3) {
            const bounds = points.reduce((result, point) => ({
                minX: Math.min(result.minX, point[0]),
                minY: Math.min(result.minY, point[1]),
                maxX: Math.max(result.maxX, point[0]),
                maxY: Math.max(result.maxY, point[1])
            }), { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity });
            addCandidate(entity, layerGroup, 'rectangle-center', [
                (bounds.minX + bounds.maxX) / 2,
                (bounds.minY + bounds.maxY) / 2
            ], 'bounds-center');
        }
        points.forEach((point, index) => {
            const endpoint = !isClosed && (index === 0 || index === points.length - 1);
            if (isClosed || !endpoint) {
                addCandidate(entity, layerGroup, 'vertex', point, `vertex-${index}`);
            } else {
                addCandidate(entity, layerGroup, 'endpoint', point, `endpoint-${index}`);
            }
        });
        if (points.length < 2 || entity.type === 'CIRCLE') return;
        const segmentCount = isClosed ? points.length : points.length - 1;
        for (let index = 0; index < segmentCount; index += 1) {
            const start = points[index];
            const end = points[(index + 1) % points.length];
            addCandidate(entity, layerGroup, 'edge-midpoint', [
                (start[0] + end[0]) / 2,
                (start[1] + end[1]) / 2
            ], `midpoint-${index}`);
        }
    });
    edit.candidates = candidates;
    return candidates;
}

function findCadSnapAtPointer(pointerEvent, { entityId = null, allowOutsideRadius = false } = {}) {
    if (!state.camera || !state.renderer || !pointerEvent) return null;
    const root = getCadDocumentModel();
    const bounds = state.renderer.domElement.getBoundingClientRect();
    if (!root || bounds.width <= 0 || bounds.height <= 0) return null;
    const edit = syncCadOriginEditRoot(root);
    const requestedType = edit.snapType === 'auto' ? null : edit.snapType;
    const pointerX = pointerEvent.clientX - bounds.left;
    const pointerY = pointerEvent.clientY - bounds.top;
    const nearby = [];
    root.updateMatrixWorld(true);
    state.camera.updateMatrixWorld(true);
    const candidates = getCadOriginSnapCandidates(root);
    candidates.forEach((candidate) => {
        const layerGroup = candidate.layerGroup || root;
        if (!layerGroup.visible || root.userData.cadLayerVisibility?.[candidate.entity.layerId] === false) return;
        if (entityId && candidate.entityId !== entityId) return;
        if (requestedType && candidate.type !== requestedType) return;
        const worldPoint = candidate.sourcePoint.clone().applyMatrix4(layerGroup.matrixWorld);
        const projected = worldPoint.clone().project(state.camera);
        if (!Number.isFinite(projected.x) || !Number.isFinite(projected.y)
            || projected.z < -1 || projected.z > 1) return;
        const screenX = (projected.x * 0.5 + 0.5) * bounds.width;
        const screenY = (-projected.y * 0.5 + 0.5) * bounds.height;
        const pixelDistance = Math.hypot(screenX - pointerX, screenY - pointerY);
        if (!allowOutsideRadius && pixelDistance > SNAP_RADIUS_PX) return;
        nearby.push({
            ...candidate,
            worldPoint,
            projected,
            screenX,
            screenY,
            pixelDistance,
            cameraDistance: state.camera.position.distanceTo(worldPoint)
        });
    });
    nearby.sort(requestedType
        ? (left, right) => left.pixelDistance - right.pixelDistance
        : compareSimulationSnapCandidates);
    return nearby[0] || null;
}

function findCadOriginSnapAtPointer(pointerEvent) {
    if (!isCadOriginSnapPicking()) return null;
    return findCadSnapAtPointer(pointerEvent);
}

function showCadSnapMarker(snap) {
    if (!snap || !el.snapMarker || isSimulationSnapPicking()) {
        if (el.snapMarker && !isSimulationSnapPicking()) el.snapMarker.classList.add('hidden');
        return;
    }
    state.cad2d.originEdit.hoveredCandidate = snap;
    el.snapMarker.style.left = `${snap.screenX}px`;
    el.snapMarker.style.top = `${snap.screenY}px`;
    el.snapMarker.classList.toggle('label-left', snap.screenX > el.canvasContainer.clientWidth - 190);
    el.snapMarker.dataset.snapType = snap.type;
    const info = snapTypeInfo(snap.type);
    const symbol = el.snapMarker.querySelector('span');
    if (symbol) symbol.textContent = info.symbol;
    if (el.snapLabel) {
        el.snapLabel.textContent = `${uiText(info.label)} · X ${formatCadNumber(snap.worldPoint.x)}, Y ${formatCadNumber(snap.worldPoint.y)}, Z ${formatCadNumber(snap.worldPoint.z)}`;
    }
    el.snapMarker.classList.remove('hidden');
}

function applyCadPointPlacement() {
    const root = getCadDocumentModel();
    const edit = syncCadOriginEditRoot(root);
    const currentPoint = getSelectedCadCandidateWorldPoint(root);
    if (!root || !edit.selectedCandidate || !currentPoint) {
        if (el.cadEditorError) el.cadEditorError.textContent = uiText('먼저 도면의 선이나 점을 클릭하세요.');
        return false;
    }
    const inputs = [el.cadPointTargetX, el.cadPointTargetY, el.cadPointTargetZ];
    const targetValues = inputs.map((input) => Number(input?.value));
    if (!targetValues.every(Number.isFinite)) {
        if (el.cadEditorError) el.cadEditorError.textContent = uiText('목표 X, Y, Z를 모두 입력하세요.');
        return false;
    }
    const targetPoint = new THREE.Vector3(...targetValues);
    const deltaWorld = targetPoint.clone().sub(currentPoint);
    if (deltaWorld.lengthSq() <= 1e-10) {
        if (el.cadEditorError) el.cadEditorError.textContent = '';
        setStatus('CAD 선택점이 이미 목표 위치에 있습니다.', '#60a5fa');
        return true;
    }
    const before = !state.historySuspended ? captureSceneSnapshot() : null;
    const parent = root.parent;
    const currentParentPoint = parent
        ? parent.worldToLocal(currentPoint.clone())
        : currentPoint.clone();
    const targetParentPoint = parent
        ? parent.worldToLocal(targetPoint.clone())
        : targetPoint.clone();
    root.position.add(targetParentPoint.sub(currentParentPoint));
    root.updateMatrixWorld(true);
    edit.candidates = [];
    edit.hoveredCandidate = null;
    if (el.cadEditorError) el.cadEditorError.textContent = '';
    renderCadPanel();
    requestRender();
    scheduleMotionProjectSave();
    if (before) recordHistory('CAD 선택점 이동', before, captureSceneSnapshot());
    setStatus('CAD 선택점을 목표 위치로 이동했습니다.', '#22c55e');
    return true;
}

function applyCadOriginSnap(snap) {
    const root = getCadDocumentModel();
    if (!root || !snap?.worldPoint) return false;
    const edit = syncCadOriginEditRoot(root);
    const sourcePoint = snap.sourcePoint?.clone?.() || root.worldToLocal(snap.worldPoint.clone());
    if (![sourcePoint.x, sourcePoint.y, sourcePoint.z].every(Number.isFinite)) return false;
    const before = !state.historySuspended ? captureSceneSnapshot() : null;
    applyModelZeroPointFrame(root, sourcePoint, new THREE.Vector3());
    root.userData.cadOriginOffset = sourcePoint.toArray();
    root.userData.cadOriginSource = {
        entityId: snap.entityId,
        entityType: snap.entity?.type || '',
        snapType: snap.type
    };
    edit.originOffset.copy(sourcePoint);
    edit.candidates = [];
    edit.hoveredCandidate = null;
    setCadOriginSnapMode(false);
    renderCadPanel();
    requestRender();
    scheduleMotionProjectSave();
    if (before) recordHistory('CAD 도면 기준점 변경', before, captureSceneSnapshot());
    setStatus('CAD 기준점을 스냅했습니다.', '#22c55e');
    return true;
}

function resetCadOrigin() {
    const root = getCadDocumentModel();
    if (!root) return;
    const edit = syncCadOriginEditRoot(root);
    if (edit.snapMode) setCadOriginSnapMode(false);
    if (edit.originOffset.lengthSq() <= 1e-8) return;
    const before = !state.historySuspended ? captureSceneSnapshot() : null;
    applyModelZeroPointFrame(root, edit.originOffset.clone().multiplyScalar(-1), new THREE.Vector3());
    edit.originOffset.set(0, 0, 0);
    edit.candidates = [];
    delete root.userData.cadOriginOffset;
    delete root.userData.cadOriginSource;
    renderCadPanel();
    requestRender();
    scheduleMotionProjectSave();
    if (before) recordHistory('CAD 도면 기준점 초기화', before, captureSceneSnapshot());
    setStatus('도면 기준점을 초기화했습니다.', '#22c55e');
}

function setCadOriginSnapMode(enabled) {
    const root = getCadDocumentModel();
    const edit = state.cad2d.originEdit;
    if (!root && enabled) return;
    if (enabled) {
        if (state.measurement.active) closeMeasurementPanel();
        if (state.placement.active) deactivateModelPlacement();
        if (state.zeroPointEdit.active) exitZeroPointEditor();
        if (state.tcpSnapMode) setTcpSnapMode(false);
        if (state.snapMoveMode) {
            state.snapMoveMode = false;
            clearSimulationSnapFaceSelection({ invalidate: false });
            invalidateSimulationSnapCandidates();
            updateSimulationSnapButton();
        }
        syncCadOriginEditRoot(root);
        edit.snapType = el.cadOriginSnapType?.value || edit.snapType || 'auto';
        edit.snapMode = true;
        edit.hoveredCandidate = null;
        setCadOriginSnapReadout('도면의 스냅 점을 선택하세요.');
        setStatus('도면의 스냅 점을 선택하세요.', '#60a5fa');
        captureSimulationSnapMarkerReferenceDistance();
    } else {
        edit.snapMode = false;
        edit.hoveredCandidate = null;
        hideSimulationSnapMarker();
        resetSimulationSnapMarkerCameraScale();
        invalidateSimulationSnapCandidates();
        setCadOriginSnapReadout('기준점 스냅 안내');
    }
    el.canvasContainer?.classList.toggle('cad-origin-snap-picking', edit.snapMode);
    updateCadOriginEditorUi();
}

function getCadSelectedEntity() {
    const entry = getCadDocumentEntry();
    if (!entry) return null;
    const selectedId = [...state.cad2d.selectedEntityIds][0];
    return entry.document.entities.find((entity) => entity.id === selectedId) || null;
}

function getCadProfileRegionById(regionId, root = getCadDocumentModel()) {
    if (!regionId || !root) return null;
    return (root.userData?.cadFaceRegions || []).find((region) => region.id === regionId) || null;
}

function getCadSelectedProfileRegion() {
    const root = getCadDocumentModel();
    const selectedRegion = getCadProfileRegionById(state.cad2d.selectedProfileRegionId, root);
    if (selectedRegion) return selectedRegion;
    const selectedId = [...state.cad2d.selectedEntityIds][0];
    if (!selectedId) return null;
    return (root?.userData?.cadFaceRegions || []).find((region) => region.entityIds.includes(selectedId)) || null;
}

function formatCadNumber(value) {
    const number = Number(value);
    if (!Number.isFinite(number)) return '-';
    return String(Number(number.toFixed(3)));
}

function formatCadPoint(point) {
    return Array.isArray(point)
        ? `(${formatCadNumber(point[0])}, ${formatCadNumber(point[1])}) mm`
        : '-';
}

function getCadEntityWorldPoints(entity, root = getCadDocumentModel()) {
    const points = Array.isArray(entity?.renderPoints) ? entity.renderPoints : [];
    const layerGroup = root?.userData?.cadLayerGroups?.get(entity?.layerId);
    const matrix = layerGroup?.matrixWorld || root?.matrixWorld;
    return points.map((point) => {
        const local = new THREE.Vector3(Number(point[0]) || 0, Number(point[1]) || 0, 0);
        const world = matrix ? local.applyMatrix4(matrix) : local;
        return [world.x, world.y];
    });
}

function getCadLoopWorldPoints(loop, root = getCadDocumentModel()) {
    const sourceEntityId = loop?.entityIds?.[0];
    const sourceEntity = root?.userData?.cadDocument?.entities?.find((entity) => entity.id === sourceEntityId);
    const layerGroup = root?.userData?.cadLayerGroups?.get(sourceEntity?.layerId);
    const matrix = layerGroup?.matrixWorld || root?.matrixWorld;
    return (loop?.points || []).map((point) => {
        const local = new THREE.Vector3(Number(point?.[0]) || 0, Number(point?.[1]) || 0, 0);
        const world = matrix ? local.applyMatrix4(matrix) : local;
        return [world.x, world.y];
    });
}

function isCadClosedProfile(entity) {
    if (!entity) return false;
    if (entity.type === 'CIRCLE') return Number(entity.geometry?.radius) > 0;
    if (!entity.closed || !Array.isArray(entity.renderPoints) || entity.renderPoints.length < 4) return false;
    return Math.abs(polygonSignedArea(entity.renderPoints)) > 1e-6;
}

function getCadProfileWorldPoints(entity) {
    const root = getCadDocumentModel();
    return getCadEntityWorldPoints(entity, root);
}

function createCadProfileShape(entity, region = null) {
    if (region?.outer?.points?.length >= 3) {
        const shape = new THREE.Shape();
        const outerPoints = getCadLoopWorldPoints(region.outer);
        if (outerPoints.length < 3) return null;
        shape.moveTo(outerPoints[0][0], outerPoints[0][1]);
        outerPoints.slice(1).forEach((point) => shape.lineTo(point[0], point[1]));
        shape.closePath();
        (region.holes || []).forEach((hole) => {
            const holePoints = getCadLoopWorldPoints(hole);
            if (holePoints.length < 3) return;
            const path = new THREE.Path();
            path.moveTo(holePoints[0][0], holePoints[0][1]);
            holePoints.slice(1).forEach((point) => path.lineTo(point[0], point[1]));
            path.closePath();
            shape.holes.push(path);
        });
        return shape;
    }
    if (!isCadClosedProfile(entity)) return null;
    if (entity.type === 'CIRCLE') {
        const center = getCadEntityWorldPoints({ ...entity, renderPoints: [entity.geometry.center] })[0];
        const shape = new THREE.Shape();
        shape.absarc(center[0], center[1], Number(entity.geometry.radius) || 0, 0, Math.PI * 2, false);
        return shape;
    }
    const points = getCadProfileWorldPoints(entity).filter((point) => Array.isArray(point));
    if (points.length < 3) return null;
    const uniquePoints = points.length > 1
        && Math.hypot(points[0][0] - points.at(-1)[0], points[0][1] - points.at(-1)[1]) < 1e-7
        ? points.slice(0, -1)
        : points;
    if (uniquePoints.length < 3) return null;
    const shape = new THREE.Shape();
    shape.moveTo(uniquePoints[0][0], uniquePoints[0][1]);
    uniquePoints.slice(1).forEach((point) => shape.lineTo(point[0], point[1]));
    shape.closePath();
    return shape;
}

function cadEntityToSketchProfile(entity) {
    if (!entity) return null;
    if (entity.type === 'CIRCLE') {
        const center = getCadEntityWorldPoints({ ...entity, renderPoints: [entity.geometry.center] })[0];
        return {
            id: `cad-${entity.id}`,
            type: 'circle',
            center: new THREE.Vector3(center[0], center[1], 0),
            radius: Number(entity.geometry.radius) || 0
        };
    }
    if (!isCadClosedProfile(entity)) return null;
    const points = getCadProfileWorldPoints(entity);
    const bounds = points.reduce((result, point) => ({
        minX: Math.min(result.minX, point[0]),
        minY: Math.min(result.minY, point[1]),
        maxX: Math.max(result.maxX, point[0]),
        maxY: Math.max(result.maxY, point[1])
    }), { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity });
    const corners = [[bounds.minX, bounds.minY], [bounds.maxX, bounds.minY], [bounds.maxX, bounds.maxY], [bounds.minX, bounds.maxY]];
    const isRectangle = points.length <= 6 && corners.every((corner) => points.some((point) => (
        Math.hypot(point[0] - corner[0], point[1] - corner[1]) < 1e-4
    )));
    if (!isRectangle) return null;
    return {
        id: `cad-${entity.id}`,
        type: 'rectangle',
        start: new THREE.Vector3(bounds.minX, bounds.minY, 0),
        end: new THREE.Vector3(bounds.maxX, bounds.maxY, 0)
    };
}

function createCadExtrudeFeatureRoot(entity, depth, options = {}) {
    const region = options.region || null;
    const shape = createCadProfileShape(entity, region);
    if (!shape) throw new Error('A closed CAD profile is required.');
    const generatedNameKey = options.generatedNameKey || (options.name ? null : 'CAD 돌출');
    const modelName = options.name || `${uiText(generatedNameKey || 'CAD 돌출')} ${getNextSketchFeatureNameIndex()}`;
    const geometry = new THREE.ExtrudeGeometry(shape, {
        depth,
        steps: 1,
        curveSegments: 48,
        bevelEnabled: false
    });
    geometry.computeBoundingBox();
    geometry.computeBoundingSphere();
    const root = new THREE.Group();
    root.name = `CAD: ${modelName}`;
    root.userData = {
        sketchFeature: true,
        sketchFeatureType: 'extrude',
        sketchFeatureSchemaVersion: 1,
        sketchFeatureNameIndex: getNextSketchFeatureNameIndex(),
        sketchExtrudeDepth: depth,
        cadExtrudeFeature: true,
        cadDocumentId: state.cad2d.activeDocumentId,
        cadProfileEntityId: entity.id,
        cadProfileEntityIds: region?.entityIds ? [...region.entityIds] : [entity.id],
        cadProfileHoleEntityIds: region?.holeEntityIds ? [...region.holeEntityIds] : [],
        cadProfileRegionId: region?.id || null,
        cadProfileType: entity.type,
        cadProfilePoints: region?.outer?.points
            ? getCadLoopWorldPoints(region.outer)
            : getCadProfileWorldPoints(entity),
        cadProfileHolePoints: region?.holes?.map((hole) => getCadLoopWorldPoints(hole)) || [],
        cadProfileGeometry: region
            ? { kind: 'region', holes: region.holes?.length || 0 }
            : entity.type === 'CIRCLE'
                ? { kind: 'circle', center: getCadEntityWorldPoints({ ...entity, renderPoints: [entity.geometry.center] })[0], radius: Number(entity.geometry.radius) || 0 }
                : { kind: 'polygon' },
        modelName,
        generatedNameKey,
        placement: 'scene',
        collisionEnabled: true
    };
    ensureWorkspaceModelId(root, options.workspaceModelId);
    ensureModelTreeId(root);
    const material = new THREE.MeshStandardMaterial({
        color: options.materialColor || '#bfc7d5',
        roughness: 0.58,
        metalness: 0.08
    });
    const mesh = new THREE.Mesh(geometry, material);
    mesh.name = `${modelName} profile`;
    mesh.userData.sketchFeatureMesh = true;
    mesh.userData.cadExtrudeFeature = true;
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    root.add(mesh);
    root.visible = options.visible !== false;
    if (options.transform) applyClipboardTransform(root, options.transform);
    root.updateMatrixWorld(true);
    return root;
}

function updateCadSelectionVisuals() {
    const root = getCadDocumentModel();
    if (root) setCadEntityVisualState(root, state.cad2d.selectedEntityIds, state.cad2d.hoveredEntityId);
}

function setCadSelection(entityIds = [], { toggle = false, profileRegionId = null } = {}) {
    const next = toggle ? new Set(state.cad2d.selectedEntityIds) : new Set();
    entityIds.forEach((id) => {
        if (toggle && next.has(id)) next.delete(id);
        else next.add(id);
    });
    state.cad2d.selectedEntityIds = next;
    state.cad2d.selectedProfileRegionId = next.size && profileRegionId ? profileRegionId : null;
    const selectedSnap = state.cad2d.originEdit.selectedCandidate;
    if (selectedSnap && !next.has(selectedSnap.entityId)) clearCadSnapCandidate();
    updateCadSelectionVisuals();
    renderCadPanel();
}

function clearCadSelection() {
    state.cad2d.selectedEntityIds.clear();
    state.cad2d.selectedProfileRegionId = null;
    state.cad2d.hoveredEntityId = null;
    clearCadSnapCandidate();
    updateCadSelectionVisuals();
    renderCadPanel();
}

function appendCadProperty(list, label, value) {
    const term = document.createElement('dt');
    const description = document.createElement('dd');
    term.textContent = label;
    description.textContent = value;
    list.append(term, description);
}

function renderCadPanel() {
    if (!el.cadPanel) return;
    const entry = getCadDocumentEntry();
    el.cadPanel.hidden = !entry || state.sketch.active;
    if (!entry || state.sketch.active) return;
    const { document: cadDocument, root } = entry;
    syncCadOriginEditRoot(root);
    updateCadOriginEditorUi();
    const source = cadDocument.source || {};
    if (el.cadDocumentSummary) {
        el.cadDocumentSummary.textContent = uiFormat('CAD drawing summary', {
            fileName: source.fileName || '2D CAD',
            entityCount: cadDocument.entities.length,
            layerCount: cadDocument.drawing.layers.length,
            sourceUnit: source.sourceUnit || 'unknown'
        });
    }
    if (el.cadDocumentVisible) el.cadDocumentVisible.checked = root.visible !== false;
    if (el.cadLayerList) {
        el.cadLayerList.replaceChildren();
        cadDocument.drawing.layers.forEach((layer) => {
            const label = document.createElement('label');
            label.className = 'cad-layer-row';
            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.checked = root.userData.cadLayerVisibility?.[layer.id] !== false;
            checkbox.dataset.cadLayerId = layer.id;
            checkbox.setAttribute('aria-label', uiFormat('CAD 레이어 {layer}', { layer: layer.name }));
            const color = document.createElement('span');
            color.className = 'cad-layer-color';
            color.style.background = layer.color || '#38bdf8';
            const name = document.createElement('span');
            name.className = 'cad-layer-name';
            name.textContent = layer.name;
            const count = document.createElement('span');
            count.className = 'cad-layer-count';
            count.textContent = String(layer.entityCount || cadDocument.entities.filter((entity) => entity.layerId === layer.id).length);
            label.append(checkbox, color, name, count);
            el.cadLayerList.appendChild(label);
        });
    }
    const entity = getCadSelectedEntity();
    const profileRegion = getCadSelectedProfileRegion();
    const selectionCount = state.cad2d.selectedEntityIds.size;
    const cadCutSelected = el.cadOperation?.value === 'cut';
    if (el.cadCutDirectionField) el.cadCutDirectionField.hidden = !cadCutSelected;
    if (el.cadCutDirection) el.cadCutDirection.value = normalizeCutDirection(el.cadCutDirection.value);
    if (el.cadSelectionSummary) {
        el.cadSelectionSummary.textContent = entity
            ? profileRegion
                ? uiFormat('CAD selected face summary', {
                    count: selectionCount,
                    type: entity.type,
                    handle: entity.handle,
                    holes: profileRegion.holes?.length || 0
                })
                : uiFormat('CAD selected entity summary', {
                count: selectionCount,
                type: entity.type,
                handle: entity.handle,
                closed: entity.closed ? uiText('CAD closed profile') : ''
                })
            : uiText('CAD 면 선택 안내');
    }
    if (el.cadSelectionProperties) {
        el.cadSelectionProperties.replaceChildren();
        if (entity) {
            appendCadProperty(el.cadSelectionProperties, uiText('CAD 속성 형식'), entity.type);
            appendCadProperty(el.cadSelectionProperties, uiText('CAD 속성 핸들'), entity.handle);
            appendCadProperty(el.cadSelectionProperties, uiText('CAD 속성 레이어'), entity.layerName);
            appendCadProperty(el.cadSelectionProperties, uiText('CAD 속성 경계'), `${formatCadPoint(entity.bounds.min)} ~ ${formatCadPoint(entity.bounds.max)}`);
            appendCadProperty(el.cadSelectionProperties, uiText('CAD 속성 길이'), `${formatCadNumber(entity.length)} mm`);
            if (entity.type === 'CIRCLE' || entity.type === 'ARC') {
                appendCadProperty(el.cadSelectionProperties, uiText('CAD 속성 반지름'), `${formatCadNumber(entity.geometry.radius)} mm`);
                if (entity.type === 'CIRCLE') appendCadProperty(el.cadSelectionProperties, uiText('CAD 속성 지름'), `${formatCadNumber(entity.geometry.radius * 2)} mm`);
            }
            if (entity.geometry?.vertices) appendCadProperty(el.cadSelectionProperties, uiText('CAD 속성 꼭짓점'), String(entity.geometry.vertices.length));
            if (entity.closed) appendCadProperty(el.cadSelectionProperties, uiText('CAD 속성 닫힘'), uiText('예'));
            if (profileRegion) {
                appendCadProperty(el.cadSelectionProperties, uiText('CAD 선택 면'), uiText('CAD 프로파일 면'));
                appendCadProperty(el.cadSelectionProperties, uiText('CAD 내부 구멍'), `${profileRegion.holes?.length || 0}`);
            }
        }
    }
    const canExtrude = selectionCount === 1 && Boolean(profileRegion);
    if (el.cadCreate3d) {
        el.cadCreate3d.disabled = !canExtrude;
        const label = el.cadCreate3d.querySelector('span');
        if (label) label.textContent = uiText(canExtrude ? '선택 면 돌출' : '닫힌 면 선택');
    }
    if (el.cadEditorError && canExtrude) el.cadEditorError.textContent = '';
}

function getCadPickThreshold() {
    const camera = state.camera;
    const height = state.renderer?.domElement?.clientHeight || 720;
    if (!camera?.isPerspectiveCamera) return 5;
    const distance = camera.position.distanceTo(state.controls?.target || new THREE.Vector3());
    return Math.max(0.3, Math.min(40, distance * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)) * 2 / height * 10));
}

function pickCadAtPointer(event) {
    const root = getCadDocumentModel();
    const rect = state.renderer?.domElement?.getBoundingClientRect();
    if (!root || !rect || rect.width <= 0 || rect.height <= 0) return null;
    const pointerNdc = new THREE.Vector2(
        ((event.clientX - rect.left) / rect.width) * 2 - 1,
        -((event.clientY - rect.top) / rect.height) * 2 + 1
    );
    state.camera.updateMatrixWorld(true);
    return pickCadEntity(state.sceneSelectionRaycaster, state.camera, pointerNdc, root, getCadPickThreshold());
}

function handleCadPointerMove(event) {
    if (state.sketch.active || state.cad2d.originEdit.snapMode || event.buttons !== 0 || !getCadDocumentModel()) return;
    const hit = pickCadAtPointer(event);
    const nextId = hit?.entity?.id || null;
    const snap = hit && !isSimulationSnapPicking()
        ? findCadSnapAtPointer(event, { entityId: hit.entity.id })
        : null;
    state.cad2d.originEdit.hoveredCandidate = snap;
    if (snap) showCadSnapMarker(snap);
    else if (!isSimulationSnapPicking()) el.snapMarker?.classList.add('hidden');
    if (state.cad2d.hoveredEntityId === nextId) return;
    state.cad2d.hoveredEntityId = nextId;
    updateCadSelectionVisuals();
    requestRender();
}

function handleCadCanvasClick(event) {
    if (event.button !== 0 || state.sketch.active || state.cad2d.originEdit.snapMode || state.sceneSelectionPointer?.moved) return;
    const hit = pickCadAtPointer(event);
    if (!hit) return;
    const toggle = Boolean(event.shiftKey || event.ctrlKey || event.metaKey);
    setCadSelection([hit.entity.id], { toggle, profileRegionId: hit.face?.id || null });
    if (state.cad2d.selectedEntityIds.has(hit.entity.id)) {
        const snap = findCadSnapAtPointer(event, {
            entityId: hit.entity.id,
            allowOutsideRadius: true
        });
        if (selectCadSnapCandidate(snap) && !isSimulationSnapPicking()) showCadSnapMarker(snap);
    } else {
        clearCadSnapCandidate();
    }
    const root = getCadDocumentModel();
    // Keep an already selected primitive as the cut target. This lets the
    // user select a Box in the model tree, then click a CAD profile without
    // losing the target selection to the CAD document root.
    if (root && (!state.selectedModel || isCad2dModel(state.selectedModel))) selectSceneModel(root);
    event.preventDefault();
    event.stopImmediatePropagation();
}

function fitCadDocument(topOnly = false) {
    const root = getCadDocumentModel();
    if (!root || !state.camera || !state.controls) return;
    const bounds = new THREE.Box3().setFromObject(root);
    if (bounds.isEmpty()) return;
    fitCameraToBounds(bounds, { topOnly });
}

function createCad3dFromSelection() {
    const entity = getCadSelectedEntity();
    const profileRegion = getCadSelectedProfileRegion();
    const depth = Number(el.cadExtrudeDepth?.value);
    const operation = el.cadOperation?.value === 'cut' ? 'cut' : 'add';
    const cutDirection = normalizeCutDirection(el.cadCutDirection?.value);
    if (!entity || !profileRegion) {
        if (el.cadEditorError) el.cadEditorError.textContent = uiText('CAD 면을 먼저 선택하세요.');
        return;
    }
    if (!Number.isFinite(depth) || depth < SKETCH_MIN_SIZE || depth > SKETCH_MAX_SIZE) {
        if (el.cadEditorError) el.cadEditorError.textContent = uiText('Z 높이는 0보다 크고 유효한 숫자여야 합니다.');
        return;
    }
    const historyBefore = !state.historySuspended ? captureSceneSnapshot() : null;
    if (operation === 'cut') {
        const target = state.selectedModel && !isCad2dModel(state.selectedModel) ? state.selectedModel : null;
        if ((profileRegion.holes?.length || 0) > 0) {
            if (el.cadEditorError) el.cadEditorError.textContent = uiText('구멍이 있는 CAD 면은 돌출 컷이 아니라 돌출 작업으로 생성하세요.');
            return;
        }
        const profile = cadEntityToSketchProfile(entity);
        if (!target || !isPrimitiveShapeModel(target) || target.userData.primitiveShapeType !== 'box' || !profile) {
            if (el.cadEditorError) el.cadEditorError.textContent = uiText('CAD 돌출 컷은 먼저 대상 사각형 도형과 직사각형/원 프로파일을 선택하세요.');
            return;
        }
        if (!applySketchCutFeature(target, profile, depth, cutDirection)) return;
        updateUIStatus();
        selectSceneModel(target);
        if (historyBefore) recordHistory('CAD 돌출 컷', historyBefore, captureSceneSnapshot());
        if (el.cadEditorError) el.cadEditorError.textContent = '';
        setStatus(uiText('CAD 프로파일 돌출 컷을 적용했습니다.'), '#22c55e');
        return;
    }
    const model = createCadExtrudeFeatureRoot(entity, depth, { region: profileRegion });
    state.scene.add(model);
    state.models.push(model);
    if (state.collision.enabled) state.collision.system?.prepare([model]);
    markSceneCollisionDirty(model);
    updateModelRenderComplexity(model);
    updateUIStatus();
    selectSceneModel(model);
    if (historyBefore) recordHistory('CAD 프로파일 돌출', historyBefore, captureSceneSnapshot());
    if (el.cadEditorError) el.cadEditorError.textContent = '';
    setStatus(uiText('선택한 CAD 면을 돌출했습니다.'), '#22c55e');
}

function getNextSketchFeatureNameIndex() {
    const used = new Set(state.models
        .filter((model) => isSketchFeatureModel(model))
        .map((model) => Number(model.userData.sketchFeatureNameIndex))
        .filter((value) => Number.isSafeInteger(value) && value > 0));
    let index = 1;
    while (used.has(index)) index += 1;
    return index;
}

function sketchVector(value) {
    if (value?.isVector3) return value.clone();
    const source = Array.isArray(value) ? value : [value?.x, value?.y, value?.z];
    const numbers = source.map(Number);
    return numbers.length >= 2 && numbers.slice(0, 2).every(Number.isFinite)
        ? new THREE.Vector3(numbers[0], numbers[1], Number.isFinite(numbers[2]) ? numbers[2] : 0)
        : null;
}

function serializeSketchEntity(entity) {
    if (!entity || !SKETCH_TOOL_TYPES.includes(entity.type)) return null;
    const pointArray = (point) => point?.toArray ? point.toArray() : Array.isArray(point) ? point.slice(0, 3) : null;
    const result = { id: String(entity.id || ''), type: entity.type };
    if (entity.linetype) result.linetype = normalizeCadLineTypeName(entity.linetype);
    const linePattern = normalizeCadLinePattern(entity.linePattern);
    if (linePattern.length) result.linePattern = linePattern;
    if (entity.start && entity.end) {
        result.start = pointArray(entity.start);
        result.end = pointArray(entity.end);
    }
    if (entity.center) result.center = pointArray(entity.center);
    if (Number.isFinite(entity.radius)) result.radius = Number(entity.radius);
    if (Number.isFinite(entity.chamfer)) result.chamfer = Number(entity.chamfer);
    if (Array.isArray(entity.points)) {
        result.points = entity.points.map(pointArray).filter(Boolean);
        result.closed = entity.closed !== false;
    }
    if (Array.isArray(entity.holes) && entity.holes.length) {
        result.holes = entity.holes.map(serializeSketchEntity).filter(Boolean);
    }
    return result;
}

function createEmptySketchDimensionDraft() {
    return {
        mode: null,
        start: null,
        end: null,
        startRef: null,
        endRef: null,
        target: null
    };
}

function normalizeSketchReference(reference) {
    if (!reference || typeof reference !== 'object') return null;
    const point = sketchVector(reference.point);
    const kind = String(reference.kind || 'free');
    const rawRatio = Number(reference.ratio);
    return {
        kind,
        entityId: reference.entityId ? String(reference.entityId) : null,
        pointIndex: Number.isInteger(reference.pointIndex) ? reference.pointIndex : null,
        segmentIndex: Number.isInteger(reference.segmentIndex) ? reference.segmentIndex : null,
        ratio: Number.isFinite(rawRatio)
            ? kind === 'line-point' ? rawRatio : THREE.MathUtils.clamp(rawRatio, 0, 1)
            : null,
        angle: Number.isFinite(Number(reference.angle)) ? Number(reference.angle) : null,
        corner: reference.corner ? String(reference.corner) : null,
        point: point ? point.toArray() : null
    };
}

function serializeSketchReference(reference) {
    return normalizeSketchReference(reference);
}

function normalizeSketchDimensionLabelOffset(value) {
    const source = Array.isArray(value) ? value : [value?.x, value?.y];
    const x = Number(source?.[0]);
    const y = Number(source?.[1]);
    return Number.isFinite(x) && Number.isFinite(y) ? { x, y } : null;
}

function normalizeSketchDimensionRecord(record) {
    const type = ['distance', 'length', 'diameter', 'position'].includes(record?.type)
        ? record.type
        : 'distance';
    const start = sketchVector(record?.start);
    const end = sketchVector(record?.end);
    const rawXValue = Number(record?.xValue);
    const rawYValue = Number(record?.yValue);
    const xValue = Number.isFinite(rawXValue) ? rawXValue : start && end ? end.x - start.x : 0;
    const yValue = Number.isFinite(rawYValue) ? rawYValue : start && end ? end.y - start.y : 0;
    const axis = type === 'position'
        ? (record?.axis === 'x' || record?.axis === 'y'
            ? record.axis
            : Math.abs(xValue) >= Math.abs(yValue) ? 'x' : 'y')
        : null;
    const rawValue = Number(record?.value);
    const value = type === 'position'
        ? Math.abs(axis === 'x' ? xValue : yValue)
        : rawValue;
    if (!start || !end) return null;
    if (!Number.isFinite(value) || value < SKETCH_MIN_SIZE) return null;
    return {
        id: String(record.id || `dimension-${Date.now()}-${Math.random().toString(36).slice(2)}`),
        type,
        start,
        end,
        value: THREE.MathUtils.clamp(value, SKETCH_MIN_SIZE, SKETCH_MAX_SIZE),
        xValue: type === 'position' ? (Number.isFinite(xValue) ? xValue : end.x - start.x) : null,
        yValue: type === 'position' ? (Number.isFinite(yValue) ? yValue : end.y - start.y) : null,
        axis,
        entityId: record.entityId ? String(record.entityId) : null,
        edgeIndex: Number.isInteger(record.edgeIndex) ? record.edgeIndex : null,
        startRef: normalizeSketchReference(record.startRef),
        endRef: normalizeSketchReference(record.endRef),
        drivingRef: record.drivingRef === 'start' || record.drivingRef === 'end'
            ? record.drivingRef
            : null,
        labelOffset: normalizeSketchDimensionLabelOffset(record.labelOffset),
        reference: record.reference === true,
        referenceEntityIds: Array.isArray(record.referenceEntityIds)
            ? [...new Set(record.referenceEntityIds.map(String).filter(Boolean))]
            : []
    };
}

function serializeSketchDimension(dimension) {
    const normalized = normalizeSketchDimensionRecord(dimension);
    if (!normalized) return null;
    return {
        id: normalized.id,
        type: normalized.type,
        start: normalized.start.toArray(),
        end: normalized.end.toArray(),
        value: normalized.value,
        xValue: normalized.xValue,
        yValue: normalized.yValue,
        axis: normalized.axis,
        entityId: normalized.entityId,
        edgeIndex: normalized.edgeIndex,
        startRef: serializeSketchReference(normalized.startRef),
        endRef: serializeSketchReference(normalized.endRef),
        drivingRef: normalized.drivingRef,
        labelOffset: normalized.labelOffset
            ? [normalized.labelOffset.x, normalized.labelOffset.y]
            : null,
        reference: normalized.reference,
        referenceEntityIds: normalized.referenceEntityIds
    };
}

function syncSketchDocumentEntities() {
    const document = state.sketch.document;
    if (!document) return null;
    state.sketch.previewRevision += 1;
    state.sketch.snapCandidatesCache = null;
    state.sketch.snapCandidatesRevision = -1;
    state.sketch.entitySpatialIndex = null;
    state.sketch.entitySpatialIndexRevision = -1;
    state.sketch.closedLineLoopsCache = null;
    state.sketch.closedLineLoopsRevision = -1;
    state.sketch.profileRegionsCache = null;
    state.sketch.profileRegionsRevision = -1;
    refreshSketchDimensionReferences();
    document.entities = state.sketch.entities
        .map(serializeSketchEntity)
        .filter(Boolean);
    document.dimensions = state.sketch.dimensions
        .map(serializeSketchDimension)
        .filter(Boolean);
    document.settings = {
        ...(document.settings || {}),
        snapEnabled: state.sketch.snapEnabled !== false
    };
    return document;
}

function captureSketchEditSnapshot() {
    const sketch = state.sketch;
    return {
        origin: sketch.origin.toArray(),
        entities: sketch.entities.map(serializeSketchEntity).filter(Boolean),
        dimensions: sketch.dimensions.map(serializeSketchDimension).filter(Boolean),
        selectedEntityId: sketch.selectedEntityId,
        selectedEntityIds: [...sketch.selectedEntityIds],
        selectedDimensionId: sketch.selectedDimensionId,
        snapEnabled: sketch.snapEnabled !== false,
        importSources: JSON.parse(JSON.stringify(sketch.document?.importSources || []))
    };
}

function sketchEditSnapshotsEqual(left, right) {
    return JSON.stringify(left || null) === JSON.stringify(right || null);
}

function recordSketchHistory(label, before) {
    const sketch = state.sketch;
    if (!sketch.active || sketch.historySuspended || !before) return false;
    const after = captureSketchEditSnapshot();
    if (sketchEditSnapshotsEqual(before, after)) return false;
    sketch.undoStack.push({ label, before, after });
    if (sketch.undoStack.length > 100) sketch.undoStack.shift();
    sketch.redoStack = [];
    updateHistoryButtons();
    return true;
}

function applySketchEditSnapshot(snapshot) {
    const sketch = state.sketch;
    if (!snapshot) return false;
    sketch.historySuspended = true;
    sketch.entities = (snapshot.entities || []).map(normalizeSketchEntityRecord).filter(Boolean);
    sketch.dimensions = (snapshot.dimensions || []).map(normalizeSketchDimensionRecord).filter(Boolean);
    sketch.origin.fromArray(snapshot.origin || [0, 0, 0]);
    sketch.selectedEntityId = sketch.entities.some((entry) => entry.id === snapshot.selectedEntityId)
        ? snapshot.selectedEntityId
        : null;
    sketch.selectedEntityIds = new Set(
        (Array.isArray(snapshot.selectedEntityIds) ? snapshot.selectedEntityIds : [])
            .map(String)
            .filter((id) => sketch.entities.some((entry) => entry.id === id))
    );
    if (sketch.selectedEntityId) sketch.selectedEntityIds.add(sketch.selectedEntityId);
    sketch.selectedDimensionId = sketch.dimensions.some((entry) => entry.id === snapshot.selectedDimensionId)
        ? snapshot.selectedDimensionId
        : null;
    sketch.snapEnabled = snapshot.snapEnabled !== false;
    if (sketch.document) sketch.document.importSources = JSON.parse(JSON.stringify(snapshot.importSources || []));
    sketch.dimensionPlacement = null;
    sketch.dimensionAnnotationEditing = null;
    sketch.dimensionEditing = null;
    sketch.dimensionLabelDrag = null;
    sketch.dimensionLineDrag = null;
    sketch.dimensionDraft = createEmptySketchDimensionDraft();
    sketch.phase = 'draw';
    sketch.pointerId = null;
    sketch.startPoint = null;
    sketch.endPoint = null;
    sketch.rectangleCenterMode = false;
    sketch.draggingEntityId = null;
    sketch.draggingEntityBefore = null;
    clearSketchSelectionBox();
    sketch.historyBefore = null;
    sketch.snapCandidate = null;
    sketch.dimensionHoverTarget = null;
    sketch.hoverEntityId = null;
    syncSketchDocumentEntities();
    updateSketchPreview();
    renderSketchEditorUi();
    requestRender();
    sketch.historySuspended = false;
    return true;
}

function undoSketchAction() {
    const sketch = state.sketch;
    if (!sketch.active) return false;
    if (sketch.dimensionAnnotationEditing) finishSketchDimensionAnnotationEdit(true);
    if (sketch.dimensionEditing) finishSketchDimensionEdit(true);
    if (sketch.dimensionPlacement) {
        cancelSketchDimensionPlacement({ remove: true });
        sketch.historyBefore = null;
        updateSketchPreview();
        renderSketchEditorUi();
        setStatus(uiText('현재 스케치 명령을 취소했습니다. 스케치 편집은 계속됩니다.'), '#60a5fa');
        return true;
    }
    const entry = sketch.undoStack.pop();
    if (!entry) return false;
    applySketchEditSnapshot(entry.before);
    sketch.redoStack.push(entry);
    updateHistoryButtons();
    setStatus(uiFormat('되돌리기: {action}', { action: uiText(entry.label) }), '#60a5fa');
    return true;
}

function redoSketchAction() {
    const sketch = state.sketch;
    if (!sketch.active) return false;
    if (sketch.dimensionAnnotationEditing) finishSketchDimensionAnnotationEdit(true);
    if (sketch.dimensionEditing) finishSketchDimensionEdit(true);
    if (sketch.dimensionPlacement) {
        cancelSketchDimensionPlacement({ remove: true });
        sketch.historyBefore = null;
        updateSketchPreview();
        renderSketchEditorUi();
        setStatus(uiText('현재 스케치 명령을 취소했습니다. 스케치 편집은 계속됩니다.'), '#60a5fa');
        return true;
    }
    const entry = sketch.redoStack.pop();
    if (!entry) return false;
    applySketchEditSnapshot(entry.after);
    sketch.undoStack.push(entry);
    updateHistoryButtons();
    setStatus(uiFormat('다시 실행: {action}', { action: uiText(entry.label) }), '#60a5fa');
    return true;
}

function normalizeSketchEntityRecord(record) {
    const type = SKETCH_TOOL_TYPES.includes(record?.type) ? record.type : null;
    if (!type) return null;
    const entity = { id: String(record.id || `sketch-${Date.now()}-${Math.random().toString(36).slice(2)}`), type };
    const linetype = String(record?.linetype || record?.lineType || '').trim();
    if (linetype) entity.linetype = normalizeCadLineTypeName(linetype);
    const linePattern = normalizeCadLinePattern(record?.linePattern);
    if (linePattern.length) entity.linePattern = linePattern;
    if (type === 'polyline') {
        entity.points = (Array.isArray(record.points) ? record.points : [])
            .map(sketchVector)
            .filter(Boolean);
        entity.closed = record.closed !== false;
        if (entity.points.length < (entity.closed ? 3 : 2)) return null;
    } else if (type === 'line' || type === 'rectangle' || type === 'chamfer') {
        entity.start = sketchVector(record.start);
        entity.end = sketchVector(record.end);
        if (!entity.start || !entity.end) return null;
        if (type === 'chamfer') {
            const maxChamfer = Math.max(SKETCH_MIN_SIZE, Math.min(
                Math.abs(entity.end.x - entity.start.x),
                Math.abs(entity.end.y - entity.start.y)
            ) * 0.49);
            entity.chamfer = THREE.MathUtils.clamp(Number(record.chamfer) || 0, 0, maxChamfer);
        }
    } else if (type === 'circle') {
        entity.center = sketchVector(record.center);
        entity.radius = Number(record.radius);
        if (!entity.center || !Number.isFinite(entity.radius) || entity.radius < SKETCH_MIN_SIZE) return null;
    }
    if (Array.isArray(record.holes)) {
        entity.holes = record.holes
            .map((hole) => normalizeSketchEntityRecord(hole))
            .filter(Boolean);
    }
    return entity;
}

function cloneSketchEntity(entity) {
    return normalizeSketchEntityRecord(serializeSketchEntity(entity));
}

function scaleSketchEntity(entity, center, scaleX, scaleY) {
    const scaled = cloneSketchEntity(entity);
    if (!scaled || !center) return scaled;
    const scalePoint = (point) => {
        if (!point) return;
        point.x = center.x + (point.x - center.x) * scaleX;
        point.y = center.y + (point.y - center.y) * scaleY;
    };
    scalePoint(scaled.start);
    scalePoint(scaled.end);
    scalePoint(scaled.center);
    scaled.points?.forEach(scalePoint);
    if (Number.isFinite(scaled.radius)) {
        // The sketch schema stores circles as a radius rather than an ellipse.
        // Circular feature dimensions are linked, so a uniform factor is used
        // here even when an imported document contains mixed profile types.
        scaled.radius *= (Math.abs(scaleX) + Math.abs(scaleY)) / 2;
    }
    if (Number.isFinite(scaled.chamfer)) {
        scaled.chamfer *= (Math.abs(scaleX) + Math.abs(scaleY)) / 2;
    }
    if (Array.isArray(scaled.holes)) {
        scaled.holes = scaled.holes
            .map((hole) => scaleSketchEntity(hole, center, scaleX, scaleY))
            .filter(Boolean);
    }
    return normalizeSketchEntityRecord(serializeSketchEntity(scaled));
}

function scaleSketchDimensionRecord(record, center, scaleX, scaleY) {
    const dimension = normalizeSketchDimensionRecord(record);
    if (!dimension || !center) return dimension;
    const scalePoint = (point) => new THREE.Vector3(
        center.x + (point.x - center.x) * scaleX,
        center.y + (point.y - center.y) * scaleY,
        point.z
    );
    const start = scalePoint(dimension.start);
    const end = scalePoint(dimension.end);
    const delta = end.clone().sub(start);
    const next = {
        ...serializeSketchDimension(dimension),
        start: start.toArray(),
        end: end.toArray(),
        xValue: dimension.xValue === null ? null : delta.x,
        yValue: dimension.yValue === null ? null : delta.y
    };
    if (dimension.type === 'position') {
        next.value = Math.abs(dimension.axis === 'x' ? delta.x : delta.y);
    } else if (dimension.type === 'length' || dimension.type === 'distance') {
        next.value = delta.length();
    } else if (dimension.type === 'diameter') {
        next.value = Math.abs(dimension.value) * (Math.abs(scaleX) + Math.abs(scaleY)) / 2;
    }
    return normalizeSketchDimensionRecord(next);
}

function translateSketchEntity(entity, offset) {
    const translated = cloneSketchEntity(entity);
    if (!translated || !offset) return translated;
    if (translated.center) translated.center.add(offset);
    if (translated.start) translated.start.add(offset);
    if (translated.end) translated.end.add(offset);
    if (translated.points) translated.points.forEach((point) => point.add(offset));
    if (translated.holes) {
        translated.holes = translated.holes
            .map((hole) => translateSketchEntity(hole, offset))
            .filter(Boolean);
    }
    return translated;
}

function getSketchEntity(entityId = state.sketch.selectedEntityId) {
    return state.sketch.entities.find((entity) => entity.id === entityId)
        || state.sketch.entities.at(-1)
        || null;
}

function isSketchEntitySelected(entityId) {
    const sketch = state.sketch;
    return entityId === sketch.selectedEntityId || sketch.selectedEntityIds?.has(entityId);
}

function getSketchEntityDimensions(entity) {
    if (!entity) return null;
    if (entity.type === 'circle') return { x: entity.radius * 2, y: null };
    if (entity.type === 'line') return { x: entity.start.distanceTo(entity.end), y: null };
    if (entity.type === 'polyline') {
        const bounds = entity.points.reduce((result, point) => ({
            minX: Math.min(result.minX, point.x),
            maxX: Math.max(result.maxX, point.x),
            minY: Math.min(result.minY, point.y),
            maxY: Math.max(result.maxY, point.y)
        }), { minX: Infinity, maxX: -Infinity, minY: Infinity, maxY: -Infinity });
        return { x: bounds.maxX - bounds.minX, y: bounds.maxY - bounds.minY };
    }
    return {
        x: Math.abs(entity.end.x - entity.start.x),
        y: Math.abs(entity.end.y - entity.start.y)
    };
}

function getSketchLineEndpointKey(point) {
    if (!point || !Number.isFinite(point.x) || !Number.isFinite(point.y)) return null;
    const epsilon = 1e-4;
    return `${Math.round(point.x / epsilon)}:${Math.round(point.y / epsilon)}`;
}

function getSketchClosedLineLoops() {
    const sketch = state.sketch;
    // Large imported drawings are rendered as a single line buffer. Building
    // a topology graph for every LINE entity here only delays first paint and
    // is not needed for dense-document selection.
    if (isDenseSketchDocument(sketch)) {
        sketch.closedLineLoopsCache = [];
        sketch.closedLineLoopsRevision = sketch.previewRevision;
        return sketch.closedLineLoopsCache;
    }
    if (sketch.closedLineLoopsCache
        && sketch.closedLineLoopsRevision === sketch.previewRevision) {
        return sketch.closedLineLoopsCache;
    }
    const lineEntries = sketch.entities
        .map((entity) => ({
            entity,
            startKey: getSketchLineEndpointKey(entity?.start),
            endKey: getSketchLineEndpointKey(entity?.end)
        }))
        .filter((entry) => entry.entity?.type === 'line'
            && entry.startKey
            && entry.endKey
            && entry.startKey !== entry.endKey
            && !isSketchConstructionEntity(entry.entity)
            && entry.entity.start?.distanceTo(entry.entity.end) > 1e-6);
    const adjacency = new Map();
    const addAdjacentEdge = (key, entry) => {
        const edges = adjacency.get(key) || [];
        edges.push(entry);
        adjacency.set(key, edges);
    };
    lineEntries.forEach((entry) => {
        addAdjacentEdge(entry.startKey, entry);
        addAdjacentEdge(entry.endKey, entry);
    });

    const visitedEdges = new Set();
    const loops = [];
    lineEntries.forEach((startEntry) => {
        if (visitedEdges.has(startEntry)) return;
        const startVertexKey = startEntry.startKey;
        const startEdges = adjacency.get(startVertexKey) || [];
        if (startEdges.length !== 2
            || (adjacency.get(startEntry.endKey) || []).length !== 2) {
            return;
        }
        const points = [startEntry.entity.start.clone(), startEntry.entity.end.clone()];
        const loopEntries = new Set([startEntry]);
        let currentEntry = startEntry;
        let currentVertexKey = startEntry.endKey;
        let closed = false;
        while (currentVertexKey !== startVertexKey) {
            const nextEntry = (adjacency.get(currentVertexKey) || [])
                .find((entry) => entry !== currentEntry);
            if (!nextEntry || loopEntries.has(nextEntry)) break;
            if ((adjacency.get(currentVertexKey) || []).length !== 2) break;
            loopEntries.add(nextEntry);
            const nextPoint = nextEntry.startKey === currentVertexKey
                ? nextEntry.entity.end
                : nextEntry.entity.start;
            points.push(nextPoint.clone());
            currentVertexKey = nextEntry.startKey === currentVertexKey
                ? nextEntry.endKey
                : nextEntry.startKey;
            currentEntry = nextEntry;
            if (loopEntries.size > lineEntries.length) break;
        }
        closed = currentVertexKey === startVertexKey
            && loopEntries.size >= 3
            && points.length >= 3;
        loopEntries.forEach((entry) => visitedEdges.add(entry));
        if (!closed) return;
        if (points.length > 1 && points[0].distanceTo(points.at(-1)) <= 1e-6) points.pop();
        const signedArea = points.reduce((area, point, index) => {
            const next = points[(index + 1) % points.length];
            return area + point.x * next.y - next.x * point.y;
        }, 0) / 2;
        if (Math.abs(signedArea) < 1e-8) return;
        const sourceEntityIds = [...loopEntries]
            .map((entry) => entry.entity.id)
            .sort();
        loops.push({
            id: `sketch-line-loop-${sourceEntityIds.join('-')}`,
            type: 'polyline',
            points,
            closed: true,
            sourceEntityIds
        });
    });
    sketch.closedLineLoopsCache = loops;
    sketch.closedLineLoopsRevision = sketch.previewRevision;
    return loops;
}

function isSketchClosedProfile(entity) {
    return !isSketchConstructionEntity(entity)
        && (entity?.type === 'rectangle'
        || entity?.type === 'circle'
        || entity?.type === 'chamfer'
        || (entity?.type === 'polyline' && entity.closed !== false));
}

function isSketchConstructionEntity(entity) {
    return Boolean(entity && getCadLineDashSpec(entity.linetype, entity.linePattern));
}

function getSketchProfileSelectionIds(profile) {
    if (Array.isArray(profile?.sourceEntityIds) && profile.sourceEntityIds.length) {
        return [...new Set(profile.sourceEntityIds.map(String).filter(Boolean))];
    }
    return profile?.id ? [profile.id] : [];
}

function isSketchProfileSelected(profile) {
    const selectionIds = getSketchProfileSelectionIds(profile);
    return selectionIds.length > 0 && selectionIds.every((id) => isSketchEntitySelected(id));
}

function isSketchProfileHovered(profile) {
    return getSketchProfileSelectionIds(profile).includes(state.sketch.hoverEntityId);
}

function getSketchProfileSourceIds(profile) {
    if (Array.isArray(profile?.sourceEntityIds) && profile.sourceEntityIds.length) {
        return [...new Set(profile.sourceEntityIds.map(String).filter(Boolean))];
    }
    return profile?.id ? [String(profile.id)] : [];
}

function getSketchProfileBoundaryArea(profile) {
    const points = getSketchProfileBoundaryPoints(profile);
    if (points.length < 3) return null;
    const signedArea = polygonSignedArea(points.map((point) => [point.x, point.y]));
    if (!Number.isFinite(signedArea) || Math.abs(signedArea) <= 1e-7) return null;
    return {
        points,
        signedArea,
        area: Math.abs(signedArea)
    };
}

function getSketchProfileRegionContainsPoint(region, point) {
    const outerPoints = getSketchProfileBoundaryPoints(region);
    if (!isSketchPointInsidePolygon(point, outerPoints)) return false;
    return !(region.holes || []).some((hole) => (
        isSketchPointInsidePolygon(point, getSketchProfileBoundaryPoints(hole))
    ));
}

function getSketchProfileRegions() {
    const sketch = state.sketch;
    if (sketch.profileRegionsCache
        && sketch.profileRegionsRevision === sketch.previewRevision) {
        return sketch.profileRegionsCache;
    }
    if (isDenseSketchDocument(sketch)) {
        // Dense sketches intentionally expose only standalone closed entities
        // as profiles. This avoids the O(n²) nesting work used by normal-sized
        // sketches while retaining selectable closed DXF entities for extrude.
        const regions = sketch.entities
            .filter(isSketchClosedProfile)
            .map((profile) => ({
                ...profile,
                profileRegion: true,
                sourceEntityIds: getSketchProfileSourceIds(profile),
                outerEntityIds: getSketchProfileSourceIds(profile),
                holeEntityIds: [],
                holes: []
            }));
        sketch.profileRegionsCache = regions;
        sketch.profileRegionsRevision = sketch.previewRevision;
        return regions;
    }
    const profiles = sketch.entities
        .filter(isSketchClosedProfile)
        .concat(getSketchClosedLineLoops());
    const entries = profiles
        .map((profile) => ({ profile, boundary: getSketchProfileBoundaryArea(profile) }))
        .filter((entry) => entry.boundary);
    // Avoid a quadratic nesting pass for very large imported sketches. The
    // dense preview keeps those entities selectable individually; returning
    // standalone regions here preserves that behavior without freezing the
    // workbench while still allowing normal-sized sketches to form holes.
    if (entries.length > 4096) {
        const regions = entries.map(({ profile }) => ({
            ...profile,
            profileRegion: true,
            sourceEntityIds: getSketchProfileSourceIds(profile),
            outerEntityIds: getSketchProfileSourceIds(profile),
            holeEntityIds: [],
            holes: []
        }));
        sketch.profileRegionsCache = regions;
        sketch.profileRegionsRevision = sketch.previewRevision;
        return regions;
    }
    const parents = entries.map((entry, entryIndex) => {
        const child = entry.boundary;
        return entries
            .map((candidate, candidateIndex) => ({ candidate, candidateIndex }))
            .filter(({ candidate, candidateIndex }) => (
                candidateIndex !== entryIndex
                && candidate.boundary.area > child.area + 1e-7
                && child.points.every((point) => isSketchPointInsidePolygon(
                    point,
                    candidate.boundary.points
                ))
            ))
            .sort((left, right) => left.candidate.boundary.area - right.candidate.boundary.area)
            .at(0)?.candidateIndex ?? -1;
    });
    const depths = entries.map((_, entryIndex) => {
        let depth = 0;
        let parent = parents[entryIndex];
        const visited = new Set();
        while (parent >= 0 && !visited.has(parent)) {
            visited.add(parent);
            depth += 1;
            parent = parents[parent];
        }
        return depth;
    });
    const regions = entries
        .map((entry, entryIndex) => ({ entry, entryIndex }))
        .filter(({ entryIndex }) => depths[entryIndex] % 2 === 0)
        .map(({ entry, entryIndex }) => {
            const outer = entry.profile;
            const holes = entries
                .map((candidate, candidateIndex) => ({ candidate, candidateIndex }))
                .filter(({ candidateIndex }) => (
                    parents[candidateIndex] === entryIndex
                    && depths[candidateIndex] === depths[entryIndex] + 1
                ))
                .map(({ candidate }) => candidate.profile);
            const sourceEntityIds = getSketchProfileSourceIds(outer);
            return {
                ...outer,
                profileRegion: true,
                sourceEntityIds,
                outerEntityIds: [...sourceEntityIds],
                holeEntityIds: holes.flatMap((hole) => getSketchProfileSourceIds(hole)),
                holes
            };
        });
    sketch.profileRegionsCache = regions;
    sketch.profileRegionsRevision = sketch.previewRevision;
    return regions;
}

function getSketchClosedProfiles() {
    return getSketchProfileRegions();
}

function getSelectedSketchProfiles() {
    const sketch = state.sketch;
    if (isDenseSketchDocument(sketch)) {
        return sketch.entities.filter((entity) => (
            isSketchClosedProfile(entity) && isSketchEntitySelected(entity.id)
        ));
    }
    return getSketchClosedProfiles().filter(isSketchProfileSelected);
}

function startSketchExtrudeFlow(operation = 'add') {
    const sketch = state.sketch;
    if (!sketch.active) return false;
    sketch.operation = operation === 'cut' ? 'cut' : 'add';
    if (el.sketchOperation) el.sketchOperation.value = sketch.operation;
    const profiles = getSelectedSketchProfiles();
    if (!profiles.length) {
        sketch.extrudePanelOpen = false;
        sketch.extrudeSelectionMode = true;
        selectSketchTool('select', { remember: false });
        renderSketchWorkbenchUi();
        setStatus(uiText('돌출할 닫힌 스케치 항목을 선택하세요. Shift 키로 여러 항목을 선택할 수 있습니다.'), '#facc15');
        requestRender();
        return false;
    }
    sketch.extrudeSelectionMode = false;
    sketch.extrudePanelOpen = true;
    sketch.phase = 'draw';
    renderSketchWorkbenchUi();
    setStatus(
        uiFormat(
            sketch.operation === 'cut'
                ? '선택된 {count}개 스케치 항목의 Z 깊이를 설정하세요.'
                : '선택된 {count}개 스케치 항목의 Z 높이를 설정하세요.',
            { count: profiles.length }
        ),
        '#22d3ee'
    );
    requestRender();
    return true;
}

function cancelSketchExtrudeFlow() {
    const sketch = state.sketch;
    if (!sketch.active) return false;
    sketch.extrudeSelectionMode = false;
    sketch.extrudePanelOpen = false;
    renderSketchWorkbenchUi();
    setStatus(uiText('돌출 설정을 취소했습니다. 스케치 편집은 계속됩니다.'), '#94a3b8');
    requestRender();
    return true;
}

function applySketchExtrudeFlow() {
    const sketch = state.sketch;
    const profiles = getSelectedSketchProfiles();
    if (!profiles.length) {
        sketch.extrudePanelOpen = false;
        sketch.extrudeSelectionMode = true;
        renderSketchWorkbenchUi();
        setStatus(uiText('돌출할 닫힌 스케치 항목을 선택하세요. Shift 키로 여러 항목을 선택할 수 있습니다.'), '#facc15');
        requestRender();
        return false;
    }
    const height = Number(el.sketchWorkbenchHeight?.value);
    if (!Number.isFinite(height) || height <= 0 || height > 100000) {
        if (el.sketchEditorError) el.sketchEditorError.textContent = uiText('Z 높이는 0보다 크고 유효한 숫자여야 합니다.');
        return false;
    }
    return finishSketchAndCreateShape({
        profilesOverride: profiles,
        heightInput: el.sketchWorkbenchHeight,
        keepSketchActive: true
    });
}

function isSketchReady() {
    return Boolean(state.sketch.active && state.sketch.entities.length > 0);
}

function getSketchDimensions() {
    return getSketchEntityDimensions(getSketchEntity());
}

function formatSketchPoint(point) {
    return point ? `${Math.round(point.x)}, ${Math.round(point.y)}` : '-';
}

function formatSketchPreviewDimensionValue(value) {
    const numericValue = Number(value);
    return Number.isFinite(numericValue) ? String(Math.round(numericValue)) : '-';
}

function getSketchCircleRadiusFromDrag(start, end) {
    if (!start || !end) return 0;
    const distance = start.distanceTo(end);
    const diameter = Math.max(
        SKETCH_MIN_SIZE * 2,
        Math.round((distance * 2) / SKETCH_POINTER_STEP_MM) * SKETCH_POINTER_STEP_MM
    );
    return diameter / 2;
}

function getSketchPolygonPoints(entity, offsetX = 0, offsetY = 0) {
    if (entity?.type === 'polyline') {
        return (entity.points || []).map((point) => new THREE.Vector2(
            point.x - offsetX,
            point.y - offsetY
        ));
    }
    if (!entity?.start || !entity?.end) return [];
    const minX = Math.min(entity.start.x, entity.end.x) - offsetX;
    const maxX = Math.max(entity.start.x, entity.end.x) - offsetX;
    const minY = Math.min(entity.start.y, entity.end.y) - offsetY;
    const maxY = Math.max(entity.start.y, entity.end.y) - offsetY;
    const chamfer = entity.type === 'chamfer'
        ? THREE.MathUtils.clamp(Number(entity.chamfer) || 0, 0, Math.max(0, Math.min(maxX - minX, maxY - minY) * 0.49))
        : 0;
    return [
        new THREE.Vector2(minX + chamfer, minY),
        new THREE.Vector2(maxX - chamfer, minY),
        ...(chamfer > 0 ? [new THREE.Vector2(maxX, minY + chamfer)] : []),
        new THREE.Vector2(maxX, maxY - chamfer),
        ...(chamfer > 0 ? [new THREE.Vector2(maxX - chamfer, maxY)] : []),
        new THREE.Vector2(minX + chamfer, maxY),
        ...(chamfer > 0 ? [new THREE.Vector2(minX, maxY - chamfer)] : []),
        new THREE.Vector2(minX, minY + chamfer),
        ...(chamfer > 0 ? [new THREE.Vector2(minX + chamfer, minY)] : [])
    ];
}

function getSketchCirclePoints(entity, z = 0, segments = 64) {
    if (entity?.type !== 'circle' || !entity.center || !Number.isFinite(entity.radius)) return [];
    return Array.from({ length: segments }, (_, index) => {
        const angle = (index / segments) * Math.PI * 2;
        return new THREE.Vector3(
            entity.center.x + Math.cos(angle) * entity.radius,
            entity.center.y + Math.sin(angle) * entity.radius,
            z
        );
    });
}

function getSketchShapePathPoints(entity, offsetX = 0, offsetY = 0) {
    const points = entity?.type === 'circle'
        ? getSketchCirclePoints(entity).map((point) => new THREE.Vector2(point.x - offsetX, point.y - offsetY))
        : getSketchPolygonPoints(entity, offsetX, offsetY);
    if (points.length > 1 && points[0].distanceTo(points.at(-1)) <= 1e-6) points.pop();
    return points;
}

function appendSketchShapePath(path, entity, offsetX = 0, offsetY = 0, {
    reverse = false,
    clockwise = false
} = {}) {
    if (entity?.type === 'circle' && entity.center) {
        path.absarc(
            entity.center.x - offsetX,
            entity.center.y - offsetY,
            Math.abs(Number(entity.radius) || 0),
            0,
            Math.PI * 2,
            clockwise
        );
        return path;
    }
    const points = getSketchShapePathPoints(entity, offsetX, offsetY);
    if (points.length < 3) return null;
    const ordered = reverse ? [...points].reverse() : points;
    path.moveTo(ordered[0].x, ordered[0].y);
    ordered.slice(1).forEach((point) => path.lineTo(point.x, point.y));
    path.closePath();
    return path;
}

function createSketchProfileShape(entity, offsetX = 0, offsetY = 0) {
    const shape = new THREE.Shape();
    if (!appendSketchShapePath(shape, entity, offsetX, offsetY)) return null;
    const outerArea = polygonSignedArea(
        getSketchShapePathPoints(entity, offsetX, offsetY).map((point) => [point.x, point.y])
    );
    (entity?.holes || []).forEach((hole) => {
        const holePoints = getSketchShapePathPoints(hole, offsetX, offsetY);
        if (holePoints.length < 3) return;
        const holeArea = polygonSignedArea(holePoints.map((point) => [point.x, point.y]));
        const holePath = new THREE.Path();
        appendSketchShapePath(
            holePath,
            hole,
            offsetX,
            offsetY,
            {
                reverse: hole.type !== 'circle' && Math.sign(holeArea) === Math.sign(outerArea),
                clockwise: hole.type === 'circle' && outerArea >= 0
            }
        );
        shape.holes.push(holePath);
    });
    return shape;
}

function createSketchExtrudeGeometry(entity, depth) {
    const shape = createSketchProfileShape(entity);
    if (!shape) return null;
    const geometry = new THREE.ExtrudeGeometry(shape, {
        depth,
        steps: 1,
        curveSegments: 48,
        bevelEnabled: false
    });
    geometry.computeBoundingBox();
    geometry.computeBoundingSphere();
    return geometry;
}

function getSketchFeatureOriginOffset(model) {
    const offset = sketchVector(model?.userData?.sketchOriginOffset);
    return offset || new THREE.Vector3();
}

function getSketchFeatureLocalBoundsCenter(model) {
    if (!model) return new THREE.Vector3();
    const bounds = new THREE.Box3();
    // Sketch-only roots are made of line helpers. Once the root is converted
    // to an extrusion, those helpers are stale source visuals and must not
    // participate in the mesh-centering offset.
    const includeSketchLines = isSketchOnlyModel(model);
    model.children
        .filter((child) => (
            (child.isMesh && child.userData?.sketchFeatureMesh)
            || (includeSketchLines && child.userData?.sketchFeatureLine)
        ))
        .forEach((mesh) => {
            if (!mesh.geometry?.boundingBox) mesh.geometry?.computeBoundingBox?.();
            if (!mesh.geometry?.boundingBox) return;
            if (mesh.matrixAutoUpdate !== false) mesh.updateMatrix();
            bounds.union(mesh.geometry.boundingBox.clone().applyMatrix4(mesh.matrix));
        });
    return bounds.isEmpty() ? new THREE.Vector3() : bounds.getCenter(new THREE.Vector3());
}

function transformSketchFeatureLocalVectorToWorld(model, vector) {
    return vector.clone()
        .multiply(model?.scale || new THREE.Vector3(1, 1, 1))
        .applyQuaternion(model?.quaternion || new THREE.Quaternion());
}

function getSketchFeatureSketchOrigin(model) {
    if (!model) return new THREE.Vector3();
    return model.position.clone().sub(
        transformSketchFeatureLocalVectorToWorld(model, getSketchFeatureOriginOffset(model))
    );
}

function centerSketchFeatureGeometry(model, { preserveSketchOrigin = false } = {}) {
    if (!isSketchFeatureModel(model) || model.userData.cadExtrudeFeature) return new THREE.Vector3();
    if (model.userData.sketchGeometryCentered) return getSketchFeatureOriginOffset(model);

    const previousOffset = getSketchFeatureOriginOffset(model);
    const nextOffset = getSketchFeatureLocalBoundsCenter(model);
    const delta = nextOffset.clone().sub(previousOffset);
    if (preserveSketchOrigin && delta.lengthSq() > 1e-12) {
        model.position.add(transformSketchFeatureLocalVectorToWorld(model, delta));
    }
    model.children
        .filter((child) => child.isMesh && child.userData?.sketchFeatureMesh)
        .forEach((mesh) => {
            mesh.geometry?.translate?.(-nextOffset.x, -nextOffset.y, -nextOffset.z);
            mesh.geometry?.computeBoundingBox?.();
            mesh.geometry?.computeBoundingSphere?.();
        });
    model.userData.sketchOriginOffset = nextOffset.toArray();
    model.userData.sketchGeometryCentered = true;
    model.updateMatrixWorld(true);
    return nextOffset;
}

function getSketchFeatureProfiles(model) {
    return (Array.isArray(model?.userData?.sketchProfiles) ? model.userData.sketchProfiles : [])
        .map(normalizeSketchEntityRecord)
        .filter(Boolean)
        .filter((profile) => profile.type !== 'line');
}

function getSketchFeatureMaterial(model, fallbackColor = '#bfc7d5') {
    const mesh = model?.children?.find((child) => child.userData?.sketchFeatureMesh && child.isMesh)
        || model?.children?.find((child) => child.isMesh);
    const source = Array.isArray(mesh?.material) ? mesh.material[0] : mesh?.material;
    return source || new THREE.MeshStandardMaterial({
        color: fallbackColor,
        roughness: 0.58,
        metalness: 0.08
    });
}

function getSketchFeatureDisplayColor(model, fallbackColor = '#bfc7d5') {
    if (model?.userData?.sketchMaterialColor) return model.userData.sketchMaterialColor;
    const visual = model?.children?.find((child) => (
        child.userData?.sketchFeatureLine || (child.userData?.sketchFeatureMesh && child.isMesh)
    ));
    const material = Array.isArray(visual?.material) ? visual.material[0] : visual?.material;
    return material?.color?.getHexString ? `#${material.color.getHexString()}` : fallbackColor;
}

function getSketchFeatureEntities(model) {
    const storedEntities = model?.userData?.sketchDocument?.entities;
    const source = Array.isArray(storedEntities) && storedEntities.length
        ? storedEntities
        : model?.userData?.sketchProfiles;
    return (Array.isArray(source) ? source : [])
        .map(normalizeSketchEntityRecord)
        .filter(Boolean);
}

function getSketchFeatureEntityPoints(entity, z = 0.04) {
    if (!entity) return [];
    if (entity.type === 'circle') return getSketchCirclePoints(entity, z);
    if (entity.type === 'line') {
        return entity.start && entity.end
            ? [entity.start.clone().setZ(z), entity.end.clone().setZ(z)]
            : [];
    }
    if (entity.type === 'polyline') {
        return (entity.points || []).map((point) => point.clone().setZ(z));
    }
    return getSketchPolygonPoints(entity).map((point) => new THREE.Vector3(point.x, point.y, z));
}

function rebuildSketchOnlyVisual(model, { materialColor = '#c4b5fd' } = {}) {
    if (!isSketchOnlyModel(model)) return false;
    model.userData.sketchMaterialColor = materialColor;
    model.userData.sketchGeometryCentered = true;
    model.userData.sketchOriginOffset = [0, 0, 0];
    model.children
        .filter((child) => child.userData?.sketchFeatureMesh && child.isMesh)
        .forEach((child) => {
            disposeObjectResources(child);
            child.removeFromParent();
        });
    model.children
        .filter((child) => child.userData?.sketchFeatureLine)
        .forEach((child) => {
            disposeObjectResources(child);
            child.removeFromParent();
        });
    getSketchFeatureEntities(model).forEach((entity) => {
        const entities = [entity, ...(entity.holes || [])];
        entities.forEach((entry, entityIndex) => {
            const points = getSketchFeatureEntityPoints(entry);
            if (points.length < 2) return;
            const closed = entry.type !== 'line' && entry.closed !== false;
            const line = createSketchLine(materialColor, 0.95, closed, entry);
            line.name = `${model.userData.modelName || model.name} ${entity.id}${entityIndex ? ' hole' : ''}`;
            line.userData.sketchFeatureLine = true;
            line.userData.sketchEntityId = entity.id;
            line.userData.sketchFeatureEntity = serializeSketchEntity(entry);
            setSketchLinePoints(line, points);
            model.add(line);
        });
    });
    model.updateMatrixWorld(true);
    return true;
}

function rebuildSketchFeatureVisual(model, { materialColor = '#bfc7d5' } = {}) {
    if (!isSketchFeatureModel(model)) return false;
    if (isSketchOnlyModel(model)) return rebuildSketchOnlyVisual(model, {
        materialColor: materialColor || '#c4b5fd'
    });
    const profiles = getSketchFeatureProfiles(model);
    const depth = Number(model.userData.sketchExtrudeDepth);
    if (!profiles.length || !Number.isFinite(depth) || depth < SKETCH_MIN_SIZE) return false;
    model.userData.sketchGeometryCentered = false;
    const oldMeshes = model.children.filter((child) => child.userData?.sketchFeatureMesh && child.isMesh);
    const sourceMaterial = getSketchFeatureMaterial(model, materialColor);
    oldMeshes.forEach((mesh, index) => {
        mesh.geometry?.dispose?.();
        if (index > 0 && mesh.material && mesh.material !== sourceMaterial) {
            const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
            materials.forEach((entry) => entry?.dispose?.());
        }
        mesh.removeFromParent();
    });
    // A sketch-only model owns line helpers for its editable source drawing.
    // Remove them when turning it into an extrusion; otherwise the helpers
    // stay at their pre-centering coordinates while the generated mesh moves
    // with its preserved sketch origin, appearing as a diagonal offset.
    model.children
        .filter((child) => child.userData?.sketchFeatureLine)
        .forEach((child) => {
            disposeObjectResources(child);
            child.removeFromParent();
        });
    profiles.forEach((profile, index) => {
        const geometry = createSketchExtrudeGeometry(profile, depth);
        if (!geometry) return;
        const mesh = new THREE.Mesh(geometry, index === 0 ? sourceMaterial : sourceMaterial.clone());
        mesh.name = `${model.userData.modelName || model.name} profile ${index + 1}`;
        mesh.userData.sketchFeatureMesh = true;
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        model.add(mesh);
    });
    model.updateMatrixWorld(true);
    return true;
}

function createSketchFeatureRoot(profiles, depth, options = {}) {
    const sketchOnly = options.sketchOnly === true;
    const normalizedEntities = (Array.isArray(profiles) ? profiles : [profiles])
        .map(normalizeSketchEntityRecord)
        .filter(Boolean);
    const normalizedProfiles = normalizedEntities.filter((entity) => entity.type !== 'line');
    if (!(sketchOnly ? normalizedEntities.length : normalizedProfiles.length)) {
        throw new Error(sketchOnly ? 'A sketch entity is required.' : 'A closed sketch profile is required.');
    }
    const sketchFeatureNameIndex = Number.isSafeInteger(Number(options.sketchFeatureNameIndex))
        && Number(options.sketchFeatureNameIndex) > 0
        ? Number(options.sketchFeatureNameIndex)
        : getNextSketchFeatureNameIndex();
    const generatedNameKey = options.generatedNameKey
        || (options.name ? null : sketchOnly ? '스케치' : '스케치 돌출');
    const modelName = options.name || `${uiText(generatedNameKey || (sketchOnly ? '스케치' : '스케치 돌출'))} ${sketchFeatureNameIndex}`;
    const root = new THREE.Group();
    root.name = `Sketch: ${modelName}`;
    root.userData = {
        sketchFeature: true,
        sketchFeatureType: sketchOnly ? 'sketch' : 'extrude',
        sketchFeatureSchemaVersion: 1,
        sketchFeatureNameIndex,
        sketchProfiles: normalizedEntities.map(serializeSketchEntity),
        sketchDocument: normalizeSketchDocument(options.sketchDocument || {
            name: modelName,
            entities: normalizedEntities.map(serializeSketchEntity)
        }),
        sketchExtrudeDepth: sketchOnly ? null : depth,
        sketchMaterialColor: options.materialColor || (sketchOnly ? '#c4b5fd' : '#bfc7d5'),
        modelName,
        generatedNameKey,
        placement: 'scene',
        collisionEnabled: true
    };
    ensureWorkspaceModelId(root, options.workspaceModelId);
    ensureModelTreeId(root);
    rebuildSketchFeatureVisual(root, {
        materialColor: options.materialColor || (sketchOnly ? '#c4b5fd' : '#bfc7d5')
    });
    if (!sketchOnly) centerSketchFeatureGeometry(root);
    root.visible = options.visible !== false;
    if (options.transform) applyClipboardTransform(root, options.transform);
    root.updateMatrixWorld(true);
    if (options.sketchCutFeature) applySketchCutFeature(
        root,
        options.sketchCutFeature.profiles
            || options.sketchCutFeature.profile
            || options.sketchCutFeature,
        options.sketchCutFeature.depth,
        options.sketchCutFeature.direction
    );
    return root;
}

function applySketchFeatureDimensions(model, dimensions, {
    recordHistoryChange = true,
    status = true
} = {}) {
    if (!isSketchDimensionShapeModel(model)) return false;
    const previous = getSketchFeatureDimensions(model);
    if (!previous) return false;
    const profiles = getSketchFeatureProfiles(model);
    const circlesOnly = profiles.length > 0 && profiles.every((profile) => profile.type === 'circle');
    const normalized = {
        x: Number(dimensions?.x),
        y: Number(dimensions?.y),
        z: Number(dimensions?.z)
    };
    if (circlesOnly) normalized.y = normalized.x;
    if (!['x', 'y', 'z'].every((axis) => Number.isFinite(normalized[axis])
        && normalized[axis] >= SKETCH_MIN_SIZE
        && normalized[axis] <= SKETCH_MAX_SIZE)) {
        if (status) setStatus(uiText('도형 치수는 0보다 크고 유효한 숫자여야 합니다.'), '#ef4444');
        return false;
    }
    if (['x', 'y', 'z'].every((axis) => Math.abs(previous[axis] - normalized[axis]) < 1e-9)) {
        renderPrimitiveShapePanel();
        updatePrimitiveDimensionOverlay();
        return false;
    }
    const bounds = getSketchFeatureDimensionBounds(model);
    const center = bounds
        ? new THREE.Vector3((bounds.minX + bounds.maxX) / 2, (bounds.minY + bounds.maxY) / 2, 0)
        : new THREE.Vector3();
    const scaleX = normalized.x / previous.x;
    const scaleY = normalized.y / previous.y;
    const scaleZ = normalized.z / previous.z;
    const historyBefore = recordHistoryChange && !state.historySuspended
        ? captureSceneSnapshot()
        : null;
    const originalProfiles = profiles.map(serializeSketchEntity).filter(Boolean);
    const originalDocument = getStoredSketchFeatureDocument(model);
    const originalCut = getStoredSketchCutFeature(model);
    const documentEntities = (originalDocument.entities?.length
        ? originalDocument.entities
        : originalProfiles)
        .map(normalizeSketchEntityRecord)
        .filter(Boolean)
        .map((entity) => scaleSketchEntity(entity, center, scaleX, scaleY))
        .filter(Boolean);
    const scaledProfiles = profiles
        .map((profile) => scaleSketchEntity(profile, center, scaleX, scaleY))
        .filter(Boolean);
    const scaledDimensions = (originalDocument.dimensions || [])
        .map((dimension) => scaleSketchDimensionRecord(dimension, center, scaleX, scaleY))
        .filter(Boolean)
        .map(serializeSketchDimension);
    const scaledCut = originalCut
        ? {
            profiles: originalCut.profiles
                .map((profile) => scaleSketchEntity(profile, center, scaleX, scaleY))
                .filter(Boolean),
            depth: THREE.MathUtils.clamp(
                originalCut.depth * scaleZ,
                SKETCH_MIN_SIZE,
                normalized.z
            ),
            direction: originalCut.direction
        }
        : null;

    model.userData.sketchProfiles = scaledProfiles.map(serializeSketchEntity).filter(Boolean);
    model.userData.sketchDocument = normalizeSketchDocument({
        ...originalDocument,
        entities: documentEntities.map(serializeSketchEntity).filter(Boolean),
        dimensions: scaledDimensions
    });
    model.userData.sketchExtrudeDepth = normalized.z;
    delete model.userData.sketchCutFeature;
    rebuildSketchFeatureVisual(model, { materialColor: getModelColorHex(model) });
    centerSketchFeatureGeometry(model, { preserveSketchOrigin: true });
    if (scaledCut && !applySketchCutFeature(
        model,
        scaledCut.profiles,
        scaledCut.depth,
        scaledCut.direction
    )) {
        // The scaled profile has the same topology and relative cut position,
        // so this is only a defensive rollback for malformed legacy data.
        model.userData.sketchProfiles = originalProfiles;
        model.userData.sketchDocument = originalDocument;
        model.userData.sketchExtrudeDepth = previous.z;
        delete model.userData.sketchCutFeature;
        rebuildSketchFeatureVisual(model, { materialColor: getModelColorHex(model) });
        centerSketchFeatureGeometry(model, { preserveSketchOrigin: true });
        if (originalCut) applySketchCutFeature(
            model,
            originalCut.profiles,
            originalCut.depth,
            originalCut.direction
        );
        return false;
    }
    model.updateMatrixWorld(true);
    updateModelRenderComplexity(model);
    if (state.collision.enabled) state.collision.system?.prepare([model]);
    markSceneCollisionDirty(model);
    refreshCollisionDebugOverlays();
    renderModelTree();
    renderPrimitiveShapePanel();
    updatePrimitiveDimensionOverlay();
    requestRender();
    scheduleMotionProjectSave();
    if (historyBefore) recordHistory('도형 치수 변경', historyBefore, captureSceneSnapshot());
    if (status) setStatus(uiText('도형 치수가 적용되었습니다.'), '#22c55e');
    return true;
}

function selectSketchTool(tool, { remember = true } = {}) {
    const sketch = state.sketch;
    const nextTool = isSketchCommandTool(tool) ? tool : 'select';
    if (remember && nextTool !== 'select') sketch.lastSketchTool = nextTool;
    cancelSketchDimensionLineDrag();
    if (cancelSketchDimensionPlacement({ remove: true })) syncSketchDocumentEntities();
    clearSketchSelectionBox({ releasePointer: true });
    sketch.activeTool = nextTool;
    sketch.rectangleCenterMode = false;
    if (sketch.phase === 'drawing') sketch.phase = 'draw';
    sketch.startPoint = null;
    sketch.endPoint = null;
    sketch.pointerId = null;
    sketch.draggingEntityId = null;
    sketch.draggingEntityBefore = null;
    sketch.dimensionDraft = createEmptySketchDimensionDraft();
    sketch.snapCandidate = null;
    sketch.dimensionHoverTarget = null;
    sketch.hoverEntityId = null;
    sketch.selectedDimensionId = null;
    renderSketchEditorUi();
    updateSketchPreview();
    setStatus(uiFormat('{tool} 도구를 선택했습니다.', { tool: sketchToolDisplayName(nextTool) }), '#a78bfa');
    requestRender();
}

function getSketchWorkbenchEntityLabel(entity, index) {
    const type = entity?.type === 'polyline'
        ? 'Polyline'
        : entity?.type === 'circle'
            ? 'Circle'
            : entity?.type === 'line'
                ? 'Line'
                : entity?.type === 'chamfer'
                    ? 'Chamfer'
                    : 'Rectangle';
    return `${type} ${index + 1}`;
}

function getSketchWorkbenchEntityIcon(type) {
    return type === 'circle'
        ? 'fa-circle'
        : type === 'line'
            ? 'fa-minus'
            : type === 'polyline'
                ? 'fa-draw-polygon'
                : 'fa-square';
}

function renderSketchWorkbenchUi() {
    const sketch = state.sketch;
    const active = Boolean(sketch.active);
    const ready = isSketchReady();
    const selectedProfiles = getSelectedSketchProfiles();
    document.body.classList.toggle('sketch-workbench-active', active);
    if (el.sketchWorkbench) el.sketchWorkbench.hidden = !active;
    el.sketchWorkbenchToolButtons?.forEach((button) => {
        const selected = button.dataset.sketchWorkbenchTool === sketch.activeTool;
        button.classList.toggle('active', selected);
        button.setAttribute('aria-pressed', String(selected));
    });
    if (el.sketchWorkbenchFinish) {
        el.sketchWorkbenchFinish.disabled = !active || !ready || sketch.phase === 'drawing'
            || sketch.extrudeSelectionMode || sketch.extrudePanelOpen;
        const label = el.sketchWorkbenchFinish.querySelector('span');
        if (label) label.textContent = uiText('스케치 완료');
    }
    [
        [el.sketchWorkbenchExtrude, 'add', '돌출'],
        [el.sketchWorkbenchExtrudeCut, 'cut', '돌출 컷']
    ].forEach(([button, operation, labelText]) => {
        if (!button) return;
        const selectionMode = sketch.extrudeSelectionMode && sketch.operation === operation;
        const panelOpen = sketch.extrudePanelOpen && sketch.operation === operation;
        button.disabled = !active;
        button.classList.toggle('active', selectionMode || panelOpen);
        const label = button.querySelector('span');
        if (label) label.textContent = uiText(sketch.extrudeSelectionMode && selectionMode ? '프로파일 선택' : labelText);
        button.setAttribute('aria-pressed', String(selectionMode || panelOpen));
        const commandTitle = selectionMode
            ? '돌출할 스케치 항목을 선택하세요.'
            : operation === 'cut'
                ? '선택한 스케치 프로파일 돌출 컷'
                : '선택한 스케치 프로파일 돌출';
        const translatedTitle = uiText(commandTitle);
        button.title = translatedTitle;
        button.setAttribute('aria-label', translatedTitle);
    });
    if (el.sketchWorkbenchExtrudeControls) {
        el.sketchWorkbenchExtrudeControls.hidden = !active || !sketch.extrudePanelOpen;
    }
    if (el.sketchWorkbenchExtrudeSelectionCount) {
        el.sketchWorkbenchExtrudeSelectionCount.textContent = `${selectedProfiles.length} profiles`;
    }
    const extrusionTitle = el.sketchWorkbenchExtrudeControls?.querySelector('.sketch-workbench-extrude-title');
    if (extrusionTitle) extrusionTitle.textContent = uiText(sketch.operation === 'cut' ? '돌출 컷' : '돌출');
    if (el.sketchWorkbenchElementCount) el.sketchWorkbenchElementCount.textContent = String(sketch.entities.length);
    if (el.sketchWorkbenchDimensionCount) el.sketchWorkbenchDimensionCount.textContent = String(sketch.dimensions.length);
    if (el.sketchWorkbenchEntityList) {
        el.sketchWorkbenchEntityList.replaceChildren();
        if (isDenseSketchDocument(sketch)) {
            const summary = document.createElement('div');
            summary.className = 'sketch-workbench-entity dense-sketch-summary';
            summary.textContent = uiFormat('대형 DXF 도면 · {count}개 요소는 캔버스에서 선택하세요.', {
                count: sketch.entities.length
            });
            el.sketchWorkbenchEntityList.append(summary);
        } else {
            sketch.entities.forEach((entity, index) => {
                const button = document.createElement('button');
                button.type = 'button';
                button.className = 'sketch-workbench-entity';
                button.dataset.sketchEntityId = entity.id;
                button.setAttribute('role', 'option');
                const selected = isSketchEntitySelected(entity.id);
                button.setAttribute('aria-selected', String(selected));
                if (selected) button.classList.add('active');
                const icon = document.createElement('i');
                icon.className = `fa-regular ${getSketchWorkbenchEntityIcon(entity.type)}`;
                icon.setAttribute('aria-hidden', 'true');
                const label = document.createElement('span');
                label.textContent = getSketchWorkbenchEntityLabel(entity, index);
                button.append(icon, label);
                el.sketchWorkbenchEntityList.append(button);
            });
        }
    }
    const selectedEntities = sketch.entities.filter((entity) => isSketchEntitySelected(entity.id));
    const selected = getSketchEntity();
    if (el.sketchWorkbenchSelectedName) {
        el.sketchWorkbenchSelectedName.textContent = selectedEntities.length > 1
            ? `${selectedEntities.length}개 선택`
            : selected
            ? getSketchWorkbenchEntityLabel(selected, sketch.entities.indexOf(selected))
            : 'None';
    }
    const origin = sketch.origin || new THREE.Vector3();
    const originText = `X ${origin.x.toFixed(3)} · Y ${origin.y.toFixed(3)} · Z ${origin.z.toFixed(3)} mm`;
    if (el.sketchWorkbenchOrigin) el.sketchWorkbenchOrigin.textContent = originText;
    if (el.sketchWorkbenchFooterOrigin) el.sketchWorkbenchFooterOrigin.textContent = `${origin.x.toFixed(3)}, ${origin.y.toFixed(3)}`;
    if (el.sketchWorkbenchFooterReadout) el.sketchWorkbenchFooterReadout.textContent = `${sketch.entities.length} elements · ${sketch.dimensions.length} dimensions`;
    if (el.sketchWorkbenchOriginReset) el.sketchWorkbenchOriginReset.disabled = !active || origin.lengthSq() < 1e-8;
    if (el.sketchWorkbenchOperation) el.sketchWorkbenchOperation.value = sketch.operation;
    if (el.sketchWorkbenchHeight && el.sketchWorkbenchHeight !== document.activeElement && el.sketchHeight) {
        el.sketchWorkbenchHeight.value = el.sketchHeight.value;
    }
    if (el.sketchWorkbenchSnap) {
        const snapEnabled = Boolean(active && sketch.snapEnabled !== false);
        el.sketchWorkbenchSnap.classList.toggle('active', snapEnabled);
        el.sketchWorkbenchSnap.setAttribute('aria-pressed', String(snapEnabled));
        const snapLabel = uiText(snapEnabled ? '스냅 끄기' : '스냅 켜기');
        el.sketchWorkbenchSnap.title = snapLabel;
        el.sketchWorkbenchSnap.setAttribute('aria-label', snapLabel);
    }
    if (el.sketchWorkbenchImportCad) {
        const importLabel = uiText('DXF를 스케치로 삽입');
        el.sketchWorkbenchImportCad.disabled = !active;
        el.sketchWorkbenchImportCad.title = importLabel;
        el.sketchWorkbenchImportCad.setAttribute('aria-label', importLabel);
        const label = el.sketchWorkbenchImportCad.querySelector('span');
        if (label) label.textContent = uiText('DXF 삽입');
    }
    if (el.sketchWorkbenchClear) el.sketchWorkbenchClear.disabled = !active;
    const selectedDimension = sketch.dimensions.find((dimension) => dimension.id === sketch.selectedDimensionId) || null;
    if (el.sketchWorkbenchDimensionPanel) el.sketchWorkbenchDimensionPanel.hidden = !active || (!selectedDimension && sketch.activeTool !== 'dimension');
    if (el.sketchWorkbenchDimensionName) {
        el.sketchWorkbenchDimensionName.textContent = selectedDimension
            ? `Dimension ${sketch.dimensions.indexOf(selectedDimension) + 1}`
            : sketch.activeTool === 'dimension' ? uiText('새 치수') : 'None';
    }
    const isPositionDimension = selectedDimension?.type === 'position';
    const positionAxis = isPositionDimension && selectedDimension.axis === 'y' ? 'y' : 'x';
    if (el.sketchWorkbenchDimensionLinear) el.sketchWorkbenchDimensionLinear.hidden = isPositionDimension;
    if (el.sketchWorkbenchDimensionPosition) el.sketchWorkbenchDimensionPosition.hidden = !isPositionDimension;
    if (el.sketchWorkbenchDimensionAxis) {
        el.sketchWorkbenchDimensionAxis.textContent = isPositionDimension
            ? uiText(positionAxis === 'x' ? 'X축 치수' : 'Y축 치수')
            : 'Axis';
    }
    const xDimensionField = el.sketchWorkbenchDimensionXValue?.closest('label');
    const yDimensionField = el.sketchWorkbenchDimensionYValue?.closest('label');
    if (xDimensionField) {
        const hidden = !isPositionDimension || positionAxis !== 'x';
        xDimensionField.hidden = hidden;
        xDimensionField.style.display = hidden ? 'none' : '';
    }
    if (yDimensionField) {
        const hidden = !isPositionDimension || positionAxis !== 'y';
        yDimensionField.hidden = hidden;
        yDimensionField.style.display = hidden ? 'none' : '';
    }
    if (el.sketchWorkbenchDimensionValue) {
        if (selectedDimension && !isPositionDimension && el.sketchWorkbenchDimensionValue !== document.activeElement) {
            el.sketchWorkbenchDimensionValue.value = formatJogValue(selectedDimension.value);
        }
        el.sketchWorkbenchDimensionValue.disabled = !selectedDimension || isPositionDimension;
    }
    if (el.sketchWorkbenchDimensionXValue) {
        if (selectedDimension?.type === 'position' && el.sketchWorkbenchDimensionXValue !== document.activeElement) {
            el.sketchWorkbenchDimensionXValue.value = formatJogValue(Math.abs(selectedDimension.xValue));
        }
        el.sketchWorkbenchDimensionXValue.disabled = !isPositionDimension || positionAxis !== 'x';
    }
    if (el.sketchWorkbenchDimensionYValue) {
        if (selectedDimension?.type === 'position' && el.sketchWorkbenchDimensionYValue !== document.activeElement) {
            el.sketchWorkbenchDimensionYValue.value = formatJogValue(Math.abs(selectedDimension.yValue));
        }
        el.sketchWorkbenchDimensionYValue.disabled = !isPositionDimension || positionAxis !== 'y';
    }
    if (el.sketchWorkbenchDimensionApply) el.sketchWorkbenchDimensionApply.disabled = !selectedDimension;
    if (el.sketchWorkbenchDimensionHelp) {
        el.sketchWorkbenchDimensionHelp.textContent = sketch.dimensionPlacement
            ? uiText('치수 위치를 따라가고 있습니다. 원하는 위치에서 클릭해 고정하세요.')
            : sketch.activeTool === 'dimension'
            ? sketch.dimensionDraft?.mode === 'position'
                ? uiText('두 번째 스냅 지점을 클릭해 한 축 위치 치수를 완성하세요.')
                : uiText('선 또는 모서리를 클릭하면 길이 치수를 만들고, 유효한 스냅 지점을 차례로 클릭하면 X 또는 Y 한 축 위치 치수를 만듭니다.')
            : selectedDimension
                ? uiText('치수 값을 입력하고 적용하세요.')
                : uiText('치수 기입 도구를 선택하세요.');
    }
    if (el.sketchWorkbenchFooterSnap) el.sketchWorkbenchFooterSnap.textContent = sketch.snapEnabled === false ? 'OFF' : 'ON';
}

function focusSelectedSketchDimensionEditor() {
    const sketch = state.sketch;
    const dimension = sketch.dimensions.find((entry) => entry.id === sketch.selectedDimensionId);
    const input = dimension?.type === 'position'
        ? dimension.axis === 'y' ? el.sketchWorkbenchDimensionYValue : el.sketchWorkbenchDimensionXValue
        : el.sketchWorkbenchDimensionValue;
    if (!input || input.disabled) return false;
    input.focus({ preventScroll: true });
    input.select?.();
    return true;
}

function renderSketchEditorUi() {
    const sketch = state.sketch;
    const active = Boolean(sketch.active);
    const entity = getSketchEntity();
    const dimensions = getSketchEntityDimensions(entity);
    const ready = isSketchReady();
    const dimensionToolActive = active && sketch.activeTool === 'dimension';
    sketch.dimensionLabels.forEach((label) => {
        // Inline size labels must not cover the geometry hit area while the
        // dimension tool is waiting for a line/edge click. Dimension
        // annotations remain clickable so an existing dimension can still be
        // selected from the canvas.
        label.style.pointerEvents = sketch.phase === 'drawing' || dimensionToolActive ? 'none' : 'auto';
    });
    sketch.dimensionAnnotationLabels.forEach((label) => {
        const pending = sketch.dimensionPlacement?.dimensionId === label.dataset.dimensionId;
        label.style.pointerEvents = sketch.phase === 'drawing' || pending ? 'none' : 'auto';
    });
    renderSketchWorkbenchUi();
    if (el.sketchEditor) el.sketchEditor.hidden = !active;
    if (el.sketchModeButton) {
        el.sketchModeButton.classList.toggle('active', active);
        el.sketchModeButton.setAttribute('aria-pressed', String(active));
        el.sketchModeButton.title = uiText(active ? '스케치 모드 종료' : '스케치 모드 시작');
        el.sketchModeButton.setAttribute('aria-label', el.sketchModeButton.title);
        el.sketchModeButton.innerHTML = `<i class="fa-solid fa-pen-ruler"></i> <span>${uiText(active ? '스케치 종료' : '스케치')}</span>`;
    }
    if (el.sketchViewPanelButton) {
        el.sketchViewPanelButton.title = uiText('뷰 변경');
        el.sketchViewPanelButton.setAttribute('aria-label', uiText('뷰 변경'));
        el.sketchViewPanelButton.innerHTML = `<i class="fa-solid fa-eye"></i> <span>${uiText('뷰 변경')}</span>`;
    }
    if (el.sketchSnapButton) {
        const snapActive = Boolean(active && sketch.snapMode);
        el.sketchSnapButton.classList.toggle('active', snapActive);
        el.sketchSnapButton.setAttribute('aria-pressed', String(snapActive));
        const snapLabel = uiText(snapActive ? '도면 위치 스냅 종료' : '도면 위치 스냅');
        el.sketchSnapButton.title = snapLabel;
        el.sketchSnapButton.setAttribute('aria-label', snapLabel);
        el.sketchSnapButton.innerHTML = `<i class="fa-solid fa-magnet"></i> <span>${snapLabel}</span>`;
    }
    if (el.sketchSnapResetButton) {
        const hasOrigin = sketch.origin.lengthSq() > 1e-8;
        el.sketchSnapResetButton.disabled = !active || !hasOrigin;
        el.sketchSnapResetButton.title = uiText('스케치 원점 초기화');
        el.sketchSnapResetButton.setAttribute('aria-label', uiText('스케치 원점 초기화'));
        const label = el.sketchSnapResetButton.querySelector('span');
        if (label) label.textContent = uiText('초기화');
    }
    if (el.sketchSnapReadout) {
        const origin = sketch.origin || new THREE.Vector3();
        el.sketchSnapReadout.textContent = `X ${origin.x.toFixed(3)} · Y ${origin.y.toFixed(3)} · Z ${origin.z.toFixed(3)} mm`;
    }
    el.sketchToolButtons?.forEach((button) => {
        const selected = button.dataset.sketchTool === sketch.activeTool;
        button.classList.toggle('active', selected);
        button.setAttribute('aria-pressed', String(selected));
    });
    if (el.shapeCreateButton) el.shapeCreateButton.disabled = active;
    const type = entity?.type || sketch.activeTool;
    const hasXY = Boolean(entity && ['rectangle', 'chamfer'].includes(type));
    const isCircle = type === 'circle';
    const isLine = type === 'line';
    if (el.sketchWidthLabel) el.sketchWidthLabel.textContent = isCircle ? uiText('직경') : isLine ? uiText('길이') : 'X';
    if (el.sketchDepthLabel) el.sketchDepthLabel.textContent = hasXY ? 'Y' : '';
    if (el.sketchWidth) {
        el.sketchWidth.disabled = !entity || sketch.phase === 'drawing';
        if (dimensions?.x !== null && dimensions?.x !== undefined && el.sketchWidth !== document.activeElement) {
            el.sketchWidth.value = formatJogValue(dimensions.x);
        }
    }
    if (el.sketchDepth) {
        el.sketchDepth.parentElement.hidden = !hasXY;
        el.sketchDepth.disabled = !hasXY || sketch.phase === 'drawing';
        if (hasXY && dimensions?.y !== null && el.sketchDepth !== document.activeElement) {
            el.sketchDepth.value = formatJogValue(dimensions.y);
        }
    }
    if (el.sketchChamferField) el.sketchChamferField.hidden = type !== 'chamfer' && sketch.activeTool !== 'chamfer';
    if (el.sketchChamferDistance) {
        el.sketchChamferDistance.disabled = (type !== 'chamfer' && sketch.activeTool !== 'chamfer') || Boolean(entity && type !== 'chamfer');
        if (type === 'chamfer' && entity && el.sketchChamferDistance !== document.activeElement) {
            el.sketchChamferDistance.value = formatJogValue(entity.chamfer || 0);
        }
    }
    if (el.sketchOperation) el.sketchOperation.value = sketch.operation;
    if (el.sketchCutDirectionField) el.sketchCutDirectionField.hidden = sketch.operation !== 'cut';
    if (el.sketchCutDirection) el.sketchCutDirection.value = normalizeCutDirection(sketch.cutDirection);
    if (el.sketchHeightLabel) el.sketchHeightLabel.textContent = uiText(sketch.operation === 'cut' ? 'Z 컷 깊이' : 'Z 높이');
    if (el.sketchRedrawButton) el.sketchRedrawButton.disabled = !active;
    if (el.sketchFinishButton) {
        el.sketchFinishButton.disabled = !ready || sketch.phase === 'drawing';
        const label = el.sketchFinishButton.querySelector('span');
        if (label) label.textContent = uiText('스케치 완료');
    }
    if (el.sketchCoordinateReadout) {
        const pending = sketch.startPoint
            ? ` · P1 ${formatSketchPoint(sketch.startPoint)} · P2 ${formatSketchPoint(sketch.endPoint)}`
            : '';
        el.sketchCoordinateReadout.textContent = `${uiText('스케치 요소')} ${sketch.entities.length}${pending}`;
    }
    if (el.sketchModeStatus) {
        const status = sketch.snapMode
            ? '스냅할 3D 모델의 면 또는 표시된 스냅 점을 클릭하세요.'
            : sketch.phase === 'drawing'
            ? '마우스를 움직여 크기를 정한 뒤 다시 클릭하면 도형이 생성됩니다.'
            : ready
                ? '치수 라벨 또는 입력값을 수정하고, 닫힌 프로파일을 돌출하거나 컷하세요.'
                : '도구를 선택하고 첫 번째 위치를 클릭한 뒤, 크기를 정해 다시 클릭하세요. 가운데/오른쪽 드래그와 휠로 뷰를 변경할 수 있습니다.';
        el.sketchModeStatus.textContent = uiText(status);
    }
}

function createSketchLine(color, opacity = 0.95, loop = false, lineStyle = null) {
    const dashSpec = getCadLineDashSpec(lineStyle?.linetype, lineStyle?.linePattern);
    const LineMaterial = dashSpec ? THREE.LineDashedMaterial : THREE.LineBasicMaterial;
    const material = new LineMaterial({
        color,
        depthTest: false,
        depthWrite: false,
        transparent: true,
        opacity,
        ...(dashSpec || {})
    });
    const line = loop
        ? new THREE.LineLoop(new THREE.BufferGeometry(), material)
        : new THREE.Line(new THREE.BufferGeometry(), material);
    line.frustumCulled = false;
    line.renderOrder = 36;
    return line;
}

function ensureSketchPreview() {
    const sketch = state.sketch;
    if (sketch.previewGroup) return sketch.previewGroup;
    const group = new THREE.Group();
    group.name = '2D sketch preview';
    group.userData.sketchOverlay = true;
    group.renderOrder = 36;
    const entitiesGroup = new THREE.Group();
    const dimensionsGroup = new THREE.Group();
    const snapGroup = new THREE.Group();
    group.add(entitiesGroup, dimensionsGroup, snapGroup);
    group.userData.entitiesGroup = entitiesGroup;
    group.userData.dimensionsGroup = dimensionsGroup;
    group.userData.snapGroup = snapGroup;
    sketch.previewGroup = group;
    state.scene.add(group);
    ['x', 'y', 'diameter', 'length', 'chamfer'].forEach((axis) => {
        const label = document.createElement('div');
        label.className = 'sketch-dimension-label';
        label.dataset.axis = axis;
        label.addEventListener('click', (event) => {
            event.preventDefault();
            event.stopPropagation();
            beginSketchDimensionEdit(axis);
        });
        label.addEventListener('pointerdown', (event) => event.stopPropagation());
        label.addEventListener('pointerup', (event) => event.stopPropagation());
        el.sketchDimensionOverlay?.appendChild(label);
        sketch.dimensionLabels.set(axis, label);
    });
    const snapReadout = document.createElement('div');
    snapReadout.className = 'sketch-snap-readout';
    snapReadout.hidden = true;
    snapReadout.setAttribute('role', 'status');
    snapReadout.setAttribute('aria-live', 'polite');
    el.sketchDimensionOverlay?.appendChild(snapReadout);
    sketch.snapReadout = snapReadout;
    return group;
}

function getSketchDimensionAnnotationLabel(dimensionId) {
    const sketch = state.sketch;
    let label = sketch.dimensionAnnotationLabels.get(dimensionId);
    if (label) return label;
    label = document.createElement('div');
    label.className = 'sketch-dimension-label sketch-dimension-annotation';
    label.dataset.dimensionId = dimensionId;
    label.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        const dimension = sketch.dimensions.find((entry) => entry.id === dimensionId);
        sketch.selectedDimensionId = dimensionId;
        sketch.activeTool = 'dimension';
        if (dimension && beginSketchDimensionAnnotationEdit(dimensionId)) return;
        renderSketchEditorUi();
    });
    label.addEventListener('pointerdown', (event) => {
        event.preventDefault();
        event.stopPropagation();
        startSketchDimensionLabelDrag(event, label);
    });
    label.addEventListener('pointermove', (event) => {
        if (!updateSketchDimensionLabelDrag(event, label)) return;
        event.preventDefault();
        event.stopPropagation();
    });
    label.addEventListener('pointerup', (event) => {
        event.stopPropagation();
        finishSketchDimensionLabelDrag(event, label);
    });
    label.addEventListener('pointercancel', (event) => {
        event.stopPropagation();
        finishSketchDimensionLabelDrag(event, label);
    });
    el.sketchDimensionOverlay?.appendChild(label);
    sketch.dimensionAnnotationLabels.set(dimensionId, label);
    return label;
}

function disposeSketchPreviewChildren(group) {
    while (group?.children?.length) {
        const child = group.children.pop();
        disposeObjectResources(child);
    }
}

function clearSketchPreviewVisual() {
    const sketch = state.sketch;
    sketch.dimensionEditing = null;
    sketch.dimensionLabelDrag = null;
    sketch.dimensionLineDrag = null;
    sketch.dimensionPlacement = null;
    sketch.dimensionAnnotationEditing = null;
    sketch.dimensionLabels.forEach((label) => label.remove());
    sketch.dimensionLabels.clear();
    sketch.dimensionAnnotationLabels.forEach((label) => label.remove());
    sketch.dimensionAnnotationLabels.clear();
    sketch.snapReadout?.remove();
    sketch.snapReadout = null;
    if (sketch.previewGroup) {
        disposeObjectResources(sketch.previewGroup);
        sketch.previewGroup.removeFromParent();
    }
    sketch.previewGroup = null;
}

function getSketchOverlaySize() {
    const rect = el.canvasContainer?.getBoundingClientRect();
    return {
        width: el.sketchDimensionOverlay?.clientWidth || rect?.width || 0,
        height: el.sketchDimensionOverlay?.clientHeight || rect?.height || 0
    };
}

function projectSketchPointRaw(point) {
    const projected = point.clone().add(state.sketch.origin).project(state.camera);
    const { width, height } = getSketchOverlaySize();
    return {
        left: (projected.x + 1) * 0.5 * width,
        top: (1 - projected.y) * 0.5 * height
    };
}

function projectSketchPoint(point) {
    const projected = projectSketchPointRaw(point);
    const { width, height } = getSketchOverlaySize();
    return {
        left: THREE.MathUtils.clamp(projected.left, 42, Math.max(42, width - 42)),
        top: THREE.MathUtils.clamp(projected.top, 22, Math.max(22, height - 22))
    };
}

function getSketchDimensionAxisLine(normalized) {
    if (!normalized) return null;
    if (normalized.type !== 'position') {
        return {
            start: normalized.start.clone(),
            end: normalized.end.clone()
        };
    }
    const axis = normalized.axis === 'y' ? 'y' : 'x';
    return {
        start: normalized.start.clone(),
        end: axis === 'x'
            ? new THREE.Vector3(normalized.end.x, normalized.start.y, 0)
            : new THREE.Vector3(normalized.start.x, normalized.end.y, 0)
    };
}

function getSketchDimensionExtensionOrigin(normalized, reference, fallback, offset) {
    if (!normalized || reference?.kind !== 'line-point') return fallback;
    const entity = getSketchReferenceEntity(reference);
    const segment = entity
        ? getSketchEntityEdgeSegments(entity).find(({ index }) => index === reference.segmentIndex)
        : null;
    if (!segment) return fallback;
    const delta = segment.end.clone().sub(segment.start);
    let axisValue = normalized.axis === 'y' ? offset?.x : offset?.y;
    if (!Number.isFinite(axisValue) || Math.abs(axisValue) < 1e-8) axisValue = 1;
    if (normalized.axis === 'x' && Math.abs(delta.y) >= Math.abs(delta.x)) {
        return (axisValue >= 0 ? segment.start.y >= segment.end.y : segment.start.y <= segment.end.y)
            ? segment.start.clone()
            : segment.end.clone();
    }
    if (normalized.axis === 'y' && Math.abs(delta.x) >= Math.abs(delta.y)) {
        return (axisValue >= 0 ? segment.start.x >= segment.end.x : segment.start.x <= segment.end.x)
            ? segment.start.clone()
            : segment.end.clone();
    }
    const normal = normalized.axis === 'y'
        ? new THREE.Vector3(1, 0, 0)
        : new THREE.Vector3(0, 1, 0);
    const startProjection = segment.start.dot(normal);
    const endProjection = segment.end.dot(normal);
    return (axisValue >= 0 ? startProjection >= endProjection : startProjection <= endProjection)
        ? segment.start.clone()
        : segment.end.clone();
}

function createSketchDimensionArrowheads(start, end, color, opacity = 0.95, sizePixels = 8, z = 0.56) {
    if (!start || !end) return null;
    const direction = end.clone().sub(start).setZ(0);
    const length = direction.length();
    if (length < 1e-6) return null;
    direction.multiplyScalar(1 / length);
    const normal = new THREE.Vector3(-direction.y, direction.x, 0);
    const size = Math.min(
        getSketchWorldUnitsPerPixel() * sizePixels,
        Math.max(getSketchWorldUnitsPerPixel() * 3, length * 0.28)
    );
    const wing = size * 0.62;
    const startTip = start.clone().setZ(z);
    const endTip = end.clone().setZ(z);
    const startBase = startTip.clone().addScaledVector(direction, size);
    const endBase = endTip.clone().addScaledVector(direction, -size);
    const group = new THREE.Group();
    group.name = 'Sketch dimension arrowheads';
    [
        [startTip, startBase],
        [endTip, endBase]
    ].forEach(([tip, base]) => {
        const left = base.clone().addScaledVector(normal, wing);
        const right = base.clone().addScaledVector(normal, -wing);
        const geometry = new THREE.BufferGeometry();
        geometry.setAttribute('position', new THREE.Float32BufferAttribute([
            tip.x, tip.y, tip.z,
            left.x, left.y, left.z,
            right.x, right.y, right.z
        ], 3));
        geometry.computeVertexNormals();
        const fill = new THREE.Mesh(
            geometry,
            new THREE.MeshBasicMaterial({
                color,
                transparent: true,
                opacity: Math.min(1, opacity * 0.92),
                depthTest: false,
                depthWrite: false,
                side: THREE.DoubleSide,
                toneMapped: false
            })
        );
        fill.renderOrder = 83;
        group.add(fill);
        [[tip, left], [tip, right]].forEach(([from, to]) => {
            const edge = createSketchLine(color, opacity);
            setSketchLinePoints(edge, [from, to]);
            edge.renderOrder = 84;
            group.add(edge);
        });
    });
    return group;
}

function getSketchDimensionLabelGapPixels(label, minimum = 28) {
    if (!label || label.hidden) return 0;
    const width = label.getBoundingClientRect?.().width || label.offsetWidth || 0;
    return Math.max(minimum, Math.ceil(width + 10));
}

function addSketchDimensionLine(dimensionsGroup, start, end, color, opacity = 0.9, options = {}) {
    if (!dimensionsGroup || !start || !end) return null;
    const z = Number.isFinite(options.z) ? options.z : 0.56;
    const shiftedStart = start.clone().setZ(z);
    const shiftedEnd = end.clone().setZ(z);
    const direction = shiftedEnd.clone().sub(shiftedStart).setZ(0);
    const length = direction.length();
    if (length < 1e-6) return null;
    direction.multiplyScalar(1 / length);
    const labelGapWorld = getSketchWorldUnitsPerPixel() * Math.max(0, Number(options.labelGapPixels) || 0);
    const halfGap = Math.min(length * 0.46, labelGapWorld * 0.5);
    const gapCenter = shiftedStart.clone().add(shiftedEnd).multiplyScalar(0.5);
    const segments = halfGap > 0
        ? [
            [shiftedStart, gapCenter.clone().addScaledVector(direction, -halfGap)],
            [gapCenter.clone().addScaledVector(direction, halfGap), shiftedEnd]
        ]
        : [[shiftedStart, shiftedEnd]];
    let firstLine = null;
    segments.forEach(([segmentStart, segmentEnd]) => {
        if (segmentStart.distanceToSquared(segmentEnd) < 1e-10) return;
        const line = createSketchLine(color, opacity);
        setSketchLinePoints(line, [segmentStart, segmentEnd]);
        line.renderOrder = 81;
        dimensionsGroup.add(line);
        if (!firstLine) firstLine = line;
    });
    if (options.arrows !== false) {
        const arrows = createSketchDimensionArrowheads(
            shiftedStart,
            shiftedEnd,
            color,
            Math.min(1, opacity + 0.12),
            options.arrowSizePixels || 8,
            z + 0.01
        );
        if (arrows) dimensionsGroup.add(arrows);
    }
    return firstLine;
}

function getSketchDimensionLabelAnchor(normalized) {
    if (!normalized) return null;
    const line = getSketchDimensionAxisLine(normalized);
    if (!line) return null;
    return line.start.clone().add(line.end).multiplyScalar(0.5).setZ(0.5);
}

function getSketchDimensionDefaultLabelOffset(normalized) {
    const line = getSketchDimensionAxisLine(normalized);
    if (!line) return { x: 0, y: -getSketchWorldUnitsPerPixel() * 22 };
    const direction = line.end.clone().sub(line.start).setZ(0);
    const length = Math.hypot(direction.x, direction.y);
    const pixels = normalized.type === 'position' ? 24 : 20;
    const distance = getSketchWorldUnitsPerPixel() * pixels;
    if (length < 1e-6) return { x: 0, y: -distance };
    return {
        x: (-direction.y / length) * distance,
        y: (direction.x / length) * distance
    };
}

function getSketchDimensionLabelLayout(normalized) {
    const anchor = getSketchDimensionLabelAnchor(normalized);
    if (!anchor) return null;
    const offset = normalized.labelOffset || getSketchDimensionDefaultLabelOffset(normalized);
    const labelPoint = anchor.clone().add(new THREE.Vector3(offset.x, offset.y, 0));
    const screenPoint = projectSketchPoint(labelPoint);
    const { width, height } = getSketchOverlaySize();
    return {
        anchor,
        labelPoint,
        offset,
        left: THREE.MathUtils.clamp(screenPoint.left, 8, Math.max(8, width - 8)),
        top: THREE.MathUtils.clamp(screenPoint.top, 8, Math.max(8, height - 8))
    };
}

function getSketchDimensionLineAtPoint(point, tolerance = getSketchHitToleranceWorld(14)) {
    if (!point) return null;
    refreshSketchDimensionReferences();
    let nearest = null;
    (state.sketch.dimensions || []).forEach((dimension) => {
        const normalized = normalizeSketchDimensionRecord(dimension);
        const line = getSketchDimensionAxisLine(normalized);
        if (!normalized || !line) return;
        const offset = normalized.labelOffset || getSketchDimensionDefaultLabelOffset(normalized);
        const shiftedStart = line.start.clone().add(new THREE.Vector3(offset.x, offset.y, 0));
        const shiftedEnd = line.end.clone().add(new THREE.Vector3(offset.x, offset.y, 0));
        const distance = distanceToSketchSegment(point, shiftedStart, shiftedEnd);
        if (distance > tolerance || (nearest && distance >= nearest.distance)) return;
        nearest = {
            dimension,
            normalized,
            start: shiftedStart,
            end: shiftedEnd,
            distance
        };
    });
    return nearest;
}

function getSketchPlaneOffsetFromScreenDelta(anchor, screenDeltaX, screenDeltaY) {
    const origin = projectSketchPointRaw(anchor);
    const xBasis = projectSketchPointRaw(anchor.clone().add(new THREE.Vector3(1, 0, 0)));
    const yBasis = projectSketchPointRaw(anchor.clone().add(new THREE.Vector3(0, 1, 0)));
    const xAxis = { x: xBasis.left - origin.left, y: xBasis.top - origin.top };
    const yAxis = { x: yBasis.left - origin.left, y: yBasis.top - origin.top };
    const determinant = xAxis.x * yAxis.y - yAxis.x * xAxis.y;
    if (Math.abs(determinant) < 1e-8) {
        const unitsPerPixel = getSketchWorldUnitsPerPixel();
        return {
            x: screenDeltaY * -unitsPerPixel,
            y: screenDeltaX * unitsPerPixel
        };
    }
    return {
        x: (screenDeltaX * yAxis.y - screenDeltaY * yAxis.x) / determinant,
        y: (xAxis.x * screenDeltaY - xAxis.y * screenDeltaX) / determinant
    };
}

function getSketchDimensionPlacementOffset(normalized, point) {
    const anchor = getSketchDimensionLabelAnchor(normalized);
    const line = getSketchDimensionAxisLine(normalized);
    if (!anchor || !line || !point) return null;
    const direction = line.end.clone().sub(line.start).setZ(0);
    const length = Math.hypot(direction.x, direction.y);
    if (length < 1e-6) return null;
    const normal = new THREE.Vector3(-direction.y / length, direction.x / length, 0);
    const mouseDelta = point.clone().sub(anchor).setZ(0);
    const signedDistance = mouseDelta.dot(normal);
    return {
        x: normal.x * signedDistance,
        y: normal.y * signedDistance
    };
}

function beginSketchDimensionPlacement(dimension, point, historyBefore = null, created = false) {
    const sketch = state.sketch;
    const normalized = normalizeSketchDimensionRecord(dimension);
    if (!normalized) return false;
    const offset = getSketchDimensionPlacementOffset(normalized, point);
    if (offset) dimension.labelOffset = offset;
    sketch.selectedDimensionId = dimension.id;
    sketch.dimensionPlacement = {
        dimensionId: dimension.id,
        historyBefore: historyBefore || captureSketchEditSnapshot(),
        created
    };
    sketch.dimensionDraft = createEmptySketchDimensionDraft();
    sketch.snapCandidate = null;
    sketch.dimensionHoverTarget = null;
    sketch.hoverEntityId = null;
    syncSketchDocumentEntities();
    updateSketchPreview();
    renderSketchEditorUi();
    setStatus(uiText('치수 위치를 따라가고 있습니다. 원하는 위치에서 클릭해 고정하세요.'), '#facc15');
    requestRender();
    return true;
}

function getSketchPositionDimensionAxisForPlacement(dimension, point, axisLocked = null) {
    if (axisLocked === 'x' || axisLocked === 'y') return axisLocked;
    if (!dimension?.start || !dimension?.end || !point) return dimension?.axis === 'y' ? 'y' : 'x';
    const midpoint = dimension.start.clone().add(dimension.end).multiplyScalar(0.5);
    const mouseDelta = point.clone().sub(midpoint);
    // Cursor above/below the selected points places a horizontal X dimension;
    // cursor to either side places a vertical Y dimension.
    return Math.abs(mouseDelta.y) >= Math.abs(mouseDelta.x) ? 'x' : 'y';
}

function updateSketchDimensionPlacement(point) {
    const sketch = state.sketch;
    const placement = sketch.dimensionPlacement;
    if (!placement || !point) return false;
    const dimension = sketch.dimensions.find((entry) => entry.id === placement.dimensionId);
    if (!dimension) return false;
    if (placement.positionDraft) {
        dimension.axis = getSketchPositionDimensionAxisForPlacement(dimension, point, placement.axisLocked);
        dimension.xValue = dimension.end.x - dimension.start.x;
        dimension.yValue = dimension.end.y - dimension.start.y;
        dimension.value = Math.abs(dimension.axis === 'x' ? dimension.xValue : dimension.yValue);
        if (dimension.value < SKETCH_MIN_SIZE) {
            updateSketchPreview();
            renderSketchEditorUi();
            requestRender();
            return false;
        }
    }
    const normalized = normalizeSketchDimensionRecord(dimension);
    const offset = getSketchDimensionPlacementOffset(normalized, point);
    if (!offset) return false;
    dimension.labelOffset = offset;
    updateSketchPreview();
    renderSketchEditorUi();
    requestRender();
    return true;
}

function beginSketchPositionDimensionPlacement(
    start,
    end,
    startRef,
    endRef,
    { axisLocked = null, placementPoint = null, drivingRef = null } = {}
) {
    if (!start || !end) return false;
    const xValue = end.x - start.x;
    const yValue = end.y - start.y;
    let axis = getSketchPositionDimensionAxisForPlacement(
        { start, end, axis: null },
        placementPoint,
        axisLocked
    );
    if (Math.abs(axis === 'x' ? xValue : yValue) < SKETCH_MIN_SIZE && !axisLocked) {
        const alternateAxis = axis === 'x' ? 'y' : 'x';
        if (Math.abs(alternateAxis === 'x' ? xValue : yValue) >= SKETCH_MIN_SIZE) axis = alternateAxis;
    }
    const value = Math.abs(axis === 'x' ? xValue : yValue);
    if (!Number.isFinite(value) || value < SKETCH_MIN_SIZE) {
        setStatus(uiText('두 스냅 지점의 X 또는 Y 축 거리가 너무 짧습니다. 다시 선택하세요.'), '#f59e0b');
        return false;
    }
    const historyBefore = captureSketchEditSnapshot();
    const dimension = normalizeSketchDimensionRecord({
        id: `dimension-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        type: 'position',
        start: start.toArray(),
        end: end.toArray(),
        xValue,
        yValue,
        value,
        startRef,
        endRef,
        axis,
        drivingRef: drivingRef || (startRef?.kind === 'line-point' ? 'start' : null),
        referenceEntityIds: [startRef?.entityId, endRef?.entityId].filter(Boolean)
    });
    if (!dimension) return false;
    state.sketch.dimensions.push(dimension);
    state.sketch.selectedDimensionId = dimension.id;
    state.sketch.dimensionDraft = createEmptySketchDimensionDraft();
    state.sketch.dimensionHoverTarget = null;
    state.sketch.hoverEntityId = null;
    state.sketch.dimensionPlacement = {
        dimensionId: dimension.id,
        historyBefore,
        created: true,
        positionDraft: true,
        axisLocked: axisLocked === 'x' || axisLocked === 'y' ? axisLocked : null
    };
    updateSketchDimensionPlacement(placementPoint || getSketchDimensionLabelAnchor(dimension));
    syncSketchDocumentEntities();
    updateSketchPreview();
    renderSketchEditorUi();
    setStatus(uiText('치수 방향과 위치를 정한 뒤 클릭하면 치수를 고정하고 값을 입력할 수 있습니다.'), '#facc15');
    requestRender();
    return true;
}

function finishSketchDimensionPlacement(point) {
    const sketch = state.sketch;
    const placement = sketch.dimensionPlacement;
    if (!placement) return false;
    const updated = updateSketchDimensionPlacement(point);
    if (placement.positionDraft && !updated) {
        setStatus(uiText('현재 방향의 치수 거리가 너무 짧습니다. 수평 또는 수직 방향을 바꿔 다시 위치를 정하세요.'), '#f59e0b');
        return false;
    }
    sketch.dimensionPlacement = null;
    syncSketchDocumentEntities();
    updateSketchPreview();
    renderSketchEditorUi();
    recordSketchHistory('치수 생성 또는 위치 변경', placement.historyBefore);
    beginSketchDimensionAnnotationEdit(placement.dimensionId);
    setStatus(uiText('치수 위치를 고정했습니다. 값을 입력하세요.'), '#22c55e');
    requestRender();
    return true;
}

function cancelSketchDimensionPlacement({ remove = true } = {}) {
    const sketch = state.sketch;
    const placement = sketch.dimensionPlacement;
    if (!placement) return false;
    if (remove && placement.created) {
        sketch.dimensions = sketch.dimensions.filter((entry) => entry.id !== placement.dimensionId);
        if (sketch.selectedDimensionId === placement.dimensionId) sketch.selectedDimensionId = null;
    } else if (remove && placement.historyBefore) {
        const previous = placement.historyBefore.dimensions?.find((entry) => entry.id === placement.dimensionId);
        const dimension = sketch.dimensions.find((entry) => entry.id === placement.dimensionId);
        const restored = normalizeSketchDimensionRecord(previous);
        if (dimension && restored) Object.assign(dimension, restored);
    }
    sketch.dimensionPlacement = null;
    return true;
}

function finishSketchDimensionAnnotationEdit(apply) {
    const sketch = state.sketch;
    const edit = sketch.dimensionAnnotationEditing;
    if (!edit) return false;
    const dimension = sketch.dimensions.find((entry) => entry.id === edit.dimensionId);
    sketch.dimensionAnnotationEditing = null;
    const valid = apply && dimension
        ? applySelectedSketchDimensionValue(edit.input.value, { announce: false, recordHistory: false })
        : false;
    if (!valid) {
        const restoredEntities = (edit.beforeEntities || [])
            .map(normalizeSketchEntityRecord)
            .filter(Boolean);
        if (restoredEntities.length) sketch.entities = restoredEntities;
        const restoredDimension = normalizeSketchDimensionRecord(edit.beforeDimension);
        if (dimension && restoredDimension) Object.assign(dimension, restoredDimension);
    } else {
        recordSketchHistory('스케치 치수 변경', edit.historyBefore);
    }
    syncSketchDocumentEntities();
    updateSketchPreview();
    renderSketchEditorUi();
    requestRender();
    return valid;
}

function beginSketchDimensionAnnotationEdit(dimensionId) {
    const sketch = state.sketch;
    const dimension = sketch.dimensions.find((entry) => entry.id === dimensionId);
    const label = getSketchDimensionAnnotationLabel(dimensionId);
    if (!sketch.active || !dimension || !label || sketch.dimensionPlacement || sketch.dimensionAnnotationEditing) {
        return false;
    }
    const input = document.createElement('input');
    input.type = 'number';
    input.min = String(SKETCH_MIN_SIZE);
    input.max = String(SKETCH_MAX_SIZE);
    input.step = '0.5';
    input.value = formatJogValue(dimension.type === 'position'
        ? dimension.drivingRef === 'start'
            ? Math.abs(dimension.value)
            : dimension.axis === 'y' ? Math.abs(dimension.yValue) : Math.abs(dimension.xValue)
        : dimension.value);
    sketch.selectedDimensionId = dimensionId;
    sketch.dimensionAnnotationEditing = {
        dimensionId,
        input,
        beforeDimension: serializeSketchDimension(dimension),
        beforeEntities: sketch.entities.map(serializeSketchEntity).filter(Boolean),
        historyBefore: captureSketchEditSnapshot()
    };
    label.replaceChildren(input);
    input.addEventListener('input', () => applySelectedSketchDimensionValue(
        input.value,
        { announce: false, recordHistory: false }
    ));
    input.addEventListener('keydown', (event) => {
        event.stopPropagation();
        if (event.key === 'Enter') {
            event.preventDefault();
            finishSketchDimensionAnnotationEdit(true);
        } else if (event.key === 'Escape') {
            event.preventDefault();
            finishSketchDimensionAnnotationEdit(false);
        }
    });
    input.addEventListener('blur', () => finishSketchDimensionAnnotationEdit(true));
    input.addEventListener('pointerdown', (event) => event.stopPropagation());
    input.addEventListener('click', (event) => event.stopPropagation());
    input.focus({ preventScroll: true });
    input.select();
    return true;
}

function startSketchDimensionLabelDrag(event, label) {
    const sketch = state.sketch;
    const dimensionId = label?.dataset?.dimensionId;
    const dimension = sketch.dimensions.find((entry) => entry.id === dimensionId);
    if (!dimension) return;
    const normalized = normalizeSketchDimensionRecord(dimension);
    const layout = getSketchDimensionLabelLayout(normalized);
    if (!layout) return;
    sketch.selectedDimensionId = dimensionId;
    sketch.activeTool = 'dimension';
    sketch.dimensionLabelDrag = {
        dimensionId,
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        initialOffset: { ...layout.offset },
        moveAxis: null,
        moved: false,
        historyBefore: captureSketchEditSnapshot()
    };
    label.classList.add('is-dragging');
    label.setPointerCapture?.(event.pointerId);
    renderSketchEditorUi();
}

function getSketchDimensionAxisLockedScreenDelta(drag, event) {
    const screenDeltaX = event.clientX - drag.startX;
    const screenDeltaY = event.clientY - drag.startY;
    if (!drag.moveAxis && Math.hypot(screenDeltaX, screenDeltaY) > 2) {
        drag.moveAxis = Math.abs(screenDeltaX) >= Math.abs(screenDeltaY)
            ? 'horizontal'
            : 'vertical';
    }
    if (drag.moveAxis === 'horizontal') return { x: screenDeltaX, y: 0 };
    if (drag.moveAxis === 'vertical') return { x: 0, y: screenDeltaY };
    return { x: 0, y: 0 };
}

function updateSketchDimensionLabelDrag(event, label) {
    const drag = state.sketch.dimensionLabelDrag;
    if (!drag || drag.pointerId !== event.pointerId || drag.dimensionId !== label?.dataset?.dimensionId) {
        return false;
    }
    const dimension = state.sketch.dimensions.find((entry) => entry.id === drag.dimensionId);
    if (!dimension) return false;
    const normalized = normalizeSketchDimensionRecord(dimension);
    const screenDelta = getSketchDimensionAxisLockedScreenDelta(drag, event);
    const planeDelta = getSketchPlaneOffsetFromScreenDelta(
        getSketchDimensionLabelAnchor(normalized),
        screenDelta.x,
        screenDelta.y
    );
    drag.moved = drag.moved || Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY) > 2;
    dimension.labelOffset = {
        x: drag.initialOffset.x + planeDelta.x,
        y: drag.initialOffset.y + planeDelta.y
    };
    syncSketchDocumentEntities();
    updateSketchPreview();
    renderSketchEditorUi();
    requestRender();
    return true;
}

function finishSketchDimensionLabelDrag(event, label) {
    const drag = state.sketch.dimensionLabelDrag;
    if (!drag || drag.pointerId !== event.pointerId || drag.dimensionId !== label?.dataset?.dimensionId) return;
    label.releasePointerCapture?.(event.pointerId);
    label.classList.remove('is-dragging');
    state.sketch.dimensionLabelDrag = null;
    if (drag.moved) {
        syncSketchDocumentEntities();
        recordSketchHistory('치수 표시 위치 변경', drag.historyBefore);
        setStatus(uiText('치수 표시 위치를 변경했습니다.'), '#60a5fa');
        requestRender();
    }
}

function startSketchDimensionLineDrag(event, hit) {
    const sketch = state.sketch;
    const dimension = hit?.dimension;
    if (!sketch.active || !dimension || sketch.dimensionPlacement || sketch.dimensionAnnotationEditing) {
        return false;
    }
    const normalized = hit.normalized || normalizeSketchDimensionRecord(dimension);
    const layout = getSketchDimensionLabelLayout(normalized);
    if (!normalized || !layout) return false;
    sketch.selectedDimensionId = dimension.id;
    sketch.activeTool = 'dimension';
    sketch.dimensionLineDrag = {
        dimensionId: dimension.id,
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        initialOffset: { ...layout.offset },
        initialLabelOffset: normalized.labelOffset ? { ...normalized.labelOffset } : null,
        moveAxis: null,
        moved: false,
        historyBefore: captureSketchEditSnapshot()
    };
    state.renderer.domElement.setPointerCapture?.(event.pointerId);
    renderSketchEditorUi();
    updateSketchPreview();
    requestRender();
    return true;
}

function updateSketchDimensionLineDrag(event) {
    const sketch = state.sketch;
    const drag = sketch.dimensionLineDrag;
    if (!drag || drag.pointerId !== event.pointerId) return false;
    const dimension = sketch.dimensions.find((entry) => entry.id === drag.dimensionId);
    const normalized = normalizeSketchDimensionRecord(dimension);
    const anchor = getSketchDimensionLabelAnchor(normalized);
    if (!dimension || !normalized || !anchor) return false;
    const screenDeltaX = event.clientX - drag.startX;
    const screenDeltaY = event.clientY - drag.startY;
    const screenDelta = getSketchDimensionAxisLockedScreenDelta(drag, event);
    const planeDelta = getSketchPlaneOffsetFromScreenDelta(anchor, screenDelta.x, screenDelta.y);
    drag.moved = drag.moved || Math.hypot(screenDeltaX, screenDeltaY) > 2;
    dimension.labelOffset = {
        x: drag.initialOffset.x + planeDelta.x,
        y: drag.initialOffset.y + planeDelta.y
    };
    syncSketchDocumentEntities();
    updateSketchPreview();
    renderSketchEditorUi();
    requestRender();
    return true;
}

function finishSketchDimensionLineDrag(event) {
    const sketch = state.sketch;
    const drag = sketch.dimensionLineDrag;
    if (!drag || drag.pointerId !== event.pointerId) return false;
    state.renderer.domElement.releasePointerCapture?.(event.pointerId);
    sketch.dimensionLineDrag = null;
    if (drag.moved) {
        syncSketchDocumentEntities();
        recordSketchHistory('치수 표시 위치 변경', drag.historyBefore);
        setStatus(uiText('치수 표시 위치를 변경했습니다.'), '#60a5fa');
    }
    updateSketchPreview();
    renderSketchEditorUi();
    requestRender();
    return true;
}

function cancelSketchDimensionLineDrag() {
    const sketch = state.sketch;
    const drag = sketch.dimensionLineDrag;
    if (!drag) return false;
    state.renderer.domElement.releasePointerCapture?.(drag.pointerId);
    const dimension = sketch.dimensions.find((entry) => entry.id === drag.dimensionId);
    if (dimension) {
        dimension.labelOffset = drag.initialLabelOffset ? { ...drag.initialLabelOffset } : null;
    }
    sketch.dimensionLineDrag = null;
    syncSketchDocumentEntities();
    return true;
}

function setSketchLinePoints(line, points, visible = true) {
    if (!line) return;
    line.geometry.setFromPoints(points || []);
    if (line.material?.isLineDashedMaterial) line.computeLineDistances();
    line.visible = Boolean(visible && points?.length >= (line.isLineLoop ? 3 : 2));
}

function getSketchWorldUnitsPerPixel() {
    const rect = state.renderer?.domElement?.getBoundingClientRect?.();
    const height = Math.max(1, rect?.height || state.renderer?.domElement?.clientHeight || 1);
    const camera = state.camera;
    if (!camera) return 0.5;
    if (camera.isOrthographicCamera) {
        return Math.max(0.001, (camera.top - camera.bottom) / (height * Math.max(camera.zoom || 1, Number.EPSILON)));
    }
    if (camera.isPerspectiveCamera) {
        const target = state.controls?.target || new THREE.Vector3();
        const distance = Math.max(1, camera.position.distanceTo(target));
        return Math.max(0.001, (2 * distance * Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2)) / height);
    }
    return 0.5;
}

function renderSketchSnapIndicators(snapGroup) {
    const sketch = state.sketch;
    if (sketch.snapReadout) sketch.snapReadout.hidden = true;
    if (!snapGroup || !sketch.active || sketch.snapMode || sketch.snapEnabled === false || !sketch.hoverPoint) return;
    const candidate = sketch.snapCandidate;
    const point = candidate?.point || sketch.hoverPoint;
    if (!point) return;
    if (candidate && sketch.snapReadout) {
        const screenPoint = projectSketchPoint(point);
        sketch.snapReadout.hidden = false;
        sketch.snapReadout.style.left = `${screenPoint.left}px`;
        sketch.snapReadout.style.top = `${screenPoint.top}px`;
        sketch.snapReadout.innerHTML = `<strong>${candidate.label || getSketchSnapCandidateLabel(candidate)}</strong><br><span>X ${formatJogValue(point.x)} · Y ${formatJogValue(point.y)} mm</span>`;
    }
    const pixels = getSketchWorldUnitsPerPixel();
    const size = Math.max(pixels * (candidate ? 8 : 6), 0.75);
    const color = candidate ? 0xfacc15 : 0x64748b;
    const marker = new THREE.Group();
    marker.position.set(point.x, point.y, 1.25);
    marker.userData.sketchSnapIndicator = true;
    marker.renderOrder = 90;

    const ring = createSketchLine(color, candidate ? 0.95 : 0.5, true);
    const ringPoints = Array.from({ length: 20 }, (_, index) => {
        const angle = (index / 20) * Math.PI * 2;
        return new THREE.Vector3(Math.cos(angle) * size, Math.sin(angle) * size, 0);
    });
    setSketchLinePoints(ring, ringPoints);
    ring.renderOrder = 91;
    marker.add(ring);

    const cross = createSketchLine(color, candidate ? 0.9 : 0.42);
    setSketchLinePoints(cross, [
        new THREE.Vector3(-size * 1.45, 0, 0), new THREE.Vector3(size * 1.45, 0, 0),
        new THREE.Vector3(0, -size * 1.45, 0), new THREE.Vector3(0, size * 1.45, 0)
    ]);
    cross.renderOrder = 91;
    marker.add(cross);

    if (candidate) {
        const glyph = createSketchLine(color, 1, true);
        const glyphSize = size * 0.95;
        const glyphPoints = candidate.type === 'midpoint'
            ? [
                new THREE.Vector3(0, glyphSize, 0),
                new THREE.Vector3(glyphSize, 0, 0),
                new THREE.Vector3(0, -glyphSize, 0),
                new THREE.Vector3(-glyphSize, 0, 0)
            ]
            : candidate.type === 'endpoint' || candidate.type === 'vertex'
                ? [
                    new THREE.Vector3(-glyphSize, -glyphSize, 0),
                    new THREE.Vector3(glyphSize, -glyphSize, 0),
                    new THREE.Vector3(glyphSize, glyphSize, 0),
                    new THREE.Vector3(-glyphSize, glyphSize, 0)
                ]
                : [];
        if (glyphPoints.length) {
            setSketchLinePoints(glyph, glyphPoints);
            glyph.renderOrder = 92;
            marker.add(glyph);
        }
        const dot = new THREE.Mesh(
            new THREE.CircleGeometry(Math.max(size * 0.24, 0.35), 16),
            new THREE.MeshBasicMaterial({
                color,
                depthTest: false,
                depthWrite: false,
                transparent: true,
                opacity: 0.95,
                toneMapped: false
            })
        );
        dot.renderOrder = 93;
        marker.add(dot);
    }
    snapGroup.add(marker);
}

function renderSketchDimensionHover(dimensionsGroup) {
    const sketch = state.sketch;
    const target = sketch.dimensionHoverTarget;
    if (!dimensionsGroup || sketch.activeTool !== 'dimension' || !target?.entity) return;
    if (!state.sketch.entities.some((entity) => entity.id === target.entity.id)) return;
    const lineColor = SKETCH_DIMENSION_GREEN;
    const line = createSketchLine(lineColor, 1, target.targetType === 'diameter' && Boolean(target.entity.center));
    line.renderOrder = 80;
    if (target.targetType === 'diameter' && target.entity.center) {
        const points = Array.from({ length: 48 }, (_, index) => {
            const angle = (index / 48) * Math.PI * 2;
            return new THREE.Vector3(
                target.entity.center.x + Math.cos(angle) * target.entity.radius,
                target.entity.center.y + Math.sin(angle) * target.entity.radius,
                0.78
            );
        });
        setSketchLinePoints(line, points);
    } else {
        setSketchLinePoints(line, [
            target.start.clone().setZ(0.78),
            target.end.clone().setZ(0.78)
        ]);
    }
    line.userData.sketchDimensionHover = true;
    dimensionsGroup.add(line);
    const arrows = createSketchDimensionArrowheads(
        target.start,
        target.end,
        lineColor,
        1,
        8,
        0.8
    );
    if (arrows) dimensionsGroup.add(arrows);
}

function showSketchDimensionLabel(axis, text, point) {
    const label = state.sketch.dimensionLabels.get(axis);
    if (!label || !point) return;
    label.hidden = false;
    const screenPoint = projectSketchPoint(point);
    label.style.left = `${screenPoint.left}px`;
    label.style.top = `${screenPoint.top}px`;
    if (!(state.sketch.dimensionEditing?.axis === axis && label.contains(state.sketch.dimensionEditing.input))) {
        label.textContent = text;
    }
}

function renderSketchDimensionAnnotations(dimensionsGroup) {
    const sketch = state.sketch;
    refreshSketchDimensionReferences();
    sketch.dimensionAnnotationLabels.forEach((label) => { label.hidden = true; });
    (sketch.dimensions || []).forEach((dimension, index) => {
        const normalized = normalizeSketchDimensionRecord(dimension);
        if (!normalized) return;
        const selected = normalized.id === sketch.selectedDimensionId;
        const lineColor = selected ? 0x86efac : SKETCH_DIMENSION_GREEN;
        const dimensionLine = getSketchDimensionAxisLine(normalized);
        const layout = getSketchDimensionLabelLayout(normalized);
        if (!dimensionLine || !layout) return;
        const offset = new THREE.Vector3(layout.offset.x, layout.offset.y, 0);
        const shiftedStart = dimensionLine.start.clone().add(offset).setZ(0.5);
        const shiftedEnd = dimensionLine.end.clone().add(offset).setZ(0.5);
        const label = getSketchDimensionAnnotationLabel(normalized.id);
        label.hidden = false;
        label.classList.toggle('selected', selected);
        label.classList.toggle('is-placement-pending', sketch.dimensionPlacement?.dimensionId === normalized.id);
        label.style.left = `${layout.left}px`;
        label.style.top = `${layout.top}px`;
        const editing = sketch.dimensionAnnotationEditing?.dimensionId === normalized.id
            && label.contains(sketch.dimensionAnnotationEditing.input);
        if (!editing) {
            label.textContent = normalized.type === 'position'
                ? `${formatJogValue(Math.abs(normalized.axis === 'x' ? normalized.xValue : normalized.yValue))}`
                : `${normalized.type === 'diameter' ? 'Ø' : normalized.type === 'length' ? 'L' : 'D'}${index + 1} = ${formatJogValue(normalized.value)}`;
        }
        addSketchDimensionLine(
            dimensionsGroup,
            shiftedStart,
            shiftedEnd,
            lineColor,
            selected ? 1 : 0.85,
            {
                z: 0.56,
                arrowSizePixels: selected ? 9 : 8,
                labelGapPixels: getSketchDimensionLabelGapPixels(label)
            }
        );
        const extensionStart = createSketchLine(lineColor, selected ? 0.72 : 0.52);
        const extensionEnd = createSketchLine(lineColor, selected ? 0.72 : 0.52);
        const extensionStartOrigin = getSketchDimensionExtensionOrigin(
            normalized,
            normalized.startRef,
            dimensionLine.start,
            offset
        );
        const extensionEndOrigin = getSketchDimensionExtensionOrigin(
            normalized,
            normalized.endRef,
            dimensionLine.end,
            offset
        );
        setSketchLinePoints(extensionStart, [extensionStartOrigin.clone().setZ(0.5), shiftedStart]);
        setSketchLinePoints(extensionEnd, [extensionEndOrigin.clone().setZ(0.5), shiftedEnd]);
        dimensionsGroup.add(extensionStart, extensionEnd);
    });
    const draft = sketch.dimensionDraft;
    if (draft?.start && draft?.end) {
        if (draft.mode === 'position') {
            const axis = Math.abs(draft.end.x - draft.start.x) >= Math.abs(draft.end.y - draft.start.y) ? 'x' : 'y';
            const axisEnd = axis === 'x'
                ? new THREE.Vector3(draft.end.x, draft.start.y, 0.55)
                : new THREE.Vector3(draft.start.x, draft.end.y, 0.55);
            addSketchDimensionLine(
                dimensionsGroup,
                draft.start.clone().setZ(0.55),
                axisEnd,
                0x86efac,
                0.9,
                { z: 0.6, arrowSizePixels: 8 }
            );
        } else {
            addSketchDimensionLine(
                dimensionsGroup,
                draft.start.clone().setZ(0.55),
                draft.end.clone().setZ(0.55),
                0x86efac,
                0.9,
                { z: 0.6, arrowSizePixels: 8 }
            );
        }
    }
}

// Per-entity line objects and DOM rows become expensive well before the DXF
// parser itself does. Keep the normal editor for small sketches, but switch to
// the indexed/batched path early enough to prevent import-time UI stalls.
const DENSE_SKETCH_ENTITY_THRESHOLD = 2048;
const DENSE_SKETCH_IMPORT_DECIMATION_THRESHOLD = 12000;

function isDenseSketchDocument(sketch = state.sketch) {
    return Boolean(sketch?.entities?.length >= DENSE_SKETCH_ENTITY_THRESHOLD);
}

function getDenseSketchEntityPoints(entity, z = 0.35) {
    if (entity?.type === 'circle') return getSketchCirclePoints(entity, z, 32);
    if (entity?.type === 'line') {
        return [entity.start, entity.end]
            .filter(Boolean)
            .map((point) => point.clone().setZ(z));
    }
    if (entity?.type === 'polyline') {
        return (entity.points || []).map((point) => point.clone().setZ(z));
    }
    return getSketchPolygonPoints(entity)
        .map((point) => new THREE.Vector3(point.x, point.y, z));
}

function appendDenseSketchEntitySegments(entity, positions) {
    const points = getDenseSketchEntityPoints(entity);
    if (points.length < 2) return;
    const closed = entity.type !== 'line' && entity.closed !== false;
    const hasRepeatedEndpoint = closed && points.length > 2
        && points[0].distanceTo(points.at(-1)) <= 1e-7;
    const edgeCount = hasRepeatedEndpoint
        ? points.length - 1
        : closed ? points.length : points.length - 1;
    for (let index = 0; index < edgeCount; index += 1) {
        const start = points[index];
        const end = points[(index + 1) % points.length];
        positions.push(
            start.x, start.y, start.z,
            end.x, end.y, end.z
        );
    }
}

function createDenseSketchPreview(entitiesGroup, sketch) {
    const positions = [];
    sketch.entities.forEach((entity) => appendDenseSketchEntitySegments(entity, positions));
    const base = new THREE.Group();
    base.name = `Dense DXF sketch · ${sketch.entities.length} entities`;
    base.userData.denseSketchBase = true;
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    const material = new THREE.LineBasicMaterial({
        color: 0xc4b5fd,
        transparent: true,
        opacity: 0.95,
        depthTest: false,
        depthWrite: false
    });
    const line = new THREE.LineSegments(geometry, material);
    line.name = `Dense DXF sketch · ${sketch.entities.length} entities · visual`;
    line.frustumCulled = false;
    line.renderOrder = 36;
    base.add(line);
    entitiesGroup.add(base);
    return base;
}

function updateDenseSketchPreview(entitiesGroup, sketch) {
    let base = entitiesGroup.children.find((child) => child.userData?.denseSketchBase) || null;
    if (!base || entitiesGroup.userData.denseSketchRevision !== sketch.previewRevision) {
        entitiesGroup.children
            .filter((child) => child !== base)
            .forEach((child) => {
                entitiesGroup.remove(child);
                disposeObjectResources(child);
            });
        if (base) {
            entitiesGroup.remove(base);
            disposeObjectResources(base);
        }
        base = createDenseSketchPreview(entitiesGroup, sketch);
        entitiesGroup.userData.denseSketchRevision = sketch.previewRevision;
    }

    const overlay = entitiesGroup.children.find((child) => child.userData?.denseSketchOverlay);
    if (overlay) {
        entitiesGroup.remove(overlay);
        disposeObjectResources(overlay);
    }
    const selectedEntities = sketch.entities.filter((entity) => (
        isSketchEntitySelected(entity.id) || entity.id === sketch.hoverEntityId
    ));
    if (!selectedEntities.length) return;
    const nextOverlay = new THREE.Group();
    nextOverlay.userData.denseSketchOverlay = true;
    selectedEntities.forEach((entity) => {
        const selected = isSketchEntitySelected(entity.id);
        const closed = entity.type !== 'line' && entity.closed !== false;
        const line = createSketchLine(selected ? 0x7dd3fc : 0xfde047, 1, closed, entity);
        setSketchLinePoints(line, getDenseSketchEntityPoints(entity));
        nextOverlay.add(line);
    });
    entitiesGroup.add(nextOverlay);
}

function updateSketchClosedLineLoopPreview(entitiesGroup, sketch, denseSketch) {
    entitiesGroup.children
        .filter((child) => child.userData?.closedLineLoopFill)
        .forEach((child) => {
            entitiesGroup.remove(child);
            disposeObjectResources(child);
        });
    if (denseSketch) return;
    const profileRegions = denseSketch ? [] : getSketchProfileRegions();
    getSketchClosedLineLoops()
        .filter((loop) => !profileRegions.some((profile) => (
            getSketchProfileSelectionIds(profile).length === getSketchProfileSelectionIds(loop).length
            && getSketchProfileSelectionIds(profile).every((id) => getSketchProfileSelectionIds(loop).includes(id))
        )))
        .filter((loop) => !denseSketch || isSketchProfileSelected(loop) || isSketchProfileHovered(loop))
        .forEach((loop) => {
            const shape = createSketchProfileShape(loop);
            if (!shape) return;
            const selected = isSketchProfileSelected(loop);
            const hovered = !selected && isSketchProfileHovered(loop);
            const fill = new THREE.Mesh(
                new THREE.ShapeGeometry(shape),
                new THREE.MeshBasicMaterial({
                    color: selected ? 0x0ea5e9 : hovered ? 0xf59e0b : 0x8b5cf6,
                    transparent: true,
                    opacity: selected ? 0.2 : hovered ? 0.16 : 0.1,
                    depthTest: false,
                    depthWrite: false,
                    side: THREE.DoubleSide,
                    toneMapped: false
                })
            );
            fill.userData.closedLineLoopFill = true;
            fill.position.z = 0.2;
            fill.renderOrder = 35;
            entitiesGroup.add(fill);
        });
}

function updateSketchPreview() {
    const sketch = state.sketch;
    const group = sketch.previewGroup;
    if (!group) return;
    group.visible = Boolean(sketch.active);
    group.position.copy(sketch.origin);
    sketch.dimensionLabels.forEach((label) => { label.hidden = true; });
    const entitiesGroup = group.userData.entitiesGroup;
    const dimensionsGroup = group.userData.dimensionsGroup;
    const snapGroup = group.userData.snapGroup;
    const denseSketch = isDenseSketchDocument(sketch);
    if (!denseSketch) disposeSketchPreviewChildren(entitiesGroup);
    disposeSketchPreviewChildren(dimensionsGroup);
    disposeSketchPreviewChildren(snapGroup);
    const z = 0.35;
    if (denseSketch) {
        updateDenseSketchPreview(entitiesGroup, sketch);
    } else {
        const profileRegions = getSketchProfileRegions();
        profileRegions.forEach((profile) => {
            const selected = isSketchProfileSelected(profile);
            const hovered = !selected && isSketchProfileHovered(profile);
            const shape = createSketchProfileShape(profile);
            if (!shape) return;
            const fill = new THREE.Mesh(
                new THREE.ShapeGeometry(shape),
                new THREE.MeshBasicMaterial({
                    color: selected ? 0x0ea5e9 : hovered ? 0xf59e0b : 0x8b5cf6,
                    transparent: true,
                    opacity: selected ? 0.2 : hovered ? 0.16 : 0.1,
                    depthTest: false,
                    depthWrite: false,
                    side: THREE.DoubleSide,
                    toneMapped: false
                })
            );
            fill.position.z = 0.2;
            fill.renderOrder = 35;
            entitiesGroup.add(fill);
        });
        sketch.entities.forEach((entity) => {
        const containingRegion = profileRegions.find((profile) => (
            profile.holeEntityIds?.includes(entity.id)
            || getSketchProfileSelectionIds(profile).includes(entity.id)
        ));
        const selected = isSketchEntitySelected(entity.id)
            || Boolean(containingRegion && isSketchProfileSelected(containingRegion));
        const hovered = entity.id === sketch.hoverEntityId;
        const color = selected ? 0x7dd3fc : hovered ? 0xfde047 : 0xc4b5fd;
        const closed = entity.type !== 'line' && entity.closed !== false;
        const outline = createSketchLine(color, 0.95, closed, entity);
        const points = entity.type === 'circle'
            ? getSketchCirclePoints(entity, z)
            : closed
                ? getSketchPolygonPoints(entity).map((point) => new THREE.Vector3(point.x, point.y, z))
            : entity.type === 'line'
                ? [entity.start.clone().setZ(z), entity.end.clone().setZ(z)]
                : (entity.points || []).map((point) => point.clone().setZ(z));
        setSketchLinePoints(outline, points);
        outline.userData.sketchEntityId = entity.id;
        entitiesGroup.add(outline);
        });
    }
    updateSketchClosedLineLoopPreview(entitiesGroup, sketch, denseSketch);
    let previewEntity = null;
    if (sketch.startPoint && sketch.endPoint) {
        const previewPoints = sketch.activeTool === 'rectangle'
            ? getSketchRectangleDrawingPoints(sketch.startPoint, sketch.endPoint)
            : { start: sketch.startPoint, end: sketch.endPoint };
        previewEntity = normalizeSketchEntityRecord({
            id: 'preview',
            type: sketch.activeTool,
            start: previewPoints.start.toArray(),
            end: previewPoints.end.toArray(),
            center: sketch.startPoint.toArray(),
            radius: getSketchCircleRadiusFromDrag(sketch.startPoint, sketch.endPoint),
            chamfer: Number(el.sketchChamferDistance?.value) || sketch.chamferDistance
        });
        if (previewEntity) {
            const outline = createSketchLine(0xf5d0fe, 0.95, previewEntity.type !== 'line');
            const points = previewEntity.type === 'circle'
                ? getSketchCirclePoints(previewEntity, z)
                : previewEntity.type === 'line'
                    ? [previewEntity.start.clone().setZ(z), previewEntity.end.clone().setZ(z)]
                    : getSketchPolygonPoints(previewEntity).map((point) => new THREE.Vector3(point.x, point.y, z));
            setSketchLinePoints(outline, points);
            entitiesGroup.add(outline);
        }
    }
    renderSketchDimensionHover(dimensionsGroup);
    renderSketchDimensionAnnotations(dimensionsGroup);
    renderSketchSnapIndicators(snapGroup);
    const entity = sketch.phase === 'drawing' ? previewEntity : getSketchEntity();
    if (!entity) return;
    const formatDimensionValue = sketch.phase === 'drawing'
        ? formatSketchPreviewDimensionValue
        : formatJogValue;
    const dimensions = getSketchEntityDimensions(entity);
    if (entity.type === 'circle') {
        const diameterStart = new THREE.Vector3(entity.center.x - entity.radius, entity.center.y, z);
        const diameterEnd = new THREE.Vector3(entity.center.x + entity.radius, entity.center.y, z);
        showSketchDimensionLabel('x', `${formatDimensionValue(dimensions.x)}`, new THREE.Vector3(entity.center.x, entity.center.y, z));
        addSketchDimensionLine(
            dimensionsGroup,
            diameterStart,
            diameterEnd,
            SKETCH_DIMENSION_GREEN,
            0.82,
            {
                z: z + 0.03,
                arrowSizePixels: 7,
                labelGapPixels: getSketchDimensionLabelGapPixels(sketch.dimensionLabels.get('x'))
            }
        );
    } else if (entity.type === 'line') {
        const midpoint = entity.start.clone().add(entity.end).multiplyScalar(0.5).setZ(z);
        showSketchDimensionLabel('x', `${formatDimensionValue(dimensions.x)}`, midpoint);
        addSketchDimensionLine(
            dimensionsGroup,
            entity.start.clone().setZ(z),
            entity.end.clone().setZ(z),
            SKETCH_DIMENSION_GREEN,
            0.82,
            {
                z: z + 0.03,
                arrowSizePixels: 7,
                arrows: false,
                labelGapPixels: getSketchDimensionLabelGapPixels(sketch.dimensionLabels.get('x'))
            }
        );
    } else if (entity.type === 'polyline') {
        const points = entity.points || [];
        if (!points.length) return;
        const minX = Math.min(...points.map((point) => point.x));
        const maxX = Math.max(...points.map((point) => point.x));
        const minY = Math.min(...points.map((point) => point.y));
        const maxY = Math.max(...points.map((point) => point.y));
        showSketchDimensionLabel(
            'x',
            `${formatDimensionValue(dimensions.x)} · ${formatDimensionValue(dimensions.y)}`,
            new THREE.Vector3((minX + maxX) * 0.5, minY - 18, z)
        );
    } else {
        const minX = Math.min(entity.start.x, entity.end.x);
        const maxX = Math.max(entity.start.x, entity.end.x);
        const minY = Math.min(entity.start.y, entity.end.y);
        const maxY = Math.max(entity.start.y, entity.end.y);
        const centerX = (minX + maxX) * 0.5;
        const centerY = (minY + maxY) * 0.5;
        const xOffset = Math.max(12, Math.min(36, (maxY - minY) * 0.15));
        const yOffset = Math.max(12, Math.min(36, (maxX - minX) * 0.15));
        const xDimensionY = minY - xOffset;
        const yDimensionX = minX - yOffset;
        const xExtensionStart = createSketchLine(SKETCH_DIMENSION_GREEN, 0.82);
        const xExtensionEnd = createSketchLine(SKETCH_DIMENSION_GREEN, 0.82);
        const yExtensionStart = createSketchLine(SKETCH_DIMENSION_GREEN, 0.82);
        const yExtensionEnd = createSketchLine(SKETCH_DIMENSION_GREEN, 0.82);
        setSketchLinePoints(xExtensionStart, [
            new THREE.Vector3(minX, minY, z), new THREE.Vector3(minX, xDimensionY, z)
        ]);
        setSketchLinePoints(xExtensionEnd, [
            new THREE.Vector3(maxX, minY, z), new THREE.Vector3(maxX, xDimensionY, z)
        ]);
        setSketchLinePoints(yExtensionStart, [
            new THREE.Vector3(minX, minY, z), new THREE.Vector3(yDimensionX, minY, z)
        ]);
        setSketchLinePoints(yExtensionEnd, [
            new THREE.Vector3(minX, maxY, z), new THREE.Vector3(yDimensionX, maxY, z)
        ]);
        dimensionsGroup.add(xExtensionStart, xExtensionEnd, yExtensionStart, yExtensionEnd);
        showSketchDimensionLabel('x', `${formatDimensionValue(dimensions.x)}`, new THREE.Vector3(centerX, xDimensionY, z));
        showSketchDimensionLabel('y', `${formatDimensionValue(dimensions.y)}`, new THREE.Vector3(yDimensionX, centerY, z));
        addSketchDimensionLine(
            dimensionsGroup,
            new THREE.Vector3(minX, xDimensionY, z),
            new THREE.Vector3(maxX, xDimensionY, z),
            SKETCH_DIMENSION_GREEN,
            0.82,
            {
                z: z + 0.03,
                arrowSizePixels: 7,
                labelGapPixels: getSketchDimensionLabelGapPixels(sketch.dimensionLabels.get('x'))
            }
        );
        addSketchDimensionLine(
            dimensionsGroup,
            new THREE.Vector3(yDimensionX, minY, z),
            new THREE.Vector3(yDimensionX, maxY, z),
            SKETCH_DIMENSION_GREEN,
            0.82,
            {
                z: z + 0.03,
                arrowSizePixels: 7,
                labelGapPixels: getSketchDimensionLabelGapPixels(sketch.dimensionLabels.get('y'))
            }
        );
        if (entity.type === 'chamfer' && entity.chamfer > 0) {
            showSketchDimensionLabel('chamfer', `C = ${formatJogValue(entity.chamfer)}`, new THREE.Vector3(maxX - entity.chamfer, maxY - entity.chamfer, z));
        }
    }
}

function updateSketchDimension(axis, rawValue, { entityId = null } = {}) {
    const entity = entityId
        ? state.sketch.entities.find((candidate) => candidate.id === entityId)
        : getSketchEntity();
    const value = Number(rawValue);
    if (!entity || !Number.isFinite(value) || value < SKETCH_MIN_SIZE || value > SKETCH_MAX_SIZE) return false;
    if (entity.type === 'circle' && (axis === 'x' || axis === 'diameter')) {
        entity.radius = value / 2;
    } else if (entity.type === 'line' && (axis === 'x' || axis === 'length')) {
        const direction = entity.end.clone().sub(entity.start).normalize();
        if (!Number.isFinite(direction.x) || direction.lengthSq() < 1e-12) return false;
        entity.end.copy(entity.start).add(direction.multiplyScalar(value));
    } else if (['rectangle', 'chamfer'].includes(entity.type) && ['x', 'y'].includes(axis)) {
        const targetAxis = axis;
        const direction = Math.sign(entity.end[targetAxis] - entity.start[targetAxis]) || 1;
        entity.end[targetAxis] = entity.start[targetAxis] + direction * value;
        if (entity.type === 'chamfer') {
            entity.chamfer = THREE.MathUtils.clamp(entity.chamfer, 0, Math.min(
                Math.abs(entity.end.x - entity.start.x), Math.abs(entity.end.y - entity.start.y)
            ) * 0.49);
        }
    } else return false;
    syncSketchDocumentEntities();
    updateSketchPreview();
    renderSketchEditorUi();
    requestRender();
    return true;
}

function updateSketchChamfer(rawValue, { entityId = null } = {}) {
    const entity = entityId
        ? state.sketch.entities.find((candidate) => candidate.id === entityId)
        : getSketchEntity();
    const value = Number(rawValue);
    if (!entity || entity.type !== 'chamfer' || !Number.isFinite(value) || value < 0 || value > SKETCH_MAX_SIZE) return false;
    const max = Math.min(Math.abs(entity.end.x - entity.start.x), Math.abs(entity.end.y - entity.start.y)) * 0.49;
    entity.chamfer = THREE.MathUtils.clamp(value, 0, max);
    state.sketch.chamferDistance = entity.chamfer;
    syncSketchDocumentEntities();
    updateSketchPreview();
    renderSketchEditorUi();
    requestRender();
    return true;
}

function finishSketchDimensionEdit(apply) {
    const edit = state.sketch.dimensionEditing;
    if (!edit) return;
    state.sketch.dimensionEditing = null;
    const entityIndex = state.sketch.entities.findIndex((candidate) => candidate.id === edit.entityId);
    let valid = false;
    if (!apply || entityIndex < 0) {
        if (entityIndex >= 0) state.sketch.entities[entityIndex] = normalizeSketchEntityRecord(edit.before);
    } else {
        valid = edit.axis === 'chamfer'
            ? updateSketchChamfer(edit.input.value, { entityId: edit.entityId })
            : updateSketchDimension(edit.axis, edit.input.value, { entityId: edit.entityId });
        if (!valid) state.sketch.entities[entityIndex] = normalizeSketchEntityRecord(edit.before);
    }
    syncSketchDocumentEntities();
    if (valid) recordSketchHistory('스케치 치수 변경', edit.historyBefore);
    updateSketchPreview();
    renderSketchEditorUi();
    requestRender();
}

function beginSketchDimensionEdit(axis) {
    const sketch = state.sketch;
    const entity = getSketchEntity();
    const label = sketch.dimensionLabels.get(axis);
    if (!sketch.active || sketch.phase === 'drawing' || !entity || !label || sketch.dimensionEditing) return;
    const dimensions = getSketchEntityDimensions(entity);
    const isChamfer = axis === 'chamfer';
    const current = isChamfer ? entity.chamfer : axis === 'y' ? dimensions?.y : dimensions?.x;
    if (!Number.isFinite(current)) return;
    const input = document.createElement('input');
    input.type = 'number';
    input.min = String(isChamfer ? 0 : SKETCH_MIN_SIZE);
    input.max = String(SKETCH_MAX_SIZE);
    input.step = '0.5';
    input.value = formatJogValue(current);
    sketch.dimensionEditing = {
        axis,
        entityId: entity.id,
        input,
        before: serializeSketchEntity(entity),
        historyBefore: captureSketchEditSnapshot()
    };
    label.replaceChildren(input);
    input.addEventListener('input', () => isChamfer ? updateSketchChamfer(input.value) : updateSketchDimension(axis, input.value));
    input.addEventListener('keydown', (event) => {
        event.stopPropagation();
        if (event.key === 'Enter') {
            event.preventDefault();
            finishSketchDimensionEdit(true);
        } else if (event.key === 'Escape') {
            event.preventDefault();
            finishSketchDimensionEdit(false);
        }
    });
    input.addEventListener('blur', () => finishSketchDimensionEdit(true));
    input.addEventListener('pointerdown', (event) => event.stopPropagation());
    input.focus({ preventScroll: true });
    input.select();
}

function getSketchSnapCandidateLabel(candidate) {
    if (!candidate) return '';
    if (candidate.type === 'origin') return uiText('0,0 영점 위치');
    if (candidate.type === 'robot-body-center') return uiText('로봇 바디 중심점');
    if (candidate.type === 'robot-tcp') return uiText('현재 TCP (점)');
    if (candidate.type === 'endpoint') return uiText('끝점');
    if (candidate.type === 'vertex') return uiText('꼭짓점');
    if (candidate.type === 'midpoint') return uiText('중점');
    if (candidate.type === 'quadrant') return uiText('원주점');
    if (candidate.type === 'hole-center') return uiText('구멍 가상 중심점');
    if (candidate.type === 'center') {
        const entity = candidate.entityId
            ? state.sketch.entities.find((entry) => entry.id === candidate.entityId)
            : null;
        return uiText(entity?.type === 'circle' ? '원 중심점' : '도형 중심점');
    }
    if (candidate.type === 'model-edge') return uiText('모델 파츠 선');
    return uiText('스냅점');
}

function addSketchSnapCandidate(candidates, point, type, entityId = null, reference = null) {
    if (!point?.isVector3 || !Number.isFinite(point.x) || !Number.isFinite(point.y)) return;
    candidates.push({
        point: point.clone(),
        type,
        entityId,
        label: getSketchSnapCandidateLabel({ type, entityId }),
        reference: normalizeSketchReference(reference || { kind: type, entityId })
    });
}

function getSketchEntityCenterPoint(entity) {
    if (!entity) return null;
    if (entity.type === 'circle' && entity.center?.isVector3) return entity.center.clone();
    const rawPoints = entity.type === 'line'
        ? [entity.start, entity.end]
        : entity.type === 'polyline'
            ? entity.points || []
            : getSketchPolygonPoints(entity).map((point) => new THREE.Vector3(point.x, point.y, 0));
    const points = rawPoints.filter((point) => (
        point?.isVector3 && Number.isFinite(point.x) && Number.isFinite(point.y)
    ));
    if (!points.length) return null;
    const bounds = points.reduce((result, point) => ({
        minX: Math.min(result.minX, point.x),
        maxX: Math.max(result.maxX, point.x),
        minY: Math.min(result.minY, point.y),
        maxY: Math.max(result.maxY, point.y)
    }), { minX: Infinity, maxX: -Infinity, minY: Infinity, maxY: -Infinity });
    return new THREE.Vector3(
        (bounds.minX + bounds.maxX) * 0.5,
        (bounds.minY + bounds.maxY) * 0.5,
        0
    );
}

function getSketchExternalSnapCandidates() {
    const candidates = [];
    addSketchSnapCandidate(candidates, new THREE.Vector3(), 'origin', null, {
        kind: 'origin',
        point: [0, 0, 0]
    });
    // In the sketch workbench the robot body's CAD reference is its fixed
    // model root, not a triangle-derived point on the P0 mesh. This keeps the
    // body-center snap stable when the model is rotated, when the base mesh is
    // hidden behind another part, and while the generic 3D snap cache is being
    // rebuilt. It also intentionally allows the body center to overlap the
    // sketch origin, so the readout can identify both references together.
    const sketchRobots = typeof getArticulatedRobots === 'function'
        ? getArticulatedRobots()
        : [];
    if (sketchRobots.length) {
        sketchRobots.forEach((robot) => {
            if (!robot?.userData?.tcpFrame || robot.visible === false) return;
            robot.updateWorldMatrix?.(true, false);
            const worldPoint = new THREE.Vector3().setFromMatrixPosition(robot.matrixWorld);
            const sketchPoint = worldPoint.sub(state.sketch.origin).setZ(0);
            addSketchSnapCandidate(candidates, sketchPoint, 'robot-body-center', null, {
                kind: 'external',
                point: sketchPoint.toArray()
            });
            const tcpFrame = robot.userData.tcpFrame;
            if (tcpFrame.visible === false) return;
            tcpFrame.updateWorldMatrix?.(true, false);
            const tcpWorldPoint = new THREE.Vector3().setFromMatrixPosition(tcpFrame.matrixWorld);
            const tcpSketchPoint = tcpWorldPoint.sub(state.sketch.origin).setZ(0);
            addSketchSnapCandidate(candidates, tcpSketchPoint, 'robot-tcp', null, {
                kind: 'external',
                point: tcpSketchPoint.toArray()
            });
        });
    } else if (typeof getSimulationSnapRobotBodyCenterCandidates === 'function') {
        // Keep compatibility with the shared snap provider for a scene whose
        // articulated model list is temporarily unavailable during loading.
        getSimulationSnapRobotBodyCenterCandidates('scene').forEach((candidate) => {
            if (!candidate?.mesh || !candidate.localPoint?.isVector3) return;
            candidate.mesh.updateWorldMatrix?.(true, false);
            const worldPoint = candidate.localPoint.clone().applyMatrix4(candidate.mesh.matrixWorld);
            const sketchPoint = worldPoint.sub(state.sketch.origin).setZ(0);
            addSketchSnapCandidate(candidates, sketchPoint, 'robot-body-center', null, {
                kind: 'external',
                point: sketchPoint.toArray()
            });
        });
    }
    return candidates;
}

function getSketchExternalSnapCandidateType(type) {
    if (type === 'endpoint' || type === 'vertex') return type;
    if (type === 'edge-midpoint') return 'midpoint';
    if (type === 'hole-center') return 'hole-center';
    if (type === 'circle-center'
        || type === 'rectangle-center'
        || type === 'face-center'
        || type === 'shape-center') return 'center';
    return 'vertex';
}

function getSketchExternalSnapMeshesSignature(meshes) {
    const origin = state.sketch.origin;
    const originSignature = [origin.x, origin.y, origin.z].map((value) => Number(value).toFixed(4)).join(',');
    const meshSignature = meshes.map((mesh) => {
        mesh.updateWorldMatrix?.(true, false);
        const matrixSignature = mesh.matrixWorld?.elements?.map((value) => Number(value).toFixed(4)).join(',') || '';
        return `${mesh.uuid}:${mesh.geometry?.uuid || ''}:${matrixSignature}`;
    }).join('|');
    return `${originSignature}|${meshSignature}`;
}

function buildSketchExternalSnapCandidates(meshes, signature) {
    const sketch = state.sketch;
    if (sketch.externalSnapCandidatesPromise
        && sketch.externalSnapCandidatesBuildSignature === signature) return;
    sketch.externalSnapCandidatesBuildSignature = signature;
    const sketchOrigin = sketch.origin.clone();
    let promise;
    promise = (async () => {
        const candidates = [];
        const seen = new Set();
        for (let index = 0; index < meshes.length; index += 1) {
            if (!sketch.active || sketch.externalSnapCandidatesBuildSignature !== signature) return;
            const mesh = meshes[index];
            mesh.updateWorldMatrix?.(true, false);
            try {
                const result = buildSimulationSnapResultForMesh(mesh, true);
                (result?.candidates || []).forEach((candidate) => {
                    const localPoint = candidate?.point;
                    if (!Array.isArray(localPoint) || localPoint.length !== 3) return;
                    const worldPoint = new THREE.Vector3().fromArray(localPoint).applyMatrix4(mesh.matrixWorld);
                    const sketchPoint = worldPoint.sub(sketchOrigin).setZ(0);
                    const type = getSketchExternalSnapCandidateType(candidate.type);
                    const key = `${type}:${sketchPoint.x.toFixed(4)},${sketchPoint.y.toFixed(4)}`;
                    if (seen.has(key)) return;
                    seen.add(key);
                    addSketchSnapCandidate(candidates, sketchPoint, type, null, {
                        kind: 'external',
                        point: sketchPoint.toArray(),
                        sourceType: candidate.type
                    });
                });
            } catch (error) {
                console.warn('Sketch external snap candidate generation failed:', mesh.name, error);
            }
            if (index + 1 < meshes.length) await yieldToAnimationFrame();
        }
        if (!sketch.active || sketch.externalSnapCandidatesBuildSignature !== signature) return;
        sketch.externalSnapCandidatesCache = candidates;
        sketch.externalSnapCandidatesSignature = signature;
        if (sketch.hoverPoint) {
            const refreshedSnap = getSketchSnappedPoint(sketch.hoverPoint);
            sketch.snapCandidate = refreshedSnap.candidate;
        }
        updateSketchPreview();
        requestRender();
    })().catch((error) => {
        if (sketch.active && sketch.externalSnapCandidatesBuildSignature === signature) {
            sketch.externalSnapCandidatesCache = [];
            sketch.externalSnapCandidatesSignature = signature;
        }
        console.warn('Sketch external snap candidate build failed:', error);
    }).finally(() => {
        if (sketch.externalSnapCandidatesPromise === promise) {
            sketch.externalSnapCandidatesPromise = null;
        }
    });
    sketch.externalSnapCandidatesPromise = promise;
}

function getSketchExternalMeshSnapCandidates() {
    const sketch = state.sketch;
    if (!sketch.active || sketch.snapMode) return [];
    const meshes = typeof getSimulationSnapMeshes === 'function'
        ? getSimulationSnapMeshes('scene')
        : [];
    const signature = getSketchExternalSnapMeshesSignature(meshes);
    if (sketch.externalSnapCandidatesCache
        && sketch.externalSnapCandidatesSignature === signature) {
        return sketch.externalSnapCandidatesCache;
    }
    buildSketchExternalSnapCandidates(meshes, signature);
    return [];
}

function getSketchSnapCandidates() {
    const candidates = getSketchExternalSnapCandidates()
        .concat(getSketchExternalMeshSnapCandidates());
    const denseSketch = isDenseSketchDocument(state.sketch);
    if (denseSketch && state.sketch.snapCandidatesCache
        && state.sketch.snapCandidatesRevision === state.sketch.previewRevision) {
        return candidates.concat(state.sketch.snapCandidatesCache);
    }
    const entityCandidateStart = candidates.length;
    state.sketch.entities.forEach((entity) => {
        if (entity.type === 'circle' && entity.center) {
            addSketchSnapCandidate(candidates, entity.center, 'center', entity.id, {
                kind: 'center',
                entityId: entity.id
            });
            for (let index = 0; index < 8; index += 1) {
                const angle = (index / 8) * Math.PI * 2;
                addSketchSnapCandidate(candidates, entity.center.clone().add(new THREE.Vector3(
                    Math.cos(angle) * entity.radius,
                    Math.sin(angle) * entity.radius,
                    0
                )), 'quadrant', entity.id, {
                    kind: 'circle-point',
                    entityId: entity.id,
                    angle
                });
            }
            return;
        }
        const center = getSketchEntityCenterPoint(entity);
        if (center) {
            addSketchSnapCandidate(candidates, center, 'center', entity.id, {
                kind: 'center',
                entityId: entity.id
            });
        }
        const points = entity.type === 'line'
            ? [entity.start, entity.end]
            : entity.type === 'polyline'
                ? entity.points || []
                : getSketchPolygonPoints(entity).map((point) => new THREE.Vector3(point.x, point.y, 0));
        points.forEach((point, index) => addSketchSnapCandidate(candidates, point, entity.type === 'polyline' ? 'vertex' : 'endpoint', entity.id, {
            kind: entity.type === 'polyline' ? 'vertex' : 'endpoint',
            entityId: entity.id,
            pointIndex: index
        }));
        for (let index = 1; index < points.length; index += 1) {
            addSketchSnapCandidate(candidates, points[index - 1].clone().add(points[index]).multiplyScalar(0.5), 'midpoint', entity.id, {
                kind: 'midpoint',
                entityId: entity.id,
                segmentIndex: index - 1
            });
        }
        if (points.length > 2 && entity.closed !== false) {
            addSketchSnapCandidate(candidates, points.at(-1).clone().add(points[0]).multiplyScalar(0.5), 'midpoint', entity.id, {
                kind: 'midpoint',
                entityId: entity.id,
                segmentIndex: points.length - 1
            });
        }
    });
    if (denseSketch) {
        state.sketch.snapCandidatesCache = candidates.slice(entityCandidateStart);
        state.sketch.snapCandidatesRevision = state.sketch.previewRevision;
    }
    return candidates;
}

function getSketchModelEdgeSnapCandidate(event) {
    const sketch = state.sketch;
    const canvas = state.renderer?.domElement;
    const rect = canvas?.getBoundingClientRect?.();
    if (!event || !canvas || !rect || rect.width <= 0 || rect.height <= 0
        || sketch.snapEnabled === false || sketch.snapMode) return null;
    const meshes = getAllSimulationSnapMeshes('scene').filter((mesh) => (
        mesh?.isMesh
        && !isSimulationSnapRobotMesh(mesh)
        && mesh.visible !== false
        && mesh.geometry?.getAttribute?.('position')
    ));
    if (!meshes.length) return null;
    const pointer = new THREE.Vector2(
        ((event.clientX - rect.left) / rect.width) * 2 - 1,
        -((event.clientY - rect.top) / rect.height) * 2 + 1
    );
    const raycaster = new THREE.Raycaster();
    raycaster.setFromCamera(pointer, state.camera);
    const hit = raycaster.intersectObjects(meshes, false)[0];
    if (!hit?.object || !Number.isInteger(hit.faceIndex) || !hit.point?.isVector3) return null;
    const geometry = hit.object.geometry;
    const position = geometry.getAttribute('position');
    const index = geometry.index?.array;
    const triangleStart = hit.faceIndex * 3;
    const vertexIndices = index
        ? [index[triangleStart], index[triangleStart + 1], index[triangleStart + 2]]
        : [triangleStart, triangleStart + 1, triangleStart + 2];
    if (vertexIndices.some((vertexIndex) => !Number.isInteger(vertexIndex))) return null;
    hit.object.updateWorldMatrix?.(true, false);
    const worldVertices = vertexIndices.map((vertexIndex) => (
        new THREE.Vector3().fromBufferAttribute(position, vertexIndex).applyMatrix4(hit.object.matrixWorld)
    ));
    let closestPoint = null;
    let closestDistance = Infinity;
    for (let index = 0; index < worldVertices.length; index += 1) {
        const start = worldVertices[index];
        const end = worldVertices[(index + 1) % worldVertices.length];
        const candidate = new THREE.Line3(start, end).closestPointToPoint(hit.point, true, new THREE.Vector3());
        const distance = candidate.distanceTo(hit.point);
        if (distance < closestDistance) {
            closestDistance = distance;
            closestPoint = candidate;
        }
    }
    if (!closestPoint) return null;
    const projected = closestPoint.clone().project(state.camera);
    const screenX = (projected.x * 0.5 + 0.5) * rect.width;
    const screenY = (-projected.y * 0.5 + 0.5) * rect.height;
    const pointerX = event.clientX - rect.left;
    const pointerY = event.clientY - rect.top;
    if (!Number.isFinite(screenX) || !Number.isFinite(screenY)
        || Math.hypot(screenX - pointerX, screenY - pointerY) > 9) return null;
    const sketchPoint = closestPoint.clone().sub(sketch.origin).setZ(0);
    return {
        point: sketchPoint,
        type: 'model-edge',
        entityId: null,
        label: getSketchSnapCandidateLabel({ type: 'model-edge' }),
        reference: normalizeSketchReference({
            kind: 'model-edge',
            point: sketchPoint.toArray()
        })
    };
}

function getSketchSnappedPoint(point, event = null) {
    const sketch = state.sketch;
    if (!point) return { point: null, candidate: null };
    if (sketch.snapEnabled === false) return { point: point.clone(), candidate: null };
    const candidates = getSketchSnapCandidates();
    const modelEdgeCandidate = getSketchModelEdgeSnapCandidate(event);
    if (modelEdgeCandidate) candidates.push(modelEdgeCandidate);
    let nearest = null;
    let nearestDistance = Infinity;
    candidates.forEach((candidate) => {
        const distance = candidate.point.distanceTo(point);
        if (distance < nearestDistance) {
            nearest = candidate;
            nearestDistance = distance;
        }
    });
    if (nearest && nearestDistance <= SKETCH_SNAP_TOLERANCE) {
        const overlappingLabels = candidates
            .filter((candidate) => candidate.point.distanceTo(nearest.point) <= 1e-5)
            .map((candidate) => candidate.label || getSketchSnapCandidateLabel(candidate))
            .filter(Boolean);
        const label = [...new Set(overlappingLabels)].join(' · ');
        return {
            point: nearest.point.clone(),
            candidate: label && label !== nearest.label ? { ...nearest, label } : nearest
        };
    }
    return { point: point.clone(), candidate: null };
}

function setSketchSnapEnabled(enabled, { announce = true } = {}) {
    const sketch = state.sketch;
    if (!sketch.active) return false;
    sketch.snapEnabled = Boolean(enabled);
    sketch.snapCandidate = null;
    syncSketchDocumentEntities();
    renderSketchEditorUi();
    updateSketchPreview();
    if (announce) setStatus(uiText(sketch.snapEnabled ? '스냅을 켰습니다.' : '스냅을 껐습니다.'), '#60a5fa');
    requestRender();
    return true;
}

function getSketchEntityEdgeSegments(entity) {
    if (!entity) return [];
    if (entity.type === 'circle' && entity.center) return [];
    const rawPoints = entity.type === 'line'
        ? [entity.start, entity.end]
        : entity.type === 'polyline'
            ? (entity.points || [])
            : getSketchPolygonPoints(entity).map((point) => new THREE.Vector3(point.x, point.y, 0));
    const points = rawPoints.filter(Boolean).map((point) => point.clone());
    if (points.length < 2) return [];
    const segments = [];
    const closed = entity.type !== 'line' && (entity.type !== 'polyline' || entity.closed !== false);
    const count = closed && points.length > 2 && points.at(-1).distanceTo(points[0]) < 1e-8
        ? points.length - 1
        : points.length;
    for (let index = 0; index < count - 1; index += 1) {
        segments.push({
            index,
            start: points[index].clone(),
            end: points[index + 1].clone()
        });
    }
    if (closed && count > 2) {
        segments.push({ index: count - 1, start: points[count - 1].clone(), end: points[0].clone() });
    }
    return segments;
}

function getSketchReferenceEntity(reference) {
    if (!reference?.entityId) return null;
    return state.sketch.entities.find((entity) => entity.id === reference.entityId) || null;
}

function getSketchReferencePoint(reference) {
    if (!reference) return null;
    const storedPoint = sketchVector(reference.point);
    const entity = getSketchReferenceEntity(reference);
    if (!entity) return storedPoint;
    if (reference.kind === 'center') {
        if (entity.center) return entity.center.clone();
        if (entity.type === 'line' && entity.start && entity.end) {
            return entity.start.clone().add(entity.end).multiplyScalar(0.5);
        }
        const points = entity.type === 'polyline'
            ? (entity.points || [])
            : getSketchPolygonPoints(entity).map((point) => new THREE.Vector3(point.x, point.y, 0));
        if (points.length) {
            const bounds = points.reduce((result, point) => ({
                minX: Math.min(result.minX, point.x),
                maxX: Math.max(result.maxX, point.x),
                minY: Math.min(result.minY, point.y),
                maxY: Math.max(result.maxY, point.y)
            }), { minX: Infinity, maxX: -Infinity, minY: Infinity, maxY: -Infinity });
            return new THREE.Vector3(
                (bounds.minX + bounds.maxX) * 0.5,
                (bounds.minY + bounds.maxY) * 0.5,
                0
            );
        }
    }
    if (reference.kind === 'circle-point' && entity.center && Number.isFinite(reference.angle)) {
        return entity.center.clone().add(new THREE.Vector3(
            Math.cos(reference.angle) * entity.radius,
            Math.sin(reference.angle) * entity.radius,
            0
        ));
    }
    if (reference.kind === 'midpoint') {
        const segment = getSketchEntityEdgeSegments(entity).find(({ index }) => index === reference.segmentIndex);
        return segment ? segment.start.clone().add(segment.end).multiplyScalar(0.5) : storedPoint;
    }
    if (reference.kind === 'line-point') {
        const segment = getSketchEntityEdgeSegments(entity).find(({ index }) => index === reference.segmentIndex);
        if (!segment) return storedPoint;
        const ratio = Number.isFinite(reference.ratio) ? reference.ratio : 0.5;
        return segment.start.clone().lerp(segment.end, ratio);
    }
    if (['endpoint', 'vertex'].includes(reference.kind)) {
        if (entity.type === 'line') return entity[reference.pointIndex === 0 ? 'start' : 'end']?.clone() || storedPoint;
        if (entity.type === 'polyline') return entity.points[reference.pointIndex]?.clone() || storedPoint;
        const points = getSketchPolygonPoints(entity).map((point) => new THREE.Vector3(point.x, point.y, 0));
        return points[reference.pointIndex]?.clone() || storedPoint;
    }
    return storedPoint;
}

function setSketchEntityBounds(entity, minX, maxX, minY, maxY) {
    if (!entity?.start || !entity?.end) return false;
    const signX = Math.sign(entity.end.x - entity.start.x) || 1;
    const signY = Math.sign(entity.end.y - entity.start.y) || 1;
    entity.start.x = signX > 0 ? minX : maxX;
    entity.end.x = signX > 0 ? maxX : minX;
    entity.start.y = signY > 0 ? minY : maxY;
    entity.end.y = signY > 0 ? maxY : minY;
    if (entity.type === 'chamfer') {
        entity.chamfer = THREE.MathUtils.clamp(
            entity.chamfer,
            0,
            Math.min(Math.abs(maxX - minX), Math.abs(maxY - minY)) * 0.49
        );
    }
    return true;
}

function moveSketchReference(reference, targetPoint) {
    const entity = getSketchReferenceEntity(reference);
    if (!entity || !targetPoint) return false;
    const current = getSketchReferencePoint(reference);
    if (!current) return false;
    if (reference.kind === 'center'
        || reference.kind === 'circle-point'
        || reference.kind === 'midpoint'
        || reference.kind === 'line-point') {
        translateSketchEntityInPlace(entity, targetPoint.clone().sub(current));
        return true;
    }
    if (['rectangle', 'chamfer'].includes(entity.type) && ['endpoint', 'vertex'].includes(reference.kind)) {
        // A position dimension controls where a closed shape is located. Move
        // the whole shape so its existing width, height, and chamfer remain unchanged.
        translateSketchEntityInPlace(entity, targetPoint.clone().sub(current));
        return true;
    }
    if (entity.type === 'line' && reference.kind === 'endpoint') {
        entity[reference.pointIndex === 0 ? 'start' : 'end'].copy(targetPoint);
        return true;
    }
    if (entity.type === 'polyline' && reference.kind === 'vertex') {
        if (!entity.points[reference.pointIndex]) return false;
        entity.points[reference.pointIndex].copy(targetPoint);
        return true;
    }
    return false;
}

function getSketchHitToleranceWorld(pixelTolerance = 10) {
    return Math.max(8, getSketchWorldUnitsPerPixel() * pixelTolerance);
}

function getSketchDimensionTargetAtPoint(point, tolerance = getSketchHitToleranceWorld(12)) {
    if (!point) return null;
    let nearest = null;
    getSketchEntitiesNearPoint(point, tolerance).forEach(({ entity }) => {
        if (entity.type === 'circle' && entity.center) {
            const distance = Math.abs(point.distanceTo(entity.center) - entity.radius);
            if (distance <= tolerance && (!nearest || distance < nearest.distance)) {
                nearest = {
                    entity,
                    distance,
                    targetType: 'diameter',
                    axis: 'x',
                    edgeIndex: null,
                    start: entity.center.clone().add(new THREE.Vector3(-entity.radius, 0, 0)),
                    end: entity.center.clone().add(new THREE.Vector3(entity.radius, 0, 0))
                };
            }
            return;
        }
        getSketchEntityEdgeSegments(entity).forEach((segment) => {
            const distance = distanceToSketchSegment(point, segment.start, segment.end);
            if (distance > tolerance || (nearest && distance >= nearest.distance)) return;
            const delta = segment.end.clone().sub(segment.start);
            nearest = {
                entity,
                distance,
                targetType: 'length',
                axis: Math.abs(delta.x) >= Math.abs(delta.y) ? 'x' : 'y',
                edgeIndex: segment.index,
                start: segment.start,
                end: segment.end
            };
        });
    });
    return nearest;
}

function isSketchDimensionPointIntent(candidate) {
    return Boolean(candidate && [
        'origin', 'robot-body-center', 'model-edge', 'center', 'endpoint', 'vertex', 'quadrant'
    ].includes(candidate.type));
}

function isSketchDimensionReferenceIntent(candidate) {
    return Boolean(candidate?.reference && [
        'origin', 'robot-body-center', 'model-edge', 'center', 'endpoint', 'midpoint', 'vertex', 'quadrant', 'line-point'
    ].includes(candidate.type));
}

function getSketchDimensionLinePointAtAnchor(segment, anchorPoint) {
    if (!segment) return null;
    const delta = segment.end.clone().sub(segment.start);
    const lengthSquared = delta.lengthSq();
    const ratio = anchorPoint && lengthSquared > 1e-8
        // Use the infinite line projection. A point outside the segment still
        // needs to define the dimension's horizontal/vertical extension line;
        // clamping here incorrectly falls back to an endpoint or midpoint.
        ? anchorPoint.clone().sub(segment.start).dot(delta) / lengthSquared
        : 0.5;
    return {
        point: segment.start.clone().lerp(segment.end, ratio),
        ratio
    };
}

function getSketchDimensionPositionReference(dimension, anchorPoint = null) {
    if (!dimension?.entityId || !['length', 'diameter'].includes(dimension.type)) return null;
    const entity = state.sketch.entities.find((candidate) => candidate.id === dimension.entityId);
    if (!entity) return null;
    if (dimension.type === 'diameter' || entity.type === 'circle') {
        const point = entity.center?.clone();
        return point
            ? normalizeSketchReference({ kind: 'center', entityId: entity.id, point: point.toArray() })
            : null;
    }
    const edgeIndex = Number.isInteger(dimension.edgeIndex) ? dimension.edgeIndex : 0;
    const segment = getSketchEntityEdgeSegments(entity).find(({ index }) => index === edgeIndex);
    if (!segment) return null;
    const linePoint = getSketchDimensionLinePointAtAnchor(segment, anchorPoint);
    return normalizeSketchReference({
        kind: linePoint && anchorPoint ? 'line-point' : 'midpoint',
        entityId: entity.id,
        segmentIndex: segment.index,
        ratio: linePoint?.ratio,
        point: (linePoint?.point || segment.start.clone().add(segment.end).multiplyScalar(0.5)).toArray()
    });
}

function getSketchDimensionPositionReferenceFromTarget(target, anchorPoint = null) {
    if (!target?.entity) return null;
    const entity = target.entity;
    if (target.targetType === 'diameter' || entity.type === 'circle') {
        const point = entity.center?.clone();
        return point
            ? normalizeSketchReference({ kind: 'center', entityId: entity.id, point: point.toArray() })
            : null;
    }
    const edgeIndex = Number.isInteger(target.edgeIndex) ? target.edgeIndex : 0;
    const segment = getSketchEntityEdgeSegments(entity).find(({ index }) => index === edgeIndex);
    if (!segment) return null;
    const linePoint = getSketchDimensionLinePointAtAnchor(segment, anchorPoint);
    return normalizeSketchReference({
        kind: linePoint && anchorPoint ? 'line-point' : 'midpoint',
        entityId: entity.id,
        segmentIndex: segment.index,
        ratio: linePoint?.ratio,
        point: (linePoint?.point || segment.start.clone().add(segment.end).multiplyScalar(0.5)).toArray()
    });
}

function getSketchDimensionLineSnapCandidate(target, anchorPoint) {
    if (!target?.entity || target.targetType !== 'length') return null;
    const reference = getSketchDimensionPositionReferenceFromTarget(target, anchorPoint);
    const point = reference ? getSketchReferencePoint(reference) : null;
    if (!reference || !point) return null;
    return {
        point,
        type: 'line-point',
        entityId: reference.entityId,
        segmentIndex: reference.segmentIndex,
        label: uiText('선 투영점'),
        reference
    };
}

function getSketchLinePointDimensionAxis(reference) {
    if (reference?.kind !== 'line-point') return null;
    const entity = getSketchReferenceEntity(reference);
    const segment = entity
        ? getSketchEntityEdgeSegments(entity).find(({ index }) => index === reference.segmentIndex)
        : null;
    if (!segment) return null;
    const delta = segment.end.clone().sub(segment.start);
    // A vertical line defines an X (horizontal) offset. A horizontal line
    // defines a Y (vertical) offset.
    return Math.abs(delta.x) >= Math.abs(delta.y) ? 'y' : 'x';
}

function convertSketchLengthDimensionToPositionDimension(dimension, end, endRef, historyBefore = null) {
    const sketch = state.sketch;
    if (!dimension || !['length', 'diameter'].includes(dimension.type) || !end || !endRef) return false;
    const previousPlacement = sketch.dimensionPlacement;
    const dimensionIndex = sketch.dimensions.findIndex((entry) => entry.id === dimension.id);
    const startRef = getSketchDimensionPositionReference(dimension, end);
    const start = startRef ? getSketchReferencePoint(startRef) : null;
    if (dimensionIndex < 0 || !start) return false;
    const xValue = end.x - start.x;
    const yValue = end.y - start.y;
    const axis = startRef.kind === 'line-point'
        ? (getSketchLinePointDimensionAxis(startRef) || 'x')
        : Math.abs(xValue) >= Math.abs(yValue) ? 'x' : 'y';
    const value = Math.abs(axis === 'x' ? xValue : yValue);
    if (!Number.isFinite(value) || value < SKETCH_MIN_SIZE) {
        setStatus(uiText('선과 스냅 지점 사이의 X 또는 Y 축 거리가 너무 짧습니다. 다시 선택하세요.'), '#f59e0b');
        return false;
    }
    const editHistoryBefore = historyBefore || captureSketchEditSnapshot();
    const position = normalizeSketchDimensionRecord({
        id: dimension.id,
        type: 'position',
        start: start.toArray(),
        end: end.toArray(),
        xValue,
        yValue,
        value,
        startRef,
        endRef,
        axis,
        drivingRef: 'start',
        labelOffset: dimension.labelOffset,
        referenceEntityIds: [startRef.entityId, endRef.entityId].filter(Boolean)
    });
    if (!position) return false;
    sketch.dimensions[dimensionIndex] = position;
    sketch.selectedDimensionId = position.id;
    sketch.dimensionDraft = createEmptySketchDimensionDraft();
    sketch.dimensionHoverTarget = null;
    sketch.hoverEntityId = null;
    sketch.dimensionPlacement = {
        dimensionId: position.id,
        historyBefore: editHistoryBefore,
        created: previousPlacement?.created || false,
        positionDraft: true,
        axisLocked: axis
    };
    updateSketchDimensionPlacement(end);
    syncSketchDocumentEntities();
    updateSketchPreview();
    renderSketchEditorUi();
    setStatus(uiText(
        axis === 'x'
            ? '선과 스냅점 사이 수평 치수의 위치를 정한 뒤 클릭하면 값을 입력할 수 있습니다.'
            : '선과 스냅점 사이 수직 치수의 위치를 정한 뒤 클릭하면 값을 입력할 수 있습니다.'
    ), '#facc15');
    requestRender();
    return true;
}

function refreshSketchDimensionReferences() {
    state.sketch.dimensions.forEach((dimension) => {
        const normalized = normalizeSketchDimensionRecord(dimension);
        if (!normalized) return;
        if (normalized.type === 'position') {
            const start = getSketchReferencePoint(normalized.startRef) || normalized.start;
            const end = getSketchReferencePoint(normalized.endRef) || normalized.end;
            normalized.start = start.clone();
            normalized.end = end.clone();
            normalized.xValue = end.x - start.x;
            normalized.yValue = end.y - start.y;
            normalized.value = Math.max(
                SKETCH_MIN_SIZE,
                Math.abs(normalized.axis === 'x' ? normalized.xValue : normalized.yValue)
            );
        } else if (normalized.entityId) {
            const entity = state.sketch.entities.find((candidate) => candidate.id === normalized.entityId);
            if (!entity) return;
            if (normalized.type === 'diameter' && entity.center) {
                normalized.start.copy(entity.center).add(new THREE.Vector3(-entity.radius, 0, 0));
                normalized.end.copy(entity.center).add(new THREE.Vector3(entity.radius, 0, 0));
                normalized.value = entity.radius * 2;
            } else if (entity.type === 'line') {
                normalized.start.copy(entity.start);
                normalized.end.copy(entity.end);
                normalized.value = entity.start.distanceTo(entity.end);
            } else {
                const segment = getSketchEntityEdgeSegments(entity).find(({ index }) => index === normalized.edgeIndex);
                if (segment) {
                    normalized.start.copy(segment.start);
                    normalized.end.copy(segment.end);
                    normalized.value = segment.start.distanceTo(segment.end);
                }
            }
        }
        Object.assign(dimension, normalized);
    });
}

function createSketchLengthDimension(target, placementPoint = null) {
    if (!target?.entity || !target.start || !target.end) return false;
    const value = target.start.distanceTo(target.end);
    if (!Number.isFinite(value) || value < SKETCH_MIN_SIZE) return false;
    const dimensionType = target.targetType === 'diameter' ? 'diameter' : 'length';
    const existing = state.sketch.dimensions.find((entry) => (
        entry.entityId === target.entity.id
        && entry.type === dimensionType
        && (entry.edgeIndex ?? null) === (target.edgeIndex ?? null)
    ));
    if (existing) {
        state.sketch.selectedDimensionId = existing.id;
        state.sketch.dimensionPlacement = null;
        state.sketch.dimensionDraft = createEmptySketchDimensionDraft();
        state.sketch.dimensionHoverTarget = null;
        state.sketch.hoverEntityId = null;
        syncSketchDocumentEntities();
        updateSketchPreview();
        renderSketchEditorUi();
        const editing = beginSketchDimensionAnnotationEdit(existing.id);
        if (editing) {
            setStatus(uiText('기존 치수 값을 입력하세요.'), '#22c55e');
            requestRender();
        }
        return editing;
    }
    const historyBefore = captureSketchEditSnapshot();
    const dimension = normalizeSketchDimensionRecord({
        id: `dimension-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        type: dimensionType,
        start: target.start.toArray(),
        end: target.end.toArray(),
        value,
        axis: target.axis,
        entityId: target.entity.id,
        edgeIndex: target.edgeIndex,
        referenceEntityIds: [target.entity.id]
    });
    if (!dimension) return false;
    state.sketch.dimensions.push(dimension);
    return beginSketchDimensionPlacement(dimension, placementPoint, historyBefore, true);
}

function createSketchPositionDimension(start, end, startRef, endRef, { axis: axisOverride = null } = {}) {
    if (!start || !end) return false;
    const historyBefore = captureSketchEditSnapshot();
    const xValue = end.x - start.x;
    const yValue = end.y - start.y;
    const axis = axisOverride === 'x' || axisOverride === 'y'
        ? axisOverride
        : Math.abs(xValue) >= Math.abs(yValue) ? 'x' : 'y';
    const value = axis === 'x' ? Math.abs(xValue) : Math.abs(yValue);
    if (!Number.isFinite(value) || value < SKETCH_MIN_SIZE) {
        setStatus(uiText('두 스냅 지점의 X 또는 Y 축 거리가 너무 짧습니다. 다시 선택하세요.'), '#f59e0b');
        return false;
    }
    const referenceEntityIds = [startRef?.entityId, endRef?.entityId].filter(Boolean);
    const dimension = normalizeSketchDimensionRecord({
        id: `dimension-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        type: 'position',
        start: start.toArray(),
        end: end.toArray(),
        xValue,
        yValue,
        value,
        startRef,
        endRef,
        axis,
        referenceEntityIds
    });
    if (!dimension) return false;
    state.sketch.dimensions.push(dimension);
    state.sketch.selectedDimensionId = dimension.id;
    state.sketch.dimensionDraft = createEmptySketchDimensionDraft();
    state.sketch.dimensionHoverTarget = null;
    state.sketch.hoverEntityId = null;
    syncSketchDocumentEntities();
    updateSketchPreview();
    renderSketchEditorUi();
    setStatus(uiText('한 축 위치 치수를 만들었습니다. 값을 입력하면 스냅한 도형 위치가 변경됩니다.'), '#22c55e');
    recordSketchHistory('한 축 위치 치수 추가', historyBefore);
    beginSketchDimensionAnnotationEdit(dimension.id);
    requestRender();
    return true;
}

function applySketchLengthDimension(dimension, value) {
    const entity = state.sketch.entities.find((candidate) => candidate.id === dimension.entityId);
    if (!entity) return false;
    if (dimension.type === 'diameter' && entity.type === 'circle') {
        entity.radius = value / 2;
    } else if (entity.type === 'line') {
        const direction = entity.end.clone().sub(entity.start).normalize();
        if (direction.lengthSq() < 1e-12) return false;
        entity.end.copy(entity.start).add(direction.multiplyScalar(value));
    } else if (['rectangle', 'chamfer'].includes(entity.type) && ['x', 'y'].includes(dimension.axis)) {
        const axis = dimension.axis;
        const direction = Math.sign(entity.end[axis] - entity.start[axis]) || 1;
        entity.end[axis] = entity.start[axis] + direction * value;
        if (entity.type === 'chamfer') {
            entity.chamfer = THREE.MathUtils.clamp(entity.chamfer, 0, Math.min(
                Math.abs(entity.end.x - entity.start.x),
                Math.abs(entity.end.y - entity.start.y)
            ) * 0.49);
        }
    } else if (entity.type === 'polyline' && Number.isInteger(dimension.edgeIndex)) {
        const segment = getSketchEntityEdgeSegments(entity).find(({ index }) => index === dimension.edgeIndex);
        if (!segment) return false;
        const direction = segment.end.clone().sub(segment.start).normalize();
        const hasRepeatedClosingPoint = entity.points.length > 1
            && entity.points.at(-1).distanceTo(entity.points[0]) < 1e-8;
        const isClosingSegment = entity.closed !== false && (
            dimension.edgeIndex === entity.points.length - 1
            || (hasRepeatedClosingPoint && dimension.edgeIndex === entity.points.length - 2)
        );
        const pointIndex = isClosingSegment ? 0 : dimension.edgeIndex + 1;
        const targetPoint = entity.points[pointIndex];
        if (!targetPoint) return false;
        targetPoint.copy(segment.start).add(direction.multiplyScalar(value));
    } else return false;
    return true;
}

function applySelectedSketchPositionDimension(rawX, rawY, { announce = true, recordHistory = true } = {}) {
    const historyBefore = recordHistory ? captureSketchEditSnapshot() : null;
    const dimension = state.sketch.dimensions.find((entry) => entry.id === state.sketch.selectedDimensionId);
    const axis = dimension?.axis === 'y' ? 'y' : 'x';
    const axisValue = Number(axis === 'x' ? rawX : rawY ?? rawX);
    if (!dimension || dimension.type !== 'position'
        || !Number.isFinite(axisValue)
        || Math.abs(axisValue) < SKETCH_MIN_SIZE
        || Math.abs(axisValue) > SKETCH_MAX_SIZE) return false;
    const currentStart = getSketchReferencePoint(dimension.startRef) || dimension.start.clone();
    const currentEnd = getSketchReferencePoint(dimension.endRef) || dimension.end.clone();
    const currentAxisDelta = axis === 'x'
        ? currentEnd.x - currentStart.x
        : currentEnd.y - currentStart.y;
    const drivingDistance = Math.abs(axisValue) * (Math.sign(currentAxisDelta) || 1);
    const axisOffset = new THREE.Vector3(
        axis === 'x' ? drivingDistance : 0,
        axis === 'y' ? drivingDistance : 0,
        0
    );
    const targetEnd = currentStart.clone().add(axisOffset);
    const targetStart = currentEnd.clone().sub(axisOffset);
    const endCanMove = Boolean(dimension.endRef?.entityId);
    const startCanMove = Boolean(dimension.startRef?.entityId);
    const moveStart = dimension.drivingRef === 'start'
        || (dimension.drivingRef !== 'end' && !endCanMove && startCanMove);
    const moved = moveStart
        ? (startCanMove ? moveSketchReference(dimension.startRef, targetStart) : false)
        : (endCanMove ? moveSketchReference(dimension.endRef, targetEnd) : false);
    if (!moved) return false;
    refreshSketchDimensionReferences();
    syncSketchDocumentEntities();
    updateSketchPreview();
    renderSketchEditorUi();
    if (recordHistory) recordSketchHistory('한 축 위치 치수 변경', historyBefore);
    if (announce) setStatus(uiText('한 축 위치 치수를 적용했습니다. 도형 위치가 변경되었습니다.'), '#22c55e');
    requestRender();
    return true;
}

function applySelectedSketchDimension(rawValue, { announce = true, recordHistory = true } = {}) {
    const historyBefore = recordHistory ? captureSketchEditSnapshot() : null;
    const dimension = state.sketch.dimensions.find((entry) => entry.id === state.sketch.selectedDimensionId);
    const value = Number(rawValue);
    if (!dimension || dimension.type === 'position' || !Number.isFinite(value)
        || value < SKETCH_MIN_SIZE || value > SKETCH_MAX_SIZE) return false;
    if (dimension.type === 'distance') {
        const direction = dimension.end.clone().sub(dimension.start).normalize();
        if (direction.lengthSq() < 1e-12) return false;
        dimension.end.copy(dimension.start).add(direction.multiplyScalar(value));
    } else if (!applySketchLengthDimension(dimension, value)) return false;
    dimension.value = value;
    refreshSketchDimensionReferences();
    syncSketchDocumentEntities();
    updateSketchPreview();
    renderSketchEditorUi();
    if (recordHistory) recordSketchHistory('스케치 치수 변경', historyBefore);
    if (announce) setStatus(uiText('스케치 치수를 적용했습니다.'), '#22c55e');
    requestRender();
    return true;
}

function applySelectedSketchDimensionValue(rawValue, options = {}) {
    const dimension = state.sketch.dimensions.find((entry) => entry.id === state.sketch.selectedDimensionId);
    if (dimension?.type === 'position') {
        return applySelectedSketchPositionDimension(rawValue, rawValue, options);
    }
    return applySelectedSketchDimension(rawValue, options);
}

function getSketchPlanePoint(event) {
    const canvas = state.renderer?.domElement;
    const rect = canvas?.getBoundingClientRect();
    if (!rect || rect.width <= 0 || rect.height <= 0) return null;
    const pointer = new THREE.Vector2(
        ((event.clientX - rect.left) / rect.width) * 2 - 1,
        -((event.clientY - rect.top) / rect.height) * 2 + 1
    );
    const raycaster = new THREE.Raycaster();
    raycaster.setFromCamera(pointer, state.camera);
    const origin = state.sketch.origin || new THREE.Vector3();
    const worldPoint = raycaster.ray.intersectPlane(
        new THREE.Plane(new THREE.Vector3(0, 0, 1), -origin.z),
        new THREE.Vector3()
    );
    if (!worldPoint) return null;
    const point = worldPoint.sub(origin);
    return new THREE.Vector3(
        Math.round(point.x / SKETCH_POINTER_STEP_MM) * SKETCH_POINTER_STEP_MM,
        Math.round(point.y / SKETCH_POINTER_STEP_MM) * SKETCH_POINTER_STEP_MM,
        0
    );
}

function resetSketchSnapOrigin({ announce = true } = {}) {
    const sketch = state.sketch;
    if (!sketch.active) return false;
    const historyBefore = captureSketchEditSnapshot();
    sketch.origin.set(0, 0, 0);
    updateSketchPreview();
    renderSketchEditorUi();
    recordSketchHistory('스케치 원점 초기화', historyBefore);
    requestRender();
    if (announce) setStatus(uiText('스케치 원점을 초기화했습니다.'), '#60a5fa');
    return true;
}

function setSketchSnapMode(enabled) {
    const sketch = state.sketch;
    if (!sketch.active) return false;
    sketch.snapMode = Boolean(enabled);
    if (sketch.snapMode) {
        if (state.measurement.active) closeMeasurementPanel();
        if (state.placement.active) deactivateModelPlacement();
        if (state.tcpSnapMode) setTcpSnapMode(false);
        state.snapMoveMode = false;
        clearSimulationSnapFaceSelection({ invalidate: false });
        invalidateSimulationSnapCandidates();
        state.snapLastPointerEvent = null;
        captureSimulationSnapMarkerReferenceDistance();
        setStatus(uiText('스케치 위치를 스냅할 3D 모델의 면 또는 스냅 점을 클릭하세요.'), '#60a5fa');
        void buildSimulationSnapCandidates('scene')
            .then(() => {
                if (sketch.active && sketch.snapMode) {
                    setStatus(uiText('스케치 위치를 스냅할 3D 모델의 면 또는 스냅 점을 클릭하세요.'), '#60a5fa');
                }
            })
            .catch((error) => {
                console.warn('Sketch snap candidate generation failed:', error);
                if (sketch.active && sketch.snapMode) {
                    setSketchSnapMode(false);
                    setStatus(uiText('선택 가능한 스냅 지점을 가리켜 주세요.'), '#ef4444');
                }
            });
    } else {
        clearSimulationSnapFaceSelection();
        hideSimulationSnapMarker();
        resetSimulationSnapMarkerCameraScale();
    }
    renderSketchEditorUi();
    updateSimulationSnapButton();
    syncModelOutlines();
    updateTcpSnapUi();
    return true;
}

function handleSketchSnapSelection(snap) {
    const sketch = state.sketch;
    if (!sketch.active || !sketch.snapMode || !snap?.worldPoint) return false;
    const historyBefore = captureSketchEditSnapshot();
    sketch.origin.copy(snap.worldPoint);
    setSketchSnapMode(false);
    updateSketchPreview();
    renderSketchEditorUi();
    recordSketchHistory('스케치 원점 이동', historyBefore);
    setStatus(uiText('스케치 도면을 선택한 스냅 위치에 배치했습니다.'), '#22c55e');
    requestRender();
    return true;
}

function makeSketchEntityFromPoints(start, end) {
    const sketch = state.sketch;
    const tool = sketch.activeTool;
    const drawingPoints = tool === 'rectangle'
        ? getSketchRectangleDrawingPoints(start, end)
        : { start, end };
    const entityStart = drawingPoints.start;
    const entityEnd = drawingPoints.end;
    const distance = entityStart.distanceTo(entityEnd);
    if (distance < SKETCH_MIN_SIZE) return null;
    if (tool === 'circle') {
        return normalizeSketchEntityRecord({
            id: `circle-${Date.now()}-${Math.random().toString(36).slice(2)}`,
            type: 'circle',
            center: start.toArray(),
            radius: getSketchCircleRadiusFromDrag(start, end)
        });
    }
    if (tool === 'line') {
        return normalizeSketchEntityRecord({
            id: `line-${Date.now()}-${Math.random().toString(36).slice(2)}`,
            type: 'line',
            start: entityStart.toArray(),
            end: entityEnd.toArray()
        });
    }
    const width = Math.abs(entityEnd.x - entityStart.x);
    const height = Math.abs(entityEnd.y - entityStart.y);
    if (width < SKETCH_MIN_SIZE || height < SKETCH_MIN_SIZE) return null;
    return normalizeSketchEntityRecord({
        id: `${tool}-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        type: tool,
        start: entityStart.toArray(),
        end: entityEnd.toArray(),
        chamfer: tool === 'chamfer' ? Number(el.sketchChamferDistance?.value) || sketch.chamferDistance : 0
    });
}

function getSketchRectangleDrawingPoints(start, end) {
    const sketch = state.sketch;
    if (sketch.rectangleCenterMode && start && end) {
        const half = end.clone().sub(start).multiplyScalar(0.5);
        return {
            start: start.clone().sub(half),
            end: start.clone().add(half)
        };
    }
    return { start, end };
}

function constrainSketchLineEndpoint(start, end, event) {
    const sketch = state.sketch;
    if (sketch.activeTool !== 'line' || !event?.ctrlKey || !start || !end) return end;
    const dx = end.x - start.x;
    const dy = end.y - start.y;
    return Math.abs(dx) >= Math.abs(dy)
        ? new THREE.Vector3(end.x, start.y, end.z)
        : new THREE.Vector3(start.x, end.y, end.z);
}

function getSketchDrawingEndPoint(start, end, event) {
    const sketch = state.sketch;
    if (sketch.activeTool === 'line') return constrainSketchLineEndpoint(start, end, event);
    const centerMode = sketch.activeTool === 'rectangle'
        && (event ? Boolean(event.ctrlKey) : sketch.rectangleCenterMode);
    if (!centerMode || !start || !end) return end;
    return new THREE.Vector3(
        start.x + (end.x - start.x) * 2,
        start.y + (end.y - start.y) * 2,
        end.z
    );
}

function finishSketchDrawing(endPoint, { continuous = false, snapPoint = null } = {}) {
    const sketch = state.sketch;
    if (!sketch.active || sketch.phase !== 'drawing' || !sketch.startPoint || !endPoint) return false;

    const continuousTool = continuous && ['line', 'rectangle', 'circle'].includes(sketch.activeTool);
    const continuousLine = continuousTool && sketch.activeTool === 'line';
    // Keep the candidate selected by the click as the authoritative point.
    // The preview can be updated by another pointer event between the snap
    // marker hover and pointerdown, so using only the preview endpoint can
    // otherwise create the geometry from the unsnapped cursor position.
    const resolvedEndPoint = snapPoint?.isVector3 ? snapPoint.clone() : endPoint.clone();
    sketch.endPoint.copy(resolvedEndPoint);
    const entity = makeSketchEntityFromPoints(sketch.startPoint, sketch.endPoint);
    const nextStartPoint = sketch.endPoint.clone();
    sketch.startPoint = null;
    sketch.endPoint = null;
    sketch.phase = 'draw';
    sketch.pointerId = null;
    sketch.draggingEntityId = null;
    sketch.draggingEntityBefore = null;
    sketch.hoverEntityId = entity?.id || null;
    if (entity) {
        sketch.entities.push(entity);
        sketch.selectedEntityId = entity.id;
        sketch.selectedEntityIds = new Set([entity.id]);
        syncSketchDocumentEntities();
        recordSketchHistory('스케치 요소 추가', sketch.historyBefore);
        if (continuousTool) {
            if (continuousLine) {
                sketch.activeTool = 'line';
                sketch.startPoint = nextStartPoint;
                sketch.endPoint = nextStartPoint.clone();
                sketch.phase = 'drawing';
                setStatus(uiText('다음 선의 끝점을 클릭하세요. Shift를 누르면 계속 연결합니다.'), '#22c55e');
            } else {
                sketch.activeTool = entity.type;
                sketch.phase = 'draw';
                setStatus(uiFormat('{tool} 스케치를 추가했습니다. 다음 도형을 클릭하세요. Shift를 누르면 계속 생성합니다.', { tool: sketchToolDisplayName(entity.type) }), '#22c55e');
            }
            sketch.historyBefore = captureSketchEditSnapshot();
        } else {
            sketch.activeTool = 'select';
            setStatus(uiFormat('{tool} 스케치를 추가했습니다. 필요하면 다른 도구로 계속 그리세요.', { tool: sketchToolDisplayName(entity.type) }), '#22c55e');
        }
    } else {
        setStatus(uiText('스케치 크기가 너무 작습니다. 다시 첫 번째 위치를 클릭하세요.'), '#f59e0b');
    }
    if (!continuousTool) sketch.historyBefore = null;
    return Boolean(entity);
}

function distanceToSketchSegment(point, start, end) {
    const segment = end.clone().sub(start);
    const lengthSq = segment.lengthSq();
    if (lengthSq < 1e-12) return point.distanceTo(start);
    const t = THREE.MathUtils.clamp(point.clone().sub(start).dot(segment) / lengthSq, 0, 1);
    return point.distanceTo(start.clone().add(segment.multiplyScalar(t)));
}

function getSketchEntityHitDistance(entity, point) {
    if (!entity || !point) return Infinity;
    if (entity.type === 'circle' && entity.center) {
        return Math.abs(point.distanceTo(entity.center) - entity.radius);
    }
    const points = entity.type === 'line'
        ? [entity.start, entity.end]
        : entity.type === 'polyline'
            ? entity.points || []
            : getSketchPolygonPoints(entity).map((entry) => new THREE.Vector3(entry.x, entry.y, 0));
    if (points.length < 2) return Infinity;
    let distance = Infinity;
    for (let index = 1; index < points.length; index += 1) {
        distance = Math.min(distance, distanceToSketchSegment(point, points[index - 1], points[index]));
    }
    if (entity.type !== 'line' && entity.type !== 'polyline') {
        distance = Math.min(distance, distanceToSketchSegment(point, points.at(-1), points[0]));
    } else if (entity.type === 'polyline' && entity.closed !== false) {
        distance = Math.min(distance, distanceToSketchSegment(point, points.at(-1), points[0]));
    }
    return distance;
}

function isSketchPointInsideEntity(entity, point) {
    if (!entity || !point || entity.type === 'line') return false;
    if (entity.type === 'circle' && entity.center) {
        return point.distanceTo(entity.center) <= entity.radius;
    }
    if (entity.type !== 'polyline' && entity.closed === false) return false;
    const points = (entity.type === 'polyline'
        ? entity.points || []
        : getSketchPolygonPoints(entity).map((entry) => new THREE.Vector3(entry.x, entry.y, 0)));
    if (points.length < 3) return false;
    let inside = false;
    for (let index = 0, previous = points.length - 1; index < points.length; previous = index, index += 1) {
        const current = points[index];
        const prior = points[previous];
        const crosses = ((current.y > point.y) !== (prior.y > point.y))
            && (point.x < ((prior.x - current.x) * (point.y - current.y))
                / ((prior.y - current.y) || Number.EPSILON) + current.x);
        if (crosses) inside = !inside;
    }
    return inside;
}

function pickSketchEntityAtPoint(point, tolerance = 8, { includeFaces = true } = {}) {
    const sketch = state.sketch;
    const denseSketch = isDenseSketchDocument(sketch);
    const nearbyEntities = getSketchEntitiesNearPoint(point, tolerance);
    const edgeCandidates = nearbyEntities
        .map(({ entity, index }) => {
            const edgeDistance = getSketchEntityHitDistance(entity, point);
            return {
                entity,
                index,
                distance: edgeDistance,
                hitType: 'edge'
            };
        })
        .filter((candidate) => candidate.distance <= tolerance);
    const denseFaceCandidates = includeFaces && denseSketch
        ? nearbyEntities
            .map(({ entity, index }) => ({
                entity,
                index,
                distance: isSketchPointInsideEntity(entity, point) ? 0 : Infinity,
                hitType: 'face'
            }))
            .filter((candidate) => candidate.distance === 0)
        : [];
    const profileCandidates = includeFaces && !denseSketch
        ? getSketchProfileRegions()
            .map((profile, index) => ({
                entity: profile,
                index: Number.MAX_SAFE_INTEGER - index,
                distance: getSketchProfileRegionContainsPoint(profile, point) ? 0 : Infinity,
                hitType: 'face'
            }))
            .filter((candidate) => candidate.distance === 0)
        : [];
    return edgeCandidates.concat(denseFaceCandidates, profileCandidates).sort((left, right) => (
        left.distance - right.distance
        || (left.hitType === 'edge' ? -1 : 1) - (right.hitType === 'edge' ? -1 : 1)
        || right.index - left.index
    ))[0]?.entity || null;
}

function deleteSelectedSketchItem() {
    const sketch = state.sketch;
    if (!sketch.active || sketch.phase === 'drawing') return false;
    const historyBefore = captureSketchEditSnapshot();
    if (sketch.selectedDimensionId) {
        const dimensionIndex = sketch.dimensions.findIndex((dimension) => dimension.id === sketch.selectedDimensionId);
        if (dimensionIndex >= 0) {
            sketch.dimensions.splice(dimensionIndex, 1);
            sketch.selectedDimensionId = null;
            sketch.dimensionDraft = createEmptySketchDimensionDraft();
            syncSketchDocumentEntities();
            recordSketchHistory('선택한 스케치 요소 삭제', historyBefore);
            updateSketchPreview();
            renderSketchEditorUi();
            setStatus(uiText('치수를 삭제했습니다.'), '#f59e0b');
            requestRender();
            return true;
        }
    }
    const selectedEntityIds = new Set(sketch.selectedEntityIds || []);
    if (sketch.selectedEntityId) selectedEntityIds.add(sketch.selectedEntityId);
    if (!selectedEntityIds.size) return false;
    sketch.entities = sketch.entities.filter((entity) => !selectedEntityIds.has(entity.id));
    sketch.dimensions = sketch.dimensions.filter((dimension) => {
        const referencedIds = [
            ...(dimension.referenceEntityIds || []),
            ...(dimension.entityId ? [dimension.entityId] : [])
        ];
        return !referencedIds.some((entityId) => selectedEntityIds.has(entityId));
    });
    sketch.selectedEntityId = null;
    sketch.selectedEntityIds = new Set();
    sketch.selectedDimensionId = null;
    sketch.dimensionDraft = createEmptySketchDimensionDraft();
    syncSketchDocumentEntities();
    recordSketchHistory('선택한 스케치 요소 삭제', historyBefore);
    updateSketchPreview();
    renderSketchEditorUi();
    setStatus(uiText('선택한 스케치 요소를 삭제했습니다.'), '#f59e0b');
    requestRender();
    return true;
}

function translateSketchEntityInPlace(entity, offset) {
    if (!entity || !offset) return;
    if (entity.start) entity.start.add(offset);
    if (entity.end) entity.end.add(offset);
    if (entity.center) entity.center.add(offset);
    if (Array.isArray(entity.points)) entity.points.forEach((point) => point.add(offset));
}

function getSketchEntityBounds(entity) {
    if (!entity) return null;
    if (entity.type === 'circle' && entity.center && Number.isFinite(entity.radius)) {
        return {
            minX: entity.center.x - entity.radius,
            maxX: entity.center.x + entity.radius,
            minY: entity.center.y - entity.radius,
            maxY: entity.center.y + entity.radius
        };
    }
    const points = entity.type === 'line'
        ? [entity.start, entity.end]
        : entity.type === 'polyline'
            ? entity.points || []
            : getSketchPolygonPoints(entity).map((point) => new THREE.Vector3(point.x, point.y, 0));
    const validPoints = points.filter((point) => point && Number.isFinite(point.x) && Number.isFinite(point.y));
    if (!validPoints.length) return null;
    return {
        minX: Math.min(...validPoints.map((point) => point.x)),
        maxX: Math.max(...validPoints.map((point) => point.x)),
        minY: Math.min(...validPoints.map((point) => point.y)),
        maxY: Math.max(...validPoints.map((point) => point.y))
    };
}

function getDenseSketchEntitySpatialIndex() {
    const sketch = state.sketch;
    if (!isDenseSketchDocument(sketch)) return null;
    if (sketch.entitySpatialIndex
        && sketch.entitySpatialIndexRevision === sketch.previewRevision) {
        return sketch.entitySpatialIndex;
    }
    const gridSize = 128;
    const entries = sketch.entities
        .map((entity, index) => ({ entity, index, bounds: getSketchEntityBounds(entity) }))
        .filter((entry) => entry.bounds);
    if (!entries.length) return null;
    const bounds = entries.reduce((result, entry) => ({
        minX: Math.min(result.minX, entry.bounds.minX),
        maxX: Math.max(result.maxX, entry.bounds.maxX),
        minY: Math.min(result.minY, entry.bounds.minY),
        maxY: Math.max(result.maxY, entry.bounds.maxY)
    }), { minX: Infinity, maxX: -Infinity, minY: Infinity, maxY: -Infinity });
    const spanX = Math.max(bounds.maxX - bounds.minX, 1e-9);
    const spanY = Math.max(bounds.maxY - bounds.minY, 1e-9);
    const grid = new Map();
    const large = [];
    const toCell = (value, minimum, span) => Math.min(gridSize - 1, Math.max(0,
        Math.floor((value - minimum) / span * gridSize)));
    entries.forEach((entry, entryIndex) => {
        const minX = toCell(entry.bounds.minX, bounds.minX, spanX);
        const maxX = toCell(entry.bounds.maxX, bounds.minX, spanX);
        const minY = toCell(entry.bounds.minY, bounds.minY, spanY);
        const maxY = toCell(entry.bounds.maxY, bounds.minY, spanY);
        const cellCount = (maxX - minX + 1) * (maxY - minY + 1);
        if (cellCount > 4096) {
            large.push(entryIndex);
            return;
        }
        for (let x = minX; x <= maxX; x += 1) {
            for (let y = minY; y <= maxY; y += 1) {
                const key = `${x}:${y}`;
                const cell = grid.get(key) || [];
                cell.push(entryIndex);
                grid.set(key, cell);
            }
        }
    });
    sketch.entitySpatialIndex = { entries, bounds, spanX, spanY, gridSize, grid, large };
    sketch.entitySpatialIndexRevision = sketch.previewRevision;
    return sketch.entitySpatialIndex;
}

function getSketchEntitiesNearPoint(point, tolerance = 0) {
    const sketch = state.sketch;
    if (!isDenseSketchDocument(sketch) || !point) {
        return sketch.entities.map((entity, index) => ({ entity, index }));
    }
    const index = getDenseSketchEntitySpatialIndex();
    if (!index) return [];
    const cellX = (value) => Math.min(index.gridSize - 1, Math.max(0,
        Math.floor((value - index.bounds.minX) / index.spanX * index.gridSize)));
    const cellY = (value) => Math.min(index.gridSize - 1, Math.max(0,
        Math.floor((value - index.bounds.minY) / index.spanY * index.gridSize)));
    const cellRadiusX = Math.max(1, Math.ceil(Math.max(0, tolerance) / index.spanX * index.gridSize));
    const cellRadiusY = Math.max(1, Math.ceil(Math.max(0, tolerance) / index.spanY * index.gridSize));
    const centerX = cellX(point.x);
    const centerY = cellY(point.y);
    const candidates = new Set(index.large);
    for (let x = Math.max(0, centerX - cellRadiusX); x <= Math.min(index.gridSize - 1, centerX + cellRadiusX); x += 1) {
        for (let y = Math.max(0, centerY - cellRadiusY); y <= Math.min(index.gridSize - 1, centerY + cellRadiusY); y += 1) {
            (index.grid.get(`${x}:${y}`) || []).forEach((entryIndex) => candidates.add(entryIndex));
        }
    }
    return [...candidates]
        .map((entryIndex) => index.entries[entryIndex])
        .filter((entry) => entry && point.x >= entry.bounds.minX - tolerance
            && point.x <= entry.bounds.maxX + tolerance
            && point.y >= entry.bounds.minY - tolerance
            && point.y <= entry.bounds.maxY + tolerance);
}

function getSketchSelectionBounds(start, end) {
    if (!start || !end) return null;
    return {
        minX: Math.min(start.x, end.x),
        maxX: Math.max(start.x, end.x),
        minY: Math.min(start.y, end.y),
        maxY: Math.max(start.y, end.y)
    };
}

function isSketchBoundsContained(inner, outer) {
    return Boolean(inner && outer)
        && inner.minX >= outer.minX
        && inner.maxX <= outer.maxX
        && inner.minY >= outer.minY
        && inner.maxY <= outer.maxY;
}

function doSketchBoundsIntersect(left, right) {
    return Boolean(left && right)
        && left.maxX >= right.minX
        && left.minX <= right.maxX
        && left.maxY >= right.minY
        && left.minY <= right.maxY;
}

function renderSketchSelectionBox() {
    const sketch = state.sketch;
    const selection = sketch.selectionBox;
    if (!selection || !el.sketchDimensionOverlay) return;
    if (!sketch.selectionBoxElement) {
        sketch.selectionBoxElement = document.createElement('div');
        sketch.selectionBoxElement.className = 'sketch-selection-box';
        sketch.selectionBoxElement.setAttribute('aria-hidden', 'true');
        el.sketchDimensionOverlay.append(sketch.selectionBoxElement);
    }
    const overlayRect = el.sketchDimensionOverlay.getBoundingClientRect();
    const left = Math.min(selection.startScreen.x, selection.currentScreen.x) - overlayRect.left;
    const top = Math.min(selection.startScreen.y, selection.currentScreen.y) - overlayRect.top;
    const width = Math.abs(selection.currentScreen.x - selection.startScreen.x);
    const height = Math.abs(selection.currentScreen.y - selection.startScreen.y);
    const box = sketch.selectionBoxElement;
    box.hidden = !selection.moved;
    box.classList.toggle('crossing', selection.currentScreen.x < selection.startScreen.x);
    box.style.left = `${left}px`;
    box.style.top = `${top}px`;
    box.style.width = `${width}px`;
    box.style.height = `${height}px`;
}

function clearSketchSelectionBox({ releasePointer = false } = {}) {
    const sketch = state.sketch;
    const pointerId = sketch.selectionBox?.pointerId;
    if (releasePointer && pointerId !== null && pointerId !== undefined) {
        state.renderer?.domElement?.releasePointerCapture?.(pointerId);
    }
    sketch.selectionBoxElement?.remove();
    sketch.selectionBoxElement = null;
    sketch.selectionBox = null;
}

function finalizeSketchSelectionBox(event) {
    const sketch = state.sketch;
    const selection = sketch.selectionBox;
    if (!selection || selection.pointerId !== event.pointerId) return false;
    const rawPoint = getSketchPlanePoint(event);
    if (rawPoint) selection.current.copy(rawPoint);
    selection.currentScreen = { x: event.clientX, y: event.clientY };
    selection.moved = selection.moved || Math.hypot(
        selection.currentScreen.x - selection.startScreen.x,
        selection.currentScreen.y - selection.startScreen.y
    ) > 3;
    const selectionBounds = getSketchSelectionBounds(selection.start, selection.current);
    const crossing = selection.currentScreen.x < selection.startScreen.x;
    const selectedEntities = selection.moved && selectionBounds
        ? sketch.entities.filter((entity) => {
            const entityBounds = getSketchEntityBounds(entity);
            return crossing
                ? doSketchBoundsIntersect(selectionBounds, entityBounds)
                : isSketchBoundsContained(entityBounds, selectionBounds);
        })
        : [];
    const selectedIds = new Set(selectedEntities.map((entity) => entity.id));
    if (event.shiftKey) {
        const additiveIds = new Set(sketch.selectedEntityIds || []);
        selectedIds.forEach((id) => additiveIds.add(id));
        sketch.selectedEntityIds = additiveIds;
    } else {
        sketch.selectedEntityIds = selectedIds;
    }
    sketch.selectedEntityId = [...sketch.selectedEntityIds].at(-1) || null;
    sketch.selectedDimensionId = null;
    state.renderer?.domElement?.releasePointerCapture?.(event.pointerId);
    sketch.pointerId = null;
    sketch.phase = 'draw';
    clearSketchSelectionBox();
    event.preventDefault();
    event.stopImmediatePropagation();
    updateSketchPreview();
    renderSketchEditorUi();
    setStatus(
        selectedEntities.length
            ? `${selectedEntities.length}개 스케치 요소를 선택했습니다.`
            : '선택 영역에 포함된 스케치 요소가 없습니다.',
        selectedEntities.length ? '#60a5fa' : '#94a3b8'
    );
    requestRender();
    return true;
}

function handleSketchPointerDown(event) {
    const sketch = state.sketch;
    if (event.button === 2 && sketch.active && !sketch.snapMode
        && (sketch.activeTool !== 'select' || sketch.phase !== 'draw' || sketch.dimensionPlacement)) {
        event.preventDefault();
        event.stopImmediatePropagation();
        cancelSketchCurrentAction();
        selectSketchTool('select', { remember: false });
        return;
    }
    if (!sketch.active || sketch.snapMode || event.button !== 0 || !['draw', 'drawing'].includes(sketch.phase)) return;
    // A primary click starts or finishes geometry. Alt/Meta and unsupported
    // Ctrl-assisted clicks, middle clicks and the wheel remain available to
    // OrbitControls for view changes. A right click cancels the active sketch
    // command before this handler returns.
    if (event.altKey || event.metaKey || (event.ctrlKey && !['line', 'rectangle'].includes(sketch.activeTool))) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    const rawPoint = getSketchPlanePoint(event);
    if (!rawPoint) return;
    if (sketch.dimensionPlacement) {
        if (sketch.activeTool === 'dimension') {
            const placementDimension = sketch.dimensions.find((entry) => entry.id === sketch.dimensionPlacement.dimensionId);
            const placementSnapped = getSketchSnappedPoint(rawPoint, event);
            const placementTarget = getSketchDimensionTargetAtPoint(rawPoint);
            const lineSnapCandidate = placementSnapped.candidate
                ? null
                : getSketchDimensionLineSnapCandidate(placementTarget, rawPoint);
            const placementCandidate = placementSnapped.candidate || lineSnapCandidate;
            if (placementDimension
                && isSketchDimensionReferenceIntent(placementCandidate)
                && convertSketchLengthDimensionToPositionDimension(
                    placementDimension,
                    placementCandidate.point,
                    placementCandidate.reference,
                    sketch.dimensionPlacement.historyBefore
                )) {
                return;
            }
        }
        finishSketchDimensionPlacement(rawPoint);
        return;
    }
    if (['select', 'dimension'].includes(sketch.activeTool)) {
        const dimensionHit = getSketchDimensionLineAtPoint(rawPoint);
        if (dimensionHit && startSketchDimensionLineDrag(event, dimensionHit)) {
            return;
        }
    }
    const snapped = getSketchSnappedPoint(rawPoint, event);
    const point = snapped.point;
    sketch.hoverPoint = rawPoint.clone();
    sketch.snapCandidate = snapped.candidate;
    if (sketch.activeTool === 'dimension') {
        const candidate = snapped.candidate;
        const target = getSketchDimensionTargetAtPoint(rawPoint);
        sketch.dimensionHoverTarget = target;
        sketch.hoverEntityId = target?.entity?.id || null;
        const pointReference = candidate?.reference || null;
        const pointIntent = isSketchDimensionPointIntent(candidate);
        const selectedDimension = sketch.dimensions.find((entry) => entry.id === sketch.selectedDimensionId);
        if (isSketchDimensionReferenceIntent(candidate)
            && selectedDimension
            && ['length', 'diameter'].includes(selectedDimension.type)
            && !sketch.dimensionDraft?.mode) {
            if (sketch.dimensionAnnotationEditing?.dimensionId === selectedDimension.id) {
                finishSketchDimensionAnnotationEdit(true);
            }
            if (convertSketchLengthDimensionToPositionDimension(
                selectedDimension,
                point,
                pointReference
            )) {
                return;
            }
        }
        if (sketch.dimensionDraft?.mode === 'position') {
            const midpointLineTarget = target?.targetType === 'length' && candidate?.type === 'midpoint';
            if (candidate && pointReference && !midpointLineTarget) {
                beginSketchPositionDimensionPlacement(
                    sketch.dimensionDraft.start,
                    point,
                    sketch.dimensionDraft.startRef,
                    pointReference,
                    { placementPoint: rawPoint }
                );
            } else if (target) {
                const targetReference = getSketchDimensionPositionReferenceFromTarget(
                    target,
                    sketch.dimensionDraft.start
                );
                const targetPoint = targetReference
                    ? getSketchReferencePoint(targetReference)
                    : null;
                if (targetReference && targetPoint) {
                    beginSketchPositionDimensionPlacement(
                        sketch.dimensionDraft.start,
                        targetPoint,
                        sketch.dimensionDraft.startRef,
                        targetReference,
                        {
                            axisLocked: getSketchLinePointDimensionAxis(targetReference),
                            placementPoint: rawPoint
                        }
                    );
                } else {
                    setStatus(uiText('두 번째 치수점은 스냅 지점, 선 또는 모델 파츠의 유효한 점이어야 합니다.'), '#f59e0b');
                }
            } else {
                setStatus(uiText('두 번째 치수점은 스냅 지점, 선 또는 모델 파츠의 유효한 점이어야 합니다.'), '#f59e0b');
            }
        } else if (pointIntent) {
            sketch.dimensionHoverTarget = null;
            sketch.hoverEntityId = null;
            sketch.dimensionDraft = {
                mode: 'position',
                start: point.clone(),
                end: null,
                startRef: pointReference,
                endRef: null,
                target: null
            };
            setStatus(uiText('첫 번째 치수점을 선택했습니다. 유효한 스냅 지점을 선택해 X 또는 Y 한 축 치수를 완성하세요.'), '#a78bfa');
        } else {
            if (target) {
                createSketchLengthDimension(target, rawPoint);
            } else {
                setStatus(uiText('선 또는 유효한 스냅 지점을 클릭하세요.'), '#f59e0b');
            }
        }
        updateSketchPreview();
        renderSketchEditorUi();
        requestRender();
        return;
    }
    if (sketch.phase === 'drawing' && !['select', 'dimension'].includes(sketch.activeTool)) {
        if (sketch.activeTool === 'rectangle') sketch.rectangleCenterMode = Boolean(event.ctrlKey);
        const drawingEndPoint = getSketchDrawingEndPoint(sketch.startPoint, point, event);
        finishSketchDrawing(drawingEndPoint, {
            continuous: event.shiftKey,
            snapPoint: drawingEndPoint
        });
        updateSketchPreview();
        renderSketchEditorUi();
        requestRender();
        return;
    }
    // A drawing command always starts a new entity. Do not let a coincident
    // existing sketch edge/face turn the first snapped click into a move
    // operation; moving existing geometry belongs to Select mode.
    if (sketch.activeTool !== 'select' && sketch.activeTool !== 'dimension') {
        sketch.startPoint = point.clone();
        sketch.endPoint = point.clone();
        sketch.rectangleCenterMode = sketch.activeTool === 'rectangle' && Boolean(event.ctrlKey);
        sketch.historyBefore = captureSketchEditSnapshot();
        sketch.pointerId = null;
        sketch.phase = 'drawing';
        updateSketchPreview();
        renderSketchEditorUi();
        requestRender();
        return;
    }
    const selected = pickSketchEntityAtPoint(
        sketch.activeTool === 'select' ? rawPoint : point,
        getSketchHitToleranceWorld(10),
        { includeFaces: sketch.activeTool === 'select' }
    );
    const selectedEntityIds = getSketchProfileSelectionIds(selected);
    sketch.hoverEntityId = selectedEntityIds.at(-1) || null;
    if (sketch.activeTool === 'select') {
        // Select mode only selects or moves sketch entities. Dimension
        // creation is intentionally owned by the dedicated dimension tool.
        if (selected) {
            if (event.shiftKey) {
                const selectedIds = new Set(sketch.selectedEntityIds || []);
                const isSelected = selectedEntityIds.every((id) => selectedIds.has(id));
                selectedEntityIds.forEach((id) => {
                    if (isSelected) selectedIds.delete(id);
                    else selectedIds.add(id);
                });
                sketch.selectedEntityIds = selectedIds;
                sketch.selectedEntityId = [...selectedIds].at(-1) || null;
            } else {
                sketch.selectedEntityId = selectedEntityIds.at(-1) || null;
                sketch.selectedEntityIds = new Set(selectedEntityIds);
            }
        } else if (!event.shiftKey) {
            sketch.selectedEntityId = null;
            sketch.selectedEntityIds = new Set();
        }
        sketch.selectedDimensionId = null;
        if (!selected) {
            sketch.selectionBox = {
                pointerId: event.pointerId,
                start: rawPoint.clone(),
                current: rawPoint.clone(),
                startScreen: { x: event.clientX, y: event.clientY },
                currentScreen: { x: event.clientX, y: event.clientY },
                moved: false
            };
            sketch.pointerId = event.pointerId;
            state.renderer.domElement.setPointerCapture?.(event.pointerId);
            renderSketchSelectionBox();
        }
        updateSketchPreview();
        renderSketchEditorUi();
        if (sketch.extrudeSelectionMode) {
            const profileCount = getSelectedSketchProfiles().length;
            setStatus(
                profileCount
                    ? uiFormat(
                        sketch.operation === 'cut'
                            ? '{count}개 프로파일이 선택되었습니다. 돌출 컷을 눌러 Z 깊이를 설정하세요.'
                            : '{count}개 프로파일이 선택되었습니다. Extrude를 눌러 Z 높이를 설정하세요.',
                        { count: profileCount }
                    )
                    : uiText('돌출할 닫힌 스케치 항목을 선택하세요. Shift 키로 여러 항목을 선택할 수 있습니다.'),
                profileCount ? '#22d3ee' : '#facc15'
            );
        }
        requestRender();
        return;
    }
    if (selected) {
        sketch.selectedEntityId = selected.id;
        sketch.selectedEntityIds = new Set([selected.id]);
        sketch.draggingEntityId = selected.id;
        sketch.draggingEntityBefore = serializeSketchEntity(selected);
        sketch.historyBefore = captureSketchEditSnapshot();
        sketch.startPoint = point;
        sketch.endPoint = point.clone();
        sketch.pointerId = event.pointerId;
        sketch.phase = 'moving';
        state.renderer.domElement.setPointerCapture?.(event.pointerId);
        updateSketchPreview();
        renderSketchEditorUi();
        requestRender();
        return;
    }
    sketch.startPoint = point;
    sketch.endPoint = point.clone();
    sketch.rectangleCenterMode = sketch.activeTool === 'rectangle' && Boolean(event.ctrlKey);
    sketch.historyBefore = captureSketchEditSnapshot();
    sketch.pointerId = null;
    sketch.phase = 'drawing';
    updateSketchPreview();
    renderSketchEditorUi();
    requestRender();
}

function handleSketchContextMenu(event) {
    const sketch = state.sketch;
    const target = event.target;
    const canvas = state.renderer?.domElement;
    const isSketchSurface = target === canvas
        || target?.closest?.('#sketch-dimension-overlay');
    if (!isSketchSurface || !sketch.active) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    if (sketch.snapMode
        || (sketch.activeTool === 'select' && sketch.phase === 'draw' && !sketch.dimensionPlacement)) return;
    cancelSketchCurrentAction();
    selectSketchTool('select', { remember: false });
}

function handleSketchPointerMove(event) {
    const sketch = state.sketch;
    if (!sketch.active || sketch.snapMode) return;
    const rawPoint = getSketchPlanePoint(event);
    if (!rawPoint) return;
    if (sketch.dimensionPlacement) {
        const snapped = getSketchSnappedPoint(rawPoint, event);
        const dimensionTarget = getSketchDimensionTargetAtPoint(rawPoint);
        const lineSnapCandidate = snapped.candidate
            ? null
            : getSketchDimensionLineSnapCandidate(dimensionTarget, rawPoint);
        sketch.hoverPoint = rawPoint.clone();
        sketch.snapCandidate = snapped.candidate || lineSnapCandidate;
        sketch.dimensionHoverTarget = dimensionTarget;
        sketch.hoverEntityId = sketch.dimensionHoverTarget?.entity?.id || null;
        updateSketchDimensionPlacement(rawPoint);
        event.preventDefault();
        event.stopImmediatePropagation();
        return;
    }
    if (sketch.dimensionLineDrag?.pointerId === event.pointerId) {
        updateSketchDimensionLineDrag(event);
        event.preventDefault();
        event.stopImmediatePropagation();
        return;
    }
    if (sketch.selectionBox?.pointerId === event.pointerId) {
        const selection = sketch.selectionBox;
        selection.current.copy(rawPoint);
        selection.currentScreen = { x: event.clientX, y: event.clientY };
        selection.moved = selection.moved || Math.hypot(
            selection.currentScreen.x - selection.startScreen.x,
            selection.currentScreen.y - selection.startScreen.y
        ) > 3;
        sketch.hoverPoint = rawPoint.clone();
        sketch.snapCandidate = null;
        sketch.hoverEntityId = null;
        renderSketchSelectionBox();
        event.preventDefault();
        event.stopImmediatePropagation();
        return;
    }
    const snapped = getSketchSnappedPoint(rawPoint, event);
    const point = snapped.point;
    if (sketch.phase === 'drawing' && sketch.activeTool === 'rectangle') {
        sketch.rectangleCenterMode = Boolean(event.ctrlKey);
    }
    sketch.hoverPoint = rawPoint.clone();
    sketch.snapCandidate = snapped.candidate;
    if (sketch.activeTool === 'dimension') {
        const dimensionTarget = getSketchDimensionTargetAtPoint(rawPoint);
        const lineSnapCandidate = snapped.candidate
            ? null
            : getSketchDimensionLineSnapCandidate(dimensionTarget, rawPoint);
        const dimensionSnapCandidate = snapped.candidate || lineSnapCandidate;
        const dimensionPoint = dimensionSnapCandidate?.point || point;
        sketch.snapCandidate = dimensionSnapCandidate;
        sketch.dimensionHoverTarget = dimensionTarget;
        sketch.hoverEntityId = sketch.dimensionHoverTarget?.entity?.id || null;
        if (sketch.dimensionDraft?.start) {
            sketch.dimensionDraft.end = dimensionSnapCandidate?.reference ? dimensionPoint.clone() : null;
            sketch.dimensionDraft.endRef = dimensionSnapCandidate?.reference || null;
            event.preventDefault();
            event.stopImmediatePropagation();
        }
        updateSketchPreview();
        renderSketchEditorUi();
        requestRender();
        if (sketch.dimensionDraft?.start) return;
    } else {
        const hovered = pickSketchEntityAtPoint(
            sketch.activeTool === 'select' ? rawPoint : point,
            getSketchHitToleranceWorld(10),
            { includeFaces: sketch.activeTool === 'select' }
        );
        sketch.hoverEntityId = getSketchProfileSelectionIds(hovered).at(-1) || null;
        sketch.dimensionHoverTarget = null;
        updateSketchPreview();
        renderSketchEditorUi();
        requestRender();
    }
    const isDrawing = sketch.phase === 'drawing';
    const isMoving = sketch.phase === 'moving' && sketch.pointerId === event.pointerId;
    if (!isDrawing && !isMoving) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    const previewPoint = sketch.phase === 'drawing'
        ? getSketchDrawingEndPoint(sketch.startPoint, point, event)
        : point;
    sketch.endPoint.copy(previewPoint);
    if (isMoving && sketch.draggingEntityBefore) {
        const index = sketch.entities.findIndex((entity) => entity.id === sketch.draggingEntityId);
        const before = normalizeSketchEntityRecord(sketch.draggingEntityBefore);
        if (index >= 0 && before) {
            translateSketchEntityInPlace(before, previewPoint.clone().sub(sketch.startPoint));
            sketch.entities[index] = before;
            sketch.selectedEntityId = before.id;
            syncSketchDocumentEntities();
        }
    }
    updateSketchPreview();
    renderSketchEditorUi();
    requestRender();
}

function handleSketchPointerUp(event) {
    const sketch = state.sketch;
    if (sketch.dimensionLineDrag?.pointerId === event.pointerId) {
        finishSketchDimensionLineDrag(event);
        event.preventDefault();
        event.stopImmediatePropagation();
        return;
    }
    if (sketch.selectionBox?.pointerId === event.pointerId) {
        finalizeSketchSelectionBox(event);
        return;
    }
    if (!sketch.active || sketch.snapMode || sketch.phase !== 'moving' || sketch.pointerId !== event.pointerId) return;
    const rawPoint = getSketchPlanePoint(event);
    const snapped = getSketchSnappedPoint(rawPoint, event);
    const point = snapped.point;
    if (point) sketch.endPoint.copy(point);
    sketch.hoverPoint = rawPoint?.clone() || sketch.hoverPoint;
    sketch.snapCandidate = snapped.candidate;
    state.renderer.domElement.releasePointerCapture?.(event.pointerId);
    sketch.pointerId = null;
    if (sketch.phase === 'moving') {
        sketch.phase = 'draw';
        sketch.startPoint = null;
        sketch.endPoint = null;
        sketch.draggingEntityId = null;
        sketch.draggingEntityBefore = null;
        syncSketchDocumentEntities();
        recordSketchHistory('스케치 요소 이동', sketch.historyBefore);
        sketch.historyBefore = null;
        updateSketchPreview();
        renderSketchEditorUi();
        setStatus(uiText('스케치 요소를 이동했습니다.'), '#22c55e');
        requestRender();
        return;
    }
}

function handleSketchPointerCancel(event) {
    const sketch = state.sketch;
    if (sketch.dimensionLineDrag?.pointerId === event.pointerId) {
        cancelSketchDimensionLineDrag();
        event.preventDefault();
        event.stopImmediatePropagation();
        updateSketchPreview();
        renderSketchEditorUi();
        requestRender();
        return;
    }
    if (sketch.selectionBox?.pointerId === event.pointerId) {
        clearSketchSelectionBox({ releasePointer: true });
        sketch.pointerId = null;
        event.preventDefault();
        event.stopImmediatePropagation();
        updateSketchPreview();
        renderSketchEditorUi();
        return;
    }
    if (!sketch.active || sketch.pointerId !== event.pointerId) return;
    sketch.pointerId = null;
    sketch.startPoint = null;
    sketch.endPoint = null;
    sketch.phase = 'draw';
    sketch.historyBefore = null;
    sketch.snapCandidate = null;
    sketch.dimensionHoverTarget = null;
    event.stopImmediatePropagation();
    updateSketchPreview();
    renderSketchEditorUi();
}

function handleSketchPointerLeave() {
    const sketch = state.sketch;
    if (!sketch.active || sketch.pointerId !== null) return;
    sketch.hoverPoint = null;
    sketch.snapCandidate = null;
    sketch.hoverEntityId = null;
    sketch.dimensionHoverTarget = null;
    updateSketchPreview();
    requestRender();
}

function getSketchCameraFocus(camera = state.camera) {
    const box = new THREE.Box3();
    state.models.forEach((model) => box.expandByObject(model));
    const hasModels = !box.isEmpty();
    const center = hasModels ? box.getCenter(new THREE.Vector3()) : new THREE.Vector3();
    const size = hasModels ? box.getSize(new THREE.Vector3()) : new THREE.Vector3(800, 800, 0);
    const aspect = Math.max(0.1, camera?.isOrthographicCamera
        ? (camera.right - camera.left) / Math.max(camera.top - camera.bottom, Number.EPSILON)
        : camera?.aspect || 1);
    const fov = THREE.MathUtils.degToRad(camera?.fov || 45);
    // In sketch view, robot X+ is screen-up and robot Y+ is screen-left.
    // The camera's vertical span therefore follows X, while the horizontal
    // span follows Y.
    const visibleSpan = Math.max(size.x, size.y / aspect, 400);
    const verticalSpan = visibleSpan * 1.35;
    const distance = Math.max(500, verticalSpan / (2 * Math.tan(fov / 2)));
    return { center: new THREE.Vector3(center.x, center.y, 0), distance, verticalSpan };
}

function positionSketchCameraAtScene() {
    if (!state.camera || !state.controls) return;
    const sourceCamera = state.sketch.previousCameraObject || state.camera;
    const { center, distance, verticalSpan } = getSketchCameraFocus(sourceCamera);
    const previousCamera = state.sketch.previousCamera;
    const previousTarget = previousCamera?.target;
    const previousDistance = previousCamera?.position && previousTarget
        ? previousCamera.position.distanceTo(previousTarget)
        : NaN;
    const previousFov = Number.isFinite(previousCamera?.fov)
        ? THREE.MathUtils.degToRad(previousCamera.fov)
        : 0;
    const previousVerticalSpan = Number.isFinite(previousDistance)
        && previousDistance > 0
        && previousFov > 0
        ? (2 * previousDistance * Math.tan(previousFov / 2))
            / Math.max(previousCamera.zoom || 1, Number.EPSILON)
        : NaN;
    const sketchVerticalSpan = state.sketch.preserveCameraDistanceOnEntry
        && Number.isFinite(previousVerticalSpan)
        && previousVerticalSpan > 0
        ? previousVerticalSpan
        : verticalSpan;
    const aspect = Math.max(0.1, state.renderer?.domElement?.clientWidth || 1)
        / Math.max(1, state.renderer?.domElement?.clientHeight || 1);
    const halfHeight = Math.max(1, sketchVerticalSpan * 0.5);
    const halfWidth = Math.max(1, halfHeight * aspect);
    const planeZ = state.sketch.origin?.z || 0;
    state.camera.up.set(1, 0, 0);
    state.camera.left = -halfWidth;
    state.camera.right = halfWidth;
    state.camera.top = halfHeight;
    state.camera.bottom = -halfHeight;
    state.camera.zoom = 1;
    state.camera.position.set(center.x, center.y, planeZ + distance);
    // OrbitControls keeps the camera-up conversion in a private closure.
    // Recreate it after switching to the sketch X-up view. Passing the saved
    // state explicitly keeps the sketch controller independent from the
    // normal controller that will be restored when sketching ends.
    // With an X-up camera, screenSpacePanning=false derives the vertical pan
    // direction from object.up and can turn a right-drag into Z movement.
    // Sketches live on the XY plane, so pan in screen space while sketching.
    const sketchControlsState = state.sketch.previousControls
        ? {
            ...state.sketch.previousControls,
            enabled: true,
            enablePan: true,
            enableRotate: false,
            screenSpacePanning: true
        }
        : null;
    recreateMainOrbitControls(sketchControlsState);
    state.camera.lookAt(new THREE.Vector3(center.x, center.y, planeZ));
    state.camera.updateProjectionMatrix();
    state.controls.target.set(center.x, center.y, planeZ);
    state.controls.update();
}

function getStoredSketchFeatureDocument(model) {
    if (!isSketchFeatureModel(model)) return normalizeSketchDocument({});
    const stored = model.userData.sketchDocument;
    if (stored) return normalizeSketchDocument(stored);
    return normalizeSketchDocument({
        name: model.userData.modelName || model.name,
        entities: (model.userData.sketchProfiles || []).map(serializeSketchEntity).filter(Boolean)
    });
}

function getStoredSketchCutFeature(model) {
    const feature = model?.userData?.sketchCutFeature;
    const profiles = getSketchCutFeatureProfiles(feature);
    const depth = Number(feature?.depth);
    if (!profiles.length || !Number.isFinite(depth) || depth < SKETCH_MIN_SIZE) return null;
    return {
        profiles,
        profile: profiles[0],
        depth,
        direction: normalizeCutDirection(feature.direction)
    };
}

function getSketchCutFeatureProfiles(feature) {
    if (!feature) return [];
    const source = Array.isArray(feature.profiles)
        ? feature.profiles
        : feature.profile
            ? [feature.profile]
            : [feature];
    return source
        .map(normalizeSketchEntityRecord)
        .filter(Boolean);
}

function serializeSketchCutFeature(feature) {
    const profiles = getSketchCutFeatureProfiles(feature);
    const depth = Number(feature?.depth);
    if (!profiles.length || !Number.isFinite(depth) || depth < SKETCH_MIN_SIZE) return null;
    return {
        profiles: profiles.map(serializeSketchEntity),
        // Keep the first profile for compatibility with saved projects created
        // before multi-profile extrude cuts were supported.
        profile: serializeSketchEntity(profiles[0]),
        depth,
        direction: normalizeCutDirection(feature.direction)
    };
}

function getSketchFeatureEditEntities(model, mode) {
    const document = getStoredSketchFeatureDocument(model);
    const cutFeature = getStoredSketchCutFeature(model);
    if (mode === 'feature' && cutFeature) {
        const sketchOrigin = getSketchFeatureSketchOrigin(model);
        const localOffset = new THREE.Vector3(
            -sketchOrigin.x,
            -sketchOrigin.y,
            -sketchOrigin.z
        );
        const localCutProfiles = cutFeature.profiles
            .map((profile) => translateSketchEntity(profile, localOffset))
            .filter(Boolean);
        return {
            document,
            cutFeature,
            entities: localCutProfiles
        };
    }
    const entities = (document.entities?.length
        ? document.entities
        : (model.userData.sketchProfiles || []).map(serializeSketchEntity)
    ).map(normalizeSketchEntityRecord).filter(Boolean);
    return { document, cutFeature, entities };
}

function beginSketchModelEdit(model, mode = 'sketch') {
    if (!model || !state.models.includes(model) || !isEditableSketchFeatureModel(model)) return false;
    if (model.userData.placement !== 'scene') {
        setStatus(uiText('장면에 배치된 스케치 도형만 편집할 수 있습니다.'), '#f59e0b');
        return false;
    }
    if (mode !== 'feature') mode = 'sketch';
    if (state.sketch.active) exitSketchMode({ status: null });
    selectSceneModel(model);
    return enterSketchMode({ editModel: model, editMode: mode });
}

function enterSketchMode({ editModel = null, editMode = 'sketch' } = {}) {
    const sketch = state.sketch;
    // Sketching is an additive scene operation.  Keep it available while a
    // program or OLP runtime is moving a robot; the active motion session
    // continues to own the robot pose independently of the sketch camera.
    if (sketch.active) return false;
    if (editModel && (!state.models.includes(editModel) || !isEditableSketchFeatureModel(editModel))) return false;
    if (state.placement.active || state.measurement.active || state.tcpSnapMode || state.snapMoveMode) {
        setStatus('다른 위치 선택 모드를 먼저 종료하세요.', '#f59e0b');
        return false;
    }
    const previousPanelState = captureSketchPanelState();
    closeSketchPanels();
    const editingMode = editModel ? (editMode === 'feature' ? 'feature' : 'sketch') : null;
    const storedEdit = editModel ? getSketchFeatureEditEntities(editModel, editingMode) : null;
    if (state.primitiveShapeOverlay.dimensionMode) setPrimitiveShapeDimensionMode(false);
    sketch.previousCamera = {
        position: state.camera.position.clone(),
        quaternion: state.camera.quaternion.clone(),
        up: state.camera.up.clone(),
        target: state.controls.target.clone(),
        zoom: state.camera.zoom,
        fov: state.camera.fov
    };
    sketch.previousCameraObject = state.camera;
    sketch.previousControls = captureMainOrbitControlState(state.controls);
    sketch.previousPanelState = previousPanelState;
    sketch.previousTransformEnabled = Boolean(state.transformControls?.enabled);
    sketch.previousBaseGizmoEnabled = Boolean(state.baseJogTransformControls?.enabled);
    sketch.active = true;
    sketch.document = storedEdit
        ? normalizeSketchDocument({
            ...storedEdit.document,
            entities: storedEdit.entities.map(serializeSketchEntity).filter(Boolean),
            dimensions: editingMode === 'feature' ? [] : storedEdit.document.dimensions
        })
        : createSketchDocument({
            name: 'Sketch 1',
            settings: { snapEnabled: true }
        });
    sketch.phase = 'draw';
    sketch.activeTool = 'select';
    sketch.entities = storedEdit ? storedEdit.entities : [];
    sketch.closedLineLoopsCache = null;
    sketch.closedLineLoopsRevision = -1;
    sketch.profileRegionsCache = null;
    sketch.profileRegionsRevision = -1;
    sketch.externalSnapCandidatesCache = null;
    sketch.externalSnapCandidatesSignature = '';
    sketch.externalSnapCandidatesBuildSignature = '';
    sketch.externalSnapCandidatesPromise = null;
    sketch.selectedEntityId = null;
    sketch.selectedEntityIds = new Set();
    sketch.extrudeSelectionMode = false;
    sketch.extrudePanelOpen = editingMode === 'feature';
    sketch.operation = editingMode === 'feature' && storedEdit?.cutFeature ? 'cut' : 'add';
    sketch.cutDirection = storedEdit?.cutFeature?.direction
        || normalizeCutDirection(el.sketchCutDirection?.value);
    sketch.origin.copy(editModel ? getSketchFeatureSketchOrigin(editModel) : new THREE.Vector3());
    sketch.editingModel = editModel;
    sketch.editingMode = editingMode;
    sketch.extrudeAppliedDuringEdit = false;
    sketch.editingModelVisibility = editModel ? editModel.visible !== false : null;
    sketch.editingHistoryBefore = editModel && !state.historySuspended
        ? captureSceneSnapshot()
        : null;
    sketch.editingCutFeature = storedEdit?.cutFeature
        ? serializeSketchCutFeature(storedEdit.cutFeature)
        : null;
    if (editModel) {
        editModel.visible = false;
        updateModelSelectionOutlines();
        renderModelTree();
    }
    sketch.snapMode = false;
    sketch.snapEnabled = true;
    sketch.snapCandidate = null;
    sketch.hoverPoint = null;
    sketch.hoverEntityId = null;
    sketch.dimensionHoverTarget = null;
    sketch.dimensions = editingMode === 'feature'
        ? []
        : (storedEdit?.document?.dimensions || []).map(normalizeSketchDimensionRecord).filter(Boolean);
    sketch.selectedDimensionId = null;
    sketch.dimensionLabelDrag = null;
    sketch.dimensionLineDrag = null;
    sketch.dimensionPlacement = null;
    sketch.dimensionAnnotationEditing = null;
    sketch.historyBefore = null;
    sketch.undoStack = [];
    sketch.redoStack = [];
    sketch.historySuspended = false;
    clearSketchSelectionBox();
    sketch.dimensionDraft = createEmptySketchDimensionDraft();
    sketch.startPoint = null;
    sketch.endPoint = null;
    sketch.pointerId = null;
    sketch.draggingEntityId = null;
    sketch.draggingEntityBefore = null;
    state.sceneSelectionPointer = null;
    state.controls.enabled = true;
    state.camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.1, 1e8);
    state.camera.name = 'Sketch Orthographic Camera';
    setTransformHandlesEnabled(false);
    setBaseJogGizmoEnabled(false);
    document.body.classList.add('sketch-workbench-active');
    sketch.preserveCameraDistanceOnEntry = true;
    positionSketchCameraAtScene();
    sketch.preserveCameraDistanceOnEntry = false;
    ensureSketchPreview();
    el.canvasContainer?.classList.add('sketch-mode-active');
    renderPrimitiveShapePanel();
    updateSketchPreview();
    updateSimulationSnapButton();
    updateHistoryButtons();
    if (editModel && editingMode === 'feature') {
        const height = storedEdit?.cutFeature?.depth || Number(editModel.userData.sketchExtrudeDepth) || 100;
        if (el.sketchWorkbenchHeight) el.sketchWorkbenchHeight.value = String(height);
        if (el.sketchHeight) el.sketchHeight.value = String(height);
        const featureProfileIds = new Set(
            getSketchFeatureProfiles(editModel)
                .flatMap((profile) => [
                    ...getSketchProfileSelectionIds(profile),
                    ...(profile.holes || []).flatMap((hole) => getSketchProfileSourceIds(hole))
                ])
                .map(String)
        );
        const featureProfiles = storedEdit?.cutFeature
            ? sketch.entities
            : sketch.entities.filter((entity) => featureProfileIds.has(String(entity.id)));
        // Keep all sketch entities visible for editing, but select only the
        // profile(s) that produced the current feature. If an older saved
        // model has no matching profile IDs, retain the previous select-all
        // behavior as a compatibility fallback.
        const selectedFeatureEntities = featureProfiles.length ? featureProfiles : sketch.entities;
        sketch.selectedEntityIds = new Set(selectedFeatureEntities.map((entity) => entity.id));
        sketch.selectedEntityId = selectedFeatureEntities[0]?.id || null;
        renderSketchEditorUi();
        updateSketchPreview();
        setStatus(uiText('피쳐 편집 중입니다. Z 높이를 변경한 뒤 적용하세요.'), '#22d3ee');
    } else if (editModel) {
        const height = Number(editModel.userData.sketchExtrudeDepth);
        if (Number.isFinite(height) && el.sketchWorkbenchHeight) el.sketchWorkbenchHeight.value = String(height);
        if (Number.isFinite(height) && el.sketchHeight) el.sketchHeight.value = String(height);
        setStatus(uiText('스케치 편집 중입니다. 수정한 뒤 스케치 완료를 누르세요.'), '#a78bfa');
    } else {
        setStatus(uiText('2D 평면뷰입니다. 도구를 선택하고 첫 번째 위치를 클릭한 뒤, 크기를 정해 다시 클릭하세요.'), '#a78bfa');
    }
    requestRender();
    return true;
}

function exitSketchMode({ restoreCamera = true, status = null } = {}) {
    const sketch = state.sketch;
    if (!sketch.active) return false;
    const editingModel = sketch.editingModel;
    const editingModelVisibility = sketch.editingModelVisibility;
    if (sketch.pointerId !== null) state.renderer.domElement.releasePointerCapture?.(sketch.pointerId);
    if (sketch.snapMode) {
        clearSimulationSnapFaceSelection({ invalidate: false });
        invalidateSimulationSnapCandidates();
        hideSimulationSnapMarker();
        resetSimulationSnapMarkerCameraScale();
    }
    const previousCamera = sketch.previousCamera;
    const previousControls = sketch.previousControls;
    clearSketchPreviewVisual();
    sketch.active = false;
    sketch.document = null;
    sketch.phase = 'idle';
    sketch.entities = [];
    sketch.closedLineLoopsCache = null;
    sketch.closedLineLoopsRevision = -1;
    sketch.profileRegionsCache = null;
    sketch.profileRegionsRevision = -1;
    sketch.externalSnapCandidatesCache = null;
    sketch.externalSnapCandidatesSignature = '';
    sketch.externalSnapCandidatesBuildSignature = '';
    sketch.externalSnapCandidatesPromise = null;
    sketch.selectedEntityId = null;
    sketch.selectedEntityIds = new Set();
    sketch.extrudeSelectionMode = false;
    sketch.extrudePanelOpen = false;
    sketch.startPoint = null;
    sketch.endPoint = null;
    sketch.pointerId = null;
    sketch.draggingEntityId = null;
    sketch.draggingEntityBefore = null;
    sketch.origin.set(0, 0, 0);
    sketch.snapMode = false;
    sketch.snapEnabled = true;
    sketch.snapCandidate = null;
    sketch.hoverPoint = null;
    sketch.hoverEntityId = null;
    sketch.dimensionHoverTarget = null;
    sketch.dimensions = [];
    sketch.selectedDimensionId = null;
    sketch.dimensionLabelDrag = null;
    sketch.dimensionLineDrag = null;
    sketch.dimensionPlacement = null;
    sketch.dimensionAnnotationEditing = null;
    sketch.historyBefore = null;
    if (editingModel && state.models.includes(editingModel)) {
        editingModel.visible = editingModelVisibility !== false;
        updateModelSelectionOutlines();
        renderModelTree();
    }
    sketch.editingModel = null;
    sketch.editingMode = null;
    sketch.extrudeAppliedDuringEdit = false;
    sketch.editingModelVisibility = null;
    sketch.editingCutFeature = null;
    sketch.editingHistoryBefore = null;
    sketch.undoStack = [];
    sketch.redoStack = [];
    sketch.historySuspended = false;
    clearSketchSelectionBox();
    sketch.dimensionDraft = createEmptySketchDimensionDraft();
    resetMainOrbitControlInteraction();
    restoreMain3DViewAfterSketch(previousCamera, previousControls, restoreCamera);
    el.canvasContainer?.classList.remove('sketch-mode-active');
    document.body.classList.remove('sketch-workbench-active');
    setTransformHandlesEnabled(sketch.previousTransformEnabled);
    setBaseJogGizmoEnabled(sketch.previousBaseGizmoEnabled);
    restoreSketchPanelState(sketch.previousPanelState);
    sketch.previousCamera = null;
    sketch.previousCameraObject = null;
    sketch.previousControls = null;
    sketch.previousPanelState = null;
    renderPrimitiveShapePanel();
    updatePrimitiveDimensionOverlay();
    updateSimulationSnapButton();
    updateHistoryButtons();
    if (status) setStatus(status, '#60a5fa');
    requestRender();
    return true;
}

function redrawSketchRectangle() {
    if (!state.sketch.active) return;
    const historyBefore = captureSketchEditSnapshot();
    state.sketch.entities = [];
    state.sketch.dimensions = [];
    state.sketch.selectedDimensionId = null;
    state.sketch.dimensionDraft = createEmptySketchDimensionDraft();
    syncSketchDocumentEntities();
    state.sketch.selectedEntityId = null;
    state.sketch.selectedEntityIds = new Set();
    state.sketch.extrudeSelectionMode = false;
    state.sketch.extrudePanelOpen = false;
    clearSketchSelectionBox();
    state.sketch.startPoint = null;
    state.sketch.endPoint = null;
    state.sketch.pointerId = null;
    state.sketch.phase = 'draw';
    recordSketchHistory('스케치 지우기', historyBefore);
    updateSketchPreview();
    renderSketchEditorUi();
    setStatus(uiText('스케치를 지웠습니다. 도구를 선택해 다시 그리세요.'), '#a78bfa');
    requestRender();
}

function updateExistingSketchFeatureFromEdit(model, profiles, depth, sketchDocument, cutFeature = null) {
    if (!isSketchFeatureModel(model) || model.userData.placement !== 'scene') return false;
    const normalizedProfiles = (Array.isArray(profiles) ? profiles : [profiles])
        .map(normalizeSketchEntityRecord)
        .filter(Boolean)
        .filter((profile) => profile.type !== 'line');
    const normalizedDepth = Number(depth);
    if (!normalizedProfiles.length
        || !Number.isFinite(normalizedDepth)
        || normalizedDepth < SKETCH_MIN_SIZE
        || normalizedDepth > SKETCH_MAX_SIZE) {
        if (el.sketchEditorError) el.sketchEditorError.textContent = uiText('돌출할 닫힌 스케치 항목을 먼저 선택하거나 작성하세요.');
        return false;
    }
    const normalizedCut = cutFeature
        ? {
            profiles: getSketchCutFeatureProfiles(cutFeature)
                .map((profile) => normalizeSketchEntityRecord(serializeSketchEntity(profile)))
                .filter(Boolean),
            depth: Number(cutFeature.depth),
            direction: normalizeCutDirection(cutFeature.direction)
        }
        : null;
    if (normalizedCut) {
        const targetProfiles = getSketchFeatureProfiles(model);
        const targetProfile = normalizedProfiles[0];
        const cutLayout = getExtrudeCutLayout(normalizedDepth, normalizedCut.depth, normalizedCut.direction);
        const validTarget = normalizedProfiles.length === 1
            && isSketchClosedProfile(targetProfile)
            && targetProfiles.length === 1
            && isSketchClosedProfile(targetProfiles[0])
            && model.scale.distanceTo(new THREE.Vector3(1, 1, 1)) <= 1e-6
            && Math.abs(model.quaternion.x) <= 1e-6
            && Math.abs(model.quaternion.y) <= 1e-6
            && Math.abs(model.quaternion.z) <= 1e-6
            && Math.abs(Math.abs(model.quaternion.w) - 1) <= 1e-6
            && cutLayout
            && normalizedCut.profiles.length
            && normalizedCut.depth >= SKETCH_MIN_SIZE
            && normalizedCut.depth <= normalizedDepth
            && normalizedCut.profiles.every((profile) => isSketchCutProfileInsideSketchFeature(profile, targetProfile, model));
        if (!validTarget) {
            if (el.sketchEditorError) el.sketchEditorError.textContent = uiText('돌출 컷 프로파일은 대상 도형 안에 있어야 하며 컷 깊이는 도형 높이 이하여야 합니다.');
            return false;
        }
    }
    // Updating a feature changes the generated mesh profiles, not the
    // editable sketch document. Keep every entity in the document so a
    // second feature edit does not erase the unextruded DXF figures.
    const documentEntities = (
        Array.isArray(sketchDocument?.entities) && sketchDocument.entities.length
            ? sketchDocument.entities
            : normalizedProfiles
    )
        .map(normalizeSketchEntityRecord)
        .filter(Boolean)
        .map(serializeSketchEntity);
    const normalizedDocument = normalizeSketchDocument({
        ...(sketchDocument || {}),
        entities: documentEntities
    });
    model.userData.sketchProfiles = normalizedProfiles.map(serializeSketchEntity);
    model.userData.sketchDocument = normalizedDocument;
    const wasSketchOnly = isSketchOnlyModel(model);
    model.userData.sketchFeatureType = 'extrude';
    model.userData.sketchExtrudeDepth = normalizedDepth;
    if (wasSketchOnly) {
        model.userData.modelName = `${uiText('스케치 돌출')} ${model.userData.sketchFeatureNameIndex}`;
        model.userData.generatedNameKey = '스케치 돌출';
        model.name = `Sketch: ${model.userData.modelName}`;
    }
    delete model.userData.sketchCutFeature;
    rebuildSketchFeatureVisual(model, { materialColor: getModelColorHex(model) });
    centerSketchFeatureGeometry(model, { preserveSketchOrigin: true });
    if (normalizedCut && !applySketchCutFeature(
        model,
        normalizedCut.profiles,
        normalizedCut.depth,
        normalizedCut.direction
    )) return false;
    model.updateMatrixWorld(true);
    updateModelRenderComplexity(model);
    if (state.collision.enabled) state.collision.system?.prepare([model]);
    markSceneCollisionDirty(model);
    refreshCollisionDebugOverlays();
    renderModelTree();
    updateModelSelectionOutlines();
    requestRender();
    return true;
}

function updateExistingSketchOnlyFromEdit(model, entities, sketchDocument, sketchOrigin) {
    if (!isSketchFeatureModel(model) || model.userData.cadExtrudeFeature) return false;
    const normalizedEntities = (Array.isArray(entities) ? entities : [entities])
        .map(normalizeSketchEntityRecord)
        .filter(Boolean);
    if (!normalizedEntities.length) {
        if (el.sketchEditorError) el.sketchEditorError.textContent = uiText('스케치 요소를 먼저 작성하세요.');
        return false;
    }
    const sketchFeatureNameIndex = Number(model.userData.sketchFeatureNameIndex) > 0
        ? Number(model.userData.sketchFeatureNameIndex)
        : getNextSketchFeatureNameIndex();
    const modelName = `${uiText('스케치')} ${sketchFeatureNameIndex}`;
    model.userData.sketchFeatureType = 'sketch';
    model.userData.sketchFeatureNameIndex = sketchFeatureNameIndex;
    model.userData.sketchProfiles = normalizedEntities.map(serializeSketchEntity);
    model.userData.sketchDocument = normalizeSketchDocument(sketchDocument || {
        name: modelName,
        entities: model.userData.sketchProfiles
    });
    model.userData.sketchExtrudeDepth = null;
    model.userData.sketchMaterialColor = getSketchFeatureDisplayColor(model, '#c4b5fd');
    model.userData.sketchOriginOffset = [0, 0, 0];
    model.userData.sketchGeometryCentered = true;
    model.userData.modelName = modelName;
    model.userData.generatedNameKey = '스케치';
    model.name = `Sketch: ${modelName}`;
    delete model.userData.sketchCutFeature;
    model.position.copy(sketchOrigin || model.position);
    rebuildSketchFeatureVisual(model, {
        materialColor: model.userData.sketchMaterialColor
    });
    model.updateMatrixWorld(true);
    updateModelRenderComplexity(model);
    markSceneCollisionDirty(model);
    renderModelTree();
    updateModelSelectionOutlines();
    requestRender();
    return true;
}

function finishSketch() {
    const sketch = state.sketch;
    if (!sketch.active || sketch.phase === 'drawing') return false;
    syncSketchDocumentEntities();
    const entities = sketch.entities.map(serializeSketchEntity).filter(Boolean);
    if (!entities.length) {
        setStatus(uiText('스케치 요소를 먼저 작성하세요.'), '#f59e0b');
        return false;
    }
    const sketchDocument = sketch.document
        ? normalizeSketchDocument({
            ...sketch.document,
            entities
        })
        : normalizeSketchDocument({ entities });
    const sketchOrigin = sketch.origin.clone();
    const editingModel = sketch.editingModel;
    if (editingModel && state.models.includes(editingModel)) {
        if (sketch.editingMode === 'feature') return finishSketchAndCreateShape();
        const historyBefore = sketch.editingHistoryBefore || captureSceneSnapshot();
        if (sketch.extrudeAppliedDuringEdit) {
            // The extrusion was already applied while this sketch edit was
            // active. Preserve the generated feature instead of converting it
            // back to a sketch-only model when the user finishes editing.
            editingModel.userData.sketchDocument = sketchDocument;
            editingModel.updateMatrixWorld(true);
            renderModelTree();
            updateModelSelectionOutlines();
            exitSketchMode({ restoreCamera: true });
            updateUIStatus();
            selectSceneModel(editingModel);
            if (historyBefore) recordHistory('스케치 피쳐 편집', historyBefore, captureSceneSnapshot());
            if (el.sketchEditorError) el.sketchEditorError.textContent = '';
            setStatus(uiText('스케치 돌출이 적용된 상태로 스케치를 완료했습니다.'), '#22c55e');
            return true;
        }
        if (!updateExistingSketchOnlyFromEdit(editingModel, entities, sketchDocument, sketchOrigin)) return false;
        exitSketchMode({ restoreCamera: true });
        updateUIStatus();
        selectSceneModel(editingModel);
        if (historyBefore) recordHistory('스케치 편집', historyBefore, captureSceneSnapshot());
        if (el.sketchEditorError) el.sketchEditorError.textContent = '';
        setStatus(uiText('스케치 완료'), '#22c55e');
        return true;
    }
    const historyBefore = !state.historySuspended ? captureSceneSnapshot() : null;
    exitSketchMode({ restoreCamera: true });
    const model = createSketchFeatureRoot(entities, null, {
        sketchOnly: true,
        sketchDocument
    });
    model.position.copy(sketchOrigin);
    model.updateMatrixWorld(true);
    state.scene.add(model);
    state.models.push(model);
    updateUIStatus();
    selectSceneModel(model);
    if (historyBefore) recordHistory('2D 스케치 생성', historyBefore, captureSceneSnapshot());
    if (el.sketchEditorError) el.sketchEditorError.textContent = '';
    setStatus(uiText('스케치 완료'), '#22c55e');
    return true;
}

function keepSketchModeAfterExtrude() {
    const sketch = state.sketch;
    if (!sketch.active) return;
    sketch.extrudeSelectionMode = false;
    sketch.extrudePanelOpen = false;
    sketch.phase = 'draw';
    sketch.startPoint = null;
    sketch.endPoint = null;
    sketch.pointerId = null;
    sketch.snapCandidate = null;
    renderSketchWorkbenchUi();
    renderSketchEditorUi();
    updateSketchPreview();
    requestRender();
}

function finishSketchAndCreateShape(options = {}) {
    const sketch = state.sketch;
    const profilesOverride = Array.isArray(options.profilesOverride) ? options.profilesOverride : null;
    const keepSketchActive = options.keepSketchActive === true;
    const selectedProfiles = getSelectedSketchProfiles();
    const sourceProfiles = profilesOverride
        || (selectedProfiles.length ? selectedProfiles : getSketchClosedProfiles());
    if (!sketch.active || !sourceProfiles.length) {
        setStatus(uiText('돌출할 닫힌 스케치 항목을 먼저 선택하거나 작성하세요.'), '#f59e0b');
        return false;
    }
    const heightField = options.heightInput || el.sketchHeight;
    const height = Number(heightField?.value);
    if (!Number.isFinite(height) || height <= 0 || height > 100000) {
        if (el.sketchEditorError) el.sketchEditorError.textContent = uiText('Z 높이는 0보다 크고 유효한 숫자여야 합니다.');
        return false;
    }
    const profiles = sourceProfiles.map(cloneSketchEntity).filter(Boolean);
    syncSketchDocumentEntities();
    // The generated mesh may intentionally contain only the selected
    // profiles, but the editable sketch document must retain every entity
    // from the drawing so reopening Sketch mode does not discard the other
    // DXF figures.
    const documentEntities = sketch.entities.map(serializeSketchEntity).filter(Boolean);
    const sketchDocument = sketch.document
        ? normalizeSketchDocument({
            ...sketch.document,
            entities: documentEntities
        })
        : normalizeSketchDocument({ entities: documentEntities });
    const sketchOrigin = sketch.origin.clone();
    const operation = sketch.operation === 'cut' ? 'cut' : 'add';
    const editingModel = sketch.editingModel;
    if (editingModel && state.models.includes(editingModel)) {
        const existingProfiles = operation === 'cut'
            ? getSketchFeatureProfiles(editingModel)
            : profiles;
        const editDepth = operation === 'cut'
            || (sketch.editingMode === 'sketch' && !isSketchOnlyModel(editingModel))
            ? Number(editingModel.userData.sketchExtrudeDepth)
            : height;
        const editCutFeature = operation === 'cut'
            ? {
                profiles: profiles
                    .map((profile) => translateSketchEntity(profile, sketchOrigin))
                    .filter(Boolean),
                depth: height,
                direction: sketch.cutDirection
            }
            : sketch.editingMode === 'sketch'
                ? sketch.editingCutFeature
                : null;
        const editDocument = sketch.editingMode === 'feature'
            ? getStoredSketchFeatureDocument(editingModel)
            : sketchDocument;
        if (!updateExistingSketchFeatureFromEdit(
            editingModel,
            existingProfiles,
            editDepth,
            editDocument,
            editCutFeature
        )) return false;
        if (keepSketchActive) sketch.extrudeAppliedDuringEdit = true;
        const historyBefore = sketch.editingHistoryBefore;
        if (keepSketchActive) keepSketchModeAfterExtrude();
        else exitSketchMode({ restoreCamera: true });
        syncModelOutlines();
        updateUIStatus();
        selectSceneModel(editingModel);
        if (historyBefore && !keepSketchActive) recordHistory('스케치 피쳐 편집', historyBefore, captureSceneSnapshot());
        if (keepSketchActive) scheduleMotionProjectSave();
        if (el.sketchEditorError) el.sketchEditorError.textContent = '';
        setStatus(uiText('기존 스케치 피쳐를 수정했습니다.'), '#22c55e');
        return true;
    }
    const target = state.selectedModel;
    const historyBefore = !state.historySuspended ? captureSceneSnapshot() : null;
    if (operation === 'cut') {
        const cutProfiles = profiles
            .map((profile) => translateSketchEntity(profile, sketchOrigin))
            .filter(Boolean);
        if (!isSketchCutTarget(target)) {
            if (el.sketchEditorError) el.sketchEditorError.textContent = uiText('돌출 컷은 먼저 사각형 도형 또는 단일 스케치 돌출 도형을 선택하세요.');
            return false;
        }
        if (!applySketchCutFeature(target, cutProfiles, height, sketch.cutDirection)) return false;
        if (keepSketchActive) keepSketchModeAfterExtrude();
        else exitSketchMode({ restoreCamera: true });
        syncModelOutlines();
        updateUIStatus();
        selectSceneModel(target);
        if (historyBefore && !keepSketchActive) recordHistory('2D 스케치 돌출 컷', historyBefore, captureSceneSnapshot());
        if (keepSketchActive) scheduleMotionProjectSave();
        if (el.sketchEditorError) el.sketchEditorError.textContent = '';
        setStatus(uiText('선택한 도형에 스케치 돌출 컷을 적용했습니다.'), '#22c55e');
        return true;
    }
    if (keepSketchActive) keepSketchModeAfterExtrude();
    else exitSketchMode({ restoreCamera: true });
    const model = createSketchFeatureRoot(profiles, height, { sketchDocument });
    model.position.copy(sketchOrigin).add(getSketchFeatureOriginOffset(model));
    model.updateMatrixWorld(true);
    state.scene.add(model);
    state.models.push(model);
    if (state.collision.enabled) state.collision.system?.prepare([model]);
    markSceneCollisionDirty(model);
    updateModelRenderComplexity(model);
    updateUIStatus();
    selectSceneModel(model);
    if (historyBefore && !keepSketchActive) recordHistory('2D 스케치 돌출 생성', historyBefore, captureSceneSnapshot());
    if (keepSketchActive) scheduleMotionProjectSave();
    if (el.sketchEditorError) el.sketchEditorError.textContent = '';
    setStatus(uiText('스케치 프로파일을 돌출해 3D 형상을 생성했습니다.'), '#22c55e');
    return true;
}

function createPrimitiveShapeMaterial(model) {
    const mesh = getPrimitiveShapeMesh(model);
    const source = Array.isArray(mesh?.material) ? mesh.material[0] : mesh?.material;
    return source || new THREE.MeshStandardMaterial({
        color: '#bfc7d5',
        roughness: 0.58,
        metalness: 0.08
    });
}

function rebuildPrimitiveShapeVisual(model, type, dimensions) {
    const primitiveMeshes = model.children.filter((child) => child.userData?.primitiveShapeMesh && child.isMesh);
    const material = createPrimitiveShapeMaterial(model);
    primitiveMeshes.forEach((mesh, index) => {
        if (index > 0 && mesh.material && mesh.material !== material) {
            const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
            materials.forEach((entry) => entry?.dispose?.());
        }
        mesh.geometry?.dispose?.();
        mesh.removeFromParent();
    });
    const mesh = new THREE.Mesh(createPrimitiveShapeGeometry(type, dimensions), material);
    mesh.name = `${model.userData.modelName || model.name} geometry`;
    mesh.userData.primitiveShapeMesh = true;
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    model.add(mesh);
    delete model.userData.sketchCutFeature;
    return mesh;
}

function isSketchCutProfileInsideBox(profile, dimensions, model) {
    if (!profile) return false;
    const offsetX = Number(model.position.x) || 0;
    const offsetY = Number(model.position.y) || 0;
    const halfX = dimensions.x / 2;
    const halfY = dimensions.y / 2;
    const epsilon = 1e-6;
    if (profile.type === 'circle') {
        const x = profile.center.x - offsetX;
        const y = profile.center.y - offsetY;
        return x - profile.radius >= -halfX + epsilon
            && x + profile.radius <= halfX - epsilon
            && y - profile.radius >= -halfY + epsilon
            && y + profile.radius <= halfY - epsilon;
    }
    return getSketchProfileBoundaryPoints(profile, offsetX, offsetY).every((point) => (
        point.x >= -halfX + epsilon && point.x <= halfX - epsilon
        && point.y >= -halfY + epsilon && point.y <= halfY - epsilon
    ));
}

function getSketchProfileBoundaryPoints(profile, offsetX = 0, offsetY = 0) {
    if (!profile) return [];
    if (profile.type === 'circle' && profile.center) {
        const radius = Math.abs(Number(profile.radius) || 0);
        return Array.from({ length: 64 }, (_, index) => {
            const angle = (index / 64) * Math.PI * 2;
            return new THREE.Vector2(
                profile.center.x - offsetX + Math.cos(angle) * radius,
                profile.center.y - offsetY + Math.sin(angle) * radius
            );
        });
    }
    const points = getSketchPolygonPoints({
        ...profile,
        start: profile.start?.clone?.().setZ(0),
        end: profile.end?.clone?.().setZ(0)
    }, offsetX, offsetY);
    if (points.length > 1 && points[0].distanceTo(points.at(-1)) < 1e-6) points.pop();
    return points;
}

function isSketchPointInsidePolygon(point, polygon) {
    if (!point || polygon.length < 3) return false;
    let inside = false;
    const epsilon = 1e-6;
    for (let index = 0, previous = polygon.length - 1; index < polygon.length; previous = index++) {
        const currentPoint = polygon[index];
        const previousPoint = polygon[previous];
        const cross = (point.x - previousPoint.x) * (currentPoint.y - previousPoint.y)
            - (point.y - previousPoint.y) * (currentPoint.x - previousPoint.x);
        const onSegment = Math.abs(cross) <= epsilon
            && point.x >= Math.min(previousPoint.x, currentPoint.x) - epsilon
            && point.x <= Math.max(previousPoint.x, currentPoint.x) + epsilon
            && point.y >= Math.min(previousPoint.y, currentPoint.y) - epsilon
            && point.y <= Math.max(previousPoint.y, currentPoint.y) + epsilon;
        if (onSegment) return true;
        const intersects = ((currentPoint.y > point.y) !== (previousPoint.y > point.y))
            && point.x < ((previousPoint.x - currentPoint.x) * (point.y - currentPoint.y))
                / (previousPoint.y - currentPoint.y) + currentPoint.x;
        if (intersects) inside = !inside;
    }
    return inside;
}

function isSketchExtrudeCutTarget(model) {
    if (!isSketchFeatureModel(model) || isSketchOnlyModel(model) || model.userData.cadExtrudeFeature) return false;
    const profiles = getSketchFeatureProfiles(model);
    return profiles.length === 1 && isSketchClosedProfile(profiles[0]);
}

function isSketchCutProfileInsideSketchFeature(profile, targetProfile, model) {
    const originOffset = getSketchFeatureOriginOffset(model);
    const targetPoints = getSketchProfileBoundaryPoints(targetProfile, originOffset.x, originOffset.y);
    const localOffsetX = Number(model.position.x) || 0;
    const localOffsetY = Number(model.position.y) || 0;
    const cutPoints = getSketchProfileBoundaryPoints(profile, localOffsetX, localOffsetY);
    return targetPoints.length >= 3
        && cutPoints.length >= 3
        && cutPoints.every((point) => isSketchPointInsidePolygon(point, targetPoints));
}

function isSketchCutTarget(model) {
    return Boolean(model) && (
        (isPrimitiveShapeModel(model) && model.userData.primitiveShapeType === 'box')
        || isSketchExtrudeCutTarget(model)
    );
}

function applySketchCutFeature(model, profile, depth, direction = 'positive') {
    const isBoxTarget = Boolean(isPrimitiveShapeModel(model) && model.userData.primitiveShapeType === 'box');
    const isSketchTarget = isSketchExtrudeCutTarget(model);
    if (!isBoxTarget && !isSketchTarget) {
        if (el.sketchEditorError) el.sketchEditorError.textContent = uiText('돌출 컷은 사각형 도형 또는 단일 스케치 돌출 도형에만 적용할 수 있습니다.');
        return false;
    }
    if (model.userData.placement !== 'scene'
        || model.scale.distanceTo(new THREE.Vector3(1, 1, 1)) > 1e-6
        || Math.abs(model.quaternion.x) > 1e-6
        || Math.abs(model.quaternion.y) > 1e-6
        || Math.abs(model.quaternion.z) > 1e-6
        || Math.abs(Math.abs(model.quaternion.w) - 1) > 1e-6) {
        if (el.sketchEditorError) el.sketchEditorError.textContent = uiText('돌출 컷 대상은 회전하지 않은 장면 도형이어야 합니다.');
        return false;
    }
    const targetProfile = isSketchTarget ? getSketchFeatureProfiles(model)[0] : null;
    if (isSketchTarget) centerSketchFeatureGeometry(model, { preserveSketchOrigin: true });
    if (isSketchTarget && model.userData.sketchCutFeature) {
        if (el.sketchEditorError) el.sketchEditorError.textContent = uiText('이미 돌출 컷이 적용된 스케치 도형에는 추가 컷을 적용할 수 없습니다.');
        return false;
    }
    const dimensions = isBoxTarget ? getPrimitiveShapeDimensions(model) : null;
    const targetDepth = isBoxTarget ? dimensions.z : Number(model.userData.sketchExtrudeDepth);
    const normalizedProfiles = (Array.isArray(profile) ? profile : [profile])
        .map((entry) => normalizeSketchEntityRecord(serializeSketchEntity(entry)));
    const cutDepth = Number(depth);
    const cutLayout = getExtrudeCutLayout(targetDepth, cutDepth, direction);
    const cutDirection = cutLayout?.direction || normalizeCutDirection(direction);
    if (!normalizedProfiles.length
        || normalizedProfiles.some((entry) => !entry || !isSketchClosedProfile(entry))
        || !Number.isFinite(targetDepth) || !Number.isFinite(cutDepth)
        || cutDepth < SKETCH_MIN_SIZE || cutDepth > targetDepth
        || !normalizedProfiles.every((entry) => isBoxTarget
            ? isSketchCutProfileInsideBox(entry, dimensions, model)
            : isSketchCutProfileInsideSketchFeature(entry, targetProfile, model))) {
        if (el.sketchEditorError) el.sketchEditorError.textContent = uiText('돌출 컷 프로파일은 대상 도형 안에 있어야 하며 컷 깊이는 도형 높이 이하여야 합니다.');
        return false;
    }
    const localOffsetX = Number(model.position.x) || 0;
    const localOffsetY = Number(model.position.y) || 0;
    const sketchOriginOffset = isSketchTarget ? getSketchFeatureOriginOffset(model) : null;
    const localCutStartZ = cutLayout.cutStartZ - (isSketchTarget ? sketchOriginOffset.z : 0);
    const localRemainingStartZ = cutLayout.remainingStartZ - (isSketchTarget ? sketchOriginOffset.z : 0);
    const outer = isBoxTarget
        ? new THREE.Shape()
        : createSketchProfileShape(targetProfile, sketchOriginOffset.x, sketchOriginOffset.y);
    if (!outer) return false;
    if (isBoxTarget) {
        outer.moveTo(-dimensions.x / 2, -dimensions.y / 2);
        outer.lineTo(dimensions.x / 2, -dimensions.y / 2);
        outer.lineTo(dimensions.x / 2, dimensions.y / 2);
        outer.lineTo(-dimensions.x / 2, dimensions.y / 2);
        outer.closePath();
    }
    const holes = normalizedProfiles.map((entry) => createSketchProfileShape(entry, localOffsetX, localOffsetY));
    if (holes.some((hole) => !hole)) return false;
    outer.holes = holes;
    const ringGeometry = new THREE.ExtrudeGeometry(outer, {
        depth: cutDepth,
        steps: 1,
        curveSegments: 48,
        bevelEnabled: false
    });
    ringGeometry.translate(0, 0, localCutStartZ);
    ringGeometry.computeBoundingBox();
    ringGeometry.computeBoundingSphere();
    const oldMeshes = model.children.filter((child) => (
        child.isMesh && (isBoxTarget ? child.userData?.primitiveShapeMesh : child.userData?.sketchFeatureMesh)
    ));
    const material = isBoxTarget ? createPrimitiveShapeMaterial(model) : getSketchFeatureMaterial(model);
    oldMeshes.forEach((mesh, index) => {
        mesh.geometry?.dispose?.();
        if (index > 0 && mesh.material && mesh.material !== material) {
            const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
            materials.forEach((entry) => entry?.dispose?.());
        }
        mesh.removeFromParent();
    });
    const ring = new THREE.Mesh(ringGeometry, material);
    ring.name = `${model.userData.modelName || model.name} cut geometry`;
    if (isBoxTarget) ring.userData.primitiveShapeMesh = true;
    else ring.userData.sketchFeatureMesh = true;
    ring.castShadow = true;
    ring.receiveShadow = true;
    model.add(ring);
    if (cutDepth < targetDepth - SKETCH_MIN_SIZE * 0.25) {
        const remainingHeight = cutLayout.remainingHeight;
        let capGeometry;
        if (isBoxTarget) {
            capGeometry = new THREE.BoxGeometry(dimensions.x, dimensions.y, remainingHeight);
            capGeometry.translate(0, 0, cutLayout.remainingStartZ + remainingHeight / 2);
        } else {
            capGeometry = new THREE.ExtrudeGeometry(createSketchProfileShape(
                targetProfile,
                sketchOriginOffset.x,
                sketchOriginOffset.y
            ), {
                depth: remainingHeight,
                steps: 1,
                curveSegments: 48,
                bevelEnabled: false
            });
            capGeometry.translate(0, 0, localRemainingStartZ);
        }
        capGeometry.computeBoundingBox();
        capGeometry.computeBoundingSphere();
        const cap = new THREE.Mesh(capGeometry, material.clone());
        cap.name = `${model.userData.modelName || model.name} upper solid`;
        if (isBoxTarget) cap.userData.primitiveShapeMesh = true;
        else cap.userData.sketchFeatureMesh = true;
        cap.castShadow = true;
        cap.receiveShadow = true;
        model.add(cap);
    }
    model.userData.sketchCutFeature = {
        profiles: normalizedProfiles.map(serializeSketchEntity),
        // Retain the legacy singular field for older workspace readers.
        profile: serializeSketchEntity(normalizedProfiles[0]),
        depth: cutDepth,
        direction: cutDirection
    };
    model.updateMatrixWorld(true);
    syncModelOutlines();
    if (state.collision.enabled) state.collision.system?.prepare([model]);
    markSceneCollisionDirty(model);
    refreshCollisionDebugOverlays();
    requestRender();
    return true;
}

function ensurePrimitiveDimensionOverlay() {
    if (state.primitiveShapeOverlay.group) return state.primitiveShapeOverlay.group;
    const group = new THREE.Group();
    group.name = 'Primitive dimension overlay';
    group.renderOrder = 35;
    group.userData.dimensionOverlay = true;
    ['x', 'y', 'z'].forEach((axis) => {
        const color = AXIS_COLORS[axis];
        const material = new THREE.LineBasicMaterial({
            color,
            depthTest: false,
            depthWrite: false,
            transparent: true,
            opacity: 0.95
        });
        const line = new THREE.Line(new THREE.BufferGeometry(), material);
        line.frustumCulled = false;
        line.renderOrder = 35;
        const extensionMaterial = new THREE.LineBasicMaterial({
            color,
            depthTest: false,
            depthWrite: false,
            transparent: true,
            opacity: 0.72
        });
        const extensionLine = new THREE.LineSegments(new THREE.BufferGeometry(), extensionMaterial);
        extensionLine.frustumCulled = false;
        extensionLine.renderOrder = 35;
        const arrowMaterial = new THREE.MeshBasicMaterial({
            color,
            depthTest: false,
            depthWrite: false,
            transparent: true,
            opacity: 0.95
        });
        const arrows = [0, 1].map(() => {
            const arrow = new THREE.Mesh(new THREE.ConeGeometry(3.2, 9, 4), arrowMaterial);
            arrow.renderOrder = 35;
            return arrow;
        });
        const axisGroup = new THREE.Group();
        axisGroup.add(extensionLine, line, ...arrows);
        axisGroup.userData.extensionLine = extensionLine;
        axisGroup.userData.line = line;
        axisGroup.userData.arrows = arrows;
        group.add(axisGroup);
        const label = document.createElement('div');
        label.className = 'primitive-dimension-label';
        label.dataset.axis = axis;
        label.addEventListener('click', (event) => {
            event.preventDefault();
            event.stopPropagation();
            if (state.placement.active) beginPlacementDimensionLabelEdit(axis);
            else beginGeneratedShapeDimensionLabelEdit(axis);
        });
        label.addEventListener('pointerdown', (event) => event.stopPropagation());
        el.primitiveDimensionOverlay?.appendChild(label);
        state.primitiveShapeOverlay.labels.set(axis, label);
    });
    state.scene.add(group);
    state.primitiveShapeOverlay.group = group;
    return group;
}

function setPrimitiveDimensionAxisVisual(
    axisGroup,
    sourceStart,
    sourceEnd,
    start,
    end,
    showExtensionLines = true
) {
    const extensionLine = axisGroup.userData.extensionLine;
    const line = axisGroup.userData.line;
    const arrows = axisGroup.userData.arrows || [];
    extensionLine.visible = Boolean(showExtensionLines);
    if (extensionLine.visible) {
        extensionLine.geometry.setFromPoints([sourceStart, start, sourceEnd, end]);
    } else {
        extensionLine.geometry.setFromPoints([]);
    }
    line.geometry.setFromPoints([start, end]);
    const direction = end.clone().sub(start).normalize();
    // ConeGeometry's origin is at its center, while its tip is half the
    // height away from that origin. Keep each arrow inside the measured span
    // so its outward-facing tip lands exactly on the line endpoint.
    const arrowHalfLength = Number(arrows[0]?.geometry?.parameters?.height) / 2 || 0;
    const startArrowQuaternion = new THREE.Quaternion().setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.clone().negate()
    );
    const endArrowQuaternion = new THREE.Quaternion().setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction
    );
    arrows[0]?.position.copy(start).addScaledVector(direction, arrowHalfLength);
    arrows[1]?.position.copy(end).addScaledVector(direction, -arrowHalfLength);
    arrows.forEach((arrow, index) => {
        arrow.quaternion.copy(index === 0 ? startArrowQuaternion : endArrowQuaternion);
    });
}

function updatePlacementDimensionOverlay() {
    const placement = state.placement;
    const overlay = state.primitiveShapeOverlay;
    const group = ensurePrimitiveDimensionOverlay();
    if (!group) return;
    const transformTarget = getPlacementTransformTarget();
    if (placement.active && transformTarget && !placement.dimensionOriginWorldPoint) {
        capturePlacementDimensionOrigin();
    }
    updatePlacementDimensionFromTarget();
    const source = placement.dimensionOriginWorldPoint;
    const target = placement.dimensionTargetWorldPoint;
    const translation = placement.dimensionTranslation;
    const editing = overlay.editing;
    const show = placement.active
        && transformTarget
        && source
        && target
        && translation
        && ['x', 'y', 'z'].some((axis) => Math.abs(translation[axis]) > PLACEMENT_DIMENSION_DISPLAY_EPSILON);
    group.visible = Boolean(show);
    if (!show) {
        overlay.labels.forEach((label) => { label.hidden = true; });
        return;
    }

    const pX = new THREE.Vector3(target.x, source.y, source.z);
    const pY = new THREE.Vector3(target.x, target.y, source.z);
    const labelOffsetX = new THREE.Vector3(0, -15, 0);
    const labelOffsetY = new THREE.Vector3(-15, 0, 0);
    const labelOffsetZ = new THREE.Vector3(15, 15, 0);
    const placedLabelPositions = [];
    const axes = {
        x: { source: [source, pX], labelOffset: labelOffsetX },
        y: { source: [pX, pY], labelOffset: labelOffsetY },
        z: { source: [pY, target], labelOffset: labelOffsetZ }
    };
    ['x', 'y', 'z'].forEach((axis) => {
        const axisGroup = group.children[['x', 'y', 'z'].indexOf(axis)];
        const label = overlay.labels.get(axis);
        const descriptor = axes[axis];
        const value = translation[axis];
        const hasLength = Math.abs(value) > PLACEMENT_DIMENSION_DISPLAY_EPSILON;
        const editingThisLabel = editing?.kind === 'placement'
            && editing.axis === axis
            && label?.contains(editing.input);
        if (axisGroup) axisGroup.visible = hasLength;
        if (!label) return;
        if (!hasLength && !editingThisLabel) {
            label.hidden = true;
            return;
        }
        label.hidden = false;
        // Model placement is a movement preview, not a part measurement. Keep
        // the bidirectional arrow on the actual X/Y/Z movement path and omit
        // the CAD-style extension lines that would otherwise lift it away.
        const dimensionStart = descriptor.source[0].clone();
        const dimensionEnd = descriptor.source[1].clone();
        const labelStart = descriptor.source[0].clone().add(descriptor.labelOffset);
        const labelEnd = descriptor.source[1].clone().add(descriptor.labelOffset);
        if (hasLength) {
            setPrimitiveDimensionAxisVisual(
                axisGroup,
                descriptor.source[0],
                descriptor.source[1],
                dimensionStart,
                dimensionEnd,
                false
            );
        }
        const midpoint = labelStart.clone().lerp(labelEnd, 0.8).project(state.camera);
        const rect = el.canvasContainer?.getBoundingClientRect();
        const width = el.primitiveDimensionOverlay?.clientWidth || rect?.width || 0;
        const height = el.primitiveDimensionOverlay?.clientHeight || rect?.height || 0;
        let left = THREE.MathUtils.clamp((midpoint.x + 1) * 0.5 * width, 42, Math.max(42, width - 42));
        let top = THREE.MathUtils.clamp((1 - midpoint.y) * 0.5 * height, 22, Math.max(22, height - 22));
        // A placement can have two or three components that project to nearly
        // the same screen point. Separate the editable labels in screen space
        // so each axis remains independently clickable without moving its
        // dimension line.
        for (let attempt = 0; attempt < 12 && placedLabelPositions.some((previous) => (
            Math.abs(left - previous.left) < 92 && Math.abs(top - previous.top) < 28
        )); attempt += 1) {
            top = THREE.MathUtils.clamp(top + 32, 22, Math.max(22, height - 22));
            if (placedLabelPositions.some((previous) => (
                Math.abs(left - previous.left) < 92 && Math.abs(top - previous.top) < 28
            ))) {
                left = THREE.MathUtils.clamp(left + 98, 42, Math.max(42, width - 42));
            }
        }
        placedLabelPositions.push({ left, top });
        label.style.left = `${left}px`;
        label.style.top = `${top}px`;
        if (editingThisLabel) return;
        label.textContent = `${axis.toUpperCase()} = ${formatJogValue(value)} mm`;
    });
}

function updatePrimitiveDimensionOverlay() {
    if (state.sketch.active) {
        const group = state.primitiveShapeOverlay.group;
        if (group) group.visible = false;
        state.primitiveShapeOverlay.labels.forEach((label) => { label.hidden = true; });
        return;
    }
    if (state.placement.active) {
        updatePlacementDimensionOverlay();
        return;
    }
    const model = state.selectedModel;
    const overlay = ensurePrimitiveDimensionOverlay();
    const group = state.primitiveShapeOverlay.group;
    const editing = state.primitiveShapeOverlay.editing;
    const editingSelectedShape = editing?.model === model;
    const shapePanelVisible = Boolean(el.shapePanel)
        && !el.shapePanel.classList.contains('panel-user-hidden');
    const dimensionModeActive = state.primitiveShapeOverlay.dimensionMode
        && !state.placement.active;
    const show = isDimensionEditableShapeModel(model)
        && isModelTreeVisible(model)
        && (shapePanelVisible || dimensionModeActive)
        && (!editing || editingSelectedShape);
    group.visible = show;
    if (!show) {
        state.primitiveShapeOverlay.labels.forEach((label) => { label.hidden = true; });
        return;
    }
    const dimensions = getDimensionEditableShapeDimensions(model);
    if (!dimensions) return;
    const rect = el.canvasContainer?.getBoundingClientRect();
    const width = el.primitiveDimensionOverlay?.clientWidth || rect?.width || 0;
    const height = el.primitiveDimensionOverlay?.clientHeight || rect?.height || 0;
    if (isSketchDimensionShapeModel(model)) {
        updateSketchFeatureDimensionOverlay(model, dimensions, {
            group,
            overlay: state.primitiveShapeOverlay,
            editingSelectedShape,
            width,
            height
        });
        return;
    }
    model.updateMatrixWorld(true);
    const type = model.userData.primitiveShapeType;
    const x = dimensions.x, y = dimensions.y, z = dimensions.z;
    const isRoundShape = type === 'cylinder' || type === 'cone';
    const radius = x / 2;
    const diameterReferenceZ = type === 'cone' ? 0 : z;
    const anchors = isRoundShape ? {
        // Cylinders and cones use one diameter annotation instead of separate
        // X/Y annotations. A cone's diameter is explicitly taken from its
        // bottom face; the cylinder uses its top circular face.
        x: {
            source: [new THREE.Vector3(-radius, 0, diameterReferenceZ), new THREE.Vector3(radius, 0, diameterReferenceZ)],
            dimension: [new THREE.Vector3(-radius, -15, diameterReferenceZ), new THREE.Vector3(radius, -15, diameterReferenceZ)]
        },
        y: null,
        z: {
            source: type === 'cone'
                ? [new THREE.Vector3(radius, 0, 0), new THREE.Vector3(0, 0, z)]
                : [new THREE.Vector3(radius, 0, 0), new THREE.Vector3(radius, 0, z)],
            dimension: [new THREE.Vector3(radius + 15, 0, 0), new THREE.Vector3(radius + 15, 0, z)]
        }
    } : {
        // X/Y are measured on the upper face so labels do not sit through the
        // middle of a box and remain readable in the 3D view.
        x: {
            source: [new THREE.Vector3(-x / 2, -y / 2, z), new THREE.Vector3(x / 2, -y / 2, z)],
            dimension: [new THREE.Vector3(-x / 2, -y / 2 - 15, z), new THREE.Vector3(x / 2, -y / 2 - 15, z)]
        },
        y: {
            source: [new THREE.Vector3(-x / 2, -y / 2, z), new THREE.Vector3(-x / 2, y / 2, z)],
            dimension: [new THREE.Vector3(-x / 2 - 15, -y / 2, z), new THREE.Vector3(-x / 2 - 15, y / 2, z)]
        },
        z: {
            source: [new THREE.Vector3(x / 2, y / 2, 0), new THREE.Vector3(x / 2, y / 2, z)],
            dimension: [new THREE.Vector3(x / 2 + 15, y / 2 + 15, 0), new THREE.Vector3(x / 2 + 15, y / 2 + 15, z)]
        }
    };
    Object.entries(anchors).forEach(([axis, anchor]) => {
        const axisGroup = group.children[['x', 'y', 'z'].indexOf(axis)];
        const label = state.primitiveShapeOverlay.labels.get(axis);
        const visible = Boolean(anchor && axisGroup && label);
        if (axisGroup) axisGroup.visible = visible;
        if (label) label.hidden = !visible;
        if (!visible) return;
        const sourceStart = model.localToWorld(anchor.source[0].clone());
        const sourceEnd = model.localToWorld(anchor.source[1].clone());
        const start = model.localToWorld(anchor.dimension[0].clone());
        const end = model.localToWorld(anchor.dimension[1].clone());
        setPrimitiveDimensionAxisVisual(axisGroup, sourceStart, sourceEnd, start, end);
        const midpoint = start.clone().add(end).multiplyScalar(0.5).project(state.camera);
        const left = THREE.MathUtils.clamp((midpoint.x + 1) * 0.5 * width, 42, Math.max(42, width - 42));
        const top = THREE.MathUtils.clamp((1 - midpoint.y) * 0.5 * height, 22, Math.max(22, height - 22));
        label.hidden = false;
        // Repainting can happen while the user is typing or moving the pointer.
        // Keep the active input node intact so a render does not blur it or
        // replace a partially entered value after the first digit.
        if (editingSelectedShape && editing.axis === axis && label.contains(editing.input)) {
            label.style.left = `${left}px`;
            label.style.top = `${top}px`;
            return;
        }
        const labelAxis = isRoundShape && axis === 'x' ? 'Ø' : axis.toUpperCase();
        const labelValue = isRoundShape && axis === 'x' ? dimensions.x : dimensions[axis];
        label.textContent = `${labelAxis} = ${formatJogValue(labelValue)} mm`;
        label.style.left = `${left}px`;
        label.style.top = `${top}px`;
    });
}

function updateSketchFeatureDimensionOverlay(model, dimensions, {
    group,
    overlay,
    editingSelectedShape,
    width,
    height
}) {
    model.updateMatrixWorld(true);
    const x = dimensions.x;
    const y = dimensions.y;
    const z = dimensions.z;
    const anchors = {
        x: {
            source: [new THREE.Vector3(-x / 2, -y / 2, z / 2), new THREE.Vector3(x / 2, -y / 2, z / 2)],
            dimension: [new THREE.Vector3(-x / 2, -y / 2 - 15, z / 2), new THREE.Vector3(x / 2, -y / 2 - 15, z / 2)]
        },
        y: {
            source: [new THREE.Vector3(-x / 2, -y / 2, z / 2), new THREE.Vector3(-x / 2, y / 2, z / 2)],
            dimension: [new THREE.Vector3(-x / 2 - 15, -y / 2, z / 2), new THREE.Vector3(-x / 2 - 15, y / 2, z / 2)]
        },
        z: {
            source: [new THREE.Vector3(x / 2, y / 2, -z / 2), new THREE.Vector3(x / 2, y / 2, z / 2)],
            dimension: [new THREE.Vector3(x / 2 + 15, y / 2 + 15, -z / 2), new THREE.Vector3(x / 2 + 15, y / 2 + 15, z / 2)]
        }
    };
    const placedLabelPositions = [];
    Object.entries(anchors).forEach(([axis, anchor]) => {
        const axisGroup = group.children[['x', 'y', 'z'].indexOf(axis)];
        const label = overlay.labels.get(axis);
        if (!axisGroup || !label) return;
        axisGroup.visible = true;
        const sourceStart = model.localToWorld(anchor.source[0].clone());
        const sourceEnd = model.localToWorld(anchor.source[1].clone());
        const start = model.localToWorld(anchor.dimension[0].clone());
        const end = model.localToWorld(anchor.dimension[1].clone());
        setPrimitiveDimensionAxisVisual(axisGroup, sourceStart, sourceEnd, start, end);
        const midpoint = start.clone().add(end).multiplyScalar(0.5).project(state.camera);
        let left = THREE.MathUtils.clamp((midpoint.x + 1) * 0.5 * width, 42, Math.max(42, width - 42));
        let top = THREE.MathUtils.clamp((1 - midpoint.y) * 0.5 * height, 22, Math.max(22, height - 22));
        for (let attempt = 0; attempt < 12 && placedLabelPositions.some((previous) => (
            Math.abs(left - previous.left) < 92 && Math.abs(top - previous.top) < 28
        )); attempt += 1) {
            top = THREE.MathUtils.clamp(top + 32, 22, Math.max(22, height - 22));
            if (placedLabelPositions.some((previous) => (
                Math.abs(left - previous.left) < 92 && Math.abs(top - previous.top) < 28
            ))) {
                left = THREE.MathUtils.clamp(left + 98, 42, Math.max(42, width - 42));
            }
        }
        placedLabelPositions.push({ left, top });
        label.hidden = false;
        const editing = state.primitiveShapeOverlay.editing;
        if (editingSelectedShape && editing?.axis === axis && label.contains(editing.input)) {
            label.style.left = `${left}px`;
            label.style.top = `${top}px`;
            return;
        }
        label.textContent = `${axis.toUpperCase()} = ${formatJogValue(dimensions[axis])} mm`;
        label.style.left = `${left}px`;
        label.style.top = `${top}px`;
    });
}

function disposePrimitiveDimensionOverlay() {
    const overlay = state.primitiveShapeOverlay;
    overlay.editing = null;
    overlay.dimensionMode = false;
    overlay.labels.forEach((label) => label.remove());
    overlay.labels.clear();
    if (overlay.group) {
        disposeObjectResources(overlay.group);
        overlay.group.removeFromParent();
    }
    overlay.group = null;
}

function beginPlacementDimensionLabelEdit(axis) {
    const placement = state.placement;
    const label = state.primitiveShapeOverlay.labels.get(axis);
    const translation = placement.dimensionTranslation;
    if (!placement.active || !label || !translation
        || !['x', 'y', 'z'].includes(axis) || state.primitiveShapeOverlay.editing) return;
    const input = document.createElement('input');
    input.type = 'number';
    input.step = '0.5';
    input.value = formatJogValue(translation[axis]);
    const target = getPlacementTransformTarget();
    const edit = {
        kind: 'placement',
        axis,
        input,
        model: placement.model,
        beforeTranslation: translation.clone(),
        beforeTransform: capturePlacementModelTransform(target),
        beforePlacementState: {
            previewTranslation: placement.previewTranslation?.clone() || null,
            previewOriginalTransform: placement.previewOriginalTransform,
            previewTransform: placement.previewTransform,
            targetPoint: placement.targetPoint?.clone() || null,
            targetDistance: placement.targetDistance,
            applied: placement.applied
        },
        liveChanged: false,
        historyBefore: !state.historySuspended ? captureSceneSnapshot() : null,
        controlsEnabled: Boolean(state.controls?.enabled),
        transformEnabled: Boolean(state.transformControls?.enabled),
        baseGizmoEnabled: Boolean(state.baseJogTransformControls?.enabled)
    };
    state.primitiveShapeOverlay.editing = edit;
    label.replaceChildren(input);
    state.controls.enabled = false;
    setTransformHandlesEnabled(false);
    setBaseJogGizmoEnabled(false);
    input.addEventListener('input', () => {
        if (!state.placement.active || state.placement.model !== edit.model) return;
        const rawValue = input.value.trim();
        const value = rawValue === '' ? NaN : Number(rawValue);
        if (!Number.isFinite(value)) return;
        const nextTranslation = edit.beforeTranslation.clone();
        nextTranslation[edit.axis] = value;
        if (nextTranslation.distanceToSquared(edit.beforeTranslation) <= 1e-18) return;
        if (applyPlacementDimensionTranslation(nextTranslation)) edit.liveChanged = true;
    });
    input.addEventListener('keydown', (event) => {
        event.stopPropagation();
        if (event.key === 'Enter') {
            event.preventDefault();
            finishGeneratedShapeDimensionLabelEdit(true);
        } else if (event.key === 'Escape') {
            event.preventDefault();
            finishGeneratedShapeDimensionLabelEdit(false);
        }
    });
    input.addEventListener('blur', () => finishGeneratedShapeDimensionLabelEdit(true));
    input.addEventListener('pointerdown', (event) => event.stopPropagation());
    enableHalfStepWheel(input);
    input.focus({ preventScroll: true });
    input.select();
}

function finishPlacementDimensionLabelEdit(edit, apply) {
    state.primitiveShapeOverlay.editing = null;
    let changed = edit.liveChanged;
    if (apply && state.placement.active && state.placement.model === edit.model) {
        const rawValue = edit.input.value.trim();
        const value = rawValue === '' ? NaN : Number(rawValue);
        if (Number.isFinite(value)) {
            const nextTranslation = edit.beforeTranslation.clone();
            nextTranslation[edit.axis] = value;
            if (nextTranslation.distanceToSquared(edit.beforeTranslation) > 1e-18) {
                changed = applyPlacementDimensionTranslation(nextTranslation) || changed;
            }
        } else if (!edit.liveChanged) {
            setMeasurementPanelStatus('이동 치수는 유효한 숫자여야 합니다.');
        }
    } else if (!apply && edit.liveChanged && state.placement.active
        && state.placement.model === edit.model) {
        const target = getPlacementTransformTarget();
        if (target && edit.beforeTransform) restorePlacementModelTransform(target, edit.beforeTransform);
        const beforeState = edit.beforePlacementState;
        state.placement.previewTranslation = beforeState.previewTranslation?.clone() || null;
        state.placement.previewOriginalTransform = beforeState.previewOriginalTransform;
        state.placement.previewTransform = beforeState.previewTransform;
        state.placement.targetPoint = beforeState.targetPoint?.clone() || null;
        state.placement.targetDistance = beforeState.targetDistance;
        state.placement.applied = beforeState.applied;
        updatePlacementDimensionFromTarget();
        changed = false;
    }
    if (apply && changed && edit.historyBefore) {
        recordHistory('모델 변환', edit.historyBefore, captureSceneSnapshot());
    }
    if (state.placement.active && state.placement.model === edit.model) {
        state.controls.enabled = edit.controlsEnabled;
        if (edit.transformEnabled) setTransformHandlesEnabled(true);
        if (edit.baseGizmoEnabled) setBaseJogGizmoEnabled(true);
    }
    updateMeasurementUi();
    updateMeasurementOverlay();
    requestRender();
}

function beginPrimitiveDimensionLabelEdit(axis) {
    const model = state.selectedModel;
    const label = state.primitiveShapeOverlay.labels.get(axis);
    const dimensions = getDimensionEditableShapeDimensions(model);
    if (!isDimensionEditableShapeModel(model) || !label || !dimensions || state.primitiveShapeOverlay.editing) return;
    const input = document.createElement('input');
    input.type = 'number';
    input.min = String(isPrimitiveShapeModel(model) ? PRIMITIVE_SHAPE_LIMITS.min : SKETCH_MIN_SIZE);
    input.max = String(isPrimitiveShapeModel(model) ? PRIMITIVE_SHAPE_LIMITS.max : SKETCH_MAX_SIZE);
    input.step = '0.5';
    input.value = formatJogValue(dimensions[axis]);
    const edit = {
        axis,
        model,
        input,
        beforeDimensions: { ...dimensions },
        historyBefore: !state.historySuspended ? captureSceneSnapshot() : null,
        controlsEnabled: Boolean(state.controls?.enabled),
        transformEnabled: Boolean(state.transformControls?.enabled),
        baseGizmoEnabled: Boolean(state.baseJogTransformControls?.enabled),
        liveChanged: false
    };
    state.primitiveShapeOverlay.editing = edit;
    label.replaceChildren(input);
    state.controls.enabled = false;
    setTransformHandlesEnabled(false);
    setBaseJogGizmoEnabled(false);
    input.addEventListener('input', () => {
        if (state.primitiveShapeOverlay.editing !== edit || !state.models.includes(edit.model)) return;
        const rawValue = input.value.trim();
        if (rawValue === '' || ['-', '.', '-.'].includes(rawValue)) return;
        try {
            const nextDimensions = updateDimensionEditableShapeDimension(
                edit.model,
                edit.beforeDimensions,
                edit.axis,
                rawValue
            );
            const applied = isPrimitiveShapeModel(edit.model)
                ? applyPrimitiveShapeDimensions(edit.model, nextDimensions, {
                    recordHistoryChange: false,
                    status: false
                })
                : applySketchFeatureDimensions(edit.model, nextDimensions, {
                    recordHistoryChange: false,
                    status: false
                });
            if (applied) {
                edit.liveChanged = true;
                if (el.shapeSelectedStatus) el.shapeSelectedStatus.textContent = '';
            }
        } catch (_) {
            if (el.shapeSelectedStatus) {
                el.shapeSelectedStatus.textContent = uiText('도형 치수는 0보다 크고 유효한 숫자여야 합니다.');
            }
        }
    });
    input.addEventListener('keydown', (event) => {
        event.stopPropagation();
        if (event.key === 'Enter') {
            event.preventDefault();
            finishPrimitiveDimensionLabelEdit(true);
        } else if (event.key === 'Escape') {
            event.preventDefault();
            finishPrimitiveDimensionLabelEdit(false);
        }
    });
    input.addEventListener('blur', () => finishPrimitiveDimensionLabelEdit(true));
    input.addEventListener('pointerdown', (event) => event.stopPropagation());
    enableHalfStepWheel(input);
    input.focus({ preventScroll: true });
    input.select();
}

function finishPrimitiveDimensionLabelEdit(apply) {
    const edit = state.primitiveShapeOverlay.editing;
    if (!edit) return;
    if (edit.kind === 'placement') {
        finishPlacementDimensionLabelEdit(edit, apply);
        return;
    }
    state.primitiveShapeOverlay.editing = null;
    let dimensions = null;
    let changed = Boolean(edit.liveChanged);
    if (apply && state.models.includes(edit.model)) {
        try {
            dimensions = updateDimensionEditableShapeDimension(
                edit.model,
                edit.beforeDimensions,
                edit.axis,
                Number(edit.input.value)
            );
        } catch (_) {
            dimensions = null;
        }
    }
    if (dimensions && state.models.includes(edit.model)) {
        changed = (isPrimitiveShapeModel(edit.model)
            ? applyPrimitiveShapeDimensions(edit.model, dimensions, {
                recordHistoryChange: false,
                status: false
            })
            : applySketchFeatureDimensions(edit.model, dimensions, {
                recordHistoryChange: false,
                status: false
            })) || changed;
    } else if (!apply && edit.liveChanged && state.models.includes(edit.model)) {
        if (isPrimitiveShapeModel(edit.model)) {
            applyPrimitiveShapeDimensions(edit.model, edit.beforeDimensions, {
                recordHistoryChange: false,
                status: false
            });
        } else {
            applySketchFeatureDimensions(edit.model, edit.beforeDimensions, {
                recordHistoryChange: false,
                status: false
            });
        }
        changed = false;
    } else if (apply && !dimensions && !edit.liveChanged && el.shapeSelectedStatus) {
        el.shapeSelectedStatus.textContent = uiText('도형 치수는 0보다 크고 유효한 숫자여야 합니다.');
    }
    if (apply && changed && edit.historyBefore) {
        recordHistory('도형 치수 변경', edit.historyBefore, captureSceneSnapshot());
    }
    state.controls.enabled = edit.controlsEnabled;
    if (edit.transformEnabled && state.selectedModel === edit.model) setTransformHandlesEnabled(true);
    if (edit.baseGizmoEnabled && state.selectedModel === edit.model) setBaseJogGizmoEnabled(true);
    renderPrimitiveShapePanel();
    updatePrimitiveDimensionOverlay();
    requestRender();
}

function beginGeneratedShapeDimensionLabelEdit(axis) {
    return beginPrimitiveDimensionLabelEdit(axis);
}

function finishGeneratedShapeDimensionLabelEdit(apply) {
    return finishPrimitiveDimensionLabelEdit(apply);
}

function beginPrimitiveShapeDimensionHistory() {
    if (!state.historySuspended && !state.pendingPrimitiveShapeHistory
        && isDimensionEditableShapeModel(state.selectedModel)) {
        state.pendingPrimitiveShapeHistory = captureSceneSnapshot();
    }
}

function applySelectedPrimitiveShapeDimension(event) {
    const model = state.selectedModel;
    const input = event?.currentTarget;
    const axis = input?.dataset?.shapeSelectedDimension;
    const current = getDimensionEditableShapeDimensions(model);
    if (!isDimensionEditableShapeModel(model) || !current || !['x', 'y', 'z'].includes(axis)) return;
    if (input.value.trim() === '' || ['-', '.', '-.'].includes(input.value.trim())) return;
    beginPrimitiveShapeDimensionHistory();
    try {
        const dimensions = updateDimensionEditableShapeDimension(
            model,
            current,
            axis,
            input.value
        );
        applyDimensionEditableShapeDimensions(model, dimensions, {
            recordHistoryChange: false,
            status: false
        });
        if (el.shapeSelectedStatus) el.shapeSelectedStatus.textContent = '';
    } catch (_) {
        if (el.shapeSelectedStatus) el.shapeSelectedStatus.textContent = uiText('도형 치수는 0보다 크고 유효한 숫자여야 합니다.');
    }
}

function commitSelectedPrimitiveShapeDimension(event) {
    applySelectedPrimitiveShapeDimension(event);
    finishSelectedPrimitiveShapeDimension();
}

function finishSelectedPrimitiveShapeDimension() {
    commitPendingHistory('도형 치수 변경', 'pendingPrimitiveShapeHistory');
    renderPrimitiveShapePanel();
    updatePrimitiveDimensionOverlay();
}

function setupScene() {
    state.scene = new THREE.Scene();
    state.scene.background = new THREE.Color(0x0b0e14);
    state.camera = new THREE.PerspectiveCamera(45, el.canvasContainer.clientWidth / el.canvasContainer.clientHeight, 0.1, 1e7);
    state.camera.up.set(0, 0, 1);
    state.camera.position.set(1400, -1400, 1000);
    state.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    state.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    state.renderer.setSize(el.canvasContainer.clientWidth, el.canvasContainer.clientHeight);
    state.renderer.shadowMap.enabled = true;
    state.renderer.toneMapping = THREE.ReinhardToneMapping;
    state.renderer.toneMappingExposure = 2.3;
    el.canvasContainer.appendChild(state.renderer.domElement);
    state.renderer.domElement.addEventListener('mousedown', preventMiddleButtonAutoscroll, { capture: true });

    state.grid = new THREE.GridHelper(10000, 100, 0x475569, 0x1e293b);
    state.grid.rotateX(Math.PI / 2);
    // Keep the reference grid on the world XY plane. Render it first without
    // writing depth so opaque model surfaces always cover it, even when a
    // model's floor is coplanar with the grid.
    state.grid.position.z = 0;
    state.grid.renderOrder = -100;
    const gridMaterials = Array.isArray(state.grid.material) ? state.grid.material : [state.grid.material];
    gridMaterials.forEach((material) => {
        material.depthTest = true;
        material.depthWrite = false;
    });
    state.scene.add(state.grid);

    state.baseAxes = new THREE.AxesHelper(280);
    state.baseAxes.name = 'Viewer Base Coordinate';
    applyAxesHelperColors(state.baseAxes);
    const baseAxisMaterials = Array.isArray(state.baseAxes.material) ? state.baseAxes.material : [state.baseAxes.material];
    baseAxisMaterials.forEach((material) => {
        material.depthTest = false;
        material.transparent = true;
    });
    state.baseAxes.renderOrder = 20;
    state.scene.add(state.baseAxes);
    addGridLabels();
    state.collision.system = new MeshCollisionSystem({
        // The imported coordinates are millimetres.  This tolerance is small
        // enough for STL contact while avoiding floating point chatter.
        epsilon: 1e-4,
        leafSize: 16
    });
    updateWorkObjectVisuals();
    updateInterferenceZoneVisuals();
    refreshViewPresetsUi();
}

function preventMiddleButtonAutoscroll(event) {
    if (event.button === 1) event.preventDefault();
}

function trackMainOrbitControlPointer(event) {
    if (event?.pointerId !== undefined) state.orbitControlPointerIds.add(event.pointerId);
}

function clearMainOrbitControlPointer(event) {
    if (event?.pointerId !== undefined) state.orbitControlPointerIds.delete(event.pointerId);
}

function resetMainOrbitControlInteraction() {
    const canvas = state.renderer?.domElement;
    if (!canvas) return;

    // OrbitControls keeps its active pointer state in a private closure. If a
    // sketch gesture is interrupted while the canvas still owns a pointer,
    // release it through the same pointerup path OrbitControls uses so the
    // next normal 3D drag cannot inherit ROTATE/PAN/DOLLY state.
    const pointerIds = [...state.orbitControlPointerIds];
    pointerIds.forEach((pointerId) => {
        if (typeof PointerEvent === 'function') {
            canvas.dispatchEvent(new PointerEvent('pointerup', {
                pointerId,
                pointerType: 'mouse',
                isPrimary: true,
                button: -1,
                buttons: 0,
                clientX: 0,
                clientY: 0
            }));
        }
        try {
            if (canvas.hasPointerCapture?.(pointerId)) canvas.releasePointerCapture(pointerId);
        } catch { }
    });
    state.orbitControlPointerIds.clear();
    state.sceneSelectionPointer = null;
    state.sceneContextPointer = null;
    state.suppressNextSceneContextMenu = false;
    if (state.viewNavigationActive) endSimulationViewNavigation();
}

function restoreMain3DViewAfterSketch(previousCamera, previousControls, restoreCamera = true) {
    if (!state.camera || !state.renderer?.domElement) return;

    const previousCameraObject = state.sketch.previousCameraObject;
    if (previousCameraObject && state.camera !== previousCameraObject) {
        state.camera = previousCameraObject;
    }

    const currentTarget = state.controls?.target?.clone() || new THREE.Vector3();
    const target = restoreCamera && previousCamera?.target
        ? previousCamera.target.clone()
        : currentTarget;
    const cameraUp = previousCamera?.up?.clone() || new THREE.Vector3(0, 0, 1);
    if (cameraUp.lengthSq() <= Number.EPSILON) cameraUp.set(0, 0, 1);
    else cameraUp.normalize();

    // Apply the normal 3D camera basis before constructing OrbitControls. The
    // controller captures camera.up internally, so changing the up axis after
    // construction leaves sketch X-up navigation in the next 3D view.
    state.camera.up.copy(cameraUp);
    if (restoreCamera && previousCamera) {
        state.camera.position.copy(previousCamera.position);
        state.camera.zoom = previousCamera.zoom;
        state.camera.fov = previousCamera.fov;
        state.camera.lookAt(target);
    }
    state.camera.updateProjectionMatrix();

    const restoredControls = {
        ...(previousControls || captureMainOrbitControlState(state.controls) || {}),
        enabled: true,
        enableRotate: true,
        enablePan: true,
        enableZoom: true,
        enableDamping: false,
        // Match the deployed 3D viewer: vertical right-drag pans in screen
        // space instead of being reinterpreted through the Z-up world basis.
        screenSpacePanning: true,
        mouseButtons: {
            LEFT: THREE.MOUSE.ROTATE,
            MIDDLE: THREE.MOUSE.DOLLY,
            RIGHT: THREE.MOUSE.PAN
        },
        touches: {
            ONE: THREE.TOUCH.ROTATE,
            TWO: THREE.TOUCH.DOLLY_PAN
        },
        zoomToCursor: false,
        target
    };
    recreateMainOrbitControls(restoredControls);
    state.controls.target.copy(target);
    state.controls.update();
}

function findSceneModelAncestor(object) {
    for (let current = object; current; current = current.parent) {
        if (state.models.includes(current)) return current;
    }
    return null;
}

function findSceneModelPartAncestor(object, model) {
    const parts = getImportedModelParts(model);
    if (!parts.length) return null;
    for (let current = object; current && current !== model; current = current.parent) {
        if (parts.includes(current)) return current;
    }
    return null;
}

function getSelectedModelTransformTarget() {
    const model = state.selectedModel;
    const part = state.selectedModelPart;
    return model && part && getImportedModelParts(model).includes(part) ? part : model;
}

function getPlacementTransformTarget() {
    const placement = state.placement;
    const model = placement.model;
    const target = placement.target;
    return model && target
        && (target === model || getImportedModelParts(model).includes(target))
        ? target
        : model;
}

function syncActivePlacementTargetToSelection() {
    const placement = state.placement;
    if (!placement.active || placement.model !== state.selectedModel) return;
    const nextTarget = getSelectedModelTransformTarget();
    if (!nextTarget || placement.target === nextTarget) return;
    const hadPlacementPoints = Boolean(
        placement.sourcePoint || placement.directionPoint
    );
    restorePlacementPreview();
    placement.target = nextTarget;
    capturePlacementDimensionOrigin();
    if (hadPlacementPoints) resetPlacementSelection();
    else updateMeasurementUi();
    if (state.transformControls?.enabled) attachTransformControlsToSelectedModel();
}

function handleSceneModelPointerDown(event) {
    if (event.button !== 0) return;
    state.sceneSelectionPointer = {
        pointerId: event.pointerId,
        x: event.clientX,
        y: event.clientY,
        moved: false
    };
}

function handleSceneModelPointerMove(event) {
    const pointer = state.sceneSelectionPointer;
    if (!pointer || pointer.pointerId !== event.pointerId) return;
    const dx = event.clientX - pointer.x;
    const dy = event.clientY - pointer.y;
    if (dx * dx + dy * dy > 16) pointer.moved = true;
}

function handleSceneModelPointerCancel(event) {
    const pointer = state.sceneSelectionPointer;
    if (!pointer || pointer.pointerId === event.pointerId) state.sceneSelectionPointer = null;
}

function handleSceneContextPointerDown(event) {
    if (event.button !== 2 || state.sketch.active) return;
    state.suppressNextSceneContextMenu = false;
    state.sceneContextPointer = {
        pointerId: event.pointerId,
        x: event.clientX,
        y: event.clientY,
        moved: false
    };
}

function handleSceneContextPointerMove(event) {
    const pointer = state.sceneContextPointer;
    if (!pointer || pointer.pointerId !== event.pointerId) return;
    const dx = event.clientX - pointer.x;
    const dy = event.clientY - pointer.y;
    if (dx * dx + dy * dy > 16) pointer.moved = true;
}

function handleSceneContextPointerUp(event) {
    const pointer = state.sceneContextPointer;
    if (!pointer || pointer.pointerId !== event.pointerId) return;
    if (pointer.moved) state.suppressNextSceneContextMenu = true;
    state.sceneContextPointer = null;
}

function handleSceneContextPointerCancel(event) {
    const pointer = state.sceneContextPointer;
    if (!pointer || pointer.pointerId !== event.pointerId) return;
    state.sceneContextPointer = null;
    state.suppressNextSceneContextMenu = false;
}

function suppressSceneContextMenuAfterViewDrag(event) {
    const pointer = state.sceneContextPointer;
    const shouldSuppress = Boolean(
        state.suppressNextSceneContextMenu
        || pointer?.moved
    );
    if (!shouldSuppress) return false;
    event.preventDefault();
    event.stopImmediatePropagation();
    state.sceneContextPointer = null;
    state.suppressNextSceneContextMenu = false;
    closeModelContextMenu();
    return true;
}

function isSceneModelObjectPickable(object, model) {
    if (!object || !model || !isModelTreeVisible(model)) return false;
    for (let current = object; current; current = current.parent) {
        if (current.visible === false) return false;
        if (current === model) return true;
    }
    return false;
}

function getSceneModelAtPointer(event) {
    const rect = state.renderer?.domElement?.getBoundingClientRect();
    if (!rect || rect.width <= 0 || rect.height <= 0) return null;
    const pointerNdc = new THREE.Vector2(
        ((event.clientX - rect.left) / rect.width) * 2 - 1,
        -((event.clientY - rect.top) / rect.height) * 2 + 1
    );
    state.camera.updateMatrixWorld(true);
    state.sceneSelectionRaycaster.setFromCamera(pointerNdc, state.camera);
    const modelRoots = state.models.filter((model) => (
        isModelTreeVisible(model)
        || getModelTreeAttachedModels(model).some((attached) => attached.visible !== false)
    ));
    const intersections = state.sceneSelectionRaycaster.intersectObjects(modelRoots, true);
    return intersections.map(({ object }) => {
        const model = findSceneModelAncestor(object);
        if (!isSceneModelObjectPickable(object, model)) return null;
        return {
            model,
            part: findSceneModelPartAncestor(object, model)
        };
    }).find((selection) => selection && (selection.part || getImportedModelParts(selection.model).length <= 1)) || null;
}

function handleSceneModelClick(event) {
    const pointer = state.sceneSelectionPointer;
    state.sceneSelectionPointer = null;
    if (event.button !== 0
        || state.sketch.active
        || pointer?.moved
        || isSimulationSnapInteractionActive()
        || state.zeroPointEdit.active
        || state.viewNavigationActive
        || state.transformControls?.dragging
        || state.baseJogGizmoDragging
        || state.zeroPointEdit.transformControls?.dragging) return;

    const selection = getSceneModelAtPointer(event);
    if (!selection) return;
    if (selection.part) selectSceneModelPart(selection.model, selection.part);
    else selectSceneModel(selection.model);
}

function handleSceneModelContextMenu(event) {
    if (suppressSceneContextMenuAfterViewDrag(event)) return;
    event.preventDefault();
    const selection = getSceneModelAtPointer(event);
    if (!selection) {
        closeModelContextMenu();
        return;
    }
    if (selection.part) selectSceneModelPart(selection.model, selection.part);
    else selectSceneModel(selection.model);
    openModelContextMenu(event, selection.model, selection.part);
}

function handleCanvasContainerContextMenu(event) {
    const container = el.canvasContainer;
    const canvas = state.renderer?.domElement;
    const target = event.target;
    if (!container || !canvas || !container.contains(target)) return;

    // The canvas is not the only element layered over the 3D view. When a
    // marker or a non-interactive overlay is under the pointer, the event can
    // target that element instead of the renderer canvas and the renderer's
    // context-menu listener is skipped. Delegate those scene-area events from
    // the container so the browser menu cannot leak through.
    if (target?.closest?.(
        'aside, section, dialog, .primitive-dimension-overlay, .simulation-snap-marker, .collision-status, #sketch-workbench'
    )) return;
    const interactiveTarget = target?.closest?.(
        'button, input, select, textarea, a, summary, [contenteditable="true"], [data-panel-drag-ignore]'
    );
    if (interactiveTarget && interactiveTarget !== canvas) return;

    event.preventDefault();
    event.stopPropagation();
    handleSceneModelContextMenu(event);
}

function updateModelRenderComplexity(model) {
    let triangleCount = 0;
    model.traverse((child) => {
        if (!child.isMesh) return;
        const position = child.geometry?.getAttribute('position');
        const elementCount = child.geometry?.index?.count ?? position?.count ?? 0;
        triangleCount += Math.floor(elementCount / 3);
    });

    model.userData.renderTriangleCount = triangleCount;
    model.userData.largeModelMode = Boolean(
        model.userData.largeModelMode
        || Number(model.userData.sourceFileSize) >= LARGE_MODEL_PERFORMANCE_MIN_BYTES
        || triangleCount >= LARGE_MODEL_PERFORMANCE_MIN_TRIANGLES
    );
}

function updateLargeModelPerformanceMode() {
    const enabled = state.models.some((model) => (
        model.userData.largeModelMode && isModelTreeVisible(model)
    ));
    if (state.largeModelPerformanceMode === enabled || !state.renderer) return;
    state.largeModelPerformanceMode = enabled;
    state.renderer.shadowMap.enabled = !enabled;
    state.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, enabled ? 1 : 2));
    state.renderer.setSize(el.canvasContainer.clientWidth, el.canvasContainer.clientHeight);
}

function collisionModelLabel(model) {
    return model?.userData?.motionDisplayName
        || model?.userData?.modelName
        || model?.name
        || '3D Model';
}

function getCollisionMaterials(mesh) {
    if (!mesh?.isMesh) return [];
    return Array.isArray(mesh.material) ? mesh.material.filter(Boolean) : mesh.material ? [mesh.material] : [];
}

function setCollisionMaterialHighlight(material, enabled) {
    const snapshots = state.collision.highlightedMaterials;
    const snapshot = snapshots.get(material);
    if (enabled) {
        if (snapshot) return;
        snapshots.set(material, {
            color: material.color?.clone?.() || null,
            emissive: material.emissive?.clone?.() || null,
            emissiveIntensity: Number.isFinite(material.emissiveIntensity)
                ? material.emissiveIntensity
                : null
        });
        material.color?.setHex(0xef4444);
        material.emissive?.setHex(0x7f1d1d);
        if ('emissiveIntensity' in material) material.emissiveIntensity = 0.9;
        return;
    }
    if (!snapshot) return;
    if (snapshot.color && material.color) material.color.copy(snapshot.color);
    if (snapshot.emissive && material.emissive) material.emissive.copy(snapshot.emissive);
    if (snapshot.emissiveIntensity !== null && 'emissiveIntensity' in material) {
        material.emissiveIntensity = snapshot.emissiveIntensity;
    }
    snapshots.delete(material);
}

function collectCollisionHighlightMaterials(result) {
    const materials = new Set();
    const attachedTools = new Set();
    asCollisionResults(result).forEach((hit) => {
        getCollisionMaterials(hit.meshA).forEach((material) => materials.add(material));
        getCollisionMaterials(hit.meshB).forEach((material) => materials.add(material));
        if (hit.objectA?.userData?.attachmentHost) attachedTools.add(hit.objectA);
        if (hit.objectB?.userData?.attachmentHost) attachedTools.add(hit.objectB);
    });

    // A Tool import often contains several independently coloured meshes.
    // checkAll() intentionally retains one precise contact per robot link for
    // motion performance, so colouring only that representative mesh can
    // leave another visibly colliding Tool part green. Once a Tool is part of
    // a collision pair, show the complete Tool assembly in red without adding
    // another expensive mesh-pair scan. De-duplicate each Tool and material so
    // a multi-link collision never traverses or updates the same assembly more
    // than once.
    attachedTools.forEach((model) => {
        model.traverse((child) => {
            if (!child.isMesh || child.userData?.collisionDisabled) return;
            getCollisionMaterials(child).forEach((material) => materials.add(material));
        });
    });
    return materials;
}

function syncCollisionHighlight(result) {
    const desiredMaterials = collectCollisionHighlightMaterials(result);
    [...state.collision.highlightedMaterials.keys()].forEach((material) => {
        if (!desiredMaterials.has(material)) setCollisionMaterialHighlight(material, false);
    });
    desiredMaterials.forEach((material) => setCollisionMaterialHighlight(material, true));
}

function clearCollisionHighlight() {
    [...state.collision.highlightedMaterials.keys()]
        .forEach((material) => setCollisionMaterialHighlight(material, false));
}

function setCollisionDebugForModel(model, enabled) {
    if (!model) return;
    const meshes = [];
    model.traverse((child) => {
        if (child.isMesh && !child.userData.collisionDebugMesh && !child.userData.collisionDisabled) {
            meshes.push(child);
        }
    });
    meshes.forEach((mesh) => {
        const existing = state.collision.debugLines.get(mesh);
        if (enabled) {
            if (existing || !mesh.geometry) return;
            const material = new THREE.LineBasicMaterial({
                color: 0x38bdf8,
                transparent: true,
                opacity: 0.28,
                depthTest: false,
                depthWrite: false
            });
            const line = new THREE.LineSegments(new THREE.WireframeGeometry(mesh.geometry), material);
            line.name = `${mesh.name || 'Mesh'} collision wireframe`;
            line.userData.collisionDebugMesh = true;
            line.renderOrder = 19;
            line.frustumCulled = false;
            // Parent the visualizer to the actual mesh so all local transforms,
            // joint rotations and TCP attachment transforms are inherited.
            mesh.add(line);
            state.collision.debugLines.set(mesh, line);
        } else if (existing) {
            existing.removeFromParent();
            existing.geometry?.dispose?.();
            existing.material?.dispose?.();
            state.collision.debugLines.delete(mesh);
        }
    });
}

function refreshCollisionDebugOverlays() {
    state.models.forEach((model) => setCollisionDebugForModel(model, state.collision.debugVisible));
}

function disposeCollisionDebugForModel(model) {
    state.collision.safeRobotAngles.delete(model);
    model?.traverse?.((child) => {
        const line = state.collision.debugLines.get(child);
        if (!line) return;
        line.removeFromParent();
        line.geometry?.dispose?.();
        line.material?.dispose?.();
        state.collision.debugLines.delete(child);
    });
}

function normalizeCollisionMode(value, legacyEnabled = false) {
    return COLLISION_MODE_CYCLE.includes(value)
        ? value
        : legacyEnabled ? COLLISION_MODE.STOP : COLLISION_MODE.OFF;
}

function setCollisionModeState(value, legacyEnabled = false) {
    const mode = normalizeCollisionMode(value, legacyEnabled);
    state.collision.mode = mode;
    state.collision.enabled = mode !== COLLISION_MODE.OFF;
    return mode;
}

function collisionStopsMotion() {
    return state.collision.mode === COLLISION_MODE.STOP;
}

function nextCollisionMode() {
    const currentMode = normalizeCollisionMode(state.collision.mode, state.collision.enabled);
    const currentIndex = COLLISION_MODE_CYCLE.indexOf(currentMode);
    return COLLISION_MODE_CYCLE[(currentIndex + 1) % COLLISION_MODE_CYCLE.length];
}

function collisionModeActionText(mode) {
    if (mode === COLLISION_MODE.OFF) return '충돌 감지 켜기';
    if (mode === COLLISION_MODE.STOP) return '충돌 감지 표시만';
    return '충돌 감지 끄기';
}

function updateCollisionUi() {
    const mode = setCollisionModeState(state.collision.mode, state.collision.enabled);
    const enabledButton = el.btnToggleCollision;
    if (enabledButton) {
        const actionText = collisionModeActionText(mode);
        enabledButton.classList.toggle('active', mode !== COLLISION_MODE.OFF);
        enabledButton.setAttribute('aria-pressed', String(mode !== COLLISION_MODE.OFF));
        enabledButton.dataset.collisionMode = mode;
        enabledButton.title = uiText(actionText);
        enabledButton.setAttribute('aria-label', uiText(actionText));
    }
}

function setCollisionMode(value, { announce = true, persist = true } = {}) {
    const mode = setCollisionModeState(value, state.collision.enabled);
    clearCollisionStopNotice();
    if (mode === COLLISION_MODE.OFF) {
        state.collision.lastResult = null;
        updateCollisionStatus(resolveCollisionVisualResult(null, { immediate: true }));
        if (announce) setStatus('충돌 감지 끄기', '#f59e0b');
    } else {
        if (announce) {
            setStatus(
                mode === COLLISION_MODE.DISPLAY ? '충돌 감지 표시만' : '충돌 감지 켜기',
                mode === COLLISION_MODE.DISPLAY ? '#f59e0b' : '#22c55e'
            );
        }
        checkSceneCollisions({ force: true });
    }
    updateCollisionUi();
    requestRender();
    if (persist) scheduleMotionProjectSave();
    return mode;
}

function enableControllerGripCollisionWarning() {
    if (state.collision.mode !== COLLISION_MODE.OFF && state.collision.enabled) return false;
    // Grip inference consumes the same collision results as the warning
    // banner. Enable warning-only detection so controller input can pick or
    // release an object without turning the controller into a motion stop
    // interlock.
    setCollisionMode(COLLISION_MODE.DISPLAY, { announce: false, persist: false });
    return true;
}

function collisionResultKey(result) {
    if (!result?.meshA?.uuid || !result?.meshB?.uuid) return '';
    return [result.meshA.uuid, result.meshB.uuid].sort().join(':');
}

function asCollisionResults(result) {
    if (Array.isArray(result)) return result.filter(Boolean);
    return result ? [result] : [];
}

function cancelCollisionVisualClearTimer() {
    if (!state.collision.visualClearTimer) return;
    window.clearTimeout(state.collision.visualClearTimer);
    state.collision.visualClearTimer = null;
}

function resolveCollisionVisualResult(result, {
    now = performance.now(),
    immediate = false
} = {}) {
    const results = asCollisionResults(result);
    if (results.length) {
        cancelCollisionVisualClearTimer();
        state.collision.lastVisualHitAt = now;
        return results;
    }

    const previousResults = asCollisionResults(state.collision.lastVisualResult);
    if (immediate || !previousResults.length || state.collision.stopNotice) {
        cancelCollisionVisualClearTimer();
        state.collision.lastVisualHitAt = 0;
        return null;
    }

    const remaining = COLLISION_VISUAL_CLEAR_DELAY_MS - (now - state.collision.lastVisualHitAt);
    if (remaining <= 0) {
        cancelCollisionVisualClearTimer();
        state.collision.lastVisualHitAt = 0;
        return null;
    }

    // A single boundary miss used to flash every material back to its base
    // colour and red again on the following scan. Keep only the visual state
    // latched briefly; motion logic still receives the raw empty result.
    if (!state.collision.visualClearTimer) {
        state.collision.visualClearTimer = window.setTimeout(() => {
            state.collision.visualClearTimer = null;
            if (asCollisionResults(state.collision.lastResult).length || state.collision.stopNotice) return;
            state.collision.lastVisualHitAt = 0;
            state.collision.lastResult = null;
            updateCollisionStatus(resolveCollisionVisualResult(null, { immediate: true }));
            requestRender();
        }, Math.ceil(remaining));
    }
    return previousResults;
}

function collisionResultsKey(result) {
    return asCollisionResults(result)
        .map(collisionResultKey)
        .filter(Boolean)
        .sort()
        .join('|');
}

function updateCollisionStatus(result = null) {
    const results = asCollisionResults(result);
    const status = el.collisionStatus;
    if (!results.length) {
        // A stopped program remains at its collision pose. Keep every active
        // collision highlighted until the user moves away or restarts motion
        // from that breakpoint.
        const stopResults = asCollisionResults(state.collision.stopNotice?.result);
        if (stopResults.length) {
            if (collisionResultsKey(state.collision.lastVisualResult) !== collisionResultsKey(stopResults)) {
                updateCollisionStatus(stopResults);
            }
            return;
        }
        if (status) {
            status.classList.add('hidden');
            const label = status.querySelector('span');
            if (label) label.textContent = '';
        }
        clearCollisionHighlight();
        const currentText = String(state.viewerStatus?.text || '');
        if (state.viewerStatus?.color === '#ef4444' && currentText.includes('충돌')) {
            setStatus('Ready', '#22c55e');
        }
        state.collision.lastVisualResult = null;
        state.collision.lastStatusKey = '';
        return;
    }

    const primary = results[0];
    const leftName = collisionModelLabel(primary.objectA);
    const rightName = collisionModelLabel(primary.objectB);
    const statusKey = collisionResultsKey(results);
    const sameCollision = state.collision.lastStatusKey === statusKey;
    if (!sameCollision) syncCollisionHighlight(results);
    state.collision.lastVisualResult = results;
    const collisionMessage = '충돌 감지: {left} ↔ {right}';
    const collisionReplacements = {
        left: leftName,
        right: rightName
    };
    if (status) {
        if (status.classList.contains('hidden')) status.classList.remove('hidden');
        const label = status.querySelector('span');
        const nextLabel = uiFormat(collisionMessage, collisionReplacements);
        if (label && label.textContent !== nextLabel) label.textContent = nextLabel;
    }
    const viewerAlreadyShowsCollision = state.viewerStatus?.color === '#ef4444'
        && String(state.viewerStatus.text || '').includes('충돌');
    // Import/model-load success messages can arrive after the collision pair
    // was already cached. Restore the red viewer state even for the same pair.
    // A latched stop uses its more specific "motion stopped" message below.
    if (state.collision.lastStatusKey !== statusKey
        || (!viewerAlreadyShowsCollision && !state.collision.stopNotice)) {
        state.collision.lastStatusKey = statusKey;
        setStatus(collisionMessage, '#ef4444', collisionReplacements);
    }
}

function latchCollisionStopNotice(result, message) {
    const results = asCollisionResults(result);
    if (!results.length) return;
    state.collision.stopNotice = { result: results, message };
    updateCollisionStatus(results);
    setStatus(message, '#ef4444');
}

function clearCollisionStopNotice({ resetViewerStatus = true } = {}) {
    state.collision.stopNotice = null;
    state.collision.ignoredMotionCollisionKeys.clear();
    const currentText = String(state.viewerStatus?.text || '');
    if (resetViewerStatus && state.viewerStatus?.color === '#ef4444' && currentText.includes('충돌')) {
        setStatus('Ready', '#22c55e');
    }
}

function clearJogCollisionLock() {
    // JOG is an interactive simulation control. It may enter a collision pose,
    // but collision detection must never reject or roll back that pose.
    // Release a previous program-stop latch without clearing the visible
    // collision state. The next fresh scan decides whether the collision is
    // gone; if it is still present, the same red alert remains latched.
    clearCollisionStopNotice({ resetViewerStatus: false });

    // Queue a normal pass immediately, then guarantee one fresh pass after the
    // throttling window. Do not force a triangle scan for every slider/pointer
    // event; the trailing pass coalesces rapid input without reintroducing the
    // JOG lag.
    requestRender();
    if (state.collision.jogRefreshTimer !== null) {
        clearTimeout(state.collision.jogRefreshTimer);
    }
    const refreshDelay = Math.max(16, Number(state.collision.minCheckIntervalMs) + 16);
    state.collision.jogRefreshTimer = setTimeout(() => {
        state.collision.jogRefreshTimer = null;
        requestRender();
    }, refreshDelay);
}

function getCollisionModels() {
    // MeshCollisionSystem records one representative collision per left mesh
    // and model pair. Put articulated links and their Tool first so every
    // colliding robot part retains red feedback without repeatedly testing
    // against each CAD sub-mesh of the same obstacle.
    const priority = (model) => {
        if (model?.userData?.tcpFrame) return 0;
        if (model?.userData?.attachmentHost) return 1;
        return 2;
    };
    return state.models
        .filter((model) => isModelTreeVisible(model) && model.userData?.collisionEnabled !== false)
        .sort((left, right) => priority(left) - priority(right));
}

function markSceneCollisionDirty(model = null) {
    const collision = state.collision;
    collision.dirty = true;
    if (!model) {
        // No root was supplied when the scene structure changed. The next
        // pass must therefore refresh every model pair.
        collision.dirtyRoots.clear();
        return;
    }

    collision.dirtyRoots.add(model);
    const hostRobot = model.userData?.attachmentHost || (model.userData?.tcpFrame ? model : null);
    if (!hostRobot) return;
    collision.dirtyRoots.add(hostRobot);
    // TCP-mounted Tools have their own collision roots but inherit every
    // joint pose from the robot. Mark them with the robot so their cached
    // root-pair results cannot survive a JOG or program move.
    state.models.forEach((candidate) => {
        if (candidate.userData?.attachmentHost === hostRobot) collision.dirtyRoots.add(candidate);
    });
}

function collisionInvolvesRobot(result, robot) {
    if (!robot) return false;
    return asCollisionResults(result).some((hit) => (
        [hit.objectA, hit.objectB].some((object) => (
            object === robot || object?.userData?.attachmentHost === robot
        ))
    ));
}

function releaseClearedMotionCollisionIgnores(result) {
    const activeKeys = new Set(asCollisionResults(result).map(collisionResultKey).filter(Boolean));
    state.collision.ignoredMotionCollisionKeys.forEach((key) => {
        if (!activeKeys.has(key)) state.collision.ignoredMotionCollisionKeys.delete(key);
    });
}

function getBlockingMotionCollision(result) {
    return asCollisionResults(result).find((hit) => (
        !state.collision.ignoredMotionCollisionKeys.has(collisionResultKey(hit))
    )) || null;
}

function checkSceneCollisions({ force = false } = {}) {
    if (!state.collision.enabled || !state.collision.system || state.collision.checking) {
        if (!state.collision.enabled) {
            state.collision.lastCheckSkipped = true;
            state.collision.lastResult = null;
            updateCollisionStatus(resolveCollisionVisualResult(null, { immediate: true }));
        }
        return null;
    }
    if (!force && !state.collision.dirty) {
        state.collision.lastCheckSkipped = true;
        return state.collision.lastResult;
    }
    const now = performance.now();
    if (!force
        && state.collision.lastCheckAt > 0
        && now - state.collision.lastCheckAt < state.collision.minCheckIntervalMs) {
        state.collision.lastCheckSkipped = true;
        return state.collision.lastResult;
    }
    state.collision.checking = true;
    state.collision.lastCheckSkipped = false;
    state.collision.lastCheckAt = now;
    try {
        const collisionModels = getCollisionModels();
        const changedRoots = new Set(
            [...state.collision.dirtyRoots].filter((root) => collisionModels.includes(root))
        );
        if (!force && changedRoots.size > 0) {
            changedRoots.forEach((root) => {
                if (typeof root.updateWorldMatrix === 'function') root.updateWorldMatrix(true, true);
                else root.updateMatrixWorld(true);
            });
        } else {
            state.scene?.updateMatrixWorld(true);
        }
        if (force) state.collision.system.prepare(collisionModels);
        const result = force || changedRoots.size === 0
            ? state.collision.system.checkAll(collisionModels, { allowWarmHitReuse: false })
            : state.collision.system.checkAll(collisionModels, { changedRoots, allowWarmHitReuse: true });
        state.collision.dirty = false;
        state.collision.dirtyRoots.clear();
        state.collision.lastResult = result;
        updateCollisionStatus(resolveCollisionVisualResult(result, { now, immediate: force }));
        return result;
    } catch (error) {
        console.warn('Mesh collision check failed:', error);
        state.collision.dirty = false;
        state.collision.dirtyRoots.clear();
        const wasReported = state.collision.lastStatusKey === 'error';
        state.collision.lastResult = null;
        updateCollisionStatus(resolveCollisionVisualResult(null, { immediate: true }));
        if (!wasReported) {
            state.collision.lastStatusKey = 'error';
            setStatus('충돌 검사 오류', '#f59e0b');
        }
        return null;
    } finally {
        state.collision.checking = false;
    }
}

function captureCollisionSafeRobotPoses() {
    if (!state.collision.enabled) return;
    getArticulatedRobots().forEach((robot) => {
        state.collision.safeRobotAngles.set(robot, robot.userData.joints.map((joint) => joint.angle));
    });
}

function restoreCollisionSafeRobotPoses(robots = getArticulatedRobots()) {
    robots.forEach((robot) => {
        const safeAngles = state.collision.safeRobotAngles.get(robot);
        if (!safeAngles || !robot.userData?.joints) return;
        safeAngles.forEach((angle, index) => setJointAngle(robot.userData.joints[index], angle, false));
        robot.updateMatrixWorld(true);
        if (robot === state.activeArticulatedModel) {
            syncJointControls(robot);
            captureCurrentTcpTarget(robot);
            updateTcpPresentation(robot);
        }
    });
}

function isLazySimulationSnapMesh(mesh) {
    return Boolean(mesh?.userData.largeModelMode && mesh.userData.largeModelChunk);
}

function getSimulationSnapModels(scope = 'scene') {
    if (scope === 'zero') {
        const model = state.zeroPointEdit.model;
        return isSimulationSnapModel(model) && isModelTreeVisible(model) ? [model] : [];
    }
    if (scope === 'placement') {
        // Placement must snap against the complete scene. Exclude only the
        // model currently being moved after P1 is selected. During the first
        // point selection, the moving model is also available so its own
        // reference point can be used as P1.
        const movingModel = state.placement.model;
        return getSimulationSnapModels('scene').filter((model) => (
            model !== movingModel || !state.placement.sourcePoint
        ));
    }
    if (scope === 'measurement') {
        // Measurement can target robot geometry and every visible scene model.
        // Attached tools/loads are already part of their host robot hierarchy;
        // keeping only top-level roots avoids duplicate snap candidates.
        return state.models.filter((model) => {
            const host = model.userData?.attachmentHost;
            const attachedVisible = getModelTreeAttachedModels(model)
                .some((attached) => attached.visible !== false);
            return (isModelTreeVisible(model) || attachedVisible)
                && (!host || !state.models.includes(host));
        });
    }
    if (scope === 'interference') return getSimulationSnapModels('scene');
    if (scope === 'scene') {
        const sceneModels = state.models.filter((model) => isSimulationSnapModel(model)
            && model.userData.placement === 'scene'
            && isModelTreeVisible(model));
        // Snap move can target the robot's fixed J1 base center as well as
        // uploaded scene models and generated primitive shapes. Robot links
        // are included here so the normal face-selection flow can enter the
        // base-center snap context.
        const robotModels = getArticulatedRobots().filter((robot) => isModelTreeVisible(robot));
        return [...sceneModels, ...robotModels];
    }
    const placement = scope === 'tool' ? 'tcp' : 'scene';
    return state.models.filter((model) => isSimulationSnapModel(model)
        && (model.userData.placement === placement
            || (scope === 'tool' && isPrimitiveShapeModel(model) && model.userData.placement === 'scene'))
        && isModelTreeVisible(model));
}

function getRobotBodyBaseMesh(robot) {
    if (!robot?.userData?.tcpFrame) return null;
    const baseName = robot.userData.manifest?.base?.name || 'P0';
    let namedBase = null;
    let fallbackBase = null;
    robot.traverse((child) => {
        if (!child.isMesh || namedBase) return;
        if (child.name === baseName) namedBase = child;
        else if (!fallbackBase && child.userData?.robotJointIndex === undefined) fallbackBase = child;
    });
    return namedBase || fallbackBase;
}

function isSimulationSnapRobotModel(model) {
    return Boolean(model?.userData?.tcpFrame);
}

function isSimulationSnapRobotMesh(mesh) {
    return isSimulationSnapRobotModel(findSceneModelAncestor(mesh));
}

function isSimulationSnapReferenceCandidate(candidate) {
    return candidate?.type === 'scene-origin'
        || candidate?.type === 'robot-base-center'
        || candidate?.type === 'robot-tcp';
}

function getSimulationSnapSceneOriginCandidates(scope = 'scene', faceSelections = []) {
    if (scope !== 'scene' || !state.sketch.active || !state.sketch.snapMode || faceSelections.length) {
        return [];
    }
    if (!state.scene || state.scene.visible === false) return [];
    return [{
        type: 'scene-origin',
        mesh: state.scene,
        localPoint: new THREE.Vector3()
    }];
}

function getSimulationSnapRobotBodyCenterCandidates(scope = 'scene', faceSelections = []) {
    const movingModel = scope === 'placement' ? state.placement.model : null;
    const excludeMovingModel = scope === 'placement' && state.placement.sourcePoint;
    return getArticulatedRobots().flatMap((robot) => {
        if (!isModelTreeVisible(robot) || (excludeMovingModel && robot === movingModel)
            || (scope === 'zero' && !robot.userData.uploaded)) return [];
        const baseMesh = getRobotBodyBaseMesh(robot);
        if (!baseMesh?.geometry?.getAttribute?.('position') || baseMesh.visible === false) return [];
        const localPoint = getExtremeSectionCenter(baseMesh.geometry, 2, -1);
        if (!localPoint) return [];
        return [{
            type: 'robot-base-center',
            mesh: baseMesh,
            localPoint: localPoint.clone()
        }];
    });
}

function getSimulationSnapRobotTcpCandidates(scope = 'scene', faceSelections = []) {
    const movingModel = scope === 'placement' ? state.placement.model : null;
    const excludeMovingModel = scope === 'placement' && state.placement.sourcePoint;
    return getArticulatedRobots().flatMap((robot) => {
        if (!isModelTreeVisible(robot) || (excludeMovingModel && robot === movingModel)
            || (scope === 'zero' && !robot.userData.uploaded)) return [];
        const tcpFrame = robot.userData?.tcpFrame;
        if (!tcpFrame || tcpFrame.visible === false) return [];
        return [{
            type: 'robot-tcp',
            mesh: tcpFrame,
            localPoint: new THREE.Vector3()
        }];
    });
}

function getSimulationSnapRobotSpecialCandidates(scope = 'scene', faceSelections = []) {
    // Once a face is selected, keep every snap candidate scoped to that face.
    // Robot-wide reference points are only available before face selection.
    if (faceSelections.length) return [];
    return [
        ...getSimulationSnapSceneOriginCandidates(scope, faceSelections),
        ...getSimulationSnapRobotBodyCenterCandidates(scope, faceSelections),
        ...getSimulationSnapRobotTcpCandidates(scope, faceSelections)
    ];
}

function getSimulationSnapRobotSpecialCandidateSignature(candidates = []) {
    return candidates
        .map((candidate) => `${candidate.type}:${candidate.mesh.uuid}:${candidate.mesh.geometry?.uuid || 'frame'}`)
        .join('|');
}

function isLargeModelSnapPerformanceMode(scope = 'scene') {
    return getSimulationSnapModels(scope).some((model) => (
        model.userData.largeModelMode
        || Number(model.userData.sourceFileSize) >= STEP_LARGE_FILE_ENGINE_MIN_BYTES
    ));
}

function getAllSimulationSnapMeshes(scope = 'scene', { includeHidden = false } = {}) {
    const meshes = [];
    getSimulationSnapModels(scope).forEach((model) => model.traverse((child) => {
        if (scope === 'placement'
            && state.placement.sourcePoint
            && findSceneModelAncestor(child) === state.placement.model) return;
        if ((child.isMesh
            || child.userData?.sketchFeatureLine
            || child.userData?.cad2dSnapLine)
            && !child.userData.simulationSnapFaceOverlay
            && (includeHidden || child.visible !== false)
            && child.geometry?.getAttribute('position')) meshes.push(child);
    }));
    return meshes;
}

function isDirectSimulationSnapMesh(mesh) {
    return Boolean(mesh?.userData?.sketchFeatureLine
        || mesh?.userData?.cad2dSnapLine
        || mesh?.userData?.sketchFeatureMesh);
}

function getSimulationSnapFaceSelections() {
    const selections = Array.isArray(state.snapFaceSelections) && state.snapFaceSelections.length
        ? state.snapFaceSelections
        : (state.snapFaceSelection ? [state.snapFaceSelection] : []);
    // Robot links are never valid face-snap targets. Their only snap
    // references are the body center and the current TCP point.
    return selections.filter((selection) => !isSimulationSnapRobotMesh(selection?.mesh));
}

function getSimulationSnapFaceSelectionSignature(selections = getSimulationSnapFaceSelections()) {
    return selections.map((selection) => (
        `${selection.key}:${selection.triangleRanges.map((range) => `${range.first}-${range.last}`).join(',')}`
    )).join('|');
}

function isSimulationSnapFaceSelectionActive(scope = getSimulationSnapScope()) {
    return (scope === 'scene' && state.snapMoveMode)
        || (scope === 'scene' && state.sketch.active && state.sketch.snapMode)
        || (scope === 'interference' && state.interferenceSnapMode)
        || (scope === 'zero' && state.zeroPointEdit.active && state.zeroPointEdit.snapMode)
        || (scope === 'placement' && state.placement.active)
        || (scope === 'measurement' && state.measurement.active)
        || (scope === 'tool' && state.tcpSnapMode);
}

function getSimulationSnapMeshes(scope = 'scene') {
    const selections = getSimulationSnapFaceSelections();
    if (isSimulationSnapFaceSelectionActive(scope) && selections.length) {
        const selectedMeshes = [...new Set(selections.map((selection) => selection.mesh))]
            .filter((mesh) => !isSimulationSnapRobotMesh(mesh));
        // A selected mesh can be temporarily hidden while a large-model chunk
        // or a render update is being applied. Membership must be checked
        // without visibility filtering, but the selected-face scope must never
        // expand to unrelated meshes.
        const loadedMeshes = getAllSimulationSnapMeshes(scope, { includeHidden: true });
        if (selectedMeshes.every((mesh) => loadedMeshes.includes(mesh))) {
            return selectedMeshes;
        }
        // An unavailable selected mesh means the current face-selection
        // context has no valid snap targets until the scene becomes ready.
        return [];
    }
    const hasSelectedFirstPoint = (scope === 'placement' && Boolean(state.placement.sourcePoint))
        || (scope === 'measurement' && Boolean(state.measurement.points[0]));
    if (isSimulationSnapFaceSelectionActive(scope)
        && !hasSelectedFirstPoint
        && !(scope === 'scene' && state.sketch.active)) {
        // Before a 3D face is selected, completed 2D sketches are direct snap
        // targets. Completed sketch extrusions are also safe direct targets:
        // their snap points come from the stored sketch profile, so they must
        // not require a separate face-selection click before dimensioning or
        // placing the model. Keep other regular meshes in the face-picking
        // path so the first click can still select a face without building
        // every mesh candidate.
        return getAllSimulationSnapMeshes(scope)
            .filter(isDirectSimulationSnapMesh);
    }
    return getAllSimulationSnapMeshes(scope).filter((mesh) => !isSimulationSnapRobotMesh(mesh));
}

function cloneSimulationSnapFaceSelection(selection) {
    if (!selection?.mesh || !Array.isArray(selection.triangleRanges)) return null;
    return {
        ...selection,
        point: selection.point?.clone ? selection.point.clone() : selection.point,
        triangleRanges: selection.triangleRanges.map((range) => ({
            first: Number(range.first),
            last: Number(range.last)
        }))
    };
}

function cloneSimulationSnapFaceSelections(selections = getSimulationSnapFaceSelections()) {
    return selections.map(cloneSimulationSnapFaceSelection).filter(Boolean);
}

function getSimulationSnapScope() {
    if (state.interferenceSnapMode) return 'interference';
    if (state.zeroPointEdit.active && state.zeroPointEdit.snapMode) return 'zero';
    if (state.placement.active) return 'placement';
    if (state.measurement.active) return 'measurement';
    return state.tcpSnapMode ? 'tool' : 'scene';
}

function yieldToAnimationFrame() {
    return new Promise((resolve) => requestAnimationFrame(resolve));
}

function getValidatedStepBrepFaces(mesh) {
    const rawFaces = mesh?.userData?.stepBrepFaces;
    const triangleCount = Math.floor((mesh?.geometry?.index?.count
        ?? mesh?.geometry?.getAttribute?.('position')?.count
        ?? 0) / 3);
    if (!Array.isArray(rawFaces) || !rawFaces.length || triangleCount <= 0) return null;

    const faces = [];
    let expectedFirst = 0;
    for (const rawFace of rawFaces) {
        const first = Number(rawFace?.first);
        const last = Number(rawFace?.last);
        if (!Number.isInteger(first) || !Number.isInteger(last)
            || first !== expectedFirst || first < 0 || last < first || last >= triangleCount) {
            return null;
        }
        faces.push({ first, last });
        expectedFirst = last + 1;
    }
    return expectedFirst === triangleCount ? faces : null;
}

function getSketchFeatureSnapFaceLocalNormal(mesh, faceSelection) {
    const geometry = mesh?.geometry;
    const position = geometry?.getAttribute?.('position');
    if (!geometry || !position || !faceSelection) return null;
    const triangleIndex = Number.isInteger(Number(faceSelection.triangleIndex))
        ? Number(faceSelection.triangleIndex)
        : Number(faceSelection.triangleRanges?.[0]?.first);
    if (!Number.isInteger(triangleIndex) || triangleIndex < 0) return null;
    const indices = getSimulationSnapTriangleVertexIndices(geometry, triangleIndex);
    if (indices.some((index) => !Number.isInteger(index) || index < 0 || index >= position.count)) return null;
    const first = new THREE.Vector3().fromBufferAttribute(position, indices[0]);
    const second = new THREE.Vector3().fromBufferAttribute(position, indices[1]);
    const third = new THREE.Vector3().fromBufferAttribute(position, indices[2]);
    const normal = second.sub(first).cross(third.sub(first));
    return normal.lengthSq() > 1e-12 ? normal.normalize() : null;
}

function getSketchFeatureSnapLevels(mesh, faceSelection, depth) {
    const normal = getSketchFeatureSnapFaceLocalNormal(mesh, faceSelection);
    if (!normal || Math.abs(normal.z) < 0.82) return [0, depth];
    return [normal.z > 0 ? depth : 0];
}

function getSketchFeatureSnapProfiles(model, mesh) {
    const profiles = getSketchFeatureProfiles(model);
    if (!profiles.length) return [];
    const profileMeshes = model.children.filter((child) => (
        child.isMesh && child.userData?.sketchFeatureMesh
    ));
    const meshIndex = profileMeshes.indexOf(mesh);
    if (meshIndex >= 0 && profiles[meshIndex]) return [profiles[meshIndex]];
    return profiles;
}

function getSketchFeatureSnapSelectedSideEdge(mesh, faceSelection, profiles, modelToMesh, sketchOriginOffset) {
    const normal = getSketchFeatureSnapFaceLocalNormal(mesh, faceSelection);
    if (!normal || Math.abs(normal.z) >= 0.82) return null;
    const geometry = mesh?.geometry;
    const position = geometry?.getAttribute?.('position');
    const triangleIndex = Number.isInteger(Number(faceSelection?.triangleIndex))
        ? Number(faceSelection.triangleIndex)
        : Number(faceSelection?.triangleRanges?.[0]?.first);
    if (!geometry || !position || !Number.isInteger(triangleIndex) || triangleIndex < 0) {
        return { profileIndex: -1, edgeIndex: -1 };
    }
    const indices = getSimulationSnapTriangleVertexIndices(geometry, triangleIndex);
    if (indices.some((index) => !Number.isInteger(index) || index < 0 || index >= position.count)) {
        return { profileIndex: -1, edgeIndex: -1 };
    }
    const meshToModel = modelToMesh.clone().invert();
    const trianglePoints = indices.map((index) => new THREE.Vector3()
        .fromBufferAttribute(position, index)
        .applyMatrix4(meshToModel)
        .add(sketchOriginOffset));
    const uniqueXYPoints = [];
    trianglePoints.forEach((point) => {
        if (!uniqueXYPoints.some((other) => Math.hypot(point.x - other.x, point.y - other.y) <= 1e-5)) {
            uniqueXYPoints.push(point);
        }
    });
    if (uniqueXYPoints.length < 2) return { profileIndex: -1, edgeIndex: -1 };

    let firstEndpoint = uniqueXYPoints[0];
    let secondEndpoint = uniqueXYPoints[1];
    let longestDistanceSq = firstEndpoint.distanceToSquared(secondEndpoint);
    for (let firstIndex = 0; firstIndex < uniqueXYPoints.length - 1; firstIndex += 1) {
        for (let secondIndex = firstIndex + 1; secondIndex < uniqueXYPoints.length; secondIndex += 1) {
            const distanceSq = uniqueXYPoints[firstIndex].distanceToSquared(uniqueXYPoints[secondIndex]);
            if (distanceSq > longestDistanceSq) {
                longestDistanceSq = distanceSq;
                firstEndpoint = uniqueXYPoints[firstIndex];
                secondEndpoint = uniqueXYPoints[secondIndex];
            }
        }
    }
    const edgeTolerance = Math.max(1e-4, Math.sqrt(longestDistanceSq) * 1e-5);
    const distanceToEndpoint = (point, endpoint) => Math.hypot(
        point.x - endpoint.x,
        point.y - endpoint.y
    );
    const boundaryEntries = profiles.flatMap((profile, profileIndex) => [
        { profile, profileIndex, holeIndex: -1 },
        ...(profile.holes || []).map((hole, holeIndex) => ({
            profile: hole,
            profileIndex,
            holeIndex
        }))
    ]);
    for (const { profile, profileIndex, holeIndex } of boundaryEntries) {
        const polygon = getSketchPolygonPoints(profile);
        if (polygon.length < 3) continue;
        for (let edgeIndex = 0; edgeIndex < polygon.length; edgeIndex += 1) {
            const start = polygon[edgeIndex];
            const end = polygon[(edgeIndex + 1) % polygon.length];
            const directDistance = distanceToEndpoint(start, firstEndpoint)
                + distanceToEndpoint(end, secondEndpoint);
            const reverseDistance = distanceToEndpoint(start, secondEndpoint)
                + distanceToEndpoint(end, firstEndpoint);
            if (Math.min(directDistance, reverseDistance) <= edgeTolerance * 2) {
                return { profileIndex, holeIndex, edgeIndex };
            }
        }
    }
    return { profileIndex: -1, holeIndex: -1, edgeIndex: -1 };
}

function buildSketchOnlySnapResultForLine(line) {
    if (!line?.userData?.sketchFeatureLine) return null;
    const model = findSceneModelAncestor(line);
    if (!isSketchOnlyModel(model)) return null;
    const storedEntity = normalizeSketchEntityRecord(line.userData.sketchFeatureEntity);
    const entity = storedEntity || getSketchFeatureEntities(model).find((entry) => (
        entry.id === line.userData.sketchEntityId
    ));
    if (!entity) return null;

    model.updateWorldMatrix?.(true, true);
    line.updateWorldMatrix?.(true, false);
    const modelToLine = line.matrixWorld.clone().invert().multiply(model.matrixWorld);
    const candidates = [];
    const addCandidate = (type, point, source) => {
        if (!point?.isVector3 || ![point.x, point.y, point.z].every(Number.isFinite)) return;
        const localPoint = point.clone().applyMatrix4(modelToLine);
        if (![localPoint.x, localPoint.y, localPoint.z].every(Number.isFinite)) return;
        candidates.push({ type, point: localPoint.toArray(), source });
    };
    const addPolylineCandidates = (points, closed, source) => {
        const uniquePoints = points.filter((point, index) => (
            index === 0 || point.distanceTo(points[index - 1]) > 1e-6
        ));
        if (uniquePoints.length > 1 && uniquePoints[0].distanceTo(uniquePoints.at(-1)) <= 1e-6) {
            uniquePoints.pop();
        }
        uniquePoints.forEach((point, pointIndex) => addCandidate('vertex', point, {
            ...source,
            pointIndex
        }));
        const segmentCount = closed ? uniquePoints.length : uniquePoints.length - 1;
        for (let index = 0; index < segmentCount; index += 1) {
            const start = uniquePoints[index];
            const end = uniquePoints[(index + 1) % uniquePoints.length];
            if (!start || !end) continue;
            addCandidate('edge-midpoint', start.clone().add(end).multiplyScalar(0.5), {
                ...source,
                edgeIndex: index
            });
        }
    };

    if (entity.type === 'circle' && entity.center && Number.isFinite(entity.radius)) {
        addCandidate('circle-center', new THREE.Vector3(entity.center.x, entity.center.y, 0.04), {
            entityId: entity.id
        });
    } else if (entity.type === 'line') {
        addPolylineCandidates(
            [entity.start, entity.end].filter(Boolean).map((point) => point.clone().setZ(0.04)),
            false,
            { entityId: entity.id }
        );
    } else {
        const points = getSketchFeatureEntityPoints(entity).filter(Boolean);
        addPolylineCandidates(points, entity.closed !== false, { entityId: entity.id });
        if (entity.type === 'rectangle') {
            const center = getSketchEntityCenterPoint(entity);
            if (center) addCandidate('rectangle-center', center.setZ(0.04), { entityId: entity.id });
        }
    }
    return { candidates, stats: { profileCount: 1, candidateCount: candidates.length } };
}

function buildCad2dSnapResultForLine(line) {
    if (!line?.userData?.cad2dSnapLine) return null;
    const model = findSceneModelAncestor(line);
    if (!isCad2dModel(model)) return null;
    const entityIds = Array.isArray(line.userData.cadSnapEntityIds)
        ? line.userData.cadSnapEntityIds
        : [line.userData.cadEntityId];
    const entities = entityIds
        .map((entityId) => model.userData.cadDocument?.entities?.find((entity) => entity.id === entityId))
        .filter(Boolean);
    if (!entities.length) return null;

    model.updateWorldMatrix?.(true, true);
    line.updateWorldMatrix?.(true, false);
    const candidates = [];
    const addCandidate = (type, point, source) => {
        const x = Number(point?.[0]);
        const y = Number(point?.[1]);
        const z = Number(point?.[2]) || 0.04;
        if (![x, y, z].every(Number.isFinite)) return;
        const entity = source?.entity;
        const layerGroup = model.userData.cadLayerGroups?.get(entity?.layerId) || model;
        if (layerGroup.visible === false
            || model.userData.cadLayerVisibility?.[entity?.layerId] === false) return;
        layerGroup.updateWorldMatrix?.(true, false);
        const layerToLine = line.matrixWorld.clone().invert().multiply(layerGroup.matrixWorld);
        const localPoint = new THREE.Vector3(x, y, z).applyMatrix4(layerToLine);
        if (![localPoint.x, localPoint.y, localPoint.z].every(Number.isFinite)) return;
        candidates.push({ type, point: localPoint.toArray(), source });
    };
    const addPolylineCandidates = (entity, points, closed) => {
        const uniquePoints = points.filter((point, index) => (
            index === 0 || Math.hypot(
                point[0] - points[index - 1][0],
                point[1] - points[index - 1][1]
            ) > 1e-6
        ));
        if (uniquePoints.length > 1 && Math.hypot(
            uniquePoints[0][0] - uniquePoints.at(-1)[0],
            uniquePoints[0][1] - uniquePoints.at(-1)[1]
        ) <= 1e-6) uniquePoints.pop();
        uniquePoints.forEach((point, pointIndex) => {
            const isEndpoint = !closed && (pointIndex === 0 || pointIndex === uniquePoints.length - 1);
            addCandidate(isEndpoint ? 'endpoint' : 'vertex', [point[0], point[1], 0.04], {
                entity,
                entityId: entity.id,
                pointIndex
            });
        });
        const segmentCount = closed ? uniquePoints.length : uniquePoints.length - 1;
        for (let index = 0; index < segmentCount; index += 1) {
            const start = uniquePoints[index];
            const end = uniquePoints[(index + 1) % uniquePoints.length];
            if (!start || !end) continue;
            addCandidate('edge-midpoint', [
                (start[0] + end[0]) * 0.5,
                (start[1] + end[1]) * 0.5,
                0.04
            ], { entity, entityId: entity.id, edgeIndex: index });
        }
        if (closed && uniquePoints.length >= 3) {
            const bounds = uniquePoints.reduce((result, point) => ({
                minX: Math.min(result.minX, point[0]),
                minY: Math.min(result.minY, point[1]),
                maxX: Math.max(result.maxX, point[0]),
                maxY: Math.max(result.maxY, point[1])
            }), { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity });
            addCandidate('rectangle-center', [
                (bounds.minX + bounds.maxX) * 0.5,
                (bounds.minY + bounds.maxY) * 0.5,
                0.04
            ], { entity, entityId: entity.id });
        }
    };

    entities.forEach((entity) => {
        const type = String(entity.type || '').toUpperCase();
        if (type === 'CIRCLE' && entity.geometry?.center) {
            addCandidate('circle-center', [
                entity.geometry.center[0], entity.geometry.center[1], 0.04
            ], { entity, entityId: entity.id });
            return;
        }
        const sourcePoints = getCadOriginSnapSourcePoints(entity);
        const points = sourcePoints.length
            ? sourcePoints
            : entity.geometry?.point
            ? [entity.geometry.point]
            : [];
        if (!points.length) return;
        if ((type === 'ARC' || type === 'ELLIPSE') && entity.geometry?.center) {
            addCandidate('circle-center', [
                entity.geometry.center[0], entity.geometry.center[1], 0.04
            ], { entity, entityId: entity.id });
        }
        if (type === 'POINT' || entity.renderType === 'point') {
            addCandidate('endpoint', [points[0][0], points[0][1], 0.04], {
                entity,
                entityId: entity.id,
                pointIndex: 0
            });
            return;
        }
        addPolylineCandidates(entity, points, Boolean(entity.closed));
    });
    return {
        candidates,
        stats: { profileCount: entities.length, candidateCount: candidates.length }
    };
}

function buildSketchFeatureSnapResultForMesh(mesh, faceSelection = null) {
    if (!mesh?.userData?.sketchFeatureMesh) return null;
    const model = findSceneModelAncestor(mesh);
    if (!isSketchFeatureModel(model)) return null;
    const profiles = getSketchFeatureSnapProfiles(model, mesh);
    const depth = Number(model.userData.sketchExtrudeDepth);
    if (!profiles.length || !Number.isFinite(depth) || depth <= 0) return null;

    model.updateWorldMatrix?.(true, true);
    mesh.updateWorldMatrix?.(true, false);
    const modelToMesh = mesh.matrixWorld.clone().invert().multiply(model.matrixWorld);
    // Sketch profiles are stored in the original sketch coordinate system,
    // while the generated ExtrudeGeometry is centered around its bounds by
    // centerSketchFeatureGeometry(). Convert back to the generated mesh's
    // local coordinates before the candidate is transformed into world space.
    // Without this correction every vertex/center/edge snap is displaced by
    // the centering offset (including the Z midpoint of the extrusion).
    const sketchOriginOffset = getSketchFeatureOriginOffset(model);
    const levels = getSketchFeatureSnapLevels(mesh, faceSelection, depth);
    const selectedSideEdge = getSketchFeatureSnapSelectedSideEdge(
        mesh,
        faceSelection,
        profiles,
        modelToMesh,
        sketchOriginOffset
    );
    const candidates = [];
    const addCandidate = (type, point, source) => {
        if (!point?.isVector3 || ![point.x, point.y, point.z].every(Number.isFinite)) return;
        const localPoint = point.clone()
            .sub(sketchOriginOffset)
            .applyMatrix4(modelToMesh);
        if (![localPoint.x, localPoint.y, localPoint.z].every(Number.isFinite)) return;
        candidates.push({ type, point: localPoint.toArray(), source });
    };
    const uniquePolygonPoints = (points) => points.filter((point, index) => (
        index === 0 || point.distanceTo(points[index - 1]) > 1e-6
    )).filter((point, index, all) => (
        index < all.length - 1 || all.length < 2 || point.distanceTo(all[0]) > 1e-6
    ));

    profiles.forEach((profile, profileIndex) => {
        const selectedProfileMatches = !selectedSideEdge
            || selectedSideEdge.profileIndex < 0
            || selectedSideEdge.profileIndex === profileIndex;
        if (!selectedProfileMatches) return;
        // A hole center is a virtual reference point. It is not a physical
        // vertex on the selected side wall, so keep it available even when a
        // side face/edge selection narrows the topology candidates.
        (profile.holes || []).forEach((hole, holeIndex) => {
            let center = null;
            if (hole.type === 'circle' && hole.center
                && Number.isFinite(hole.center.x) && Number.isFinite(hole.center.y)) {
                center = new THREE.Vector2(hole.center.x, hole.center.y);
            } else {
                const holePolygon = uniquePolygonPoints(getSketchPolygonPoints(hole));
                if (holePolygon.length >= 3) {
                    center = new THREE.Box2().setFromPoints(holePolygon).getCenter(new THREE.Vector2());
                }
            }
            if (!center) return;
            levels.forEach((z) => addCandidate(
                'hole-center',
                new THREE.Vector3(center.x, center.y, z),
                { profileIndex, holeIndex, virtual: true }
            ));
        });
        const boundaryEntries = [
            { boundary: profile, holeIndex: -1 },
            ...(profile.holes || []).map((hole, holeIndex) => ({ holeIndex, boundary: hole }))
        ];
        boundaryEntries.forEach(({ boundary, holeIndex }) => {
            if (selectedSideEdge && selectedSideEdge.holeIndex !== holeIndex) return;
            if (boundary.type === 'circle' && boundary.center && Number.isFinite(boundary.radius)) {
                if (holeIndex >= 0 || selectedSideEdge) return;
                levels.forEach((z) => {
                    addCandidate(
                        'circle-center',
                        new THREE.Vector3(boundary.center.x, boundary.center.y, z),
                        { profileIndex, holeIndex }
                    );
                });
                return;
            }

            const polygon = uniquePolygonPoints(getSketchPolygonPoints(boundary));
            if (polygon.length < 3) return;
            const pointIndexes = selectedSideEdge?.profileIndex === profileIndex
                && selectedSideEdge.holeIndex === holeIndex
                ? [selectedSideEdge.edgeIndex, (selectedSideEdge.edgeIndex + 1) % polygon.length]
                : polygon.map((_, pointIndex) => pointIndex);
            levels.forEach((z) => {
                pointIndexes.forEach((pointIndex) => {
                    const point = polygon[pointIndex];
                    if (!point) return;
                    addCandidate(
                        'vertex',
                        new THREE.Vector3(point.x, point.y, z),
                        { profileIndex, holeIndex, pointIndex }
                    );
                    const next = polygon[(pointIndex + 1) % polygon.length];
                    if (selectedSideEdge && pointIndex !== selectedSideEdge.edgeIndex) return;
                    addCandidate(
                        'edge-midpoint',
                        new THREE.Vector3(
                            (point.x + next.x) * 0.5,
                            (point.y + next.y) * 0.5,
                            z
                        ),
                        { profileIndex, holeIndex, edgeIndex: pointIndex }
                    );
                });
                if (!selectedSideEdge && holeIndex < 0 && boundary.type === 'rectangle') {
                    const bounds = new THREE.Box2().setFromPoints(polygon);
                    const center = bounds.getCenter(new THREE.Vector2());
                    addCandidate(
                        'rectangle-center',
                        new THREE.Vector3(center.x, center.y, z),
                        { profileIndex, holeIndex }
                    );
                }
            });
        });
    });
    return { candidates, stats: { profileCount: profiles.length, candidateCount: candidates.length } };
}

function buildSimulationSnapResultForMesh(mesh, lazyChunk = false, faceSelection = null) {
    // Robot geometry is intentionally not a generic snap source. Use the
    // dedicated robot-base-center and robot-tcp candidates instead.
    if (isSimulationSnapRobotMesh(mesh)) return null;
    const cad2dResult = buildCad2dSnapResultForLine(mesh);
    if (cad2dResult) return cad2dResult;
    const sketchOnlyResult = buildSketchOnlySnapResultForLine(mesh);
    if (sketchOnlyResult) return sketchOnlyResult;
    const sketchFeatureResult = buildSketchFeatureSnapResultForMesh(mesh, faceSelection);
    if (sketchFeatureResult) return sketchFeatureResult;
    const brepFaces = getValidatedStepBrepFaces(mesh) || getPrimitiveShapeBrepFaces(mesh);
    const snapGeometry = brepFaces
        ? {
            attributes: mesh.geometry.attributes,
            index: mesh.geometry.index,
            brep_faces: brepFaces
        }
        : mesh.geometry;
    const selectedFaceGeometry = faceSelection?.triangleRanges?.length
        ? { ...snapGeometry, brep_faces: faceSelection.triangleRanges }
        : snapGeometry;
    return buildStepSnapCandidates(selectedFaceGeometry, {
        maxVirtualPairs: lazyChunk ? 2000 : 6000,
        maxVirtualCandidates: lazyChunk ? 80 : 160,
        maxPerType: {
            endpoint: Infinity,
            vertex: lazyChunk ? 2500 : 4000,
            'edge-midpoint': lazyChunk ? 2500 : 4000,
            'circle-center': lazyChunk ? 600 : 1000,
            'rectangle-center': lazyChunk ? 600 : 1000
        },
        triangleRanges: faceSelection?.triangleRanges,
        disabledTypes: SIMULATION_SNAP_DISABLED_TYPES
    });
}

function buildSimulationCombinedSnapCandidates(candidateGroups, selections = getSimulationSnapFaceSelections()) {
    const groups = Array.isArray(candidateGroups)
        ? candidateGroups.filter((group) => Array.isArray(group?.candidates) && group.candidates.length)
        : [];
    if (selections.length < 2 || groups.length < 2) return [];

    const result = [];
    const seen = new Set();
    const toWorldPoint = (candidate) => {
        if (!candidate?.localPoint?.clone || !candidate.mesh?.matrixWorld) return null;
        candidate.mesh.updateWorldMatrix?.(true, false);
        const point = candidate.localPoint.clone().applyMatrix4(candidate.mesh.matrixWorld);
        return point.isVector3 && Number.isFinite(point.x) && Number.isFinite(point.y)
            && Number.isFinite(point.z) ? point : null;
    };
    const addCandidate = (worldPoint, sourceKind, anchorCandidate) => {
        if (!worldPoint || !worldPoint.isVector3
            || !Number.isFinite(worldPoint.x) || !Number.isFinite(worldPoint.y)
            || !Number.isFinite(worldPoint.z)) return;
        const key = `${sourceKind}:${worldPoint.x.toFixed(5)},${worldPoint.y.toFixed(5)},${worldPoint.z.toFixed(5)}`;
        if (seen.has(key)) return;
        seen.add(key);
        const mesh = anchorCandidate?.mesh || groups[0]?.candidates?.[0]?.mesh;
        if (!mesh?.matrixWorld) return;
        mesh.updateWorldMatrix?.(true, false);
        const localPoint = worldPoint.clone().applyMatrix4(mesh.matrixWorld.clone().invert());
        if (!Number.isFinite(localPoint.x) || !Number.isFinite(localPoint.y)
            || !Number.isFinite(localPoint.z)) return;
        // Keep the combined point ready for the persistent marker layer. The
        // pointer picker can derive this from localPoint, but the settled
        // marker pass must not depend on a hover event to create worldPoint.
        result.push({
            type: 'multi-point-center',
            mesh,
            localPoint,
            snapWorldPoint: worldPoint.clone(),
            sourceKind
        });
    };

    const centerGroups = groups.map((group) => group.candidates.filter((candidate) => (
        candidate.type === 'rectangle-center'
            || candidate.type === 'circle-center'
            || candidate.type === 'hole-center'
    )));
    let centerPairCount = 0;
    for (let leftGroupIndex = 0; leftGroupIndex < centerGroups.length; leftGroupIndex += 1) {
        for (let rightGroupIndex = leftGroupIndex + 1; rightGroupIndex < centerGroups.length; rightGroupIndex += 1) {
            for (const leftCandidate of centerGroups[leftGroupIndex]) {
                for (const rightCandidate of centerGroups[rightGroupIndex]) {
                    centerPairCount += 1;
                    if (centerPairCount > 4000) break;
                    const left = toWorldPoint(leftCandidate);
                    const right = toWorldPoint(rightCandidate);
                    if (!left || !right) continue;
                    addCandidate(
                        left.clone().add(right).multiplyScalar(0.5),
                        'center-midpoint',
                        leftCandidate
                    );
                }
                if (centerPairCount > 4000) break;
            }
        }
    }

    for (let leftGroupIndex = 0; leftGroupIndex < groups.length; leftGroupIndex += 1) {
        for (let rightGroupIndex = leftGroupIndex + 1; rightGroupIndex < groups.length; rightGroupIndex += 1) {
            const boundaryCandidates = [
                ...groups[leftGroupIndex].candidates,
                ...groups[rightGroupIndex].candidates
            ].filter((candidate) => candidate.type === 'vertex' || candidate.type === 'endpoint');
            const uniqueBoundaryPoints = [];
            const boundaryKeys = new Set();
            let anchorCandidate = null;
            boundaryCandidates.forEach((candidate) => {
                const point = toWorldPoint(candidate);
                if (!point) return;
                const key = `${point.x.toFixed(5)},${point.y.toFixed(5)},${point.z.toFixed(5)}`;
                if (boundaryKeys.has(key)) return;
                boundaryKeys.add(key);
                uniqueBoundaryPoints.push(point);
                anchorCandidate ||= candidate;
            });
            if (uniqueBoundaryPoints.length >= 4) {
                const bounds = new THREE.Box3();
                uniqueBoundaryPoints.forEach((point) => bounds.expandByPoint(point));
                addCandidate(bounds.getCenter(new THREE.Vector3()), 'boundary-center', anchorCandidate);
            }
        }
    }
    return result;
}

async function buildSimulationSnapCandidates(scope = getSimulationSnapScope()) {
    if (!isSimulationSnapInteractionActive()) return [];
    const faceSelections = isSimulationSnapFaceSelectionActive(scope)
        ? cloneSimulationSnapFaceSelections() : [];
    const robotSpecialCandidates = getSimulationSnapRobotSpecialCandidates(
        scope,
        faceSelections
    );
    const hasSelectedFirstPoint = (scope === 'placement' && Boolean(state.placement.sourcePoint))
        || (scope === 'measurement' && Boolean(state.measurement.points[0]));
    const initialMeshes = scope === 'scene' && state.sketch.active
        ? []
        : getSimulationSnapMeshes(scope);
    const directSnapMeshes = initialMeshes.filter(isDirectSimulationSnapMesh);
    if (isSimulationSnapFaceSelectionActive(scope)
        && !faceSelections.length
        && !hasSelectedFirstPoint
        && !robotSpecialCandidates.length
        && !directSnapMeshes.length) {
        state.snapCandidates = [];
        state.snapCandidatesReady = false;
        return [];
    }
    const meshes = faceSelections.length || hasSelectedFirstPoint || directSnapMeshes.length
        ? initialMeshes
        : [];
    const faceSelectionsByMesh = new Map();
    faceSelections.forEach((selection) => {
        const selectionsForMesh = faceSelectionsByMesh.get(selection.mesh.uuid) || [];
        selectionsForMesh.push(selection);
        faceSelectionsByMesh.set(selection.mesh.uuid, selectionsForMesh);
    });
    const faceSignature = getSimulationSnapFaceSelectionSignature(faceSelections);
    const robotSpecialSignature = getSimulationSnapRobotSpecialCandidateSignature(
        robotSpecialCandidates
    );
    const signature = `${scope}:${meshes.map((mesh) => `${mesh.uuid}:${mesh.geometry.uuid}`).join('|')}:${faceSignature}:robot-special=${robotSpecialSignature}`;
    if (signature === state.snapCandidateModelsSignature && state.snapCandidatesReady) return meshes;
    if (signature === state.snapCandidateBuildSignature && state.snapCandidateBuildPromise) {
        await state.snapCandidateBuildPromise;
        return getSimulationSnapMeshes(scope);
    }

    state.snapCandidateBuildSignature = signature;
    state.snapCandidatesReady = false;
    state.snapWorldIndex = null;
    state.snapWorldIndexSignature = '';
    state.snapLazyReadyMeshes.clear();
    state.snapLazyBuildPromises.clear();
    const nextCandidates = [];
    const nextCandidateCounts = {};
    const candidateGroups = faceSelections.map((selection) => ({
        selectionKey: selection.key,
        candidates: []
    }));
    const candidateGroupsByKey = new Map(
        candidateGroups.map((group) => [group.selectionKey, group])
    );
    robotSpecialCandidates.forEach((candidate) => {
        const count = nextCandidateCounts[candidate.type] || 0;
        const limit = SIMULATION_SNAP_MAX_PER_TYPE[candidate.type] || Infinity;
        if (count >= limit) return;
        nextCandidateCounts[candidate.type] = count + 1;
        nextCandidates.push(candidate);
    });
    const appendMeshCandidates = (result, mesh, candidateGroup = null) => {
        if (!Array.isArray(result?.candidates)) return;
        result.candidates.forEach((candidate) => {
            const count = nextCandidateCounts[candidate.type] || 0;
            const limit = SIMULATION_SNAP_MAX_PER_TYPE[candidate.type] || Infinity;
            if (count >= limit) return;
            const localPoint = new THREE.Vector3().fromArray(candidate.point);
            if (!Number.isFinite(localPoint.x) || !Number.isFinite(localPoint.y)
                || !Number.isFinite(localPoint.z)) return;
            nextCandidateCounts[candidate.type] = count + 1;
            const preparedCandidate = {
                type: candidate.type,
                mesh,
                localPoint
            };
            nextCandidates.push(preparedCandidate);
            candidateGroup?.candidates.push(preparedCandidate);
        });
    };
    const buildPromise = (async () => {
        await yieldToAnimationFrame();
        for (let meshIndex = 0; meshIndex < meshes.length; meshIndex += 1) {
            if (state.snapCandidateBuildSignature !== signature || !isSimulationSnapInteractionActive()) return;
            const mesh = meshes[meshIndex];
            if (!faceSelections.length) {
                if (isLazySimulationSnapMesh(mesh)) continue;
            }
            try {
                const meshFaceSelections = faceSelectionsByMesh.get(mesh.uuid) || [];
                if (meshFaceSelections.length) {
                    // Build each selected face independently. This preserves
                    // the normal one-face candidates before adding any
                    // multi-face combination candidates.
                    meshFaceSelections.forEach((selection) => {
                        try {
                            const result = buildSimulationSnapResultForMesh(mesh, false, {
                                triangleRanges: selection.triangleRanges
                            });
                            appendMeshCandidates(
                                result,
                                mesh,
                                candidateGroupsByKey.get(selection.key) || null
                            );
                        } catch (error) {
                            console.warn('Selected face snap candidate generation failed:', mesh.name, error);
                        }
                    });
                } else {
                    // Without a face selection, build the complete candidate
                    // set for selecting P1 or a cross-model P2/measurement point.
                    const result = buildSimulationSnapResultForMesh(mesh, false);
                    appendMeshCandidates(result, mesh);
                }
            } catch (error) {
                console.warn('Snap candidate generation failed:', mesh.name, error);
            }
            if (meshIndex + 1 < meshes.length) await yieldToAnimationFrame();
        }
        if (state.snapCandidateBuildSignature !== signature || !isSimulationSnapInteractionActive()) return;
        try {
            const combinedCandidates = buildSimulationCombinedSnapCandidates(candidateGroups, faceSelections);
            combinedCandidates.forEach((candidate) => {
                const count = nextCandidateCounts[candidate.type] || 0;
                const limit = SIMULATION_SNAP_MAX_PER_TYPE[candidate.type] || Infinity;
                if (count >= limit) return;
                nextCandidateCounts[candidate.type] = count + 1;
                nextCandidates.push(candidate);
            });
        } catch (error) {
            // Combination snaps are additive. A malformed pair must not
            // remove valid endpoint/vertex/center candidates from either face.
            console.warn('Multi-face snap combination skipped:', error);
        }
        state.snapCandidates = nextCandidates;
        state.snapCandidateModelsSignature = signature;
        state.snapCandidatesReady = true;
        state.snapWorldIndex = null;
        state.snapWorldIndexSignature = '';
        try {
            updateSimulationSnapCandidateMarkers();
        } catch (error) {
            // Keep the prepared candidates usable for pointer snapping even
            // when the DOM marker layer cannot be refreshed in this frame.
            clearSimulationSnapCandidateMarkers();
            console.warn('Snap candidate marker refresh skipped:', error);
        }
    })();
    state.snapCandidateBuildPromise = buildPromise;
    try {
        await buildPromise;
    } finally {
        if (state.snapCandidateBuildPromise === buildPromise) state.snapCandidateBuildPromise = null;
    }
    return getSimulationSnapMeshes(scope);
}

function getPreparedSimulationSnapMeshes(scope = getSimulationSnapScope()) {
    const meshes = scope === 'scene' && state.sketch.active
        ? []
        : getSimulationSnapMeshes(scope);
    const faceSelections = isSimulationSnapFaceSelectionActive(scope)
        ? getSimulationSnapFaceSelections() : [];
    const faceSignature = getSimulationSnapFaceSelectionSignature(faceSelections);
    const robotSpecialSignature = getSimulationSnapRobotSpecialCandidateSignature(
        getSimulationSnapRobotSpecialCandidates(scope, faceSelections)
    );
    const signature = `${scope}:${meshes.map((mesh) => `${mesh.uuid}:${mesh.geometry.uuid}`).join('|')}:${faceSignature}:robot-special=${robotSpecialSignature}`;
    if (signature !== state.snapCandidateModelsSignature || !state.snapCandidatesReady) return [];
    return meshes;
}

/*
 * Candidate generation intentionally runs outside pointer events. Large STEP files
 * are split into several render meshes, allowing a frame between expensive chunks.
 */
function invalidateSimulationSnapCandidates() {
    state.snapCandidateBuildSignature = '';
    state.snapCandidateModelsSignature = '';
    state.snapCandidatesReady = false;
    state.snapCandidates = [];
    state.snapWorldIndex = null;
    state.snapWorldIndexSignature = '';
    state.snapLazyReadyMeshes.clear();
    state.snapLazyBuildPromises.clear();
    clearSimulationSnapCandidateMarkers();
}

function getSimulationSnapTriangleVertexIndices(geometry, triangleIndex) {
    const indexArray = geometry.index?.array;
    if (indexArray) {
        const offset = triangleIndex * 3;
        return [indexArray[offset], indexArray[offset + 1], indexArray[offset + 2]];
    }
    const offset = triangleIndex * 3;
    return [offset, offset + 1, offset + 2];
}

const sketchFeatureFaceCache = new WeakMap();

function getSketchFeatureBrepFaces(mesh) {
    if (!mesh?.userData?.sketchFeatureMesh || !mesh.geometry) return null;
    const geometry = mesh.geometry;
    const position = geometry.getAttribute?.('position');
    const indexCount = geometry.index?.count ?? position?.count ?? 0;
    if (!position || indexCount < 3 || indexCount % 3 !== 0) return null;
    const cached = sketchFeatureFaceCache.get(mesh);
    if (cached?.geometry === geometry) return cached.faces;

    if (!geometry.boundingBox) geometry.computeBoundingBox?.();
    const size = geometry.boundingBox?.getSize(new THREE.Vector3()) || new THREE.Vector3();
    const planeTolerance = Math.max(1e-5, size.length() * 1e-6);
    const normalTolerance = 1e-5;
    const groups = new Map();
    const pointA = new THREE.Vector3();
    const pointB = new THREE.Vector3();
    const pointC = new THREE.Vector3();
    const edgeAB = new THREE.Vector3();
    const edgeAC = new THREE.Vector3();
    const normal = new THREE.Vector3();

    for (let triangleIndex = 0; triangleIndex < indexCount / 3; triangleIndex += 1) {
        const indices = getSimulationSnapTriangleVertexIndices(geometry, triangleIndex);
        if (indices.some((vertexIndex) => !Number.isInteger(vertexIndex)
            || vertexIndex < 0 || vertexIndex >= position.count)) continue;
        pointA.fromBufferAttribute(position, indices[0]);
        pointB.fromBufferAttribute(position, indices[1]);
        pointC.fromBufferAttribute(position, indices[2]);
        edgeAB.subVectors(pointB, pointA);
        edgeAC.subVectors(pointC, pointA);
        normal.crossVectors(edgeAB, edgeAC);
        if (normal.lengthSq() <= 1e-16) continue;
        normal.normalize();
        const planeOffset = normal.dot(pointA);
        const key = [
            Math.round(normal.x / normalTolerance),
            Math.round(normal.y / normalTolerance),
            Math.round(normal.z / normalTolerance),
            Math.round(planeOffset / planeTolerance)
        ].join(':');
        const group = groups.get(key) || { triangleIndexes: [] };
        group.triangleIndexes.push(triangleIndex);
        groups.set(key, group);
    }

    const faces = [...groups.values()]
        .sort((left, right) => left.triangleIndexes[0] - right.triangleIndexes[0])
        .map((group) => {
            const triangleIndexes = group.triangleIndexes.sort((left, right) => left - right);
            const triangleRanges = [];
            let rangeStart = triangleIndexes[0];
            let rangeEnd = rangeStart;
            triangleIndexes.slice(1).forEach((triangleIndex) => {
                if (triangleIndex === rangeEnd + 1) {
                    rangeEnd = triangleIndex;
                    return;
                }
                triangleRanges.push({ first: rangeStart, last: rangeEnd });
                rangeStart = triangleIndex;
                rangeEnd = triangleIndex;
            });
            triangleRanges.push({ first: rangeStart, last: rangeEnd });
            return { triangleRanges };
        });
    sketchFeatureFaceCache.set(mesh, { geometry, faces });
    return faces;
}

function getSimulationSnapFaceTriangleRanges(mesh, triangleIndex) {
    const brepFaces = getValidatedStepBrepFaces(mesh) || getPrimitiveShapeBrepFaces(mesh);
    if (brepFaces) {
        const faceIndex = brepFaces.findIndex((face) => (
            triangleIndex >= Number(face.first) && triangleIndex <= Number(face.last)
        ));
        if (faceIndex >= 0) {
            const face = brepFaces[faceIndex];
            return {
                faceIndex,
                key: `${mesh.uuid}:step-face:${faceIndex}`,
                triangleRanges: [{ first: Number(face.first), last: Number(face.last) }]
            };
        }
    }
    const sketchFaces = getSketchFeatureBrepFaces(mesh);
    if (sketchFaces) {
        const faceIndex = sketchFaces.findIndex((face) => face.triangleRanges.some((range) => (
            triangleIndex >= range.first && triangleIndex <= range.last
        )));
        if (faceIndex >= 0) {
            return {
                faceIndex,
                key: `${mesh.uuid}:sketch-face:${faceIndex}`,
                triangleRanges: sketchFaces[faceIndex].triangleRanges
            };
        }
    }
    return {
        faceIndex: triangleIndex,
        key: `${mesh.uuid}:triangle:${triangleIndex}`,
        triangleRanges: [{ first: triangleIndex, last: triangleIndex }]
    };
}

function createSimulationSnapFaceOverlay(selection) {
    const geometry = selection?.mesh?.geometry;
    const position = geometry?.getAttribute('position');
    if (!geometry || !position || !selection?.triangleRanges?.length) return null;
    const vertices = [];
    selection.triangleRanges.forEach((range) => {
        for (let triangleIndex = range.first; triangleIndex <= range.last; triangleIndex += 1) {
            const indices = getSimulationSnapTriangleVertexIndices(geometry, triangleIndex);
            indices.forEach((vertexIndex) => {
                if (!Number.isInteger(vertexIndex) || vertexIndex < 0 || vertexIndex >= position.count) return;
                vertices.push(position.getX(vertexIndex), position.getY(vertexIndex), position.getZ(vertexIndex));
            });
        }
    });
    if (vertices.length < 9) return null;

    const overlayGeometry = new THREE.BufferGeometry();
    overlayGeometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
    overlayGeometry.computeVertexNormals();
    const overlay = new THREE.Mesh(overlayGeometry, new THREE.MeshBasicMaterial({
        color: SIMULATION_SNAP_COLOR,
        transparent: true,
        opacity: 0.2,
        depthWrite: false,
        side: THREE.DoubleSide
    }));
    overlay.name = 'Simulation Snap Selected Face';
    overlay.userData.simulationSnapFaceOverlay = true;
    overlay.renderOrder = 1000;
    overlay.frustumCulled = false;
    selection.mesh.add(overlay);
    return overlay;
}

function clearSimulationSnapFaceSelection({ invalidate = true } = {}) {
    const overlays = state.snapFaceOverlays.length
        ? state.snapFaceOverlays
        : (state.snapFaceOverlay ? [state.snapFaceOverlay] : []);
    overlays.forEach((overlay) => {
        overlay.removeFromParent();
        overlay.geometry?.dispose();
        overlay.material?.dispose();
    });
    state.snapFaceOverlays = [];
    state.snapFaceOverlay = null;
    state.snapFaceSelections = [];
    state.snapFaceSelection = null;
    clearSimulationSnapCandidateMarkers();
    if (invalidate) invalidateSimulationSnapCandidates();
    updateSnapFaceOrientationUi();
}

function clearSimulationSnapCandidateMarkers() {
    state.snapCandidateMarkers.forEach((marker) => marker.remove());
    state.snapCandidateMarkers = [];
    state.snapDisplayedCandidates = [];
}

function setSimulationSnapFaceOverlaysVisible(visible) {
    state.snapFaceOverlays.forEach((overlay) => {
        overlay.visible = visible;
    });
}

function hideSimulationSnapCandidateMarkersForNavigation() {
    // Keep the DOM nodes so the next settled frame can reuse them, but do not
    // let the marker layer participate in layout/painting while OrbitControls
    // is producing camera-change events.
    state.snapCandidateMarkers.forEach((marker) => marker.classList.add('hidden'));
    state.snapDisplayedCandidates = [];
}

function createSimulationSnapCandidateMarker() {
    const marker = document.createElement('div');
    marker.className = 'simulation-snap-marker simulation-snap-candidate-marker';
    marker.setAttribute('aria-hidden', 'true');
    marker.innerHTML = '<span></span>';
    el.canvasContainer?.appendChild(marker);
    return marker;
}

function updateSimulationSnapCandidateMarkers() {
    // Projecting every candidate and doing depth tests while the camera is
    // moving was the main source of the large-model orbit/pan hitch. The
    // selected face remains intact; markers are rebuilt once navigation ends.
    if (state.viewNavigationActive) return;
    const scope = getSimulationSnapScope();
    const hasDirectSnapCandidates = state.snapCandidates.some((candidate) => (
        isDirectSimulationSnapMesh(candidate.mesh)
    ));
    const hasReferenceSnapCandidates = state.snapCandidates.some((candidate) => (
        isSimulationSnapReferenceCandidate(candidate)
    ));
    if (!isSimulationSnapFaceSelectionActive(scope)
        || (!getSimulationSnapFaceSelections().length
            && !hasDirectSnapCandidates
            && !hasReferenceSnapCandidates)
        || !state.snapCandidatesReady
        || !el.canvasContainer || !state.renderer || !state.camera) {
        clearSimulationSnapCandidateMarkers();
        return;
    }
    const meshes = getSimulationSnapMeshes(scope);
    const bounds = state.renderer.domElement.getBoundingClientRect();
    if ((!meshes.length && !hasReferenceSnapCandidates)
        || bounds.width <= 0 || bounds.height <= 0) {
        clearSimulationSnapCandidateMarkers();
        return;
    }
    state.camera.updateMatrixWorld(true);
    getSimulationSnapWorldIndex(meshes);
    // Selected-face candidates are intentional snap targets. Do not let the
    // model's depth occlusion hide them while face-selection mode is active; the
    // marker layer must keep priority over geometry behind the selected face.
    const visibilityMeshes = isSimulationSnapFaceSelectionActive(scope)
        || isLargeModelSnapPerformanceMode(scope)
        ? null
        : getAllSimulationSnapMeshes(scope);
    const candidates = [];
    const markerCells = new Map();
    const markerSpacing = state.largeModelPerformanceMode ? 12 : 7;
    const getMarkerCellKey = (x, y) => `${Math.floor(x / markerSpacing)}:${Math.floor(y / markerSpacing)}`;
    const isBetterMarker = (next, current) => (
        snapTypeInfo(next.candidate.type).priority < snapTypeInfo(current.candidate.type).priority
    );
    const projected = new THREE.Vector3();
    // Candidate generation follows geometry/topology order, which can put
    // thousands of endpoints ahead of the useful center candidates. Grouping
    // and ordering here makes centers visible on the settled frame instead of
    // waiting for the pointer to hover over their screen position.
    const candidatesByType = new Map();
    state.snapCandidates.forEach((candidate) => {
        const candidatesForType = candidatesByType.get(candidate.type) || [];
        candidatesForType.push(candidate);
        candidatesByType.set(candidate.type, candidatesForType);
    });
    const orderedCandidates = [];
    const orderedTypes = new Set();
    SIMULATION_SNAP_MARKER_TYPE_ORDER.forEach((type) => {
        orderedTypes.add(type);
        orderedCandidates.push(...(candidatesByType.get(type) || []));
    });
    candidatesByType.forEach((candidatesForType, type) => {
        if (!orderedTypes.has(type)) orderedCandidates.push(...candidatesForType);
    });
    let centerMarkerCount = 0;
    for (const candidate of orderedCandidates) {
        if (!candidate.mesh.visible || !candidate.snapWorldPoint) continue;
        const isCenterMarker = SIMULATION_SNAP_CENTER_MARKER_TYPES.has(candidate.type);
        if (isCenterMarker && centerMarkerCount >= MAX_VISIBLE_SIMULATION_SNAP_CENTER_MARKERS) continue;
        projected.copy(candidate.snapWorldPoint).project(state.camera);
        if (projected.z < -1 || projected.z > 1) continue;
        const screenX = (projected.x * 0.5 + 0.5) * bounds.width;
        const screenY = (-projected.y * 0.5 + 0.5) * bounds.height;
        if (screenX < -12 || screenX > bounds.width + 12
            || screenY < -12 || screenY > bounds.height + 12) continue;
        if (visibilityMeshes) {
            const visibilityCandidate = {
                ...candidate,
                worldPoint: candidate.snapWorldPoint
            };
            if (!isSimulationSnapCandidateVisible(visibilityCandidate, projected, visibilityMeshes)) continue;
        }
        const item = { candidate, screenX, screenY };
        const cellX = Math.floor(screenX / markerSpacing);
        const cellY = Math.floor(screenY / markerSpacing);
        let duplicateIndex = -1;
        for (let offsetX = -1; offsetX <= 1 && duplicateIndex < 0; offsetX += 1) {
            for (let offsetY = -1; offsetY <= 1; offsetY += 1) {
                const cell = markerCells.get(`${cellX + offsetX}:${cellY + offsetY}`) || [];
                const match = cell.find((index) => (
                    Math.hypot(candidates[index].screenX - screenX, candidates[index].screenY - screenY)
                    <= markerSpacing
                ));
                if (match !== undefined) {
                    duplicateIndex = match;
                    break;
                }
            }
        }
        if (duplicateIndex >= 0) {
            if (isBetterMarker(item, candidates[duplicateIndex])) candidates[duplicateIndex] = item;
            continue;
        }
        const cellKey = getMarkerCellKey(screenX, screenY);
        const cell = markerCells.get(cellKey) || [];
        cell.push(candidates.length);
        markerCells.set(cellKey, cell);
        candidates.push(item);
        if (isCenterMarker) centerMarkerCount += 1;
        if (candidates.length >= MAX_VISIBLE_SIMULATION_SNAP_MARKERS) break;
    }
    state.snapDisplayedCandidates = candidates.map(({ candidate }) => candidate);
    while (state.snapCandidateMarkers.length < candidates.length) {
        state.snapCandidateMarkers.push(createSimulationSnapCandidateMarker());
    }
    state.snapCandidateMarkers.forEach((marker, index) => {
        const item = candidates[index];
        marker.classList.toggle('hidden', !item);
        if (!item) return;
        const info = snapTypeInfo(item.candidate.type);
        marker.style.left = `${item.screenX}px`;
        marker.style.top = `${item.screenY}px`;
        marker.dataset.snapType = item.candidate.type;
        marker.style.setProperty(
            '--simulation-snap-camera-scale',
            el.snapMarker?.style.getPropertyValue('--simulation-snap-camera-scale') || '1'
        );
        const symbol = marker.querySelector('span');
        if (symbol) symbol.textContent = info.symbol;
    });
}

function pickSimulationSnapFaceAtPointer(pointerEvent, scope = getSimulationSnapScope()) {
    // Clicking a robot must not enter mesh-face snapping. Robot snapping is
    // limited to the body-center and TCP reference candidates.
    const meshes = getAllSimulationSnapMeshes(scope)
        .filter((mesh) => !isSimulationSnapRobotMesh(mesh));
    if (!meshes.length) return null;
    const bounds = state.renderer.domElement.getBoundingClientRect();
    if (bounds.width <= 0 || bounds.height <= 0) return null;
    const pointer = new THREE.Vector2(
        ((pointerEvent.clientX - bounds.left) / bounds.width) * 2 - 1,
        -((pointerEvent.clientY - bounds.top) / bounds.height) * 2 + 1
    );
    state.camera.updateMatrixWorld(true);
    state.snapVisibilityRaycaster.setFromCamera(pointer, state.camera);
    const hit = state.snapVisibilityRaycaster.intersectObjects(meshes, false)[0];
    if (!hit?.object || !Number.isInteger(hit.faceIndex)) return null;
    const face = getSimulationSnapFaceTriangleRanges(hit.object, hit.faceIndex);
    return {
        mesh: hit.object,
        point: hit.point.clone(),
        faceIndex: face.faceIndex,
        triangleIndex: hit.faceIndex,
        key: face.key,
        triangleRanges: face.triangleRanges
    };
}

function pickSimulationSnapRobotAtPointer(pointerEvent) {
    const rect = state.renderer?.domElement?.getBoundingClientRect();
    if (!rect || rect.width <= 0 || rect.height <= 0 || !state.camera) return null;
    const pointer = new THREE.Vector2(
        ((pointerEvent.clientX - rect.left) / rect.width) * 2 - 1,
        -((pointerEvent.clientY - rect.top) / rect.height) * 2 + 1
    );
    state.camera.updateMatrixWorld(true);
    state.snapVisibilityRaycaster.setFromCamera(pointer, state.camera);
    const robots = getArticulatedRobots().filter((robot) => isModelTreeVisible(robot));
    const hit = state.snapVisibilityRaycaster.intersectObjects(robots, true)[0];
    if (!hit?.object) return null;
    for (let current = hit.object; current; current = current.parent) {
        if (robots.includes(current)) return current;
    }
    return null;
}

function rebuildSimulationSnapCandidatesForCurrentInteraction(scope = getSimulationSnapScope()) {
    if (!isSimulationSnapInteractionActive() || getSimulationSnapScope() !== scope) {
        return Promise.resolve([]);
    }
    return buildSimulationSnapCandidates(scope).then((meshes) => {
        if (!isSimulationSnapInteractionActive() || getSimulationSnapScope() !== scope) {
            return meshes;
        }
        updateSimulationSnapCandidateMarkers();
        scheduleSimulationSnapPreview();
        requestRender();
        return meshes;
    });
}

function resetSimulationSnapFaceContextAndRebuild(scope = getSimulationSnapScope()) {
    if (!isSimulationSnapInteractionActive() || getSimulationSnapScope() !== scope) return false;
    clearSimulationSnapFaceSelection({ invalidate: false });
    invalidateSimulationSnapCandidates();
    captureSimulationSnapMarkerReferenceDistance();
    void rebuildSimulationSnapCandidatesForCurrentInteraction(scope).catch((error) => {
        console.warn('Simulation snap candidate rebuild after context reset failed:', error);
    });
    return true;
}

function handleSimulationSnapFaceSelectionClick(event) {
    const scope = getSimulationSnapScope();
    const selectedFaces = getSimulationSnapFaceSelections();
    const hasFaceContext = selectedFaces.length > 0
        || Boolean(state.snapFaceSelections?.length)
        || Boolean(state.snapFaceSelection);
    const robot = pickSimulationSnapRobotAtPointer(event);
    if (robot && (hasFaceContext || !state.snapCandidatesReady)) {
        event.preventDefault();
        event.stopPropagation();
        resetSimulationSnapFaceContextAndRebuild(scope);
        setStatus('로봇 바디 중심점 또는 TCP 점을 가리켜 주세요.', '#60a5fa');
        return;
    }
    if (event.shiftKey) {
        const selection = pickSimulationSnapFaceAtPointer(event, scope);
        if (!selection) {
            setStatus('스냅할 3D 모델의 면을 클릭하세요.', '#f59e0b');
            return;
        }
        event.preventDefault();
        event.stopPropagation();
        selectSimulationSnapFace(selection, { additive: true });
        return;
    }

    const snap = findSimulationSnapAtPointer(event);
    if (snap) {
        event.preventDefault();
        event.stopPropagation();
        if (state.snapMoveMode) {
            if (moveRobotTcpToSimulationSnap(snap)) showSimulationSnapMarker(snap);
        } else if (state.sketch.active && state.sketch.snapMode) {
            if (handleSketchSnapSelection(snap)) showSimulationSnapMarker(snap);
        } else if (state.zeroPointEdit.active && state.zeroPointEdit.snapMode) {
            if (handleZeroPointSnapSelection(snap)) showSimulationSnapMarker(snap);
        } else if (state.placement.active) {
            if (handleMeasurementSnapSelection(snap)) showSimulationSnapMarker(snap);
        } else if (state.measurement.active) {
            if (handleMeasurementSnapSelection(snap)) showSimulationSnapMarker(snap);
        } else if (state.tcpSnapMode) {
            if (handleTcpSnapSelection(snap)) showSimulationSnapMarker(snap);
        } else if (state.interferenceSnapMode) {
            if (handleInterferenceSnapSelection(snap)) showSimulationSnapMarker(snap);
        }
        return;
    }

    if (robot) {
        event.preventDefault();
        event.stopPropagation();
        setStatus('로봇 바디 중심점 또는 TCP 점을 가리켜 주세요.', '#60a5fa');
        return;
    }

    const selection = pickSimulationSnapFaceAtPointer(event, scope);
    if (selection && !selectedFaces.some((face) => face.key === selection.key)) {
        event.preventDefault();
        event.stopPropagation();
        selectSimulationSnapFace(selection);
        return;
    }
    setStatus(
        selection ? '선택된 면의 스냅 후보를 가리켜 주세요.' : '스냅할 3D 모델의 면을 클릭하세요.',
        '#f59e0b'
    );
}

function selectSimulationSnapFace(selection, { additive = false } = {}) {
    const nextSelection = cloneSimulationSnapFaceSelection(selection);
    if (!nextSelection) return false;
    const currentSelections = cloneSimulationSnapFaceSelections();
    const nextSelections = additive ? currentSelections : [];
    const existingIndex = nextSelections.findIndex((face) => face.key === nextSelection.key);
    if (additive && existingIndex >= 0) nextSelections.splice(existingIndex, 1);
    else nextSelections.push(nextSelection);
    if (!nextSelections.length) {
        clearSimulationSnapFaceSelection();
        setStatus('스냅할 3D 모델의 면을 클릭하세요.', '#60a5fa');
        return false;
    }

    clearSimulationSnapFaceSelection({ invalidate: false });
    state.snapFaceSelections = nextSelections;
    state.snapFaceSelection = nextSelections[nextSelections.length - 1];
    state.snapFaceOverlays = nextSelections
        .map((face) => createSimulationSnapFaceOverlay(face))
        .filter(Boolean);
    state.snapFaceOverlay = state.snapFaceOverlays[0] || null;
    updateSnapFaceOrientationUi();
    invalidateSimulationSnapCandidates();
    hideSimulationSnapMarker();
    setStatus('면을 선택했습니다. 선택된 면의 스냅 후보를 계산하는 중입니다...', '#f59e0b');
    const selectionSignature = getSimulationSnapFaceSelectionSignature(nextSelections);
    const scope = getSimulationSnapScope();
    void buildSimulationSnapCandidates(scope).then(() => {
        if (!isSimulationSnapFaceSelectionActive(scope)
            || getSimulationSnapFaceSelectionSignature() !== selectionSignature) return;
        if (scope === 'zero') {
            setZeroPointSnapReadout('선택한 면의 스냅 후보를 클릭하세요.');
        } else if (scope === 'tool') {
            setTcpSnapReadout('선택한 면의 스냅 후보를 클릭하세요.');
        } else if (scope === 'placement' || scope === 'measurement') {
            setMeasurementPanelStatus('선택한 면의 스냅 후보를 클릭하세요.');
        }
        setStatus('선택한 면의 스냅 후보를 클릭하세요.', '#60a5fa');
    }).catch((error) => {
        console.warn('Selected face snap candidate generation failed:', error);
        if (getSimulationSnapFaceSelectionSignature() === selectionSignature) {
            // Candidate generation is asynchronous. A transient failure or a
            // stale mesh must not erase the user's face selection; keep the
            // overlays and allow a later rebuild after the scene settles.
            invalidateSimulationSnapCandidates();
            setStatus('선택한 면의 스냅 후보를 다시 계산해야 합니다. 면 선택은 유지됩니다.', '#f59e0b');
        }
    });
    return true;
}

function getActiveSimulationSnapFaceSelection() {
    const selections = getSimulationSnapFaceSelections();
    return selections[selections.length - 1] || null;
}

function getSimulationSnapFaceNormal(selection = getActiveSimulationSnapFaceSelection()) {
    const mesh = selection?.mesh;
    const geometry = mesh?.geometry;
    const position = geometry?.getAttribute?.('position');
    const ranges = Array.isArray(selection?.triangleRanges) ? selection.triangleRanges : [];
    if (!mesh || !geometry || !position || !ranges.length) return null;

    mesh.updateWorldMatrix?.(true, false);
    const candidateTriangles = [];
    const selectedTriangle = Number(selection.triangleIndex);
    if (Number.isInteger(selectedTriangle)) candidateTriangles.push(selectedTriangle);
    ranges.forEach((range) => {
        const first = Number(range?.first);
        if (Number.isInteger(first)) candidateTriangles.push(first);
    });

    const normal = new THREE.Vector3();
    const normalMatrix = new THREE.Matrix3().getNormalMatrix(mesh.matrixWorld);
    for (const triangleIndex of [...new Set(candidateTriangles)]) {
        const indices = getSimulationSnapTriangleVertexIndices(geometry, triangleIndex);
        if (indices.some((index) => !Number.isInteger(index) || index < 0 || index >= position.count)) continue;
        const first = new THREE.Vector3().fromBufferAttribute(position, indices[0]);
        const second = new THREE.Vector3().fromBufferAttribute(position, indices[1]);
        const third = new THREE.Vector3().fromBufferAttribute(position, indices[2]);
        normal.copy(second).sub(first).cross(third.clone().sub(first));
        if (normal.lengthSq() < 1e-12) continue;
        normal.normalize().applyMatrix3(normalMatrix).normalize();
        return normal;
    }
    return null;
}

function updateSnapFaceOrientationUi() {
    const snapMoveActive = Boolean(state.snapMoveMode);
    const hasSelectedFace = Boolean(getActiveSimulationSnapFaceSelection());
    const available = snapMoveActive
        && hasSelectedFace
        && Boolean(getJogTargetRobot()?.userData?.tcpFrame)
        && !isMotionActive();
    el.snapFaceOrientationActions?.classList.toggle('hidden', !snapMoveActive);
    [el.btnSnapFaceHorizontal, el.btnSnapFaceVertical].forEach((button) => {
        if (!button) return;
        button.disabled = !available;
    });
}

function applySnapFaceOrientation(mode) {
    if (!['horizontal', 'vertical'].includes(mode) || isMotionActive()) return false;
    const robot = getJogTargetRobot();
    const faceSelection = getActiveSimulationSnapFaceSelection();
    if (!state.snapMoveMode || !faceSelection || !robot?.userData?.tcpFrame) {
        setStatus('스냅 이동에서 먼저 면을 선택하세요.', '#f59e0b');
        return false;
    }

    const faceNormal = getSimulationSnapFaceNormal(faceSelection);
    if (!faceNormal) {
        setStatus('선택한 면의 방향을 계산할 수 없습니다.', '#ef4444');
        return false;
    }
    const currentPose = getCurrentTcpPoseBase(robot);
    if (!currentPose) return false;

    const baseWorldQuaternion = robot.getWorldQuaternion(new THREE.Quaternion());
    const currentWorldQuaternion = baseWorldQuaternion.clone()
        .multiply(currentPose.quaternion.clone())
        .normalize();
    const currentTcpZ = new THREE.Vector3(0, 0, 1)
        .applyQuaternion(currentWorldQuaternion)
        .normalize();
    let targetTcpZ = faceNormal.clone();
    if (mode === 'vertical') {
        // Either side is perpendicular to the face. Keep the direction that
        // requires less rotation from the current TCP pose.
        if (targetTcpZ.dot(currentTcpZ) < 0) targetTcpZ.negate();
    } else {
        // Project the current TCP Z axis onto the selected face. This keeps
        // the current heading as much as possible while making it parallel.
        targetTcpZ.copy(currentTcpZ)
            .addScaledVector(faceNormal, -currentTcpZ.dot(faceNormal));
        if (targetTcpZ.lengthSq() < 1e-12) {
            const currentTcpX = new THREE.Vector3(1, 0, 0)
                .applyQuaternion(currentWorldQuaternion)
                .normalize();
            targetTcpZ.copy(currentTcpX)
                .addScaledVector(faceNormal, -currentTcpX.dot(faceNormal));
        }
        if (targetTcpZ.lengthSq() < 1e-12) {
            const reference = Math.abs(faceNormal.z) < 0.9
                ? new THREE.Vector3(0, 0, 1)
                : new THREE.Vector3(1, 0, 0);
            targetTcpZ.copy(reference).cross(faceNormal).normalize();
        } else {
            targetTcpZ.normalize();
        }
    }

    const targetTcpZDirections = [targetTcpZ.clone().normalize()];
    const oppositeTcpZ = targetTcpZ.clone().negate().normalize();
    if (!targetTcpZDirections.some((direction) => direction.distanceToSquared(oppositeTcpZ) < 1e-12)) {
        targetTcpZDirections.push(oppositeTcpZ);
    }
    // Aligning the TCP Z direction does not constrain the roll around that
    // direction. Try several roll candidates so a valid wrist configuration
    // is still found after switching from horizontal to vertical alignment.
    const twistAngles = [0, 180, 90, -90, 45, -45, 135, -135];
    for (let angle = 15; angle < 180; angle += 15) twistAngles.push(angle, -angle);
    const targetCandidates = [];
    twistAngles.forEach((angle) => {
        targetTcpZDirections.forEach((direction) => {
            const alignmentQuaternion = new THREE.Quaternion()
                .setFromUnitVectors(currentTcpZ, direction);
            const alignedWorldQuaternion = alignmentQuaternion.clone()
                .multiply(currentWorldQuaternion)
                .normalize();
            const twistedWorldQuaternion = new THREE.Quaternion()
                .setFromAxisAngle(direction, THREE.MathUtils.degToRad(angle))
                .multiply(alignedWorldQuaternion)
                .normalize();
            const quaternion = baseWorldQuaternion.clone()
                .invert()
                .multiply(twistedWorldQuaternion)
                .normalize();
            if (!targetCandidates.some((candidate) => candidate.quaternion.angleTo(quaternion) < 1e-7)) {
                targetCandidates.push({
                    position: currentPose.position.clone(),
                    quaternion
                });
            }
        });
    });
    const previousAngles = robot.userData.joints.map((joint) => joint.angle);
    const previousTarget = robot.userData.baseJogTarget
        ? {
            position: robot.userData.baseJogTarget.position.clone(),
            quaternion: robot.userData.baseJogTarget.quaternion.clone()
        }
        : currentPose;
    const before = captureSceneSnapshot();
    setBaseJogStatus('Solving IK...', 'working');
    let result = null;
    let target = null;
    for (const candidate of targetCandidates) {
        const candidateResult = solveRobotIK(robot, candidate, {
            positionTolerance: 0.001,
            rotationTolerance: THREE.MathUtils.degToRad(0.001)
        });
        if (candidateResult.success) {
            result = candidateResult;
            target = candidate;
            break;
        }
        previousAngles.forEach((angle, index) => setJointAngle(robot.userData.joints[index], angle, false));
        robot.updateMatrixWorld(true);
    }
    if (!result || !target) {
        previousAngles.forEach((angle, index) => setJointAngle(robot.userData.joints[index], angle, false));
        robot.userData.baseJogTarget = previousTarget;
        robot.updateMatrixWorld(true);
        syncJointControls(robot);
        updateTcpPresentation(robot, previousTarget);
        syncBaseJogGizmoFromRobot(robot, previousTarget);
        setBaseJogStatus('Target is outside the reachable range or joint limits.', 'error');
        return false;
    }

    robot.userData.baseJogTarget = target;
    syncJointControls(robot);
    updateTcpPresentation(robot, target);
    syncBaseJogGizmoFromRobot(robot, target);
    setBaseJogStatus('');
    recordHistory(
        mode === 'horizontal' ? '선택 면과 수평 정렬' : '선택 면과 수직 정렬',
        before,
        captureSceneSnapshot()
    );
    setStatus(
        mode === 'horizontal'
            ? 'TCP Z 방향을 선택 면과 수평으로 맞췄습니다.'
            : 'TCP Z 방향을 선택 면과 수직으로 맞췄습니다.',
        '#22c55e'
    );
    clearJogCollisionLock();
    return true;
}

function snapTypeInfo(type) {
    return SNAP_TYPES[type] || SNAP_TYPES.vertex;
}

function compareSimulationSnapCandidates(left, right) {
    const pixelDifference = left.pixelDistance - right.pixelDistance;
    const priorityDifference = snapTypeInfo(left.type).priority - snapTypeInfo(right.type).priority;
    if (priorityDifference && Math.abs(pixelDifference) <= SIMULATION_SNAP_OVERLAP_TOLERANCE_PX) {
        return priorityDifference;
    }
    return pixelDifference || priorityDifference || left.cameraDistance - right.cameraDistance;
}

function isSimulationSnapPicking() {
    return state.placement.active || state.measurement.active || state.snapMoveMode
        || state.interferenceSnapMode || state.tcpSnapMode || isCadOriginSnapPicking()
        || (state.sketch.active && state.sketch.snapMode) || (
        state.zeroPointEdit.active && state.zeroPointEdit.snapMode
    );
}

function isSimulationSnapInteractionActive() {
    return isSimulationSnapPicking() && !state.viewNavigationActive;
}

function beginSimulationViewNavigation() {
    if (state.viewNavigationActive) return;
    state.viewNavigationActive = true;
    // Camera movement can generate a pointermove for every orbit/pan step.
    // Cancel any pending snap work before those events reach the snap picker.
    state.snapCandidateBuildSignature = '';
    hideSimulationSnapMarker();
    hideSimulationSnapCandidateMarkersForNavigation();
    setSimulationSnapFaceOverlaysVisible(false);
}

function endSimulationViewNavigation() {
    if (!state.viewNavigationActive) return;
    state.viewNavigationActive = false;
    scheduleMotionProjectSave();
    setSimulationSnapFaceOverlaysVisible(true);
    if (!isSimulationSnapPicking()) return;
    if (state.snapCandidatesReady) {
        requestRender();
        scheduleSimulationSnapPreview();
        return;
    }

    // If navigation interrupted candidate preparation, resume it after the
    // controls release without doing any work inside the camera gesture.
    void buildSimulationSnapCandidates(getSimulationSnapScope()).then(() => {
        requestRender();
        scheduleSimulationSnapPreview();
    }).catch((error) => {
        console.warn('Snap candidate generation resume failed:', error);
    });
}

function isTcpMultiPointSnapMode() {
    return state.tcpSnapMode && state.tcpSnapType === 'multi-point-center';
}

function setTcpSnapReadout(message) {
    state.tcpSnapReadoutMessage = message;
    if (!el.tcpSnapReadout) return;
    el.tcpSnapReadout.dataset.sourceMessage = message;
    el.tcpSnapReadout.textContent = uiText(message);
}

function formatSimulationSnapPoint(point) {
    return `X ${point.x.toFixed(3)} · Y ${point.y.toFixed(3)} · Z ${point.z.toFixed(3)} mm`;
}

function formatMeasurementNumber(value) {
    return Number(value).toFixed(3);
}

function formatMeasurementPoint(point) {
    if (!point) return '-';
    const worldPoint = point.worldPoint || point;
    if (!worldPoint || !['x', 'y', 'z'].every((axis) => Number.isFinite(Number(worldPoint[axis])))) return '-';
    const snapLabel = point.snapType ? ` · ${uiText(snapTypeInfo(point.snapType).label)}` : '';
    return `${formatSimulationSnapPoint(worldPoint)}${snapLabel}`;
}

function isRobotPositionMeasurement() {
    return state.measurement.displayMode === 'robot-position';
}

function getMeasurementRobot() {
    const selectedRobot = getSelectedRobotModel();
    if (selectedRobot) return selectedRobot;
    const robotId = state.measurement.robotPositionRobotId;
    if (!robotId) return null;
    return getArticulatedRobots().find((robot) => robot.userData?.motionInstanceId === robotId) || null;
}

function calculateRobotPositionMeasurement(point) {
    const robot = getMeasurementRobot();
    if (!robot || !point?.worldPoint?.clone) return null;
    robot.updateMatrixWorld(true);
    const position = robot.worldToLocal(point.worldPoint.clone());
    if (!['x', 'y', 'z'].every((axis) => Number.isFinite(position[axis]))) return null;
    return {
        robot,
        point: position,
        x: position.x,
        y: position.y,
        z: position.z
    };
}

function formatRobotPositionMeasurement(result) {
    if (!result) return '-';
    return [
        `X = ${formatMeasurementNumber(result.x)} mm`,
        `Y = ${formatMeasurementNumber(result.y)} mm`,
        `Z = ${formatMeasurementNumber(result.z)} mm`
    ].join('\n');
}

function setMeasurementPanelStatus(message) {
    state.measurement.statusMessage = message;
    [el.measurementState, el.modelPlacementState].forEach((status) => {
        if (!status) return;
        status.dataset.sourceMessage = message;
        status.textContent = uiText(message);
    });
}

function isVisibleSceneObject(object) {
    for (let current = object; current; current = current.parent) {
        if (current.visible === false) return false;
        if (state.models.includes(current)) return true;
    }
    return false;
}

function createMeasurementPoint(snap) {
    if (!snap?.mesh?.updateWorldMatrix || !snap.localPoint?.clone || !snap.worldPoint?.clone) return null;
    return {
        worldPoint: snap.worldPoint.clone(),
        mesh: snap.mesh,
        localPoint: snap.localPoint.clone(),
        snapType: snap.type,
        screenX: snap.screenX,
        screenY: snap.screenY
    };
}

function syncMeasurementPointWorldPoint(point) {
    const model = findSceneModelAncestor(point?.mesh);
    if (!point?.mesh?.updateWorldMatrix || !model || !state.models.includes(model)
        || !isVisibleSceneObject(point.mesh)) return false;
    point.mesh.updateWorldMatrix(true, false);
    const worldPoint = point.localPoint.clone().applyMatrix4(point.mesh.matrixWorld);
    if (![worldPoint.x, worldPoint.y, worldPoint.z].every(Number.isFinite)) return false;
    point.worldPoint.copy(worldPoint);
    return true;
}

function ensureMeasurementOverlayGroup() {
    if (!state.scene) return null;
    if (!state.measurement.lineGroup) {
        state.measurement.lineGroup = new THREE.Group();
        state.measurement.lineGroup.name = 'Dimension measurement overlay';
        state.measurement.lineGroup.renderOrder = 1000;
        state.scene.add(state.measurement.lineGroup);
    }
    return state.measurement.lineGroup;
}

function createMeasurementLine(color) {
    const line = new THREE.Line(
        new THREE.BufferGeometry(),
        new THREE.LineBasicMaterial({
            color,
            transparent: true,
            opacity: 0.96,
            depthTest: false,
            depthWrite: false
        })
    );
    line.renderOrder = 1001;
    line.frustumCulled = false;
    line.visible = false;
    return line;
}

function ensureMeasurementLine(name, color) {
    const group = ensureMeasurementOverlayGroup();
    if (!group) return null;
    if (!state.measurement.lines[name]) {
        state.measurement.lines[name] = createMeasurementLine(color);
        group.add(state.measurement.lines[name]);
    }
    return state.measurement.lines[name];
}

function createMeasurementPointMarker(color) {
    const marker = new THREE.Mesh(
        new THREE.SphereGeometry(1, 16, 10),
        new THREE.MeshBasicMaterial({
            color,
            transparent: true,
            opacity: 0.98,
            depthTest: false,
            depthWrite: false
        })
    );
    marker.scale.setScalar(7);
    marker.renderOrder = 1002;
    marker.frustumCulled = false;
    return marker;
}

function ensureMeasurementPointMarker(index) {
    const group = ensureMeasurementOverlayGroup();
    if (!group) return null;
    while (state.measurement.pointMarkers.length <= index) {
        const marker = createMeasurementPointMarker(
            state.measurement.pointMarkers.length === 0 ? 0x38bdf8 : 0xf59e0b
        );
        state.measurement.pointMarkers.push(marker);
        group.add(marker);
    }
    return state.measurement.pointMarkers[index];
}

function ensureMeasurementLabel(index) {
    if (!el.canvasContainer) return null;
    while (state.measurement.labelElements.length <= index) {
        const label = document.createElement('div');
        label.className = 'measurement-overlay-label hidden';
        label.setAttribute('aria-hidden', 'true');
        el.canvasContainer.appendChild(label);
        state.measurement.labelElements.push(label);
    }
    return state.measurement.labelElements[index];
}

function hideMeasurementOverlay() {
    state.measurement.lineGroup && (state.measurement.lineGroup.visible = false);
    Object.values(state.measurement.lines).forEach((line) => {
        if (line) line.visible = false;
    });
    state.measurement.pointMarkers.forEach((marker) => { marker.visible = false; });
    state.measurement.labelElements.forEach((label) => {
        label.classList.add('hidden');
        label._measurementWorldPoint = null;
    });
    state.measurement.labelAnchors = [];
}

function updateMeasurementLabelPositions() {
    if ((!state.measurement.active && !state.placement.active)
        || !el.canvasContainer || !state.camera || !state.renderer) return;
    const rendererBounds = state.renderer.domElement.getBoundingClientRect();
    const containerBounds = el.canvasContainer.getBoundingClientRect();
    state.measurement.labelElements.forEach((label) => {
        const worldPoint = label._measurementWorldPoint;
        if (!worldPoint) {
            label.classList.add('hidden');
            return;
        }
        const projected = worldPoint.clone().project(state.camera);
        const visible = projected.z >= -1 && projected.z <= 1;
        label.classList.toggle('hidden', !visible);
        if (!visible) return;
        const x = rendererBounds.left - containerBounds.left
            + (projected.x * 0.5 + 0.5) * rendererBounds.width;
        const y = rendererBounds.top - containerBounds.top
            + (-projected.y * 0.5 + 0.5) * rendererBounds.height;
        label.style.left = `${x}px`;
        label.style.top = `${y}px`;
    });
}

function setMeasurementLabel(index, text, worldPoint) {
    const label = ensureMeasurementLabel(index);
    if (!label || !worldPoint) return;
    label.textContent = text;
    label._measurementWorldPoint = worldPoint.clone();
    label.classList.remove('hidden');
}

function getMeasurementWorldPoints() {
    const placement = state.placement;
    if (placement.active) {
        return [placement.sourceWorldPoint, placement.directionWorldPoint];
    }
    return state.measurement.points.map((point) => point?.worldPoint || null);
}

function setMeasurementLinePoints(name, points, visible) {
    const line = state.measurement.lines[name];
    if (!line) return;
    line.visible = Boolean(visible && points?.length >= 2);
    if (line.visible) line.geometry.setFromPoints(points);
}

function updateMeasurementOverlay() {
    const measurement = state.measurement;
    const placement = state.placement;
    if (!measurement.active && !placement.active) {
        hideMeasurementOverlay();
        updatePrimitiveDimensionOverlay();
        return;
    }

    if (placement.active && placement.model
        && (placement.sourcePoint || placement.directionPoint)
        && (!state.models.includes(placement.model)
            || !isVisibleSceneObject(getPlacementTransformTarget()))) {
        restorePlacementPreview();
        placement.model = null;
        placement.target = null;
        resetPlacementSelection();
        return;
    }
    if (placement.active && placement.model
        && placement.previewOriginalTransform && placement.previewTransform
        && !isPlacementTransformUnchanged(getPlacementTransformTarget(), placement.previewTransform)) {
        restorePlacementPreview();
        placement.model = null;
        placement.target = null;
        resetPlacementSelection();
        return;
    }
    if (placement.active) {
        hideMeasurementOverlay();
        updatePlacementDimensionOverlay();
        return;
    }

    if (measurement.active && !placement.active) {
        const hasPoints = measurement.points.some(Boolean);
        const valid = measurement.points.filter(Boolean).every(syncMeasurementPointWorldPoint);
        measurement.stale = hasPoints && !valid;
        if (measurement.stale) {
            measurement.result = null;
            if (measurement.statusMessage !== '측정 대상이 숨겨졌거나 삭제되었습니다. 다시 측정하세요.') {
                setMeasurementPanelStatus('측정 대상이 숨겨졌거나 삭제되었습니다. 다시 측정하세요.');
            }
        } else if (measurement.points[0] && measurement.points[1]) {
            const result = calculateMeasurementResult(
                measurement.points[0].worldPoint,
                measurement.points[1].worldPoint
            );
            measurement.result = result?.isSamePoint ? null : result;
        } else if (isRobotPositionMeasurement() && measurement.points[0]) {
            measurement.result = calculateRobotPositionMeasurement(measurement.points[0]);
        }
    }

    const [firstPoint, secondPoint] = getMeasurementWorldPoints();
    if (!firstPoint) {
        hideMeasurementOverlay();
        updateMeasurementLabelPositions();
        return;
    }
    const group = ensureMeasurementOverlayGroup();
    if (!group) return;
    group.visible = !measurement.stale;
    const firstMarker = ensureMeasurementPointMarker(0);
    if (firstMarker) {
        firstMarker.position.copy(firstPoint);
        firstMarker.visible = !measurement.stale;
    }
    const secondMarker = ensureMeasurementPointMarker(1);
    if (secondMarker) {
        secondMarker.visible = Boolean(secondPoint && !measurement.stale);
        if (secondPoint) secondMarker.position.copy(secondPoint);
    }
    state.measurement.labelElements.forEach((label) => {
        label.classList.add('hidden');
        label._measurementWorldPoint = null;
    });
    if (isRobotPositionMeasurement() && !measurement.stale) {
        Object.values(measurement.lines).forEach((line) => { if (line) line.visible = false; });
        const robotPosition = measurement.result || calculateRobotPositionMeasurement(measurement.points[0]);
        measurement.result = robotPosition;
        if (robotPosition) {
            setMeasurementLabel(0, formatRobotPositionMeasurement(robotPosition), firstPoint);
        }
        updateMeasurementLabelPositions();
        return;
    }

    if (!secondPoint || measurement.stale) {
        Object.values(measurement.lines).forEach((line) => { if (line) line.visible = false; });
        updateMeasurementLabelPositions();
        return;
    }

    const result = calculateMeasurementResult(firstPoint, secondPoint);
    if (!result || result.isSamePoint) {
        Object.values(measurement.lines).forEach((line) => { if (line) line.visible = false; });
        updateMeasurementLabelPositions();
        return;
    }
    measurement.result = result;
    const displayMode = placement.active ? 'diagonal' : measurement.displayMode;
    const pX = new THREE.Vector3(secondPoint.x, firstPoint.y, firstPoint.z);
    const pY = new THREE.Vector3(secondPoint.x, secondPoint.y, firstPoint.z);
    if (displayMode === 'orthogonal') {
        ensureMeasurementLine('x', 0xef4444);
        ensureMeasurementLine('y', 0x22c55e);
        ensureMeasurementLine('z', 0x3b82f6);
        setMeasurementLinePoints('diagonal', [], false);
        setMeasurementLinePoints('x', [firstPoint, pX], result.orthogonalX > 1e-9);
        setMeasurementLinePoints('y', [pX, pY], result.orthogonalY > 1e-9);
        setMeasurementLinePoints('z', [pY, secondPoint], result.orthogonalZ > 1e-9);
        setMeasurementLabel(0, `X = ${formatMeasurementNumber(result.orthogonalX)} mm`, firstPoint.clone().lerp(pX, 0.5));
        setMeasurementLabel(1, `Y = ${formatMeasurementNumber(result.orthogonalY)} mm`, pX.clone().lerp(pY, 0.5));
        setMeasurementLabel(2, `Z = ${formatMeasurementNumber(result.orthogonalZ)} mm`, pY.clone().lerp(secondPoint, 0.5));
    } else {
        ensureMeasurementLine('diagonal', 0xfacc15);
        setMeasurementLinePoints('diagonal', [firstPoint, secondPoint], true);
        ['x', 'y', 'z'].forEach((name) => setMeasurementLinePoints(name, [], false));
        setMeasurementLabel(0, `${uiText('Distance')} = ${formatMeasurementNumber(result.diagonal)} mm`, firstPoint.clone().lerp(secondPoint, 0.5));
    }
    updateMeasurementLabelPositions();
}

function updateMeasurementUi() {
    const measurement = state.measurement;
    const placement = state.placement;
    const placementActive = placement.active;
    const measurementActive = measurement.active && !placementActive;
    const displayMode = measurement.displayMode;
    const p1 = placementActive ? placement.sourcePoint : measurement.points[0];
    const p2 = placementActive ? placement.directionPoint : measurement.points[1];
    const result = measurement.result;
    if (el.measurementState) {
        el.measurementState.dataset.sourceMessage = measurement.statusMessage || 'P1 선택';
        el.measurementState.textContent = uiText(measurement.statusMessage || 'P1 선택');
    }
    if (el.measurementSnapType) {
        el.measurementSnapType.value = measurement.snapType;
        el.measurementSnapType.disabled = !measurementActive;
    }
    el.measurementSnapControls?.classList.toggle('hidden', !measurementActive);
    if (el.measurementHoverReadout) {
        el.measurementHoverReadout.textContent = measurementActive && measurement.hover
            ? `${uiText(snapTypeInfo(measurement.hover.type).label)} · ${formatMeasurementPoint(measurement.hover.worldPoint)}`
            : uiText('모델 형상 위로 포인터를 이동하세요.');
    }
    if (el.modelPlacementSnapType) el.modelPlacementSnapType.value = placement.snapType;
    if (el.modelPlacementHoverReadout) {
        el.modelPlacementHoverReadout.textContent = placementActive && placement.hover
            ? `${uiText(snapTypeInfo(placement.hover.type).label)} · ${formatMeasurementPoint(placement.hover.worldPoint)}`
            : uiText('모델 형상 위로 포인터를 이동하세요.');
    }
    if (el.measurementP1Readout) el.measurementP1Readout.textContent = formatMeasurementPoint(measurementActive ? p1 : measurement.points[0]);
    if (el.measurementP2Readout) el.measurementP2Readout.textContent = formatMeasurementPoint(measurementActive ? p2 : measurement.points[1]);
    el.measurementP2Row?.classList.toggle('hidden', displayMode === 'robot-position');
    el.measurementDisplaySection?.classList.toggle('hidden', !measurementActive);
    el.measurementResult?.classList.toggle('hidden', !measurementActive);
    el.measurementPlacementSection?.classList.toggle('hidden', !placementActive);
    setModelPlacementUiVisibility(placementActive);
    el.btnMeasurementRemeasure?.classList.toggle('hidden', !measurementActive);
    el.btnMeasurementDelete?.classList.toggle('hidden', !measurementActive);
    el.measurementDisplayInputs.forEach((input) => {
        input.disabled = !measurementActive;
        input.checked = input.value === displayMode;
    });
    el.measurementDiagonalResult?.classList.toggle(
        'hidden', displayMode !== 'diagonal'
    );
    if (el.measurementDiagonalResult) {
        el.measurementDiagonalResult.textContent = result && displayMode === 'diagonal'
            ? `${uiText('Distance')} = ${formatMeasurementNumber(result.diagonal)} mm`
            : `${uiText('Distance')} = - mm`;
    }
    el.measurementOrthogonalResult?.classList.toggle(
        'hidden', displayMode !== 'orthogonal' || !result
    );
    el.measurementRobotPositionResult?.classList.toggle('hidden', displayMode !== 'robot-position');
    if (el.measurementRobotPositionResult) {
        const rows = el.measurementRobotPositionResult.children;
        const values = result && displayMode === 'robot-position'
            ? [result.x, result.y, result.z]
            : [null, null, null];
        values.forEach((value, index) => {
            if (rows[index]) {
                rows[index].textContent = `${['X', 'Y', 'Z'][index]} = ${value === null ? '-' : formatMeasurementNumber(value)} mm`;
            }
        });
    }
    if (result && displayMode !== 'robot-position') {
        if (el.measurementDeltaX) el.measurementDeltaX.textContent = `ΔX ${formatMeasurementNumber(result.dx)}`;
        if (el.measurementDeltaY) el.measurementDeltaY.textContent = `ΔY ${formatMeasurementNumber(result.dy)}`;
        if (el.measurementDeltaZ) el.measurementDeltaZ.textContent = `ΔZ ${formatMeasurementNumber(result.dz)}`;
        const x = el.measurementOrthogonalResult?.children?.[0];
        const y = el.measurementOrthogonalResult?.children?.[1];
        const z = el.measurementOrthogonalResult?.children?.[2];
        if (x) x.firstChild.textContent = `X = ${formatMeasurementNumber(result.orthogonalX)} mm `;
        if (y) y.firstChild.textContent = `Y = ${formatMeasurementNumber(result.orthogonalY)} mm `;
        if (z) z.firstChild.textContent = `Z = ${formatMeasurementNumber(result.orthogonalZ)} mm `;
    }
    if (el.btnMeasurementRemeasure) el.btnMeasurementRemeasure.disabled = false;
    if (el.btnMeasurementDelete) el.btnMeasurementDelete.disabled = !p1 && !p2;

    const currentPlacementTargetPoint = placement.targetPoint
        || (placement.dimensionTranslation?.lengthSq() > 1e-18
            ? placement.dimensionTargetWorldPoint
            : null);
    if (el.measurementPlacementTargetPoint) {
        el.measurementPlacementTargetPoint.textContent = currentPlacementTargetPoint
            ? formatMeasurementPoint(currentPlacementTargetPoint) : '-';
    }
    const previewReady = Boolean(
        placement.previewTranslation && placement.targetPoint && !placement.applied
    );
    if (el.btnMeasurementApplyPlacement) el.btnMeasurementApplyPlacement.disabled = !previewReady;
    if (el.btnMeasurementCancelPlacement) el.btnMeasurementCancelPlacement.disabled = !previewReady;
    if (el.btnMeasurementResetPlacement) el.btnMeasurementResetPlacement.disabled = !p1 && !p2;
}

function capturePlacementModelTransform(model) {
    if (!model) return null;
    if (model.matrixAutoUpdate !== false) model.updateMatrix();
    return {
        position: model.position.clone(),
        quaternion: model.quaternion.clone(),
        scale: model.scale.clone(),
        matrix: model.matrix.clone(),
        matrixAutoUpdate: model.matrixAutoUpdate !== false
    };
}

function restorePlacementModelTransform(model, snapshot) {
    if (!model || !snapshot) return;
    model.position.copy(snapshot.position);
    model.quaternion.copy(snapshot.quaternion);
    model.scale.copy(snapshot.scale);
    model.matrixAutoUpdate = snapshot.matrixAutoUpdate !== false;
    if (model.matrixAutoUpdate) model.updateMatrix();
    else model.matrix.copy(snapshot.matrix);
    model.updateMatrixWorld(true);
    markSceneCollisionDirty(model);
}

function getPlacementTargetWorldPosition(target = getPlacementTransformTarget()) {
    if (!target) return null;
    target.updateMatrixWorld(true);
    return target.getWorldPosition(new THREE.Vector3());
}

function capturePlacementDimensionOrigin() {
    const placement = state.placement;
    const current = getPlacementTargetWorldPosition();
    if (!current) return false;
    placement.dimensionOriginWorldPoint = current.clone();
    placement.dimensionTargetWorldPoint = current.clone();
    placement.dimensionTranslation = new THREE.Vector3();
    return true;
}

function updatePlacementDimensionFromTarget() {
    const placement = state.placement;
    const current = getPlacementTargetWorldPosition();
    if (!current || !placement.dimensionOriginWorldPoint) return false;
    placement.dimensionTargetWorldPoint = current.clone();
    placement.dimensionTranslation = current.clone().sub(placement.dimensionOriginWorldPoint);
    return true;
}

function applyPlacementDimensionTranslation(translation) {
    const placement = state.placement;
    const target = getPlacementTransformTarget();
    if (!placement.active || !placement.model || !target
        || !placement.dimensionOriginWorldPoint || !translation
        || !['x', 'y', 'z'].every((axis) => Number.isFinite(translation[axis]))) {
        return false;
    }
    const current = getPlacementTargetWorldPosition(target);
    const targetPoint = placement.dimensionOriginWorldPoint.clone().add(translation);
    if (!current || !applyWorldTranslationToModel(target, current, targetPoint)) return false;
    placement.previewTranslation = null;
    placement.previewOriginalTransform = null;
    placement.previewTransform = null;
    placement.targetPoint = null;
    placement.targetDistance = null;
    placement.applied = false;
    updatePlacementDimensionFromTarget();
    setMeasurementPanelStatus('모델 위치를 변경했습니다.');
    updateMeasurementUi();
    updateMeasurementOverlay();
    requestRender();
    return true;
}

function handlePlacementTransformObjectChange(target) {
    const placement = state.placement;
    if (!placement.active || !target || target !== getPlacementTransformTarget()) return false;
    const changedSinceSnapPreview = placement.previewOriginalTransform
        ? !isPlacementTransformUnchanged(target, placement.previewOriginalTransform)
        : Boolean(placement.applied || placement.previewTranslation);
    if (changedSinceSnapPreview) {
        placement.previewOriginalTransform = null;
        placement.previewTransform = null;
        placement.previewTranslation = null;
        placement.targetPoint = null;
        placement.targetDistance = null;
        placement.applied = false;
        setMeasurementPanelStatus('모델 위치를 직접 조정했습니다.');
    }
    return updatePlacementDimensionFromTarget();
}

function restorePlacementPreview() {
    const placement = state.placement;
    const target = getPlacementTransformTarget();
    if (target && placement.previewOriginalTransform) {
        restorePlacementModelTransform(target, placement.previewOriginalTransform);
    }
    placement.previewOriginalTransform = null;
    placement.previewTransform = null;
    placement.previewTranslation = null;
    placement.targetPoint = null;
    updatePlacementDimensionFromTarget();
}

function isPlacementTransformUnchanged(model, snapshot) {
    if (!model || !snapshot) return true;
    const current = capturePlacementModelTransform(model);
    return current.position.distanceToSquared(snapshot.position) <= 1e-12
        && 1 - Math.abs(current.quaternion.dot(snapshot.quaternion)) <= 1e-12
        && current.scale.distanceToSquared(snapshot.scale) <= 1e-12;
}

function applyWorldTranslationToModel(model, sourceWorldPoint, targetWorldPoint) {
    if (!model?.parent || !sourceWorldPoint || !targetWorldPoint) return false;
    const parent = model.parent;
    parent.updateMatrixWorld(true);
    const sourceLocal = parent.worldToLocal(sourceWorldPoint.clone());
    const targetLocal = parent.worldToLocal(targetWorldPoint.clone());
    model.position.add(targetLocal.sub(sourceLocal));
    model.updateMatrixWorld(true);
    markSceneCollisionDirty(model);
    return true;
}

function updatePlacementPreview() {
    const placement = state.placement;
    if (!placement.active || !placement.model || !getPlacementTransformTarget()
        || !placement.sourceWorldPoint || !placement.directionWorldPoint) {
        updateMeasurementUi();
        return false;
    }
    const targetDistance = Number.isFinite(placement.targetDistance)
        ? placement.targetDistance
        : NaN;
    if (!isValidTargetDistance(targetDistance)) {
        placement.targetDistance = null;
        placement.targetPoint = null;
        placement.previewTranslation = null;
        setMeasurementPanelStatus('이동 거리는 0 이상의 유한한 값이어야 합니다.');
        updateMeasurementUi();
        return false;
    }
    const calculated = calculatePlacementTarget(
        placement.sourceWorldPoint,
        placement.directionWorldPoint,
        targetDistance
    );
    if (!calculated) {
        placement.targetDistance = null;
        placement.targetPoint = null;
        placement.previewTranslation = null;
        setMeasurementPanelStatus('P1과 P2는 서로 다른 스냅 점이어야 합니다.');
        updateMeasurementUi();
        return false;
    }
    const updated = updatePlacementPreviewFromTranslation(new THREE.Vector3(
        calculated.translation.x,
        calculated.translation.y,
        calculated.translation.z
    ));
    if (updated) setMeasurementPanelStatus('배치 미리보기가 적용되었습니다. 적용 또는 취소를 선택하세요.');
    return updated;
}

function updatePlacementPreviewFromTranslation(translation) {
    const placement = state.placement;
    const target = getPlacementTransformTarget();
    if (!placement.active || !placement.model || !target || !placement.sourceWorldPoint
        || !translation || !['x', 'y', 'z'].every((axis) => Number.isFinite(translation[axis]))) {
        return false;
    }
    if (placement.applied) return false;
    if (!placement.previewOriginalTransform) {
        placement.previewOriginalTransform = capturePlacementModelTransform(target);
    } else {
        restorePlacementModelTransform(target, placement.previewOriginalTransform);
    }
    placement.targetPoint = placement.sourceWorldPoint.clone().add(translation);
    placement.previewTranslation = translation.clone();
    placement.targetDistance = translation.length();
    placement.currentDistance = placement.directionWorldPoint
        ? placement.sourceWorldPoint.distanceTo(placement.directionWorldPoint)
        : null;
    applyWorldTranslationToModel(target, placement.sourceWorldPoint, placement.targetPoint);
    placement.previewTransform = capturePlacementModelTransform(target);
    updateMeasurementUi();
    updateMeasurementOverlay();
    requestRender();
    return true;
}

function resetPlacementSelection() {
    const placement = state.placement;
    restorePlacementPreview();
    placement.sourcePoint = null;
    placement.directionPoint = null;
    placement.sourceWorldPoint = null;
    placement.directionWorldPoint = null;
    placement.targetDistance = null;
    placement.currentDistance = null;
    placement.applied = false;
    placement.hover = null;
    state.measurement.points = [null, null];
    state.measurement.robotPositionRobotId = null;
    state.measurement.result = null;
    state.measurement.stale = false;
    setMeasurementPanelStatus(placement.model
        ? 'P1 기준점을 선택하세요.'
        : '모델 트리에서 이동할 모델을 먼저 선택하세요.');
    hideSimulationSnapMarker();
    updateMeasurementUi();
    updateMeasurementOverlay();
}

function activateModelPlacement(model) {
    if (!model || !state.models.includes(model)) return false;
    if (state.placement.active && state.placement.model === model) return true;

    if (state.measurement.active) deactivateMeasurementPanel();
    if (state.zeroPointEdit.active) exitZeroPointEditor();
    if (state.snapMoveMode) {
        state.snapMoveMode = false;
        clearSimulationSnapFaceSelection({ invalidate: false });
    }
    if (state.tcpSnapMode) setTcpSnapMode(false);
    clearSimulationSnapFaceSelection({ invalidate: false });

    const placement = state.placement;
    placement.active = true;
    placement.model = model;
    placement.target = state.selectedModel === model
        ? getSelectedModelTransformTarget()
        : model;
    placement.hover = null;
    placement.sourcePoint = null;
    placement.directionPoint = null;
    placement.sourceWorldPoint = null;
    placement.directionWorldPoint = null;
    placement.targetDistance = null;
    placement.currentDistance = null;
    placement.targetPoint = null;
    placement.previewTranslation = null;
    placement.previewOriginalTransform = null;
    placement.previewTransform = null;
    capturePlacementDimensionOrigin();
    placement.applied = false;
    state.measurement.active = false;
    state.measurement.points = [null, null];
    state.measurement.robotPositionRobotId = null;
    state.measurement.result = null;
    state.measurement.hover = null;
    state.measurement.stale = false;
    state.snapLastPointerEvent = null;
    el.measurementPanel?.classList.add('panel-user-hidden');
    updatePanelLauncher('measurement-panel');
    updatePanelStack();
    setSelectedTransformMode('translate', false);
    setTransformHandlesEnabled(true);
    setMeasurementPanelStatus('P1 기준점을 선택하세요.');
    updateSimulationSnapButton();
    syncModelOutlines();
    updateTcpSnapUi();
    updateMeasurementUi();
    updateMeasurementOverlay();
    captureSimulationSnapMarkerReferenceDistance();
    invalidateSimulationSnapCandidates();
    setStatus('선택 모델의 P1 기준점을 선택하세요.', '#60a5fa');
    void buildSimulationSnapCandidates('placement').then(() => {
        if (state.placement.active && !getSimulationSnapFaceSelections().length) {
            const directSnapAvailable = getSimulationSnapMeshes('placement')
                .some(isDirectSimulationSnapMesh);
            const message = directSnapAvailable
                ? '모델 형상 위로 이동하면 스냅 후보가 표시됩니다.'
                : '스냅할 3D 모델의 면을 클릭하세요.';
            setMeasurementPanelStatus(message);
            setStatus(message, '#60a5fa');
        }
    }).catch((error) => {
        console.warn('Model placement snap candidate generation failed:', error);
    });
    return true;
}

function deactivateModelPlacement() {
    const placement = state.placement;
    restorePlacementPreview();
    placement.active = false;
    placement.model = null;
    placement.target = null;
    placement.sourcePoint = null;
    placement.directionPoint = null;
    placement.sourceWorldPoint = null;
    placement.directionWorldPoint = null;
    placement.targetDistance = null;
    placement.currentDistance = null;
    placement.targetPoint = null;
    placement.previewTranslation = null;
    placement.previewTransform = null;
    placement.previewOriginalTransform = null;
    placement.dimensionOriginWorldPoint = null;
    placement.dimensionTargetWorldPoint = null;
    placement.dimensionTranslation = null;
    placement.hover = null;
    placement.applied = false;
    state.measurement.active = false;
    state.measurement.points = [null, null];
    state.measurement.robotPositionRobotId = null;
    state.measurement.result = null;
    state.measurement.hover = null;
    state.measurement.stale = false;
    clearSimulationSnapFaceSelection({ invalidate: false });
    invalidateSimulationSnapCandidates();
    hideSimulationSnapMarker();
    resetSimulationSnapMarkerCameraScale();
    setTransformHandlesEnabled(false);
    updateSimulationSnapButton();
    syncModelOutlines();
    updateTcpSnapUi();
    updateMeasurementUi();
    updateMeasurementOverlay();
    return true;
}

function handleMeasurementSnapSelection(snap) {
    const measurement = state.measurement;
    const placementActive = state.placement.active;
    if ((!measurement.active && !placementActive) || !snap) return false;
    const point = createMeasurementPoint(snap);
    if (!point) return false;
    hideSimulationSnapMarker();
    if (!placementActive) {
        if (isRobotPositionMeasurement()) {
            const robot = getSelectedRobotModel();
            if (!robot) {
                setMeasurementPanelStatus('선택된 로봇이 없습니다. 로봇을 선택하세요.');
                setStatus('로봇 위치를 측정하려면 로봇을 선택하세요.', '#f59e0b');
                updateMeasurementUi();
                return false;
            }
            measurement.points = [point, null];
            measurement.robotPositionRobotId = robot.userData?.motionInstanceId || null;
            measurement.result = calculateRobotPositionMeasurement(point);
            measurement.stale = false;
            setMeasurementPanelStatus(measurement.result ? '측정 완료' : '선택된 로봇이 없습니다. 로봇을 선택하세요.');
            setStatus(
                measurement.result
                    ? '선택한 지점의 로봇 위치를 표시했습니다.'
                    : '로봇 위치를 측정하려면 로봇을 선택하세요.',
                measurement.result ? '#22c55e' : '#f59e0b'
            );
            updateMeasurementUi();
            updateMeasurementOverlay();
            requestRender();
            return Boolean(measurement.result);
        }
        if (!measurement.points[0] || measurement.points[1]) {
            measurement.points = [point, null];
            measurement.result = null;
            measurement.stale = false;
            setMeasurementPanelStatus('P2 선택');
            setStatus('P1을 선택했습니다. 두 번째 스냅 점 P2를 선택하세요.', '#60a5fa');
        } else {
            const result = calculateMeasurementResult(measurement.points[0].worldPoint, point.worldPoint);
            if (!result || result.isSamePoint) {
                measurement.points[1] = null;
                measurement.result = null;
                setMeasurementPanelStatus('P1과 P2는 서로 다른 스냅 점이어야 합니다.');
                setStatus('P1과 P2는 서로 다른 스냅 점이어야 합니다.', '#f59e0b');
            } else {
                measurement.points[1] = point;
                measurement.result = result;
                measurement.stale = false;
                setMeasurementPanelStatus('측정 완료');
                setStatus('두 점 사이의 치수를 표시했습니다.', '#22c55e');
            }
        }
        updateMeasurementUi();
        updateMeasurementOverlay();
        requestRender();
        return true;
    }

    const placement = state.placement;
    if (!placement.sourcePoint || placement.directionPoint) {
        selectSceneModel(placement.model, { preservePart: true });
        placement.sourcePoint = point;
        placement.directionPoint = null;
        placement.sourceWorldPoint = point.worldPoint.clone();
        placement.directionWorldPoint = null;
        placement.targetDistance = null;
        placement.currentDistance = null;
        placement.applied = false;
        placement.previewOriginalTransform = capturePlacementModelTransform(getPlacementTransformTarget());
        measurement.points = [point, null];
        setMeasurementPanelStatus('P2 방향점을 선택하세요.');
        setStatus('P1 기준점을 선택했습니다. 목표 방향의 P2를 선택하세요.', '#60a5fa');
        // The face selected to generate P1 candidates must not constrain the
        // next point. P2 may belong to a different part, so release the
        // temporary face scope before rebuilding candidates for the scene.
        clearSimulationSnapFaceSelection({ invalidate: false });
        invalidateSimulationSnapCandidates();
        void buildSimulationSnapCandidates('placement').catch((error) => {
            console.warn('Cross-model placement snap candidate generation failed:', error);
        });
    } else {
        placement.directionPoint = point;
        placement.directionWorldPoint = point.worldPoint.clone();
        measurement.points = [placement.sourcePoint, point];
        const result = calculateMeasurementResult(
            placement.sourceWorldPoint,
            placement.directionWorldPoint
        );
        if (!result || result.isSamePoint) {
            placement.directionPoint = null;
            placement.directionWorldPoint = null;
            measurement.points[1] = null;
            setMeasurementPanelStatus('P1과 P2는 서로 다른 스냅 점이어야 합니다.');
            setStatus('P1과 P2는 서로 다른 스냅 점이어야 합니다.', '#f59e0b');
        } else {
            placement.currentDistance = result.diagonal;
            placement.targetDistance = result.diagonal;
            placement.applied = false;
            updatePlacementPreview();
        }
    }
    updateMeasurementUi();
    updateMeasurementOverlay();
    requestRender();
    return true;
}

function resetMeasurementSelection() {
    state.measurement.points = [null, null];
    state.measurement.robotPositionRobotId = null;
    state.measurement.result = null;
    state.measurement.hover = null;
    state.measurement.stale = false;
    setMeasurementPanelStatus('P1 선택');
    hideSimulationSnapMarker();
    updateMeasurementUi();
    updateMeasurementOverlay();
    setStatus('다시 측정할 P1 스냅 점을 선택하세요.', '#60a5fa');
}

function deleteMeasurement() {
    state.measurement.points = [null, null];
    state.measurement.robotPositionRobotId = null;
    state.measurement.result = null;
    state.measurement.hover = null;
    state.measurement.stale = false;
    setMeasurementPanelStatus('P1 선택');
    hideSimulationSnapMarker();
    updateMeasurementUi();
    updateMeasurementOverlay();
    setStatus('치수를 삭제했습니다.', '#22c55e');
}

function applyMeasurementPlacement() {
    const placement = state.placement;
    if (placement.applied || !placement.active || !placement.model
        || !placement.sourceWorldPoint || !placement.directionWorldPoint) return;
    if (!placement.previewTranslation && !updatePlacementPreview()) return;
    const previewTranslation = placement.previewTranslation?.clone();
    const previewTargetPoint = placement.targetPoint?.clone();
    if (!previewTranslation || !previewTargetPoint) return;
    restorePlacementPreview();
    const before = captureSceneSnapshot();
    if (!isValidTargetDistance(previewTranslation.length())) return;
    applyWorldTranslationToModel(
        getPlacementTransformTarget(),
        placement.sourceWorldPoint,
        previewTargetPoint
    );
    placement.targetPoint = previewTargetPoint;
    placement.currentDistance = placement.directionWorldPoint.distanceTo(placement.sourceWorldPoint);
    placement.previewTranslation = previewTranslation;
    placement.targetDistance = previewTranslation.length();
    const after = captureSceneSnapshot();
    placement.previewOriginalTransform = null;
    placement.applied = true;
    recordHistory('선택 모델 기준 배치', before, after);
    setMeasurementPanelStatus('모델 배치를 적용했습니다.');
    setStatus('입력한 거리 기준으로 모델을 배치했습니다.', '#22c55e');
    updateMeasurementUi();
    updateMeasurementOverlay();
    requestRender();
}

function cancelMeasurementPlacement() {
    if (!state.placement.previewOriginalTransform) return;
    restorePlacementPreview();
    setMeasurementPanelStatus('모델 배치 미리보기를 취소했습니다.');
    setStatus('모델 배치 미리보기를 취소했습니다.', '#60a5fa');
    updateMeasurementUi();
    updateMeasurementOverlay();
    requestRender();
}

function activateMeasurementPanel() {
    if (isMotionActive()) return;
    if (state.placement.active) deactivateModelPlacement();
    state.measurement.active = true;
    state.measurement.points = [null, null];
    state.measurement.robotPositionRobotId = null;
    state.measurement.result = null;
    state.measurement.hover = null;
    state.measurement.stale = false;
    state.placement.active = false;
    state.placement.model = null;
    state.placement.target = null;
    state.placement.sourcePoint = null;
    state.placement.directionPoint = null;
    state.placement.sourceWorldPoint = null;
    state.placement.directionWorldPoint = null;
    state.placement.targetDistance = null;
    state.placement.currentDistance = null;
    state.placement.previewTranslation = null;
    state.placement.previewOriginalTransform = null;
    state.placement.dimensionOriginWorldPoint = null;
    state.placement.dimensionTargetWorldPoint = null;
    state.placement.dimensionTranslation = null;
    if (state.snapMoveMode) {
        state.snapMoveMode = false;
        clearSimulationSnapFaceSelection({ invalidate: false });
    }
    if (state.zeroPointEdit.active && state.zeroPointEdit.snapMode) {
        setZeroPointSnapMode(false);
    }
    if (state.tcpSnapMode) setTcpSnapMode(false);
    clearSimulationSnapFaceSelection({ invalidate: false });
    invalidateSimulationSnapCandidates();
    setMeasurementPanelStatus('P1 선택');
    captureSimulationSnapMarkerReferenceDistance();
    updateSimulationSnapButton();
    updateTcpSnapUi();
    updateMeasurementUi();
    setStatus('치수 측정 모드입니다. P1 스냅 점을 선택하세요.', '#60a5fa');
    void buildSimulationSnapCandidates('measurement').then(() => {
        if (state.measurement.active
            && !getSimulationSnapFaceSelections().length) {
            const directSnapAvailable = getSimulationSnapMeshes('measurement')
                .some(isDirectSimulationSnapMesh);
            const message = directSnapAvailable
                ? '모델 형상 위로 이동하면 스냅 후보가 표시됩니다.'
                : '스냅할 3D 모델의 면을 클릭하세요.';
            setMeasurementPanelStatus(message);
            setStatus(message, '#60a5fa');
        }
    }).catch((error) => {
        console.warn('Measurement snap candidate generation failed:', error);
    });
}

function deactivateMeasurementPanel() {
    if (state.placement.active) deactivateModelPlacement();
    restorePlacementPreview();
    state.measurement.active = false;
    state.measurement.points = [null, null];
    state.measurement.robotPositionRobotId = null;
    state.measurement.result = null;
    state.measurement.hover = null;
    state.measurement.stale = false;
    state.placement.active = false;
    state.placement.model = null;
    state.placement.target = null;
    state.placement.sourcePoint = null;
    state.placement.directionPoint = null;
    state.placement.sourceWorldPoint = null;
    state.placement.directionWorldPoint = null;
    state.placement.targetDistance = null;
    state.placement.currentDistance = null;
    state.placement.applied = false;
    state.placement.dimensionOriginWorldPoint = null;
    state.placement.dimensionTargetWorldPoint = null;
    state.placement.dimensionTranslation = null;
    clearSimulationSnapFaceSelection({ invalidate: false });
    invalidateSimulationSnapCandidates();
    hideSimulationSnapMarker();
    resetSimulationSnapMarkerCameraScale();
    updateSimulationSnapButton();
    updateTcpSnapUi();
    updateMeasurementUi();
}

function closeMeasurementPanel() {
    el.measurementPanel?.classList.add('panel-user-hidden');
    deactivateMeasurementPanel();
    updatePanelLauncher('measurement-panel');
    updatePanelStack();
}

function resetTcpSnapPoints() {
    state.tcpSnapPoints = [];
    updateTcpMultiCenterControls();
}

function getTcpSnapCenter() {
    if (!state.tcpSnapPoints.length) return null;
    const center = new THREE.Vector3();
    state.tcpSnapPoints.forEach((point) => center.add(point));
    return center.multiplyScalar(1 / state.tcpSnapPoints.length);
}

function updateTcpMultiCenterControls() {
    const multi = isTcpMultiPointSnapMode();
    const count = state.tcpSnapPoints.length;
    if (el.tcpMultiCenterControls) el.tcpMultiCenterControls.classList.toggle('hidden', !multi);
    if (el.tcpMultiCenterCount) {
        el.tcpMultiCenterCount.textContent = `${uiText('다중 점 선택')} ${count}/4`;
    }
    if (el.btnTcpMultiCenterApply) el.btnTcpMultiCenterApply.disabled = !multi || count < 2 || count > 4;
    if (el.btnTcpMultiCenterReset) el.btnTcpMultiCenterReset.disabled = !multi || count === 0;
}

function updateTcpSnapUi() {
    const available = Boolean(getJogTargetRobot()?.userData?.tcpFrame) && !isMotionActive();
    if (!available && state.tcpSnapMode) {
        state.tcpSnapMode = false;
        clearSimulationSnapFaceSelection({ invalidate: false });
        invalidateSimulationSnapCandidates();
        resetTcpSnapPoints();
        hideSimulationSnapMarker();
        resetSimulationSnapMarkerCameraScale();
    }
    if (el.btnTcpSnap) {
        el.btnTcpSnap.disabled = !available;
        el.btnTcpSnap.classList.toggle('active', state.tcpSnapMode);
        el.btnTcpSnap.setAttribute('aria-pressed', String(state.tcpSnapMode));
        el.btnTcpSnap.title = uiText(state.tcpSnapMode ? 'TCP 위치 스냅 종료' : 'TCP 위치 스냅');
    }
    if (el.tcpSnapType) el.tcpSnapType.disabled = !available;
    el.canvasContainer?.classList.toggle('tcp-snap-picking', state.tcpSnapMode);
    updateTcpMultiCenterControls();
}

function setTcpSnapMode(enabled) {
    state.tcpSnapMode = Boolean(enabled);
    if (state.tcpSnapMode) {
        state.snapMoveMode = false;
        clearSimulationSnapFaceSelection({ invalidate: false });
        state.snapLastPointerEvent = null;
        resetTcpSnapPoints();
        captureSimulationSnapMarkerReferenceDistance();
        setTcpSnapReadout('스냅할 3D 모델의 면을 클릭하세요.');
        setStatus('스냅할 3D 모델의 면을 클릭하세요.', '#60a5fa');
        updateSimulationSnapButton();
        updateTcpSnapUi();
        void buildSimulationSnapCandidates('tool')
            .then(() => {
                if (state.tcpSnapMode) {
                    const hasFaceSelection = getSimulationSnapFaceSelections().length > 0;
                    const message = hasFaceSelection
                        ? '선택한 면의 스냅 후보를 클릭하세요.'
                        : '스냅할 3D 모델의 면을 클릭하세요.';
                    setTcpSnapReadout(message);
                    setStatus(message, '#60a5fa');
                }
            })
            .catch((error) => {
                console.warn('TCP snap candidate generation failed:', error);
                if (state.tcpSnapMode) {
                    setTcpSnapMode(false);
                    setStatus('선택 가능한 스냅 지점을 가리켜 주세요.', '#ef4444');
                }
            });
    } else {
        clearSimulationSnapFaceSelection({ invalidate: false });
        invalidateSimulationSnapCandidates();
        resetTcpSnapPoints();
        hideSimulationSnapMarker();
        resetSimulationSnapMarkerCameraScale();
        setTcpSnapReadout('3D 모델링의 스냅 지점을 클릭하세요.');
        updateTcpSnapUi();
    }
}

function toggleTcpSnapMode() {
    if (isMotionActive()) return;
    if (state.measurement.active) closeMeasurementPanel();
    if (state.placement.active) deactivateModelPlacement();
    if (!getJogTargetRobot()?.userData?.tcpFrame) {
        setStatus('스냅 이동할 로봇을 먼저 선택하세요.', '#ef4444');
        return;
    }
    if (!state.tcpSnapMode && getSimulationSnapMeshes('tool').length === 0) {
        setStatus('TCP 스냅할 Tool 모델 또는 생성 도형을 먼저 준비하세요.', '#f59e0b');
        return;
    }
    setTcpSnapMode(!state.tcpSnapMode);
}

function hideSimulationSnapMarker() {
    state.snapHover = null;
    state.snapLastPointerEvent = null;
    if (state.measurement.active) {
        state.measurement.hover = null;
    }
    if (state.placement.active) state.placement.hover = null;
    if (state.measurement.active || state.placement.active) updateMeasurementUi();
    if (state.snapPointerMoveFrame !== null) {
        cancelAnimationFrame(state.snapPointerMoveFrame);
        state.snapPointerMoveFrame = null;
    }
    el.snapMarker?.classList.add('hidden');
}

function updateSimulationSnapMarkerCameraScale() {
    if (!isSimulationSnapInteractionActive()) return;
    if (!el.snapMarker || !state.camera || !state.controls) return;
    const cameraZoom = Math.max(state.camera.zoom || 1, Number.EPSILON);
    const cameraDistance = state.camera.position.distanceTo(state.controls.target) / cameraZoom;
    const referenceDistance = state.snapMarkerReferenceDistance;
    if (!Number.isFinite(cameraDistance) || !Number.isFinite(referenceDistance) || referenceDistance <= 0) return;

    const scale = THREE.MathUtils.clamp(
        Math.sqrt(cameraDistance / referenceDistance),
        SNAP_MARKER_CAMERA_SCALE.min,
        SNAP_MARKER_CAMERA_SCALE.max
    );
    el.snapMarker.style.setProperty('--simulation-snap-camera-scale', scale.toFixed(3));
}

function captureSimulationSnapMarkerReferenceDistance() {
    if (!state.camera || !state.controls) return;
    state.snapMarkerReferenceDistance = state.camera.position.distanceTo(state.controls.target)
        / Math.max(state.camera.zoom || 1, Number.EPSILON);
    updateSimulationSnapMarkerCameraScale();
}

function resetSimulationSnapMarkerCameraScale() {
    state.snapMarkerReferenceDistance = null;
    el.snapMarker?.style.setProperty('--simulation-snap-camera-scale', '1');
}

function simulationSnapMeshKey(mesh) {
    return `${mesh.uuid}:${mesh.geometry.uuid}`;
}

function scheduleLazySimulationSnapBuild(mesh) {
    const key = simulationSnapMeshKey(mesh);
    if (state.snapLazyReadyMeshes.has(key) || state.snapLazyBuildPromises.has(key)) return;
    const buildSignature = state.snapCandidateModelsSignature;
    const promise = (async () => {
        await yieldToAnimationFrame();
        if (state.snapCandidateModelsSignature !== buildSignature || !isSimulationSnapInteractionActive()) return;
        const result = buildSimulationSnapResultForMesh(mesh, true);
        if (!result?.candidates?.length) {
            state.snapLazyReadyMeshes.add(key);
            return;
        }
        if (state.snapCandidateModelsSignature !== buildSignature) return;
        const counts = {};
        state.snapCandidates.forEach((candidate) => {
            counts[candidate.type] = (counts[candidate.type] || 0) + 1;
        });
        result.candidates.forEach((candidate) => {
            const count = counts[candidate.type] || 0;
            const limit = SIMULATION_SNAP_MAX_PER_TYPE[candidate.type] || Infinity;
            if (count >= limit) return;
            counts[candidate.type] = count + 1;
            state.snapCandidates.push({
                type: candidate.type,
                mesh,
                localPoint: new THREE.Vector3().fromArray(candidate.point)
            });
        });
        state.snapLazyReadyMeshes.add(key);
        state.snapWorldIndex = null;
        state.snapWorldIndexSignature = '';
        const pointerEvent = state.snapLastPointerEvent;
        if (pointerEvent && isSimulationSnapInteractionActive()) {
            requestAnimationFrame(() => {
                if (isSimulationSnapInteractionActive()) {
                    showSimulationSnapMarker(findSimulationSnapAtPointer(pointerEvent));
                }
            });
        }
    })().catch((error) => {
        if (state.snapCandidateModelsSignature === buildSignature) {
            state.snapLazyReadyMeshes.add(key);
        }
        console.warn('Large-model snap chunk generation failed:', mesh.name, error);
    }).finally(() => {
        if (state.snapLazyBuildPromises.get(key) === promise) {
            state.snapLazyBuildPromises.delete(key);
        }
    });
    state.snapLazyBuildPromises.set(key, promise);
}

function getLazySimulationSnapMeshAtPointer(pointerX, pointerY, bounds, meshes) {
    const lazyMeshes = meshes.filter(isLazySimulationSnapMesh);
    if (!lazyMeshes.length || bounds.width <= 0 || bounds.height <= 0) return null;
    const pointer = new THREE.Vector2(
        (pointerX / bounds.width) * 2 - 1,
        -(pointerY / bounds.height) * 2 + 1
    );
    state.snapVisibilityRaycaster.setFromCamera(pointer, state.camera);
    return state.snapVisibilityRaycaster.intersectObjects(lazyMeshes, false)[0]?.object || null;
}

function isSimulationSnapCandidateVisible(candidate, projected, meshes) {
    if (isSimulationSnapReferenceCandidate(candidate)) return true;
    state.snapVisibilityRaycaster.setFromCamera(new THREE.Vector2(projected.x, projected.y), state.camera);
    const frontHit = state.snapVisibilityRaycaster.intersectObjects(meshes, false)[0] || null;
    if (!frontHit) return true;
    const candidateOffset = candidate.worldPoint.clone().sub(state.snapVisibilityRaycaster.ray.origin);
    const candidateDistance = candidateOffset.dot(state.snapVisibilityRaycaster.ray.direction);
    if (!Number.isFinite(candidateDistance) || candidateDistance <= 0) return false;
    const viewportHeight = Math.max(state.renderer.domElement.clientHeight, 1);
    const worldUnitsPerPixel = state.camera.isOrthographicCamera
        ? (state.camera.top - state.camera.bottom)
            / (viewportHeight * Math.max(state.camera.zoom || 1, Number.EPSILON))
        : (
            2 * candidateDistance * Math.tan(THREE.MathUtils.degToRad(state.camera.fov * 0.5))
        ) / viewportHeight;
    return candidateDistance <= frontHit.distance + Math.max(worldUnitsPerPixel * 2.5, 0.001);
}

function simulationSnapMatrixSignature(matrix) {
    return matrix.elements.join(',');
}

function getSimulationSnapWorldIndexSignature(meshes) {
    return [
        state.snapCandidateModelsSignature,
        ...meshes.map((mesh) => `${mesh.uuid}:${simulationSnapMatrixSignature(mesh.matrixWorld)}`)
    ].join('|');
}

function getSimulationSnapWorldIndexMeshes(meshes) {
    const indexedMeshes = new Set(meshes);
    state.snapCandidates.forEach((candidate) => {
        if (isSimulationSnapReferenceCandidate(candidate) && candidate.mesh) {
            indexedMeshes.add(candidate.mesh);
        }
    });
    return [...indexedMeshes];
}

function buildSimulationSnapWorldOctree(candidates, depth = 0) {
    const bounds = new THREE.Box3();
    candidates.forEach((candidate) => bounds.expandByPoint(candidate.snapWorldPoint));
    const sphere = new THREE.Sphere();
    bounds.getBoundingSphere(sphere);

    if (candidates.length <= SNAP_WORLD_INDEX_LEAF_SIZE || depth >= SNAP_WORLD_INDEX_MAX_DEPTH) {
        return {
            bounds,
            center: sphere.center,
            radius: sphere.radius,
            candidates,
            children: null
        };
    }

    const center = sphere.center;
    const buckets = Array.from({ length: 8 }, () => []);
    candidates.forEach((candidate) => {
        const point = candidate.snapWorldPoint;
        const bucketIndex = (point.x >= center.x ? 1 : 0)
            | (point.y >= center.y ? 2 : 0)
            | (point.z >= center.z ? 4 : 0);
        buckets[bucketIndex].push(candidate);
    });
    const nonEmptyBuckets = buckets.filter((bucket) => bucket.length > 0);
    if (nonEmptyBuckets.length <= 1) {
        return {
            bounds,
            center: sphere.center,
            radius: sphere.radius,
            candidates,
            children: null
        };
    }

    return {
        bounds,
        center: sphere.center,
        radius: sphere.radius,
        candidates: null,
        children: nonEmptyBuckets.map((bucket) => buildSimulationSnapWorldOctree(bucket, depth + 1))
    };
}

function getSimulationSnapWorldIndex(meshes) {
    const indexedMeshes = getSimulationSnapWorldIndexMeshes(meshes);
    indexedMeshes.forEach((mesh) => mesh.updateWorldMatrix?.(true, false));
    const signature = getSimulationSnapWorldIndexSignature(indexedMeshes);
    if (state.snapWorldIndex && state.snapWorldIndexSignature === signature) {
        return state.snapWorldIndex;
    }

    const candidates = [];
    state.snapCandidates.forEach((candidate) => {
        if (!candidate.mesh.visible) return;
        candidate.snapWorldPoint = (candidate.snapWorldPoint || new THREE.Vector3())
            .copy(candidate.localPoint)
            .applyMatrix4(candidate.mesh.matrixWorld);
        candidates.push(candidate);
    });

    state.snapWorldIndex = {
        signature,
        root: candidates.length ? buildSimulationSnapWorldOctree(candidates) : null
    };
    state.snapWorldIndexSignature = signature;
    return state.snapWorldIndex;
}

function isSimulationSnapOctreeNodeNearPointer(node, bounds, pointerX, pointerY, radius) {
    const cameraPoint = node.center.clone().applyMatrix4(state.camera.matrixWorldInverse);
    const depth = -cameraPoint.z;
    if (depth + node.radius <= state.camera.near || depth - node.radius >= state.camera.far) return false;
    if (depth <= node.radius) return true;

    const projected = node.center.clone().project(state.camera);
    if (!Number.isFinite(projected.x) || !Number.isFinite(projected.y) || !Number.isFinite(projected.z)) return true;
    const focalPixels = bounds.height * Math.max(state.camera.zoom || 1, Number.EPSILON)
        / (2 * Math.tan(THREE.MathUtils.degToRad(state.camera.fov * 0.5)));
    const screenRadius = node.radius * focalPixels
        / Math.max(depth - node.radius, Number.EPSILON) + radius;
    const screenX = (projected.x * 0.5 + 0.5) * bounds.width;
    const screenY = (-projected.y * 0.5 + 0.5) * bounds.height;
    return screenX >= pointerX - screenRadius
        && screenX <= pointerX + screenRadius
        && screenY >= pointerY - screenRadius
        && screenY <= pointerY + screenRadius;
}

// Kept as the old entry point for callers/tests; the index is now camera-independent.
function getSimulationSnapScreenIndex(meshes, bounds) {
    return getSimulationSnapWorldIndex(meshes);
}

function getSimulationSnapCandidatesNearPointer(meshes, bounds, pointerX, pointerY, radius) {
    const nearby = [];
    const index = getSimulationSnapScreenIndex(meshes, bounds);
    if (!index.root) return nearby;

    const projected = new THREE.Vector3();
    const visit = (node) => {
        if (!isSimulationSnapOctreeNodeNearPointer(node, bounds, pointerX, pointerY, radius)) return;
        if (node.children) {
            node.children.forEach(visit);
            return;
        }
        node.candidates.forEach((candidate) => {
            if (!candidate.mesh.visible || !candidate.snapWorldPoint) return;
            projected.copy(candidate.snapWorldPoint).project(state.camera);
            if (projected.z < -1 || projected.z > 1) return;
            const screenX = (projected.x * 0.5 + 0.5) * bounds.width;
            const screenY = (-projected.y * 0.5 + 0.5) * bounds.height;
            const pixelDistance = Math.hypot(screenX - pointerX, screenY - pointerY);
            if (pixelDistance <= radius) nearby.push(candidate);
        });
    };
    visit(index.root);
    return nearby;
}

function findSimulationSnapAtPointer(pointerEvent) {
    if (!isSimulationSnapInteractionActive()) return null;
    if (isCadOriginSnapPicking()) return findCadOriginSnapAtPointer(pointerEvent);
    const scope = getSimulationSnapScope();
    const meshes = getPreparedSimulationSnapMeshes(scope);
    const visibilityMeshes = isSimulationSnapFaceSelectionActive(scope)
        ? getAllSimulationSnapMeshes(scope)
        : meshes;
    state.camera.updateMatrixWorld(true);
    const bounds = state.renderer.domElement.getBoundingClientRect();
    const pointerX = pointerEvent.clientX - bounds.left;
    const pointerY = pointerEvent.clientY - bounds.top;
    const lazyMesh = getLazySimulationSnapMeshAtPointer(pointerX, pointerY, bounds, meshes);
    if (lazyMesh) {
        const lazyKey = simulationSnapMeshKey(lazyMesh);
        if (!state.snapLazyReadyMeshes.has(lazyKey)) {
            scheduleLazySimulationSnapBuild(lazyMesh);
            return null;
        }
    }
    if (!state.snapCandidates.length) return null;
    const placementPicking = state.placement.active;
    const measurementPicking = state.measurement.active && !placementPicking;
    const tcpPicking = state.tcpSnapMode;
    const zeroPointPicking = state.zeroPointEdit.active && state.zeroPointEdit.snapMode;
    const requestedType = zeroPointPicking
        ? state.zeroPointEdit.snapType
        : placementPicking ? state.placement.snapType
        : measurementPicking ? state.measurement.snapType : state.tcpSnapType;
    const requiredType = (placementPicking || measurementPicking || tcpPicking || zeroPointPicking)
        && requestedType !== 'auto' && requestedType !== 'multi-point-center'
        ? requestedType
        : null;
    const snapRadius = SNAP_RADIUS_PX;
    const nearby = [];
    const candidatesNearPointer = getSimulationSnapCandidatesNearPointer(
        meshes,
        bounds,
        pointerX,
        pointerY,
        snapRadius
    );
    candidatesNearPointer.forEach((candidate) => {
        if (!candidate.mesh.visible) return;
        if (requiredType && candidate.type !== requiredType) return;
        const worldPoint = candidate.snapWorldPoint
            ? candidate.snapWorldPoint.clone()
            : candidate.localPoint.clone().applyMatrix4(candidate.mesh.matrixWorld);
        const projected = worldPoint.clone().project(state.camera);
        if (projected.z < -1 || projected.z > 1) return;
        const screenX = (projected.x * 0.5 + 0.5) * bounds.width;
        const screenY = (-projected.y * 0.5 + 0.5) * bounds.height;
        const pixelDistance = Math.hypot(screenX - pointerX, screenY - pointerY);
        if (pixelDistance > snapRadius) return;
        nearby.push({
            ...candidate,
            sourceCandidate: candidate,
            worldPoint,
            projected,
            screenX,
            screenY,
            pixelDistance,
            cameraDistance: state.camera.position.distanceTo(worldPoint)
        });
    });
    nearby.sort(requiredType
        ? (left, right) => left.pixelDistance - right.pixelDistance || left.cameraDistance - right.cameraDistance
        : compareSimulationSnapCandidates);
    if (isSimulationSnapFaceSelectionActive(getSimulationSnapScope())) {
        const displayedCandidate = nearby.find((candidate) => (
            state.snapDisplayedCandidates.includes(candidate.sourceCandidate)
        ));
        if (displayedCandidate) return displayedCandidate;
        // A candidate that was not persistently visible can still become the
        // active snap when the pointer is directly over its projected point.
        // showSimulationSnapMarker() then makes the priority explicit before
        // the user clicks, even when another model is in front of it.
        return nearby[0] || null;
    }
    const visibleSnap = nearby.find((candidate) => isSimulationSnapCandidateVisible(
        candidate,
        candidate.projected,
        visibilityMeshes
    ));
    return visibleSnap || null;
}

function showSimulationSnapMarker(snap) {
    if (!snap || !el.snapMarker || !isSimulationSnapInteractionActive()) {
        hideSimulationSnapMarker();
        return;
    }
    state.snapHover = snap;
    if (state.placement.active) {
        state.placement.hover = snap;
        updateMeasurementUi();
    } else if (state.measurement.active) {
        state.measurement.hover = snap;
        updateMeasurementUi();
    }
    const info = snapTypeInfo(snap.type);
    el.snapMarker.style.left = `${snap.screenX}px`;
    el.snapMarker.style.top = `${snap.screenY}px`;
    el.snapMarker.classList.toggle('label-left', snap.screenX > el.canvasContainer.clientWidth - 190);
    el.snapMarker.dataset.snapType = snap.type;
    const symbol = el.snapMarker.querySelector('span');
    if (symbol) symbol.textContent = info.symbol;
    if (el.snapLabel) {
        el.snapLabel.textContent = `${uiText(info.label)} · X ${snap.worldPoint.x.toFixed(3)}, Y ${snap.worldPoint.y.toFixed(3)}, Z ${snap.worldPoint.z.toFixed(3)}`;
    }
    el.snapMarker.classList.remove('hidden');
}

function handleSimulationSnapPointerMove(event) {
    if (!isSimulationSnapInteractionActive()) return;
    state.snapLastPointerEvent = { clientX: event.clientX, clientY: event.clientY };
    scheduleSimulationSnapPreview();
}

function scheduleSimulationSnapPreview() {
    if (!isSimulationSnapInteractionActive()
        || !state.snapLastPointerEvent
        || state.snapPointerMoveFrame !== null) return;
    state.snapPointerMoveFrame = requestAnimationFrame(() => {
        state.snapPointerMoveFrame = null;
        const pointerEvent = state.snapLastPointerEvent;
        if (pointerEvent && isSimulationSnapInteractionActive()) {
            showSimulationSnapMarker(findSimulationSnapAtPointer(pointerEvent));
        }
    });
}

function applyTcpSnapPoint(worldPoint, selectedLabelKey = '스냅') {
    const robot = getJogTargetRobot();
    const flangeFrame = getRobotToolMountFrame(robot);
    if (!robot?.userData?.tcpFrame || !flangeFrame) return false;
    const localPoint = flangeFrame.worldToLocal(worldPoint.clone());
    ['x', 'y', 'z'].forEach((axis) => {
        const input = el.tcpOffsetInputs[axis];
        if (input) input.value = Number(localPoint[axis].toFixed(3));
    });
    updateTcpProfileLive();
    setTcpSnapMode(false);
    setTcpProfileStatus('TCP 위치를 스냅했습니다. 적용을 눌러 저장하세요.', 'success');
    setStatus('{label} TCP 위치 스냅', '#22c55e', {
        label: uiText(selectedLabelKey)
    });
    return true;
}

function handleTcpSnapSelection(snap) {
    if (!snap) return false;
    if (!isTcpMultiPointSnapMode()) {
        return applyTcpSnapPoint(snap.worldPoint, snapTypeInfo(snap.type).label);
    }
    if (state.tcpSnapPoints.length >= 4) {
        setStatus('최대 4개까지 선택할 수 있습니다.', '#f59e0b');
        return false;
    }
    const duplicateTolerance = 1e-4;
    if (state.tcpSnapPoints.some((point) => point.distanceTo(snap.worldPoint) <= duplicateTolerance)) {
        setStatus('중복된 스냅 점입니다.', '#f59e0b');
        return false;
    }
    state.tcpSnapPoints.push(snap.worldPoint.clone());
    updateTcpMultiCenterControls();
    const center = getTcpSnapCenter();
    setTcpSnapReadout(center && state.tcpSnapPoints.length >= 2
        ? `${uiText('다중 점 중심점')} · ${formatSimulationSnapPoint(center)}`
        : `${uiText('다중 점 선택')} ${state.tcpSnapPoints.length}/4 · ${uiText('스냅 점 2~4개를 선택하세요.')}`);
    setStatus('{count} 다중 점 선택', '#60a5fa', {
        count: `${state.tcpSnapPoints.length}/4`
    });
    return true;
}

function applyTcpMultiPointCenter() {
    if (!isTcpMultiPointSnapMode() || state.tcpSnapPoints.length < 2) return;
    const center = getTcpSnapCenter();
    if (center) applyTcpSnapPoint(center, '다중 점 중심점');
}

function isZeroPointMultiPointSnapMode() {
    return state.zeroPointEdit.active && state.zeroPointEdit.snapType === 'multi-point-center';
}

function readZeroPointSnapType() {
    return el.zeroPointSnapType?.selectedOptions?.[0]?.dataset.zeroSnapType
        || state.zeroPointEdit.snapType
        || 'auto';
}

function setZeroPointSnapReadout(message) {
    state.zeroPointEdit.snapReadoutMessage = message;
    if (!el.zeroPointSnapReadout) return;
    el.zeroPointSnapReadout.dataset.sourceMessage = message;
    el.zeroPointSnapReadout.textContent = uiText(message);
}

function resetZeroPointSnapPoints() {
    state.zeroPointEdit.snapPoints = [];
    updateZeroPointMultiCenterControls();
}

function updateZeroPointMultiCenterControls() {
    const multi = isZeroPointMultiPointSnapMode();
    const count = state.zeroPointEdit.snapPoints.length;
    el.zeroPointMultiCenterControls?.classList.toggle('hidden', !multi);
    if (el.zeroPointMultiCenterCount) {
        el.zeroPointMultiCenterCount.textContent = `${uiText('다중 점 선택')} ${count}/4`;
    }
    if (el.btnZeroPointMultiCenterApply) {
        el.btnZeroPointMultiCenterApply.disabled = !multi || count < 2 || count > 4;
    }
    if (el.btnZeroPointMultiCenterReset) {
        el.btnZeroPointMultiCenterReset.disabled = !multi || count === 0;
    }
}

function getZeroPointSnapCenter() {
    if (!state.zeroPointEdit.snapPoints.length) return null;
    const center = new THREE.Vector3();
    state.zeroPointEdit.snapPoints.forEach((point) => center.add(point));
    return center.multiplyScalar(1 / state.zeroPointEdit.snapPoints.length);
}

function getZeroPointRotationQuaternion() {
    return new THREE.Quaternion().setFromEuler(new THREE.Euler(
        THREE.MathUtils.degToRad(state.zeroPointEdit.rotationDegrees.x),
        THREE.MathUtils.degToRad(state.zeroPointEdit.rotationDegrees.y),
        THREE.MathUtils.degToRad(state.zeroPointEdit.rotationDegrees.z),
        'XYZ'
    )).normalize();
}

function updateZeroPointEditorInputs() {
    const { origin, rotationDegrees } = state.zeroPointEdit;
    ['x', 'y', 'z'].forEach((axis) => {
        const originInput = el.zeroPointOriginInputs[axis];
        const rotationInput = el.zeroPointRotationInputs[axis];
        if (originInput && originInput !== document.activeElement) {
            originInput.value = formatTransformNumber(origin[axis]);
        }
        if (rotationInput && rotationInput !== document.activeElement) {
            rotationInput.value = formatTransformNumber(normalizeDegrees(rotationDegrees[axis]));
        }
    });
}

function updateZeroPointAxisDirections() {
    const quaternion = state.zeroPointEdit.frame?.quaternion || new THREE.Quaternion();
    const directions = {
        x: new THREE.Vector3(1, 0, 0).applyQuaternion(quaternion),
        y: new THREE.Vector3(0, 1, 0).applyQuaternion(quaternion),
        z: new THREE.Vector3(0, 0, 1).applyQuaternion(quaternion)
    };
    Object.entries(directions).forEach(([axis, direction]) => {
        const output = el.zeroPointAxisDirections?.querySelector(`[data-zero-axis-direction="${axis}"]`);
        if (output) output.textContent = direction.toArray().map((value) => value.toFixed(3)).join(', ');
    });
}

function captureZeroPointModelState(model) {
    if (!model) return null;
    if (model.matrixAutoUpdate !== false) model.updateMatrix();
    return {
        position: model.position.clone(),
        quaternion: model.quaternion.clone(),
        scale: model.scale.clone(),
        matrix: model.matrix.toArray(),
        matrixAutoUpdate: model.matrixAutoUpdate !== false,
        childTransforms: [...model.children].map((child) => {
            if (child.matrixAutoUpdate !== false) child.updateMatrix();
            return {
                child,
                matrix: child.matrix.toArray(),
                matrixAutoUpdate: child.matrixAutoUpdate !== false
            };
        })
    };
}

function restoreZeroPointModelState(model, snapshot, invalidate = true) {
    if (!model || !snapshot) return;
    model.position.copy(snapshot.position);
    model.quaternion.copy(snapshot.quaternion);
    model.scale.copy(snapshot.scale);
    model.matrixAutoUpdate = snapshot.matrixAutoUpdate !== false;
    if (model.matrixAutoUpdate) model.updateMatrix();
    else model.matrix.fromArray(snapshot.matrix);
    snapshot.childTransforms.forEach(({ child, matrix, matrixAutoUpdate }) => {
        if (!child || !model.children.includes(child)) return;
        child.matrix.fromArray(matrix);
        if (matrixAutoUpdate === false) {
            child.matrixAutoUpdate = false;
            child.matrixWorldNeedsUpdate = true;
        } else {
            child.matrix.decompose(child.position, child.quaternion, child.scale);
            child.matrixAutoUpdate = true;
        }
    });
    model.updateMatrixWorld(true);
    if (invalidate) invalidateSimulationSnapCandidates();
}

function applyZeroPointModelPreview() {
    const edit = state.zeroPointEdit;
    if (!edit.active || !edit.model || !edit.baseModelState) return;
    restoreZeroPointModelState(edit.model, edit.baseModelState, false);
    applyModelZeroPointFrame(edit.model, edit.origin, edit.rotationDegrees);
}

function updateZeroPointCurrentReadout(worldPosition) {
    if (!el.zeroPointCurrentReadout || !worldPosition) return;
    el.zeroPointCurrentReadout.textContent = `${uiText('현재 영점')} · X ${worldPosition.x.toFixed(3)}, Y ${worldPosition.y.toFixed(3)}, Z ${worldPosition.z.toFixed(3)} mm`;
}

function updateZeroPointCurrentMarker() {
    const marker = state.zeroPointEdit.marker;
    const model = state.zeroPointEdit.active ? state.zeroPointEdit.model : null;
    if (!marker || !isSimulationSnapModel(model) || !isModelTreeVisible(model) || !state.models.includes(model)) {
        if (marker) marker.visible = false;
        return;
    }
    model.updateMatrixWorld(true);
    marker.position.copy(model.getWorldPosition(new THREE.Vector3()));
    marker.visible = true;
    if (state.zeroPointEdit.active) updateZeroPointCurrentReadout(marker.position);
}

function refreshZeroPointSnapCandidates() {
    const edit = state.zeroPointEdit;
    if (!edit.active || !edit.snapMode) return;
    void buildSimulationSnapCandidates('zero')
        .then(() => {
            if (!edit.active || !edit.snapMode || !state.snapLastPointerEvent) return;
            showSimulationSnapMarker(findSimulationSnapAtPointer(state.snapLastPointerEvent));
        })
        .catch((error) => console.warn('Zero point snap candidate refresh failed:', error));
}

function updateZeroPointFrameFromState() {
    const edit = state.zeroPointEdit;
    if (!edit.active || !edit.model || !edit.frame) return;
    applyZeroPointModelPreview();
    edit.model.updateMatrixWorld(true);
    const rootPosition = edit.model.getWorldPosition(new THREE.Vector3());
    const rootQuaternion = edit.model.getWorldQuaternion(new THREE.Quaternion());
    edit.frame.position.copy(rootPosition);
    edit.frame.quaternion.copy(rootQuaternion).multiply(getZeroPointRotationQuaternion()).normalize();
    edit.frame.updateMatrixWorld(true);
    edit.axes?.updateMatrixWorld(true);
    updateZeroPointAxisDirections();
    updateZeroPointCurrentReadout(rootPosition);
    updateZeroPointCurrentMarker();
    refreshZeroPointSnapCandidates();
}

function setZeroPointSnapMode(enabled) {
    const edit = state.zeroPointEdit;
    if (!edit.active || !edit.model) return;
    if (enabled && state.measurement.active) closeMeasurementPanel();
    if (enabled && state.placement.active) deactivateModelPlacement();
    edit.snapMode = Boolean(enabled);
    if (edit.snapMode) {
        state.snapMoveMode = false;
        clearSimulationSnapFaceSelection({ invalidate: false });
        invalidateSimulationSnapCandidates();
        if (state.tcpSnapMode) setTcpSnapMode(false);
        state.snapLastPointerEvent = null;
        resetZeroPointSnapPoints();
        captureSimulationSnapMarkerReferenceDistance();
        setZeroPointSnapReadout('스냅할 3D 모델의 면을 클릭하세요.');
        setStatus('스냅할 3D 모델의 면을 클릭하세요.', '#60a5fa');
        if (el.btnZeroPointSnap) {
            el.btnZeroPointSnap.classList.add('active');
            el.btnZeroPointSnap.setAttribute('aria-pressed', 'true');
        }
    } else {
        clearSimulationSnapFaceSelection({ invalidate: false });
        invalidateSimulationSnapCandidates();
        resetZeroPointSnapPoints();
        hideSimulationSnapMarker();
        resetSimulationSnapMarkerCameraScale();
        setZeroPointSnapReadout('스냅 위치 선택을 누른 뒤 모델 형상 위로 포인터를 이동하세요.');
        if (el.btnZeroPointSnap) {
            el.btnZeroPointSnap.classList.remove('active');
            el.btnZeroPointSnap.setAttribute('aria-pressed', 'false');
        }
    }
    el.canvasContainer?.classList.toggle(
        'simulation-snap-picking',
        state.snapMoveMode || state.zeroPointEdit.snapMode
    );
}

function getZeroPointBaselineLocalPoint(worldPoint) {
    const edit = state.zeroPointEdit;
    if (!edit.model) return null;
    const currentLocalPoint = edit.model.worldToLocal(worldPoint.clone());
    return currentLocalPoint.applyQuaternion(getZeroPointRotationQuaternion()).add(edit.origin);
}

function commitZeroPointSnapPoint(worldPoint, selectedLabelKey = '스냅') {
    const edit = state.zeroPointEdit;
    if (!edit.model) return false;
    const localPoint = getZeroPointBaselineLocalPoint(worldPoint);
    if (!localPoint) return false;
    edit.origin.copy(localPoint);
    updateZeroPointEditorInputs();
    updateZeroPointFrameFromState();
    setZeroPointSnapMode(false);
    setStatus('{label} 영점 위치에 적용되었습니다.', '#22c55e', {
        label: uiText(selectedLabelKey)
    });
    setZeroPointSnapReadout(`${uiText(selectedLabelKey)} · X ${localPoint.x.toFixed(3)}, Y ${localPoint.y.toFixed(3)}, Z ${localPoint.z.toFixed(3)} mm`);
    return true;
}

function handleZeroPointSnapSelection(snap) {
    if (!snap || !state.zeroPointEdit.active) return false;
    if (!isZeroPointMultiPointSnapMode()) {
        return commitZeroPointSnapPoint(snap.worldPoint, snapTypeInfo(snap.type).label);
    }
    const edit = state.zeroPointEdit;
    if (edit.snapPoints.length >= 4) {
        setStatus('최대 4개까지 선택할 수 있습니다.', '#f59e0b');
        return false;
    }
    if (edit.snapPoints.some((point) => point.distanceTo(snap.worldPoint) <= 1e-4)) {
        setStatus('중복된 스냅 점입니다.', '#f59e0b');
        return false;
    }
    edit.snapPoints.push(snap.worldPoint.clone());
    updateZeroPointMultiCenterControls();
    const center = getZeroPointSnapCenter();
    setZeroPointSnapReadout(center && edit.snapPoints.length >= 2
        ? `${uiText('다중 점 중심점')} · X ${center.x.toFixed(3)}, Y ${center.y.toFixed(3)}, Z ${center.z.toFixed(3)} mm`
        : `${uiText('다중 점 선택')} ${edit.snapPoints.length}/4 · ${uiText('스냅 점 2~4개를 선택하세요.')}`);
    setStatus('{count} 다중 점 선택', '#60a5fa', {
        count: `${edit.snapPoints.length}/4`
    });
    return true;
}

function applyZeroPointMultiCenter() {
    if (!isZeroPointMultiPointSnapMode() || state.zeroPointEdit.snapPoints.length < 2) return;
    const center = getZeroPointSnapCenter();
    if (center) commitZeroPointSnapPoint(center, '다중 점 중심점');
}

function moveRobotTcpToSimulationSnap(snap) {
    const robot = getJogTargetRobot();
    if (isMotionActive()) return false;
    if (!robot?.userData.tcpFrame) {
        setStatus('스냅 이동할 로봇을 먼저 선택하세요.', '#ef4444');
        return false;
    }
    const currentPose = getCurrentTcpPoseBase(robot);
    if (!currentPose) return false;
    robot.updateMatrixWorld(true);
    const target = {
        position: robot.worldToLocal(snap.worldPoint.clone()),
        quaternion: currentPose.quaternion.clone()
    };
    const previousAngles = robot.userData.joints.map((joint) => joint.angle);
    const previousTarget = robot.userData.baseJogTarget
        ? {
            position: robot.userData.baseJogTarget.position.clone(),
            quaternion: robot.userData.baseJogTarget.quaternion.clone()
        }
        : currentPose;
    const before = captureSceneSnapshot();
    const result = solveRobotIK(robot, target, {
        positionTolerance: 0.001,
        rotationTolerance: THREE.MathUtils.degToRad(0.001)
    });
    if (!result.success) {
        previousAngles.forEach((angle, index) => setJointAngle(robot.userData.joints[index], angle, false));
        robot.userData.baseJogTarget = previousTarget;
        robot.updateMatrixWorld(true);
        syncJointControls(robot);
        updateTcpPresentation(robot);
        setStatus('선택한 스냅 위치에 도달할 수 없습니다.', '#ef4444');
        return false;
    }
    robot.userData.baseJogTarget = target;
    syncJointControls(robot);
    updateTcpPresentation(robot, target);
    syncBaseJogGizmoFromRobot(robot, target);
    recordHistory('스냅 위치 이동', before, captureSceneSnapshot());
    setStatus('선택한 스냅 위치로 이동했습니다.', '#22c55e');
    return true;
}

function handleSimulationSnapClick(event) {
    if (!isSimulationSnapInteractionActive() || event.button !== 0) return;
    if (isCadOriginSnapPicking()) {
        const snap = findCadOriginSnapAtPointer(event);
        event.preventDefault();
        event.stopPropagation();
        if (snap) applyCadOriginSnap(snap);
        else setStatus('선택 가능한 CAD 스냅 지점을 가리켜 주세요.', '#f59e0b');
        return;
    }
    if (isSimulationSnapFaceSelectionActive()) {
        handleSimulationSnapFaceSelectionClick(event);
        return;
    }
    const snap = findSimulationSnapAtPointer(event);
    if (!snap) {
        if (state.measurement.active || state.placement.active || state.interferenceSnapMode
            || (state.sketch.active && state.sketch.snapMode)) {
            event.preventDefault();
            event.stopPropagation();
        }
        setStatus('선택 가능한 스냅 지점을 가리켜 주세요.', '#f59e0b');
        return;
    }
    event.preventDefault();
    event.stopPropagation();
    if (state.placement.active) {
        if (handleMeasurementSnapSelection(snap)) showSimulationSnapMarker(snap);
    } else if (state.measurement.active) {
        if (handleMeasurementSnapSelection(snap)) showSimulationSnapMarker(snap);
    } else if (state.sketch.active && state.sketch.snapMode) {
        if (handleSketchSnapSelection(snap)) showSimulationSnapMarker(snap);
    } else if (state.zeroPointEdit.active && state.zeroPointEdit.snapMode) {
        handleZeroPointSnapSelection(snap);
    } else if (state.tcpSnapMode) {
        handleTcpSnapSelection(snap);
    } else if (state.interferenceSnapMode) {
        handleInterferenceSnapSelection(snap);
    } else if (moveRobotTcpToSimulationSnap(snap)) {
        showSimulationSnapMarker(snap);
    }
}

function updateSimulationSnapButton() {
    if (!el.btnSnapMove) return;
    const available = Boolean(getJogTargetRobot()?.userData?.tcpFrame)
        && !isOlpRunning()
        && !state.olp.workOriginBusy
        && !state.olp.manualMoveBusy;
    if (!available && state.snapMoveMode) {
        state.snapMoveMode = false;
        clearSimulationSnapFaceSelection({ invalidate: false });
        invalidateSimulationSnapCandidates();
        hideSimulationSnapMarker();
        resetSimulationSnapMarkerCameraScale();
    }
    el.btnSnapMove.disabled = !available;
    el.btnSnapMove.classList.toggle('active', state.snapMoveMode);
    el.btnSnapMove.setAttribute('aria-pressed', String(state.snapMoveMode));
    el.btnSnapMove.title = uiText(state.snapMoveMode ? '스냅 이동 종료' : '스냅 이동');
    el.canvasContainer?.classList.toggle(
        'simulation-snap-picking',
        state.placement.active || state.measurement.active || state.snapMoveMode || state.zeroPointEdit.snapMode
            || state.interferenceSnapMode
            || (state.sketch.active && state.sketch.snapMode)
    );
    if (state.snapMoveMode) setBaseJogGizmoEnabled(false);
    updateSnapFaceOrientationUi();
}

async function toggleSimulationSnapMoveMode() {
    if (state.measurement.active) closeMeasurementPanel();
    if (state.placement.active) deactivateModelPlacement();
    state.snapMoveMode = !state.snapMoveMode;
    if (state.snapMoveMode) {
        if (state.tcpSnapMode) setTcpSnapMode(false);
        setJogMode('base', { preserveSnapMove: true });
        clearSimulationSnapFaceSelection({ invalidate: false });
        invalidateSimulationSnapCandidates();
        captureSimulationSnapMarkerReferenceDistance();
        setStatus('스냅할 3D 모델의 면을 클릭하세요.', '#60a5fa');
        updateSimulationSnapButton();
        void rebuildSimulationSnapCandidatesForCurrentInteraction('scene').catch((error) => {
            console.warn('Simulation snap candidate generation failed:', error);
        });
    } else {
        clearSimulationSnapFaceSelection();
        hideSimulationSnapMarker();
        resetSimulationSnapMarkerCameraScale();
        setBaseJogGizmoEnabled(true);
        setStatus('스냅 이동을 종료했습니다.', '#22c55e');
    }
    updateSimulationSnapButton();
    updateTcpSnapUi();
}

function addGridLabels() {
    const intervals = [500, 1000, 1500, 2000, 3000, 4000, 5000];
    const labelColor = '#94a3b8';
    // Keep floor dimensions behind model meshes while leaving the axis labels
    // as front-facing orientation cues.
    // The reference grid is at z=0. These are camera-facing sprites, so placing
    // their centers only 1 mm below the floor can still leave the upper edge of
    // the sprite above z=0 at an oblique camera angle. Keep the whole label
    // quad below the floor so model surfaces can occlude it reliably.
    const floorLabelZ = -60;
    const floorLabelOptions = { depthTest: true, renderOrder: -90 };
    intervals.forEach(val => {
        state.labels.push(createLabel(`${val}mm`, val, 0, floorLabelZ, labelColor, 160, 80, floorLabelOptions));
        state.labels.push(createLabel(`-${val}mm`, -val, 0, floorLabelZ, labelColor, 160, 80, floorLabelOptions));
        state.labels.push(createLabel(`${val}mm`, 0, val, floorLabelZ, labelColor, 160, 80, floorLabelOptions));
        state.labels.push(createLabel(`-${val}mm`, 0, -val, floorLabelZ, labelColor, 160, 80, floorLabelOptions));
    });
    state.labels.push(createLabel('X+', 335, 0, 28, AXIS_COLORS.x, 82, 41));
    state.labels.push(createLabel('Y+', 0, 335, 28, AXIS_COLORS.y, 82, 41));
    state.labels.push(createLabel('Z+', 0, 0, 335, AXIS_COLORS.z, 82, 41));
    state.labels.forEach(l => state.scene.add(l));
}

function createLabel(text, x, y, z, color, width = 160, height = 80, options = {}) {
    const { depthTest = false, renderOrder = 22 } = options;
    const canvas = document.createElement('canvas');
    canvas.width = 256; canvas.height = 128;
    const ctx = canvas.getContext('2d');
    ctx.font = 'bold 32px Outfit, Inter, Arial';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillStyle = color; ctx.fillText(text, 128, 64);
    const texture = new THREE.CanvasTexture(canvas);
    // The transparent part of a sprite must not write to the depth buffer.
    // Otherwise the whole label quad occludes the floor behind it and appears
    // as a bright rectangle when the floor/model is transparent.
    const material = new THREE.SpriteMaterial({
        map: texture,
        transparent: true,
        depthTest,
        depthWrite: false,
        toneMapped: false
    });
    const sprite = new THREE.Sprite(material);
    sprite.position.set(x, y, z);
    sprite.scale.set(width, height, 1);
    sprite.renderOrder = renderOrder;
    return sprite;
}

function setupLights() {
    state.scene.add(new THREE.AmbientLight(0xffffff, 0.6));
    const dir = new THREE.DirectionalLight(0xffffff, 1.25);
    dir.position.set(1500, -1000, 2500);
    dir.castShadow = true;
    state.scene.add(dir);
    const dir2 = new THREE.DirectionalLight(0xffffff, 0.5);
    dir2.position.set(-1500, 1200, 1000);
    state.scene.add(dir2);
}

function syncModelTransformRotationSnap(event) {
    const controls = state.transformControls;
    if (!controls) return;
    const modifierHeld = Boolean(event?.ctrlKey || event?.shiftKey || event?.altKey);
    controls.translationSnap = modifierHeld ? TRANSFORM_TRANSLATION_SNAP : null;
    controls.rotationSnap = modifierHeld ? MODEL_TRANSFORM_ROTATION_SNAP : null;

    [state.baseJogTransformControls, state.zeroPointEdit?.transformControls].forEach((handler) => {
        if (!handler) return;
        handler.translationSnap = modifierHeld ? TRANSFORM_TRANSLATION_SNAP : null;
        handler.rotationSnap = modifierHeld ? MODEL_TRANSFORM_ROTATION_SNAP : null;
    });
}

function clearModelTransformRotationSnap() {
    [
        state.transformControls,
        state.baseJogTransformControls,
        state.zeroPointEdit?.transformControls
    ].forEach((handler) => {
        if (!handler) return;
        handler.translationSnap = null;
        handler.rotationSnap = null;
    });
}

function captureMainOrbitControlState(controls) {
    if (!controls) return null;
    return {
        enabled: controls.enabled,
        enableRotate: controls.enableRotate,
        enablePan: controls.enablePan,
        enableZoom: controls.enableZoom,
        enableDamping: controls.enableDamping,
        dampingFactor: controls.dampingFactor,
        screenSpacePanning: controls.screenSpacePanning,
        rotateSpeed: controls.rotateSpeed,
        panSpeed: controls.panSpeed,
        zoomSpeed: controls.zoomSpeed,
        keyPanSpeed: controls.keyPanSpeed,
        minDistance: controls.minDistance,
        maxDistance: controls.maxDistance,
        minZoom: controls.minZoom,
        maxZoom: controls.maxZoom,
        minPolarAngle: controls.minPolarAngle,
        maxPolarAngle: controls.maxPolarAngle,
        minAzimuthAngle: controls.minAzimuthAngle,
        maxAzimuthAngle: controls.maxAzimuthAngle,
        autoRotate: controls.autoRotate,
        autoRotateSpeed: controls.autoRotateSpeed,
        mouseButtons: { ...controls.mouseButtons },
        touches: { ...controls.touches },
        keys: { ...controls.keys },
        zoomToCursor: 'zoomToCursor' in controls ? controls.zoomToCursor : undefined,
        target: controls.target.clone()
    };
}

function applyMainOrbitControlState(controls, previousState) {
    if (!controls || !previousState) return;
    controls.enabled = previousState.enabled;
    controls.enableRotate = previousState.enableRotate;
    controls.enablePan = previousState.enablePan;
    controls.enableZoom = previousState.enableZoom;
    controls.enableDamping = previousState.enableDamping;
    controls.dampingFactor = previousState.dampingFactor;
    controls.screenSpacePanning = previousState.screenSpacePanning;
    controls.rotateSpeed = previousState.rotateSpeed;
    controls.panSpeed = previousState.panSpeed;
    controls.zoomSpeed = previousState.zoomSpeed;
    controls.keyPanSpeed = previousState.keyPanSpeed;
    controls.minDistance = previousState.minDistance;
    controls.maxDistance = previousState.maxDistance;
    controls.minZoom = previousState.minZoom;
    controls.maxZoom = previousState.maxZoom;
    controls.minPolarAngle = previousState.minPolarAngle;
    controls.maxPolarAngle = previousState.maxPolarAngle;
    controls.minAzimuthAngle = previousState.minAzimuthAngle;
    controls.maxAzimuthAngle = previousState.maxAzimuthAngle;
    controls.autoRotate = previousState.autoRotate;
    controls.autoRotateSpeed = previousState.autoRotateSpeed;
    if (previousState.mouseButtons) Object.assign(controls.mouseButtons, previousState.mouseButtons);
    if (previousState.touches) Object.assign(controls.touches, previousState.touches);
    if (previousState.keys) Object.assign(controls.keys, previousState.keys);
    if ('zoomToCursor' in controls && previousState.zoomToCursor !== undefined) {
        controls.zoomToCursor = previousState.zoomToCursor;
    }
    if (previousState.target) controls.target.copy(previousState.target);
}

function configureMainOrbitControlDefaults(controls) {
    if (!controls) return;
    controls.enableDamping = false;
    // Keep the main 3D viewer aligned with the deployed OrbitControls defaults.
    // This is important for the feel of right-drag vertical movement with a
    // Z-up scene; the sketch camera applies its own independent settings.
    controls.screenSpacePanning = true;
    controls.rotateSpeed = 1;
    controls.panSpeed = 1;
    controls.zoomSpeed = 1;
    controls.mouseButtons.LEFT = THREE.MOUSE.ROTATE;
    controls.mouseButtons.MIDDLE = THREE.MOUSE.DOLLY;
    controls.mouseButtons.RIGHT = THREE.MOUSE.PAN;
    controls.touches.ONE = THREE.TOUCH.ROTATE;
    controls.touches.TWO = THREE.TOUCH.DOLLY_PAN;
    if ('zoomToCursor' in controls) controls.zoomToCursor = false;
}

function recreateMainOrbitControls(previousState = undefined) {
    const previous = state.controls;
    const restoredState = previousState === undefined
        ? captureMainOrbitControlState(previous)
        : previousState;
    previous?.dispose?.();
    const controls = new OrbitControls(state.camera, state.renderer.domElement);
    configureMainOrbitControlDefaults(controls);
    state.controls = controls;
    state.controls.addEventListener('change', requestRender);
    state.controls.addEventListener('start', beginSimulationViewNavigation);
    state.controls.addEventListener('end', endSimulationViewNavigation);
    state.controls.addEventListener('end', scheduleMotionProjectSave);
    if (restoredState) {
        applyMainOrbitControlState(controls, restoredState);
    }
    return controls;
}

function setupControls() {
    recreateMainOrbitControls();
    state.renderer.domElement.addEventListener('pointerdown', trackMainOrbitControlPointer, { capture: true });
    state.renderer.domElement.addEventListener('pointerup', clearMainOrbitControlPointer, { capture: true });
    state.renderer.domElement.addEventListener('pointercancel', clearMainOrbitControlPointer, { capture: true });

    state.transformControls = new TransformControls(state.camera, state.renderer.domElement);
    enableContinuousTransformRotation(state.transformControls, THREE);
    state.renderer.domElement.addEventListener('pointerdown', syncModelTransformRotationSnap, true);
    state.renderer.domElement.addEventListener('pointermove', syncModelTransformRotationSnap, true);
    state.renderer.domElement.addEventListener('pointerup', clearModelTransformRotationSnap, true);
    state.renderer.domElement.addEventListener('pointercancel', clearModelTransformRotationSnap, true);
    state.transformControls.addEventListener('dragging-changed', (event) => {
        state.controls.enabled = !event.value;
        if (!event.value) clearModelTransformRotationSnap();
    });
    state.transformControls.addEventListener('mouseDown', () => {
        if (!state.historySuspended && state.selectedModel) {
            state.pendingTransformHistory = captureSceneSnapshot();
        }
    });
    state.transformControls.addEventListener('mouseUp', () => {
        clearModelTransformRotationSnap();
        commitPendingHistory('모델 변환', 'pendingTransformHistory');
        const target = state.transformControls.object;
        const model = findSceneModelAncestor(target);
        if (target && model) {
            const partIndex = getImportedModelParts(model).indexOf(target);
            sendCollaborationSceneCommand({
                kind: 'transform',
                workspaceModelId: ensureWorkspaceModelId(model),
                ...(partIndex >= 0 ? { modelPartIndex: partIndex } : {}),
                transform: captureClipboardTransform(target)
            });
        }
    });
    state.transformControls.addEventListener('objectChange', () => {
        handlePlacementTransformObjectChange(state.transformControls.object);
        markSceneCollisionDirty(state.selectedModel || state.transformControls.object);
        updateSelectedModelTransformInputs();
        updatePrimitiveDimensionOverlay();
        if (state.toolLoadInfo.selectedModel === state.selectedModel) calculateToolLoadInfo();
        if (state.selectedModel?.userData?.placement === 'arm-load') renderArmLoadPanel();
        scheduleMotionProjectSave();
    });
    state.transformControls.addEventListener('objectChange', requestRender);
    removeRotationScreenHandle(state.transformControls);
    applyTransformControlColors(state.transformControls);
    state.transformControls.visible = false;
    state.transformControls.enabled = false;
    state.scene.add(state.transformControls);

    const zeroPointEdit = state.zeroPointEdit;
    zeroPointEdit.frame = new THREE.Object3D();
    zeroPointEdit.frame.name = 'Model zero point frame';
    zeroPointEdit.axes = new THREE.AxesHelper(1);
    applyAxesHelperColors(zeroPointEdit.axes);
    zeroPointEdit.axes.renderOrder = 25;
    zeroPointEdit.frame.add(zeroPointEdit.axes);
    zeroPointEdit.frame.visible = false;
    state.scene.add(zeroPointEdit.frame);

    zeroPointEdit.marker = new THREE.Mesh(
        new THREE.SphereGeometry(1, 16, 10),
        new THREE.MeshBasicMaterial({
            color: SIMULATION_SNAP_COLOR,
            depthTest: false,
            depthWrite: false,
            transparent: true,
            opacity: 0.96
        })
    );
    zeroPointEdit.marker.name = 'Current model zero point';
    zeroPointEdit.marker.renderOrder = 26;
    zeroPointEdit.marker.scale.setScalar(5);
    zeroPointEdit.marker.visible = false;
    state.scene.add(zeroPointEdit.marker);

    zeroPointEdit.transformControls = new TransformControls(state.camera, state.renderer.domElement);
    zeroPointEdit.transformControls.setMode('rotate');
    zeroPointEdit.transformControls.setSpace('local');
    zeroPointEdit.transformControls.setSize(0.82);
    enableContinuousTransformRotation(zeroPointEdit.transformControls, THREE);
    removeRotationScreenHandle(zeroPointEdit.transformControls);
    applyTransformControlColors(zeroPointEdit.transformControls);
    zeroPointEdit.transformControls.visible = false;
    zeroPointEdit.transformControls.enabled = false;
    zeroPointEdit.transformControls.addEventListener('dragging-changed', (event) => {
        state.controls.enabled = !event.value;
    });
    zeroPointEdit.transformControls.addEventListener('objectChange', () => {
        if (!zeroPointEdit.active || !zeroPointEdit.frame) return;
        const deltaQuaternion = zeroPointEdit.baseWorldQuaternion.clone().invert()
            .multiply(zeroPointEdit.frame.getWorldQuaternion(new THREE.Quaternion()))
            .normalize();
        const euler = new THREE.Euler().setFromQuaternion(deltaQuaternion, 'XYZ');
        zeroPointEdit.rotationDegrees.set(
            THREE.MathUtils.radToDeg(euler.x),
            THREE.MathUtils.radToDeg(euler.y),
            THREE.MathUtils.radToDeg(euler.z)
        );
        updateZeroPointEditorInputs();
        updateZeroPointFrameFromState();
    });
    zeroPointEdit.transformControls.addEventListener('objectChange', requestRender);
    state.scene.add(zeroPointEdit.transformControls);

    setupBaseJogTransformControls();
}

function setupBaseJogTransformControls() {
    const target = new THREE.Object3D();
    target.name = 'Base JOG TCP Target';
    state.baseJogGizmoTarget = target;

    const controls = new TransformControls(state.camera, state.renderer.domElement);
    enableContinuousTransformRotation(controls, THREE);
    controls.setMode(state.baseJogGizmoMode);
    controls.setSpace('local');
    controls.visible = false;
    controls.enabled = false;
    controls.userData.baseJogActiveAxis = null;
    controls.addEventListener('dragging-changed', (event) => {
        state.controls.enabled = !event.value;
        if (!event.value) controls.userData.baseJogActiveAxis = null;
    });
    controls.addEventListener('mouseDown', () => {
        controls.userData.baseJogActiveAxis = controls.axis;
    });
    controls.addEventListener('mouseDown', beginBaseJogGizmoDrag);
    controls.addEventListener('objectChange', applyBaseJogGizmoTarget);
    controls.addEventListener('objectChange', requestRender);
    controls.addEventListener('mouseUp', endBaseJogGizmoDrag);
    controls.addEventListener('mouseUp', () => {
        controls.userData.baseJogActiveAxis = null;
    });
    removeRotationScreenHandle(controls);
    emphasizeBaseJogTransformControls(controls);
    applyTransformControlColors(controls);
    state.baseJogTransformControls = controls;
    state.scene.add(controls);
}

const wheelStepTimers = new WeakMap();

function enableHalfStepWheel(input, onStart = null, onEnd = null, onInput = null) {
    if (!input) return;
    input.step = '0.5';
    input.addEventListener('wheel', (event) => {
        event.preventDefault();
        input.focus({ preventScroll: true });
        onStart?.();
        const parsedCurrent = Number(input.value);
        const current = Number.isFinite(parsedCurrent) ? parsedCurrent : 0;
        const minimum = input.min === '' ? -Infinity : Number(input.min);
        const maximum = input.max === '' ? Infinity : Number(input.max);
        const next = THREE.MathUtils.clamp(current + (event.deltaY < 0 ? 0.5 : -0.5), minimum, maximum);
        input.value = String(Number(next.toFixed(6)));
        input.dispatchEvent(new Event('input', { bubbles: true }));
        onInput?.();
        window.clearTimeout(wheelStepTimers.get(input));
        wheelStepTimers.set(input, window.setTimeout(() => {
            wheelStepTimers.delete(input);
            onEnd?.();
        }, 180));
    }, { passive: false });
}

function setupOlpConsoleScroll() {
    const consoleElement = el.olpConsole;
    if (!consoleElement) return;
    consoleElement.addEventListener('wheel', (event) => {
        if (event.ctrlKey || consoleElement.scrollHeight <= consoleElement.clientHeight || !event.deltaY) return;
        const lineHeight = Number.parseFloat(getComputedStyle(consoleElement).lineHeight) || 13;
        // Mouse wheels usually report pixels (around 100px per notch). Scale
        // that to roughly one or two log lines; line-mode devices use their
        // own line unit and need a smaller correction.
        const scale = event.deltaMode === WheelEvent.DOM_DELTA_LINE ? lineHeight * 0.5 : 0.18;
        event.preventDefault();
        consoleElement.scrollTop += event.deltaY * scale;
    }, { passive: false });
}

function setupOlpEditorScroll() {
    const editor = el.olpFileEditor;
    if (!editor) return;
    editor.addEventListener('wheel', (event) => {
        if (event.ctrlKey || editor.scrollHeight <= editor.clientHeight || !event.deltaY) return;
        const lineHeight = Number.parseFloat(getComputedStyle(editor).lineHeight) || 18;
        // Keep code browsing to roughly one or two source lines per wheel step.
        const scale = event.deltaMode === WheelEvent.DOM_DELTA_LINE ? lineHeight * 0.5 : 0.18;
        event.preventDefault();
        editor.scrollTop += event.deltaY * scale;
    }, { passive: false });
}

