function getOlpVirtualBusEndpoint() {
    // The local launcher (tools/serve-local.cjs) owns the broker endpoint.
    // The tester connects to the same endpoint as a WebSocket master.
    return 'ws://127.0.0.1:8765/virtualbus/';
}

async function getOlpVirtualBusToken({ force = false } = {}) {
    if (!force && state.olp.busToken) return state.olp.busToken;
    try {
        const response = await fetch('/api/virtualbus-token', { cache: 'no-store' });
        const data = await response.json().catch(() => ({}));
        if (!response.ok || typeof data.token !== 'string' || data.token.length < 32) return null;
        state.olp.busToken = data.token;
        return data.token;
    } catch {
        return null;
    }
}

async function sendOlpVirtualBusHello(socket = state.olp.socket) {
    if (!socket || socket.readyState !== WebSocket.OPEN) return false;
    // Fetch on every hello so a server restart cannot leave the browser
    // handshaking with a token from an earlier launcher session.
    const token = await getOlpVirtualBusToken({ force: true });
    if (!token || socket.readyState !== WebSocket.OPEN) {
        updateOlpBusStatus('Virtual Bus unavailable · OLP local execution remains active', 'Local Virtual Bus pairing token is not configured.');
        return false;
    }
    socket.send(JSON.stringify({
        type: 'hello',
        token,
        role: 'slave',
        protocol: 'inorobot-virtual-bus',
        version: 1,
        sessionId: String(state.olp.busSocketGeneration || 0),
        robotName: state.activeProgramRobot?.userData?.robotName || '',
        modelName: state.activeProgramRobot?.userData?.modelName || '',
        labels: getOlpProject()?.labels || {},
        remoteIoMapping: getOlpProject()?.remoteIoMapping || []
    }));
    return true;
}

function connectOlpVirtualBus({ refreshMetadata = false } = {}) {
    const controllerActive = typeof isVirtualControllerActive === 'function'
        ? isVirtualControllerActive()
        : Boolean(state.virtualController?.wanted);
    if (controllerActive || !state.olp.virtualBusWanted) return;
    startOlpBusMonitor();
    if (state.olp.reconnectTimer) {
        clearTimeout(state.olp.reconnectTimer);
        state.olp.reconnectTimer = null;
    }
    const oldSocket = state.olp.socket;
    if (oldSocket && oldSocket.readyState === WebSocket.OPEN) {
        // A project can be loaded after OLP was enabled. Refresh the broker's
        // project metadata without opening a second browser connection.
        if (refreshMetadata) void sendOlpVirtualBusHello(oldSocket).catch(() => { });
        return;
    }
    if (oldSocket && oldSocket.readyState === WebSocket.CONNECTING) return;

    let socket;
    try { socket = new WebSocket(getOlpVirtualBusEndpoint()); }
    catch (error) {
        state.olp.busConnected = false;
        state.olp.busPhase = 'unavailable';
        state.olp.busLastPacketAt = 0;
        updateOlpBusStatus('Virtual Bus unavailable · OLP local execution remains active', error?.message || 'connection skipped');
        scheduleOlpVirtualBusReconnect();
        return;
    }
    const socketGeneration = (state.olp.busSocketGeneration || 0) + 1;
    state.olp.busSocketGeneration = socketGeneration;
    const isCurrentSocket = () => state.olp.socket === socket
        && state.olp.busSocketGeneration === socketGeneration;
    state.olp.socket = socket;
    state.olp.busConnected = false;
    state.olp.busPhase = 'connecting';
    state.olp.busLastPacketAt = 0;
    updateOlpBusStatus('Virtual Bus connecting');
    socket.addEventListener('open', () => {
        if (!isCurrentSocket()) return;
        if (state.olp.reconnectTimer) {
            clearTimeout(state.olp.reconnectTimer);
            state.olp.reconnectTimer = null;
        }
        state.olp.busConnected = false;
        state.olp.busPhase = 'handshaking';
        state.olp.busLastPacketAt = Date.now();
        clearOlpBusHandshakeTimer();
        state.olp.busHandshakeTimer = window.setTimeout(() => {
            if (!isCurrentSocket() || state.olp.busConnected) return;
            invalidateOlpBusSocket(
                socket,
                'Virtual Bus waiting for tester',
                'Virtual Bus handshake timeout; waiting for tester reconnect.'
            );
        }, 3000);
        updateOlpBusStatus('Virtual Bus waiting for tester', 'OLP local broker endpoint is open; waiting for tester Connect.');
        try {
            sendOlpVirtualBusHello(socket);
        } catch (error) {
            updateOlpBusStatus('Virtual Bus unavailable · OLP local execution remains active', error?.message || 'hello failed');
        }
    });
    socket.addEventListener('message', (event) => {
        try {
            const message = JSON.parse(event.data);
            if (!isCurrentSocket()) return;
            if (message.type === 'busStatus' && message.connected === false) {
                // Invalidate this socket before closing it.  A delayed
                // `ready` event from the old master is then ignored by the
                // generation guard above and cannot restore a green icon.
                invalidateOlpBusSocket(socket, 'Virtual Bus disconnected', 'Tester master disconnected.');
                setOlpStatus(isOlpRunning() ? 'running' : 'connected');
                return;
            }
            if (message.type === 'ready' && String(message.role || '').toLowerCase() === 'master') {
                if (String(message.protocol || '') !== 'inorobot-virtual-bus' || Number(message.version) !== 1) {
                    invalidateOlpBusSocket(socket, 'Virtual Bus unavailable · OLP local execution remains active', 'Virtual Bus protocol mismatch.');
                    return;
                }
                setOlpBusPhase('connected', 'Virtual Bus connected · tester master', 'Tester master handshake completed.');
                setOlpStatus(isOlpRunning() ? 'running' : 'connected');
                sendOlpOutputSnapshot({ force: true });
                return;
            }
            if (message.type !== 'inputSnapshot' || !Array.isArray(message.words) || !state.olp.busConnected) return;
            const previousPositionValues = new Map(state.olp.positionCommandValues);
            const nextWords = Uint16Array.from(message.words.slice(0, OLP_WORD_COUNT).map(clampWord));
            const nextExtended = new Map();
            if (message.mappedValues && typeof message.mappedValues === 'object') {
                Object.entries(message.mappedValues).forEach(([address, value]) => {
                    const parsed = normalizeOlpAddress(address, getOlpProject()?.labels || {});
                    if (parsed?.prefix === 'IN' || parsed?.prefix === 'INW') {
                        nextExtended.set(canonicalOlpAddress(parsed), parsed.prefix === 'INW' ? clampWord(value) : (Number(value) ? 1 : 0));
                    }
                });
            }
            const nextSignature = `${[...nextWords].join(',')}|${[...nextExtended.entries()].sort().map(([key, value]) => `${key}:${value}`).join(',')}`;
            const changed = nextSignature !== state.olp.lastInputSignature;
            const previousRemoteValues = new Map(state.olp.remoteCommandValues);
            state.olp.inputWords = nextWords;
            state.olp.inputExtended = nextExtended;
            if (changed) markIoSimulatorDirty(IO_SIMULATOR_DIRECTIONS.INPUT);
            state.olp.lastInputAt = Date.now();
            state.olp.busLastPacketAt = state.olp.lastInputAt;
            state.olp.lastInputSignature = nextSignature;
            if (changed) processIoFunctionMappings({ direction: IO_SIMULATOR_DIRECTIONS.INPUT });
            const rawPositionValues = new Map(getOlpPositionCommandEntries()
                .map((entry) => [entry.address, readOlpRawInputAddress(entry.address) ? 1 : 0]));
            monitorOlpPositionInputs(previousPositionValues, rawPositionValues);
            const monitorInputBit = getOlpMonitorAddress('IN', state.olp.lastRawInputBitAddress);
            const monitorInputWord = getOlpMonitorAddress('INW', state.olp.lastRawInputWordAddress);
            const inputEvents = [
                monitorInputBit ? `${monitorInputBit.address}=${readOlpAddress(monitorInputBit.address) ? 1 : 0}` : null,
                monitorInputWord ? `${monitorInputWord.address}=${readOlpAddress(monitorInputWord.address)}` : null
            ].filter(Boolean);
            setOlpLastIoEvent(inputEvents.length
                ? 'Tester → OLP: {events}'
                : 'Tester → OLP: no mapped project input labels',
                inputEvents.length ? { events: inputEvents.join(', ') } : {});
            state.olp.remoteCommandValues = new Map(['start', 'stop', 'reset', 'clearAlarm']
                .map((command) => {
                    const entry = getOlpRemoteCommand(command);
                    return [command, entry ? readOlpAddress(entry.address) : 0];
                }));
            if (changed) appendOlpConsole(state.olp.lastIoSource, state.olp.lastIoReplacements);
            renderOlpIoMonitor();
            void handleOlpRemoteIoCommands(previousRemoteValues);
        } catch (error) { console.warn('OLP Virtual Bus message ignored:', error); }
    });
    socket.addEventListener('close', () => {
        if (!isCurrentSocket()) return;
        clearOlpBusHandshakeTimer();
        state.olp.busToken = null;
        state.olp.socket = null;
        state.olp.busConnected = false;
        state.olp.busPhase = state.olp.virtualBusWanted ? 'waiting' : 'off';
        if (state.olp.virtualBusWanted && !isVirtualControllerActive()) {
            updateOlpBusStatus('Virtual Bus waiting for tester');
            setOlpStatus(isOlpRunning() ? 'running' : 'connected');
            if (!state.olp.reconnectTimer) state.olp.reconnectTimer = window.setTimeout(() => {
                state.olp.reconnectTimer = null;
                connectOlpVirtualBus();
            }, 1000);
        } else {
            updateOlpBusStatus('Virtual Bus disconnected');
        }
    });
    socket.addEventListener('error', () => {
        if (!isCurrentSocket()) return;
        state.olp.busToken = null;
        state.olp.busConnected = false;
        state.olp.busPhase = 'unavailable';
        updateOlpBusStatus('Virtual Bus unavailable · OLP local execution remains active');
        scheduleOlpVirtualBusReconnect();
    });
}

async function startOlpSession({ step = false, robot = null } = {}) {
    const runtimeMap = state.olp.runtimes instanceof Map ? state.olp.runtimes : null;
    const resolveRobot = (candidate = null) => typeof getOlpRobot === 'function'
        ? getOlpRobot(candidate)
        : candidate || state.activeProgramRobot || state.activeArticulatedModel || null;
    const resolveRuntime = (candidate = null) => typeof getOlpRuntimeForRobot === 'function'
        ? getOlpRuntimeForRobot(candidate)
        : runtimeMap?.get(candidate?.userData?.motionInstanceId)
            || (candidate === state.activeProgramRobot ? state.olp.runtime : null);
    const runtimeIsRunning = (candidate) => typeof isOlpRuntimeRunning === 'function'
        ? isOlpRuntimeRunning(candidate)
        : Boolean(candidate?.running)
            || ['starting', 'running', 'waiting', 'paused', 'stopping'].includes(String(candidate?.phase || '').toLowerCase());
    const setExecution = (candidate, snapshot) => {
        if (typeof setOlpExecutionForRobot === 'function') setOlpExecutionForRobot(candidate, snapshot);
        else state.olp.execution = { ...state.olp.execution, ...snapshot };
    };
    const syncRuntime = () => {
        if (typeof syncActiveOlpRuntime === 'function') syncActiveOlpRuntime();
    };
    const controllerIsActive = () => typeof isVirtualControllerActive === 'function'
        ? isVirtualControllerActive()
        : Boolean(state.virtualController?.wanted);
    const targetRobot = resolveRobot(robot);
    const targetProject = getOlpProjectForRobot(targetRobot);
    const existingRuntime = resolveRuntime(targetRobot);
    if (step && existingRuntime?.running && existingRuntime.paused) {
        existingRuntime.stepOnce();
        return;
    }
    if (!step && existingRuntime?.running && existingRuntime.paused) {
        existingRuntime.togglePause();
        setOlpStatus('running', 'OLP resumed.');
        return;
    }
    if (runtimeIsRunning(existingRuntime)) return;
    if (!targetProject) { setOlpStatus('error', 'Load a robot project folder for the selected robot first.'); return; }
    if (!targetRobot) { setOlpStatus('error', 'Select one robot before running OLP.'); return; }
    if (state.olp.workOriginBusy) { setOlpStatus('error', 'Wait until Work Origin movement is complete.'); return; }
    if (state.olp.manualMoveBusy) { setOlpStatus('error', 'Wait until the manual point movement is complete.'); return; }
    if (controllerIsActive()) { setOlpStatus('error', 'OLP is unavailable while a controller is connected.'); return; }
    if (state.motionSessions.size) { setOlpStatus('error', 'Stop the normal motion program before running OLP.'); return; }
    flushOlpPendingEdit();
    const wasAnyRuntimeRunning = isOlpRunning();
    const robotInstanceId = targetRobot.userData?.motionInstanceId || 'active-robot';
    if (state.tcpPath?.enabled) {
        resetTcpPath(targetRobot);
        appendTcpPathPoint(targetRobot);
    }
    let runtime;
    const sharedIoAdapter = getOlpSharedIoAdapter();
    runtime = new OlpRuntime(targetProject, {
        ...sharedIoAdapter,
        move: runOlpMove,
        jump: runOlpJump,
        home: runOlpHome,
        getCurrentPosition: (kind, currentRuntime) => getOlpCurrentPosition(kind, currentRuntime),
        alarm: (code, easyGo, currentRuntime) => handleOlpAlarm(code, easyGo, currentRuntime),
        delay: (milliseconds) => new Promise((resolve) => window.setTimeout(resolve, Math.max(0, milliseconds))),
        log: appendOlpConsole,
        status: appendOlpConsole,
        cursor: (snapshot) => queueOlpRuntimeView(runtime, snapshot),
        onStopped: (snapshot) => {
            setExecution(targetRobot, snapshot);
            const shouldResetCursor = state.olp.resetCursorOnStop
                || state.olp.resetCursorRobotIds?.has(robotInstanceId);
            if (shouldResetCursor) {
                resetOlpProgramCursor(targetRobot);
                state.olp.resetCursorRobotIds?.delete(robotInstanceId);
                if (targetRobot === resolveRobot()) state.olp.resetCursorOnStop = false;
            }
            if (resolveRuntime(resolveRobot()) === runtime) {
                flushOlpRuntimeView(runtime, snapshot);
            }
            if (runtimeMap?.get(robotInstanceId) === runtime) runtimeMap.delete(robotInstanceId);
            syncRuntime();
            if (!isOlpRunning()) {
                setOlpStatus('connected', snapshot?.phase === 'completed' ? 'OLP cycle completed.' : 'OLP stopped.');
                updateMotionUiLock();
                requestRender();
            } else {
                state.olp.status = 'running';
                updateOlpProgramPanelUi();
                updateMotionUiLock();
                requestRender();
            }
        }
    });
    runtime.robot = targetRobot;
    runtime.robotInstanceId = robotInstanceId;
    runtimeMap?.set(robotInstanceId, runtime);
    state.olp.runtime = runtime;
    state.olp.resetCursorOnStop = false;
    state.olp.virtualBusWanted = true;
    setExecution(targetRobot, {
        phase: 'starting', running: true, paused: false,
        filePath: targetProject.programPath, lineNumber: 0, lineText: '',
        command: '', waitCondition: '', callStack: [], alarm: null
    });
    syncRuntime();
    if (!wasAnyRuntimeRunning) {
        writeOlpAddress('Out[512]', 1);
        writeOlpAddress('Out[513]', 0);
    }
    setOlpStatus('running', 'Running {program} locally on {robot}.', {
        program: targetProject.programPath || 'main.pro',
        robot: targetRobot.userData?.motionDisplayName || targetRobot.userData?.modelName || targetRobot.name || 'Robot'
    });
    // Start the OLP interpreter first. The tester connection is deliberately
    // detached from program execution, so a missing Virtual Bus can never
    // prevent main.pro from running on the selected robot.
    const runtimePromise = step
        ? runtime.stepOnce(targetProject.programPath)
        : runtime.run(targetProject.programPath);
    try { connectOlpVirtualBus(); }
    catch (error) {
        updateOlpBusStatus('Virtual Bus unavailable · OLP local execution remains active', error?.message || 'connection skipped');
    }
    try { await runtimePromise; }
    catch (error) {
        if (!/OLP stopped/i.test(error?.message || '')) {
            setExecution(targetRobot, { phase: 'error', running: false });
            setOlpStatus('error', 'OLP error: {error}', { error: error.message || error });
        }
    }
    if (runtimeMap?.get(robotInstanceId) === runtime) runtimeMap.delete(robotInstanceId);
    syncRuntime();
    if (!isOlpRunning()) setOlpStatus(state.olp.status === 'error' ? 'error' : 'connected', state.olp.status === 'error' ? '' : 'OLP ready.');
}

async function stopOlpSession(reason = 'OLP stopped', { closeBus = false, resetCursor = false, robot = null, robots = null } = {}) {
    const targetRobots = Array.isArray(robots)
        ? robots.filter(Boolean)
        : robot
            ? [robot]
            : [...(state.olp.runtimes?.values() || [])].map(getOlpRuntimeRobot).filter(Boolean);
    const runtimes = targetRobots
        .map((target) => getOlpRuntimeForRobot(target))
        .filter(Boolean);
    const wasRunning = runtimes.some(isOlpRuntimeRunning);
    if (resetCursor) {
        targetRobots.forEach((target) => {
            const instanceId = target.userData?.motionInstanceId;
            if (instanceId) state.olp.resetCursorRobotIds.add(instanceId);
        });
        if (!targetRobots.length || targetRobots.includes(getOlpRobot())) state.olp.resetCursorOnStop = true;
        targetRobots
            .filter((target) => !getOlpRuntimeForRobot(target))
            .forEach((target) => {
                resetOlpProgramCursor(target);
                const instanceId = target.userData?.motionInstanceId;
                if (instanceId) state.olp.resetCursorRobotIds.delete(instanceId);
            });
    }
    runtimes.forEach((runtime) => runtime.stop());
    // `stop()` changes the runtime phase synchronously.  Reflect it now so
    // duplicate Pause/Stop clicks are disabled while the current command is
    // unwinding, rather than waiting for the asynchronous stop completion.
    if (wasRunning) setOlpStatus('running');
    state.olp.virtualBusWanted = !closeBus && hasOlpProjects() && !isVirtualControllerActive();
    if (state.olp.reconnectTimer) {
        clearTimeout(state.olp.reconnectTimer);
        state.olp.reconnectTimer = null;
    }
    if (closeBus) {
        stopOlpBusMonitor();
        const socket = state.olp.socket;
        state.olp.socket = null;
        state.olp.busConnected = false;
        if (socket && [WebSocket.OPEN, WebSocket.CONNECTING].includes(socket.readyState)) {
            if (socket.readyState === WebSocket.OPEN) {
                try { socket.send(JSON.stringify({ type: 'goodbye', reason })); } catch { }
            }
            try { socket.close(); } catch { }
        }
    }
    updateOlpBusStatus(closeBus
        ? 'Virtual Bus closed'
        : (state.olp.busConnected ? 'Virtual Bus connected · tester master; OLP stopped' : 'Virtual Bus disconnected; OLP stopped'), reason);
    if (runtimes.length || reason) appendOlpConsole(reason);
    if (runtimes.length) {
        const deadline = performance.now() + 1200;
        while (runtimes.some((candidate) => candidate.running) && performance.now() < deadline) {
            await new Promise((resolve) => window.setTimeout(resolve, 20));
        }
    }
    if (!isOlpRunning()) {
        writeOlpAddress('Out[512]', 0);
        writeOlpAddress('Out[513]', 1);
        if (state.olp.resetCursorOnStop) {
            resetOlpProgramCursor();
            state.olp.resetCursorOnStop = false;
        }
        setOlpStatus(getOlpProject() ? 'connected' : 'disconnected', reason);
        if (!closeBus && state.olp.virtualBusWanted && !state.olp.socket) connectOlpVirtualBus();
    } else {
        state.olp.status = 'running';
        syncActiveOlpRuntime();
        updateOlpProgramPanelUi();
    }
    updateMotionUiLock();
}

async function connectVirtualController() {
    const controller = state.virtualController;
    if (isOlpRunning() || state.olp.socket) await stopOlpSession('Controller connection requested; OLP and Virtual Bus closed.', { closeBus: true });
    if (isRobotMotionActive()) return;
    refreshVirtualControllerRobotOptions();
    const isRealController = controller.controllerKind === 'real';
    const ipAddress = isRealController ? (el.virtualControllerIp?.value.trim() || '') : '127.0.0.1';
    if (getVirtualControllerSourceConfig(controller).id === 'bridge' && isRealController && !ipAddress) {
        setVirtualControllerStatus('error', '컨트롤러 IP를 입력해 주세요.');
        el.virtualControllerIp?.focus();
        return;
    }
    controller.ipAddress = ipAddress;
    const targetRobot = getVirtualControllerTargetRobot(controller);
    if (!targetRobot) {
        setVirtualControllerStatus(
            'error',
            state.collaboration.enabled ? '먼저 협업 패널에서 제어할 로봇을 점유하세요.' : '로봇을 선택하세요'
        );
        return;
    }
    const duplicate = getVirtualControllerSessions().find((candidate) => (
        candidate !== controller
        && candidate.wanted
        && candidate.targetRobotId === controller.targetRobotId
    ));
    if (duplicate) {
        setVirtualControllerStatus('error', '해당 로봇에는 이미 컨트롤러가 연결되어 있습니다.', controller);
        return;
    }
    try {
        await ensureVirtualControllerCore();
    } catch (error) {
        console.error('Virtual controller support failed to load:', error);
        setVirtualControllerStatus('error', '가상 컨트롤러 기능을 불러올 수 없습니다.');
        return;
    }
    if (getVirtualControllerSourceConfig(controller).id === 'bridge' && !controller.bridgeToken) {
        const bridgeRunning = await isVirtualControllerBridgeRunning(controller);
        if (!bridgeRunning || !controller.bridgeToken) {
            setVirtualControllerStatus('error', '브리지 인증 설정이 없어 연결할 수 없습니다. 운영 Origin과 토큰을 설정해 주세요.');
            return;
        }
    }
    commitAllPendingHistories();
    registerVirtualControllerSession(controller);
    controller.historyBefore = captureSceneSnapshot();
    controller.wanted = true;
    resetControllerGripInference(controller);
    if (controller.gripInference.enabled) enableControllerGripCollisionWarning();
    controller.samples?.clear();
    controller.lastAppliedSampleId = 0;
    controller.lastRateUpdateAt = 0;
    controller.sourceConnectedAt = 0;
    controller.lastSampleAt = 0;
    controller.lastStreamStartAt = 0;
    controller.reconnectAttempt = 0;
    controller.reconnectMessage = '';
    openVirtualControllerSocket(false, controller);
    requestRender();
}

function clearVirtualControllerBridgeHealthMonitor() {
    const controller = state.virtualController;
    if (controller.bridgeHealthTimer) {
        clearTimeout(controller.bridgeHealthTimer);
        controller.bridgeHealthTimer = null;
    }
    controller.bridgeHealthMonitorGeneration += 1;
}

async function isVirtualControllerBridgeRunning(controller = state.virtualController) {
    const healthCheckSequence = controller.bridgeHealthCheckSequence + 1;
    controller.bridgeHealthCheckSequence = healthCheckSequence;
    const bridge = controller.core?.getVirtualControllerSource?.('bridge') || {
        healthUrl: 'http://127.0.0.1:5055/api/health'
    };
    if (!bridge.healthUrl) return false;
    try {
        const response = await fetch(bridge.healthUrl, { cache: 'no-store' });
        const health = await response.json().catch(() => ({}));
        const pairingToken = response.ok && typeof health.pairingToken === 'string'
            ? health.pairingToken
            : null;
        const running = response.ok
            && health.service === 'InoRobotVirtualControllerBridge'
            && Boolean(pairingToken);
        if (controller.bridgeHealthCheckSequence === healthCheckSequence && running) {
            controller.bridgeToken = pairingToken;
            controller.bridgeHealthFailureCount = 0;
        } else if (controller.bridgeHealthCheckSequence === healthCheckSequence
            && (controller.wanted || controller.bridgeRunning || controller.bridgeStartInProgress)) {
            console.warn('Virtual controller bridge health check returned an unusable response.', {
                healthUrl: bridge.healthUrl,
                sequence: healthCheckSequence,
                status: Number(response.status) || 0,
                service: String(health.service || ''),
                hasPairingToken: Boolean(pairingToken)
            });
        }
        return running;
    } catch (error) {
        if (controller.bridgeHealthCheckSequence === healthCheckSequence
            && (controller.wanted || controller.bridgeRunning || controller.bridgeStartInProgress)) {
            console.warn('Virtual controller bridge health check failed.', {
                healthUrl: bridge.healthUrl,
                sequence: healthCheckSequence,
                error: error instanceof Error
                    ? `${error.name}: ${error.message}`
                    : String(error)
            });
        }
        return false;
    }
}

function monitorVirtualControllerBridgeHealth(silent = false) {
    const controller = state.virtualController;
    clearVirtualControllerBridgeHealthMonitor();
    const monitorGeneration = controller.bridgeHealthMonitorGeneration;
    void (async () => {
        const wasRunning = controller.bridgeRunning;
        const healthCheckSequence = controller.bridgeHealthCheckSequence + 1;
        const running = await isVirtualControllerBridgeRunning(controller);
        if (controller.bridgeHealthMonitorGeneration !== monitorGeneration) return;
        if (controller.bridgeHealthCheckSequence !== healthCheckSequence) {
            controller.bridgeHealthTimer = window.setTimeout(
                () => monitorVirtualControllerBridgeHealth(true),
                controller.wanted ? 350 : 750
            );
            return;
        }
        const bridgeIsActiveSource = getVirtualControllerSourceConfig(controller).id === 'bridge';

        if (running) {
            controller.bridgeRunning = true;
            controller.bridgeHealthFailureCount = 0;
            const wasStarting = controller.bridgeStartInProgress;
            controller.bridgeStartInProgress = false;
            controller.bridgeHealthDeadline = 0;
            if (wasStarting && !controller.wanted && bridgeIsActiveSource) {
                setVirtualControllerStatus('disconnected', '전용 브리지가 실행 중입니다.', controller);
            } else {
                refreshVirtualControllerUi();
            }
            if (bridgeIsActiveSource || controller.wanted) {
                controller.bridgeHealthTimer = window.setTimeout(
                    () => monitorVirtualControllerBridgeHealth(true),
                    1000
                );
            }
            return;
        }

        const stillStarting = controller.bridgeStartInProgress
            && performance.now() < controller.bridgeHealthDeadline;
        if (stillStarting) {
            controller.bridgeHealthTimer = window.setTimeout(monitorVirtualControllerBridgeHealth, 250);
            return;
        }

        controller.bridgeHealthFailureCount = Math.min(
            VIRTUAL_CONTROLLER_BRIDGE_HEALTH_FAILURE_LIMIT,
            controller.bridgeHealthFailureCount + 1
        );
        if (controller.bridgeHealthFailureCount < VIRTUAL_CONTROLLER_BRIDGE_HEALTH_FAILURE_LIMIT) {
            controller.bridgeHealthTimer = window.setTimeout(
                () => monitorVirtualControllerBridgeHealth(true),
                controller.wanted ? 350 : 750
            );
            if (!wasRunning) refreshVirtualControllerUi();
            return;
        }

        controller.bridgeRunning = false;
        controller.bridgeToken = null;
        controller.bridgeStartInProgress = false;
        controller.bridgeHealthDeadline = 0;
        if (controller.wanted && bridgeIsActiveSource) {
            endVirtualControllerSessionForSourceExit(getVirtualControllerSourceConfig());
        } else if (bridgeIsActiveSource && wasRunning) {
            setVirtualControllerStatus('disconnected', '전용 브리지가 종료되었습니다.');
        } else if (bridgeIsActiveSource && !silent) {
            setVirtualControllerStatus('error', '전용 브리지를 시작하지 못했습니다. 먼저 다운로드한 브리지를 한 번 실행해 주세요.');
        } else {
            refreshVirtualControllerUi();
        }
        if (bridgeIsActiveSource && !controller.wanted && !controller.bridgeStartInProgress
            && !el.virtualControllerPanel?.classList.contains('panel-user-hidden')) {
            controller.bridgeHealthTimer = window.setTimeout(
                () => monitorVirtualControllerBridgeHealth(true),
                1500
            );
        }
    })();
}

function launchVirtualControllerBridge() {
    const controller = state.virtualController;
    if (getVirtualControllerSourceConfig().id !== 'bridge') return;
    try {
        window.location.href = 'inorobot-vc-bridge://start';
        controller.bridgeStartInProgress = true;
        controller.bridgeHealthDeadline = performance.now() + 6000;
        setVirtualControllerStatus('disconnected', '전용 브리지를 시작하는 중...');
        monitorVirtualControllerBridgeHealth();
    } catch (error) {
        console.error('Virtual controller bridge launch failed:', error);
        setVirtualControllerStatus('error', '브리지를 먼저 다운로드하여 한 번 실행해 주세요.');
    }
}

async function stopVirtualControllerBridge() {
    const controller = state.virtualController;
    if (getVirtualControllerSourceConfig().id !== 'bridge' || controller.bridgeStopInProgress) return;
    getVirtualControllerSessions().slice().forEach((candidate) => {
        if (!candidate.wanted) return;
        state.virtualController = candidate;
        disconnectVirtualController();
    });
    state.virtualController = controller;

    try {
        await ensureVirtualControllerCore();
    } catch (error) {
        console.error('Virtual controller bridge support failed to load:', error);
        setVirtualControllerStatus('error', '가상 컨트롤러 기능을 불러올 수 없습니다.');
        return;
    }

    controller.bridgeStopInProgress = true;
    refreshVirtualControllerUi();
    const bridgeUrl = controller.core.getVirtualControllerSource('bridge').socketUrl;
    try {
        if (!(await isVirtualControllerBridgeRunning()) || !controller.bridgeToken) {
            throw new Error('Bridge pairing is not configured.');
        }
        await new Promise((resolve, reject) => {
            const socket = new WebSocket(bridgeUrl);
            const timeout = window.setTimeout(() => {
                try { socket.close(); } catch { /* Ignore close errors. */ }
                reject(new Error('Bridge shutdown timed out.'));
            }, 2500);
            const finish = (error = null) => {
                clearTimeout(timeout);
                try { socket.close(); } catch { /* Ignore close errors. */ }
                if (error) reject(error);
                else resolve();
            };
            socket.addEventListener('open', () => {
                socket.send(JSON.stringify({ type: 'hello', token: controller.bridgeToken }));
                socket.send(JSON.stringify({ type: 'shutdown', allowShutdown: true }));
            });
            socket.addEventListener('message', (event) => {
                const parsed = controller.core.parseVirtualControllerMessage(event.data, performance.now());
                if (parsed.kind === 'event' && parsed.type === 'shutdownResult') {
                    finish(parsed.message.success ? null : new Error('Bridge rejected shutdown.'));
                }
            });
            socket.addEventListener('error', () => finish(new Error('Bridge is not running.')));
        });
        setVirtualControllerStatus('disconnected', '전용 브리지가 종료되었습니다.');
    } catch (error) {
        console.error('Virtual controller bridge shutdown failed:', error);
        setVirtualControllerStatus('error', '실행 중인 전용 브리지를 찾을 수 없습니다.');
    } finally {
        controller.bridgeStopInProgress = false;
        controller.bridgeRunning = false;
        clearVirtualControllerBridgeHealthMonitor();
        refreshVirtualControllerUi();
    }
}

function closeVirtualControllerSocket(notifyBridge = true, controller = state.virtualController) {
    if (controller.reconnectTimer) {
        clearTimeout(controller.reconnectTimer);
        controller.reconnectTimer = null;
    }
    const socket = controller.socket;
    controller.socket = null;
    controller.socketGeneration += 1;
    if (!socket) return;
    if (notifyBridge && socket.readyState === WebSocket.OPEN) {
        socket.send(JSON.stringify({ type: getVirtualControllerSourceConfig(controller).stopCommand }));
        socket.send(JSON.stringify({ type: 'disconnect' }));
    }
    try { socket.close(1000, '3D simulation disconnected'); } catch { /* Already closed. */ }
}

function disconnectVirtualController(controller = state.virtualController) {
    const historyBefore = controller.historyBefore;
    const robot = getVirtualControllerTargetRobot(controller);
    if (robot) sendCollaborationRobotState(robot, { connected: false, streaming: false });
    controller.historyBefore = null;
    controller.wanted = false;
    resetControllerGripInference(controller);
    closeVirtualControllerSocket(true, controller);
    controller.pendingInterferenceReads.clear();
    controller.pendingInterferenceToolReads.clear();
    controller.samples?.clear();
    controller.lastAppliedSampleId = 0;
    controller.sourceConnectedAt = 0;
    controller.lastSampleAt = 0;
    controller.lastStreamStartAt = 0;
    controller.reconnectMessage = '';
    clearVirtualControllerStreamWatchdog(controller);
    setVirtualControllerStatus('disconnected', '', controller);
    refreshViewPresetsUi();
    if (historyBefore) recordHistory('가상 컨트롤러 동기화', historyBefore, captureSceneSnapshot());
    removeVirtualControllerSession(controller);
    refreshVirtualControllerUi();
}

function isVirtualControllerSourceLive(timestamp, controller = state.virtualController) {
    const source = getVirtualControllerSourceConfig(controller);
    if (source.id !== 'trace') return true;
    const lastActivityAt = Math.max(controller.sourceConnectedAt || 0, controller.lastSampleAt || 0);
    if (!lastActivityAt || timestamp - lastActivityAt <= TRACE_SOURCE_LIVENESS_TIMEOUT_MS) return true;
    endVirtualControllerSessionForSourceExit(source, controller);
    return false;
}

function resetControllerGripInference(controller = state.virtualController) {
    const inference = controller.gripInference;
    inference.robot = null;
    inference.stationaryPose = null;
    inference.stationarySince = 0;
    inference.contactKey = '';
    inference.contactSince = 0;
    inference.actionDone = false;
    inference.blockedUntilContactClears = false;
}

function getControllerGripPose(robot) {
    const joints = robot?.userData?.joints;
    if (!Array.isArray(joints) || joints.length === 0) return null;
    const pose = joints.map((joint) => Number(joint?.angle));
    return pose.every(Number.isFinite) ? pose : null;
}

function updateControllerGripStationaryState(robot, timestamp, controller = state.virtualController) {
    const inference = controller.gripInference;
    const pose = getControllerGripPose(robot);
    if (!pose) {
        resetControllerGripInference(controller);
        return false;
    }

    if (inference.robot !== robot
        || !Array.isArray(inference.stationaryPose)
        || inference.stationaryPose.length !== pose.length) {
        inference.robot = robot;
        inference.stationaryPose = pose;
        inference.stationarySince = timestamp;
        inference.contactSince = 0;
        inference.contactKey = '';
        inference.actionDone = false;
        inference.blockedUntilContactClears = false;
        return false;
    }

    const moved = pose.some((value, index) => (
        Math.abs(value - inference.stationaryPose[index]) > CONTROLLER_GRIP_POSITION_TOLERANCE
    ));
    if (moved) {
        // Keep the reference fixed until the accumulated pose drift exceeds
        // the tolerance. This prevents a slow, continuous motion made up of
        // sub-tolerance frame steps from being mistaken for a stop.
        inference.stationaryPose = pose;
        inference.stationarySince = timestamp;
        inference.contactSince = 0;
        if (!inference.blockedUntilContactClears) inference.actionDone = false;
    }
    return true;
}

function isControllerGripTool(model, robot) {
    return Boolean(
        model
        && model.userData?.placement === 'tcp'
        && model.userData?.attachmentHost === robot
        && model.visible !== false
    );
}

function isControllerGripObject(model, robot) {
    if (!model || model === robot) return false;
    if (isGripObjectModelInUse(model)) {
        return model.userData?.attachmentHost === robot;
    }
    return model.userData?.placement === 'scene' && isGripObjectTarget(model);
}

function isObjectWithinControllerGripRoot(object, root) {
    let current = object;
    while (current) {
        if (current === root) return true;
        current = current.parent;
    }
    return false;
}

function getControllerGripCollisionPart(model, mesh) {
    if (!model?.userData?.uploaded || !mesh) return null;
    return getImportedModelParts(model).find((part) => (
        isObjectWithinControllerGripRoot(mesh, part)
    )) || null;
}

function getControllerGripContactIdentity(model, part = null) {
    const source = normalizeGripObjectSource(model?.userData?.gripObjectSource);
    if (source?.sourceModelId) {
        return `${source.mode}:${source.sourceModelId}:${source.sourcePartIndex ?? ''}`;
    }
    const modelId = ensureWorkspaceModelId(model);
    if (part) {
        const partIndex = getImportedModelParts(model).indexOf(part);
        return `part:${modelId}:${partIndex}`;
    }
    return `model:${modelId}`;
}

function getControllerGripContact(result, robot) {
    const candidates = [];
    asCollisionResults(result).forEach((hit) => {
        const pairs = [
            { tool: hit.objectA, object: hit.objectB, objectMesh: hit.meshB },
            { tool: hit.objectB, object: hit.objectA, objectMesh: hit.meshA }
        ];
        pairs.forEach(({ tool, object, objectMesh }) => {
            if (!isControllerGripTool(tool, robot) || !isControllerGripObject(object, robot)) return;
            const attached = isGripObjectModelInUse(object);
            const part = attached ? null : getControllerGripCollisionPart(object, objectMesh);
            if (part && findActiveGripObjectForSource(object, part)) return;
            const identity = getControllerGripContactIdentity(object, part);
            candidates.push({
                key: `${tool.uuid}:${identity}`,
                tool,
                object,
                objectMesh,
                part,
                attached
            });
        });
    });

    // If the Tool is touching both a held object and a scene object, finish
    // the held-object toggle first. This keeps the attached state coherent.
    candidates.sort((left, right) => Number(right.attached) - Number(left.attached));
    return candidates[0] || null;
}

function applyControllerGripContact(contact, robot) {
    const attached = isGripObjectModelInUse(contact.object)
        && contact.object.userData?.attachmentHost === robot;
    if (attached) {
        const released = releaseGripObject(contact.object, {
            recordHistory: false,
            select: false,
            announce: false,
            allowDuringMotion: true
        });
        if (released) setStatus('물건을 놓았습니다.', '#22c55e');
        return { applied: released, action: 'release' };
    }

    const used = useGripObject(contact.object, contact.part, robot, {
        recordHistory: false,
        select: false,
        announce: false,
        allowDuringMotion: true
    });
    if (used) setStatus('물건을 잡았습니다.', '#22c55e');
    return { applied: used, action: 'use' };
}

function updateControllerGripInference(timestamp, collision, controller = state.virtualController) {
    const robot = getVirtualControllerTargetRobot(controller);
    const sampleIsLive = controller.status === 'streaming'
        && Number.isFinite(controller.lastSampleAt)
        && timestamp - controller.lastSampleAt <= VIRTUAL_CONTROLLER_STREAM_STALL_MS;
    if (!controller.wanted || !controller.gripInference.enabled || !robot || !state.collision.enabled || !sampleIsLive) {
        resetControllerGripInference(controller);
        return;
    }

    const stationary = updateControllerGripStationaryState(robot, timestamp, controller);
    const inference = controller.gripInference;
    const contact = getControllerGripContact(collision, robot);
    if (!contact) {
        inference.contactKey = '';
        inference.contactSince = 0;
        inference.actionDone = false;
        inference.blockedUntilContactClears = false;
        return;
    }

    if (inference.contactKey !== contact.key) {
        inference.contactKey = contact.key;
        inference.contactSince = 0;
        inference.actionDone = false;
        inference.blockedUntilContactClears = false;
    }
    if (!stationary || inference.blockedUntilContactClears || inference.actionDone) return;
    if (!inference.contactSince) inference.contactSince = timestamp;
    if (timestamp - inference.contactSince < CONTROLLER_GRIP_CONTACT_HOLD_MS) return;

    const result = applyControllerGripContact(contact, robot);
    inference.actionDone = true;
    // A release can leave the object geometrically touching the Tool. Do not
    // immediately pick it again until the contact has actually cleared.
    if (result.action === 'release' && result.applied) {
        inference.blockedUntilContactClears = true;
    }
}

function applyVirtualControllerFrameForController(timestamp, controller) {
    if (!controller.wanted || !controller.samples || !controller.core) return;
    if (!isVirtualControllerSourceLive(timestamp, controller)) return;
    const robot = getVirtualControllerTargetRobot(controller);
    const sample = controller.samples.getLatest();
    if (!robot || !sample || sample.sampleId <= controller.lastAppliedSampleId) return;
    if (robot.userData.interferenceStopLatched) return;
    if (timestamp - controller.lastRateUpdateAt >= 250) {
        controller.lastRateUpdateAt = timestamp;
        refreshVirtualControllerUi();
    }
    controller.lastAppliedSampleId = sample.sampleId;
    const joints = robot.userData.joints || [];
    if (!Array.isArray(sample.joints) || sample.joints.length < joints.length) {
        setVirtualControllerStatus('error', '가상 컨트롤러의 관절 위치를 가져올 수 없습니다.', controller);
        return;
    }
    joints.forEach((joint, index) => {
        let value = sample.joints[index];
        // The controller can report the SCARA vertical axis as a motor/encoder
        // angle, while the simulator's J3 is prismatic and expects millimeters.
        // TCP Z is already in the Cartesian unit expected by the simulator. If
        // TCP feedback is unavailable (for example Trace), convert the raw
        // controller Joint angle back to the simulator's millimeter coordinate.
        if (index === 2
            && robot.userData.manifest?.robotType === 'scara'
            && Number.isFinite(sample.position?.[2])) {
            const tcpOffsetZ = Number(robot.userData.tcpFrame?.position?.z) || 0;
            value = sample.position[2] - tcpOffsetZ;
        } else if (index === 2 && robot.userData.manifest?.robotType === 'scara') {
            value = getJointJogDisplaySpec(joint).fromDisplay(value);
        }
        setJointAngle(joint, value, false);
    });
    robot.updateMatrixWorld(true);
    queueCollaborationRobotState(robot);
    controller.statusMessage = '';
    const pose = getCurrentTcpPoseBase(robot);
    if (pose) {
        robot.userData.baseJogTarget = {
            position: pose.position.clone(),
            quaternion: pose.quaternion.clone()
        };
        if (robot === state.activeArticulatedModel) {
            syncJointControls(robot);
            updateTcpPresentation(robot, pose);
            if (!el.baseJogView?.classList.contains('hidden')) {
                syncBaseJogGizmoFromRobot(robot, pose);
            }
        }
    }

}

function getArticulatedRobots() {
    return state.models.filter(isArticulatedRobotModel);
}

function applyVirtualControllerFrame(timestamp) {
    getVirtualControllerSessions().forEach((controller) => {
        applyVirtualControllerFrameForController(timestamp, controller);
    });
}

function isArticulatedRobotModel(model) {
    return Boolean(model && Array.isArray(model.userData?.joints) && model.userData?.tcpFrame);
}

function getJogTargetRobot() {
    const robots = getArticulatedRobots();
    if (robots.length === 0) return null;

    // JOG follows an explicitly selected robot. Selecting a shape must not
    // change the robot that the JOG panel controls.
    if (robots.includes(state.selectedModel)) return state.selectedModel;

    // activeArticulatedModel is kept as the last selected robot while the
    // scene selection is empty or points to a non-robot model.
    if (robots.includes(state.activeArticulatedModel)) return state.activeArticulatedModel;

    // A single robot is unambiguous even when the scene currently has no
    // selected model (for example after a selection was cleared).
    return robots.length === 1 ? robots[0] : null;
}

function createMotionId(prefix = 'motion') {
    if (globalThis.crypto?.randomUUID) return `${prefix}-${globalThis.crypto.randomUUID()}`;
    return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function parseRobotInstanceNumber(value) {
    const match = String(value || '').match(/#(\d+)\s*$/);
    const number = match ? Number(match[1]) : 0;
    return Number.isInteger(number) && number > 0 ? number : 0;
}

function getNextRobotInstanceNumber() {
    const existingNumbers = getArticulatedRobots().map((candidate) => (
        Number(candidate.userData?.robotInstanceNumber)
        || parseRobotInstanceNumber(candidate.userData?.motionDisplayName)
    ));
    state.robotInstanceNumberCounter = Math.max(
        state.robotInstanceNumberCounter,
        ...existingNumbers,
        0
    ) + 1;
    return state.robotInstanceNumberCounter;
}

function assignRobotInstanceMetadata(robot, modelDefinition, preferred = {}) {
    const modelName = preferred.modelName || modelDefinition?.name || robot.userData.robotName || robot.name || 'Robot';
    const preferredNumber = Number(preferred.instanceNumber);
    const hasPreferredNumber = Number.isInteger(preferredNumber) && preferredNumber > 0
        && !getArticulatedRobots().some((candidate) => (
            Number(candidate.userData?.robotInstanceNumber)
            || parseRobotInstanceNumber(candidate.userData?.motionDisplayName)
        ) === preferredNumber
        );
    const instanceNumber = hasPreferredNumber ? preferredNumber : getNextRobotInstanceNumber();
    const preferredDisplayBase = typeof preferred.displayName === 'string'
        ? preferred.displayName.replace(/\s*#\d+\s*$/, '').trim()
        : '';
    robot.userData.motionInstanceId = preferred.instanceId || robot.userData.motionInstanceId || createMotionId('robot');
    robot.userData.motionModelName = modelName;
    robot.userData.robotInstanceNumber = instanceNumber;
    robot.userData.motionDisplayName = `${preferredDisplayBase || modelName} #${instanceNumber}`;
    state.robotInstanceNumberCounter = Math.max(state.robotInstanceNumberCounter, instanceNumber);
    robot.userData.motionModelFolder = preferred.modelFolder || modelDefinition?.folder || '';
    robot.userData.motionRobotType = preferred.robotType || modelDefinition?.robotType || robot.userData.manifest?.robotType || '';
    robot.userData.motionModelDefinition = modelDefinition || robot.userData.motionModelDefinition || null;
    return robot.userData.motionInstanceId;
}

function ensureMotionProgram(robot) {
    if (!robot?.userData.tcpFrame) return null;
    if (!robot.userData.motionInstanceId) {
        assignRobotInstanceMetadata(robot, robot.userData.motionModelDefinition || {
            name: robot.userData.robotName,
            folder: robot.userData.motionModelFolder,
            robotType: robot.userData.manifest?.robotType
        });
    }
    const id = robot.userData.motionInstanceId;
    if (!state.motionPrograms.has(id)) state.motionPrograms.set(id, createEmptyMotionProgram(true));
    return state.motionPrograms.get(id);
}

function getMotionSession(robot) {
    return robot ? state.motionSessions.get(robot.userData.motionInstanceId) || null : null;
}

function isMotionActive() {
    return isRobotMotionActive()
        || isVirtualControllerActive();
}

function isAny3DTransformHandleDragging() {
    return Boolean(
        state.transformControls?.dragging
        || state.zeroPointEdit?.transformControls?.dragging
        || state.baseJogGizmoDragging
    );
}

// A connected controller continuously updates the selected robot pose, but it
// should not make unrelated scene operations unavailable. Keep the controller
// in the motion interlock for robot-control actions while using this narrower
// predicate for model loading and other scene-only operations.
function isRobotMotionActive() {
    return state.motionSessions.size > 0
        || isOlpRunning()
        || Boolean(state.olp.workOriginBusy)
        || Boolean(state.olp.manualMoveBusy);
}

function isModelMotionActive(model) {
    if (!model?.userData?.motionInstanceId) return false;
    const session = getMotionSession(model);
    if (session && ['running', 'paused'].includes(String(session.status || '').toLowerCase())) return true;
    const runtime = getOlpRuntimeForRobot(model);
    if (isOlpRuntimeRunning(runtime)) return true;
    if (state.olp.runtime?.robot === model && isOlpRuntimeRunning(state.olp.runtime)) return true;
    if ((state.olp.workOriginBusy || state.olp.manualMoveBusy) && getOlpRobot() === model) return true;
    return Boolean(
        isVirtualControllerActive()
        && (state.activeArticulatedModel === model || state.activeProgramRobot === model)
    );
}

function getMotionStatus(robot) {
    return getMotionSession(robot)?.status || ensureMotionProgram(robot)?.status || 'idle';
}

function motionStatusLabel(status) {
    return uiText(({
        idle: '대기',
        running: '실행 중',
        paused: '일시정지',
        completed: '완료',
        error: '오류',
        stopped: '정지됨'
    })[status] || status);
}

function showMotionProgramPanel() {
    if (!el.programPanel) return;
    const wasHidden = el.programPanel.classList.contains('hidden')
        || el.programPanel.classList.contains('panel-user-hidden');
    el.programPanel.classList.remove('hidden');
    if (!el.programPanel.dataset.motionPanelInitialized) {
        el.programPanel.classList.remove('panel-user-hidden');
        el.programPanel.dataset.motionPanelInitialized = 'true';
    }
    if (wasHidden && !el.programPanel.classList.contains('panel-user-hidden')) {
        bringPanelToFront('program-panel');
    }
    updatePanelLauncher('program-panel');
}

function refreshMotionProgramStatus() {
    if (!el.programStatus || !state.motionProgramStatus) return;
    const { message, type, replacements } = state.motionProgramStatus;
    el.programStatus.textContent = uiFormat(message, replacements);
    el.programStatus.classList.toggle('error', type === 'error');
    el.programStatus.classList.toggle('working', type === 'working');
}

function setMotionProgramStatus(message, type = '', replacements = {}) {
    if (!el.programStatus) return;
    state.motionProgramStatus = { message, type, replacements };
    refreshMotionProgramStatus();
}

function setAutoPathStatus(message, type = '', replacements = {}) {
    if (!el.autoPathStatus) return;
    const text = uiFormat(message, replacements);
    el.autoPathStatus.textContent = text;
    el.autoPathStatus.classList.toggle('working', type === 'working');
    el.autoPathStatus.classList.toggle('error', type === 'error');
    el.autoPathStatus.classList.toggle('success', type === 'success');
}

function getAutoPathRobot() {
    return state.activeProgramRobot || state.activeArticulatedModel || getArticulatedRobots()[0] || null;
}

function getAutoPathPointSteps(robot = state.autoPath.robot || state.activeProgramRobot) {
    const program = robot ? ensureMotionProgram(robot) : null;
    return (program?.steps || []).filter((step) => isMotionPointMotion(step.motion));
}

function formatAutoPathPointOption(step) {
    const pointName = formatMotionPointName(step.pointIndex);
    return step.label ? `${pointName} · ${step.label}` : pointName;
}

function refreshAutoPathPointOptions() {
    const pointSteps = getAutoPathPointSteps();
    [
        [el.autoPathStart, state.autoPath.startStepId],
        [el.autoPathTarget, state.autoPath.targetStepId]
    ].forEach(([select, selectedId]) => {
        if (!select) return;
        select.setAttribute('aria-label', uiText(select === el.autoPathStart ? '시작 위치' : '목표 위치'));
        select.replaceChildren();
        pointSteps.forEach((step) => {
            const option = document.createElement('option');
            option.value = step.id;
            option.textContent = formatAutoPathPointOption(step);
            select.appendChild(option);
        });
        const fallbackId = pointSteps.find((step) => step.id === selectedId)?.id
            || pointSteps[select === el.autoPathStart ? 0 : 1]?.id
            || pointSteps[0]?.id
            || '';
        select.value = fallbackId;
        select.disabled = pointSteps.length < 2 || state.autoPath.planning;
    });
    if (pointSteps.length >= 2) {
        state.autoPath.startStepId = el.autoPathStart?.value || pointSteps[0].id;
        state.autoPath.targetStepId = el.autoPathTarget?.value || pointSteps[1].id;
    } else {
        state.autoPath.startStepId = null;
        state.autoPath.targetStepId = null;
    }
}

function refreshAutoPathUi() {
    if (el.btnProgramAutoPath) {
        el.btnProgramAutoPath.title = uiText('자동 경로 생성');
        el.btnProgramAutoPath.setAttribute('aria-label', uiText('자동 경로 생성'));
    }
    const heading = el.autoPathPanel?.querySelector('.auto-path-heading strong');
    if (heading) heading.innerHTML = `<i class="fa-solid fa-route"></i> ${uiText('자동 경로 생성')}`;
    if (el.btnAutoPathGenerate) el.btnAutoPathGenerate.textContent = uiText(state.autoPath.path ? '경로 다시 계산' : '경로 생성');
    if (el.btnAutoPathApply) {
        el.btnAutoPathApply.textContent = uiText('경로 적용');
        el.btnAutoPathApply.disabled = !state.autoPath.path
            || (state.autoPath.generatedPointCount <= 0
                && !state.autoPath.motionChangeRequired
                && !state.autoPath.targetConfigurationChangeRequired
                && !state.autoPath.endpointTcpSyncRequired)
            || state.autoPath.planning;
    }
    if (el.btnAutoPathCancel) {
        el.btnAutoPathCancel.title = uiText('경로 취소');
        el.btnAutoPathCancel.setAttribute('aria-label', uiText('경로 취소'));
    }
    refreshAutoPathPointOptions();
}

function clearAutoPathPreview() {
    const group = state.autoPath.previewGroup;
    if (!group) return;
    group.parent?.remove(group);
    group.traverse((child) => {
        child.geometry?.dispose?.();
        if (Array.isArray(child.material)) child.material.forEach((material) => material.dispose?.());
        else child.material?.dispose?.();
    });
    state.autoPath.previewGroup = null;
    requestRender();
}

function closeAutoPathPanel({ preserveStatus = false } = {}) {
    state.autoPath.cancelRequested = true;
    clearAutoPathPreview();
    const robot = state.autoPath.robot;
    if (robot && Array.isArray(state.autoPath.startAngles)) {
        applyPlanningJointAngles(robot, state.autoPath.startAngles);
    }
    state.autoPath.active = false;
    state.autoPath.planning = false;
    state.autoPath.robot = null;
    state.autoPath.startAngles = null;
    state.autoPath.startStepId = null;
    state.autoPath.targetStepId = null;
    state.autoPath.targetPose = null;
    state.autoPath.path = null;
    state.autoPath.generatedPointCount = 0;
    state.autoPath.motionChangeRequired = false;
    state.autoPath.targetConfigurationChangeRequired = false;
    state.autoPath.endpointTcpSyncRequired = false;
    state.autoPath.settings = null;
    el.autoPathPanel?.classList.add('hidden');
    if (!preserveStatus) setAutoPathStatus('시작 위치와 목표 위치를 선택한 후 경로 생성 버튼을 누르세요.');
    refreshAutoPathUi();
}

function openAutoPathPanel() {
    if (isMotionActive()) return;
    const robot = getAutoPathRobot();
    const program = robot ? ensureMotionProgram(robot) : null;
    if (!robot || !program) {
        setMotionProgramStatus('활성 로봇을 선택하세요.', 'error');
        return;
    }
    clearAutoPathPreview();
    const pointSteps = getAutoPathPointSteps(robot);
    state.autoPath = {
        active: true,
        planning: false,
        cancelRequested: false,
        robot,
        startAngles: robot.userData.joints.map((joint) => joint.angle),
        startStepId: pointSteps[0]?.id || null,
        targetStepId: pointSteps[1]?.id || pointSteps[0]?.id || null,
        targetPose: null,
        path: null,
        generatedPointCount: 0,
        motion: 'auto',
        motionChangeRequired: false,
        targetConfigurationChangeRequired: false,
        endpointTcpSyncRequired: false,
        previewGroup: null,
        settings: null
    };
    el.autoPathPanel?.classList.remove('hidden');
    refreshAutoPathUi();
    setAutoPathStatus(pointSteps.length >= 2
        ? '시작 위치와 목표 위치를 선택한 후 경로 생성 버튼을 누르세요.'
        : '자동 경로 생성에는 이동 포인트 2개가 필요합니다.',
    pointSteps.length >= 2 ? '' : 'error');
    bringPanelToFront('program-panel');
}

function readAutoPathSettings() {
    const read = (input, fallback) => {
        const value = Number(input?.value);
        return Number.isFinite(value) ? value : fallback;
    };
    return {
        holdOrientation: el.autoPathHoldOrientation?.checked !== false,
        speed: THREE.MathUtils.clamp(read(el.autoPathSpeed, DEFAULT_MOVJ_SPEED), 1, 100),
        maxPoints: Math.floor(THREE.MathUtils.clamp(read(el.autoPathMaxPoints, 40), 2, 50)),
        maxTimeMs: THREE.MathUtils.clamp(read(el.autoPathMaxTime, 7), 1, 15) * 1000
    };
}

function handleAutoPathPointSelectionChange() {
    if (!state.autoPath.active || state.autoPath.planning || isMotionActive()) return;
    state.autoPath.startStepId = el.autoPathStart?.value || null;
    state.autoPath.targetStepId = el.autoPathTarget?.value || null;
    state.autoPath.targetPose = null;
    state.autoPath.path = null;
    state.autoPath.generatedPointCount = 0;
    state.autoPath.motionChangeRequired = false;
    state.autoPath.targetConfigurationChangeRequired = false;
    state.autoPath.endpointTcpSyncRequired = false;
    clearAutoPathPreview();
    setAutoPathStatus('시작 위치와 목표 위치를 선택한 후 경로 생성 버튼을 누르세요.');
    refreshAutoPathUi();
}

function handleAutoPathSettingChange() {
    if (!state.autoPath.active || state.autoPath.planning || isMotionActive()) return;
    state.autoPath.targetPose = null;
    state.autoPath.path = null;
    state.autoPath.generatedPointCount = 0;
    state.autoPath.motionChangeRequired = false;
    state.autoPath.targetConfigurationChangeRequired = false;
    state.autoPath.endpointTcpSyncRequired = false;
    clearAutoPathPreview();
    setAutoPathStatus('경로 설정을 바꿨습니다. 경로 생성 버튼을 눌러 다시 계산하세요.');
    refreshAutoPathUi();
}

function withCollisionPoseProbe(callback) {
    state.collision.poseProbeDepth = (Number(state.collision.poseProbeDepth) || 0) + 1;
    try {
        return callback();
    } finally {
        state.collision.poseProbeDepth = Math.max(0, (Number(state.collision.poseProbeDepth) || 1) - 1);
    }
}

function applyPlanningJointAngles(robot, angles) {
    if (!robot?.userData?.joints || !Array.isArray(angles)) return;
    withCollisionPoseProbe(() => {
        robot.userData.joints.forEach((joint, index) => setJointAngle(joint, angles[index], false));
        robot.updateMatrixWorld(true);
    });
}

function isAutoPathTargetInsideModel(robot, targetPose, collisionModels) {
    const worldPoint = targetPose.position.clone().applyMatrix4(robot.matrixWorld);
    const obstacleModels = collisionModels.filter((model) => (
        model !== robot && model.userData?.attachmentHost !== robot
    ));
    return Boolean(state.collision.system?.isPointInside(obstacleModels, worldPoint));
}

function createAutoPathCollisionEvaluator(robot, originalAngles) {
    const collisionModels = getCollisionModels();
    const system = state.collision.system;
    if (!system) throw new Error('충돌 검사 시스템이 준비되지 않았습니다.');
    system.prepare(collisionModels);
    // Only the planning robot and the Tools/loads mounted on it move while a
    // route is being sampled.  Marking every static CAD root as changed made
    // each candidate rebuild all model-pair checks and exhausted the planner
    // before it could find the transition poses around a fixture.
    const changedRoots = new Set(collisionModels.filter((model) => (
        model === robot || model.userData?.attachmentHost === robot
    )));
    const getHits = (angles) => {
        applyPlanningJointAngles(robot, angles);
        try {
            return asCollisionResults(system.checkAll(collisionModels, {
                changedRoots,
                allowWarmHitReuse: false
            }));
        } finally {
            applyPlanningJointAngles(robot, originalAngles);
        }
    };
    return {
        collisionModels,
        getHits,
        isSafe: (angles) => getHits(angles).length === 0
    };
}

function formatAutoPathCollisionPairs(hits, limit = 2) {
    return asCollisionResults(hits)
        .slice(0, limit)
        .map((hit) => {
            const describePart = (mesh, root) => {
                const jointIndex = Number(mesh?.userData?.robotJointIndex);
                if (Number.isInteger(jointIndex)) return `J${jointIndex + 1}`;
                for (let current = mesh; current && current !== root; current = current.parent) {
                    const partName = current.userData?.modelPartName || current.userData?.cadPartName;
                    if (partName) return partName;
                }
                return mesh?.userData?.modelPartName || mesh?.userData?.cadPartName || mesh?.name || '';
            };
            const leftPart = describePart(hit.meshA, hit.objectA);
            const rightPart = describePart(hit.meshB, hit.objectB);
            const left = `${collisionModelLabel(hit.objectA)}${leftPart ? ` (${leftPart})` : ''}`;
            const right = `${collisionModelLabel(hit.objectB)}${rightPart ? ` (${rightPart})` : ''}`;
            return `${left} ↔ ${right}`;
        })
        .filter(Boolean)
        .join(', ');
}

function autoPathJointBounds(robot) {
    return (robot.userData.joints || []).map((joint) => ({
        min: Number(joint.definition.min),
        max: Number(joint.definition.max),
        weight: 1,
        sampleStep: joint.definition.type === 'prismatic' ? 10 : 8
    }));
}

function autoPathJointDistance(left, right, bounds) {
    return Math.sqrt(left.reduce((sum, value, index) => {
        const range = Math.max(1e-6, bounds[index].max - bounds[index].min);
        return sum + (((right[index] - value) / range) ** 2);
    }, 0));
}

function solveAutoPathGoalCandidates(robot, targetPose, startingAngles, { maxSeeds = Infinity } = {}) {
    const joints = robot.userData.joints || [];
    if (robot.userData.manifest?.robotType === 'scara') {
        applyPlanningJointAngles(robot, startingAngles);
        const result = solveRobotIK(robot, targetPose, {
            positionTolerance: 0.8,
            rotationTolerance: THREE.MathUtils.degToRad(0.5)
        });
        const angles = result.success ? joints.map((joint) => joint.angle) : null;
        applyPlanningJointAngles(robot, startingAngles);
        return angles ? [{ angles }] : [];
    }

    const seedOffsets = [
        [],
        [[0, 60]], [[0, -60]], [[0, 100]], [[0, -100]],
        [[1, 45]], [[1, -45]], [[1, 75]], [[1, -75]],
        [[2, 60]], [[2, -60]], [[2, 120]], [[2, -120]],
        [[4, 60]], [[4, -60]], [[4, 100]], [[4, -100]],
        [[0, 60], [1, 45]], [[0, -60], [1, -45]],
        [[0, 60], [1, -45]], [[0, -60], [1, 45]],
        [[0, 180]], [[0, -180]], [[1, 120]], [[1, -120]],
        [[5, 90]], [[5, -90]]
    ];
    const bounds = autoPathJointBounds(robot);
    const candidates = [];
    const seeds = [];
    const addSeed = (angles) => {
        if (!Array.isArray(angles)
            || angles.length !== joints.length
            || angles.some((angle, index) => !Number.isFinite(angle)
                || angle < bounds[index].min
                || angle > bounds[index].max)) return;
        if (!seeds.some((seed) => autoPathJointDistance(seed, angles, bounds) < 0.01)) {
            seeds.push(angles.slice());
        }
    };
    const addCandidate = (angles) => {
        if (!angles || candidates.some((candidate) => autoPathJointDistance(candidate.angles, angles, bounds) < 0.01)) return;
        candidates.push({
            angles: angles.slice(),
            score: autoPathJointDistance(startingAngles, angles, bounds)
        });
    };

    addSeed(startingAngles);
    for (const offsets of seedOffsets) {
        addSeed(startingAngles.map((angle, index) => (
            angle + (offsets.find(([jointIndex]) => jointIndex === index)?.[1] || 0)
        )));
    }
    const targetYaw = THREE.MathUtils.radToDeg(Math.atan2(targetPose.position.y, targetPose.position.x));
    const absoluteSeedBases = [
        [0, -90, 0, 0, 90, 0],
        [0, -90, 0, 0, -90, 0],
        [90, -90, 0, 0, 90, 0],
        [-90, -90, 0, 0, -90, 0],
        [targetYaw, -90, 0, 0, 90, 0],
        [targetYaw + 180, -90, 0, 0, -90, 0]
    ];
    absoluteSeedBases.forEach((base) => {
        addSeed(base);
        addSeed(base.map((angle, index) => angle + (index === 1 ? 45 : 0)));
        addSeed(base.map((angle, index) => angle + (index === 1 ? -45 : 0)));
    });

    for (const seed of seeds.slice(0, Math.max(1, Math.floor(Number(maxSeeds) || 1)))) {
        applyPlanningJointAngles(robot, seed);
        const result = solveRobotIK(robot, targetPose, {
            positionTolerance: 0.8,
            rotationTolerance: THREE.MathUtils.degToRad(0.5)
        });
        if (result.success) addCandidate(joints.map((joint) => joint.angle));
    }
    applyPlanningJointAngles(robot, startingAngles);
    return candidates.sort((left, right) => left.score - right.score);
}

function findCollisionFreeAutoPathPoseCandidates(robot, targetPose, preferredAngles, evaluator) {
    return solveAutoPathGoalCandidates(robot, targetPose, preferredAngles)
        .filter((candidate) => evaluator.isSafe(candidate.angles));
}

function addAutoPathTransitionCandidate(candidates, angles, bounds, source = '') {
    if (!Array.isArray(angles)
        || angles.length !== bounds.length
        || angles.some((angle, index) => !Number.isFinite(angle)
            || angle < bounds[index].min
            || angle > bounds[index].max)) return false;
    if (candidates.some((candidate) => (
        autoPathJointDistance(candidate.angles, angles, bounds) < 0.008
    ))) return false;
    candidates.push({ angles: angles.slice(), source });
    return true;
}

function clampAutoPathTransitionState(angles, bounds) {
    return bounds.map((bound, index) => THREE.MathUtils.clamp(
        Number(angles[index]) || 0,
        bound.min,
        bound.max
    ));
}

function buildAutoPathTeachingSeeds(startAngles, targetAngles, bounds) {
    const seeds = [];
    const add = (angles) => addAutoPathTransitionCandidate(seeds, angles, bounds, 'seed');
    add(startAngles);
    add(targetAngles);
    add(startAngles.map((angle, index) => (angle + targetAngles[index]) * 0.5));

    if (bounds.length < 6) return seeds.map((candidate) => candidate.angles);
    const yawValues = [startAngles[0], targetAngles[0], 0, -90, 90];
    const compactPostures = [
        [-105, 110, 0, 0, 0],
        [-85, 80, 0, 0, 0],
        [-55, 125, 0, 0, 0],
        [-110, 55, 0, 0, 0],
        [-35, 90, 0, 0, 0]
    ];
    yawValues.forEach((yaw, yawIndex) => {
        const posture = compactPostures[yawIndex % compactPostures.length];
        add(clampAutoPathTransitionState([yaw, ...posture], bounds));
    });
    return seeds.map((candidate) => candidate.angles);
}

function buildAutoPathTeachingStagePoses(robot, startPose, targetPose, collisionModels) {
    const obstacleTop = getAutoPathObstacleTopInBase(robot, collisionModels);
    const clearanceZ = Math.max(
        startPose.position.z + 150,
        targetPose.position.z + 150,
        Number.isFinite(obstacleTop) ? obstacleTop + 70 : -Infinity,
        420
    );
    const poses = [];
    const add = (position) => {
        if (!Number.isFinite(position.x) || !Number.isFinite(position.y) || !Number.isFinite(position.z)) return;
        if (poses.some((pose) => pose.position.distanceToSquared(position) < 1)) return;
        poses.push({
            position: position.clone(),
            quaternion: startPose.quaternion.clone()
        });
    };
    const directionFor = (position) => {
        const direction = new THREE.Vector3(position.x, position.y, 0);
        if (direction.lengthSq() < 1) direction.set(1, 0, 0);
        return direction.normalize();
    };
    const addEndpointStages = (pose) => {
        const direction = directionFor(pose.position);
        const tangent = new THREE.Vector3(-direction.y, direction.x, 0);
        const raisedZ = Math.min(clearanceZ, Math.max(pose.position.z + 100, clearanceZ - 120));
        add(new THREE.Vector3(pose.position.x, pose.position.y, raisedZ));
        add(new THREE.Vector3(
            pose.position.x + direction.x * 140,
            pose.position.y + direction.y * 140,
            clearanceZ
        ));
        add(new THREE.Vector3(
            pose.position.x + tangent.x * 180,
            pose.position.y + tangent.y * 180,
            clearanceZ
        ));
        add(new THREE.Vector3(
            pose.position.x - tangent.x * 180,
            pose.position.y - tangent.y * 180,
            clearanceZ
        ));
    };

    addEndpointStages(startPose);
    addEndpointStages(targetPose);
    const directions = [directionFor(startPose.position), directionFor(targetPose.position)];
    const midpointDirection = directions[0].clone().add(directions[1]);
    if (midpointDirection.lengthSq() > 1e-6) directions.push(midpointDirection.normalize());
    directions.forEach((direction) => {
        add(direction.clone().multiplyScalar(430).setZ(clearanceZ));
        add(direction.clone().multiplyScalar(650).setZ(clearanceZ));
    });
    add(new THREE.Vector3(0, 0, clearanceZ));
    return poses.slice(0, 12);
}

function solveAutoPathStageCandidates(robot, stagePose, seedStates, bounds, limit = 3) {
    const originalAngles = robot.userData.joints.map((joint) => joint.angle);
    const candidates = [];
    const seeds = [];
    const addSeed = (angles) => {
        if (!Array.isArray(angles)
            || angles.length !== bounds.length
            || angles.some((angle, index) => !Number.isFinite(angle)
                || angle < bounds[index].min
                || angle > bounds[index].max)) return;
        if (!seeds.some((seed) => autoPathJointDistance(seed, angles, bounds) < 0.008)) {
            seeds.push(angles.slice());
        }
    };
    seedStates.forEach(addSeed);
    for (const seed of seeds.slice(0, 5)) {
        applyPlanningJointAngles(robot, seed);
        const solved = solveRobotIK(robot, stagePose, {
            positionTolerance: 0.8,
            rotationTolerance: THREE.MathUtils.degToRad(0.6)
        });
        if (solved.success) {
            addAutoPathTransitionCandidate(
                candidates,
                robot.userData.joints.map((joint) => joint.angle),
                bounds,
                'stage'
            );
        }
        if (candidates.length >= limit) break;
    }
    applyPlanningJointAngles(robot, originalAngles);
    return candidates.map((candidate) => candidate.angles);
}

async function collectAutoPathTeachingCandidates(
    robot,
    startAngles,
    targetAngles,
    startPose,
    routeTargetPose,
    targetPose,
    collisionModels,
    bounds,
    holdOrientation,
    shouldCancel,
    report,
    deadline = Infinity,
    hintStates = []
) {
    const candidates = [];
    const add = (angles, source) => {
        if (candidates.length >= 96) return false;
        return addAutoPathTransitionCandidate(candidates, angles, bounds, source);
    };
    // Points already taught between the selected endpoints are deliberate
    // user guidance.  Keep them at the front of the candidate list so the
    // candidate cap cannot discard a four-corner escape route in favour of
    // synthetic IK seeds.
    hintStates.forEach((angles) => add(angles, 'user hint'));
    const targetCandidates = performance.now() < deadline
        ? solveAutoPathGoalCandidates(robot, targetPose, startAngles, { maxSeeds: 10 })
        : [];
    targetCandidates.slice(0, 6).forEach((candidate) => add(candidate.angles, 'target configuration'));

    const seedStates = buildAutoPathTeachingSeeds(startAngles, targetAngles, bounds);
    targetCandidates.slice(0, 3).forEach((candidate) => {
        if (!seedStates.some((seed) => autoPathJointDistance(seed, candidate.angles, bounds) < 0.008)) {
            seedStates.push(candidate.angles.slice());
        }
    });
    const stagePoses = buildAutoPathTeachingStagePoses(
        robot,
        startPose,
        { ...routeTargetPose, position: routeTargetPose.position.clone() },
        collisionModels
    );
    for (let index = 0; index < stagePoses.length; index += 1) {
        if (shouldCancel()) throw new Error('경로 계산을 취소했습니다.');
        if (performance.now() >= deadline) break;
        const stagePose = stagePoses[index];
        stagePose.quaternion.copy(routeTargetPose.quaternion);
        const solved = solveAutoPathStageCandidates(robot, stagePose, seedStates, bounds);
        solved.forEach((angles) => {
            if (add(angles, 'clearance stage')) {
                seedStates.unshift(angles.slice());
            }
        });
        if (typeof report === 'function') report(index + 1, stagePoses.length);
        if (index % 2 === 1) await new Promise((resolve) => requestAnimationFrame(resolve));
    }

    // A released-orientation route may also use compact arm postures.  With
    // TCP hold enabled, every generated transition is instead solved by IK at
    // the saved TCP orientation above.
    if (!holdOrientation && bounds.length >= 6) {
        const yawValues = [startAngles[0], targetAngles[0], 0, -90, 90];
        const compactPostures = [
            [-110, 115, 0, 0, 0],
            [-85, 90, 0, 0, 0],
            [-55, 130, 0, 0, 0],
            [-105, 55, 0, 0, 0],
            [-40, 100, 0, 0, 0]
        ];
        yawValues.forEach((yaw) => compactPostures.forEach((posture) => {
            add(clampAutoPathTransitionState([yaw, ...posture], bounds), 'compact posture');
        }));
    }
    return candidates;
}

function autoPathJointEdgeChecker(evaluator, bounds, isStateSafe = evaluator.isSafe, onBlocked = null) {
    return (from, to) => {
        const distance = Math.sqrt(from.reduce((sum, value, index) => {
            const range = Math.max(1e-6, bounds[index].max - bounds[index].min);
            return sum + (((to[index] - value) / range) ** 2);
        }, 0));
        const maximumJointTravel = from.reduce((maximum, value, index) => (
            Math.max(maximum, Math.abs(to[index] - value) / Math.max(1e-6, bounds[index].sampleStep))
        ), 0);
        // Normalized joint distance alone can jump across a thin CAD bar.
        // Keep the original configuration-space density while also limiting
        // each physical joint step so a MOVJ edge cannot tunnel through it.
        const segments = Math.max(1, Math.ceil(Math.max(distance / 0.08, maximumJointTravel)));
        for (let index = 1; index <= segments; index += 1) {
            const alpha = index / segments;
            const sample = from.map((value, jointIndex) => value + (to[jointIndex] - value) * alpha);
            if (!isStateSafe(sample)) {
                if (typeof onBlocked === 'function') {
                    onBlocked({
                        blockedAngles: sample.slice()
                    });
                }
                return false;
            }
        }
        return true;
    };
}

async function solveAutoPathLinear(
    robot,
    startAngles,
    startPose,
    targetPose,
    evaluator,
    shouldCancel,
    report,
    {
        deadline = Infinity,
        isStateSafe = evaluator.isSafe,
        allowUnsafeTarget = false,
        finalAngles = null,
        onBlocked = null
    } = {}
) {
    const distance = startPose.position.distanceTo(targetPose.position);
    const rotation = THREE.MathUtils.radToDeg(startPose.quaternion.angleTo(targetPose.quaternion));
    const samples = Math.max(1, Math.min(240, Math.ceil(Math.max(
        distance / MOTION_MOVL_SAMPLE_DISTANCE,
        rotation / MOTION_MOVL_SAMPLE_ANGLE
    ))));
    const fail = (details = null) => {
        applyPlanningJointAngles(robot, startAngles);
        if (details && typeof onBlocked === 'function') onBlocked(details);
        return null;
    };
    const path = [startAngles.slice()];
    let seed = startAngles.slice();
    for (let sampleIndex = 1; sampleIndex <= samples; sampleIndex += 1) {
        if (shouldCancel()) throw new Error('경로 계산을 취소했습니다.');
        if (performance.now() >= deadline) {
            return fail();
        }
        const alpha = sampleIndex / samples;
        const pose = {
            position: new THREE.Vector3().fromArray(interpolateLinearPosition(
                startPose.position.toArray(), targetPose.position.toArray(), alpha
            )),
            quaternion: new THREE.Quaternion().fromArray(slerpQuaternion(
                startPose.quaternion.toArray(), targetPose.quaternion.toArray(), alpha
            )).normalize()
        };
        if (sampleIndex === samples && Array.isArray(finalAngles)) {
            // The endpoint already has a taught/selected joint solution.  Use
            // that exact branch instead of letting the iterative IK solver
            // jump to a different wrist configuration at the last sample.
            // This is especially important when a held TCP orientation has
            // multiple valid six-axis IK solutions.
            applyPlanningJointAngles(robot, finalAngles);
            seed = finalAngles.slice();
        } else {
            applyPlanningJointAngles(robot, seed);
            const ik = solveRobotIK(robot, pose, {
                positionTolerance: 0.8,
                rotationTolerance: THREE.MathUtils.degToRad(0.5)
            });
            if (!ik.success) return fail();
            seed = robot.userData.joints.map((joint) => joint.angle);
        }
        if (!(allowUnsafeTarget && sampleIndex === samples) && !isStateSafe(seed)) {
            return fail({
                blockedAngles: seed.slice(),
                blockedPose: pose,
                hits: typeof evaluator.getHits === 'function' ? evaluator.getHits(seed) : []
            });
        }
        path.push(seed.slice());
        if (typeof report === 'function') report(sampleIndex, samples);
        if (sampleIndex % 12 === 0) await new Promise((resolve) => requestAnimationFrame(resolve));
    }
    applyPlanningJointAngles(robot, startAngles);
    return path;
}

function autoPathBoxInRobotBase(robot, object) {
    if (!robot || !object) return null;
    const worldBounds = new THREE.Box3().setFromObject(object);
    if (worldBounds.isEmpty()) return null;
    const inverseRobotMatrix = robot.matrixWorld.clone().invert();
    const bounds = new THREE.Box3();
    for (const x of [worldBounds.min.x, worldBounds.max.x]) {
        for (const y of [worldBounds.min.y, worldBounds.max.y]) {
            for (const z of [worldBounds.min.z, worldBounds.max.z]) {
                bounds.expandByPoint(new THREE.Vector3(x, y, z).applyMatrix4(inverseRobotMatrix));
            }
        }
    }
    return bounds.isEmpty() ? null : bounds;
}

function getAutoPathCollisionObstacleBounds(robot, collisionModels, hits) {
    const attachedModels = collisionModels.filter((model) => model.userData?.attachmentHost === robot);
    const isRobotObject = (object) => object === robot
        || robot.getObjectById?.(object?.id) === object
        || attachedModels.some((model) => model === object || model.getObjectById?.(object?.id) === object);
    const obstacleObjects = [];
    asCollisionResults(hits).forEach((hit) => {
        [hit.meshA, hit.meshB].forEach((mesh) => {
            if (!mesh || isRobotObject(mesh)) return;
            if (!obstacleObjects.includes(mesh)) obstacleObjects.push(mesh);
        });
    });

    const candidates = obstacleObjects.length
        ? obstacleObjects
        : collisionModels.filter((model) => (
            model !== robot && model.userData?.attachmentHost !== robot
        ));
    const bounds = new THREE.Box3();
    candidates.forEach((object) => {
        const objectBounds = autoPathBoxInRobotBase(robot, object);
        if (objectBounds) bounds.union(objectBounds);
    });
    return bounds.isEmpty() ? null : bounds;
}

function buildAutoPathAxisEscapePoses(robot, firstCollision, collisionModels) {
    const blockedPose = firstCollision?.blockedPose
        || (Array.isArray(firstCollision?.blockedAngles)
            ? getAutoPathPointPoseAtJoints(robot, firstCollision.blockedAngles)
            : null);
    if (!blockedPose?.position) return [];

    const obstacleBounds = getAutoPathCollisionObstacleBounds(
        robot,
        collisionModels,
        firstCollision?.hits
    );
    const directions = [
        { axis: 0, sign: 1, label: 'X+' },
        { axis: 0, sign: -1, label: 'X-' },
        { axis: 1, sign: 1, label: 'Y+' },
        { axis: 1, sign: -1, label: 'Y-' },
        { axis: 2, sign: 1, label: 'Z+' },
        { axis: 2, sign: -1, label: 'Z-' }
    ];
    const poses = [];
    directions.forEach(({ axis, sign, label }) => {
        const coordinate = blockedPose.position.getComponent(axis);
        const obstacleExtent = obstacleBounds
            ? Math.max(1, obstacleBounds.max.getComponent(axis) - obstacleBounds.min.getComponent(axis))
            : 160;
        const distanceToOutside = obstacleBounds
            ? sign > 0
                ? Math.max(0, obstacleBounds.max.getComponent(axis) - coordinate)
                : Math.max(0, coordinate - obstacleBounds.min.getComponent(axis))
            : 0;
        const margin = THREE.MathUtils.clamp(obstacleExtent * 0.35, 35, 140);
        const distance = Math.max(80, distanceToOutside + margin);
        const position = blockedPose.position.clone();
        position.setComponent(axis, coordinate + sign * distance);
        poses.push({
            label,
            position,
            quaternion: blockedPose.quaternion.clone()
        });
    });
    return poses;
}

async function solveAutoPathAxisEscapeRoute(
    robot,
    startAngles,
    startPose,
    routeTargetPose,
    targetAngles,
    collisionModels,
    evaluator,
    isStateSafe,
    shouldCancel,
    report,
    deadline,
    firstCollision
) {
    const escapePoses = buildAutoPathAxisEscapePoses(robot, firstCollision, collisionModels);
    for (let index = 0; index < escapePoses.length; index += 1) {
        if (shouldCancel()) throw new Error('경로 계산을 취소했습니다.');
        if (performance.now() >= deadline) return null;
        const escapePose = escapePoses[index];
        const candidates = solveAutoPathGoalCandidates(robot, escapePose, startAngles, { maxSeeds: 18 });
        for (const candidate of candidates) {
            if (shouldCancel()) throw new Error('경로 계산을 취소했습니다.');
            if (performance.now() >= deadline) return null;
            if (!isStateSafe(candidate.angles)) continue;
            applyPlanningJointAngles(robot, candidate.angles);
            const actualEscapePose = getCurrentTcpPoseBase(robot);
            if (!actualEscapePose) continue;
            const firstSegment = await solveAutoPathLinear(
                robot,
                startAngles,
                startPose,
                actualEscapePose,
                evaluator,
                shouldCancel,
                undefined,
                {
                    deadline,
                    isStateSafe,
                    finalAngles: candidate.angles
                }
            );
            if (!firstSegment) continue;
            const secondSegment = await solveAutoPathLinear(
                robot,
                candidate.angles,
                actualEscapePose,
                routeTargetPose,
                evaluator,
                shouldCancel,
                undefined,
                {
                    deadline,
                    isStateSafe,
                    allowUnsafeTarget: true,
                    finalAngles: targetAngles
                }
            );
            if (!secondSegment) continue;
            applyPlanningJointAngles(robot, startAngles);
            return {
                path: [startAngles.slice(), candidate.angles.slice(), targetAngles.slice()],
                motion: 'MOVL',
                direction: escapePose.label
            };
        }
        if (typeof report === 'function') report(index + 1, escapePoses.length);
    }
    applyPlanningJointAngles(robot, startAngles);
    return null;
}

function buildAutoPathCartesianWaypointPoses(robot, startPose, targetPose, collisionModels) {
    const obstacleTop = getAutoPathObstacleTopInBase(robot, collisionModels);
    const start = startPose.position;
    const target = targetPose.position;
    const span = Math.max(
        Math.abs(target.x - start.x),
        Math.abs(target.y - start.y),
        1
    );
    const padding = THREE.MathUtils.clamp(span * 0.08, 35, 180);
    const clearanceZ = Math.max(
        start.z + 40,
        target.z + 40,
        Number.isFinite(obstacleTop) ? obstacleTop + 70 : -Infinity,
        420
    );
    const zLevels = [...new Set([
        start.z,
        target.z,
        Math.max(start.z, target.z) + 40,
        clearanceZ
    ].map((value) => Number(value.toFixed(3))))];
    const minX = Math.min(start.x, target.x) - padding;
    const maxX = Math.max(start.x, target.x) + padding;
    const minY = Math.min(start.y, target.y) - padding;
    const maxY = Math.max(start.y, target.y) + padding;
    const midpoint = start.clone().add(target).multiplyScalar(0.5);
    const route = target.clone().sub(start).setZ(0);
    const normal = route.lengthSq() > 1e-6
        ? new THREE.Vector3(-route.y, route.x, 0).normalize()
        : new THREE.Vector3(1, 0, 0);
    const positions = [];
    const add = (x, y, z) => {
        const position = new THREE.Vector3(x, y, z);
        if (!position.toArray().every(Number.isFinite)) return;
        if (positions.some((candidate) => candidate.distanceToSquared(position) < 4)) return;
        positions.push(position);
    };
    const addAxisCorners = (z) => {
        // Prefer the user's natural teaching order: X first, then Y.  The
        // other L order is retained because a fixture may block one corner.
        add(target.x, start.y, z);
        add(start.x, target.y, z);
    };
    zLevels.forEach(addAxisCorners);
    [
        [minX, start.y], [maxX, start.y], [minX, target.y], [maxX, target.y],
        [start.x, minY], [start.x, maxY], [target.x, minY], [target.x, maxY]
    ].forEach(([x, y]) => zLevels.forEach((z) => add(x, y, z)));
    [padding, -padding, padding * 2, -padding * 2].forEach((offset) => {
        zLevels.forEach((z) => add(
            midpoint.x + normal.x * offset,
            midpoint.y + normal.y * offset,
            z
        ));
    });
    return positions.slice(0, 48).map((position) => ({
        position,
        quaternion: targetPose.quaternion.clone()
    }));
}

async function solveAutoPathCartesianWaypointRoute(
    robot,
    startAngles,
    targetAngles,
    startPose,
    routeTargetPose,
    collisionModels,
    evaluator,
    edgeIsSafe,
    isStateSafe,
    shouldCancel,
    report,
    deadline,
    holdOrientation
) {
    const bounds = autoPathJointBounds(robot);
    const waypointPoses = buildAutoPathCartesianWaypointPoses(
        robot,
        startPose,
        routeTargetPose,
        collisionModels
    );
    for (let index = 0; index < waypointPoses.length; index += 1) {
        if (shouldCancel()) throw new Error('경로 계산을 취소했습니다.');
        if (performance.now() >= deadline) return null;
        const waypointPose = waypointPoses[index];
        const seedGroups = [startAngles, targetAngles];
        const waypointCandidates = [];
        const addCandidate = (candidate) => {
            if (!candidate?.angles || waypointCandidates.some((existing) => (
                autoPathJointDistance(existing.angles, candidate.angles, bounds) < 0.01
            ))) return;
            waypointCandidates.push(candidate);
        };
        for (const seed of seedGroups) {
            if (performance.now() >= deadline) break;
            solveAutoPathGoalCandidates(robot, waypointPose, seed, { maxSeeds: 14 })
                .forEach(addCandidate);
        }
        for (const candidate of waypointCandidates) {
            if (shouldCancel()) throw new Error('경로 계산을 취소했습니다.');
            if (performance.now() >= deadline) return null;
            const waypointAngles = candidate.angles;
            if (!isStateSafe(waypointAngles)) continue;
            applyPlanningJointAngles(robot, waypointAngles);
            const actualWaypointPose = getCurrentTcpPoseBase(robot);
            if (!actualWaypointPose) continue;
            const firstSegment = await solveAutoPathLinear(
                robot,
                startAngles,
                startPose,
                actualWaypointPose,
                evaluator,
                shouldCancel,
                undefined,
                {
                    deadline,
                    isStateSafe,
                    finalAngles: waypointAngles
                }
            );
            if (!firstSegment) continue;
            const secondSegment = await solveAutoPathLinear(
                robot,
                waypointAngles,
                actualWaypointPose,
                routeTargetPose,
                evaluator,
                shouldCancel,
                undefined,
                {
                    deadline,
                    isStateSafe,
                    allowUnsafeTarget: true,
                    finalAngles: targetAngles
                }
            );
            if (!secondSegment) continue;
            const path = [startAngles.slice(), waypointAngles.slice(), targetAngles.slice()];
            const motion = holdOrientation
                ? 'MOVL'
                : edgeIsSafe(path[0], path[1]) && edgeIsSafe(path[1], path[2])
                    ? 'MOVJ'
                    : 'MOVL';
            applyPlanningJointAngles(robot, startAngles);
            return { path, motion };
        }
        if (typeof report === 'function') report(index + 1, waypointPoses.length);
        if (index % 2 === 1) await new Promise((resolve) => requestAnimationFrame(resolve));
    }
    applyPlanningJointAngles(robot, startAngles);
    return null;
}

function getAutoPathObstacleTopInBase(robot, collisionModels) {
    const inverseRobotMatrix = robot.matrixWorld.clone().invert();
    let top = -Infinity;
    collisionModels
        .filter((model) => (
            model !== robot && model.userData?.attachmentHost !== robot
        ))
        .forEach((model) => {
            const worldBounds = new THREE.Box3().setFromObject(model);
            if (worldBounds.isEmpty()) return;
            for (const x of [worldBounds.min.x, worldBounds.max.x]) {
                for (const y of [worldBounds.min.y, worldBounds.max.y]) {
                    for (const z of [worldBounds.min.z, worldBounds.max.z]) {
                        top = Math.max(top, new THREE.Vector3(x, y, z).applyMatrix4(inverseRobotMatrix).z);
                    }
                }
            }
        });
    return Number.isFinite(top) ? top : null;
}

async function solveAutoPathClearanceRoute(
    robot,
    startAngles,
    startPose,
    targetPose,
    collisionModels,
    evaluator,
    shouldCancel,
    report,
    deadline = Infinity,
    isStateSafe = evaluator.isSafe
) {
    const obstacleTop = getAutoPathObstacleTopInBase(robot, collisionModels);
    if (!Number.isFinite(obstacleTop)) return null;
    const minimumClearance = Math.max(startPose.position.z, targetPose.position.z) + 25;
    const clearanceHeights = [...new Set([
        minimumClearance,
        obstacleTop + 20,
        obstacleTop + 40,
        obstacleTop + 80,
        obstacleTop + 160
    ].map((height) => Math.max(minimumClearance, height)).map((height) => Number(height.toFixed(3))))]
        .sort((left, right) => left - right);
    for (const clearanceZ of clearanceHeights) {
        if (shouldCancel()) throw new Error('경로 계산을 취소했습니다.');
        if (performance.now() >= deadline) return null;
        const liftStart = {
            position: new THREE.Vector3(startPose.position.x, startPose.position.y, clearanceZ),
            quaternion: startPose.quaternion.clone()
        };
        const liftTarget = {
            position: new THREE.Vector3(targetPose.position.x, targetPose.position.y, clearanceZ),
            quaternion: targetPose.quaternion.clone()
        };
        const segments = [
            [startAngles, startPose, liftStart],
            [null, liftStart, liftTarget],
            [null, liftTarget, targetPose]
        ];
        let currentAngles = startAngles.slice();
        const path = [currentAngles.slice()];
        let routeIsSafe = true;
        for (const [segmentStartAngles, segmentStartPose, segmentTargetPose] of segments) {
            const segment = await solveAutoPathLinear(
                robot,
                segmentStartAngles || currentAngles,
                segmentStartPose,
                segmentTargetPose,
                evaluator,
                shouldCancel,
                report,
                {
                    deadline,
                    isStateSafe,
                    allowUnsafeTarget: segmentTargetPose === targetPose
                }
            );
            if (!segment) {
                routeIsSafe = false;
                break;
            }
            path.push(...segment.slice(1));
            currentAngles = segment.at(-1)?.slice() || currentAngles;
        }
        applyPlanningJointAngles(robot, startAngles);
        if (routeIsSafe && path.length > 1) return path;
    }
    return null;
}

function buildAutoPathPreview(robot, path, originalAngles) {
    clearAutoPathPreview();
    if (!state.scene || !path?.length) return;
    const points = [];
    path.forEach((angles) => {
        applyPlanningJointAngles(robot, angles);
        const pose = getCurrentTcpPoseBase(robot);
        if (pose) points.push(pose.position.clone().applyMatrix4(robot.matrixWorld));
    });
    applyPlanningJointAngles(robot, originalAngles);
    if (points.length < 2) return;
    const group = new THREE.Group();
    group.name = 'Auto Path Preview';
    group.renderOrder = 20;
    const line = new THREE.Line(
        new THREE.BufferGeometry().setFromPoints(points),
        new THREE.LineBasicMaterial({ color: 0xfacc15, transparent: true, opacity: 0.95, depthTest: false })
    );
    line.renderOrder = 20;
    group.add(line);
    const radius = Math.max(1.5, points.reduce((max, point, index) => (
        index ? Math.max(max, point.distanceTo(points[index - 1])) : max
    ), 0) * 0.035);
    points.forEach((point, index) => {
        const marker = new THREE.Mesh(
            new THREE.SphereGeometry(radius * (index === 0 || index === points.length - 1 ? 1.45 : 0.8), 12, 8),
            new THREE.MeshBasicMaterial({
                color: index === 0 ? 0x4ade80 : index === points.length - 1 ? 0xf87171 : 0xfacc15,
                transparent: true,
                opacity: 0.9,
                depthTest: false
            })
        );
        marker.position.copy(point);
        marker.renderOrder = 21;
        group.add(marker);
    });
    state.scene.add(group);
    state.autoPath.previewGroup = group;
    requestRender();
}

function appendAutoPathTarget(path, targetAngles, bounds) {
    if (!Array.isArray(path) || !path.length) return [targetAngles.slice()];
    const last = path.at(-1);
    if (Array.isArray(last)
        && autoPathJointDistance(last, targetAngles, bounds) < 0.01) {
        return [...path.slice(0, -1), targetAngles.slice()];
    }
    return [...path, targetAngles.slice()];
}

async function verifyAutoPathTargetApproach(
    robot,
    path,
    targetMotion,
    targetAngles,
    targetPose,
    evaluator,
    bounds,
    edgeIsSafe,
    shouldCancel,
    isStateSafe = evaluator.isSafe
) {
    const approachStart = path.length > 1 ? path[path.length - 2] : path[0];
    if (!Array.isArray(approachStart)) return false;
    if (targetMotion !== 'MOVL') return edgeIsSafe(approachStart, targetAngles);
    for (let index = 1; index < path.length; index += 1) {
        const segmentStart = path[index - 1];
        const segmentTarget = path[index];
        applyPlanningJointAngles(robot, segmentStart);
        const segmentStartPose = getCurrentTcpPoseBase(robot);
        if (!segmentStartPose) return false;
        let segmentTargetPose = targetPose;
        if (index < path.length - 1) {
            applyPlanningJointAngles(robot, segmentTarget);
            segmentTargetPose = getCurrentTcpPoseBase(robot);
            if (!segmentTargetPose) return false;
        }
        const solvedSegment = await solveAutoPathLinear(
            robot,
            segmentStart,
            segmentStartPose,
            segmentTargetPose,
            evaluator,
            shouldCancel,
            undefined,
            {
                isStateSafe,
                allowUnsafeTarget: index === path.length - 1,
                finalAngles: segmentTarget
            }
        );
        if (!solvedSegment?.length) return false;
        const solvedEnd = solvedSegment.at(-1);
        if (autoPathJointDistance(solvedEnd, segmentTarget, bounds) >= 0.08) return false;
    }
    return true;
}

async function generateAutoPath() {
    if (!state.autoPath.active || state.autoPath.planning || isMotionActive()) return;
    const robot = state.autoPath.robot || getAutoPathRobot();
    if (!robot?.userData?.joints?.length || !robot.userData.tcpFrame) {
        setAutoPathStatus('활성 로봇의 관절과 TCP를 확인하세요.', 'error');
        return;
    }
    const settings = readAutoPathSettings();
    const originalAngles = robot.userData.joints.map((joint) => joint.angle);
    state.autoPath.planning = true;
    state.autoPath.cancelRequested = false;
    state.autoPath.robot = robot;
    state.autoPath.startAngles = originalAngles.slice();
        state.autoPath.settings = settings;
        state.autoPath.path = null;
        state.autoPath.generatedPointCount = 0;
        state.autoPath.targetConfigurationChangeRequired = false;
        state.autoPath.endpointTcpSyncRequired = false;
        clearAutoPathPreview();
    el.btnAutoPathGenerate.disabled = true;
    el.btnAutoPathApply.disabled = true;
    updateMotionUiLock();
    setAutoPathStatus('목표 위치 분석 중', 'working');
    try {
        const program = ensureMotionProgram(robot);
        const pointSteps = getAutoPathPointSteps(robot);
        const startStep = pointSteps.find((step) => step.id === state.autoPath.startStepId);
        const targetStep = pointSteps.find((step) => step.id === state.autoPath.targetStepId);
        if (pointSteps.length < 2) throw new Error('자동 경로 생성에는 이동 포인트 2개가 필요합니다.');
        if (!startStep || !targetStep) throw new Error('시작 위치와 목표 위치를 선택하세요.');
        if (startStep.id === targetStep.id) throw new Error('시작 위치와 목표 위치는 서로 다른 이동 포인트여야 합니다.');
        const startIndex = program.steps.findIndex((step) => step.id === startStep.id);
        const targetIndex = program.steps.findIndex((step) => step.id === targetStep.id);
        if (startIndex < 0 || targetIndex < 0 || targetIndex <= startIndex) {
            throw new Error('시작 포인트는 목표 포인트보다 프로그램 앞에 있어야 합니다.');
        }
        if (!Array.isArray(startStep.joints) || startStep.joints.length !== robot.userData.joints.length) {
            throw new Error('선택한 시작 포인트의 관절 데이터를 읽을 수 없습니다.');
        }
        const startAngles = startStep.joints.map((angle) => Number(angle));
        if (startAngles.some((angle) => !Number.isFinite(angle))) {
            throw new Error('선택한 시작 포인트의 관절 데이터를 읽을 수 없습니다.');
        }
        if (!Array.isArray(targetStep.joints) || targetStep.joints.length !== robot.userData.joints.length) {
            throw new Error('선택한 목표 포인트의 관절 데이터를 읽을 수 없습니다.');
        }
        const targetAngles = targetStep.joints.map((angle) => Number(angle));
        if (targetAngles.some((angle) => !Number.isFinite(angle))) {
            throw new Error('선택한 목표 포인트의 관절 데이터를 읽을 수 없습니다.');
        }
        const jointBounds = autoPathJointBounds(robot);
        const isWithinJointBounds = (angles) => angles.every((angle, index) => (
            angle >= jointBounds[index].min && angle <= jointBounds[index].max
        ));
        if (!isWithinJointBounds(startAngles)) throw new Error('선택한 시작 포인트의 관절 제한을 벗어났습니다.');
        if (!isWithinJointBounds(targetAngles)) throw new Error('선택한 목표 포인트의 관절 제한을 벗어났습니다.');
        const userHintStates = program.steps
            .slice(startIndex + 1, targetIndex)
            .filter((step) => isMotionPointMotion(step.motion))
            .map((step) => Array.isArray(step.joints) && step.joints.length === robot.userData.joints.length
                ? step.joints.map((angle) => Number(angle))
                : null)
            .filter((angles) => angles?.every((angle, index) => Number.isFinite(angle)
                && angle >= jointBounds[index].min
                && angle <= jointBounds[index].max));
        const startEndpoint = resolveAutoPathPointPose(robot, startStep, startAngles);
        const targetEndpoint = resolveAutoPathPointPose(robot, targetStep, targetAngles);
        const startPose = startEndpoint.pose;
        const targetPose = targetEndpoint.pose;
        if (!startPose || !targetPose) throw new Error('TCP 자세를 읽을 수 없습니다.');
        const endpointTcpSyncRequired = startEndpoint.needsSync || targetEndpoint.needsSync;
        const routeTargetPose = settings.holdOrientation
            ? {
                position: targetPose.position.clone(),
                quaternion: startPose.quaternion.clone()
            }
            : targetPose;
        const targetOrientationWillChange = settings.holdOrientation
            && THREE.MathUtils.radToDeg(startPose.quaternion.angleTo(targetPose.quaternion)) > 0.35;
        const collisionModels = getCollisionModels();
        if (!collisionModels.includes(robot)) throw new Error('활성 로봇을 충돌 검사 대상으로 준비할 수 없습니다.');
        if (isAutoPathTargetInsideModel(robot, routeTargetPose, collisionModels)) throw new Error('타겟 위치가 3D 모델 내부에 있습니다.');
        const evaluator = createAutoPathCollisionEvaluator(robot, originalAngles);
        let planningTargetAngles = targetAngles.slice();
        if (targetOrientationWillChange) {
            const goalCandidates = solveAutoPathGoalCandidates(
                robot,
                routeTargetPose,
                targetAngles
            );
            const collisionFreeCandidate = goalCandidates.find((candidate) => evaluator.isSafe(candidate.angles));
            const selectedCandidate = collisionFreeCandidate || goalCandidates[0];
            if (!selectedCandidate) {
                throw new Error('TCP 자세를 유지한 목표 위치의 안전한 관절 자세를 찾지 못했습니다.');
            }
            // Endpoint collision is allowed below. Prefer a collision-free
            // configuration when one exists, but do not reject an otherwise
            // valid taught target solely because the tool is touching it.
            planningTargetAngles = selectedCandidate.angles.slice();
        }
        const isAutoPathEndpoint = (angles) => (
            autoPathJointDistance(angles, startAngles, jointBounds) < 0.0001
            || autoPathJointDistance(angles, planningTargetAngles, jointBounds) < 0.0001
        );
        const isPathStateSafe = (angles) => isAutoPathEndpoint(angles) || evaluator.isSafe(angles);
        const planningDeadline = performance.now() + settings.maxTimeMs;
        setAutoPathStatus('직선 경로 검사 중', 'working');
        let firstCollision = null;
        const rememberFirstCollision = (details) => {
            if (firstCollision || !details?.blockedAngles) return;
            firstCollision = {
                ...details,
                blockedPose: details.blockedPose
                    || getAutoPathPointPoseAtJoints(robot, details.blockedAngles),
                hits: details.hits
                    || (typeof evaluator.getHits === 'function'
                        ? evaluator.getHits(details.blockedAngles)
                        : [])
            };
        };
        const edgeIsSafe = autoPathJointEdgeChecker(
            evaluator,
            jointBounds,
            isPathStateSafe,
            rememberFirstCollision
        );
        let path = null;
        let motion = 'MOVJ';
        let requiredMotion = null;
        let teachingCandidates = [];
        const linearPath = await solveAutoPathLinear(
            robot,
            startAngles,
            startPose,
            routeTargetPose,
            evaluator,
            () => state.autoPath.cancelRequested,
            (current, total) => setAutoPathStatus('직선 경로 검사 중 ({current}/{total})', 'working', { current, total }),
            {
                deadline: planningDeadline,
                isStateSafe: isPathStateSafe,
                allowUnsafeTarget: true,
                finalAngles: planningTargetAngles,
                onBlocked: rememberFirstCollision
            }
        );
        if (linearPath) {
            // Check the TCP straight line first.  Keep MOVJ only when its
            // joint-space edge is also safe; otherwise the generated command
            // must retain the collision-free Cartesian trajectory.
            path = [startAngles.slice(), linearPath.at(-1)?.slice() || planningTargetAngles.slice()];
            if (!edgeIsSafe(startAngles, planningTargetAngles)) requiredMotion = 'MOVL';
        } else if (!firstCollision && edgeIsSafe(startAngles, planningTargetAngles)) {
            // A straight Cartesian route can fail because an intermediate IK
            // solve is unavailable even though the direct joint route is safe.
            // Preserve that valid direct route as a fallback.
            path = [startAngles.slice(), planningTargetAngles.slice()];
        }
        if (!path && userHintStates.length) {
            setAutoPathStatus('사용자 회피 포인트 검사 중', 'working');
            const hintedRoute = await planJointWaypointGraph({
                start: startAngles,
                goal: planningTargetAngles,
                candidates: userHintStates,
                bounds: jointBounds,
                isStateSafe: isPathStateSafe,
                edgeIsSafe,
                maxCandidates: userHintStates.length,
                neighbors: Math.min(8, Math.max(2, userHintStates.length)),
                maxNeighbors: Math.min(16, Math.max(2, userHintStates.length)),
                maxTimeMs: Math.max(120, Math.min(2500, planningDeadline - performance.now())),
                shouldCancel: () => state.autoPath.cancelRequested,
                onYield: () => new Promise((resolve) => requestAnimationFrame(resolve)),
                yieldEvery: 8
            });
            if (hintedRoute.success) {
                path = await simplifyJointPath(hintedRoute.path, edgeIsSafe, {
                    maxPasses: 4,
                    shouldCancel: () => state.autoPath.cancelRequested
                });
                motion = 'MOVJ';
            }
            if (hintedRoute.reason === 'cancelled') throw new Error('경로 계산을 취소했습니다.');
        }
        if (!path && firstCollision) {
            setAutoPathStatus('최초 간섭점 6방향 탈출 검사 중', 'working');
            const axisEscapeRoute = await solveAutoPathAxisEscapeRoute(
                robot,
                startAngles,
                startPose,
                routeTargetPose,
                planningTargetAngles,
                collisionModels,
                evaluator,
                isPathStateSafe,
                () => state.autoPath.cancelRequested,
                (current, total) => setAutoPathStatus(
                    '최초 간섭점 6방향 탈출 검사 중 ({current}/{total})',
                    'working',
                    { current, total }
                ),
                planningDeadline,
                firstCollision
            );
            if (axisEscapeRoute) {
                path = axisEscapeRoute.path;
                motion = axisEscapeRoute.motion;
                requiredMotion = settings.holdOrientation ? 'MOVL' : requiredMotion;
            }
        }
        if (!path) {
            setAutoPathStatus('Cartesian 전환점 탐색 중', 'working');
            const cartesianRoute = await solveAutoPathCartesianWaypointRoute(
                robot,
                startAngles,
                planningTargetAngles,
                startPose,
                routeTargetPose,
                collisionModels,
                evaluator,
                edgeIsSafe,
                isPathStateSafe,
                () => state.autoPath.cancelRequested,
                (current, total) => setAutoPathStatus(
                    'Cartesian 전환점 탐색 중 ({current}/{total})',
                    'working',
                    { current, total }
                ),
                planningDeadline,
                settings.holdOrientation
            );
            if (cartesianRoute) {
                path = cartesianRoute.path;
                motion = cartesianRoute.motion;
                if (settings.holdOrientation) requiredMotion = 'MOVL';
            }
        }
        if (!path) {
            setAutoPathStatus('안전 전환 자세 탐색 중', 'working');
            teachingCandidates = await collectAutoPathTeachingCandidates(
                robot,
                startAngles,
                planningTargetAngles,
                startPose,
                routeTargetPose,
                routeTargetPose,
                collisionModels,
                jointBounds,
                settings.holdOrientation,
                () => state.autoPath.cancelRequested,
                (current, total) => setAutoPathStatus(
                    '안전 전환 자세 탐색 중 ({current}/{total})',
                    'working',
                    { current, total }
                ),
                performance.now() + Math.max(
                    120,
                    Math.min(1800, (planningDeadline - performance.now()) * 0.32)
                ),
                userHintStates
            );
            const remainingTimeMs = Math.max(1, planningDeadline - performance.now());
            if (teachingCandidates.length && remainingTimeMs > 120) {
                setAutoPathStatus('전환점 연결 검사 중', 'working');
                const transitionRoute = await planJointWaypointGraph({
                    start: startAngles,
                    goal: planningTargetAngles,
                    candidates: teachingCandidates.map((candidate) => candidate.angles),
                    bounds: jointBounds,
                    isStateSafe: isPathStateSafe,
                    edgeIsSafe,
                    maxCandidates: 96,
                    neighbors: 9,
                    maxNeighbors: 20,
                    maxTimeMs: Math.max(120, remainingTimeMs * 0.68),
                    shouldCancel: () => state.autoPath.cancelRequested,
                    onProgress: ({ nodes, checkedEdges }) => setAutoPathStatus(
                        '전환점 연결 검사 중 ({nodes} 자세 · {edges} links)',
                        'working',
                        { nodes, edges: checkedEdges }
                    ),
                    onYield: () => new Promise((resolve) => requestAnimationFrame(resolve)),
                    yieldEvery: 16
                });
                if (transitionRoute.success) {
                    setAutoPathStatus('경로 최적화 중', 'working');
                    path = await simplifyJointPath(transitionRoute.path, edgeIsSafe, {
                        maxPasses: 4,
                        shouldCancel: () => state.autoPath.cancelRequested
                    });
                    motion = 'MOVJ';
                } else if (transitionRoute.reason === 'cancelled') {
                    throw new Error('경로 계산을 취소했습니다.');
                }
            }
        }
        if (!path) {
            setAutoPathStatus('안전 높이 경로 검사 중', 'working');
            path = await solveAutoPathClearanceRoute(
                robot,
                startAngles,
                startPose,
                routeTargetPose,
                collisionModels,
                evaluator,
                () => state.autoPath.cancelRequested,
                (current, total) => setAutoPathStatus('안전 높이 경로 검사 중 ({current}/{total})', 'working', { current, total }),
                planningDeadline,
                isPathStateSafe
            );
            if (path && settings.holdOrientation) requiredMotion = 'MOVL';
        }
        if (!path) {
            setAutoPathStatus('우회 경로 탐색 중', 'working');
            const remainingTimeMs = Math.max(1, planningDeadline - performance.now());
            const planned = await planJointPath({
                start: startAngles,
                goal: planningTargetAngles,
                bounds: jointBounds,
                isStateSafe: isPathStateSafe,
                edgeIsSafe,
                maxNodes: Math.max(2500, settings.maxPoints * 400),
                maxTimeMs: remainingTimeMs,
                goalBias: 0.18,
                stepSize: 0.13,
                random: createSeededRandom(0x1a7e5eed),
                sampleStates: teachingCandidates.map((candidate) => candidate.angles),
                sampleBias: 0.36,
                shouldCancel: () => state.autoPath.cancelRequested,
                onProgress: ({ nodes, elapsedMs }) => setAutoPathStatus(
                    '우회 경로 탐색 중 ({nodes} nodes · {seconds} s)',
                    'working',
                    { nodes, seconds: (elapsedMs / 1000).toFixed(1) }
                ),
                onYield: () => new Promise((resolve) => requestAnimationFrame(resolve)),
                yieldEvery: 40
            });
            if (planned.success) {
                setAutoPathStatus('경로 최적화 중', 'working');
                path = await simplifyJointPath(planned.path, edgeIsSafe, {
                    maxPasses: 4,
                    shouldCancel: () => state.autoPath.cancelRequested
                });
                motion = 'MOVJ';
            }
            if (planned.reason === 'cancelled') throw new Error('경로 계산을 취소했습니다.');
            if (!path) throw new Error('제한 시간 안에 안전한 우회 경로를 찾지 못했습니다.');
        }
        if (state.autoPath.cancelRequested) throw new Error('경로 계산을 취소했습니다.');
        path = appendAutoPathTarget(path, planningTargetAngles, jointBounds);
        const generatedPointCount = Math.max(0, path.length - 2);
        if (generatedPointCount > settings.maxPoints) throw new Error(`생성 포인트가 최대 포인트 수(${settings.maxPoints})를 초과합니다.`);
        setAutoPathStatus('최종 간섭 검사 중', 'working');
        const movjPathIsSafe = path.every((angles, index) => (
            index === 0 || edgeIsSafe(path[index - 1], angles)
        ));
        motion = requiredMotion || (movjPathIsSafe ? 'MOVJ' : 'MOVL');
        for (let index = 0; index < path.length; index += 1) {
            if (state.autoPath.cancelRequested || !isPathStateSafe(path[index])) throw new Error('최종 경로 간섭 검사에 실패했습니다.');
            if (index > 0 && motion === 'MOVJ' && !edgeIsSafe(path[index - 1], path[index])) {
                throw new Error('최종 경로 간섭 검사에 실패했습니다.');
            }
        }
        if (!(await verifyAutoPathTargetApproach(
            robot,
            path,
            motion,
            planningTargetAngles,
            routeTargetPose,
            evaluator,
            jointBounds,
            edgeIsSafe,
            () => state.autoPath.cancelRequested,
            isPathStateSafe
        ))) {
            throw new Error('목표 포인트로 이어지는 최종 접근 경로가 안전하지 않습니다.');
        }
        applyPlanningJointAngles(robot, originalAngles);
        state.autoPath.targetPose = routeTargetPose;
        state.autoPath.path = path;
        state.autoPath.generatedPointCount = generatedPointCount;
        state.autoPath.motion = motion;
        state.autoPath.motionChangeRequired = targetStep.motion !== motion;
        state.autoPath.targetConfigurationChangeRequired = targetOrientationWillChange;
        state.autoPath.endpointTcpSyncRequired = endpointTcpSyncRequired;
        buildAutoPathPreview(robot, path, originalAngles);
        setAutoPathStatus(endpointTcpSyncRequired
            ? '현재 TCP 기준으로 포인트를 보정했습니다. 경로 적용을 누르세요.'
            : targetOrientationWillChange
            ? generatedPointCount > 0
                ? '경로 생성 완료 · {count}개 우회 포인트 ({motion}) · TCP 자세 유지'
                : 'TCP 자세 유지에 맞춰 목표 포인트를 갱신합니다. 경로 적용을 누르세요.'
            : generatedPointCount > 0
                ? '경로 생성 완료 · {count}개 우회 포인트 ({motion})'
                : state.autoPath.motionChangeRequired
                    ? '충돌 검사 결과 {motion} 경로로 결정되었습니다. 경로 적용을 눌러 목표 명령을 변경하세요.'
                    : '두 포인트 사이에 추가할 우회 포인트가 없습니다.',
        'success', {
            count: generatedPointCount,
            motion
        });
    } catch (error) {
        applyPlanningJointAngles(robot, originalAngles);
        state.autoPath.path = null;
        state.autoPath.generatedPointCount = 0;
        state.autoPath.motionChangeRequired = false;
        state.autoPath.targetConfigurationChangeRequired = false;
        state.autoPath.endpointTcpSyncRequired = false;
        if (error?.message !== '경로 계산을 취소했습니다.') console.warn('Automatic path planning failed:', error);
        setAutoPathStatus(error?.message || '자동 경로 생성에 실패했습니다.', 'error');
    } finally {
        state.autoPath.planning = false;
        el.btnAutoPathGenerate.disabled = false;
        el.btnAutoPathApply.disabled = !state.autoPath.path
            || (state.autoPath.generatedPointCount <= 0
                && !state.autoPath.motionChangeRequired
                && !state.autoPath.targetConfigurationChangeRequired
                && !state.autoPath.endpointTcpSyncRequired);
        updateMotionUiLock();
        refreshAutoPathUi();
    }
}

function applyAutoPath() {
    const {
        robot,
        path,
        settings,
        motion,
        startAngles,
        startStepId,
        targetStepId,
        targetConfigurationChangeRequired,
        endpointTcpSyncRequired
    } = state.autoPath;
    if (!robot || !Array.isArray(path) || path.length < 2 || !settings || isMotionActive()) return;
    const program = ensureMotionProgram(robot);
    if (!program) return;
    const startIndex = program.steps.findIndex((step) => step.id === startStepId);
    const targetIndex = program.steps.findIndex((step) => step.id === targetStepId);
    if (startIndex < 0 || targetIndex <= startIndex) {
        setAutoPathStatus('시작 포인트와 목표 포인트를 다시 선택하세요.', 'error');
        return;
    }
    const targetStep = program.steps.find((step) => step.id === targetStepId);
    const startStep = program.steps.find((step) => step.id === startStepId);
    if (!startStep || !isMotionPointMotion(startStep.motion)) {
        setAutoPathStatus('시작 이동 포인트를 다시 선택하세요.', 'error');
        return;
    }
    if (!targetStep || !isMotionPointMotion(targetStep.motion)) {
        setAutoPathStatus('목표 이동 포인트를 다시 선택하세요.', 'error');
        return;
    }
    const hintStepIds = new Set(program.steps
        .slice(startIndex + 1, targetIndex)
        .filter((step) => isMotionPointMotion(step.motion))
        .map((step) => step.id));
    const before = captureSceneSnapshot();
    const used = new Set((program.steps || []).map((step) => Number(step.pointIndex)).filter(Number.isInteger));
    const externalAxes = Array.isArray(targetStep.externalAxes) && targetStep.externalAxes.length === 6
        ? [...targetStep.externalAxes]
        : [0, 0, 0, 0, 0, 0];
    const steps = [];
    try {
        for (let index = 1; index < path.length - 1; index += 1) {
            let pointIndex = null;
            for (let candidate = MIN_POINT_INDEX; candidate <= MAX_POINT_INDEX; candidate += 1) {
                if (!used.has(candidate)) {
                    pointIndex = candidate;
                    used.add(candidate);
                    break;
                }
            }
            if (pointIndex === null) throw new Error('사용 가능한 포인트 번호가 없습니다.');
            applyPlanningJointAngles(robot, path[index]);
            const step = captureRobotMotionStep(robot, {
                motion,
                speed: Math.min(settings.speed, motion === 'MOVL'
                    ? robot.userData.manifest?.cartesianMotion?.maxSpeed || settings.speed
                    : 100),
                pointIndex,
                label: 'Auto Path',
                externalAxes
            });
            if (!step) throw new Error('자동 경로 포인트를 생성하지 못했습니다.');
            steps.push(step);
        }
        const motionChanged = targetStep.motion !== motion;
        const targetConfigurationChanged = Boolean(targetConfigurationChangeRequired);
        const endpointTcpSyncChanged = Boolean(endpointTcpSyncRequired);
        if (!steps.length && !motionChanged && !targetConfigurationChanged && !endpointTcpSyncChanged && !hintStepIds.size) {
            setAutoPathStatus('두 포인트 사이에 추가할 우회 포인트가 없습니다.', 'success');
            return;
        }
        const syncMotionPointTcp = (motionStep, angles, stepMotion = motionStep.motion) => {
            if (!Array.isArray(angles) || angles.length !== robot.userData.joints.length) {
                throw new Error('현재 TCP 기준의 포인트 자세를 준비하지 못했습니다.');
            }
            applyPlanningJointAngles(robot, angles);
            const replacement = captureRobotMotionStep(robot, { ...motionStep, motion: stepMotion });
            if (!replacement) throw new Error('현재 TCP 기준의 포인트를 저장하지 못했습니다.');
            Object.assign(motionStep, replacement);
        };
        if (endpointTcpSyncChanged) {
            syncMotionPointTcp(startStep, startAngles);
        }
        if (targetConfigurationChanged || endpointTcpSyncChanged) {
            const plannedTargetAngles = path.at(-1);
            syncMotionPointTcp(targetStep, plannedTargetAngles, motion);
        }
        if (motionChanged) {
            targetStep.motion = motion;
            const currentSpeed = Number(targetStep.speed);
            const motionMaxSpeed = motion === 'MOVL'
                ? Number(robot.userData.manifest?.cartesianMotion?.maxSpeed) || settings.speed
                : 100;
            targetStep.speed = Math.min(
                Number.isFinite(currentSpeed) ? currentSpeed : settings.speed,
                motionMaxSpeed
            );
        }
        if (hintStepIds.size) {
            // The intermediate points are teaching hints, not a second route
            // to keep executing after the optimized path is inserted. Remove
            // only those motion points so delays/timers/gripper commands in
            // the selected program span remain intact.
            for (let index = program.steps.length - 1; index > startIndex; index -= 1) {
                if (hintStepIds.has(program.steps[index]?.id)) program.steps.splice(index, 1);
            }
        }
        const updatedTargetIndex = program.steps.findIndex((step) => step.id === targetStepId);
        if (steps.length) program.steps.splice(updatedTargetIndex, 0, ...steps);
        program.selectedStepId = steps.at(-1)?.id || program.selectedStepId;
        applyPlanningJointAngles(robot, startAngles);
        clearAutoPathPreview();
        state.autoPath.path = null;
        recordHistory('자동 경로 생성', before, captureSceneSnapshot());
        renderMotionProgramPanel();
        setMotionProgramStatus(
            steps.length
                ? '자동 경로를 {motion}으로 결정하고 {count}개 우회 포인트를 등록했습니다.'
                : targetConfigurationChanged
                    ? 'TCP 자세를 유지하도록 목표 포인트를 갱신했습니다.'
                    : endpointTcpSyncChanged
                        ? '현재 TCP 기준으로 포인트를 동기화했습니다.'
                        : '자동 경로 모션을 {motion}으로 변경했습니다.',
            '',
            { count: steps.length, motion }
        );
        closeAutoPathPanel({ preserveStatus: true });
    } catch (error) {
        applyPlanningJointAngles(robot, startAngles);
        setAutoPathStatus(error?.message || '자동 경로 포인트 등록에 실패했습니다.', 'error');
    }
}

function programCommandName(step) {
    if (isMotionPointMotion(step.motion)) return formatMotionPointName(step.pointIndex);
    if (step.motion === 'VIEW') return `View ${Math.min(4, Math.max(1, Number(step.viewSlot) + 1 || 1))}`;
    return ({
        DELAY: 'Delay',
        WAIT: 'Wait',
        HOME: 'Home',
        TIME_START: 'Time Start',
        TIME_OUT: 'Time Out',
        GRIP_USE: uiText('물건 잡기'),
        GRIP_RELEASE: uiText('놓기')
    })[step.motion] || step.motion;
}

function getWorkOriginRobot() {
    return state.activeProgramRobot || state.activeArticulatedModel || null;
}

function getRobotWorkOrigin(robot = getWorkOriginRobot()) {
    return robot ? ensureMotionProgram(robot)?.workOrigin || null : null;
}

function isRobotAtWorkOrigin(robot, workOrigin = getRobotWorkOrigin(robot)) {
    if (!robot?.userData?.joints?.length || !workOrigin) return false;
    return robot.userData.joints.every((joint, index) => (
        Math.abs(Number(joint.angle || 0) - Number(workOrigin.joints[index] || 0)) <= 0.05
    ));
}

function getWorkOriginOutputStates() {
    const states = new Map();
    getArticulatedRobots().forEach((robot) => {
        const workOrigin = getRobotWorkOrigin(robot);
        const outputBit = Number(workOrigin?.outputBit);
        if (!workOrigin || !Number.isSafeInteger(outputBit) || outputBit < 0) return;
        const reached = isRobotAtWorkOrigin(robot, workOrigin);
        states.set(outputBit, states.has(outputBit) ? states.get(outputBit) && reached : reached);
    });
    return states;
}

function applyWorkOriginOutputStates() {
    state.workOriginOutputStates = getWorkOriginOutputStates();
    return state.workOriginOutputStates;
}

function syncWorkOriginOutputStates() {
    applyWorkOriginOutputStates();
    renderWorkOriginDialog();
}

function setWorkOriginDialogStatus(message = '', type = '') {
    if (!el.workOriginStatus) return;
    el.workOriginStatus.textContent = message ? uiText(message) : '';
    el.workOriginStatus.classList.toggle('error', type === 'error');
}

function renderWorkOriginDialog() {
    const robot = getWorkOriginRobot();
    const workOrigin = getRobotWorkOrigin(robot);
    if (el.workOriginRobotName) {
        el.workOriginRobotName.textContent = robot
            ? formatRobotPanelName(robot.userData.motionDisplayName)
            : uiText('로봇을 선택하세요');
    }
    if (el.workOriginOutputBit) el.workOriginOutputBit.value = String(workOrigin?.outputBit ?? 519);
    if (el.workOriginSummary) {
        el.workOriginSummary.textContent = workOrigin
            ? uiFormat('등록됨 · Out [{bit}] · {state}', {
                bit: workOrigin.outputBit,
                state: isRobotAtWorkOrigin(robot, workOrigin) ? uiText('ON') : uiText('OFF')
            })
            : uiText('아직 Work Origin이 등록되지 않았습니다.');
    }
    const unavailable = !robot || Boolean(state.olp.enabled) || isMotionActive();
    if (el.btnRegisterWorkOrigin) el.btnRegisterWorkOrigin.disabled = unavailable;
    if (el.btnMoveWorkOrigin) el.btnMoveWorkOrigin.disabled = unavailable || !workOrigin;
}

function openWorkOriginDialog() {
    if (state.olp.enabled) return;
    if (!getWorkOriginRobot()) {
        setMotionProgramStatus('Work Origin을 설정할 로봇을 선택하세요.', 'error');
        return;
    }
    const popupRecord = state.panelWindows.get('work-origin-dialog');
    if (popupRecord && !popupRecord.popup.closed) {
        popupRecord.popup.focus();
        return;
    }
    setWorkOriginDialogStatus('');
    renderWorkOriginDialog();
    el.workOriginDialog?.classList.remove('hidden', 'panel-user-hidden');
    // Work Origin is an editing aid for the simulation, so keep the 3D view
    // and surrounding controls available while the dialog is open.
    if (typeof el.workOriginDialog?.show === 'function') {
        if (!el.workOriginDialog.open) el.workOriginDialog.show();
        constrainWorkOriginDialogToLayoutBounds();
        // Keep the dialog container focused so opening it does not trigger a
        // tooltip for the first header action before the pointer reaches it.
        el.workOriginDialog.focus({ preventScroll: true });
        bringPanelToFront('work-origin-dialog');
    }
    updateWorkOriginButtonUi();
}

function closeWorkOriginDialog() {
    setWorkOriginDialogStatus('');
    if (state.panelWindows.has('work-origin-dialog')) {
        restorePanelFromWindow('work-origin-dialog', true, true);
    }
    if (el.workOriginDialog?.open) el.workOriginDialog.close();
    updatePanelStack();
    updateWorkOriginButtonUi();
}

function createWorkOriginMotionStep(robot) {
    const step = captureRobotMotionStep(robot);
    if (!step) return null;
    step.motion = 'HOME';
    step.name = 'Home';
    delete step.pointIndex;
    delete step.label;
    delete step.armParameters;
    delete step.externalAxes;
    delete step.speed;
    delete step.delaySeconds;
    delete step.viewSlot;
    delete step.gripObjectRef;
    delete step.waitRobotInstanceId;
    delete step.waitLineNumber;
    return step;
}

function registerWorkOrigin() {
    const robot = getWorkOriginRobot();
    if (!robot || isMotionActive() || state.olp.enabled) return;
    const program = ensureMotionProgram(robot);
    const outputBitText = String(el.workOriginOutputBit?.value ?? '').trim();
    const outputBit = Number(outputBitText);
    if (!/^\d+$/.test(outputBitText) || !Number.isSafeInteger(outputBit)) {
        setWorkOriginDialogStatus('출력 비트 번호는 0 이상의 숫자만 입력하세요.', 'error');
        return;
    }
    const before = captureSceneSnapshot();
    const pose = getCurrentTcpPoseBase(robot);
    const previousTcp = program.workOrigin?.tcp;
    program.workOrigin = {
        mode: 'JOINT',
        joints: robot.userData.joints.map((joint) => Number(joint.angle) || 0),
        tcp: {
            position: pose?.position?.toArray?.() || previousTcp?.position || [0, 0, 0],
            quaternion: pose?.quaternion?.toArray?.() || previousTcp?.quaternion || [0, 0, 0, 1]
        },
        outputBit
    };
    syncWorkOriginOutputStates();
    recordHistory('Work Origin 등록', before, captureSceneSnapshot());
    setWorkOriginDialogStatus('현재 위치를 Work Origin으로 등록했습니다.');
    renderWorkOriginDialog();
    renderMotionProgramPanel();
    scheduleMotionProjectSave();
}

function moveRobotToWorkOrigin() {
    const robot = getWorkOriginRobot();
    const workOrigin = getRobotWorkOrigin(robot);
    if (!robot || !workOrigin) {
        setWorkOriginDialogStatus('먼저 Work Origin을 등록하세요.', 'error');
        return;
    }
    if (isMotionActive() || state.olp.enabled) return;
    const step = createWorkOriginMotionStep(robot);
    if (!step) return;
    closeWorkOriginDialog();
    startRobotMotionPlans([{ robot, steps: [step], repeat: false, reverseRepeat: false, controlScope: 'robot' }]);
}

function handleWorkOriginButtonClick() {
    if (state.olp.enabled) {
        void moveOlpToWorkOrigin();
        return;
    }
    const popupRecord = state.panelWindows.get('work-origin-dialog');
    if (el.workOriginDialog?.open || (popupRecord && !popupRecord.popup.closed)) {
        closeWorkOriginDialog();
        return;
    }
    openWorkOriginDialog();
}

function updateWorkOriginButtonUi() {
    const button = el.btnProgramWorkOriginRobot;
    if (!button) return;
    const robot = getWorkOriginRobot();
    const isOlp = Boolean(state.olp.enabled);
    const visible = isOlp ? Boolean(getOlpProject(robot)) : Boolean(robot);
    const workOrigin = getRobotWorkOrigin(robot);
    const popupRecord = state.panelWindows.get('work-origin-dialog');
    const dialogOpen = Boolean(el.workOriginDialog?.open)
        || Boolean(popupRecord && !popupRecord.popup.closed);
    const disabled = isOlp
        ? !getOlpProject(robot) || isOlpRunning() || Boolean(state.olp.workOriginBusy || state.olp.manualMoveBusy)
            || isVirtualControllerActive()
        : !robot || isMotionActive();
    button.classList.toggle('hidden', !visible);
    button.classList.toggle('active', !isOlp && dialogOpen);
    button.disabled = disabled;
    button.title = uiText(isOlp
        ? (disabled ? 'Work Origin is available when OLP is stopped' : 'Move to Work Origin 0')
        : workOrigin ? 'Work Origin 설정·이동' : 'Work Origin 등록');
    button.setAttribute('aria-label', button.title);
    button.setAttribute('aria-pressed', String(!isOlp && dialogOpen));
}

function getWaitTargetRobot(robot = state.activeProgramRobot) {
    return getArticulatedRobots().find((candidate) => candidate && candidate !== robot) || null;
}

function getWaitTargetRobots(robot = state.activeProgramRobot) {
    return getArticulatedRobots().filter((candidate) => candidate && candidate !== robot);
}

function nextAvailablePointIndex(program, excludedStep = null) {
    const used = new Set((program?.steps || [])
        .filter((step) => step !== excludedStep && isMotionPointMotion(step.motion))
        .map((step) => Number(step.pointIndex))
        .filter((value) => Number.isInteger(value) && value >= MIN_POINT_INDEX && value <= MAX_POINT_INDEX));
    for (let pointIndex = MIN_POINT_INDEX; pointIndex <= MAX_POINT_INDEX; pointIndex += 1) {
        if (!used.has(pointIndex)) return pointIndex;
    }
    return null;
}

function updateCycleTimeReadout(timestamp = performance.now(), force = false) {
    if (!el.programCycleTime) return;
    if (!force && timestamp - state.lastCycleTimeDisplayUpdate < CYCLE_TIME_DISPLAY_INTERVAL) return;
    state.lastCycleTimeDisplayUpdate = timestamp;
    const robot = state.activeProgramRobot;
    const program = robot ? ensureMotionProgram(robot) : null;
    const session = robot ? getMotionSession(robot) : null;
    const timerNow = session?.status === 'paused' && Number.isFinite(session.pauseStarted)
        ? session.pauseStarted
        : timestamp;
    const elapsed = calculateCycleElapsedSeconds(program?.cycleTimerStartedAt, timerNow);
    const measuring = elapsed !== null;
    el.programCycleTime.textContent = measuring
        ? `${elapsed.toFixed(3)} s`
        : Number.isFinite(program?.lastCycleTimeSeconds)
            ? `${program.lastCycleTimeSeconds.toFixed(3)} s`
            : '-- s';
    el.programCycleTime.classList.toggle('measuring', measuring);
    el.programCycleTime.setAttribute('aria-label', uiText(measuring ? '사이클 타임 측정 중' : '사이클 타임'));
}

const PROGRAM_STEP_CONTROL_DATASETS = Object.freeze([
    'programStepPointIndex',
    'programStepLabel',
    'programStepMotion',
    'programStepViewSlot',
    'programStepGripObject',
    'programStepWaitRobot',
    'programStepWaitLine',
    'programStepSpeed'
]);

function captureProgramStepInputFocus() {
    const active = document.activeElement;
    if (!active || !el.programStepList?.contains(active)) return null;
    const row = active.closest('[data-program-step-id]');
    if (!row || !el.programStepList.contains(row)) return null;
    const stepId = row.dataset.programStepId;
    const controlDataset = PROGRAM_STEP_CONTROL_DATASETS.find((key) => active.dataset[key] === stepId);
    if (!controlDataset) return null;
    return {
        stepId,
        controlDataset,
        value: 'value' in active ? active.value : null,
        selectionStart: typeof active.selectionStart === 'number' ? active.selectionStart : null,
        selectionEnd: typeof active.selectionEnd === 'number' ? active.selectionEnd : null,
        selectionDirection: active.selectionDirection || 'none',
        scrollTop: el.programStepList.scrollTop,
        scrollLeft: el.programStepList.scrollLeft
    };
}

function restoreProgramStepInputFocus(focusState) {
    if (!focusState || !el.programStepList) return;
    const row = [...el.programStepList.querySelectorAll('[data-program-step-id]')]
        .find((candidate) => candidate.dataset.programStepId === focusState.stepId);
    if (!row) return;
    const control = [...row.querySelectorAll('[data-program-edit]')]
        .find((candidate) => candidate.dataset[focusState.controlDataset] === focusState.stepId);
    if (!control) return;
    if ('value' in control && focusState.value !== null) control.value = focusState.value;
    control.focus({ preventScroll: true });
    if (focusState.selectionStart !== null && typeof control.setSelectionRange === 'function') {
        try {
            control.setSelectionRange(
                focusState.selectionStart,
                focusState.selectionEnd ?? focusState.selectionStart,
                focusState.selectionDirection
            );
        } catch (_) {
            // Select elements and some number inputs do not expose text selection.
        }
    }
    el.programStepList.scrollTop = focusState.scrollTop;
    el.programStepList.scrollLeft = focusState.scrollLeft;
}

function updateMotionProgramPlaybackUi() {
    if (!el.programStepList) return;

    const robot = state.activeProgramRobot;
    const session = robot ? getMotionSession(robot) : null;
    el.programStepList.querySelectorAll('[data-program-step-id]').forEach((row) => {
        const isRunning = session?.status === 'running'
            && session.currentStepId === row.dataset.programStepId;
        row.classList.toggle('running', isRunning);
    });

    el.programRobotList?.querySelectorAll('[data-robot-instance-id]').forEach((row) => {
        const candidate = findProgramRobot(row.dataset.robotInstanceId);
        if (!candidate) return;
        const candidateSession = getMotionSession(candidate);
        const statusText = row.querySelector('.program-robot-status');
        if (!statusText) return;
        if (state.olp.enabled) {
            const olpStatus = getOlpRobotStatus(candidate);
            statusText.className = `program-robot-status ${olpStatus}`;
            statusText.textContent = olpStatusLabel(olpStatus);
            const projectText = row.querySelector('.program-robot-project');
            if (projectText) {
                const project = getOlpProjectForRobot(candidate);
                projectText.textContent = project?.name || uiText('No project loaded');
                projectText.title = project?.name || uiText('No project loaded');
            }
            return;
        }
        const isInterferenceWaiting = Boolean(candidateSession?.waitingForInterference);
        const status = getMotionStatus(candidate);
        statusText.className = `program-robot-status ${isInterferenceWaiting ? 'interference-waiting' : status}`;
        statusText.textContent = isInterferenceWaiting
            ? uiText('로봇 간섭 회피 대기 중')
            : motionStatusLabel(status);
    });
}

function handleProgramStepListInput(event) {
    const control = event.target.closest('[data-program-edit]');
    if (!control) return;
    const robot = state.activeProgramRobot;
    const program = ensureMotionProgram(robot);
    const stepId = PROGRAM_STEP_CONTROL_DATASETS
        .map((key) => control.dataset[key])
        .find(Boolean);
    const step = program?.steps.find((candidate) => candidate.id === stepId);
    if (!step) return;

    if (control.dataset.programStepSpeed === step.id) {
        const rawValue = control.value.trim();
        if (!rawValue || !Number.isFinite(Number(rawValue))) return;
        const maximum = step.motion === 'MOVJ'
            ? 100
            : step.motion === 'MOVL'
                ? Number(robot?.userData?.manifest?.cartesianMotion?.maxSpeed) || 2500
                : MAX_DELAY_SECONDS;
        const value = step.motion === 'DELAY'
            ? THREE.MathUtils.clamp(Number(rawValue), MIN_DELAY_SECONDS, MAX_DELAY_SECONDS)
            : THREE.MathUtils.clamp(Number(rawValue), 1, maximum);
        if (step.motion === 'DELAY') step.delaySeconds = value;
        else if (step.motion === 'MOVJ' || step.motion === 'MOVL') step.speed = value;
        else return;
        scheduleMotionProjectSave();
        return;
    }

    if (control.dataset.programStepLabel === step.id) {
        const label = control.value.trim();
        if (!label || isValidMotionPointLabel(label)) {
            step.label = label;
            scheduleMotionProjectSave();
        }
        return;
    }

    if (control.dataset.programStepPointIndex === step.id) {
        const pointIndex = Number(control.value);
        const duplicate = program.steps.some((candidate) => candidate !== step
            && isMotionPointMotion(candidate.motion)
            && candidate.pointIndex === pointIndex);
        if (Number.isInteger(pointIndex)
            && pointIndex >= MIN_POINT_INDEX
            && pointIndex <= MAX_POINT_INDEX
            && !duplicate) {
            step.pointIndex = pointIndex;
            step.name = formatMotionPointName(pointIndex);
            scheduleMotionProjectSave();
        }
    }
}

function renderMotionProgramPanel() {
    if (!el.programRobotList || !el.programStepList) return;
    const focusState = captureProgramStepInputFocus();
    const robots = getArticulatedRobots();
    updateRobotInterferenceAvoidanceUi();
    updateTcpPathToggleUi();
    refreshVirtualControllerRobotOptions();
    if (!robots.includes(state.activeProgramRobot)) {
        state.activeProgramRobot = robots.includes(state.activeArticulatedModel)
            ? state.activeArticulatedModel
            : robots[0] || null;
    }
    syncActiveOlpProjectView();
    el.programRobotList.replaceChildren();
    robots.forEach((robot) => {
        const program = ensureMotionProgram(robot);
        const status = state.olp.enabled ? getOlpRobotStatus(robot) : getMotionStatus(robot);
        const session = getMotionSession(robot);
        const isInterferenceWaiting = Boolean(session?.waitingForInterference);
        const row = document.createElement('div');
        row.className = `program-robot-row${robot === state.activeProgramRobot ? ' active' : ''}`;
        row.dataset.robotInstanceId = robot.userData.motionInstanceId;

        const included = document.createElement('input');
        included.type = 'checkbox';
        included.checked = program.included;
        included.dataset.programRobotInclude = robot.userData.motionInstanceId;
        included.setAttribute('aria-label', uiFormat('{name} 동시 실행 대상', {
            name: robot.userData.motionDisplayName
        }));

        const select = document.createElement('button');
        select.type = 'button';
        select.className = 'program-robot-select';
        select.dataset.programRobotSelect = robot.userData.motionInstanceId;
        select.textContent = formatRobotPanelName(robot.userData.motionDisplayName);

        const statusText = document.createElement('span');
        statusText.className = `program-robot-status ${state.olp.enabled
            ? status
            : isInterferenceWaiting ? 'interference-waiting' : status}`;
        statusText.textContent = state.olp.enabled
            ? olpStatusLabel(status)
            : isInterferenceWaiting
                ? uiText('로봇 간섭 회피 대기 중')
                : motionStatusLabel(status);
        if (state.olp.enabled) {
            const projectText = document.createElement('span');
            const project = getOlpProjectForRobot(robot);
            projectText.className = 'program-robot-project';
            projectText.textContent = project?.name || uiText('No project loaded');
            projectText.title = project?.name || uiText('No project loaded');
            row.append(included, select, statusText, projectText);
        } else {
            row.append(included, select, statusText);
        }
        el.programRobotList.appendChild(row);
    });

    const robot = state.activeProgramRobot;
    const program = robot ? ensureMotionProgram(robot) : null;
    if (el.programRobotName) el.programRobotName.textContent = robot
        ? formatRobotPanelName(robot.userData.motionDisplayName)
        : uiText('로봇을 선택하세요');
    updateCycleTimeReadout(performance.now(), true);
    el.programStepList.replaceChildren();
    if (!program || program.steps.length === 0) {
        const empty = document.createElement('p');
        empty.className = 'program-step-empty';
        empty.textContent = uiText(robot
            ? '자세, 뷰, DELAY, WAIT 또는 타이머 명령을 추가하세요.'
            : '프로그램 가능한 로봇이 없습니다.');
        el.programStepList.appendChild(empty);
    } else {
        program.steps.forEach((step, index) => {
            const row = document.createElement('div');
            const isSelected = step.id === program.selectedStepId;
            const session = getMotionSession(robot);
            const isRunning = session?.currentStepId === step.id && session.status === 'running';
            const isTimer = step.motion === 'TIME_START' || step.motion === 'TIME_OUT';
            const isGrip = isGripObjectMotion(step.motion);
            const isWait = isWaitMotion(step.motion);
            const isHome = isHomeMotion(step.motion);
            row.className = `program-step-row${isSelected ? ' active' : ''}${isRunning ? ' running' : ''}${step.motion === 'DELAY' ? ' delay' : ''}${isWait ? ' wait' : ''}${isHome ? ' home' : ''}${isTimer ? ' timer' : ''}${isGrip ? ' grip-object' : ''}`;
            row.tabIndex = 0;
            row.dataset.programStepId = step.id;
            row.dataset.programLineNumber = String(index + 1);
            row.setAttribute('aria-selected', String(isSelected));

            const dragHandle = document.createElement('button');
            dragHandle.type = 'button';
            dragHandle.className = 'program-step-drag-handle';
            dragHandle.draggable = true;
            dragHandle.dataset.programStepDrag = step.id;
            dragHandle.dataset.programEdit = '';
            dragHandle.title = uiText('드래그하여 순서 변경');
            dragHandle.setAttribute('aria-label', `${programCommandName(step)} ${uiText('드래그하여 순서 변경')}`);
            dragHandle.innerHTML = '<i class="fa-solid fa-grip-vertical"></i>';

            const lineNumber = document.createElement('span');
            lineNumber.className = 'program-step-line-number';
            lineNumber.textContent = String(index + 1);
            lineNumber.title = uiFormat('프로그램 행 {number}', { number: index + 1 });
            lineNumber.setAttribute('aria-label', uiFormat('프로그램 행 {number}', { number: index + 1 }));

            let pointControl;
            let labelControl = null;
            if (isMotionPointMotion(step.motion)) {
                pointControl = document.createElement('label');
                pointControl.className = 'program-step-select program-point-index';
                const prefix = document.createElement('span');
                prefix.textContent = 'P[';
                const pointIndexInput = document.createElement('input');
                pointIndexInput.type = 'number';
                pointIndexInput.min = String(MIN_POINT_INDEX);
                pointIndexInput.max = String(MAX_POINT_INDEX);
                pointIndexInput.step = '1';
                pointIndexInput.value = String(step.pointIndex);
                pointIndexInput.dataset.programStepPointIndex = step.id;
                pointIndexInput.dataset.programEdit = '';
                pointIndexInput.title = uiText('포인트 번호');
                pointIndexInput.setAttribute('aria-label', uiText('포인트 번호'));
                const suffix = document.createElement('span');
                suffix.textContent = ']';
                pointControl.append(prefix, pointIndexInput, suffix);

                labelControl = document.createElement('input');
                labelControl.type = 'text';
                labelControl.className = 'program-step-label';
                labelControl.value = step.label || '';
                labelControl.maxLength = MAX_POINT_LABEL_LENGTH;
                labelControl.placeholder = uiText('라벨');
                labelControl.dataset.programStepLabel = step.id;
                labelControl.dataset.programEdit = '';
                labelControl.title = uiText('포인트 라벨');
                labelControl.setAttribute('aria-label', uiText('포인트 라벨'));
            } else {
                pointControl = document.createElement('span');
                pointControl.className = 'program-step-select program-command-name';
                pointControl.textContent = programCommandName(step);
            }

            const motion = document.createElement('select');
            motion.dataset.programStepMotion = step.id;
            motion.dataset.programEdit = '';
            (isGrip
                ? [
                    ['GRIP_USE', uiText('물건 잡기')],
                    ['GRIP_RELEASE', uiText('놓기')]
                ]
                : [
                    ['MOVJ', 'MovJ'],
                    ['MOVL', 'MovL'],
                    ['HOME', 'Home'],
                    ['DELAY', 'Delay'],
                    ['WAIT', 'Wait'],
                    ['TIME_START', 'T.Start'],
                    ['TIME_OUT', 'T.Out'],
                    ['VIEW', 'View'],
                    ['GRIP_USE', uiText('물건 잡기')],
                    ['GRIP_RELEASE', uiText('놓기')]
                ]).forEach(([value, label]) => {
                const option = document.createElement('option');
                option.value = value;
                option.textContent = label;
                motion.appendChild(option);
            });
            motion.value = step.motion;
            motion.title = step.motion.replace('_', ' ');

            const isView = step.motion === 'VIEW';
            const waitTargetRobot = isWait ? document.createElement('select') : null;
            const waitTargetLine = isWait ? document.createElement('input') : null;
            const speed = isView || isGrip || isWait
                ? document.createElement('select')
                : isHome
                    ? document.createElement('span')
                    : document.createElement('input');
            const isDelay = step.motion === 'DELAY';
            speed.className = `program-step-speed${isGrip ? ' program-step-grip-object' : ''}`;
            if (isView) {
                speed.dataset.programStepViewSlot = step.id;
                speed.dataset.programEdit = '';
                for (let slot = 0; slot < VIEW_PRESET_COUNT; slot += 1) {
                    const option = document.createElement('option');
                    option.value = String(slot);
                    option.textContent = `V${slot + 1}`;
                    speed.appendChild(option);
                }
                speed.value = String(Math.min(VIEW_PRESET_COUNT - 1, Math.max(0, Number(step.viewSlot) || 0)));
                speed.title = uiText('전환할 화면 뷰');
                speed.setAttribute('aria-label', uiText('전환할 화면 뷰'));
            } else if (isGrip) {
                speed.dataset.programStepGripObject = step.id;
                speed.dataset.programEdit = '';
                const references = getGripObjectReferences();
                if (!references.length) {
                    const option = document.createElement('option');
                    option.value = '';
                    option.textContent = uiText('오브젝트를 선택하세요');
                    option.disabled = true;
                    option.selected = true;
                    speed.appendChild(option);
                } else {
                    references.forEach((reference) => {
                        const option = document.createElement('option');
                        option.value = reference.value;
                        option.textContent = reference.label;
                        speed.appendChild(option);
                    });
                    if (step.gripObjectRef && !references.some((reference) => reference.value === step.gripObjectRef)) {
                        const option = document.createElement('option');
                        option.value = step.gripObjectRef;
                        option.textContent = uiText('물건 잡기/놓기 명령 대상이 없습니다.');
                        option.disabled = true;
                        speed.appendChild(option);
                    }
                    speed.value = step.gripObjectRef || references[0].value;
                }
                speed.title = uiText('사용할 오브젝트');
                speed.setAttribute('aria-label', uiText('사용할 오브젝트'));
            } else if (isWait) {
                waitTargetRobot.className = 'program-step-wait-robot';
                waitTargetRobot.dataset.programStepWaitRobot = step.id;
                waitTargetRobot.dataset.programEdit = '';
                waitTargetRobot.title = uiText('대기 대상 로봇');
                waitTargetRobot.setAttribute('aria-label', uiText('대기 대상 로봇'));
                const waitTargets = getWaitTargetRobots(robot);
                if (!waitTargets.length) {
                    const option = document.createElement('option');
                    option.value = '';
                    option.textContent = uiText('다른 로봇이 없습니다.');
                    option.disabled = true;
                    option.selected = true;
                    waitTargetRobot.appendChild(option);
                } else {
                    waitTargets.forEach((targetRobot) => {
                        const option = document.createElement('option');
                        option.value = targetRobot.userData.motionInstanceId;
                        option.textContent = formatRobotPanelName(targetRobot.userData.motionDisplayName);
                        waitTargetRobot.appendChild(option);
                    });
                    const selectedTarget = waitTargets.some((targetRobot) => (
                        targetRobot.userData.motionInstanceId === step.waitRobotInstanceId
                    )) ? step.waitRobotInstanceId : waitTargets[0].userData.motionInstanceId;
                    waitTargetRobot.value = selectedTarget;
                }

                const targetRobot = getArticulatedRobots().find((candidate) => (
                    candidate.userData.motionInstanceId === waitTargetRobot.value
                ));
                waitTargetLine.type = 'number';
                waitTargetLine.className = 'program-step-wait-line';
                waitTargetLine.min = String(MIN_WAIT_LINE_NUMBER);
                waitTargetLine.max = String(Math.max(
                    MIN_WAIT_LINE_NUMBER,
                    targetRobot ? ensureMotionProgram(targetRobot).steps.length : MIN_WAIT_LINE_NUMBER
                ));
                waitTargetLine.step = '1';
                waitTargetLine.value = String(Math.max(
                    MIN_WAIT_LINE_NUMBER,
                    Math.min(MAX_WAIT_LINE_NUMBER, Number(step.waitLineNumber) || MIN_WAIT_LINE_NUMBER)
                ));
                waitTargetLine.dataset.programStepWaitLine = step.id;
                waitTargetLine.dataset.programEdit = '';
                waitTargetLine.title = uiText('대기할 프로그램 행');
                waitTargetLine.setAttribute('aria-label', uiText('대기할 프로그램 행'));
            } else if (isHome) {
                speed.className = 'program-step-home-target';
                speed.textContent = uiText('Work Origin');
                speed.title = uiText('등록된 Work Origin으로 이동');
                speed.setAttribute('aria-label', uiText('등록된 Work Origin으로 이동'));
            } else {
                speed.type = 'number';
                speed.disabled = isTimer;
                speed.placeholder = isTimer ? '—' : '';
                speed.min = String(isDelay ? MIN_DELAY_SECONDS : 1);
                speed.max = String(isDelay
                    ? MAX_DELAY_SECONDS
                    : step.motion === 'MOVJ'
                        ? 100
                        : robot.userData.manifest.cartesianMotion.maxSpeed);
                speed.step = isDelay ? '0.1' : '1';
                speed.value = isTimer ? '' : String(isDelay ? step.delaySeconds : step.speed);
                if (!isTimer) speed.dataset.programStepSpeed = step.id;
            }
            speed.dataset.programEdit = '';

            const unit = document.createElement('span');
            unit.className = 'program-step-unit';
            unit.textContent = isTimer || isView || isGrip || isWait || isHome ? '' : isDelay ? 's' : step.motion === 'MOVJ' ? '%' : 'mm/s';
            row.append(dragHandle, lineNumber, pointControl, motion);
            if (isWait) row.append(waitTargetRobot, waitTargetLine);
            else row.append(speed, unit);
            if (labelControl) row.appendChild(labelControl);
            el.programStepList.appendChild(row);
        });
    }
    syncMotionRepeatControl();
    const selected = program?.steps.find((step) => step.id === program.selectedStepId) || null;
    const activeRobotSession = getMotionSession(robot);
    if (el.btnProgramDelete) el.btnProgramDelete.disabled = !selected;
    if (el.btnProgramAddWait) el.btnProgramAddWait.disabled = getWaitTargetRobots(robot).length === 0;
    if (el.btnProgramStepRobot) el.btnProgramStepRobot.disabled = !program?.steps.length
        || Boolean(activeRobotSession)
        || isVirtualControllerActive();
    if (el.btnProgramRunRobot) el.btnProgramRunRobot.disabled = !program?.steps.length
        || (Boolean(activeRobotSession) && activeRobotSession.status !== 'paused')
        || isVirtualControllerActive();
    if (el.btnProgramStepGroup) el.btnProgramStepGroup.disabled = isVirtualControllerActive() || !robots.some((candidate) => {
        const candidateProgram = ensureMotionProgram(candidate);
        return candidateProgram.included && candidateProgram.steps.length && !getMotionSession(candidate);
    });
    if (el.btnProgramRunGroup) el.btnProgramRunGroup.disabled = isVirtualControllerActive() || !robots.some((candidate) => {
        const candidateProgram = ensureMotionProgram(candidate);
        const session = getMotionSession(candidate);
        return candidateProgram.included && candidateProgram.steps.length
            && (!session || session.status === 'paused');
    });
    if (el.btnPositionExport) {
        el.btnPositionExport.disabled = !robot
            || !program?.steps.some((step) => isMotionPointMotion(step.motion));
    }
    updateMotionUiLock();
    updateOlpProgramPanelUi();
    updatePanelLauncher('program-panel');
    if (state.autoPath.active) refreshAutoPathUi();
    restoreProgramStepInputFocus(focusState);
}

function findProgramRobot(instanceId) {
    return getArticulatedRobots().find((robot) => robot.userData.motionInstanceId === instanceId) || null;
}

function handleProgramRobotListClick(event) {
    const button = event.target.closest('[data-program-robot-select]');
    if (!button) return;
    const robot = findProgramRobot(button.dataset.programRobotSelect);
    if (!robot) return;
    flushOlpPendingEdit();
    state.activeProgramRobot = robot;
    syncActiveOlpProjectView();
    syncActiveOlpRuntime();
    if (state.olp.enabled) renderOlpProjectUi();
    // Scene selection remains protected while a robot is moving, but the
    // program panel can still switch the program being edited or controlled.
    if (!isMotionActive()) selectSceneModel(robot);
    else refreshOlpVirtualBusMetadata();
    renderMotionProgramPanel();
}

function handleProgramRobotListChange(event) {
    const checkbox = event.target.closest('[data-program-robot-include]');
    if (!checkbox) return;
    const robot = findProgramRobot(checkbox.dataset.programRobotInclude);
    if (!robot) return;
    const before = captureSceneSnapshot();
    ensureMotionProgram(robot).included = checkbox.checked;
    recordHistory('동시 실행 대상 변경', before, captureSceneSnapshot());
    renderMotionProgramPanel();
}

function handleProgramStepListClick(event) {
    const row = event.target.closest('[data-program-step-id]');
    if (!row || !el.programStepList.contains(row)) return;
    const program = ensureMotionProgram(state.activeProgramRobot);
    if (!program) return;
    program.selectedStepId = row.dataset.programStepId;
    scheduleMotionProjectSave();
    if (event.target.closest('select, input')) {
        el.programStepList.querySelectorAll('[data-program-step-id]').forEach((candidate) => {
            const selected = candidate === row;
            candidate.classList.toggle('active', selected);
            candidate.setAttribute('aria-selected', String(selected));
        });
        if (el.btnProgramDelete) el.btnProgramDelete.disabled = false;
        return;
    }
    renderMotionProgramPanel();
    focusProgramStepRow(program.selectedStepId);
}

function focusProgramStepRow(stepId) {
    if (!stepId || !el.programStepList) return;
    const row = [...el.programStepList.querySelectorAll('[data-program-step-id]')]
        .find((candidate) => candidate.dataset.programStepId === stepId);
    row?.focus({ preventScroll: true });
}

function closeProgramStepContextMenu() {
    state.programContextStepId = null;
    el.programStepContextMenu?.classList.add('hidden');
}

function overwriteContextProgramPoint() {
    const program = state.activeProgramRobot ? ensureMotionProgram(state.activeProgramRobot) : null;
    const step = program?.steps.find((candidate) => candidate.id === state.programContextStepId);
    if (!step || !isMotionPointMotion(step.motion)) {
        closeProgramStepContextMenu();
        return;
    }
    program.selectedStepId = step.id;
    closeProgramStepContextMenu();
    updateSelectedMotionStep();
}

function deleteContextProgramStep() {
    const program = state.activeProgramRobot ? ensureMotionProgram(state.activeProgramRobot) : null;
    const step = program?.steps.find((candidate) => candidate.id === state.programContextStepId);
    if (!program || !step) {
        closeProgramStepContextMenu();
        return;
    }
    program.selectedStepId = step.id;
    closeProgramStepContextMenu();
    deleteSelectedMotionStep();
}

function closeOlpPointContextMenu() {
    state.olp.pointContextTarget = null;
    el.olpPointContextMenu?.classList.add('hidden');
}

function openOlpPointContextMenu(event, record) {
    const menu = el.olpPointContextMenu;
    if (!menu || !record) return;
    closeOlpPointContextMenu();
    state.olp.pointContextTarget = {
        path: record.path,
        index: record.index,
        sourceSymbol: record.sourceSymbol || 'P'
    };
    menu.classList.remove('hidden');
    menu.style.left = '0px';
    menu.style.top = '0px';
    const bounds = menu.getBoundingClientRect();
    menu.style.left = `${Math.max(8, Math.min(event.clientX, window.innerWidth - bounds.width - 8))}px`;
    menu.style.top = `${Math.max(8, Math.min(event.clientY, window.innerHeight - bounds.height - 8))}px`;
}

function handleOlpPointContextMenu(event) {
    if (isOlpRunning() || state.olp.manualMoveBusy || state.olp.workOriginBusy || !getOlpProject()) return;
    const row = event.target.closest('[data-olp-point-row]');
    if (!row) return;
    const pointFile = getOlpSelectedPointFile();
    const record = pointFile?.records?.find((candidate) => candidate.index === Number(row.dataset.olpPointIndex)
        && (candidate.sourceSymbol || 'P').toUpperCase() === String(row.dataset.olpPointSymbol || 'P').toUpperCase());
    if (!record) return;
    event.preventDefault();
    openOlpPointContextMenu(event, record);
}

function handleOlpPointTableActivate(event) {
    if (event.type === 'keydown' && !['Enter', ' '].includes(event.key)) return;
    if (isOlpRunning() || state.olp.manualMoveBusy || state.olp.workOriginBusy || !getOlpProject()) return;
    const row = event.target.closest('[data-olp-point-row]');
    if (!row) return;
    const pointFile = getOlpSelectedPointFile();
    const record = pointFile?.records?.find((candidate) => candidate.index === Number(row.dataset.olpPointIndex)
        && (candidate.sourceSymbol || 'P').toUpperCase() === String(row.dataset.olpPointSymbol || 'P').toUpperCase());
    if (!record) return;
    if (event.type === 'keydown') event.preventDefault();
    const bounds = row.getBoundingClientRect();
    openOlpPointContextMenu({
        clientX: event.clientX || bounds.left + 12,
        clientY: event.clientY || bounds.bottom
    }, record);
}

function getOlpPointContextRecord(target = state.olp.pointContextTarget) {
    const project = getOlpProject();
    if (!target || !project) return null;
    const pointFile = project.pointFiles?.find((file) => file.path === target.path);
    return pointFile?.records?.find((record) => record.index === Number(target.index)
        && (record.sourceSymbol || 'P').toUpperCase() === String(target.sourceSymbol || 'P').toUpperCase()) || null;
}

async function moveOlpPointFromContext() {
    const target = state.olp.pointContextTarget;
    closeOlpPointContextMenu();
    if (!target || !getOlpProject()) return;
    if (isOlpRunning()) {
        setOlpStatus('error', 'Stop OLP before moving to a point.');
        return;
    }
    if (state.olp.manualMoveBusy || state.olp.workOriginBusy) return;
    if (isVirtualControllerActive()) {
        setOlpStatus('error', 'Point movement is unavailable while a controller is connected.');
        return;
    }
    if (state.motionSessions.size) {
        setOlpStatus('error', 'Stop the normal motion program before moving to a point.');
        return;
    }

    const robot = state.activeProgramRobot || state.activeArticulatedModel;
    const record = getOlpPointContextRecord(target);
    if (!robot) {
        setOlpStatus('error', 'Select one robot before moving to a point.');
        return;
    }
    if (!record || !Array.isArray(record.values) || !record.values.length) {
        setOlpStatus('error', 'Point record not found: {point}.', {
            point: `${target.sourceSymbol || 'P'}[${target.index}]`
        });
        return;
    }

    const pointName = `${record.sourceSymbol || 'P'}[${record.index}]`;
    state.olp.manualMoveBusy = true;
    updateOlpProgramPanelUi();
    updateMotionUiLock();
    try {
        setOlpLastMotion('Moving to {point}.', { point: pointName });
        appendOlpConsole('Moving {point} from {path}.', {
            point: pointName,
            path: record.path
        });
        setOlpStatus('working');
        await moveOlpTarget(robot, 'MOVJ', record, 100, null, {
            segmentName: pointName,
            armParameters: record.armParameters || []
        });
        setOlpLastMotion('{point} reached.', { point: pointName });
        appendOlpConsole('{point} reached.', { point: pointName });
        setOlpStatus('connected', 'Moved to {point}.', { point: pointName });
    } catch (error) {
        setOlpStatus('error', 'Point move failed: {error}', {
            error: error?.message || error
        });
    } finally {
        state.olp.manualMoveBusy = false;
        updateOlpProgramPanelUi();
        updateMotionUiLock();
        requestRender();
    }
}

function formatOlpPointSourceLine(record, coordinates, armParameters) {
    const sourceLine = String(record?.sourceLine || '');
    const segments = sourceLine.split(';');
    const assignment = segments[0]?.match(/^(\s*(?:P|LP)\s*\[\s*\d+\s*\]\s*=\s*)/i);
    if (!assignment) throw new Error('포인트 레코드 형식을 인식할 수 없습니다.');
    const formatNumber = (value) => {
        const numeric = Number(value);
        if (!Number.isFinite(numeric)) throw new Error('현재 로봇 위치값이 올바르지 않습니다.');
        return (Object.is(numeric, -0) ? 0 : numeric).toFixed(6);
    };
    const coordinateText = coordinates.slice(0, 6).map(formatNumber).join(', ');
    const armText = armParameters.slice(0, 4).map((value) => {
        const numeric = Number(value);
        if (!Number.isFinite(numeric)) throw new Error('Arm 파라미터가 올바르지 않습니다.');
        return String(Math.trunc(numeric));
    }).join(', ');
    segments[0] = `${assignment[1]}${coordinateText}`;
    segments[1] = ` ${armText}`;
    if (segments.length < 3) segments.push('0.000000, 0.000000, 0.000000, 0.000000, 0.000000, 0.000000');
    return segments.join(';');
}

function writeOlpPointFromCurrentRobot() {
    const target = state.olp.pointContextTarget;
    closeOlpPointContextMenu();
    const project = getOlpProject();
    if (!target || isOlpRunning() || !project) return;
    const robot = state.activeProgramRobot || state.activeArticulatedModel;
    const pointFile = project.pointFiles?.find((file) => file.path === target.path && file.kind === 'point');
    const record = pointFile?.records?.find((candidate) => candidate.index === Number(target.index)
        && (candidate.sourceSymbol || 'P').toUpperCase() === String(target.sourceSymbol || 'P').toUpperCase());
    if (!robot || !pointFile || !record) return;
    const coordinates = getOlpCurrentPosition('point');
    if (!Array.isArray(coordinates) || coordinates.length < 6) {
        setOlpStatus('error', '현재 로봇 위치를 읽을 수 없습니다.');
        return;
    }
    try {
        const joints = (robot.userData.joints || []).map((joint) => Number(joint.angle) || 0);
        const armParameters = calculatePointArmParameters(robot, joints);
        const nextLine = formatOlpPointSourceLine(record, coordinates, armParameters);
        const fileRecord = project.files.get(target.path);
        const sourceLines = String(fileRecord?.text || '').split(/\r?\n/);
        let lineIndex = sourceLines.findIndex((line) => line === record.sourceLine);
        if (lineIndex < 0) {
            lineIndex = sourceLines.findIndex((line) => new RegExp(`^\\s*(?:P|LP)\\s*\\[\\s*${Number(target.index)}\\s*\\]\\s*=`, 'i').test(line));
        }
        if (lineIndex < 0) throw new Error('원본 포인트 행을 찾을 수 없습니다.');
        sourceLines[lineIndex] = nextLine;
        const viewState = captureOlpPointViewState();
        updateOlpFileText(project, target.path, sourceLines.join('\n'));
        state.olp.selectedFile = target.path;
        state.olp.projectDirty = true;
        saveActiveOlpProjectViewState();
        scheduleMotionProjectSave();
        renderOlpFileList();
        restoreOlpPointViewState(viewState);
        appendOlpConsole('{symbol}[{index}] overwritten from current robot pose; Arm=[{arm}].', {
            symbol: target.sourceSymbol || 'P',
            index: target.index,
            arm: armParameters.join(', ')
        });
        setOlpStatus(state.olp.status === 'error' ? 'connected' : state.olp.status, 'OLP point updated from the current robot position.');
    } catch (error) {
        setOlpStatus('error', '포인트 쓰기 실패: {error}', { error: error.message || error });
    }
}

function handleProgramStepContextMenu(event) {
    const row = event.target.closest('[data-program-step-id]');
    const program = ensureMotionProgram(state.activeProgramRobot);
    const step = program?.steps.find((candidate) => candidate.id === row?.dataset.programStepId);
    if (!row || !step) return;
    event.preventDefault();
    program.selectedStepId = step.id;
    state.programContextStepId = step.id;
    renderMotionProgramPanel();
    const menu = el.programStepContextMenu;
    if (!menu) return;
    const isMotionPoint = isMotionPointMotion(step.motion);
    if (el.btnProgramOverwritePoint) el.btnProgramOverwritePoint.hidden = !isMotionPoint;
    if (el.btnProgramShowPositionValue) el.btnProgramShowPositionValue.hidden = !isMotionPoint;
    menu.classList.remove('hidden');
    menu.style.left = '0px';
    menu.style.top = '0px';
    const bounds = menu.getBoundingClientRect();
    menu.style.left = `${Math.max(8, Math.min(event.clientX, window.innerWidth - bounds.width - 8))}px`;
    menu.style.top = `${Math.max(8, Math.min(event.clientY, window.innerHeight - bounds.height - 8))}px`;
}

function showPositionValueError(message = '') {
    if (!el.positionValueError) return;
    el.positionValueError.textContent = message ? uiText(message) : '';
    el.positionValueError.classList.toggle('visible', Boolean(message));
}

function openContextProgramPointPosition() {
    const robot = state.activeProgramRobot;
    const program = ensureMotionProgram(robot);
    const step = program?.steps.find((candidate) => candidate.id === state.programContextStepId);
    closeProgramStepContextMenu();
    if (!robot || !step || !isMotionPointMotion(step.motion)) return;
    const pose = motionStepTargetPose(step);
    const rotation = getTcpRotationDegrees(robot, pose);
    const positionValues = {
        x: pose.position.x,
        y: pose.position.y,
        z: pose.position.z,
        a: rotation.rz,
        b: rotation.ry,
        c: rotation.rx
    };
    Object.entries(positionValues).forEach(([key, value]) => {
        if (el.positionValueInputs[key]) el.positionValueInputs[key].value = Number(value).toFixed(6);
    });
    const armParameters = step.armParameters || calculatePointArmParameters(robot, step.joints);
    el.positionArmInputs.forEach((input, index) => { input.value = String(armParameters[index] ?? 0); });
    const externalAxes = step.externalAxes || [0, 0, 0, 0, 0, 0];
    el.positionExternalInputs.forEach((input, index) => {
        input.value = Number(externalAxes[index] || 0).toFixed(6);
    });
    if (el.positionValueLabel) el.positionValueLabel.value = step.label || '';
    if (el.positionValuePointName) el.positionValuePointName.textContent = formatMotionPointName(step.pointIndex);
    state.positionDialogTarget = {
        robotInstanceId: robot.userData.motionInstanceId,
        stepId: step.id
    };
    showPositionValueError();
    el.positionValueDialog?.showModal();
}

function closePositionValueDialog() {
    state.positionDialogTarget = null;
    showPositionValueError();
    if (el.positionValueDialog?.open) el.positionValueDialog.close();
}

function quaternionFromPointRotation(robot, rx, ry, rz) {
    return quaternionFromTcpRotationDegrees(robot, rx, ry, rz);
}

function applyPositionValueDialog() {
    const targetRecord = state.positionDialogTarget;
    const robot = findProgramRobot(targetRecord?.robotInstanceId);
    const program = ensureMotionProgram(robot);
    const step = program?.steps.find((candidate) => candidate.id === targetRecord?.stepId);
    if (!robot || !step || !isMotionPointMotion(step.motion)) {
        showPositionValueError('수정할 위치 포인트를 찾을 수 없습니다.');
        return;
    }
    const values = Object.fromEntries(Object.entries(el.positionValueInputs)
        .map(([key, input]) => [key, Number(input.value)]));
    const armParameters = el.positionArmInputs.map((input) => Number(input.value));
    const externalAxes = el.positionExternalInputs.map((input) => Number(input.value));
    const label = el.positionValueLabel?.value.trim() || '';
    if (!Object.values(values).every(Number.isFinite)
        || !armParameters.every(Number.isInteger)
        || !externalAxes.every(Number.isFinite)) {
        showPositionValueError('위치 값, Arm 파라미터 및 외부 축 값을 올바르게 입력하세요.');
        return;
    }
    if (!isValidMotionPointLabel(label)) {
        showPositionValueError('라벨은 영문자로 시작하고 영문, 숫자, 밑줄만 사용하여 19자 이하로 입력하세요.');
        return;
    }

    const targetPose = {
        position: new THREE.Vector3(values.x, values.y, values.z),
        quaternion: quaternionFromPointRotation(robot, values.c, values.b, values.a)
    };
    const before = captureSceneSnapshot();
    const originalBaseTransform = captureClipboardTransform(robot);
    const originalExternalAxes = getRobotExternalAxes(robot);
    const originalAngles = robot.userData.joints.map((joint) => joint.angle);
    applyRobotTravelAxis(robot, externalAxes, { syncPresentation: false });
    const seedAngles = Array.isArray(step.joints) ? step.joints : originalAngles;
    seedAngles.forEach((angle, index) => setJointAngle(robot.userData.joints[index], angle, false));
    robot.updateMatrixWorld(true);
    const result = solveRobotIK(robot, targetPose, {
        positionTolerance: 0.001,
        rotationTolerance: THREE.MathUtils.degToRad(0.001)
    });
    if (!result.success) {
        restoreRobotJointAngles(robot, originalAngles);
        applyClipboardTransform(robot, originalBaseTransform);
        robot.userData.externalAxes = originalExternalAxes;
        robot.updateMatrixWorld(true);
        markSceneCollisionDirty(robot);
        updateTcpPresentation(robot);
        syncBaseJogGizmoFromRobot(robot);
        showPositionValueError('입력한 위치가 로봇의 도달 범위 또는 관절 제한을 벗어났습니다.');
        return;
    }
    const solvedAngles = robot.userData.joints.map((joint) => joint.angle);
    restoreRobotJointAngles(robot, originalAngles);

    step.joints = solvedAngles;
    step.tcp = {
        position: targetPose.position.toArray(),
        quaternion: targetPose.quaternion.toArray()
    };
    step.armParameters = armParameters;
    step.externalAxes = externalAxes;
    step.label = label;
    step.name = formatMotionPointName(step.pointIndex);
    updateTcpPresentation(robot);
    syncBaseJogGizmoFromRobot(robot);
    recordHistory('프로그램 포인트 위치 값 변경', before, captureSceneSnapshot());
    closePositionValueDialog();
    renderMotionProgramPanel();
    setMotionProgramStatus('{name} 위치 값을 수정했습니다.', '', { name: step.name });
}

function handleProgramStepListChange(event) {
    const pointIndexControl = event.target.closest('[data-program-step-point-index]');
    const labelControl = event.target.closest('[data-program-step-label]');
    const motionControl = event.target.closest('[data-program-step-motion]');
    const viewSlotControl = event.target.closest('[data-program-step-view-slot]');
    const gripObjectControl = event.target.closest('[data-program-step-grip-object]');
    const waitRobotControl = event.target.closest('[data-program-step-wait-robot]');
    const waitLineControl = event.target.closest('[data-program-step-wait-line]');
    const speedControl = event.target.closest('[data-program-step-speed]');
    const stepId = pointIndexControl?.dataset.programStepPointIndex
        || labelControl?.dataset.programStepLabel
        || motionControl?.dataset.programStepMotion
        || viewSlotControl?.dataset.programStepViewSlot
        || gripObjectControl?.dataset.programStepGripObject
        || waitRobotControl?.dataset.programStepWaitRobot
        || waitLineControl?.dataset.programStepWaitLine
        || speedControl?.dataset.programStepSpeed;
    const robot = state.activeProgramRobot;
    const program = ensureMotionProgram(robot);
    const step = program?.steps.find((candidate) => candidate.id === stepId);
    if (!step) return;
    if (pointIndexControl) {
        const pointIndex = Number(pointIndexControl.value);
        const duplicate = program.steps.some((candidate) => candidate !== step
            && isMotionPointMotion(candidate.motion)
            && candidate.pointIndex === pointIndex);
        if (!Number.isInteger(pointIndex)
            || pointIndex < MIN_POINT_INDEX
            || pointIndex > MAX_POINT_INDEX
            || duplicate) {
            setMotionProgramStatus(duplicate
                ? '이미 사용 중인 포인트 번호입니다.'
                : '포인트 번호는 0부터 9999 사이의 정수여야 합니다.', 'error');
            renderMotionProgramPanel();
            return;
        }
        if (step.pointIndex === pointIndex) return;
        const before = captureSceneSnapshot();
        step.pointIndex = pointIndex;
        step.name = formatMotionPointName(pointIndex);
        recordHistory('프로그램 포인트 번호 변경', before, captureSceneSnapshot());
        renderMotionProgramPanel();
        return;
    }
    if (labelControl) {
        const label = labelControl.value.trim();
        if (!isValidMotionPointLabel(label)) {
            setMotionProgramStatus('라벨은 영문자로 시작하고 영문, 숫자, 밑줄만 사용하여 19자 이하로 입력하세요.', 'error');
            renderMotionProgramPanel();
            return;
        }
        if ((step.label || '') === label) return;
        const before = captureSceneSnapshot();
        step.label = label;
        recordHistory('프로그램 포인트 라벨 변경', before, captureSceneSnapshot());
        renderMotionProgramPanel();
        return;
    }
    if (viewSlotControl) {
        const viewSlot = Number(viewSlotControl.value);
        if (!Number.isInteger(viewSlot) || viewSlot < 0 || viewSlot >= VIEW_PRESET_COUNT) {
            renderMotionProgramPanel();
            return;
        }
        if (step.motion !== 'VIEW' || step.viewSlot === viewSlot) return;
        const before = captureSceneSnapshot();
        step.viewSlot = viewSlot;
        step.name = programCommandName(step);
        recordHistory('화면 뷰 전환 대상 변경', before, captureSceneSnapshot());
        renderMotionProgramPanel();
        return;
    }
    if (gripObjectControl) {
        const reference = gripObjectControl.value;
        if (!getGripObjectReferences().some((candidate) => candidate.value === reference)) {
            setMotionProgramStatus('물건 잡기/놓기 명령 대상이 없습니다.', 'error');
            renderMotionProgramPanel();
            return;
        }
        if (step.gripObjectRef === reference) return;
        const before = captureSceneSnapshot();
        step.gripObjectRef = reference;
        step.name = programCommandName(step);
        recordHistory('물건 잡기 대상 변경', before, captureSceneSnapshot());
        renderMotionProgramPanel();
        return;
    }
    if (waitRobotControl) {
        const targetRobot = getArticulatedRobots().find((candidate) => (
            candidate.userData.motionInstanceId === waitRobotControl.value
        ));
        if (!targetRobot || targetRobot === robot) {
            setMotionProgramStatus('대기 대상 로봇을 선택하세요.', 'error');
            renderMotionProgramPanel();
            return;
        }
        if (step.waitRobotInstanceId === targetRobot.userData.motionInstanceId) return;
        const before = captureSceneSnapshot();
        step.waitRobotInstanceId = targetRobot.userData.motionInstanceId;
        const targetLine = Number(step.waitLineNumber);
        step.waitLineNumber = Number.isInteger(targetLine)
            ? THREE.MathUtils.clamp(targetLine, MIN_WAIT_LINE_NUMBER, MAX_WAIT_LINE_NUMBER)
            : MIN_WAIT_LINE_NUMBER;
        recordHistory('WAIT 대상 로봇 변경', before, captureSceneSnapshot());
        renderMotionProgramPanel();
        return;
    }
    if (waitLineControl) {
        const lineNumber = Number(waitLineControl.value);
        if (!Number.isInteger(lineNumber)
            || lineNumber < MIN_WAIT_LINE_NUMBER
            || lineNumber > MAX_WAIT_LINE_NUMBER) {
            setMotionProgramStatus(
                '대기 행 번호는 {min}부터 {max} 사이의 정수여야 합니다.',
                'error',
                { min: MIN_WAIT_LINE_NUMBER, max: MAX_WAIT_LINE_NUMBER }
            );
            renderMotionProgramPanel();
            return;
        }
        if (step.waitLineNumber === lineNumber) return;
        const before = captureSceneSnapshot();
        step.waitLineNumber = lineNumber;
        recordHistory('WAIT 대상 행 변경', before, captureSceneSnapshot());
        renderMotionProgramPanel();
        return;
    }
    const before = captureSceneSnapshot();
    if (motionControl) {
        const wasPoint = isMotionPointMotion(step.motion);
        const nextMotion = ['MOVJ', 'MOVL', 'HOME', 'DELAY', 'WAIT', 'TIME_START', 'TIME_OUT', 'VIEW', 'GRIP_USE', 'GRIP_RELEASE'].includes(motionControl.value)
            ? motionControl.value
            : 'MOVJ';
        const isPoint = isMotionPointMotion(nextMotion);
        if (isWaitMotion(nextMotion) && !getWaitTargetRobot(robot)) {
            setMotionProgramStatus('WAIT 명령에는 다른 로봇이 필요합니다.', 'error');
            renderMotionProgramPanel();
            return;
        }
        const allocatedPointIndex = isPoint && !wasPoint
            ? nextAvailablePointIndex(program, step)
            : null;
        if (isPoint && !wasPoint && allocatedPointIndex === null) {
            setMotionProgramStatus('사용 가능한 포인트 번호가 없습니다.', 'error');
            renderMotionProgramPanel();
            return;
        }
        step.motion = nextMotion;
        if (isPoint && !wasPoint) {
            step.pointIndex = allocatedPointIndex;
            step.name = formatMotionPointName(allocatedPointIndex);
            step.label = '';
            step.armParameters = calculatePointArmParameters(robot, step.joints);
            step.externalAxes = getRobotExternalAxes(robot);
        } else if (!isPoint) {
            delete step.pointIndex;
            delete step.label;
            delete step.armParameters;
            delete step.externalAxes;
            step.name = step.motion === 'DELAY'
                ? 'Delay'
                : step.motion === 'WAIT'
                    ? 'Wait'
                : step.motion === 'TIME_START'
                    ? 'Time Start'
                : step.motion === 'TIME_OUT'
                    ? 'Time Out'
                    : step.motion === 'HOME'
                        ? 'Home'
                    : step.motion === 'GRIP_USE'
                            ? uiText('물건 잡기')
                            : step.motion === 'GRIP_RELEASE'
                                ? uiText('놓기')
                                : 'View 1';
        }
        if (step.motion === 'DELAY') {
            delete step.speed;
            delete step.viewSlot;
            delete step.waitRobotInstanceId;
            delete step.waitLineNumber;
            step.delaySeconds = DEFAULT_DELAY_SECONDS;
        } else if (step.motion === 'WAIT') {
            delete step.delaySeconds;
            delete step.speed;
            delete step.viewSlot;
            delete step.gripObjectRef;
            const targetRobot = getWaitTargetRobot(robot);
            step.waitRobotInstanceId = getArticulatedRobots().some((candidate) => (
                candidate.userData.motionInstanceId === step.waitRobotInstanceId && candidate !== robot
            )) ? step.waitRobotInstanceId : targetRobot?.userData.motionInstanceId || '';
            step.waitLineNumber = Number.isInteger(step.waitLineNumber)
                ? THREE.MathUtils.clamp(step.waitLineNumber, MIN_WAIT_LINE_NUMBER, MAX_WAIT_LINE_NUMBER)
                : MIN_WAIT_LINE_NUMBER;
        } else if (step.motion === 'MOVJ' || step.motion === 'MOVL') {
            delete step.delaySeconds;
            delete step.viewSlot;
            delete step.waitRobotInstanceId;
            delete step.waitLineNumber;
            step.speed = getDefaultMotionSpeed(robot, step.motion);
        } else if (step.motion === 'HOME') {
            delete step.delaySeconds;
            delete step.speed;
            delete step.viewSlot;
            delete step.gripObjectRef;
            delete step.waitRobotInstanceId;
            delete step.waitLineNumber;
            step.name = 'Home';
        } else if (step.motion === 'VIEW') {
            delete step.delaySeconds;
            delete step.speed;
            delete step.waitRobotInstanceId;
            delete step.waitLineNumber;
            step.viewSlot = Number.isInteger(step.viewSlot)
                ? THREE.MathUtils.clamp(step.viewSlot, 0, VIEW_PRESET_COUNT - 1)
                : 0;
            step.name = programCommandName(step);
        } else if (isGripObjectMotion(step.motion)) {
            delete step.delaySeconds;
            delete step.speed;
            delete step.viewSlot;
            delete step.waitRobotInstanceId;
            delete step.waitLineNumber;
            const references = getGripObjectReferences();
            if (!references.length) {
                setMotionProgramStatus('물건 잡기 대상을 선택하세요.', 'error');
                renderMotionProgramPanel();
                return;
            }
            step.gripObjectRef = references.some((reference) => reference.value === step.gripObjectRef)
                ? step.gripObjectRef
                : getSelectedGripObjectReference() || references[0].value;
            step.name = programCommandName(step);
        } else {
            delete step.speed;
            delete step.delaySeconds;
            delete step.viewSlot;
            delete step.gripObjectRef;
            delete step.waitRobotInstanceId;
            delete step.waitLineNumber;
        }
    } else if (step.motion === 'DELAY') {
        step.delaySeconds = THREE.MathUtils.clamp(
            Number(speedControl.value) || DEFAULT_DELAY_SECONDS,
            MIN_DELAY_SECONDS,
            MAX_DELAY_SECONDS
        );
    } else {
        const maximum = step.motion === 'MOVJ'
            ? 100
            : robot.userData.manifest.cartesianMotion.maxSpeed;
        step.speed = THREE.MathUtils.clamp(Number(speedControl.value) || 1, 1, maximum);
    }
    recordHistory('모션 명령 편집', before, captureSceneSnapshot());
    renderMotionProgramPanel();
}

function clearProgramStepDropIndicators() {
    el.programStepList?.querySelectorAll('.dragging, .drag-over-before, .drag-over-after')
        .forEach((row) => row.classList.remove('dragging', 'drag-over-before', 'drag-over-after'));
}

function getProgramStepDropTarget(event) {
    const rows = [...(el.programStepList?.querySelectorAll('[data-program-step-id]') || [])];
    if (!rows.length) return null;
    const directRow = event.target.closest?.('[data-program-step-id]');
    if (directRow && el.programStepList.contains(directRow)) {
        const bounds = directRow.getBoundingClientRect();
        return {
            row: directRow,
            stepId: directRow.dataset.programStepId,
            placeAfter: event.clientY >= bounds.top + bounds.height / 2
        };
    }
    const nextRow = rows.find((row) => {
        const bounds = row.getBoundingClientRect();
        return event.clientY < bounds.top + bounds.height / 2;
    });
    const row = nextRow || rows.at(-1);
    return {
        row,
        stepId: row.dataset.programStepId,
        placeAfter: !nextRow
    };
}

function quaternionFromTcpRotationDegrees(robot, rx, ry, rz) {
    if (robot.userData.manifest?.robotType === 'scara' && robot.userData.toolHomeQuaternion) {
        const yaw = new THREE.Quaternion().setFromAxisAngle(
            new THREE.Vector3(0, 0, 1),
            THREE.MathUtils.degToRad(rz)
        );
        return yaw.multiply(robot.userData.toolHomeQuaternion.clone()).normalize();
    }
    const positionRotation = new THREE.Quaternion().setFromEuler(new THREE.Euler(
        THREE.MathUtils.degToRad(rx),
        THREE.MathUtils.degToRad(ry),
        THREE.MathUtils.degToRad(rz),
        'ZYX'
    ));
    const homeQuaternion = robot.userData.toolHomeQuaternion;
    if (!homeQuaternion) return positionRotation;
    return homeQuaternion.clone()
        .multiply(SIX_AXIS_POSITION_HOME_QUATERNION.clone().invert())
        .multiply(positionRotation)
        .normalize();
}

function handleProgramStepDragStart(event) {
    const handle = event.target.closest?.('[data-program-step-drag]');
    const row = handle?.closest('[data-program-step-id]');
    if (!handle || !row) {
        event.preventDefault();
        return;
    }
    state.programStepDragId = handle.dataset.programStepDrag;
    row.classList.add('dragging');
    if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = 'move';
        event.dataTransfer.setData('text/plain', state.programStepDragId);
    }
}

function handleProgramStepDragOver(event) {
    if (!state.programStepDragId) return;
    const target = getProgramStepDropTarget(event);
    if (!target) return;
    event.preventDefault();
    if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
    el.programStepList.querySelectorAll('.drag-over-before, .drag-over-after').forEach((row) => {
        row.classList.remove('drag-over-before', 'drag-over-after');
    });
    target.row.classList.add(target.placeAfter ? 'drag-over-after' : 'drag-over-before');
}

function handleProgramStepDrop(event) {
    if (!state.programStepDragId) return;
    const target = getProgramStepDropTarget(event);
    if (!target) return;
    event.preventDefault();
    const sourceStepId = state.programStepDragId;
    const program = ensureMotionProgram(state.activeProgramRobot);
    const before = captureSceneSnapshot();
    const changed = reorderMotionSteps(program?.steps, sourceStepId, target.stepId, target.placeAfter);
    state.programStepDragId = null;
    clearProgramStepDropIndicators();
    if (!changed) return;
    program.selectedStepId = sourceStepId;
    recordHistory('모션 포인트 순서 변경', before, captureSceneSnapshot());
    renderMotionProgramPanel();
}

function handleProgramStepDragEnd() {
    state.programStepDragId = null;
    clearProgramStepDropIndicators();
}

function pointQuadrantIndex(angleDegrees) {
    const angle = Number(angleDegrees) || 0;
    return Math.floor((angle + 1e-9) / 90);
}

function calculatePointArmParameters(robot, jointAngles, preservedConfiguration = null) {
    const angles = Array.isArray(jointAngles)
        ? jointAngles.map((value) => Number(value) || 0)
        : (robot?.userData.joints || []).map((joint) => joint.angle);
    if (robot?.userData.manifest?.robotType === 'scara') {
        const elbowAngle = angles[1] || 0;
        return [elbowAngle < 0 ? -1 : 1, 0, 0, pointQuadrantIndex(angles[3] || 0)];
    }
    return [
        pointQuadrantIndex(angles[0] || 0),
        pointQuadrantIndex(angles[3] || 0),
        pointQuadrantIndex(angles[5] || 0),
        Number.isInteger(preservedConfiguration) ? preservedConfiguration : 1
    ];
}

function captureRobotMotionStep(robot, existing = null) {
    const pose = getCurrentTcpPoseBase(robot);
    if (!pose) return null;
    const program = ensureMotionProgram(robot);
    const motion = existing?.motion || 'MOVJ';
    const joints = robot.userData.joints.map((joint) => joint.angle);
    const defaultMotionSpeed = getDefaultMotionSpeed(robot, motion);
    const isPoint = isMotionPointMotion(motion);
    const pointIndex = isPoint
        ? (Number.isInteger(existing?.pointIndex) ? existing.pointIndex : nextAvailablePointIndex(program, existing))
        : null;
    if (isPoint && pointIndex === null) {
        setMotionProgramStatus('사용 가능한 포인트 번호가 없습니다.', 'error');
        return null;
    }
    return {
        id: existing?.id || createMotionId('point'),
        name: isPoint
            ? formatMotionPointName(pointIndex)
            : motion === 'DELAY'
                ? 'Delay'
                : motion === 'WAIT'
                    ? 'Wait'
                : motion === 'TIME_START'
                    ? 'Time Start'
                : motion === 'TIME_OUT'
                        ? 'Time Out'
                        : motion === 'GRIP_USE'
                            ? uiText('물건 잡기')
                            : motion === 'GRIP_RELEASE'
                                ? uiText('놓기')
                        : `View ${(Number.isInteger(existing?.viewSlot) ? existing.viewSlot : 0) + 1}`,
        motion,
        ...(isPoint ? {
            pointIndex,
            label: existing?.label || '',
            armParameters: calculatePointArmParameters(robot, joints, existing?.armParameters?.[3]),
            externalAxes: Array.isArray(existing?.externalAxes)
                ? [...existing.externalAxes]
                : getRobotExternalAxes(robot)
        } : {}),
        ...(motion === 'DELAY'
            ? { delaySeconds: existing?.delaySeconds ?? DEFAULT_DELAY_SECONDS }
            : motion === 'MOVJ' || motion === 'MOVL'
                ? { speed: existing?.speed ?? defaultMotionSpeed }
                : motion === 'VIEW'
                    ? { viewSlot: Number.isInteger(existing?.viewSlot)
                        ? THREE.MathUtils.clamp(existing.viewSlot, 0, VIEW_PRESET_COUNT - 1)
                        : 0 }
                : motion === 'WAIT'
                    ? {
                        waitRobotInstanceId: existing?.waitRobotInstanceId
                            || getWaitTargetRobot(robot)?.userData.motionInstanceId
                            || '',
                        waitLineNumber: Number.isInteger(existing?.waitLineNumber)
                            ? THREE.MathUtils.clamp(existing.waitLineNumber, MIN_WAIT_LINE_NUMBER, MAX_WAIT_LINE_NUMBER)
                            : MIN_WAIT_LINE_NUMBER
                    }
                : isGripObjectMotion(motion)
                    ? { gripObjectRef: existing?.gripObjectRef || '' }
                : {}),
        joints,
        tcp: {
            position: pose.position.toArray(),
            quaternion: pose.quaternion.toArray()
        }
    };
}

function addCurrentMotionStep() {
    if (!state.activeProgramRobot) return;
    const before = captureSceneSnapshot();
    const program = ensureMotionProgram(state.activeProgramRobot);
    const step = captureRobotMotionStep(state.activeProgramRobot);
    if (!step) return;
    insertMotionStepAfterSelected(program, step);
    program.selectedStepId = step.id;
    recordHistory('모션 포인트 추가', before, captureSceneSnapshot());
    renderMotionProgramPanel();
}

function addDelayMotionStep() {
    if (!state.activeProgramRobot) return;
    const before = captureSceneSnapshot();
    const program = ensureMotionProgram(state.activeProgramRobot);
    const step = captureRobotMotionStep(state.activeProgramRobot);
    if (!step) return;
    step.name = 'Delay';
    step.motion = 'DELAY';
    delete step.pointIndex;
    delete step.label;
    delete step.armParameters;
    delete step.externalAxes;
    delete step.speed;
    step.delaySeconds = DEFAULT_DELAY_SECONDS;
    insertMotionStepAfterSelected(program, step);
    program.selectedStepId = step.id;
    recordHistory('딜레이 명령 추가', before, captureSceneSnapshot());
    renderMotionProgramPanel();
}

function addTimerMotionStep(motion) {
    if (!state.activeProgramRobot || !['TIME_START', 'TIME_OUT'].includes(motion)) return;
    const before = captureSceneSnapshot();
    const program = ensureMotionProgram(state.activeProgramRobot);
    const step = captureRobotMotionStep(state.activeProgramRobot);
    if (!step) return;
    step.name = motion === 'TIME_START' ? 'Time Start' : 'Time Out';
    step.motion = motion;
    delete step.pointIndex;
    delete step.label;
    delete step.armParameters;
    delete step.externalAxes;
    delete step.speed;
    delete step.delaySeconds;
    insertMotionStepAfterSelected(program, step);
    program.selectedStepId = step.id;
    recordHistory(motion === 'TIME_START' ? 'TIME START 명령 추가' : 'TIME OUT 명령 추가', before, captureSceneSnapshot());
    renderMotionProgramPanel();
}

function addViewMotionStep() {
    if (!state.activeProgramRobot) return;
    const before = captureSceneSnapshot();
    const program = ensureMotionProgram(state.activeProgramRobot);
    const step = captureRobotMotionStep(state.activeProgramRobot);
    if (!step) return;
    step.name = 'View 1';
    step.motion = 'VIEW';
    step.viewSlot = 0;
    delete step.pointIndex;
    delete step.label;
    delete step.armParameters;
    delete step.externalAxes;
    delete step.speed;
    delete step.delaySeconds;
    insertMotionStepAfterSelected(program, step);
    program.selectedStepId = step.id;
    recordHistory('화면 뷰 전환 명령 추가', before, captureSceneSnapshot());
    renderMotionProgramPanel();
}

function insertMotionStepAfterSelected(program, step) {
    const selectedIndex = program.steps.findIndex((candidate) => candidate.id === program.selectedStepId);
    program.steps.splice(selectedIndex >= 0 ? selectedIndex + 1 : program.steps.length, 0, step);
}

function updateSelectedMotionStep() {
    if (!state.activeProgramRobot) return;
    const program = ensureMotionProgram(state.activeProgramRobot);
    const index = program.steps.findIndex((step) => step.id === program.selectedStepId);
    if (index < 0) return;
    const before = captureSceneSnapshot();
    program.steps[index] = captureRobotMotionStep(state.activeProgramRobot, program.steps[index]);
    recordHistory('모션 포인트 덮어쓰기', before, captureSceneSnapshot());
    renderMotionProgramPanel();
    showProgramPointOverwriteFeedback(program.steps[index]);
}

function showProgramPointOverwriteFeedback(step) {
    setMotionProgramStatus('{name} 위치 값을 수정했습니다.', '', { name: formatMotionPointName(step.pointIndex) });
}

function deleteSelectedMotionStep() {
    const program = ensureMotionProgram(state.activeProgramRobot);
    const index = program?.steps.findIndex((step) => step.id === program.selectedStepId) ?? -1;
    if (index < 0) return;
    const before = captureSceneSnapshot();
    program.steps.splice(index, 1);
    program.selectedStepId = program.steps[Math.min(index, program.steps.length - 1)]?.id || null;
    recordHistory('모션 포인트 삭제', before, captureSceneSnapshot());
    renderMotionProgramPanel();
    focusProgramStepRow(program.selectedStepId);
}

function preflightActiveReverseRepeatSessions(scope) {
    [...state.motionSessions.values()]
        .filter((session) => !session.stepIntoStepId && session.controlScope === scope)
        .forEach((session) => preflightRobotMotion(session.robot, session.steps, {
            reverseRepeat: true,
            timerOnly: true
        }));
}

function updateMotionRepeat(event) {
    if (state.olp.enabled) return;
    const scope = event.currentTarget?.dataset.programRepeatScope === 'robot' ? 'robot' : 'group';
    const reverse = event.currentTarget?.hasAttribute('data-program-reverse-repeat') === true;
    const repeatStateKey = scope === 'robot' ? 'motionRepeatRobot' : 'motionRepeat';
    const reverseStateKey = scope === 'robot' ? 'motionReverseRepeatRobot' : 'motionReverseRepeat';
    const stateKey = reverse ? reverseStateKey : repeatStateKey;
    const enabled = !state[stateKey];
    if (reverse && enabled) {
        try {
            preflightActiveReverseRepeatSessions(scope);
        } catch (error) {
            setMotionProgramStatus('모션 경로 검증에 실패했습니다.', 'error');
            renderMotionProgramPanel();
            return;
        }
    }
    const before = isMotionActive() ? null : captureSceneSnapshot();
    state[repeatStateKey] = reverse ? false : enabled;
    state[reverseStateKey] = reverse ? enabled : false;
    state.motionSessions.forEach((session) => {
        if (session.stepIntoStepId || session.controlScope !== scope) return;
        session.repeat = state[repeatStateKey];
        session.reverseRepeat = state[reverseStateKey];
    });
    syncMotionRepeatControl();
    if (before) recordHistory(reverse ? '역순 반복 변경' : '반복 실행 변경', before, captureSceneSnapshot());
    else scheduleMotionProjectSave();
    renderMotionProgramPanel();
}

function addWaitMotionStep() {
    if (!state.activeProgramRobot) return;
    const targetRobot = getWaitTargetRobot(state.activeProgramRobot);
    if (!targetRobot) {
        setMotionProgramStatus('WAIT 명령에는 다른 로봇이 필요합니다.', 'error');
        return;
    }
    const before = captureSceneSnapshot();
    const program = ensureMotionProgram(state.activeProgramRobot);
    const step = captureRobotMotionStep(state.activeProgramRobot);
    if (!step) return;
    step.name = 'Wait';
    step.motion = 'WAIT';
    step.waitRobotInstanceId = targetRobot.userData.motionInstanceId;
    step.waitLineNumber = MIN_WAIT_LINE_NUMBER;
    delete step.pointIndex;
    delete step.label;
    delete step.armParameters;
    delete step.externalAxes;
    delete step.speed;
    delete step.delaySeconds;
    delete step.viewSlot;
    delete step.gripObjectRef;
    insertMotionStepAfterSelected(program, step);
    program.selectedStepId = step.id;
    recordHistory('WAIT 명령 추가', before, captureSceneSnapshot());
    renderMotionProgramPanel();
}

function addGripObjectMotionStep(motion) {
    if (!state.activeProgramRobot || !isGripObjectMotion(motion)) return;
    const references = getGripObjectReferences();
    const gripObjectRef = getSelectedGripObjectReference() || references[0]?.value || '';
    if (!gripObjectRef) {
        setMotionProgramStatus('물건 잡기 대상을 선택하세요.', 'error');
        return;
    }
    const before = captureSceneSnapshot();
    const program = ensureMotionProgram(state.activeProgramRobot);
    const step = captureRobotMotionStep(state.activeProgramRobot);
    if (!step) return;
    step.name = programCommandName({ motion, gripObjectRef });
    step.motion = motion;
    step.gripObjectRef = gripObjectRef;
    delete step.pointIndex;
    delete step.label;
    delete step.armParameters;
    delete step.externalAxes;
    delete step.speed;
    delete step.delaySeconds;
    delete step.viewSlot;
    insertMotionStepAfterSelected(program, step);
    program.selectedStepId = step.id;
    recordHistory('물건 잡기/놓기 명령 추가', before, captureSceneSnapshot());
    renderMotionProgramPanel();
    scheduleMotionProjectSave();
}

function syncMotionRepeatControl() {
    el.programRepeatButtons.forEach((button) => {
        const reverse = button.hasAttribute('data-program-reverse-repeat');
        const robotScope = button.dataset.programRepeatScope === 'robot';
        const enabled = reverse
            ? (robotScope ? state.motionReverseRepeatRobot : state.motionReverseRepeat)
            : (robotScope ? state.motionRepeatRobot : state.motionRepeat);
        const available = !state.olp.enabled;
        button.classList.toggle('active', available && enabled);
        button.setAttribute('aria-pressed', String(available && enabled));
        button.setAttribute('aria-label', uiText(reverse
            ? (robotScope ? '현재 로봇 역순 반복' : '체크 로봇 역순 반복')
            : (robotScope ? '현재 로봇 반복 실행' : '체크 로봇 반복 실행')));
        button.disabled = !available;
        button.title = uiText(reverse
            ? (enabled ? '역순 반복 켜짐' : '역순 반복 꺼짐')
            : (enabled ? '반복 실행 켜짐' : '반복 실행 꺼짐'));
    });
}

function updateMotionUiLock() {
    const locked = isMotionActive();
    // Keep scene inspection and additive editing available during normal
    // playback. Robot replacement remains protected because it invalidates
    // the robot instance currently used by a motion session.
    if (el.modelSelect) el.modelSelect.disabled = false;
    // Importing an additive scene model must remain available while either
    // the normal program panel or OLP is running.  Robot replacement and
    // whole-workspace loading keep their separate motion interlocks below.
    if (el.btnImport3D) el.btnImport3D.disabled = false;
    if (el.btnReplaceRobotModelChoice) {
        el.btnReplaceRobotModelChoice.disabled = locked || !getSelectedRobotModel();
    }
    el.modelTree?.classList.remove('motion-locked');
    // JOG mode switching and live controls remain available. The base 3D
    // gizmo and snap-to-pose actions still self-protect their active robot.
    el.jogPanel?.querySelectorAll('button:not([data-panel-action]), input')
        .forEach((control) => { control.disabled = false; });
    el.jogPanel?.querySelectorAll('[data-panel-action]')
        .forEach((control) => { control.disabled = false; });
    el.tcpProfilePanel?.querySelectorAll('button:not([data-panel-action]), input, select')
        .forEach((control) => { control.disabled = locked; });
    el.tcpProfilePanel?.querySelectorAll('[data-panel-action]')
        .forEach((control) => { control.disabled = false; });
    el.modelTransformPanel?.querySelectorAll('button, input').forEach((control) => { control.disabled = false; });
    // The program panel remains editable during playback.  Playback uses a
    // session snapshot, so edits are safe and take effect on the next run.
    // Whole-project replacement and automatic path planning still change or
    // temporarily mutate the live scene and remain unavailable while moving.
    if (el.btnProgramImport) el.btnProgramImport.disabled = locked;
    if (el.btnWorkspaceLoad) {
        el.btnWorkspaceLoad.disabled = simulationWorkspaceFileBusy || locked || isOlpRunning();
    }
    if (el.btnWorkspaceSave) el.btnWorkspaceSave.disabled = simulationWorkspaceFileBusy;
    if (el.btnProgramAutoPath) el.btnProgramAutoPath.disabled = locked;
    el.autoPathPanel?.querySelectorAll('input, select, button')
        .forEach((control) => {
            control.disabled = locked || (state.autoPath.planning && control !== el.btnAutoPathCancel);
        });
    el.interferenceZonePanel?.querySelectorAll('[data-interference-zone-activate], [data-interference-zone-edit]')
        .forEach((control) => { control.disabled = false; });
    el.endMonitoringList?.querySelectorAll('[data-end-monitoring-edit]')
        .forEach((control) => { control.disabled = false; });
    el.endMonitoringDialog?.querySelectorAll('input, select, button:not(#end-monitoring-close)')
        .forEach((control) => { control.disabled = false; });
    el.programRepeatButtons.forEach((button) => { button.disabled = Boolean(state.olp.enabled); });
    if (locked) {
        setBaseJogGizmoEnabled(false);
    } else if (getJogTargetRobot()
        && el.jogPanel
        && !el.jogPanel.classList.contains('hidden')
        && !el.jogPanel.classList.contains('panel-user-hidden')
        && el.baseJogView
        && !el.baseJogView.classList.contains('hidden')) {
        setBaseJogGizmoEnabled(true);
    }
    refreshTcpProfileUi();
    updateTcpSnapUi();
    updateSimulationSnapButton();
    updateHistoryButtons();
}

function getWorkspaceObjectPath(root, object) {
    if (!root || !object) return null;
    if (root === object) return [];
    const path = [];
    let cursor = object;
    while (cursor && cursor !== root) {
        const parent = cursor.parent;
        if (!parent) return null;
        const index = parent.children.indexOf(cursor);
        if (index < 0) return null;
        path.unshift(index);
        cursor = parent;
    }
    return cursor === root ? path : null;
}

function getWorkspaceObjectAtPath(root, path) {
    if (!root || !Array.isArray(path)) return null;
    return path.reduce((object, index) => (
        object && Number.isInteger(index) ? object.children[index] || null : null
    ), root);
}

function serializeWorkspaceMeasurementPoint(point) {
    const model = findSceneModelAncestor(point?.mesh);
    const objectPath = getWorkspaceObjectPath(model, point?.mesh);
    if (!model || !objectPath || !point?.localPoint?.toArray) return null;
    return {
        workspaceModelId: ensureWorkspaceModelId(model),
        objectPath,
        localPoint: point.localPoint.toArray(),
        snapType: String(point.snapType || 'auto')
    };
}

function serializeWorkspaceMeasurement() {
    return {
        active: Boolean(state.measurement.active),
        displayMode: ['orthogonal', 'robot-position'].includes(state.measurement.displayMode)
            ? state.measurement.displayMode
            : 'diagonal',
        robotPositionRobotId: state.measurement.robotPositionRobotId || null,
        snapType: String(state.measurement.snapType || 'auto'),
        points: state.measurement.points
            .map(serializeWorkspaceMeasurementPoint)
            .filter(Boolean)
    };
}

function restoreWorkspaceMeasurement(snapshot) {
    const saved = snapshot?.measurement;
    const savedPoints = Array.isArray(saved?.points) ? saved.points : [];
    const points = savedPoints.map((entry) => {
        const model = findModelByWorkspaceId(entry?.workspaceModelId);
        const mesh = getWorkspaceObjectAtPath(model, entry?.objectPath);
        const localPoint = Array.isArray(entry?.localPoint) && entry.localPoint.length === 3
            ? new THREE.Vector3().fromArray(entry.localPoint)
            : null;
        if (!model || !mesh || !localPoint) return null;
        mesh.updateWorldMatrix?.(true, false);
        const worldPoint = localPoint.clone().applyMatrix4(mesh.matrixWorld);
        if (![worldPoint.x, worldPoint.y, worldPoint.z].every(Number.isFinite)) return null;
        return {
            worldPoint,
            mesh,
            localPoint,
            snapType: String(entry.snapType || 'auto')
        };
    });

    state.measurement.active = Boolean(saved?.active && points.some(Boolean));
    state.measurement.displayMode = ['orthogonal', 'robot-position'].includes(saved?.displayMode)
        ? saved.displayMode
        : 'diagonal';
    state.measurement.robotPositionRobotId = String(saved?.robotPositionRobotId || '') || null;
    state.measurement.snapType = String(saved?.snapType || 'auto');
    state.measurement.points = [points[0] || null, state.measurement.displayMode === 'robot-position'
        ? null
        : (points[1] || null)];
    state.measurement.result = null;
    state.measurement.hover = null;
    state.measurement.stale = savedPoints.length > points.filter(Boolean).length;
    if (state.measurement.displayMode === 'robot-position'
        && state.measurement.points[0] && !state.measurement.stale) {
        state.measurement.result = calculateRobotPositionMeasurement(state.measurement.points[0]);
    } else if (state.measurement.points[0] && state.measurement.points[1] && !state.measurement.stale) {
        const result = calculateMeasurementResult(
            state.measurement.points[0].worldPoint,
            state.measurement.points[1].worldPoint
        );
        state.measurement.result = result?.isSamePoint ? null : result;
    }
    if (state.measurement.active) {
        el.measurementPanel?.classList.remove('panel-user-hidden');
        updatePanelLauncher('measurement-panel');
        updatePanelStack();
        setMeasurementPanelStatus(state.measurement.displayMode === 'robot-position'
            ? (state.measurement.points[0] && state.measurement.result ? '측정 완료' : 'P1 선택')
            : (state.measurement.points[0] && state.measurement.points[1] ? '측정 완료' : 'P2 선택'));
    } else if (state.measurement.stale) {
        setMeasurementPanelStatus('측정 대상이 숨겨졌거나 삭제되었습니다. 다시 측정하세요.');
    } else {
        setMeasurementPanelStatus('P1 선택');
    }
    updateMeasurementUi();
    updateMeasurementOverlay();
    return {
        requested: savedPoints.length,
        restored: points.filter(Boolean).length
    };
}

function captureWorkspaceChildMatrices(model) {
    return [...(model?.children || [])].map((child, index) => {
        if (child.matrixAutoUpdate !== false) child.updateMatrix();
        return {
            index,
            matrix: child.matrix.toArray(),
            matrixAutoUpdate: child.matrixAutoUpdate !== false
        };
    });
}

function applyWorkspaceChildMatrices(model, records) {
    (Array.isArray(records) ? records : []).forEach((record) => {
        const child = model?.children?.[Number(record?.index)];
        if (!child || !Array.isArray(record.matrix) || record.matrix.length !== 16) return;
        child.matrix.fromArray(record.matrix);
        if (record.matrixAutoUpdate === false) {
            child.matrixAutoUpdate = false;
            child.matrixWorldNeedsUpdate = true;
        } else {
            child.matrix.decompose(child.position, child.quaternion, child.scale);
            child.matrixAutoUpdate = true;
        }
    });
    model?.updateMatrixWorld?.(true);
}

function getWorkspaceMaterialColor(material, mesh) {
    const partBaseline = mesh?.userData?.modelPartMaterials
        ?.find((entry) => entry.material === material)?.color;
    const collisionBaseline = state.collision.highlightedMaterials.get(material)?.color;
    const color = partBaseline || collisionBaseline || material?.color;
    return color?.isColor ? color.getHexString() : null;
}

function captureWorkspaceMaterialColors(model) {
    const records = [];
    model?.traverse?.((object) => {
        if (!object.isMesh || object.userData?.collisionDebugMesh || object.userData?.simulationSnapFaceOverlay) return;
        const path = getWorkspaceObjectPath(model, object);
        if (!path) return;
        records.push({
            path,
            colors: getMeshMaterials(object).map((material) => getWorkspaceMaterialColor(material, object))
        });
    });
    return records;
}

function applyWorkspaceMaterialColors(model, records) {
    (Array.isArray(records) ? records : []).forEach((record) => {
        const mesh = getWorkspaceObjectAtPath(model, record?.path);
        if (!mesh?.isMesh || !Array.isArray(record.colors)) return;
        ensureModelPartMaterialIsolation(mesh);
        getMeshMaterials(mesh).forEach((material, index) => {
            const colorHex = record.colors[index];
            if (!material?.color || typeof colorHex !== 'string' || !/^[0-9a-f]{6}$/i.test(colorHex)) return;
            material.color.setHex(Number.parseInt(colorHex, 16));
            material.needsUpdate = true;
            mesh.userData.modelPartMaterials?.forEach((entry) => {
                if (entry.material === material && entry.color) entry.color.copy(material.color);
            });
        });
    });
}

function captureWorkspacePartState(model) {
    return getImportedModelParts(model).map((part, index) => {
        if (part.matrixAutoUpdate !== false) part.updateMatrix();
        return {
            index,
            visible: part.visible !== false,
            transparency: getModelTransparencyPercent(part),
            matrix: part.matrix.toArray(),
            matrixAutoUpdate: part.matrixAutoUpdate !== false
        };
    });
}

function applyWorkspacePartState(model, records) {
    const parts = getImportedModelParts(model);
    (Array.isArray(records) ? records : []).forEach((record) => {
        const part = parts[Number(record?.index)];
        if (!part) return;
        part.visible = record.visible !== false;
        if (Array.isArray(record.matrix) && record.matrix.length === 16) {
            part.matrix.fromArray(record.matrix);
            if (record.matrixAutoUpdate === false) {
                part.matrixAutoUpdate = false;
                part.matrixWorldNeedsUpdate = true;
            } else {
                part.matrix.decompose(part.position, part.quaternion, part.scale);
                part.matrixAutoUpdate = true;
            }
        }
        if (record?.transparency !== undefined) {
            applyModelTransparencyVisual(model, part, record.transparency);
        }
    });
}

function getWorkspaceCatalogKey(model) {
    if (typeof model?.userData?.workspaceCatalogKey === 'string' && model.userData.workspaceCatalogKey) {
        return model.userData.workspaceCatalogKey;
    }
    return [...state.catalog.entries()].find(([, definition]) => (
        definition.type !== 'articulated-stl'
        && (definition.name === model?.userData?.modelName || definition.file === model?.userData?.modelName)
    ))?.[0] || null;
}

function serializeWorkspaceToolPartModel(model) {
    const source = normalizeToolAttachmentSource(model?.userData?.toolAttachmentSource);
    if (source?.mode !== 'part-copy') return null;
    const placement = model.userData.placement === 'tcp' ? 'tcp' : 'scene';
    return {
        kind: 'tool-part',
        workspaceModelId: ensureWorkspaceModelId(model),
        name: model.userData.modelName || model.name || '',
        placement,
        hostRobotInstanceId: model.userData.attachmentHost?.userData?.motionInstanceId || null,
        visible: isModelTreeVisible(model),
        transparency: getModelTransparencyPercent(model),
        toolLoadProperties: placement === 'tcp'
            ? normalizeToolLoadProperties(model.userData.toolLoadProperties)
            : null,
        toolAttachmentSource: source,
        transform: captureClipboardTransform(model)
    };
}

function serializeWorkspaceGripPartModel(model) {
    const source = normalizeGripObjectSource(model?.userData?.gripObjectSource);
    if (source?.mode !== 'part-copy') return null;
    const placement = isGripObjectModelInUse(model) ? 'grip-object' : 'scene';
    return {
        kind: 'grip-part',
        workspaceModelId: ensureWorkspaceModelId(model),
        name: model.userData.modelName || model.name || '',
        placement,
        hostRobotInstanceId: model.userData.attachmentHost?.userData?.motionInstanceId || null,
        visible: isModelTreeVisible(model),
        transparency: getModelTransparencyPercent(model),
        gripObjectSource: source,
        transform: captureClipboardTransform(model)
    };
}

function serializeWorkspaceSceneModel(model) {
    const workspaceModelId = ensureWorkspaceModelId(model);
    const transform = captureClipboardTransform(model);
    const toolPartRecord = serializeWorkspaceToolPartModel(model);
    if (toolPartRecord) return toolPartRecord;
    const gripPartRecord = serializeWorkspaceGripPartModel(model);
    if (gripPartRecord) return gripPartRecord;
    if (model.userData.cadExtrudeFeature) {
        const mesh = model.children.find((child) => child.userData?.sketchFeatureMesh && child.isMesh)
            || model.children.find((child) => child.isMesh);
        const material = Array.isArray(mesh?.material) ? mesh.material[0] : mesh?.material;
        return {
            kind: 'cad-extrude-feature',
            workspaceModelId,
            name: model.userData.modelName || model.name || '',
            generatedNameKey: model.userData.generatedNameKey || null,
            cadDocumentId: model.userData.cadDocumentId || null,
            cadProfileEntityId: model.userData.cadProfileEntityId || null,
            cadProfileEntityIds: [...(model.userData.cadProfileEntityIds || [])],
            cadProfileHoleEntityIds: [...(model.userData.cadProfileHoleEntityIds || [])],
            cadProfileRegionId: model.userData.cadProfileRegionId || null,
            cadProfileType: model.userData.cadProfileType || '',
            cadProfilePoints: (model.userData.cadProfilePoints || []).map((point) => [...point]),
            cadProfileHolePoints: (model.userData.cadProfileHolePoints || []).map((loop) => loop.map((point) => [...point])),
            cadProfileGeometry: model.userData.cadProfileGeometry || null,
            sketchExtrudeDepth: Number(model.userData.sketchExtrudeDepth) || 0,
            visible: isModelTreeVisible(model),
            transform,
            materialColor: getSketchFeatureDisplayColor(
                model,
                isSketchOnlyModel(model) ? '#c4b5fd' : '#bfc7d5'
            )
        };
    }
    if (isCad2dModel(model)) {
        const document = model.userData.cadDocument;
        return {
            kind: 'cad-2d',
            workspaceModelId,
            assetId: model.userData.workspaceAssetId || null,
            name: model.userData.modelName || model.name || '',
            sourceExtension: model.userData.sourceExtension || document.source?.extension || '',
            sourceUnit: document.source?.sourceUnit || 'unknown',
            sourceFileSize: Number(document.source?.size || model.userData.sourceFileSize) || 0,
            visible: isModelTreeVisible(model),
            cadDocumentVisible: model.visible !== false,
            cadCentered: Boolean(model.userData.cadCentered),
            cadOriginOffset: normalizeCadOriginOffset(model.userData.cadOriginOffset).toArray(),
            cadLayerVisibility: { ...(model.userData.cadLayerVisibility || {}) },
            transform,
            cadDocument: model.userData.workspaceAssetId ? null : document
        };
    }
    if (isSketchFeatureModel(model)) {
        return {
            kind: 'sketch-feature',
            workspaceModelId,
            name: model.userData.modelName || model.name || '',
            generatedNameKey: model.userData.generatedNameKey || null,
            sketchFeatureType: model.userData.sketchFeatureType || 'extrude',
            sketchFeatureNameIndex: Number(model.userData.sketchFeatureNameIndex) || null,
            sketchDocument: model.userData.sketchDocument
                ? normalizeSketchDocument(model.userData.sketchDocument)
                : null,
            sketchProfiles: (model.userData.sketchProfiles || []).map((profile) => serializeSketchEntity(profile)).filter(Boolean),
            sketchExtrudeDepth: isSketchOnlyModel(model)
                ? null
                : Number(model.userData.sketchExtrudeDepth) || 0,
            sketchFeatureOriginOffset: getSketchFeatureOriginOffset(model).toArray(),
            sketchCutFeature: serializeSketchCutFeature(model.userData.sketchCutFeature),
            visible: isModelTreeVisible(model),
            transform,
            materialColor: getSketchFeatureDisplayColor(
                model,
                isSketchOnlyModel(model) ? '#c4b5fd' : '#bfc7d5'
            )
        };
    }
    if (isPrimitiveShapeModel(model)) {
        const mesh = getPrimitiveShapeMesh(model);
        const material = Array.isArray(mesh?.material) ? mesh.material[0] : mesh?.material;
        const record = serializePrimitiveShapeRecord({
            workspaceModelId,
            name: model.userData.modelName || model.name || '',
            primitiveShapeNameIndex: getPrimitiveShapeNameIndex(model),
            primitiveShapeType: model.userData.primitiveShapeType,
            primitiveShapeDimensions: getPrimitiveShapeDimensions(model),
            transform,
            visible: isModelTreeVisible(model),
            materialColor: material?.color?.getHexString ? `#${material.color.getHexString()}` : '#bfc7d5',
        });
        if (model.userData.sketchCutFeature) {
            record.sketchCutFeature = serializeSketchCutFeature(model.userData.sketchCutFeature);
        }
        if (model.userData.placement !== 'tcp' && model.userData.placement !== 'grip-object') return record;
        return {
            ...record,
            placement: model.userData.placement,
            hostRobotInstanceId: model.userData.attachmentHost?.userData?.motionInstanceId || null,
            ...(model.userData.placement === 'tcp' ? {
                toolLoadProperties: normalizeToolLoadProperties(model.userData.toolLoadProperties),
                toolAttachmentSource: normalizeToolAttachmentSource(model.userData.toolAttachmentSource)
            } : {
                gripObjectSource: normalizeGripObjectSource(model.userData.gripObjectSource)
            })
        };
    }
    if (model.userData.uploaded) {
        const placement = model.userData.placement === 'tcp' || model.userData.placement === 'arm-load' || model.userData.placement === 'grip-object'
            ? model.userData.placement
            : 'scene';
        return {
            kind: 'uploaded',
            workspaceModelId,
            assetId: model.userData.workspaceAssetId || null,
            name: model.userData.modelName || model.name || '',
            placement,
            hostRobotInstanceId: model.userData.attachmentHost?.userData?.motionInstanceId || null,
            attachmentJointIndex: placement === 'arm-load' ? getArmLoadJointIndex(model) : null,
            attachmentAxis: placement === 'arm-load' ? `J${getArmLoadJointIndex(model) + 1}` : null,
            visible: isModelTreeVisible(model),
            transparency: getModelTransparencyPercent(model),
            armLoadProperties: placement === 'arm-load'
                ? normalizeArmLoadProperties(model.userData.armLoadProperties)
                : null,
            toolLoadProperties: placement === 'tcp'
                ? normalizeToolLoadProperties(model.userData.toolLoadProperties)
                : null,
            toolAttachmentSource: placement === 'tcp'
                ? normalizeToolAttachmentSource(model.userData.toolAttachmentSource)
                : null,
            gripObjectSource: placement === 'grip-object'
                ? normalizeGripObjectSource(model.userData.gripObjectSource)
                : null,
            transform,
            sourceExtension: model.userData.sourceExtension || '',
            sourceUnit: model.userData.sourceUnit || 'mm',
            sourceUpAxis: model.userData.sourceUpAxis || '',
            sourceFileSize: Number(model.userData.sourceFileSize) || 0,
            importQuality: model.userData.importQuality || 'auto',
            largeModelMode: Boolean(model.userData.largeModelMode),
            testModel: Boolean(model.userData.testModel),
            sceneModelAnchor: model.userData.sceneModelAnchor || '',
            childMatrices: captureWorkspaceChildMatrices(model),
            partState: captureWorkspacePartState(model),
            materialColors: captureWorkspaceMaterialColors(model)
        };
    }
    return {
        kind: 'catalog',
        workspaceModelId,
        catalogKey: getWorkspaceCatalogKey(model),
        name: model.userData.modelName || model.name || '',
        visible: isModelTreeVisible(model),
        transform
    };
}

function serializeWorkspaceOlpProject(robot = getOlpRobot(), project = getOlpProject(robot)) {
    if (!project?.files) return null;
    const instanceId = getOlpRobotInstanceId(robot) || null;
    const activeRobot = getOlpRobot();
    const isActiveRobot = robot === activeRobot;
    return {
        schemaVersion: 1,
        robotInstanceId: instanceId,
        name: String(project.name || 'OLP Project'),
        programPath: project.programPath || null,
        selectedFile: isActiveRobot
            ? state.olp.selectedFile || ''
            : instanceId ? state.olp.selectedFiles.get(instanceId) || '' : '',
        enabled: Boolean(state.olp.enabled),
        projectDirty: isActiveRobot
            ? Boolean(state.olp.projectDirty)
            : instanceId ? Boolean(state.olp.projectDirtyByRobot.get(instanceId)) : false,
        files: [...project.files.values()].map((record) => ({
            path: String(record.path || ''),
            binary: Boolean(record.binary),
            text: record.binary ? null : String(record.text ?? ''),
            assetId: record.binary ? (record.workspaceAssetId || null) : null,
            name: String(record.file?.name || record.path?.split('/').at(-1) || ''),
            type: String(record.file?.type || (record.binary ? 'application/octet-stream' : 'text/plain')),
            size: Math.max(0, Number(record.file?.size) || 0),
            lastModified: Math.max(0, Number(record.file?.lastModified) || 0)
        }))
    };
}

function serializeWorkspaceSnapshot() {
    flushOlpPendingEdit();
    const robots = getArticulatedRobots();
    state.models.forEach(ensureWorkspaceModelId);
    const sceneModels = state.models
        .filter((model) => !robots.includes(model))
        .map(serializeWorkspaceSceneModel);
    const selectedPartIndex = state.selectedModel
        ? getImportedModelParts(state.selectedModel).indexOf(state.selectedModelPart)
        : -1;
    const motionProject = serializeMotionProject();
    const cameraChanged = state.camera && state.controls && (
        state.camera.position.distanceToSquared(new THREE.Vector3(1400, -1400, 1000)) > 1e-8
        || state.controls.target.lengthSq() > 1e-8
        || state.camera.up.distanceToSquared(new THREE.Vector3(0, 0, 1)) > 1e-8
        || Math.abs((Number(state.camera.zoom) || 1) - 1) > 1e-8
    );
    const interferenceChanged = JSON.stringify(state.interferenceZones)
        !== JSON.stringify(normalizeInterferenceZones());
    const monitoringChanged = JSON.stringify(state.endMonitoringObjects)
        !== JSON.stringify(normalizeEndMonitoringObjects());
    const simulationIoChanged = state.simulationIo.inputs.some(Boolean)
        || state.simulationIo.outputs.some(Boolean);
    const ioFunctionMappingsChanged = state.ioFunctionMappings.length > 0;
    const measurement = serializeWorkspaceMeasurement();
    const olpProjects = serializeWorkspaceOlpProjects();
    const activeOlpProject = olpProjects.find((project) => (
        project.robotInstanceId === getOlpRobotInstanceId(getOlpRobot())
    )) || olpProjects[0] || null;
    // Keep the original singular field for older saved workspaces and tools.
    const olpProject = activeOlpProject;
    const hasWork = state.models.length > 0
        || olpProjects.length > 0
        || state.viewPresets.some(Boolean)
        || state.grid?.visible === false
        || state.outlineMode
        || state.collision.enabled
        || cameraChanged
        || interferenceChanged
        || monitoringChanged
        || simulationIoChanged
        || ioFunctionMappingsChanged
        || Boolean(state.tcpPath.enabled)
        || measurement.points.length > 0;
    return {
        schemaVersion: 1,
        hasWork,
        motionProject,
        robotRuntime: robots.map((robot) => ({
            instanceId: robot.userData.motionInstanceId,
            workspaceModelId: ensureWorkspaceModelId(robot),
            jointAngles: robot.userData.joints.map((joint) => Number(joint.angle) || 0),
            transparency: getModelTransparencyPercent(robot),
            visible: isModelTreeVisible(robot)
        })),
        simulationIo: {
            inputs: state.simulationIo.inputs.map(Boolean),
            outputs: state.simulationIo.outputs.map(Boolean)
        },
        ioFunctionMappings: cloneIoFunctionMappings(state.ioFunctionMappings),
        tcpPath: {
            enabled: Boolean(state.tcpPath.enabled)
        },
        measurement,
        programSelection: robots.map((robot) => ({
            instanceId: robot.userData.motionInstanceId,
            selectedStepId: ensureMotionProgram(robot).selectedStepId || null
        })),
        importedModels: sceneModels.filter((model) => model.kind === 'uploaded' || model.kind === 'primitive-shape' || model.kind === 'sketch-feature' || model.kind === 'cad-2d' || model.kind === 'cad-extrude-feature' || model.kind === 'grip-part'),
        catalogModels: sceneModels.filter((model) => model.kind === 'catalog'),
        olpProject,
        olpProjects,
        assetIds: [...new Set([
            ...sceneModels
                .filter((model) => (model.kind === 'uploaded' || model.kind === 'cad-2d') && model.assetId)
                .map((model) => model.assetId),
            ...olpProjects.flatMap((project) => project.files || [])
                .filter((file) => file.binary && file.assetId)
                .map((file) => file.assetId)
        ])],
        selection: {
            selectedModelId: state.selectedModel ? ensureWorkspaceModelId(state.selectedModel) : null,
            selectedPartIndex: selectedPartIndex >= 0 ? selectedPartIndex : null,
            activeRobotInstanceId: state.activeArticulatedModel?.userData?.motionInstanceId || null,
            activeProgramRobotInstanceId: state.activeProgramRobot?.userData?.motionInstanceId || null
        },
        camera: state.camera && state.controls ? {
            position: state.camera.position.toArray(),
            target: state.controls.target.toArray(),
            up: state.camera.up.toArray(),
            zoom: Number.isFinite(state.camera.zoom) ? state.camera.zoom : 1,
            viewMode: state.sketch.active ? 'sketch' : '3d'
        } : null,
        display: {
            gridVisible: state.grid?.visible !== false,
            outlineMode: Boolean(state.outlineMode),
            collisionMode: state.collision.mode,
            collisionEnabled: Boolean(state.collision.enabled)
        },
        viewConfiguration: serializeViewConfiguration(),
        collapsedModelIds: state.models
            .filter((model) => state.modelTreeCollapsedIds.has(ensureModelTreeId(model)))
            .map((model) => ensureWorkspaceModelId(model))
    };
}

function serializeMotionProject() {
    return {
        schemaVersion: MOTION_PROJECT_SCHEMA_VERSION,
        repeatCurrentRobot: state.motionRepeatRobot,
        repeat: state.motionRepeat,
        reverseRepeatCurrentRobot: state.motionReverseRepeatRobot,
        reverseRepeat: state.motionReverseRepeat,
        robotInterferenceAvoidance: {
            enabled: Boolean(state.robotInterferenceAvoidance.enabled),
            priorityRobotId: state.robotInterferenceAvoidance.priorityRobotId || null
        },
        interferenceZones: cloneInterferenceZones(state.interferenceZones),
        endMonitoringObjects: cloneEndMonitoringObjects(state.endMonitoringObjects),
        robots: getArticulatedRobots().map((robot) => {
            const program = ensureMotionProgram(robot);
            return {
                instanceId: robot.userData.motionInstanceId,
                modelFolder: robot.userData.motionModelFolder,
                displayName: robot.userData.motionDisplayName,
                instanceNumber: robot.userData.robotInstanceNumber,
                robotType: robot.userData.motionRobotType || robot.userData.manifest?.robotType,
                jointCount: robot.userData.joints.length,
                included: program.included,
                workOrigin: program.workOrigin
                    ? {
                        mode: program.workOrigin.mode,
                        joints: [...program.workOrigin.joints],
                        tcp: {
                            position: [...program.workOrigin.tcp.position],
                            quaternion: [...program.workOrigin.tcp.quaternion]
                        },
                        outputBit: program.workOrigin.outputBit
                    }
                    : null,
                externalAxes: getRobotExternalAxes(robot),
                baseTransform: {
                    position: robot.position.toArray(),
                    quaternion: robot.quaternion.toArray(),
                    scale: robot.scale.toArray()
                },
                tcpProfiles: serializeRobotTcpProfiles(robot),
                activeTcpProfileIndex: robot.userData.activeTcpProfileIndex,
                workObjects: serializeRobotWorkObjects(robot),
                activeWorkObjectIndex: robot.userData.activeWorkObjectIndex,
                steps: program.steps.map((step) => ({
                    id: step.id,
                    name: step.name,
                    motion: step.motion,
                    ...(isMotionPointMotion(step.motion) ? {
                        pointIndex: step.pointIndex,
                        label: step.label || '',
                        armParameters: [...(step.armParameters || calculatePointArmParameters(robot, step.joints))],
                        externalAxes: [...(step.externalAxes || [0, 0, 0, 0, 0, 0])]
                    } : {}),
                    ...(step.motion === 'DELAY'
                        ? { delaySeconds: step.delaySeconds }
                        : step.motion === 'MOVJ' || step.motion === 'MOVL'
                            ? { speed: step.speed }
                            : step.motion === 'VIEW'
                            ? { viewSlot: step.viewSlot }
                            : isWaitMotion(step.motion)
                                ? {
                                    waitRobotInstanceId: step.waitRobotInstanceId,
                                    waitLineNumber: step.waitLineNumber
                                }
                            : isGripObjectMotion(step.motion)
                                ? { gripObjectRef: step.gripObjectRef }
                            : {}),
                    joints: [...step.joints],
                    tcp: {
                        position: [...step.tcp.position],
                        quaternion: [...step.tcp.quaternion]
                    }
                }))
            };
        })
    };
}

async function persistImportedWorkspaceAsset(file, extension = getFileExtension(file?.name)) {
    const recovery = state.workspaceRecovery;
    if (!file || !recovery.db || !recovery.ready || recovery.restoring) {
        throw new Error('Workspace recovery storage is not ready.');
    }
    try { await navigator.storage?.persist?.(); } catch { }
    try {
        const estimate = await navigator.storage?.estimate?.();
        const remaining = Number(estimate?.quota) - Number(estimate?.usage);
        const required = Number(file.size) * 1.1 + (8 * MEBIBYTE);
        if (Number.isFinite(remaining) && remaining < required) {
            throw new DOMException('Workspace storage quota is insufficient.', 'QuotaExceededError');
        }
    } catch (error) {
        if (WorkspaceRecovery.isWorkspaceQuotaError(error)) throw error;
        console.warn('Workspace storage capacity could not be estimated:', error);
    }
    const assetId = WorkspaceRecovery.createWorkspaceId('asset');
    const blob = typeof file.slice === 'function'
        ? file.slice(0, file.size, file.type || '')
        : file;
    const asset = await recovery.db.putAsset({
        id: assetId,
        name: file.name,
        type: file.type || blob.type || '',
        size: file.size,
        lastModified: file.lastModified || Date.now(),
        extension,
        blob
    });
    return asset.id;
}

function clearSceneForWorkspaceRestore() {
    if (state.sketch.active) exitSketchMode({ restoreCamera: false });
    if (state.zeroPointEdit.active) exitZeroPointEditor();
    closeToolLoadInfoPanel();
    clearTcpPathOverlay();
    setSelectedTransformMode('translate', false);
    setTransformHandlesEnabled(true);
    setBaseJogGizmoEnabled(false);
    invalidateSimulationSnapCandidates();
    state.models.forEach((model) => {
        disposeCollisionDebugForModel(model);
        disposeModelOutlines(model);
        if (isPrimitiveShapeModel(model) || isSketchFeatureModel(model) || isCad2dModel(model)) disposeObjectResources(model);
        model.removeFromParent();
    });
    disposePrimitiveDimensionOverlay();
    state.models = [];
    state.cad2d.documents.clear();
    state.cad2d.activeDocumentId = null;
    state.cad2d.selectedEntityIds.clear();
    state.cad2d.hoveredEntityId = null;
    state.motionPrograms.clear();
    state.motionSessions.clear();
    state.selectedModel = null;
    state.selectedModelPart = null;
    state.activeArticulatedModel = null;
    state.activeProgramRobot = null;
    state.modelTreeCollapsedIds.clear();
    state.ioFunctionMappings = [];
    state.ioFunctionMappingRuntimeValues.clear();
    markSceneCollisionDirty();
}

function restoreWorkspaceViewConfiguration(configuration) {
    state.viewPresets = Array.from({ length: VIEW_PRESET_COUNT }, () => null);
    const presets = Array.isArray(configuration) ? configuration : configuration?.viewPresets;
    if (Array.isArray(presets)) {
        presets.slice(0, VIEW_PRESET_COUNT).forEach((preset, slot) => {
            if (!isValidViewPreset(preset)) return;
            state.viewPresets[slot] = {
                name: String(preset.name || getDefaultViewPresetName(slot)).slice(0, 24),
                camera: {
                    position: preset.camera.position.map(Number),
                    target: preset.camera.target.map(Number),
                    up: preset.camera.up.map(Number),
                    zoom: Number.isFinite(Number(preset.camera.zoom)) ? Number(preset.camera.zoom) : 1
                }
            };
        });
    }
    state.activeViewSlot = null;
    refreshViewPresetsUi();
}

function isSketchCameraState(cameraState) {
    if (!cameraState || typeof cameraState !== 'object') return false;
    if (cameraState.viewMode === 'sketch') return true;
    if (Object.prototype.hasOwnProperty.call(cameraState, 'viewMode')) return false;
    const position = Array.isArray(cameraState.position) ? cameraState.position.map(Number) : null;
    const target = Array.isArray(cameraState.target) ? cameraState.target.map(Number) : null;
    const up = Array.isArray(cameraState.up) ? cameraState.up.map(Number) : null;
    if (!position || position.length !== 3 || !position.every(Number.isFinite)
        || !target || target.length !== 3 || !target.every(Number.isFinite)
        || !up || up.length !== 3 || !up.every(Number.isFinite)) return false;
    const isXAxisUp = Math.abs(Math.abs(up[0]) - 1) < 1e-4
        && Math.abs(up[1]) < 1e-4
        && Math.abs(up[2]) < 1e-4;
    const horizontalDistance = Math.hypot(position[0] - target[0], position[1] - target[1]);
    const verticalDistance = Math.abs(position[2] - target[2]);
    return isXAxisUp && verticalDistance > Math.max(1, horizontalDistance * 8);
}

function resetMainOrbitControlsForWorkspaceView() {
    if (!state.camera || !state.controls) return;
    const target = state.controls.target.clone();
    const previousControls = captureMainOrbitControlState(state.controls) || {};
    state.camera.up.set(0, 0, 1);
    state.camera.lookAt(target);
    state.camera.updateProjectionMatrix();
    recreateMainOrbitControls({
        ...previousControls,
        enabled: true,
        enableRotate: true,
        enablePan: true,
        enableZoom: true,
        enableDamping: false,
        screenSpacePanning: true,
        mouseButtons: {
            LEFT: THREE.MOUSE.ROTATE,
            MIDDLE: THREE.MOUSE.DOLLY,
            RIGHT: THREE.MOUSE.PAN
        },
        touches: {
            ONE: THREE.TOUCH.ROTATE,
            TWO: THREE.TOUCH.DOLLY_PAN
        },
        zoomToCursor: false,
        target
    });
    state.controls.target.copy(target);
    state.controls.update();
}

function applyWorkspaceDisplayState(snapshot) {
    const display = snapshot?.display || {};
    const gridVisible = display.gridVisible !== false;
    if (state.grid) state.grid.visible = gridVisible;
    if (state.baseAxes) state.baseAxes.visible = gridVisible;
    state.labels.forEach((label) => { label.visible = gridVisible; });
    el.btnToggleGrid?.classList.toggle('active', gridVisible);
    setCollisionModeState(display.collisionMode, display.collisionEnabled === true);
    clearCollisionStopNotice();
    updateCollisionUi();
    setModelOutlineMode(display.outlineMode !== false);
}

function applyWorkspaceCameraState(cameraState) {
    if (!state.camera || !state.controls || !cameraState) return;
    const loadedSketchCamera = isSketchCameraState(cameraState);
    if (Array.isArray(cameraState.position) && cameraState.position.length === 3) {
        state.camera.position.fromArray(cameraState.position);
    }
    if (Array.isArray(cameraState.target) && cameraState.target.length === 3) {
        state.controls.target.fromArray(cameraState.target);
    }
    if (Array.isArray(cameraState.up) && cameraState.up.length === 3) {
        state.camera.up.fromArray(cameraState.up);
    }
    if (Number.isFinite(Number(cameraState.zoom)) && Number(cameraState.zoom) > 0) {
        state.camera.zoom = Number(cameraState.zoom);
        state.camera.updateProjectionMatrix();
    }
    state.camera.lookAt(state.controls.target);
    state.controls.update();
    if (loadedSketchCamera) resetMainOrbitControlsForWorkspaceView();
}

function findWorkspaceCatalogDefinition(entry) {
    const direct = state.catalog.get(entry?.catalogKey);
    if (direct?.type !== 'articulated-stl') return direct;
    return [...state.catalog.values()].find((definition) => (
        definition.type !== 'articulated-stl'
        && (definition.name === entry?.name || definition.file === entry?.catalogKey)
    )) || null;
}

async function restoreWorkspaceCatalogModel(entry) {
    const definition = findWorkspaceCatalogDefinition(entry);
    if (!definition) throw new Error(`Catalog model is unavailable: ${entry?.name || entry?.catalogKey || ''}`);
    const model = await loadModelFromServer(definition, {
        append: true,
        suppressHistory: true,
        suppressFit: true,
        preserveActive: true,
        preserveSelection: true,
        throwOnError: true,
        transform: entry.transform,
        workspaceModelId: entry.workspaceModelId
    });
    applyModelTreeVisibilityVisual(model, entry.visible !== false);
    return model;
}

function restoreWorkspacePrimitiveShape(entry, robotsById = new Map()) {
    const record = normalizePrimitiveShapeRecord(entry);
    if (!record) throw new Error('Saved primitive shape data is invalid.');
    const placement = entry.placement === 'tcp' || entry.placement === 'grip-object'
        ? entry.placement
        : 'scene';
    const robot = placement === 'tcp' || placement === 'grip-object'
        ? robotsById.get(entry.hostRobotInstanceId) || null
        : null;
    const attachmentFrame = placement === 'tcp' || placement === 'grip-object'
        ? getRobotToolMountFrame(robot)
        : null;
    if ((placement === 'tcp' || placement === 'grip-object') && !attachmentFrame) {
        throw new Error('The saved robot attachment point is unavailable.');
    }
    const model = createPrimitiveShapeRoot(
        record.primitiveShapeType,
        record.primitiveShapeDimensions,
        {
            name: record.name,
            primitiveShapeNameIndex: record.primitiveShapeNameIndex,
            workspaceModelId: record.workspaceModelId,
            visible: placement === 'tcp' ? true : record.visible,
            materialColor: record.materialColor,
            transform: record.transform,
            sketchCutFeature: entry.sketchCutFeature || null
        }
    );
    if (attachmentFrame) {
        attachmentFrame.add(model);
        model.userData.attachmentHost = robot;
        model.userData.attachmentFrame = placement === 'grip-object' ? 'grip' : 'flange';
        model.userData.placement = placement;
        if (placement === 'tcp') {
            model.userData.toolLoadProperties = normalizeToolLoadProperties(entry.toolLoadProperties);
            const toolAttachmentSource = normalizeToolAttachmentSource(entry.toolAttachmentSource);
            if (toolAttachmentSource) model.userData.toolAttachmentSource = toolAttachmentSource;
        } else {
            const gripObjectSource = normalizeGripObjectSource(entry.gripObjectSource);
            if (gripObjectSource) model.userData.gripObjectSource = gripObjectSource;
        }
    } else {
        state.scene.add(model);
        model.userData.placement = 'scene';
    }
    model.visible = record.visible !== false;
    state.models.push(model);
    updateModelRenderComplexity(model);
    if (state.collision.enabled) state.collision.system?.prepare([model]);
    markSceneCollisionDirty(model);
    return model;
}

function restoreWorkspaceSketchFeature(entry) {
    const sketchOnly = entry?.sketchFeatureType === 'sketch';
    const entities = (Array.isArray(entry?.sketchProfiles) ? entry.sketchProfiles : [])
        .map(normalizeSketchEntityRecord)
        .filter(Boolean);
    const profiles = entities.filter((profile) => profile.type !== 'line');
    const depth = Number(entry?.sketchExtrudeDepth);
    if (!entities.length || (!sketchOnly && (
        !profiles.length || !Number.isFinite(depth) || depth < SKETCH_MIN_SIZE || depth > SKETCH_MAX_SIZE
    ))) {
        throw new Error('Saved sketch feature data is invalid.');
    }
    const generatedNameKey = entry.generatedNameKey || (
        /^스케치 돌출\s+\d+$/.test(String(entry.name || ''))
            ? '스케치 돌출'
            : /^스케치\s+\d+$/.test(String(entry.name || '')) ? '스케치' : null
    );
    const model = createSketchFeatureRoot(sketchOnly ? entities : profiles, sketchOnly ? null : depth, {
        sketchOnly,
        name: generatedNameKey ? null : String(entry.name || `${uiText(sketchOnly ? '스케치' : '스케치 돌출')} ${getNextSketchFeatureNameIndex()}`),
        generatedNameKey,
        sketchFeatureNameIndex: Number(entry.sketchFeatureNameIndex),
        sketchDocument: entry.sketchDocument ? normalizeSketchDocument(entry.sketchDocument) : null,
        workspaceModelId: entry.workspaceModelId,
        visible: entry.visible !== false,
        materialColor: entry.materialColor,
        transform: entry.transform,
        sketchCutFeature: entry.sketchCutFeature || null
    });
    if (!Array.isArray(entry.sketchFeatureOriginOffset) && entry.transform?.position) {
        model.position.add(transformSketchFeatureLocalVectorToWorld(model, getSketchFeatureOriginOffset(model)));
    }
    state.scene.add(model);
    model.userData.placement = 'scene';
    state.models.push(model);
    updateModelRenderComplexity(model);
    if (state.collision.enabled) state.collision.system?.prepare([model]);
    markSceneCollisionDirty(model);
    return model;
}

async function restoreWorkspaceCad2d(entry) {
    let asset = null;
    if (entry?.assetId) asset = await state.workspaceRecovery.db.getAsset(entry.assetId, { touch: true });
    if (!asset?.blob && !entry?.cadDocument) return null;
    const file = asset?.blob
        ? new File([asset.blob], asset.name, {
            type: asset.type || asset.blob.type || 'application/dxf',
            lastModified: asset.lastModified || Date.now()
        })
        : new File([], entry.name || 'workspace.dxf', { type: 'application/dxf' });
    const model = await handleCad2DImport({
        file,
        cadDocument: entry.cadDocument || null,
        unitOverride: entry.sourceUnit || 'auto',
        visible: entry.visible !== false,
        centerDrawing: false,
        cadOriginOffset: entry.cadOriginOffset,
        workspaceAssetId: asset?.id || entry.assetId || null,
        workspaceModelId: entry.workspaceModelId,
        transform: entry.transform,
        skipAssetPersistence: true,
        suppressHistory: true,
        suppressFit: true,
        preserveSelection: true,
        suppressSuccessStatus: true,
        suppressErrorAlert: true,
        throwOnError: true
    });
    if (!model) throw new Error(`CAD document could not be restored: ${entry.name || '2D CAD'}`);
    Object.entries(entry.cadLayerVisibility || {}).forEach(([layerId, visible]) => {
        setCadLayerVisibility(model, layerId, visible);
    });
    model.visible = entry.cadDocumentVisible !== false && entry.visible !== false;
    model.userData.cadCentered = Boolean(entry.cadCentered);
    model.userData.cadOriginOffset = normalizeCadOriginOffset(entry.cadOriginOffset).toArray();
    return model;
}

function restoreWorkspaceCadExtrudeFeature(entry) {
    const documentId = entry?.cadDocumentId;
    const documentEntry = getCadDocumentEntry(documentId);
    if (!documentEntry) throw new Error('The source CAD document is unavailable.');
    const entity = documentEntry.document.entities.find((candidate) => candidate.id === entry.cadProfileEntityId);
    if (!entity) throw new Error('The saved CAD profile is unavailable.');
    const profileRegion = (documentEntry.root.userData?.cadFaceRegions || []).find((region) => (
        (entry.cadProfileRegionId && region.id === entry.cadProfileRegionId)
        || (Array.isArray(entry.cadProfileEntityIds) && JSON.stringify(region.entityIds) === JSON.stringify(entry.cadProfileEntityIds))
    )) || null;
    const previousDocumentId = state.cad2d.activeDocumentId;
    state.cad2d.activeDocumentId = documentId;
    try {
        const generatedNameKey = entry.generatedNameKey || (/^CAD 돌출\s+\d+$/.test(String(entry.name || '')) ? 'CAD 돌출' : null);
        const model = createCadExtrudeFeatureRoot(entity, Number(entry.sketchExtrudeDepth), {
            name: generatedNameKey ? null : (entry.name || `${uiText('CAD 돌출')} ${getNextSketchFeatureNameIndex()}`),
            generatedNameKey,
            workspaceModelId: entry.workspaceModelId,
            visible: entry.visible !== false,
            materialColor: entry.materialColor,
            transform: entry.transform,
            region: profileRegion
        });
        state.scene.add(model);
        state.models.push(model);
        if (state.collision.enabled) state.collision.system?.prepare([model]);
        markSceneCollisionDirty(model);
        updateModelRenderComplexity(model);
        return model;
    } finally {
        state.cad2d.activeDocumentId = previousDocumentId || documentId;
    }
}

function restoreWorkspaceToolPart(entry, robotsById = new Map()) {
    const source = normalizeToolAttachmentSource(entry.toolAttachmentSource);
    if (source?.mode !== 'part-copy') throw new Error('Saved Tool part source data is invalid.');
    const sourceModel = findModelByWorkspaceId(source.sourceModelId);
    const sourcePart = sourceModel
        ? getImportedModelParts(sourceModel).find((part) => part.userData.modelPartId === source.sourcePartId)
            || getImportedModelParts(sourceModel)[source.sourcePartIndex]
        : null;
    const robot = entry.placement === 'tcp'
        ? robotsById.get(entry.hostRobotInstanceId) || null
        : null;
    const attachmentFrame = entry.placement === 'tcp'
        ? getRobotToolMountFrame(robot)
        : null;
    if (!sourcePart || !sourceModel || !attachmentFrame) {
        throw new Error('The saved Tool source part or robot is unavailable.');
    }

    const model = cloneClipboardObjectTemplate(sourcePart);
    model.name = `Tool: ${entry.name || sourcePart.userData.modelPartName || sourcePart.name || uiText('PART')}`;
    model.userData.modelName = entry.name || sourcePart.userData.modelPartName || sourcePart.name || uiText('PART');
    model.userData.uploaded = true;
    model.userData.sourceExtension = 'part-copy';
    model.userData.sourceUnit = 'mm';
    model.userData.sourceUpAxis = 'tool';
    model.userData.toolLoadProperties = normalizeToolLoadProperties(entry.toolLoadProperties);
    model.userData.toolAttachmentSource = source;
    ensureWorkspaceModelId(model, entry.workspaceModelId);
    ensureModelTreeId(model);
    attachmentFrame.add(model);
    applyClipboardTransform(model, entry.transform || {
        position: [0, 0, 0],
        quaternion: [0, 0, 0, 1],
        scale: [1, 1, 1]
    });
    model.userData.attachmentHost = robot;
    model.userData.attachmentFrame = 'flange';
    model.userData.placement = 'tcp';
    model.visible = entry.visible !== false;
    sourcePart.visible = false;
    state.models.push(model);
    updateModelRenderComplexity(model);
    if (state.collision.enabled) state.collision.system?.prepare([model]);
    markSceneCollisionDirty(sourceModel);
    return model;
}

function restoreWorkspaceGripPart(entry, robotsById = new Map()) {
    const source = normalizeGripObjectSource(entry.gripObjectSource);
    if (source?.mode !== 'part-copy') throw new Error('Saved grip object part source data is invalid.');
    const sourceModel = findModelByWorkspaceId(source.sourceModelId);
    const sourcePart = sourceModel
        ? getImportedModelParts(sourceModel).find((part) => part.userData.modelPartId === source.sourcePartId)
            || getImportedModelParts(sourceModel)[source.sourcePartIndex]
        : null;
    if (!sourceModel || !sourcePart) throw new Error('The saved grip object source part is unavailable.');
    const placement = entry.placement === 'grip-object' ? 'grip-object' : 'scene';
    const robot = placement === 'grip-object'
        ? robotsById.get(entry.hostRobotInstanceId) || null
        : null;
    const attachmentFrame = placement === 'grip-object'
        ? getRobotToolMountFrame(robot)
        : null;
    if (placement === 'grip-object' && !attachmentFrame) {
        throw new Error('The saved grip object robot is unavailable.');
    }
    const model = cloneClipboardObjectTemplate(sourcePart);
    model.name = `Grip: ${entry.name || sourcePart.userData.modelPartName || sourcePart.name || uiText('PART')}`;
    model.userData.modelName = entry.name || sourcePart.userData.modelPartName || sourcePart.name || uiText('PART');
    model.userData.uploaded = true;
    model.userData.sourceExtension = 'grip-part';
    model.userData.sourceUnit = 'mm';
    model.userData.sourceUpAxis = 'tool';
    model.userData.gripObjectSource = source;
    ensureWorkspaceModelId(model, entry.workspaceModelId);
    ensureModelTreeId(model);
    if (attachmentFrame) {
        attachmentFrame.add(model);
        model.userData.attachmentHost = robot;
        model.userData.attachmentFrame = 'grip';
        model.userData.placement = 'grip-object';
    } else {
        state.scene.add(model);
        model.userData.placement = 'scene';
    }
    applyClipboardTransform(model, entry.transform || {
        position: [0, 0, 0],
        quaternion: [0, 0, 0, 1],
        scale: [1, 1, 1]
    });
    model.visible = entry.visible !== false;
    sourcePart.visible = false;
    state.models.push(model);
    updateModelRenderComplexity(model);
    if (state.collision.enabled) state.collision.system?.prepare([model]);
    markSceneCollisionDirty(sourceModel);
    return model;
}

async function restoreWorkspaceImportedModel(entry, robotsById) {
    const asset = await state.workspaceRecovery.db.getAsset(entry.assetId, { touch: true });
    if (!asset?.blob) return null;
    const needsRobotAttachment = entry.placement === 'tcp' || entry.placement === 'arm-load' || entry.placement === 'grip-object';
    const attachmentRobot = needsRobotAttachment
        ? robotsById.get(entry.hostRobotInstanceId) || null
        : null;
    if (needsRobotAttachment && !attachmentRobot) return null;
    const file = new File([asset.blob], asset.name, {
        type: asset.type || asset.blob.type || '',
        lastModified: asset.lastModified || Date.now()
    });
    const model = await handle3DImport({
        file,
        placement: entry.placement,
        attachmentRobot,
        attachmentJointIndex: entry.attachmentJointIndex !== null
            && entry.attachmentJointIndex !== undefined
            && Number.isInteger(Number(entry.attachmentJointIndex))
            ? Number(entry.attachmentJointIndex)
            : (() => {
                const match = String(entry.attachmentAxis || '').match(/^J([1-6])$/i);
                return match ? Number(match[1]) - 1 : 3;
            })(),
        armLoadProperties: entry.armLoadProperties,
        toolLoadProperties: entry.toolLoadProperties,
        visible: entry.visible !== false,
        importQuality: entry.importQuality,
        workspaceAssetId: asset.id,
        workspaceModelId: entry.workspaceModelId,
        transform: entry.transform,
        testModel: Boolean(entry.testModel),
        skipAssetPersistence: true,
        suppressHistory: true,
        suppressFit: true,
        preserveSelection: true,
        suppressSuccessStatus: true,
        suppressErrorAlert: true,
        throwOnError: true
    });
    if (!model) throw new Error(`Imported model could not be restored: ${entry.name || asset.name}`);
    model.userData.sourceUnit = entry.sourceUnit || model.userData.sourceUnit;
    model.userData.sourceUpAxis = entry.sourceUpAxis || model.userData.sourceUpAxis;
    model.userData.sceneModelAnchor = entry.sceneModelAnchor || model.userData.sceneModelAnchor;
    if (entry.placement === 'tcp') {
        const toolAttachmentSource = normalizeToolAttachmentSource(entry.toolAttachmentSource);
        if (toolAttachmentSource) model.userData.toolAttachmentSource = toolAttachmentSource;
        else delete model.userData.toolAttachmentSource;
    } else {
        delete model.userData.toolAttachmentSource;
    }
    if (entry.placement === 'grip-object') {
        const gripObjectSource = normalizeGripObjectSource(entry.gripObjectSource);
        if (gripObjectSource) model.userData.gripObjectSource = gripObjectSource;
        else delete model.userData.gripObjectSource;
    } else if (entry.kind !== 'grip-part') {
        delete model.userData.gripObjectSource;
    }
    applyWorkspaceChildMatrices(model, entry.childMatrices);
    applyModelTransparencyVisual(model, null, entry.transparency);
    applyWorkspacePartState(model, entry.partState);
    applyWorkspaceMaterialColors(model, entry.materialColors);
    return model;
}

function createWorkspaceOlpFileWrapper(entry, blob, { prefixRoot = true } = {}) {
    const path = String(entry?.path || '').replaceAll('\\', '/');
    const name = String(entry?.name || path.split('/').at(-1) || 'olp-file');
    const content = blob instanceof Blob ? blob : new Blob([String(entry?.text ?? '')], {
        type: entry?.type || 'text/plain'
    });
    return {
        name,
        type: String(entry?.type || content.type || ''),
        size: content.size,
        lastModified: Math.max(0, Number(entry?.lastModified) || 0),
        relativePath: prefixRoot ? `__workspace__/${path}` : path,
        text: () => content.text(),
        arrayBuffer: () => content.arrayBuffer()
    };
}

async function restoreWorkspaceOlpProject(snapshot, { robot = null } = {}) {
    if (!snapshot || !Array.isArray(snapshot.files) || !snapshot.files.length) return [];
    if (Number(snapshot.schemaVersion || 1) !== 1) throw new Error('Unsupported saved OLP project schema.');
    const warnings = [];
    const validationFiles = snapshot.files.map((entry) => createWorkspaceOlpFileWrapper(entry,
        entry?.binary ? new Blob([], { type: entry?.type || 'application/octet-stream' }) : null,
        { prefixRoot: false }));
    validationFiles.forEach((file, index) => {
        if (snapshot.files[index]?.binary) file.size = Math.max(0, Number(snapshot.files[index]?.size) || 0);
    });
    validateOlpImportFiles(validationFiles);

    const files = [];
    for (const entry of snapshot.files) {
        if (!entry?.binary) {
            files.push(createWorkspaceOlpFileWrapper(entry, null));
            continue;
        }
        const asset = entry.assetId
            ? await state.workspaceRecovery.db.getAsset(entry.assetId, { touch: true })
            : null;
        if (!asset?.blob) {
            warnings.push(entry?.path || entry?.name || 'OLP binary');
            continue;
        }
        files.push(createWorkspaceOlpFileWrapper(entry, asset.blob));
    }
    if (!files.length) throw new Error('The saved OLP project has no recoverable files.');
    validateOlpImportFiles(files.map((file) => ({
        ...file,
        relativePath: String(file.relativePath || '').replace(/^__workspace__\//, '')
    })));
    const project = await buildOlpProjectFromFiles(files);
    const savedProgramPath = String(snapshot.programPath || '');
    project.programPath = project.programFiles.includes(savedProgramPath)
        ? savedProgramPath
        : project.programFiles.find((path) => /(^|\/)main\.pro$/i.test(path)) || project.programFiles[0] || null;
    if (snapshot.name) project.name = String(snapshot.name);
    project.files.forEach((record, path) => {
        const saved = snapshot.files.find((entry) => entry?.path === path);
        if (saved?.binary && saved.assetId) record.workspaceAssetId = saved.assetId;
    });
    activateOlpProject(project, {
        robot: robot || getOlpRobot(),
        selectedFile: snapshot.selectedFile || '',
        enabled: snapshot.enabled !== false,
        dirty: Boolean(snapshot.projectDirty),
        connectBus: false
    });
    return warnings;
}

async function restoreWorkspaceOlpProjects(snapshot, robotsById) {
    const entries = Array.isArray(snapshot?.olpProjects) && snapshot.olpProjects.length
        ? snapshot.olpProjects
        : snapshot?.olpProject ? [snapshot.olpProject] : [];
    const warnings = [];
    for (const entry of entries) {
        const instanceId = String(entry?.robotInstanceId || entry?.instanceId || '');
        const robot = robotsById?.get(instanceId)
            || (!instanceId && entries.length === 1 ? getOlpRobot() : null);
        if (!robot) {
            warnings.push(entry?.name || 'OLP Project');
            continue;
        }
        try {
            warnings.push(...await restoreWorkspaceOlpProject(entry, { robot }));
        } catch (error) {
            console.warn('Workspace OLP project restore failed:', error);
            warnings.push(entry?.name || 'OLP Project');
        }
    }
    return warnings;
}

async function clearOlpProjectForWorkspaceRestore() {
    if (state.olp.projectEditTimer) {
        window.clearTimeout(state.olp.projectEditTimer);
        state.olp.projectEditTimer = null;
    }
    await stopOlpSession('Workspace changed', { closeBus: true });
    state.olp.project = null;
    state.olp.projects = new Map();
    state.olp.projectRobotId = null;
    state.olp.selectedFile = '';
    state.olp.selectedFiles = new Map();
    state.olp.projectDirty = false;
    state.olp.projectDirtyByRobot = new Map();
    state.olp.editorHiddenProgramInfo = new Map();
    state.olp.editorLineOffsets = new Map();
    state.olp.editorHiddenProgramInfoByRobot = new Map();
    state.olp.editorLineOffsetsByRobot = new Map();
    state.olp.runtimes?.forEach((runtime) => runtime.stop());
    state.olp.runtimes = new Map();
    state.olp.executions = new Map();
    state.olp.runtime = null;
    state.olp.resetCursorRobotIds = new Set();
    state.olp.execution = {
        phase: 'stopped', running: false, paused: false, filePath: '', lineNumber: 0,
        lineText: '', command: '', waitCondition: '', callStack: [], alarm: null
    };
    closeOlpPointContextMenu();
    toggleOlpWorkspace(false, { connectBus: false, saveWorkspace: false });
    renderOlpProjectUi();
    setOlpStatus('disconnected', '');
}

async function restoreWorkspaceSnapshot(snapshot) {
    const recovery = state.workspaceRecovery;
    const warnings = [];
    recovery.restoring = true;
    state.historySuspended = true;
    try {
        await clearOlpProjectForWorkspaceRestore();
        clearSceneForWorkspaceRestore();
        const motionProject = snapshot?.motionProject || {
            schemaVersion: MOTION_PROJECT_SCHEMA_VERSION,
            repeatCurrentRobot: false,
            repeat: false,
            reverseRepeatCurrentRobot: false,
            reverseRepeat: false,
            robots: []
        };
        await restoreMotionProjectData(motionProject);

        const robotsById = new Map(getArticulatedRobots().map((robot) => (
            [robot.userData.motionInstanceId, robot]
        )));
        (Array.isArray(snapshot?.robotRuntime) ? snapshot.robotRuntime : []).forEach((runtime) => {
            const robot = robotsById.get(runtime?.instanceId);
            if (!robot) return;
            ensureWorkspaceModelId(robot, runtime.workspaceModelId);
            if (Array.isArray(runtime.jointAngles)
                && runtime.jointAngles.length === robot.userData.joints.length) {
                restoreRobotJointAngles(robot, runtime.jointAngles);
                robot.updateMatrixWorld(true);
                captureCurrentTcpTarget(robot);
            }
            applyModelTransparencyVisual(robot, null, runtime?.transparency);
        });
        (Array.isArray(snapshot?.programSelection) ? snapshot.programSelection : []).forEach((selection) => {
            const robot = robotsById.get(selection?.instanceId);
            const program = robot ? ensureMotionProgram(robot) : null;
            if (program?.steps.some((step) => step.id === selection?.selectedStepId)) {
                program.selectedStepId = selection.selectedStepId;
            }
        });

        const simulationIo = snapshot?.simulationIo || {};
        state.simulationIo.inputs = Array.from({ length: state.simulationIo.inputs.length }, (_, index) => (
            simulationIo.inputs?.[index] === true
        ));
        state.simulationIo.outputs = Array.from({ length: state.simulationIo.outputs.length }, (_, index) => (
            simulationIo.outputs?.[index] === true
        ));
        state.ioFunctionMappings = normalizeIoFunctionMappings(snapshot?.ioFunctionMappings);
        resetIoFunctionMappingRuntimeValues();
        renderIoFunctionMappingList();
        renderInterferenceZonePanel();
        const tcpPathEnabled = snapshot?.tcpPath?.enabled === true;
        if (state.tcpPath.enabled !== tcpPathEnabled) {
            if (!tcpPathEnabled) clearTcpPathOverlay();
            state.tcpPath.enabled = tcpPathEnabled;
        }

        updateTcpPathToggleUi();

        for (const entry of Array.isArray(snapshot?.catalogModels) ? snapshot.catalogModels : []) {
            try {
                await restoreWorkspaceCatalogModel(entry);
            } catch (error) {
                console.warn('Workspace catalog model restore failed:', error);
                warnings.push(entry?.name || entry?.catalogKey || uiText('카탈로그 모델'));
            }
        }

        const importedModels = Array.isArray(snapshot?.importedModels) ? snapshot.importedModels : [];
        for (const entry of importedModels.filter((model) => model?.kind === 'primitive-shape')) {
            try {
                restoreWorkspacePrimitiveShape(entry, robotsById);
            } catch (error) {
                console.warn('Workspace primitive shape restore failed:', error);
                warnings.push(entry?.name || uiText('도형'));
            }
        }
        for (const entry of importedModels.filter((model) => model?.kind === 'sketch-feature')) {
            try {
                restoreWorkspaceSketchFeature(entry);
            } catch (error) {
                console.warn('Workspace sketch feature restore failed:', error);
                warnings.push(entry?.name || uiText('스케치 돌출'));
            }
        }
        for (const entry of importedModels.filter((model) => model?.kind === 'cad-2d')) {
            try {
                await restoreWorkspaceCad2d(entry);
            } catch (error) {
                console.warn('Workspace CAD drawing restore failed:', error);
                warnings.push(entry?.name || uiText('2D CAD 도면'));
            }
        }
        for (const entry of importedModels.filter((model) => model?.kind === 'cad-extrude-feature')) {
            try {
                restoreWorkspaceCadExtrudeFeature(entry);
            } catch (error) {
                console.warn('Workspace CAD feature restore failed:', error);
                warnings.push(entry?.name || uiText('CAD 돌출'));
            }
        }
        for (const entry of importedModels.filter((model) => (
            model?.kind !== 'primitive-shape'
            && model?.kind !== 'sketch-feature'
            && model?.kind !== 'cad-2d'
            && model?.kind !== 'cad-extrude-feature'
            && model?.kind !== 'tool-part'
            && model?.kind !== 'grip-part'
            && model?.placement !== 'tcp'
        ))) {
            try {
                await restoreWorkspaceImportedModel(entry, robotsById);
            } catch (error) {
                console.warn('Workspace imported model restore failed:', error);
                warnings.push(entry?.name || uiText('3D 모델'));
            }
        }
        for (const entry of importedModels.filter((model) => (
            model?.kind !== 'primitive-shape'
            && model?.kind !== 'sketch-feature'
            && model?.kind !== 'cad-2d'
            && model?.kind !== 'cad-extrude-feature'
            && model?.kind !== 'tool-part'
            && model?.kind !== 'grip-part'
            && model?.placement === 'tcp'
        ))) {
            try {
                await restoreWorkspaceImportedModel(entry, robotsById);
            } catch (error) {
                console.warn('Workspace tool restore failed:', error);
                warnings.push(entry?.name || uiText('Tool'));
            }
        }
        for (const entry of importedModels.filter((model) => model?.kind === 'tool-part')) {
            try {
                restoreWorkspaceToolPart(entry, robotsById);
            } catch (error) {
                console.warn('Workspace Tool part restore failed:', error);
                warnings.push(entry?.name || uiText('Tool'));
            }
        }
        for (const entry of importedModels.filter((model) => model?.kind === 'grip-part')) {
            try {
                restoreWorkspaceGripPart(entry, robotsById);
            } catch (error) {
                console.warn('Workspace grip object part restore failed:', error);
                warnings.push(entry?.name || uiText('물건 잡기 대상'));
            }
        }

        const measurementRestore = restoreWorkspaceMeasurement(snapshot);
        if (measurementRestore.requested > measurementRestore.restored) {
            warnings.push(uiText('치수 측정'));
        }

        (Array.isArray(snapshot?.robotRuntime) ? snapshot.robotRuntime : []).forEach((runtime) => {
            const robot = robotsById.get(runtime?.instanceId);
            if (robot) applyModelTreeVisibilityVisual(robot, runtime?.visible !== false);
        });

        if (snapshot?.olpProjects || snapshot?.olpProject) {
            warnings.push(...await restoreWorkspaceOlpProjects(snapshot, robotsById));
        }

        restoreWorkspaceViewConfiguration(snapshot?.viewConfiguration);
        applyWorkspaceDisplayState(snapshot);
        applyWorkspaceCameraState(snapshot?.camera);

        state.modelTreeCollapsedIds.clear();
        (Array.isArray(snapshot?.collapsedModelIds) ? snapshot.collapsedModelIds : []).forEach((modelId) => {
            const model = findModelByWorkspaceId(modelId);
            if (model) state.modelTreeCollapsedIds.add(ensureModelTreeId(model));
        });

        const selection = snapshot?.selection || {};
        const selectedModel = findModelByWorkspaceId(selection.selectedModelId);
        if (selectedModel && selection.selectedPartIndex !== null
            && selection.selectedPartIndex !== undefined
            && Number.isInteger(Number(selection.selectedPartIndex))) {
            const part = getImportedModelParts(selectedModel)[Number(selection.selectedPartIndex)];
            if (part) selectSceneModelPart(selectedModel, part);
            else selectSceneModel(selectedModel);
        } else {
            selectSceneModel(selectedModel || null);
        }
        state.activeArticulatedModel = robotsById.get(selection.activeRobotInstanceId)
            || getArticulatedRobots()[0]
            || null;
        state.activeProgramRobot = robotsById.get(selection.activeProgramRobotInstanceId)
            || state.activeArticulatedModel;
        syncActiveOlpProjectView();
        if (state.activeArticulatedModel) renderJogControls(state.activeArticulatedModel);
        else hideJogPanel();
        if (getOlpProject(state.activeProgramRobot || state.activeArticulatedModel)) {
            syncOlpHomeStatus(
                state.activeProgramRobot || state.activeArticulatedModel,
                getOlpProject(state.activeProgramRobot || state.activeArticulatedModel)
            );
        }

        state.undoStack = [];
        state.redoStack = [];
        updateHistoryButtons();
        updateUIStatus();
        renderModelTree();
        renderMotionProgramPanel();
        refreshCollisionDebugOverlays();
        markSceneCollisionDirty();
        checkSceneCollisions({ force: true });
        requestRender();
        return warnings;
    } finally {
        state.historySuspended = false;
        recovery.restoring = false;
        showLoading(false);
    }
}

function workspaceSnapshotHasWork(snapshot) {
    if (!snapshot || typeof snapshot !== 'object') return false;
    if (snapshot.hasWork === true) return true;
    if (Array.isArray(snapshot.olpProjects)
        && snapshot.olpProjects.some((project) => Array.isArray(project?.files) && project.files.length > 0)) return true;
    if (Array.isArray(snapshot.olpProject?.files) && snapshot.olpProject.files.length > 0) return true;
    const summary = WorkspaceRecovery.getWorkspaceSummary({ state: snapshot });
    if (summary.robots > 0 || summary.models > 0) return true;
    if (snapshot.viewConfiguration?.viewPresets?.some(Boolean)) return true;
    if (snapshot.display?.gridVisible === false
        || snapshot.display?.outlineMode === true
        || snapshot.display?.collisionEnabled === true
        || [COLLISION_MODE.STOP, COLLISION_MODE.DISPLAY].includes(snapshot.display?.collisionMode)) return true;
    if (snapshot.simulationIo?.inputs?.some(Boolean)
        || snapshot.simulationIo?.outputs?.some(Boolean)
        || snapshot.ioFunctionMappings?.length > 0
        || snapshot.tcpPath?.enabled === true
        || snapshot.measurement?.points?.length > 0) return true;
    const project = snapshot.motionProject || {};
    const interferenceChanged = Array.isArray(project.interferenceZones)
        && JSON.stringify(normalizeInterferenceZones(project.interferenceZones))
            !== JSON.stringify(normalizeInterferenceZones());
    const monitoringChanged = Array.isArray(project.endMonitoringObjects)
        && JSON.stringify(normalizeEndMonitoringObjects(project.endMonitoringObjects))
            !== JSON.stringify(normalizeEndMonitoringObjects());
    return interferenceChanged || monitoringChanged;
}

function readSessionStorageValue(key) {
    try { return sessionStorage.getItem(key); } catch { return null; }
}

function writeSessionStorageValue(key, value) {
    try {
        if (value === null || value === undefined) sessionStorage.removeItem(key);
        else sessionStorage.setItem(key, String(value));
    } catch (error) {
        console.warn('Unable to update the workspace session pointer:', error);
    }
}

function createWorkspaceRecord(workspaceId, snapshot = {}, options = {}) {
    const now = Date.now();
    return WorkspaceRecovery.normalizeWorkspaceRecord({
        id: workspaceId,
        schemaVersion: WorkspaceRecovery.WORKSPACE_SCHEMA_VERSION,
        revision: Number(options.revision) || 0,
        createdAt: Number(options.createdAt) || now,
        updatedAt: Number(options.updatedAt) || now,
        forkedFrom: options.forkedFrom || null,
        incompleteRecoveryFrom: options.incompleteRecoveryFrom || null,
        archived: false,
        state: snapshot
    }, { now });
}

function resolveWorkspaceRecoveryChoice(choice) {
    const recovery = state.workspaceRecovery;
    const resolve = recovery.recoveryChoiceResolver;
    if (!resolve || recovery.recoveryDeleting) return;
    recovery.recoveryChoiceResolver = null;
    resolve(choice === 'restore'
        ? { action: 'restore', workspaceId: recovery.selectedRecoveryWorkspaceId }
        : { action: 'new', workspaceId: null });
}

function showWorkspaceRecoveryError(message = '') {
    if (!el.workspaceRecoveryError) return;
    el.workspaceRecoveryError.textContent = message ? uiText(message) : '';
    el.workspaceRecoveryError.hidden = !message;
}

function formatWorkspaceRecoverySavedAt(record) {
    const language = document.documentElement.lang || navigator.language || 'ko';
    try {
        return new Intl.DateTimeFormat(language, {
            dateStyle: 'medium',
            timeStyle: 'short'
        }).format(new Date(record?.updatedAt || Date.now()));
    } catch {
        return new Date(record?.updatedAt || Date.now()).toLocaleString();
    }
}

function formatWorkspaceRecoverySummary(record) {
    const summary = WorkspaceRecovery.getWorkspaceSummary(record);
    const baseSummary = uiFormat('로봇 {robots}대 · 3D 모델 {models}개', summary);
    return summary.olpProjects > 0
        ? `${baseSummary} · ${uiFormat('OLP 프로젝트 {projects}개', { projects: summary.olpProjects })}`
        : baseSummary;
}

function getWorkspaceRecoveryDisplayName(record, number) {
    const stateSnapshot = record?.state || {};
    const primaryName = stateSnapshot.motionProject?.robots?.[0]?.displayName
        || stateSnapshot.importedModels?.[0]?.name
        || stateSnapshot.catalogModels?.[0]?.name
        || stateSnapshot.olpProjects?.[0]?.name
        || stateSnapshot.olpProject?.name
        || '';
    const numberedName = uiFormat('저장된 작업 {number}', { number });
    return primaryName ? `${numberedName} · ${primaryName}` : numberedName;
}

function updateWorkspaceRecoveryIsolationNote(isolatedCopy) {
    if (!el.workspaceRecoveryIsolationNote) return;
    const message = isolatedCopy
        ? '같은 작업이 다른 창에서 열려 있어 이 창은 독립된 복사본으로 시작합니다.'
        : '다른 창에서 연 작업은 독립된 복사본으로 저장되어 서로 덮어쓰지 않습니다.';
    const noteText = el.workspaceRecoveryIsolationNote.querySelector('span');
    if (noteText) noteText.textContent = uiText(message);
}

function getWorkspaceRecoveryDeleteInputs() {
    return [...(el.workspaceRecoveryList?.querySelectorAll('input[data-workspace-recovery-delete]') || [])];
}

function updateWorkspaceRecoveryManagementUi() {
    const recovery = state.workspaceRecovery;
    const deleteInputs = getWorkspaceRecoveryDeleteInputs();
    const eligibleInputs = deleteInputs.filter((input) => !input.disabled);
    const selectedInputs = deleteInputs.filter((input) => input.checked);
    const allSelected = eligibleInputs.length > 0
        && eligibleInputs.every((input) => input.checked);
    if (el.workspaceRecoveryManagement) {
        el.workspaceRecoveryManagement.hidden = recovery.recoveryCandidates.length === 0;
    }
    if (el.workspaceRecoverySelectionCount) {
        el.workspaceRecoverySelectionCount.textContent = uiFormat('선택된 작업 {count}개', {
            count: selectedInputs.length
        });
    }
    if (el.btnWorkspaceSelectAll) {
        el.btnWorkspaceSelectAll.textContent = uiText(allSelected ? '전체 해제' : '전체 선택');
        el.btnWorkspaceSelectAll.disabled = eligibleInputs.length === 0 || recovery.recoveryDeleting;
        el.btnWorkspaceSelectAll.setAttribute('aria-pressed', String(allSelected));
    }
    if (el.btnWorkspaceClearSelection) {
        el.btnWorkspaceClearSelection.disabled = selectedInputs.length === 0 || recovery.recoveryDeleting;
    }
    if (el.btnWorkspaceDelete) {
        el.btnWorkspaceDelete.disabled = selectedInputs.length === 0 || recovery.recoveryDeleting;
    }
}

function renderWorkspaceRecoverySelection() {
    const recovery = state.workspaceRecovery;
    const selectedId = recovery.selectedRecoveryWorkspaceId;
    const selected = recovery.recoveryCandidates.find((candidate) => candidate.record.id === selectedId)
        || recovery.recoveryCandidates[0]
        || null;
    if (selected && selected.record.id !== selectedId) {
        recovery.selectedRecoveryWorkspaceId = selected.record.id;
    }
    el.workspaceRecoveryList?.querySelectorAll('.workspace-recovery-option').forEach((option) => {
        const input = option.querySelector('input[type="radio"]');
        option.classList.toggle('is-selected', Boolean(input?.checked));
        const deleteInput = option.querySelector('input[data-workspace-recovery-delete]');
        option.classList.toggle('is-delete-selected', Boolean(deleteInput?.checked));
    });
    updateWorkspaceRecoveryIsolationNote(Boolean(selected?.live));
    if (el.btnWorkspaceRestore) {
        el.btnWorkspaceRestore.disabled = !selected || recovery.recoveryDeleting;
    }
    updateWorkspaceRecoveryManagementUi();
}

function handleWorkspaceRecoverySelectionChange(event) {
    const deleteInput = event.target?.closest?.('input[data-workspace-recovery-delete]');
    if (deleteInput) {
        const recovery = state.workspaceRecovery;
        if (deleteInput.checked) recovery.selectedRecoveryWorkspaceIds.add(deleteInput.value);
        else recovery.selectedRecoveryWorkspaceIds.delete(deleteInput.value);
        renderWorkspaceRecoverySelection();
        return;
    }
    const input = event.target?.closest?.('input[name="workspace-recovery-source"]');
    if (!input) return;
    state.workspaceRecovery.selectedRecoveryWorkspaceId = input.value;
    renderWorkspaceRecoverySelection();
}

function selectAllWorkspaceRecoveryCandidates() {
    const recovery = state.workspaceRecovery;
    if (recovery.recoveryDeleting) return;
    const inputs = getWorkspaceRecoveryDeleteInputs().filter((input) => !input.disabled);
    if (!inputs.length) return;
    const selectAll = !inputs.every((input) => input.checked);
    inputs.forEach((input) => {
        input.checked = selectAll;
        if (selectAll) recovery.selectedRecoveryWorkspaceIds.add(input.value);
        else recovery.selectedRecoveryWorkspaceIds.delete(input.value);
    });
    renderWorkspaceRecoverySelection();
}

function clearWorkspaceRecoveryCandidateSelection() {
    const recovery = state.workspaceRecovery;
    if (recovery.recoveryDeleting) return;
    recovery.selectedRecoveryWorkspaceIds.clear();
    getWorkspaceRecoveryDeleteInputs().forEach((input) => { input.checked = false; });
    renderWorkspaceRecoverySelection();
}

function renderWorkspaceRecoveryCandidates(candidates, preferredWorkspaceId = null) {
    const recovery = state.workspaceRecovery;
    recovery.recoveryCandidates = [...candidates];
    recovery.selectedRecoveryWorkspaceIds.clear();
    const preferred = candidates.some((candidate) => candidate.record.id === preferredWorkspaceId)
        ? preferredWorkspaceId
        : candidates[0]?.record?.id || null;
    recovery.selectedRecoveryWorkspaceId = preferred;
    const multiple = candidates.length > 1;
    const hasCandidates = candidates.length > 0;
    if (el.workspaceRecoveryDescription) {
        el.workspaceRecoveryDescription.textContent = uiText(multiple
            ? '저장된 작업이 여러 개 있습니다. 불러올 작업을 선택하세요.'
            : '저장된 3D 시뮬레이션 작업이 있습니다. 불러오시겠습니까?');
    }
    if (el.workspaceRecoveryOptions) el.workspaceRecoveryOptions.hidden = !hasCandidates;
    if (el.workspaceRecoveryDetails) el.workspaceRecoveryDetails.hidden = multiple;
    if (el.workspaceRecoveryManagement) el.workspaceRecoveryManagement.hidden = !hasCandidates;
    if (el.workspaceRecoveryList) el.workspaceRecoveryList.replaceChildren();

    const selected = candidates.find((candidate) => candidate.record.id === preferred)
        || candidates[0]
        || null;
    const singleIncomplete = Boolean(!multiple && selected?.incompleteFallback);
    el.workspaceRecoveryDetails?.classList.toggle('is-incomplete', singleIncomplete);
    if (el.btnWorkspaceRestore) {
        if (singleIncomplete) {
            el.btnWorkspaceRestore.setAttribute('aria-describedby', 'workspace-recovery-summary');
        } else {
            el.btnWorkspaceRestore.removeAttribute('aria-describedby');
        }
    }
    if (!multiple && selected) {
        if (el.workspaceRecoverySavedAt) {
            el.workspaceRecoverySavedAt.textContent = uiFormat('마지막 저장: {time}', {
                time: formatWorkspaceRecoverySavedAt(selected.record)
            });
        }
        if (el.workspaceRecoverySummary) {
            const summary = formatWorkspaceRecoverySummary(selected.record);
            el.workspaceRecoverySummary.textContent = selected.incompleteFallback
                ? `${summary} · ${uiText('일부만 복구된 작업')}`
                : summary;
        }
    }

    if (hasCandidates && el.workspaceRecoveryList) {
        const fragment = document.createDocumentFragment();
        candidates.forEach((candidate, index) => {
            const number = index + 1;
            const option = document.createElement('div');
            option.className = 'workspace-recovery-option';
            const input = document.createElement('input');
            input.type = 'radio';
            input.name = 'workspace-recovery-source';
            input.value = candidate.record.id;
            input.checked = candidate.record.id === preferred;
            const radioId = `workspace-recovery-source-${number}`;
            input.id = radioId;
            const metaId = `workspace-recovery-option-meta-${number}`;
            const summaryId = `workspace-recovery-option-summary-${number}`;
            input.setAttribute('aria-label', getWorkspaceRecoveryDisplayName(candidate.record, number));
            const content = document.createElement('label');
            content.className = 'workspace-recovery-option-content';
            content.htmlFor = radioId;
            const header = document.createElement('span');
            header.className = 'workspace-recovery-option-header';
            const title = document.createElement('span');
            title.className = 'workspace-recovery-option-title';
            title.textContent = getWorkspaceRecoveryDisplayName(candidate.record, number);
            header.append(title);
            const statusDescriptionIds = [];
            if (candidate.live) {
                const live = document.createElement('span');
                live.id = `workspace-recovery-option-live-${number}`;
                statusDescriptionIds.push(live.id);
                live.className = 'workspace-recovery-option-live';
                live.textContent = uiText('다른 창에서 열려 있음');
                header.append(live);
            }
            if (candidate.incompleteFallback) {
                const incomplete = document.createElement('span');
                incomplete.id = `workspace-recovery-option-incomplete-${number}`;
                statusDescriptionIds.push(incomplete.id);
                incomplete.className = 'workspace-recovery-option-incomplete';
                incomplete.textContent = uiText('일부만 복구된 작업');
                header.append(incomplete);
            }
            const meta = document.createElement('span');
            meta.id = metaId;
            meta.className = 'workspace-recovery-option-meta';
            meta.textContent = uiFormat('마지막 저장: {time}', {
                time: formatWorkspaceRecoverySavedAt(candidate.record)
            });
            const summary = document.createElement('span');
            summary.id = summaryId;
            summary.className = 'workspace-recovery-option-summary';
            summary.textContent = formatWorkspaceRecoverySummary(candidate.record);
            input.setAttribute('aria-describedby', [metaId, summaryId, ...statusDescriptionIds].join(' '));
            const deleteInput = document.createElement('input');
            deleteInput.type = 'checkbox';
            deleteInput.dataset.workspaceRecoveryDelete = 'true';
            deleteInput.value = candidate.record.id;
            deleteInput.disabled = Boolean(candidate.live);
            deleteInput.setAttribute('aria-label', uiFormat('삭제할 작업 선택: {name}', {
                name: getWorkspaceRecoveryDisplayName(candidate.record, number)
            }));
            if (candidate.live) {
                deleteInput.title = uiText('다른 창에서 사용 중인 작업은 삭제할 수 없습니다.');
            }
            content.append(header, meta, summary);
            option.append(input, deleteInput, content);
            fragment.append(option);
        });
        el.workspaceRecoveryList.append(fragment);
    }
    renderWorkspaceRecoverySelection();
}

async function deleteSelectedWorkspaceRecoveryCandidates() {
    const recovery = state.workspaceRecovery;
    if (recovery.recoveryDeleting || !recovery.db) return;
    const selectedIds = new Set(getWorkspaceRecoveryDeleteInputs()
        .filter((input) => input.checked)
        .map((input) => input.value));
    const selectedCandidates = recovery.recoveryCandidates.filter((candidate) => (
        selectedIds.has(candidate.record.id)
    ));
    if (!selectedCandidates.length) {
        showWorkspaceRecoveryError('선택한 작업이 없습니다.');
        return;
    }
    if (!window.confirm(uiFormat('선택한 작업 {count}개를 삭제하시겠습니까?', {
        count: selectedCandidates.length
    }))) return;

    recovery.recoveryDeleting = true;
    showWorkspaceRecoveryError('');
    renderWorkspaceRecoverySelection();
    try {
        const modernWorkspaceIds = new Set();
        let deleteLegacyStorage = false;
        selectedCandidates.forEach((candidate) => {
            if (candidate.legacy) {
                deleteLegacyStorage = true;
                return;
            }
            const memberIds = Array.isArray(candidate.memberIds) || candidate.memberIds instanceof Set
                ? candidate.memberIds
                : [candidate.record.id];
            [...memberIds, candidate.record.id].forEach((id) => modernWorkspaceIds.add(String(id)));
        });
        const result = await recovery.db.deleteWorkspaces([...modernWorkspaceIds]);
        if (deleteLegacyStorage) {
            localStorage.removeItem(MOTION_PROJECT_STORAGE_KEY);
            localStorage.removeItem(VIEW_PRESETS_STORAGE_KEY);
        }
        await recovery.db.deleteOrphanAssets({ gracePeriodMs: 600000 });

        const remainingCandidates = await discoverWorkspaceRecoveryCandidates({
            sessionWorkspaceId: readSessionStorageValue(WORKSPACE_SESSION_POINTER_KEY)
        });
        if (!remainingCandidates.length) {
            recovery.recoveryCandidates = [];
            recovery.selectedRecoveryWorkspaceIds.clear();
            recovery.selectedRecoveryWorkspaceId = null;
            closeWorkspaceRecoveryDialog();
            recovery.recoveryDeleting = false;
            resolveWorkspaceRecoveryChoice('new');
            return;
        }
        const preferredWorkspaceId = remainingCandidates[0]?.record?.id || null;
        renderWorkspaceRecoveryCandidates(remainingCandidates, preferredWorkspaceId);
        if (result.skippedIds.length) {
            showWorkspaceRecoveryError('일부 작업은 다른 창에서 사용 중이라 삭제하지 못했습니다.');
        }
    } catch (error) {
        console.error('Workspace recovery deletion failed:', error);
        showWorkspaceRecoveryError('선택한 작업을 삭제하지 못했습니다.');
    } finally {
        recovery.recoveryDeleting = false;
        renderWorkspaceRecoverySelection();
    }
}

function requestWorkspaceRecoveryChoice(candidates, {
    preferredWorkspaceId = null,
    errorMessage = ''
} = {}) {
    renderWorkspaceRecoveryCandidates(candidates, preferredWorkspaceId);
    const selected = candidates.find((candidate) => (
        candidate.record.id === state.workspaceRecovery.selectedRecoveryWorkspaceId
    )) || candidates[0] || null;
    if (el.workspaceRecoverySavedAt) {
        // Keep the original single-record details populated for assistive
        // technology even while the multi-record fieldset is visible.
        if (selected && candidates.length > 1) {
            el.workspaceRecoverySavedAt.textContent = uiFormat('마지막 저장: {time}', {
                time: formatWorkspaceRecoverySavedAt(selected.record)
            });
        }
    }
    showWorkspaceRecoveryError(errorMessage);
    if (typeof el.workspaceRecoveryDialog?.showModal !== 'function') {
        const shouldRestore = window.confirm(uiText(candidates.length > 1
            ? '저장된 작업이 여러 개 있습니다. 불러올 작업을 선택하세요.'
            : '저장된 3D 시뮬레이션 작업이 있습니다. 불러오시겠습니까?'));
        if (!shouldRestore || !selected) {
            return Promise.resolve({ action: 'new', workspaceId: null });
        }
        if (candidates.length === 1 || typeof window.prompt !== 'function') {
            return Promise.resolve({ action: 'restore', workspaceId: selected.record.id });
        }
        const options = candidates.map((candidate, index) => (
            `${index + 1}. ${getWorkspaceRecoveryDisplayName(candidate.record, index + 1)}`
        )).join('\n');
        const answer = window.prompt(`${uiText('불러올 작업 선택')}\n${options}`, '1');
        if (answer === null) return Promise.resolve({ action: 'new', workspaceId: null });
        const index = Math.max(0, Math.min(candidates.length - 1, Math.trunc(Number(answer) || 1) - 1));
        return Promise.resolve({ action: 'restore', workspaceId: candidates[index].record.id });
    }
    if (!el.workspaceRecoveryDialog.open) el.workspaceRecoveryDialog.showModal();
    queueMicrotask(() => {
        el.workspaceRecoveryList?.querySelector('input[type="radio"]:checked')?.focus();
    });
    return new Promise((resolve) => {
        state.workspaceRecovery.recoveryChoiceResolver = resolve;
    });
}

function closeWorkspaceRecoveryDialog() {
    showWorkspaceRecoveryError('');
    if (el.workspaceRecoveryDialog?.open) el.workspaceRecoveryDialog.close();
}

function setupWorkspaceBroadcastChannel() {
    const recovery = state.workspaceRecovery;
    if (recovery.channel || typeof BroadcastChannel !== 'function') return;
    const channel = new BroadcastChannel(WORKSPACE_BROADCAST_CHANNEL);
    const listener = (event) => {
        const message = event.data;
        if (!message || message.senderId === recovery.ownerId) return;
        if (message.type === 'workspace-probe'
            && message.workspaceId === recovery.workspaceId
            && recovery.ownerId) {
            // Flush first so a duplicated tab receives the newest durable
            // snapshot when it forks this workspace.
            void Promise.resolve(saveMotionProjectNow()).catch((error) => {
                console.warn('Workspace probe flush failed:', error);
            }).finally(() => {
                channel.postMessage({
                    type: 'workspace-alive',
                    workspaceId: recovery.workspaceId,
                    probeId: message.probeId,
                    targetOwnerId: message.senderId,
                    senderId: recovery.ownerId,
                    revision: recovery.workspace?.revision || 0
                });
            });
            return;
        }
        if (message.type === 'workspace-alive'
            && message.targetOwnerId === recovery.ownerId) {
            const pending = recovery.pendingProbes.get(message.probeId);
            if (pending) pending({
                live: true,
                revision: Number.isInteger(Number(message.revision))
                    ? Number(message.revision)
                    : null
            });
        }
    };
    channel.addEventListener('message', listener);
    recovery.channel = channel;
    recovery.channelListener = listener;
}

function probeLiveWorkspaceOwner(workspaceId) {
    const recovery = state.workspaceRecovery;
    if (!workspaceId || !recovery.channel) {
        return Promise.resolve({ live: false, revision: null });
    }
    const probeId = WorkspaceRecovery.createWorkspaceId('probe');
    return new Promise((resolve) => {
        let settled = false;
        const finish = (result = {}) => {
            if (settled) return;
            settled = true;
            recovery.pendingProbes.delete(probeId);
            resolve({
                live: Boolean(result.live),
                revision: Number.isInteger(Number(result.revision))
                    ? Number(result.revision)
                    : null
            });
        };
        recovery.pendingProbes.set(probeId, finish);
        recovery.channel.postMessage({
            type: 'workspace-probe',
            workspaceId,
            probeId,
            senderId: recovery.ownerId
        });
        window.setTimeout(() => finish({ live: false, revision: null }), WORKSPACE_LIVE_PROBE_TIMEOUT_MS);
    });
}

async function claimWorkspaceLease(workspaceId, { force = false } = {}) {
    const recovery = state.workspaceRecovery;
    for (let attempt = 0; attempt < 3; attempt += 1) {
        const result = await recovery.db.acquireLease(workspaceId, recovery.ownerId, { force });
        if (result.acquired) return workspaceId;
        workspaceId = WorkspaceRecovery.createWorkspaceId('workspace');
        force = false;
    }
    throw new Error('Unable to claim an isolated simulation workspace.');
}

function startWorkspaceHeartbeat() {
    const recovery = state.workspaceRecovery;
    window.clearInterval(recovery.heartbeatTimer);
    recovery.heartbeatTimer = window.setInterval(() => {
        if ((!recovery.ready && !recovery.restoring)
            || recovery.unloading || !recovery.workspaceId) return;
        void recovery.db.renewLease(recovery.workspaceId, recovery.ownerId).catch((error) => {
            if (error?.code === 'WORKSPACE_LEASE_LOST') {
                if (recovery.ready || recovery.restoring) void forkWorkspaceAfterOwnershipLoss();
            }
            else console.warn('Workspace heartbeat failed:', error);
        });
        recovery.channel?.postMessage({
            type: 'workspace-heartbeat',
            workspaceId: recovery.workspaceId,
            senderId: recovery.ownerId,
            at: Date.now()
        });
    }, WORKSPACE_HEARTBEAT_INTERVAL_MS);
}

async function forkWorkspaceAfterOwnershipLoss() {
    const recovery = state.workspaceRecovery;
    if (recovery.ownershipTransition) return recovery.ownershipTransition;
    recovery.ownershipTransition = (async () => {
        const previousId = recovery.workspaceId;
        const workspaceId = await claimWorkspaceLease(WorkspaceRecovery.createWorkspaceId('workspace'));
        recovery.workspaceId = workspaceId;
        recovery.workspace = createWorkspaceRecord(workspaceId, serializeWorkspaceSnapshot(), {
            forkedFrom: previousId,
            incompleteRecoveryFrom: recovery.workspace?.incompleteRecoveryFrom || null
        });
        recovery.leaseLost = false;
        writeSessionStorageValue(WORKSPACE_SESSION_POINTER_KEY, workspaceId);
        setStatus('같은 작업이 다른 창에서 열려 있어 이 창은 독립된 복사본으로 시작합니다.', '#f59e0b');
        recovery.saveQueued = true;
        if (!recovery.saveInFlight) queueMicrotask(() => void runWorkspaceSaveLoop());
    })().finally(() => {
        recovery.ownershipTransition = null;
    });
    return recovery.ownershipTransition;
}

function clearLegacyWorkspaceStorageAfterCommit() {
    const recovery = state.workspaceRecovery;
    if (!recovery.legacyMigrationPending) return;
    try {
        const currentFingerprint = readLegacyWorkspaceFingerprint();
        if (recovery.legacyMigrationFingerprint
            && currentFingerprint !== recovery.legacyMigrationFingerprint) {
            // A legacy tab saved a newer snapshot while the picker was open.
            // Preserve it for the next explicit recovery choice.
            recovery.legacyMigrationPending = false;
            recovery.legacyMigrationFingerprint = null;
            return;
        }
        localStorage.removeItem(MOTION_PROJECT_STORAGE_KEY);
        localStorage.removeItem(VIEW_PRESETS_STORAGE_KEY);
        recovery.legacyMigrationPending = false;
        recovery.legacyMigrationFingerprint = null;
    } catch (error) {
        console.warn('Unable to finish legacy workspace migration:', error);
    }
}

async function runWorkspaceSaveLoop() {
    const recovery = state.workspaceRecovery;
    if (recovery.saveInFlight) {
        recovery.saveQueued = true;
        return recovery.saveInFlight;
    }
    recovery.saveInFlight = (async () => {
        do {
            recovery.saveQueued = false;
            if (!recovery.ready || recovery.restoring || recovery.unloading
                || state.resetInProgress || !recovery.workspaceId) return;
            const snapshot = serializeWorkspaceSnapshot();
            const previous = recovery.workspace || createWorkspaceRecord(recovery.workspaceId, snapshot);
            try {
                const saved = await recovery.db.saveWorkspaceWithLease({
                    ...previous,
                    id: recovery.workspaceId,
                    state: snapshot
                }, {
                    ownerId: recovery.ownerId,
                    expectedRevision: previous.revision
                });
                recovery.workspace = saved;
                clearLegacyWorkspaceStorageAfterCommit();
            } catch (error) {
                if (error?.code === 'WORKSPACE_LEASE_LOST'
                    || error?.code === 'WORKSPACE_REVISION_CONFLICT') {
                    await forkWorkspaceAfterOwnershipLoss();
                    recovery.saveQueued = true;
                    continue;
                }
                recovery.startupWarning = true;
                console.warn('Workspace autosave failed:', error);
                setStatus(WorkspaceRecovery.isWorkspaceQuotaError(error)
                    ? '자동 복구 저장 공간이 부족합니다. 프로젝트를 파일로 저장해 주세요.'
                    : '작업을 자동 저장하지 못했습니다.', '#ef4444');
            }
        } while (recovery.saveQueued);
    })().finally(() => {
        recovery.saveInFlight = null;
    });
    return recovery.saveInFlight;
}

async function findWorkspaceRecoveryCandidates(records, { sessionWorkspaceId = null } = {}) {
    const eligible = records.filter((record) => (
        record && !record.archived && workspaceSnapshotHasWork(record.state)
    ));
    const collapsed = WorkspaceRecovery.collapseWorkspaceRecoveryRecords(eligible, { sessionWorkspaceId });
    const candidates = await Promise.all(collapsed.map(async (candidate) => {
        const [probe, lease] = await Promise.all([
            probeLiveWorkspaceOwner(candidate.record.id),
            state.workspaceRecovery.db.getLease(candidate.record.id)
        ]);
        const memberIds = [...new Set([
            candidate.record.id,
            ...(Array.isArray(candidate.memberIds) || candidate.memberIds instanceof Set
                ? candidate.memberIds
                : [])
        ].map((id) => String(id || '').trim()).filter(Boolean))];
        const additionalMemberStates = await Promise.all(memberIds
            .filter((id) => id !== candidate.record.id)
            .map(async (workspaceId) => {
                const [memberProbe, memberLease] = await Promise.all([
                    probeLiveWorkspaceOwner(workspaceId),
                    state.workspaceRecovery.db.getLease(workspaceId)
                ]);
                return { probe: memberProbe, lease: memberLease };
            }));
        const memberStates = [{ probe, lease }, ...additionalMemberStates];
        const hasLiveLease = (entry) => Boolean(entry.lease
            && Number(entry.lease.expiresAt) > Date.now()
            && entry.lease.ownerId !== state.workspaceRecovery.ownerId);
        const leased = Boolean(lease && Number(lease.expiresAt) > Date.now()
            && lease.ownerId !== state.workspaceRecovery.ownerId);
        return {
            ...candidate,
            live: probe.live || leased || additionalMemberStates.some((entry) => (
                entry.probe.live || hasLiveLease(entry)
            )),
            respondingOwner: memberStates.some((entry) => entry.probe.live),
            leased: leased || additionalMemberStates.some(hasLiveLease),
            observedRevision: probe.revision
        };
    }));
    return candidates;
}

async function waitForWorkspaceRecoveryRevision(workspaceId, minimumRevision = null) {
    let record = await state.workspaceRecovery.db.getWorkspace(workspaceId);
    if (!record || minimumRevision === null || record.revision >= minimumRevision) return record;
    for (let attempt = 0; attempt < 10; attempt += 1) {
        await new Promise((resolve) => window.setTimeout(resolve, 100));
        const refreshed = await state.workspaceRecovery.db.getWorkspace(workspaceId);
        if (refreshed) record = refreshed;
        if (!record || record.revision >= minimumRevision) break;
    }
    return record;
}

async function refreshWorkspaceRecoveryCandidate(candidate) {
    if (candidate.legacy) {
        const latest = readLegacyWorkspaceCandidate();
        if (!latest) {
            const error = new Error('The selected legacy workspace is no longer available.');
            error.code = 'WORKSPACE_NOT_FOUND';
            throw error;
        }
        return { ...candidate, record: latest, live: false };
    }
    let record = await state.workspaceRecovery.db.getWorkspace(candidate.record.id);
    if (!record || record.archived || !workspaceSnapshotHasWork(record.state)) {
        const error = new Error('The selected workspace is no longer available.');
        error.code = 'WORKSPACE_NOT_FOUND';
        throw error;
    }
    const [probe, lease] = await Promise.all([
        probeLiveWorkspaceOwner(record.id),
        state.workspaceRecovery.db.getLease(record.id)
    ]);
    if (probe.revision !== null && probe.revision > record.revision) {
        record = await waitForWorkspaceRecoveryRevision(record.id, probe.revision);
    } else {
        record = await state.workspaceRecovery.db.getWorkspace(record.id) || record;
    }
    if (!record || record.archived || !workspaceSnapshotHasWork(record.state)) {
        const error = new Error('The selected workspace is no longer available.');
        error.code = 'WORKSPACE_NOT_FOUND';
        throw error;
    }
    return {
        ...candidate,
        record,
        live: probe.live || Boolean(lease && Number(lease.expiresAt) > Date.now()
            && lease.ownerId !== state.workspaceRecovery.ownerId),
        respondingOwner: probe.live,
        leased: Boolean(lease && Number(lease.expiresAt) > Date.now()
            && lease.ownerId !== state.workspaceRecovery.ownerId),
        observedRevision: probe.revision
    };
}

function readLegacyWorkspaceCandidate() {
    let motionProject = null;
    let viewConfiguration = null;
    let motionRaw = '';
    let viewRaw = '';
    try {
        motionRaw = localStorage.getItem(MOTION_PROJECT_STORAGE_KEY) || '';
        viewRaw = localStorage.getItem(VIEW_PRESETS_STORAGE_KEY) || '';
        if (motionRaw) motionProject = JSON.parse(motionRaw);
        if (viewRaw) viewConfiguration = JSON.parse(viewRaw);
        if (!motionRaw && !viewRaw) return null;
    } catch (error) {
        console.warn('Legacy simulation recovery data is invalid:', error);
        return null;
    }
    const snapshot = {
        schemaVersion: 1,
        motionProject: motionProject || {
            schemaVersion: MOTION_PROJECT_SCHEMA_VERSION,
            repeatCurrentRobot: false,
            repeat: false,
            reverseRepeatCurrentRobot: false,
            reverseRepeat: false,
            robots: []
        },
        robotRuntime: [],
        importedModels: [],
        catalogModels: [],
        assetIds: [],
        selection: {},
        camera: null,
        display: {
            gridVisible: true,
            outlineMode: true,
            collisionMode: COLLISION_MODE.OFF,
            collisionEnabled: false
        },
        viewConfiguration: viewConfiguration || { viewPresets: [] },
        collapsedModelIds: []
    };
    if (!workspaceSnapshotHasWork(snapshot)) return null;
    const record = createWorkspaceRecord(WorkspaceRecovery.createWorkspaceId('legacy'), snapshot, {
        updatedAt: Date.now()
    });
    record.legacyFingerprint = `${motionRaw}\u0000${viewRaw}`;
    return record;
}

function readLegacyWorkspaceFingerprint() {
    try {
        const motionRaw = localStorage.getItem(MOTION_PROJECT_STORAGE_KEY) || '';
        const viewRaw = localStorage.getItem(VIEW_PRESETS_STORAGE_KEY) || '';
        return `${motionRaw}\u0000${viewRaw}`;
    } catch {
        return null;
    }
}

async function resetCleanWorkspaceUiState() {
    await clearOlpProjectForWorkspaceRestore();
    clearSceneForWorkspaceRestore();
    state.motionRepeatRobot = false;
    state.motionRepeat = false;
    state.motionReverseRepeatRobot = false;
    state.motionReverseRepeat = false;
    state.interferenceZones = normalizeInterferenceZones();
    state.endMonitoringObjects = normalizeEndMonitoringObjects();
    syncMotionRepeatControl();
    state.viewPresets = Array.from({ length: VIEW_PRESET_COUNT }, () => null);
    state.activeViewSlot = null;
    refreshViewPresetsUi();
    state.ioFunctionMappings = [];
    state.ioFunctionMappingRuntimeValues.clear();
    renderIoFunctionMappingList();
    applyWorkspaceDisplayState({
        display: {
            gridVisible: true,
            outlineMode: true,
            collisionMode: COLLISION_MODE.OFF,
            collisionEnabled: false
        }
    });
    updateUIStatus();
    renderMotionProgramPanel();
    fitCamera();
}

async function discoverWorkspaceRecoveryCandidates({ sessionWorkspaceId = null, startClean = false } = {}) {
    if (startClean) return [];
    const candidates = await findWorkspaceRecoveryCandidates(
        await state.workspaceRecovery.db.listWorkspaces(),
        { sessionWorkspaceId }
    );
    const legacy = readLegacyWorkspaceCandidate();
    if (legacy) {
        candidates.push({
            record: legacy,
            live: false,
            respondingOwner: false,
            leased: false,
            observedRevision: null,
            sessionMatch: false,
            incompleteFallback: false,
            memberIds: new Set([legacy.id]),
            legacy: true
        });
    }
    return candidates;
}

async function acquireSelectedWorkspaceRecovery(candidate) {
    const recovery = state.workspaceRecovery;
    let selected = await refreshWorkspaceRecoveryCandidate(candidate);
    let source = selected.record;
    const legacySource = selected.legacy ? source : null;
    let targetWorkspaceId = null;
    let sourceIsLive = Boolean(selected.live);

    if (selected.legacy || sourceIsLive) {
        targetWorkspaceId = await claimWorkspaceLease(WorkspaceRecovery.createWorkspaceId('workspace'));
    } else {
        const leaseResult = await recovery.db.acquireLease(source.id, recovery.ownerId);
        if (leaseResult.acquired) {
            targetWorkspaceId = source.id;
        } else {
            // Another window won the selection race. Refresh the durable source
            // that it owns, then restore into this document's isolated target.
            selected = await refreshWorkspaceRecoveryCandidate({ ...selected, live: true });
            source = selected.record;
            sourceIsLive = true;
            targetWorkspaceId = await claimWorkspaceLease(WorkspaceRecovery.createWorkspaceId('workspace'));
        }
    }

    try {
        if (!selected.legacy) {
            const latest = await state.workspaceRecovery.db.getWorkspace(source.id);
            if (!latest || latest.archived || !workspaceSnapshotHasWork(latest.state)) {
                const error = new Error('The selected workspace is no longer available.');
                error.code = 'WORKSPACE_NOT_FOUND';
                throw error;
            }
            source = latest;
        }
        return { source, sourceIsLive, legacySource, targetWorkspaceId };
    } catch (error) {
        if (targetWorkspaceId) {
            await recovery.db.releaseLease(targetWorkspaceId, recovery.ownerId).catch(() => {});
        }
        throw error;
    }
}

async function initializeWorkspaceRecovery() {
    const recovery = state.workspaceRecovery;
    recovery.ownerId = WorkspaceRecovery.createWorkspaceId('owner');
    recovery.db = new WorkspaceRecovery.WorkspaceRecoveryStore(window.indexedDB);
    setupWorkspaceBroadcastChannel();
    try {
        await recovery.db.open();
        try { await navigator.storage?.persist?.(); } catch { }
        const startClean = readSessionStorageValue(WORKSPACE_START_CLEAN_KEY) === '1';
        writeSessionStorageValue(WORKSPACE_START_CLEAN_KEY, null);
        const sessionWorkspaceId = readSessionStorageValue(WORKSPACE_SESSION_POINTER_KEY);
        let candidates = await discoverWorkspaceRecoveryCandidates({ sessionWorkspaceId, startClean });
        let preferredWorkspaceId = candidates.find((candidate) => candidate.sessionMatch)?.record.id
            || candidates[0]?.record.id
            || null;
        let source = null;
        let sourceIsLive = false;
        let legacySource = null;
        let restoreSelected = false;
        let restoreHadWarnings = false;
        let incompleteRecoverySourceId = null;
        let targetWorkspaceId = null;
        let errorMessage = '';

        while (candidates.length && !startClean) {
            const choice = await requestWorkspaceRecoveryChoice(candidates, {
                preferredWorkspaceId,
                errorMessage
            });
            if (choice.action === 'new') {
                break;
            }
            preferredWorkspaceId = choice.workspaceId;
            const candidate = candidates.find((entry) => entry.record.id === choice.workspaceId);
            if (!candidate) {
                errorMessage = '이전 작업을 불러오지 못했습니다.';
                candidates = await discoverWorkspaceRecoveryCandidates({ sessionWorkspaceId });
                continue;
            }
            closeWorkspaceRecoveryDialog();
            showLoading(true, uiText('이전 작업 불러오는 중...'));
            try {
                const prepared = await acquireSelectedWorkspaceRecovery(candidate);
                source = prepared.source;
                sourceIsLive = prepared.sourceIsLive;
                legacySource = prepared.legacySource;
                targetWorkspaceId = prepared.targetWorkspaceId;
                recovery.workspaceId = targetWorkspaceId;
                writeSessionStorageValue(WORKSPACE_SESSION_POINTER_KEY, targetWorkspaceId);
                recovery.legacyMigrationPending = Boolean(legacySource);
                recovery.legacyMigrationFingerprint = legacySource?.legacyFingerprint || null;
                startWorkspaceHeartbeat();
                const warnings = await restoreWorkspaceSnapshot(source.state);
                restoreSelected = true;
                if (warnings.length) {
                    restoreHadWarnings = true;
                    recovery.startupWarning = true;
                    setStatus('저장된 작업 파일 일부를 찾을 수 없어 이전 작업을 모두 복구하지 못했습니다.', '#f59e0b');
                } else if (source.incompleteRecoveryFrom) {
                    recovery.startupWarning = true;
                    setStatus('저장된 작업 파일 일부를 찾을 수 없어 이전 작업을 모두 복구하지 못했습니다.', '#f59e0b');
                }
                break;
            } catch (error) {
                console.error('Workspace restore failed:', error);
                showLoading(false);
                window.clearInterval(recovery.heartbeatTimer);
                recovery.heartbeatTimer = null;
                if (recovery.ownershipTransition) {
                    await recovery.ownershipTransition.catch(() => {});
                }
                const failedWorkspaceIds = new Set([
                    targetWorkspaceId,
                    recovery.workspaceId
                ].filter(Boolean));
                for (const workspaceId of failedWorkspaceIds) {
                    await recovery.db.releaseLease(workspaceId, recovery.ownerId).catch(() => {});
                }
                recovery.workspaceId = null;
                recovery.workspace = null;
                writeSessionStorageValue(WORKSPACE_SESSION_POINTER_KEY, null);
                source = null;
                sourceIsLive = false;
                legacySource = null;
                targetWorkspaceId = null;
                errorMessage = '이전 작업을 불러오지 못했습니다.';
                candidates = await discoverWorkspaceRecoveryCandidates({ sessionWorkspaceId });
                preferredWorkspaceId = candidates.some((entry) => entry.record.id === choice.workspaceId)
                    ? choice.workspaceId
                    : candidates[0]?.record.id || null;
            }
        }

        if (restoreSelected && restoreHadWarnings && source?.id === recovery.workspaceId) {
            // Keep an intact source untouched when a missing model asset causes
            // a partial restore. The incomplete result is stored separately.
            await recovery.db.releaseLease(recovery.workspaceId, recovery.ownerId);
            recovery.workspaceId = await claimWorkspaceLease(WorkspaceRecovery.createWorkspaceId('workspace'));
            targetWorkspaceId = recovery.workspaceId;
            writeSessionStorageValue(WORKSPACE_SESSION_POINTER_KEY, recovery.workspaceId);
        }
        if (restoreSelected && restoreHadWarnings && source?.id) {
            incompleteRecoverySourceId = source.id;
        }

        if (!restoreSelected) {
            closeWorkspaceRecoveryDialog();
            await resetCleanWorkspaceUiState();
            recovery.workspaceId = await claimWorkspaceLease(WorkspaceRecovery.createWorkspaceId('workspace'));
            targetWorkspaceId = recovery.workspaceId;
            writeSessionStorageValue(WORKSPACE_SESSION_POINTER_KEY, recovery.workspaceId);
            recovery.legacyMigrationPending = false;
            recovery.legacyMigrationFingerprint = null;
        }

        const reusingSourceRecord = Boolean(source && source.id === recovery.workspaceId);
        recovery.workspace = createWorkspaceRecord(recovery.workspaceId,
            restoreSelected ? source.state : serializeWorkspaceSnapshot(), {
                revision: reusingSourceRecord ? source.revision : 0,
                createdAt: reusingSourceRecord ? source.createdAt : Date.now(),
                updatedAt: Date.now(),
                forkedFrom: restoreSelected && source.id !== recovery.workspaceId ? source.id : null,
                incompleteRecoveryFrom: incompleteRecoverySourceId
                    || (restoreSelected ? source?.incompleteRecoveryFrom : null)
            });
        recovery.ready = true;
        startWorkspaceHeartbeat();
        await runWorkspaceSaveLoop();
        const targetWasCommitted = Number(recovery.workspace?.revision) > 0;
        if (targetWasCommitted && source && !sourceIsLive && !legacySource && !restoreHadWarnings
            && source.id !== recovery.workspaceId) {
            try {
                await recovery.db.archiveWorkspace(source.id, true, {
                    expectedRevision: source.revision,
                    requireUnleased: true
                });
            } catch (error) {
                console.warn('Unable to archive the migrated workspace source:', error);
            }
        }
        // Partial-recovery descendants stay durable and are collapsed behind
        // their intact source by the chooser. They are never auto-archived:
        // a throttled but live window may still own the only newer copy.
        void (async () => {
            await recovery.db.pruneArchivedWorkspaces({ keep: 1 });
            await recovery.db.deleteOrphanAssets({ gracePeriodMs: 600000 });
        })().catch((error) => {
            console.warn('Unable to clean old workspace recovery records:', error);
        });
        return recovery.startupWarning;
    } catch (error) {
        console.error('Workspace recovery initialization failed:', error);
        recovery.ready = false;
        recovery.startupWarning = true;
        renderMotionProgramPanel();
        setStatus('작업을 자동 저장하지 못했습니다.', '#ef4444');
        return true;
    }
}

function releaseWorkspaceOwnership({ releaseLease = true } = {}) {
    const recovery = state.workspaceRecovery;
    recovery.unloading = true;
    window.clearInterval(recovery.heartbeatTimer);
    recovery.heartbeatTimer = null;
    recovery.channel?.postMessage({
        type: 'workspace-goodbye',
        workspaceId: recovery.workspaceId,
        senderId: recovery.ownerId
    });
    if (releaseLease && recovery.workspaceId && recovery.ownerId) {
        void recovery.db?.releaseLease(recovery.workspaceId, recovery.ownerId).catch(() => {});
    }
    if (recovery.channel && recovery.channelListener) {
        recovery.channel.removeEventListener('message', recovery.channelListener);
    }
    recovery.channel?.close();
    recovery.channel = null;
}

function saveMotionProjectNow() {
    window.clearTimeout(state.motionSaveTimer);
    state.motionSaveTimer = null;
    if (IS_MANUAL_GUIDE_EMBED || state.placement.previewOriginalTransform) return;
    return runWorkspaceSaveLoop();
}

function scheduleMotionProjectSave() {
    window.clearTimeout(state.motionSaveTimer);
    if (IS_MANUAL_GUIDE_EMBED) {
        state.motionSaveTimer = null;
        return;
    }
    if (state.placement.previewOriginalTransform
        || state.workspaceRecovery.restoring || !state.workspaceRecovery.ready) {
        state.motionSaveTimer = null;
        return;
    }
    state.motionSaveTimer = window.setTimeout(() => void saveMotionProjectNow(), 180);
}

function findMotionModelDefinition(robotProject) {
    return [...state.catalog.values()].find((definition) => (
        definition.type === 'articulated-stl'
        && definition.folder === robotProject.modelFolder
        && (!robotProject.robotType || definition.robotType === robotProject.robotType)
    )) || null;
}

async function restoreMotionProjectData(input) {
    if (isMotionActive()) throw new Error('Stop all robot motions before loading a project.');
    const project = normalizeMotionProject(input);
    state.robotInterferenceAvoidance = {
        enabled: Boolean(input?.robotInterferenceAvoidance?.enabled),
        priorityRobotId: typeof input?.robotInterferenceAvoidance?.priorityRobotId === 'string'
            ? input.robotInterferenceAvoidance.priorityRobotId
            : null
    };
    state.interferenceZones = normalizeInterferenceZones(input.interferenceZones);
    state.endMonitoringObjects = normalizeEndMonitoringObjects(input.endMonitoringObjects);
    state.interferenceRuntime.forEach((runtime, index) => {
        if (!runtime) return;
        resetInterferenceZoneRuntime(index);
    });
    const definitions = project.robots.map((robotProject) => {
        const definition = findMotionModelDefinition(robotProject);
        if (!definition) throw new Error(`Robot model is unavailable: ${robotProject.modelFolder}`);
        if ((definition.limits || []).length !== robotProject.jointCount) {
            throw new Error(`Joint count does not match the current catalog: ${robotProject.displayName}`);
        }
        return definition;
    });

    setTransformHandlesEnabled(false);
    setBaseJogGizmoEnabled(false);
    clearTcpPathOverlay();
    const replacedRobots = new Set(getArticulatedRobots());
    const removedModels = new Set([
        ...replacedRobots,
        ...state.models.filter((model) => replacedRobots.has(model.userData.attachmentHost))
    ]);
    removedModels.forEach((model) => {
        disposeModelOutlines(model);
        model.removeFromParent();
    });
    state.models = state.models.filter((model) => !removedModels.has(model));
    markSceneCollisionDirty();
    state.motionPrograms.clear();
    state.activeArticulatedModel = null;
    state.activeProgramRobot = null;

    for (let index = 0; index < project.robots.length; index += 1) {
        const robotProject = project.robots[index];
        const definition = definitions[index];
        showLoading(true, uiFormat('{name} 불러오는 중...', { name: robotProject.displayName }), 0);
        const robot = await loadArticulatedRobot(definition, (progress) => {
            showLoading(true, uiFormat('{name}: {progress}%', {
                name: robotProject.displayName,
                progress
            }), progress);
        });
        robot.userData.modelName = definition.name;
        assignRobotInstanceMetadata(robot, definition, {
            instanceId: robotProject.instanceId,
            displayName: robotProject.displayName,
            instanceNumber: robotProject.instanceNumber,
            modelFolder: robotProject.modelFolder,
            robotType: robotProject.robotType
        });
        restoreRobotTcpProfiles(
            robot,
            robotProject.tcpProfiles,
            robotProject.activeTcpProfileIndex
        );
        restoreRobotWorkObjects(
            robot,
            robotProject.workObjects,
            robotProject.activeWorkObjectIndex
        );
        robot.position.fromArray(robotProject.baseTransform.position);
        robot.quaternion.fromArray(robotProject.baseTransform.quaternion);
        robot.scale.fromArray(robotProject.baseTransform.scale);
        robot.userData.externalAxes = normalizeExternalAxisValues(robotProject.externalAxes);
        robot.updateMatrixWorld(true);
        updateModelRenderComplexity(robot);
        if (state.collision.enabled) state.collision.system?.prepare([robot]);
        state.models.push(robot);
        state.scene.add(robot);
        markSceneCollisionDirty();
        refreshCollisionDebugOverlays();
        ensureModelTreeId(robot);
        const program = cloneMotionProgram({
            included: robotProject.included,
            selectedStepId: robotProject.steps[0]?.id || null,
            workOrigin: robotProject.workOrigin,
            steps: robotProject.steps
        });
        state.motionPrograms.set(robotProject.instanceId, program);
        captureCurrentTcpTarget(robot);
    }

    updateWorkObjectVisuals();
    updateInterferenceZoneVisuals();
    state.motionRepeatRobot = project.repeatCurrentRobot;
    state.motionRepeat = project.repeat;
    state.motionReverseRepeatRobot = project.reverseRepeatCurrentRobot;
    state.motionReverseRepeat = project.reverseRepeat;
    syncMotionRepeatControl();
    state.activeArticulatedModel = getArticulatedRobots()[0] || null;
    state.activeProgramRobot = state.activeArticulatedModel;
    if (state.activeArticulatedModel) {
        renderJogControls(state.activeArticulatedModel);
    } else {
        hideJogPanel();
    }
    syncWorkOriginOutputStates();
    updateUIStatus();
    selectSceneModel(state.activeArticulatedModel || state.models.at(-1) || null);
    renderMotionProgramPanel();
    showLoading(false);
    if (state.models.length) fitCamera();
    scheduleMotionProjectSave();
    return project;
}

async function restoreMotionProjectFromStorage() {
    let raw = null;
    try {
        raw = localStorage.getItem(MOTION_PROJECT_STORAGE_KEY);
    } catch (error) {
        console.warn('Motion project autosave is unavailable:', error);
    }
    if (!raw) {
        renderMotionProgramPanel();
        return;
    }
    try {
        await restoreMotionProjectData(JSON.parse(raw));
        setMotionProgramStatus('자동 저장된 프로젝트를 복원했습니다.');
    } catch (error) {
        console.error('Motion project restore failed:', error);
        showLoading(false);
        setMotionProgramStatus('프로젝트 복원에 실패했습니다.', 'error');
    }
}

function formatPositionPointRecord(robot, step) {
    const pose = motionStepTargetPose(step);
    const rotation = getTcpRotationDegrees(robot, pose);
    return formatPositionPointRecordLine({
        pointIndex: step.pointIndex,
        coordinates: [
            pose.position.x,
            pose.position.y,
            pose.position.z,
            rotation.rz,
            rotation.ry,
            rotation.rx
        ],
        armParameters: step.armParameters || calculatePointArmParameters(robot, step.joints),
        // P.pts retains the six controller fields, but the simulation travel
        // axis values are intentionally not exported.
        externalAxes: [0, 0, 0, 0, 0, 0],
        label: step.label
    });
}

function importActiveProject() {
    if (state.olp.enabled) {
        if (isOlpRunning()) return;
        void importOlpFolderFromPicker();
        return;
    }
    el.inputProgramImport?.click();
}

async function saveActiveProject() {
    if (state.olp.enabled) {
        await saveOlpProjectAsZip();
        return;
    }
    await exportMotionProject();
}

function setSimulationWorkspaceFileBusy(busy) {
    simulationWorkspaceFileBusy = Boolean(busy);
    if (el.btnWorkspaceSave) el.btnWorkspaceSave.disabled = simulationWorkspaceFileBusy;
    if (el.btnWorkspaceLoad) {
        el.btnWorkspaceLoad.disabled = simulationWorkspaceFileBusy || isMotionActive() || isOlpRunning();
    }
}

function sanitizeSimulationWorkspaceFileName(value) {
    const sanitized = String(value || '')
        .replace(/[<>:"/\\|?*\u0000-\u001f]/g, '_')
        .replace(/\s+/g, ' ')
        .trim()
        .replace(/[. ]+$/g, '');
    return sanitized.slice(0, 96) || 'InoRobotSimulation';
}

function getSimulationWorkspaceFileName(snapshot) {
    const firstRobot = snapshot?.motionProject?.robots?.[0]?.displayName;
    const firstModel = snapshot?.importedModels?.[0]?.name || snapshot?.catalogModels?.[0]?.name;
    return `${sanitizeSimulationWorkspaceFileName(firstRobot || firstModel || 'InoRobotSimulation')}.inosim`;
}

function isSafeSimulationWorkspaceArchivePath(value) {
    const path = String(value || '').replaceAll('\\', '/');
    return Boolean(path)
        && !path.startsWith('/')
        && !/^[A-Za-z]:/.test(path)
        && !path.split('/').includes('..');
}

async function collectSimulationWorkspaceBundleAssets(snapshot) {
    const recovery = state.workspaceRecovery;
    if (!recovery.db) throw new Error('시뮬레이션 저장소를 사용할 수 없습니다.');
    const assetIds = WorkspaceRecovery.collectWorkspaceAssetIds(snapshot);
    const assets = [];
    for (const id of assetIds) {
        const asset = await recovery.db.getAsset(id, { touch: true });
        if (!asset?.blob) throw new Error(`저장에 필요한 파일을 찾을 수 없습니다: ${asset?.name || id}`);
        assets.push({
            id,
            name: String(asset.name || id),
            type: String(asset.type || asset.blob.type || 'application/octet-stream'),
            size: Number(asset.size) || asset.blob.size,
            extension: String(asset.extension || '').toLowerCase(),
            lastModified: Number(asset.lastModified) || 0,
            path: `assets/${encodeURIComponent(id)}.bin`,
            blob: asset.blob
        });
    }
    return assets;
}

async function saveSimulationWorkspaceProject() {
    if (simulationWorkspaceFileBusy) return;
    if (!state.workspaceRecovery.ready || !state.workspaceRecovery.db) {
        setStatus('시뮬레이션 저장소가 아직 준비되지 않았습니다.', '#ef4444');
        return;
    }

    setSimulationWorkspaceFileBusy(true);
    showLoading(true, uiText('시뮬레이션 프로젝트 저장 중...'));
    try {
        await saveMotionProjectNow();
        const snapshot = serializeWorkspaceSnapshot();
        const assets = await collectSimulationWorkspaceBundleAssets(snapshot);
        const manifest = {
            format: SIMULATION_WORKSPACE_FILE_FORMAT,
            schemaVersion: SIMULATION_WORKSPACE_FILE_SCHEMA_VERSION,
            exportedAt: new Date().toISOString(),
            workspaceFile: 'workspace.json',
            projectName: getSimulationWorkspaceFileName(snapshot).replace(/\.inosim$/i, ''),
            assets: assets.map(({ blob, ...metadata }) => metadata)
        };
        const zip = new window.JSZip();
        zip.file('manifest.json', JSON.stringify(manifest, null, 2));
        zip.file(manifest.workspaceFile, JSON.stringify(snapshot, null, 2));
        assets.forEach((asset) => zip.file(asset.path, asset.blob));
        const blob = await zip.generateAsync({
            type: 'blob',
            compression: 'DEFLATE',
            compressionOptions: { level: 6 }
        });
        const suggestedName = getSimulationWorkspaceFileName(snapshot);
        let savedName = suggestedName;
        if (typeof window.showSaveFilePicker === 'function') {
            const fileHandle = await window.showSaveFilePicker({
                id: 'inorobot-simulation-workspace',
                suggestedName,
                startIn: 'documents',
                excludeAcceptAllOption: true,
                types: [{
                    description: 'InoRobot Simulation Workspace',
                    accept: { 'application/zip': ['.inosim'] }
                }]
            });
            const writable = await fileHandle.createWritable();
            await writable.write(blob);
            await writable.close();
            savedName = fileHandle.name;
        } else if (typeof window.saveAs === 'function') {
            window.saveAs(blob, suggestedName);
        } else {
            const url = URL.createObjectURL(blob);
            const anchor = document.createElement('a');
            anchor.href = url;
            anchor.download = suggestedName;
            anchor.click();
            window.setTimeout(() => URL.revokeObjectURL(url), 1000);
        }
        setStatus('시뮬레이션 프로젝트 저장됨: {name}', '#22c55e', { name: savedName });
    } catch (error) {
        if (error?.name === 'AbortError') {
            setStatus('시뮬레이션 프로젝트 저장을 취소했습니다.', '#60a5fa');
        } else {
            console.error('Simulation workspace export failed:', error);
            setStatus('시뮬레이션 프로젝트 저장에 실패했습니다.', '#ef4444');
        }
    } finally {
        showLoading(false);
        setSimulationWorkspaceFileBusy(false);
        updateMotionUiLock();
    }
}

function remapSimulationWorkspaceAssetIds(snapshot, assetIdMap) {
    const cloned = JSON.parse(JSON.stringify(snapshot));
    const rewrite = (value, key = '') => {
        if (Array.isArray(value)) return value.map((entry) => rewrite(entry));
        if (!value || typeof value !== 'object') {
            return key === 'assetId' && assetIdMap.has(String(value))
                ? assetIdMap.get(String(value))
                : value;
        }
        Object.entries(value).forEach(([entryKey, entryValue]) => {
            value[entryKey] = rewrite(entryValue, entryKey);
        });
        return value;
    };
    rewrite(cloned);
    if (Array.isArray(cloned.assetIds)) {
        cloned.assetIds = cloned.assetIds.map((id) => assetIdMap.get(String(id)) || id);
    }
    return cloned;
}

async function readSimulationWorkspaceBundle(file) {
    if (typeof window.JSZip === 'undefined') throw new Error('ZIP 라이브러리를 불러오지 못했습니다.');
    const zip = await window.JSZip.loadAsync(await file.arrayBuffer());
    const manifestEntry = zip.file('manifest.json');
    if (!manifestEntry) throw new Error('시뮬레이션 프로젝트 manifest.json이 없습니다.');
    let manifest;
    try {
        manifest = JSON.parse(await manifestEntry.async('string'));
    } catch {
        throw new Error('시뮬레이션 프로젝트 manifest.json을 읽을 수 없습니다.');
    }
    if (manifest?.format !== SIMULATION_WORKSPACE_FILE_FORMAT
        || Number(manifest?.schemaVersion) !== SIMULATION_WORKSPACE_FILE_SCHEMA_VERSION) {
        throw new Error('지원하지 않는 시뮬레이션 프로젝트 파일입니다.');
    }
    const workspaceFile = String(manifest.workspaceFile || 'workspace.json');
    if (!isSafeSimulationWorkspaceArchivePath(workspaceFile)) {
        throw new Error('시뮬레이션 프로젝트 경로가 올바르지 않습니다.');
    }
    const workspaceEntry = zip.file(workspaceFile);
    if (!workspaceEntry) throw new Error('시뮬레이션 프로젝트 workspace.json이 없습니다.');
    let snapshot;
    try {
        snapshot = JSON.parse(await workspaceEntry.async('string'));
    } catch {
        throw new Error('시뮬레이션 프로젝트 상태를 읽을 수 없습니다.');
    }
    if (!snapshot || typeof snapshot !== 'object') throw new Error('시뮬레이션 프로젝트 상태가 올바르지 않습니다.');
    const assetMetadata = Array.isArray(manifest.assets) ? manifest.assets : [];
    const assetById = new Map(assetMetadata.map((asset) => [String(asset?.id || ''), asset]));
    const requiredAssetIds = WorkspaceRecovery.collectWorkspaceAssetIds(snapshot);
    const assets = [];
    for (const id of requiredAssetIds) {
        const metadata = assetById.get(String(id));
        if (!metadata || !isSafeSimulationWorkspaceArchivePath(metadata.path)) {
            throw new Error(`시뮬레이션 프로젝트 파일이 누락되었습니다: ${metadata?.name || id}`);
        }
        const entry = zip.file(metadata.path);
        if (!entry) throw new Error(`시뮬레이션 프로젝트 파일이 누락되었습니다: ${metadata.name || id}`);
        const blob = await entry.async('blob');
        if (Number(metadata.size) !== blob.size) {
            throw new Error(`시뮬레이션 프로젝트 파일 크기가 일치하지 않습니다: ${metadata.name || id}`);
        }
        assets.push({
            id: String(id),
            name: String(metadata.name || id),
            type: String(metadata.type || blob.type || 'application/octet-stream'),
            size: blob.size,
            extension: String(metadata.extension || '').toLowerCase(),
            lastModified: Number(metadata.lastModified) || Date.now(),
            blob
        });
    }
    return { manifest, snapshot, assets };
}

async function importSimulationWorkspaceProject(file) {
    if (!file || simulationWorkspaceFileBusy) return;
    if (!state.workspaceRecovery.ready || !state.workspaceRecovery.db) {
        setStatus('시뮬레이션 저장소가 아직 준비되지 않았습니다.', '#ef4444');
        return;
    }
    if (isMotionActive() || isOlpRunning()) {
        setStatus('프로젝트를 불러오기 전에 로봇 모션과 OLP 실행을 정지하세요.', '#f59e0b');
        return;
    }
    const previousSnapshot = serializeWorkspaceSnapshot();
    if (workspaceSnapshotHasWork(previousSnapshot)
        && !window.confirm(uiText('현재 시뮬레이션 작업을 새 프로젝트로 바꾸시겠습니까?'))) return;

    setSimulationWorkspaceFileBusy(true);
    showLoading(true, uiText('시뮬레이션 프로젝트 불러오는 중...'));
    try {
        const bundle = await readSimulationWorkspaceBundle(file);
        const assetIdMap = new Map();
        for (const asset of bundle.assets) {
            const newId = WorkspaceRecovery.createWorkspaceId('asset');
            await state.workspaceRecovery.db.putAsset({
                id: newId,
                name: asset.name,
                type: asset.type,
                size: asset.size,
                extension: asset.extension,
                lastModified: asset.lastModified,
                blob: asset.blob
            });
            assetIdMap.set(asset.id, newId);
        }
        const snapshot = remapSimulationWorkspaceAssetIds(bundle.snapshot, assetIdMap);
        const warnings = await restoreWorkspaceSnapshot(snapshot);
        await saveMotionProjectNow();
        if (warnings.length) {
            setStatus('프로젝트를 불러왔지만 일부 항목을 복원하지 못했습니다.', '#f59e0b');
        } else {
            setStatus('{name}을(를) 불러왔습니다.', '#22c55e', {
                name: bundle.manifest.projectName || file.name
            });
        }
    } catch (error) {
        console.error('Simulation workspace import failed:', error);
        try {
            await restoreWorkspaceSnapshot(previousSnapshot);
            await saveMotionProjectNow();
        } catch (restoreError) {
            console.error('Previous simulation workspace restore failed:', restoreError);
        }
        setStatus(error?.message || '시뮬레이션 프로젝트 불러오기에 실패했습니다.', '#ef4444');
    } finally {
        showLoading(false);
        setSimulationWorkspaceFileBusy(false);
        updateMotionUiLock();
    }
}

async function saveStandalonePFile(content, suggestedName = 'P.pts') {
    const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
    if (typeof window.showSaveFilePicker === 'function') {
        const fileHandle = await window.showSaveFilePicker({
            id: 'inorobot-position-points',
            suggestedName,
            startIn: 'documents',
            excludeAcceptAllOption: true,
            types: [{
                description: 'InoRobot P.pts position file',
                accept: { 'text/plain': ['.pts'] }
            }]
        });
        const writable = await fileHandle.createWritable();
        await writable.write(blob);
        await writable.close();
        return fileHandle.name;
    }
    saveAs(blob, suggestedName);
    return suggestedName;
}

// Keep P.pts headers identical to 4_ProjectGenerator/generator.js DataPoints.
// This is intentionally locale-independent; browser/Windows locale must not
// change the controller's Korean 오전/오후 timestamp convention.
function formatProjectGeneratorPFileTime(date = new Date()) {
    const pad = (value) => String(value).padStart(2, '0');
    const hours = date.getHours();
    const meridiem = hours < 12 ? '오전' : '오후';
    const hour12 = hours % 12 || 12;
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${meridiem} ${hour12}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
}

function getSelectedRobotProgramName() {
    const robot = state.activeProgramRobot || state.activeArticulatedModel;
    return robot?.userData?.robotName
        || robot?.userData?.modelName
        || getOlpProject()?.projectInfo?.RobotName
        || 'SelectedRobot';
}

function normalizeExportedPFileContent(content, robotName = getSelectedRobotProgramName()) {
    const normalized = String(content ?? '').replace(/^\uFEFF/, '').replace(/\r\n?/g, '\n');
    const headerMatch = normalized.match(/^(?:[ \t]*\n)*[ \t]*ProgramInfo\b[\s\S]*?^[ \t]*EndProgramInfo\b[^\n]*(?:\n|$)/im);
    const body = (headerMatch ? normalized.slice(headerMatch[0].length) : normalized)
        .replace(/^\s+/, '')
        .trimEnd();
    const header = [
        'ProgramInfo',
        '    Version = "S4.24"',
        '    VRC = "V4R24"',
        `    Time = "${formatProjectGeneratorPFileTime()}"`,
        `    RobotName = "${robotName}"`,
        'EndProgramInfo'
    ].join('\r\n');
    // The robot controller accepts Windows text files only. Normalize both
    // the generated header and the imported point records to CRLF so an OLP
    // project originally stored with LF can still be exported directly.
    return `${header}\r\n${body ? `${body.replace(/\n/g, '\r\n')}\r\n` : ''}`;
}

async function exportPositionPoints() {
    const activeOlpProject = getOlpProject();
    if (state.olp.enabled && activeOlpProject) {
        const pointFile = activeOlpProject.pointFiles?.find((entry) => /(^|\/)P\.pts$/i.test(entry.path))
            || activeOlpProject.pointFiles?.find((entry) => entry.kind === 'point');
        const record = pointFile ? activeOlpProject.files?.get(pointFile.path) : null;
        if (!record || typeof record.text !== 'string') {
            setMotionProgramStatus('OLP 프로젝트에 P.pts 파일이 없습니다.', 'error');
            return;
        }
        try {
            const name = await saveStandalonePFile(
                normalizeExportedPFileContent(record.text),
                'P.pts'
            );
            setMotionProgramStatus('P.pts 내보내기 완료: {name}', '', { name });
            setStatus('P.pts 내보내기 완료', '#22c55e');
        } catch (error) {
            if (error?.name === 'AbortError') return;
            console.error('OLP P.pts export failed:', error);
            setMotionProgramStatus('P.pts 내보내기에 실패했습니다.', 'error');
            setStatus('P.pts 내보내기 실패', '#ef4444');
        }
        return;
    }
    const robot = state.activeProgramRobot;
    const program = ensureMotionProgram(robot);
    const points = (program?.steps || [])
        .filter((step) => isMotionPointMotion(step.motion))
        .sort((left, right) => left.pointIndex - right.pointIndex);
    if (!robot || points.length === 0) {
        setMotionProgramStatus('내보낼 위치 포인트가 없습니다.', 'error');
        setStatus('내보낼 위치 포인트가 없습니다.', '#ef4444');
        return;
    }
    const used = new Set();
    for (const step of points) {
        if (!Number.isInteger(step.pointIndex)
            || step.pointIndex < MIN_POINT_INDEX
            || step.pointIndex > MAX_POINT_INDEX
            || used.has(step.pointIndex)) {
            setMotionProgramStatus('포인트 번호를 확인하세요. 중복되거나 범위를 벗어난 번호가 있습니다.', 'error');
            return;
        }
        if (!isValidMotionPointLabel(step.label || '')) {
            setMotionProgramStatus('{name} 라벨 형식이 올바르지 않습니다.', 'error', {
                name: formatMotionPointName(step.pointIndex)
            });
            return;
        }
        used.add(step.pointIndex);
    }

    const content = normalizeExportedPFileContent(
        `${points.map((step) => formatPositionPointRecord(robot, step)).join('\n')}\n`,
        getSelectedRobotProgramName()
    );
    const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
    try {
        if (typeof window.showSaveFilePicker === 'function') {
            const fileHandle = await window.showSaveFilePicker({
                id: 'inorobot-position-points',
                suggestedName: 'P.pts',
                startIn: 'documents',
                excludeAcceptAllOption: true,
                types: [{
                    description: 'InoRobot P.pts position file',
                    accept: { 'text/plain': ['.pts'] }
                }]
            });
            const writable = await fileHandle.createWritable();
            await writable.write(blob);
            await writable.close();
            setMotionProgramStatus('P.pts 내보내기 완료: {name}', '', { name: fileHandle.name });
        } else {
            saveAs(blob, 'P.pts');
            setMotionProgramStatus('P.pts 내보내기 완료: {name}', '', { name: 'P.pts' });
        }
        setStatus('P.pts 내보내기 완료', '#22c55e');
    } catch (error) {
        if (error?.name === 'AbortError') {
            setMotionProgramStatus('위치 값 내보내기를 취소했습니다.');
            return;
        }
        console.error('Position point export failed:', error);
        setMotionProgramStatus('위치 값 내보내기에 실패했습니다.', 'error');
        setStatus('위치 값 내보내기에 실패했습니다.', '#ef4444');
    }
}

function serializeMotionProgramFileWorkOrigin(workOrigin) {
    if (!workOrigin) return null;
    return {
        mode: 'JOINT',
        joints: [...workOrigin.joints],
        tcp: {
            position: [...workOrigin.tcp.position],
            quaternion: [...workOrigin.tcp.quaternion]
        },
        outputBit: Number(workOrigin.outputBit)
    };
}

function serializeWorkspaceOlpProjects() {
    syncActiveOlpProjectView();
    const robotsById = new Map(getArticulatedRobots().map((robot) => (
        [getOlpRobotInstanceId(robot), robot]
    )));
    const entries = state.olp.projects instanceof Map
        ? [...state.olp.projects.entries()]
            .map(([instanceId, project]) => ({
                robot: robotsById.get(instanceId) || null,
                project
            }))
            .filter((entry) => entry.robot && entry.project)
        : [];
    if (!entries.length && state.olp.project?.files) {
        entries.push({ robot: getOlpRobot(), project: state.olp.project });
    }
    return entries
        .map(({ robot, project }) => serializeWorkspaceOlpProject(robot, project))
        .filter(Boolean);
}

function serializeMotionProgramFileStep(step, robotIndexByInstanceId) {
    const motion = String(step.motion || 'MOVJ');
    const record = {
        id: String(step.id),
        name: String(step.name || ''),
        motion,
        joints: [...step.joints],
        tcp: {
            position: [...step.tcp.position],
            quaternion: [...step.tcp.quaternion]
        }
    };
    if (isMotionPointMotion(motion)) {
        record.pointIndex = step.pointIndex;
        record.label = step.label || '';
        record.armParameters = [...(step.armParameters || [0, 0, 0, 1])];
        record.externalAxes = [...(step.externalAxes || [0, 0, 0, 0, 0, 0])];
    }
    if (motion === 'DELAY') record.delaySeconds = step.delaySeconds;
    if (motion === 'MOVJ' || motion === 'MOVL') record.speed = step.speed;
    if (motion === 'VIEW') record.viewSlot = step.viewSlot;
    if (isGripObjectMotion(motion)) record.gripObjectRef = step.gripObjectRef || '';
    if (isWaitMotion(motion)) {
        record.waitRobotIndex = robotIndexByInstanceId.has(step.waitRobotInstanceId)
            ? robotIndexByInstanceId.get(step.waitRobotInstanceId)
            : null;
        record.waitLineNumber = step.waitLineNumber;
    }
    return record;
}

function serializeMotionProgramFile() {
    const robots = getArticulatedRobots();
    const robotIndexByInstanceId = new Map(robots.map((robot, index) => (
        [robot.userData.motionInstanceId, index]
    )));
    const priorityRobotIndex = robotIndexByInstanceId.has(state.robotInterferenceAvoidance.priorityRobotId)
        ? robotIndexByInstanceId.get(state.robotInterferenceAvoidance.priorityRobotId)
        : null;
    return {
        format: MOTION_PROGRAM_FILE_FORMAT,
        schemaVersion: MOTION_PROGRAM_FILE_SCHEMA_VERSION,
        exportedAt: new Date().toISOString(),
        repeatCurrentRobot: Boolean(state.motionRepeatRobot),
        repeat: Boolean(state.motionRepeat),
        reverseRepeatCurrentRobot: Boolean(state.motionReverseRepeatRobot),
        reverseRepeat: Boolean(state.motionReverseRepeat),
        robotInterferenceAvoidance: {
            enabled: Boolean(state.robotInterferenceAvoidance.enabled),
            priorityRobotIndex
        },
        robots: robots.map((robot, index) => {
            const program = ensureMotionProgram(robot);
            return {
                index,
                jointCount: robot.userData.joints.length,
                included: Boolean(program.included),
                selectedStepId: program.selectedStepId || null,
                workOrigin: serializeMotionProgramFileWorkOrigin(program.workOrigin),
                steps: program.steps.map((step) => serializeMotionProgramFileStep(step, robotIndexByInstanceId))
            };
        })
    };
}

function normalizeMotionProgramFileArray(value, length, label) {
    if (!Array.isArray(value) || value.length !== length) {
        throw new Error(`${label} must contain ${length} values.`);
    }
    const numbers = value.map(Number);
    if (!numbers.every(Number.isFinite)) throw new Error(`${label} must contain finite numbers.`);
    return numbers;
}

function normalizeMotionProgramFileWorkOrigin(workOrigin, jointCount) {
    if (!workOrigin) return null;
    return {
        mode: 'JOINT',
        joints: normalizeMotionProgramFileArray(workOrigin.joints, jointCount, 'Work Origin joints'),
        tcp: {
            position: normalizeMotionProgramFileArray(workOrigin.tcp?.position, 3, 'Work Origin TCP position'),
            quaternion: normalizeMotionProgramFileArray(workOrigin.tcp?.quaternion, 4, 'Work Origin TCP quaternion')
        },
        outputBit: Number.isSafeInteger(Number(workOrigin.outputBit))
            && Number(workOrigin.outputBit) >= 0
            ? Number(workOrigin.outputBit)
            : 519
    };
}

function normalizeMotionProgramFileStep(step, jointCount, stepIndex) {
    if (!step || typeof step !== 'object') throw new Error(`Program step ${stepIndex + 1} is invalid.`);
    const motion = String(step.motion || '').trim();
    if (!MOTION_PROGRAM_FILE_MOTIONS.has(motion)) throw new Error(`Unsupported program motion: ${motion}`);
    const id = String(step.id || '').trim();
    if (!id) throw new Error(`Program step ${stepIndex + 1} has no id.`);
    const normalized = {
        id,
        name: String(step.name || ''),
        motion,
        joints: normalizeMotionProgramFileArray(step.joints, jointCount, `Program step ${stepIndex + 1} joints`),
        tcp: {
            position: normalizeMotionProgramFileArray(step.tcp?.position, 3, `Program step ${stepIndex + 1} TCP position`),
            quaternion: normalizeMotionProgramFileArray(step.tcp?.quaternion, 4, `Program step ${stepIndex + 1} TCP quaternion`)
        }
    };
    if (isMotionPointMotion(motion)) {
        const pointIndex = Number(step.pointIndex);
        const label = String(step.label || '').trim();
        if (!Number.isInteger(pointIndex) || pointIndex < MIN_POINT_INDEX || pointIndex > MAX_POINT_INDEX) {
            throw new Error(`Program step ${stepIndex + 1} has an invalid point index.`);
        }
        if (!isValidMotionPointLabel(label)) throw new Error(`Program step ${stepIndex + 1} has an invalid label.`);
        normalized.pointIndex = pointIndex;
        normalized.label = label;
        normalized.armParameters = normalizeMotionProgramFileArray(
            step.armParameters,
            4,
            `Program step ${stepIndex + 1} arm parameters`
        );
        normalized.externalAxes = normalizeMotionProgramFileArray(
            step.externalAxes,
            6,
            `Program step ${stepIndex + 1} external axes`
        );
    }
    if (motion === 'DELAY') {
        const delaySeconds = Number(step.delaySeconds);
        if (!Number.isFinite(delaySeconds) || delaySeconds < MIN_DELAY_SECONDS || delaySeconds > MAX_DELAY_SECONDS) {
            throw new Error(`Program step ${stepIndex + 1} has an invalid delay.`);
        }
        normalized.delaySeconds = delaySeconds;
    }
    if (motion === 'MOVJ' || motion === 'MOVL') {
        const speed = Number(step.speed);
        if (!Number.isFinite(speed) || speed <= 0) throw new Error(`Program step ${stepIndex + 1} has an invalid speed.`);
        normalized.speed = speed;
    }
    if (motion === 'VIEW') {
        const viewSlot = Number(step.viewSlot);
        if (!Number.isInteger(viewSlot) || viewSlot < 0 || viewSlot >= VIEW_PRESET_COUNT) {
            throw new Error(`Program step ${stepIndex + 1} has an invalid view slot.`);
        }
        normalized.viewSlot = viewSlot;
    }
    if (isGripObjectMotion(motion)) normalized.gripObjectRef = String(step.gripObjectRef || '').trim();
    if (isWaitMotion(motion)) {
        const waitRobotIndex = step.waitRobotIndex === null || step.waitRobotIndex === undefined
            ? null
            : Number(step.waitRobotIndex);
        if (waitRobotIndex !== null && (!Number.isInteger(waitRobotIndex) || waitRobotIndex < 0)) {
            throw new Error(`Program step ${stepIndex + 1} has an invalid WAIT target.`);
        }
        const waitLineNumber = Number(step.waitLineNumber);
        if (!Number.isInteger(waitLineNumber)
            || waitLineNumber < MIN_WAIT_LINE_NUMBER
            || waitLineNumber > MAX_WAIT_LINE_NUMBER) {
            throw new Error(`Program step ${stepIndex + 1} has an invalid WAIT line.`);
        }
        normalized.waitRobotIndex = waitRobotIndex;
        normalized.waitLineNumber = waitLineNumber;
    }
    return normalized;
}

function normalizeMotionProgramFile(input) {
    if (!input || typeof input !== 'object'
        || input.format !== MOTION_PROGRAM_FILE_FORMAT
        || Number(input.schemaVersion) !== MOTION_PROGRAM_FILE_SCHEMA_VERSION) {
        throw new Error('Unsupported motion program file.');
    }
    if (!Array.isArray(input.robots)) throw new Error('Motion program file robots must be an array.');
    const robots = input.robots.map((entry, index) => {
        const jointCount = Number(entry?.jointCount);
        if (!Number.isInteger(jointCount) || jointCount < 1 || jointCount > 12) {
            throw new Error(`Program robot ${index + 1} has an invalid joint count.`);
        }
        const steps = (Array.isArray(entry.steps) ? entry.steps : [])
            .map((step, stepIndex) => normalizeMotionProgramFileStep(step, jointCount, stepIndex));
        const stepIds = new Set();
        const pointIndices = new Set();
        steps.forEach((step) => {
            if (stepIds.has(step.id)) throw new Error(`Duplicate program step id: ${step.id}`);
            stepIds.add(step.id);
            if (isMotionPointMotion(step.motion)) {
                if (pointIndices.has(step.pointIndex)) throw new Error(`Duplicate program point index: ${step.pointIndex}`);
                pointIndices.add(step.pointIndex);
            }
        });
        return {
            index,
            jointCount,
            included: entry.included !== false,
            selectedStepId: stepIds.has(entry.selectedStepId) ? entry.selectedStepId : null,
            workOrigin: normalizeMotionProgramFileWorkOrigin(entry.workOrigin, jointCount),
            steps
        };
    });
    const priorityRobotIndex = input.robotInterferenceAvoidance?.priorityRobotIndex;
    return {
        repeatCurrentRobot: Boolean(input.repeatCurrentRobot),
        repeat: Boolean(input.repeat),
        reverseRepeatCurrentRobot: Boolean(input.reverseRepeatCurrentRobot),
        reverseRepeat: Boolean(input.reverseRepeat),
        robotInterferenceAvoidance: {
            enabled: Boolean(input.robotInterferenceAvoidance?.enabled),
            priorityRobotIndex: priorityRobotIndex === null || priorityRobotIndex === undefined
                ? null
                : Number(priorityRobotIndex)
        },
        robots
    };
}

function captureMotionProgramPanelState() {
    return {
        motionPrograms: getArticulatedRobots().map((robot) => ({
            robot,
            program: cloneMotionProgram(ensureMotionProgram(robot))
        })),
        motionRepeatRobot: state.motionRepeatRobot,
        motionRepeat: state.motionRepeat,
        motionReverseRepeatRobot: state.motionReverseRepeatRobot,
        motionReverseRepeat: state.motionReverseRepeat,
        robotInterferenceAvoidance: {
            enabled: Boolean(state.robotInterferenceAvoidance.enabled),
            priorityRobotId: state.robotInterferenceAvoidance.priorityRobotId || null
        }
    };
}

function restoreMotionProgramPanelState(snapshot) {
    state.motionPrograms = new Map((snapshot?.motionPrograms || [])
        .filter((entry) => entry.robot?.userData?.motionInstanceId)
        .map((entry) => [entry.robot.userData.motionInstanceId, cloneMotionProgram(entry.program)]));
    state.motionRepeatRobot = Boolean(snapshot?.motionRepeatRobot);
    state.motionRepeat = Boolean(snapshot?.motionRepeat);
    state.motionReverseRepeatRobot = Boolean(snapshot?.motionReverseRepeatRobot);
    state.motionReverseRepeat = Boolean(snapshot?.motionReverseRepeat);
    state.robotInterferenceAvoidance = {
        enabled: Boolean(snapshot?.robotInterferenceAvoidance?.enabled),
        priorityRobotId: snapshot?.robotInterferenceAvoidance?.priorityRobotId || null
    };
    syncMotionRepeatControl();
    syncWorkOriginOutputStates();
    renderMotionProgramPanel();
    updateMotionProgramPlaybackUi();
}

function restoreMotionProgramFileData(input) {
    if (isMotionActive()) throw new Error('Stop all robot motions before loading a program.');
    const project = normalizeMotionProgramFile(input);
    const robots = getArticulatedRobots();
    const warnings = [];
    const nextPrograms = new Map();
    robots.forEach((robot, index) => {
        const instanceId = ensureMotionProgram(robot) && robot.userData.motionInstanceId;
        const saved = project.robots[index];
        if (!saved) {
            nextPrograms.set(instanceId, createEmptyMotionProgram(false));
            return;
        }
        if (saved.jointCount !== robot.userData.joints.length) {
            warnings.push(`Robot ${index + 1} joint count mismatch.`);
            nextPrograms.set(instanceId, createEmptyMotionProgram(false));
            return;
        }
        const steps = saved.steps.map((step) => ({
            ...step,
            waitRobotInstanceId: Number.isInteger(step.waitRobotIndex)
                ? robots[step.waitRobotIndex]?.userData?.motionInstanceId || ''
                : ''
        }));
        if (saved.steps.some((step) => Number.isInteger(step.waitRobotIndex) && !robots[step.waitRobotIndex])) {
            warnings.push(`Robot ${index + 1} has a WAIT target that is unavailable.`);
        }
        nextPrograms.set(instanceId, cloneMotionProgram({
            included: saved.included,
            selectedStepId: saved.selectedStepId,
            workOrigin: saved.workOrigin,
            steps
        }));
    });
    if (project.robots.length !== robots.length) warnings.push('The number of program robots differs from the current simulation.');
    const priorityRobotIndex = project.robotInterferenceAvoidance.priorityRobotIndex;
    if (priorityRobotIndex !== null
        && (!Number.isInteger(priorityRobotIndex) || !robots[priorityRobotIndex])) {
        warnings.push('The saved interference-avoidance priority robot is unavailable.');
    }
    state.motionPrograms = nextPrograms;
    state.motionRepeatRobot = project.repeatCurrentRobot;
    state.motionRepeat = project.repeat;
    state.motionReverseRepeatRobot = project.reverseRepeatCurrentRobot;
    state.motionReverseRepeat = project.reverseRepeat;
    state.robotInterferenceAvoidance = {
        enabled: project.robotInterferenceAvoidance.enabled,
        priorityRobotId: robots[priorityRobotIndex]?.userData?.motionInstanceId || null
    };
    syncMotionRepeatControl();
    syncWorkOriginOutputStates();
    updateUIStatus();
    renderMotionProgramPanel();
    updateMotionProgramPlaybackUi();
    scheduleMotionProjectSave();
    return { warnings };
}

async function exportMotionProject() {
    const suggestedName = `InoRobot-Program-${new Date().toISOString().slice(0, 10)}.json`;
    try {
        const project = serializeMotionProgramFile();
        const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json;charset=utf-8' });
        if (typeof window.showSaveFilePicker === 'function') {
            const fileHandle = await window.showSaveFilePicker({
                id: 'inorobot-motion-program',
                suggestedName,
                startIn: 'documents',
                excludeAcceptAllOption: true,
                types: [{
                    description: 'InoRobot Motion Program',
                    accept: { 'application/json': ['.json'] }
                }]
            });
            const writable = await fileHandle.createWritable();
            await writable.write(blob);
            await writable.close();
            setMotionProgramStatus('프로그램 저장됨: {name}', '', { name: fileHandle.name });
        } else {
            saveAs(blob, suggestedName);
            setMotionProgramStatus('프로그램 저장됨: {name}', '', { name: suggestedName });
        }
    } catch (error) {
        if (error?.name === 'AbortError') {
            setMotionProgramStatus('프로그램 저장을 취소했습니다.');
            return;
        }
        console.error('Motion program export failed:', error);
        setMotionProgramStatus('프로그램 내보내기에 실패했습니다.', 'error');
    }
}

async function handleMotionProjectImport() {
    const file = el.inputProgramImport?.files?.[0];
    if (el.inputProgramImport) el.inputProgramImport.value = '';
    if (!file || isMotionActive()) return;
    const beforeScene = captureSceneSnapshot();
    const beforeProgram = captureMotionProgramPanelState();
    try {
        const project = JSON.parse(await file.text());
        const result = restoreMotionProgramFileData(project);
        recordHistory('프로그램 불러오기', beforeScene, captureSceneSnapshot());
        if (result.warnings.length) {
            setMotionProgramStatus('프로그램을 불러왔지만 일부 항목을 적용하지 못했습니다.', 'error');
        } else {
            setMotionProgramStatus('{name} 프로그램을 불러왔습니다.', '', { name: file.name });
        }
    } catch (error) {
        console.error('Motion program import failed:', error);
        restoreMotionProgramPanelState(beforeProgram);
        showLoading(false);
        setMotionProgramStatus('프로그램 불러오기에 실패했습니다.', 'error');
    }
}

function restoreRobotJointAngles(robot, angles) {
    withCollisionPoseProbe(() => {
        angles.forEach((angle, index) => setJointAngle(robot.userData.joints[index], angle, false));
        robot.updateMatrixWorld(true);
    });
    if (Number(state.collision.poseProbeDepth) === 0) {
        syncJointControls(robot);
        if (robot === state.activeArticulatedModel) captureCurrentTcpTarget(robot);
    }
}

function motionStepTargetPose(step) {
    return {
        position: new THREE.Vector3().fromArray(step.tcp.position),
        quaternion: new THREE.Quaternion().fromArray(step.tcp.quaternion).normalize()
    };
}

function getAutoPathPointPoseAtJoints(robot, angles) {
    const originalAngles = robot.userData.joints.map((joint) => joint.angle);
    applyPlanningJointAngles(robot, angles);
    try {
        return getCurrentTcpPoseBase(robot);
    } finally {
        applyPlanningJointAngles(robot, originalAngles);
    }
}

function resolveAutoPathPointPose(robot, step, angles) {
    const storedPose = motionStepTargetPose(step);
    const actualPose = getAutoPathPointPoseAtJoints(robot, angles);
    if (!actualPose) return { pose: storedPose, needsSync: false };

    // A motion point stores both joints and TCP data. If the active TCP
    // profile was edited after the point was taught, those two values no
    // longer describe the same physical pose. The planner must use the TCP
    // generated from the selected joints and the current profile; otherwise
    // its IK stages and preview are offset from the real Tool/TCP geometry.
    const positionMismatch = storedPose.position.distanceTo(actualPose.position) > 0.8;
    const orientationMismatch = THREE.MathUtils.radToDeg(
        storedPose.quaternion.angleTo(actualPose.quaternion)
    ) > 0.35;
    return {
        pose: actualPose,
        needsSync: positionMismatch || orientationMismatch
    };
}

function validateMovjTarget(robot, step) {
    const joints = robot.userData.joints;
    if (!Array.isArray(step.joints) || step.joints.length !== joints.length) {
        throw new Error(`${step.name}: joint count mismatch.`);
    }
    step.joints.forEach((value, index) => {
        const joint = joints[index];
        if (!Number.isFinite(value) || value < joint.definition.min - 1e-7 || value > joint.definition.max + 1e-7) {
            throw new Error(`${step.name}: ${joint.definition.name} is outside its joint limit.`);
        }
    });
}

function solveMovlSamples(robot, target, label, { isStateSafe = null } = {}) {
    const start = getCurrentTcpPoseBase(robot);
    const distance = start.position.distanceTo(target.position);
    const rotation = THREE.MathUtils.radToDeg(start.quaternion.angleTo(target.quaternion));
    const samples = Math.max(1, Math.min(240, Math.ceil(Math.max(
        distance / MOTION_MOVL_SAMPLE_DISTANCE,
        rotation / MOTION_MOVL_SAMPLE_ANGLE
    ))));
    let seedAngles = robot.userData.joints.map((joint) => joint.angle);
    for (let sample = 1; sample <= samples; sample += 1) {
        const alpha = sample / samples;
        const pose = {
            position: new THREE.Vector3().fromArray(interpolateLinearPosition(
                start.position.toArray(),
                target.position.toArray(),
                alpha
            )),
            quaternion: new THREE.Quaternion().fromArray(slerpQuaternion(
                start.quaternion.toArray(),
                target.quaternion.toArray(),
                alpha
            ))
        };
        applyPlanningJointAngles(robot, seedAngles);
        const previousAngles = seedAngles.slice();
        const result = solveRobotIK(robot, pose);
        if (!result.success) {
            restoreRobotJointAngles(robot, previousAngles);
            throw new Error(`${label}: unreachable or outside joint limits.`);
        }
        const solvedAngles = robot.userData.joints.map((joint) => joint.angle);
        if (isStateSafe && !isStateSafe(solvedAngles)) {
            restoreRobotJointAngles(robot, previousAngles);
            throw new Error(`${label}: collision detected along the path.`);
        }
        seedAngles = solvedAngles;
    }
}

function validateWaitStep(robot, step) {
    if (!isWaitMotion(step?.motion)) return;
    const targetRobot = findProgramRobot(step.waitRobotInstanceId);
    if (!targetRobot) throw new Error(`${step.name}: 대기 대상 로봇을 찾을 수 없습니다.`);
    if (targetRobot === robot) throw new Error(`${step.name}: 자기 자신은 대기 대상이 될 수 없습니다.`);
    const lineNumber = Number(step.waitLineNumber);
    if (!Number.isInteger(lineNumber)
        || lineNumber < MIN_WAIT_LINE_NUMBER
        || lineNumber > MAX_WAIT_LINE_NUMBER) {
        throw new Error(`${step.name}: 대기 행 번호는 ${MIN_WAIT_LINE_NUMBER}부터 ${MAX_WAIT_LINE_NUMBER} 사이여야 합니다.`);
    }
    const targetProgram = ensureMotionProgram(targetRobot);
    if (!targetProgram?.steps?.[lineNumber - MIN_WAIT_LINE_NUMBER]) {
        throw new Error(`${step.name}: ${formatRobotPanelName(targetRobot.userData.motionDisplayName)}의 ${lineNumber}행을 찾을 수 없습니다.`);
    }
}

function validateMotionWaitTargets(plans) {
    const plannedRobotIds = new Set(plans.map(({ robot }) => robot?.userData?.motionInstanceId).filter(Boolean));
    plans.forEach(({ robot, steps }) => {
        steps.filter((step) => isWaitMotion(step.motion)).forEach((step) => {
            validateWaitStep(robot, step);
            const targetRobot = findProgramRobot(step.waitRobotInstanceId);
            if (!plannedRobotIds.has(targetRobot.userData.motionInstanceId)
                && !getMotionSession(targetRobot)) {
                throw new Error(`${step.name}: ${formatRobotPanelName(targetRobot.userData.motionDisplayName)}의 프로그램이 함께 실행되지 않았습니다.`);
            }
        });
    });
}

function getMotionStepEdgeSequence(program, stepId) {
    const sequence = program?.runtimeStepEdgeSequences?.get?.(stepId);
    return Number.isFinite(sequence) && sequence >= 0 ? sequence : 0;
}

function markMotionStepExecutionEdge(robot, step) {
    const program = ensureMotionProgram(robot);
    if (!program) return 0;
    if (!(program.runtimeStepEdgeSequences instanceof Map)) {
        program.runtimeStepEdgeSequences = new Map();
    }
    const nextSequence = getMotionStepEdgeSequence(program, step.id) + 1;
    program.runtimeStepEdgeSequences.set(step.id, nextSequence);
    return nextSequence;
}

function getMotionWaitState(session, segment) {
    const step = segment?.step;
    if (!step) return { ready: false, error: 'WAIT 세그먼트가 올바르지 않습니다.' };
    const targetRobot = findProgramRobot(step.waitRobotInstanceId);
    if (!targetRobot) return { ready: false, error: `${step.name}: 대기 대상 로봇을 찾을 수 없습니다.` };
    const targetProgram = ensureMotionProgram(targetRobot);
    const targetSession = getMotionSession(targetRobot);
    const targetSteps = targetSession?.steps || targetProgram?.steps || [];
    const targetStep = targetSteps[Number(step.waitLineNumber) - MIN_WAIT_LINE_NUMBER];
    if (!targetStep) {
        return { ready: false, error: `${step.name}: 대기 대상 행을 찾을 수 없습니다.` };
    }
    const waitEdgeSequence = Number.isFinite(segment.waitEdgeSequence)
        ? segment.waitEdgeSequence
        : getMotionStepEdgeSequence(targetProgram, targetStep.id);
    const targetEdgeSequence = getMotionStepEdgeSequence(targetProgram, targetStep.id);
    // WAIT is an edge-triggered event. A target row that was already running
    // when this WAIT started must not satisfy it; only a later row-start edge
    // can release the waiting robot.
    if (targetEdgeSequence > waitEdgeSequence) return { ready: true, error: '' };
    if (!targetSession) {
        return {
            ready: false,
            error: `${step.name}: ${formatRobotPanelName(targetRobot.userData.motionDisplayName)}가 대기 행에 도달하기 전에 종료되었습니다.`
        };
    }
    return { ready: false, error: '' };
}

function workOriginTargetPose(workOrigin) {
    return {
        position: new THREE.Vector3().fromArray(workOrigin.tcp.position),
        quaternion: new THREE.Quaternion().fromArray(workOrigin.tcp.quaternion).normalize()
    };
}

function validateWorkOriginMotion(robot, step) {
    const workOrigin = getRobotWorkOrigin(robot);
    if (!workOrigin || !Array.isArray(workOrigin.joints)
        || workOrigin.joints.length !== robot.userData.joints.length) {
        throw new Error(`${step.name}: Work Origin을 먼저 등록하세요.`);
    }
    workOrigin.joints.forEach((angle, index) => {
        const joint = robot.userData.joints[index];
        if (!Number.isFinite(angle)
            || angle < Number(joint.definition.min)
            || angle > Number(joint.definition.max)) {
            throw new Error(`${step.name}: 등록된 Work Origin이 관절 범위를 벗어났습니다.`);
        }
    });
    return workOrigin;
}

function preflightRobotMotion(robot, steps, { reverseRepeat = false, timerOnly = false } = {}) {
    if (!timerOnly && (!robot?.userData.joints?.length || !robot.userData.tcpFrame)) {
        throw new Error('This model does not provide articulated kinematics.');
    }
    if (!steps.length) throw new Error(`${robot.userData.motionDisplayName}: no motion points.`);
    const originalAngles = timerOnly ? null : robot.userData.joints.map((joint) => joint.angle);
    const originalBaseTransform = timerOnly ? null : captureClipboardTransform(robot);
    const originalExternalAxes = timerOnly ? null : getRobotExternalAxes(robot);
    let timerAvailable = Number.isFinite(ensureMotionProgram(robot).cycleTimerStartedAt);
    const gripObjectRefsInUse = new Set();
    const traversal = steps.map((step, cursor) => ({ step, cursor, direction: 1 }));
    if (reverseRepeat && steps.length > 1) {
        for (let cursor = steps.length - 2; cursor >= 0; cursor -= 1) {
            traversal.push({ step: steps[cursor], cursor, direction: -1 });
        }
    }

    const validateTimerAction = (action, step) => {
        if (action === 'TIME_START') {
            timerAvailable = true;
            return;
        }
        if (action === 'TIME_OUT') {
            if (!timerAvailable) throw new Error(`${step.name}: TIME START must run before TIME OUT.`);
            timerAvailable = false;
        }
    };

    try {
        traversal.forEach(({ step, cursor, direction }) => {
            const timerActions = getDirectionalTimerActions(step.motion, {
                cursor,
                direction,
                stepCount: steps.length,
                repeat: false,
                reverseRepeat
            });
            if (timerActions.length) {
                timerActions.forEach((action) => validateTimerAction(action, step));
                return;
            }
            if (isWaitMotion(step.motion)) {
                validateWaitStep(robot, step);
                return;
            }
            if (timerOnly) return;
            if (isMotionPointMotion(step.motion)) {
                applyRobotTravelAxis(robot, step.externalAxes, { syncPresentation: false });
            }
            if (isGripObjectMotion(step.motion)) {
                getDirectionalGripActions(step.motion, {
                    cursor,
                    direction,
                    stepCount: steps.length,
                    repeat: false,
                    reverseRepeat
                }).forEach((gripMotion) => {
                    const action = gripMotion === 'GRIP_USE' ? 'use' : 'release';
                    const resolved = resolveGripObjectReference(step.gripObjectRef, action);
                    if (gripMotion === 'GRIP_USE') {
                        if (!resolved || isGripObjectModelInUse(resolved.model) || gripObjectRefsInUse.has(step.gripObjectRef)) {
                            throw new Error(`${step.name}: 물건 잡기 대상을 사용할 수 없습니다.`);
                        }
                        gripObjectRefsInUse.add(step.gripObjectRef);
                    } else {
                        if (!gripObjectRefsInUse.has(step.gripObjectRef) && !findGripObjectForReference(step.gripObjectRef)) {
                            throw new Error(`${step.name}: 물건 잡기 대상을 찾을 수 없습니다.`);
                        }
                        gripObjectRefsInUse.delete(step.gripObjectRef);
                    }
                });
                return;
            }
            if (step.motion === 'DELAY') {
                if (!Number.isFinite(step.delaySeconds)
                    || step.delaySeconds < MIN_DELAY_SECONDS
                    || step.delaySeconds > MAX_DELAY_SECONDS) {
                    throw new Error(`${step.name}: delay must be ${MIN_DELAY_SECONDS} to ${MAX_DELAY_SECONDS} seconds.`);
                }
                return;
            }
            if (step.motion === 'VIEW') {
                if (!getViewPreset(step.viewSlot)) {
                    throw new Error(`${step.name}: 저장된 뷰가 없습니다.`);
                }
                return;
            }
            if (isHomeMotion(step.motion)) {
                const workOrigin = validateWorkOriginMotion(robot, step);
                const targetAngles = workOrigin.joints;
                const startAngles = robot.userData.joints.map((joint) => joint.angle);
                if (collisionStopsMotion()) {
                    const evaluator = createAutoPathCollisionEvaluator(robot, startAngles);
                    const edgeIsSafe = autoPathJointEdgeChecker(evaluator, autoPathJointBounds(robot));
                    if (!edgeIsSafe(startAngles, targetAngles)) {
                        throw new Error(`${step.name}: collision detected along the path.`);
                    }
                }
                targetAngles.forEach((angle, index) => setJointAngle(robot.userData.joints[index], angle, false));
                robot.updateMatrixWorld(true);
                return;
            }
            const motionCommand = resolveMotionSegmentCommand(steps, cursor, direction);
            if (motionCommand?.motion === 'MOVJ') {
                validateMovjTarget(robot, step);
                const startAngles = robot.userData.joints.map((joint) => joint.angle);
                if (collisionStopsMotion()) {
                    const evaluator = createAutoPathCollisionEvaluator(robot, startAngles);
                    const edgeIsSafe = autoPathJointEdgeChecker(evaluator, autoPathJointBounds(robot));
                    if (!edgeIsSafe(startAngles, step.joints)) {
                        throw new Error(`${step.name}: collision detected along the path.`);
                    }
                }
                step.joints.forEach((angle, index) => setJointAngle(robot.userData.joints[index], angle, false));
                robot.updateMatrixWorld(true);
            } else if (motionCommand?.motion === 'MOVL') {
                const maximumSpeed = robot.userData.manifest.cartesianMotion.maxSpeed;
                if (!Number.isFinite(motionCommand.speed)
                    || motionCommand.speed < 1
                    || motionCommand.speed > maximumSpeed) {
                    throw new Error(`${step.name}: MOVL speed must be 1 to ${maximumSpeed} mm/s.`);
                }
                validateMovjTarget(robot, step);
                const startAngles = robot.userData.joints.map((joint) => joint.angle);
                const evaluator = collisionStopsMotion()
                    ? createAutoPathCollisionEvaluator(robot, startAngles)
                    : null;
                solveMovlSamples(robot, motionStepTargetPose(step), step.name, {
                    isStateSafe: evaluator?.isSafe || null
                });
                step.joints.forEach((angle, index) => setJointAngle(robot.userData.joints[index], angle, false));
                robot.updateMatrixWorld(true);
                const settled = getCurrentTcpPoseBase(robot);
                const target = motionStepTargetPose(step);
                if (settled.position.distanceTo(target.position) > 0.8
                    || THREE.MathUtils.radToDeg(settled.quaternion.angleTo(target.quaternion)) > 0.35) {
                    throw new Error(`${step.name}: stored TCP and joint targets are inconsistent.`);
                }
            } else {
                throw new Error(`${step.name}: unsupported program command.`);
            }
        });
    } finally {
        if (originalAngles) restoreRobotJointAngles(robot, originalAngles);
        if (originalBaseTransform) {
            applyClipboardTransform(robot, originalBaseTransform);
            robot.userData.externalAxes = originalExternalAxes;
            robot.updateMatrixWorld(true);
            markSceneCollisionDirty(robot);
        }
    }
}

function refreshMotionSessionSteps(session) {
    if (!session?.liveEdit) return true;
    const liveSteps = ensureMotionProgram(session?.robot)?.steps;
    if (!Array.isArray(liveSteps) || liveSteps.length === 0) {
        session.steps = [];
        return false;
    }

    const previousCursor = session.cursor;
    const playbackDirection = session.direction < 0 ? -1 : 1;
    const currentStepId = session.currentStepId || session.steps?.[session.cursor]?.id;
    const currentIndex = liveSteps.findIndex((step) => step.id === currentStepId);
    session.steps = cloneMotionProgram({ steps: liveSteps }).steps;
    if (currentIndex >= 0) {
        session.cursor = currentIndex;
        return true;
    }

    // If the just-completed row was deleted while running, keep the cursor on
    // the row that shifted into its place instead of skipping another row.
    session.cursor = playbackDirection > 0
        ? previousCursor - 1
        : previousCursor + 1;
    return true;
}

function createMotionSession(robot, steps, startAt, options = {}) {
    const controlScope = options.controlScope === 'robot' ? 'robot' : 'group';
    const reverseRepeat = options.reverseRepeat
        ?? (controlScope === 'robot' ? state.motionReverseRepeatRobot : state.motionReverseRepeat);
    const programSteps = ensureMotionProgram(robot)?.steps || [];
    const liveEdit = options.liveEdit
        ?? (!options.stepIntoStepId
            && steps.every((step) => programSteps.some((candidate) => candidate.id === step.id)));
    return {
        robot,
        // Keep a stable playback snapshot so live program-panel edits affect
        // the next run without changing the path that is already executing.
        steps: cloneMotionProgram({ steps }).steps,
        cursor: 0,
        direction: 1,
        currentStepId: null,
        segment: null,
        startAt,
        nextSegmentStartAt: startAt,
        reachedStepIds: new Set(),
        repeat: reverseRepeat
            ? false
            : (options.repeat ?? (controlScope === 'robot' ? state.motionRepeatRobot : state.motionRepeat)),
        reverseRepeat: Boolean(reverseRepeat),
        liveEdit: Boolean(liveEdit),
        interferenceCheck: null,
        controlScope,
        stepIntoStepId: typeof options.stepIntoStepId === 'string' ? options.stepIntoStepId : null,
        status: 'running',
        pauseStarted: 0
    };
}

function startRobotMotionPlans(plans) {
    if (plans.length === 0
        || isOlpRunning()
        || state.olp.workOriginBusy
        || state.olp.manualMoveBusy
        || isVirtualControllerActive()) return;
    const playablePlans = plans.filter(({ robot, steps }) => (
        robot && Array.isArray(steps) && steps.length > 0 && !getMotionSession(robot)
    ));
    if (playablePlans.length === 0) return;
    const hadActiveMotion = state.motionSessions.size > 0;
    try {
        validateMotionWaitTargets(playablePlans);
        playablePlans.forEach(({ robot, steps, reverseRepeat }) => preflightRobotMotion(robot, steps, { reverseRepeat }));
    } catch (error) {
        setMotionProgramStatus('모션 경로 검증에 실패했습니다.', 'error');
        return;
    }
    // A collision is a breakpoint, not an interlock.  Restarting is allowed
    // from the currently colliding pose; only a newly encountered mesh pair
    // stops motion again.  Every pair already present is tracked separately
    // so a multi-link/Tool collision can resume as one visible breakpoint.
    const currentCollisionResults = checkSceneCollisions({ force: true });
    const restartCollisionKeys = asCollisionResults(
        currentCollisionResults?.length ? currentCollisionResults : state.collision.stopNotice?.result
    ).map(collisionResultKey).filter(Boolean);
    clearCollisionStopNotice({ resetViewerStatus: false });
    state.collision.ignoredMotionCollisionKeys = new Set(restartCollisionKeys);
    commitAllPendingHistories();
    if (!hadActiveMotion) state.motionHistoryBefore = captureSceneSnapshot();
    const startAt = performance.now() + 40;
    playablePlans.forEach(({ robot, steps, repeat, reverseRepeat, controlScope, stepIntoStepId }) => {
        const program = ensureMotionProgram(robot);
        program.status = 'running';
        program.progress = 0;
        program.runtimeReachedStepIds = new Set();
        resetTcpPath(robot);
        state.motionSessions.set(robot.userData.motionInstanceId, createMotionSession(robot, steps, startAt, {
            repeat,
            reverseRepeat,
            controlScope,
            stepIntoStepId
        }));
        appendTcpPathPoint(robot);
    });
    setMotionProgramStatus('{count}대의 로봇 모션을 시작했습니다.', 'working', { count: playablePlans.length });
    updateMotionUiLock();
    renderMotionProgramPanel();
    requestRender();
}

function createStepIntoPlan(robot) {
    if (!robot) return null;
    const program = ensureMotionProgram(robot);
    if (!program?.steps.length) return null;
    const selectedIndex = program.steps.findIndex((step) => step.id === program.selectedStepId);
    const step = program.steps[selectedIndex >= 0 ? selectedIndex : 0];
    return {
        robot,
        steps: [step],
        repeat: false,
        reverseRepeat: false,
        stepIntoStepId: step.id
    };
}

function stepIntoActiveRobot() {
    const plan = createStepIntoPlan(state.activeProgramRobot);
    if (plan) startRobotMotionPlans([{ ...plan, controlScope: 'robot' }]);
}

function stepIntoCheckedRobots() {
    const plans = getArticulatedRobots()
        .filter((robot) => ensureMotionProgram(robot).included)
        .map(createStepIntoPlan)
        .filter(Boolean)
        .map((plan) => ({ ...plan, controlScope: 'group' }));
    startRobotMotionPlans(plans);
}

function getOlpCheckedRobots() {
    return getArticulatedRobots()
        .filter((robot) => ensureMotionProgram(robot)?.included);
}

function startOlpCheckedSessions({ step = false } = {}) {
    const robots = getOlpCheckedRobots();
    if (!robots.length) {
        setOlpStatus('error', 'Select at least one robot for the OLP group.');
        return;
    }
    const missingProjectRobots = robots.filter((robot) => !getOlpProjectForRobot(robot));
    if (missingProjectRobots.length) {
        setOlpStatus('error', 'Load an OLP project for every selected robot before group execution.');
        return;
    }
    if (state.motionSessions.size) {
        setOlpStatus('error', 'Stop the normal motion program before running OLP.');
        return;
    }
    robots.forEach((robot) => { void startOlpSession({ step, robot }); });
}

function stepCheckedRobotPrograms() {
    if (state.olp.enabled) {
        startOlpCheckedSessions({ step: true });
        return;
    }
    stepIntoCheckedRobots();
}

function runCheckedRobotProgramsOrOlp() {
    if (state.olp.enabled) {
        startOlpCheckedSessions();
        return;
    }
    runCheckedRobotPrograms();
}

function pauseOlpCheckedSessions() {
    const runtimes = getOlpCheckedRobots()
        .map((robot) => getOlpRuntimeForRobot(robot))
        .filter((runtime) => isOlpRuntimeRunning(runtime) && !runtime.paused);
    runtimes.forEach((runtime) => runtime.togglePause());
    if (runtimes.length) setOlpStatus('running', 'OLP group paused.');
}

function pauseCheckedRobotMotionsOrOlp() {
    if (state.olp.enabled) {
        pauseOlpCheckedSessions();
        return;
    }
    pauseCheckedRobotMotions();
}

function stopCheckedRobotMotionsOrOlp() {
    if (state.olp.enabled) {
        const robots = getOlpCheckedRobots();
        if (robots.some((robot) => getOlpRuntimeForRobot(robot))) {
            void stopOlpSession('OLP group stopped by user', {
                resetCursor: true,
                robots
            });
        }
        return;
    }
    stopCheckedRobotMotions();
}

function runActiveProgramOrOlp() {
    if (state.olp.enabled) {
        void startOlpSession();
        return;
    }
    runActiveRobotProgram();
}

function stepActiveProgramOrOlp() {
    if (state.olp.enabled) {
        void startOlpSession({ step: true });
        return;
    }
    stepIntoActiveRobot();
}

function pauseActiveProgramOrOlp() {
    if (state.olp.enabled) {
        const runtime = getOlpRuntimeForRobot();
        if (!runtime) return;
        runtime.togglePause();
        // Refresh the bottom-panel control state immediately on pause/resume.
        setOlpStatus('running');
        return;
    }
    pauseActiveRobotMotion();
}

function stopActiveProgramOrOlp() {
    if (state.olp.enabled) {
        void stopOlpSession('OLP stopped by user', { resetCursor: true });
        return;
    }
    stopActiveRobotMotion();
}

async function moveOlpToWorkOrigin() {
    if (state.olp.workOriginBusy || state.olp.manualMoveBusy) return;
    const project = getOlpProject();
    if (!project) {
        setOlpStatus('error', 'Load a robot project folder before moving to Work Origin.');
        return;
    }
    if (isOlpRunning()) {
        setOlpStatus('error', 'Stop OLP before moving to Work Origin.');
        return;
    }
    if (isVirtualControllerActive()) {
        setOlpStatus('error', 'Work Origin is unavailable while a controller is connected.');
        return;
    }

    state.olp.workOriginBusy = true;
    updateOlpProgramPanelUi();
    updateMotionUiLock();
    try {
        setOlpExecutionForRobot(getOlpRobot(), {
            phase: 'stopped',
            running: false,
            paused: false,
            filePath: project.programPath,
            lineNumber: 1,
            lineText: 'Work Origin 0',
            command: 'HOME[0]',
            waitCondition: '',
            callStack: [],
            alarm: null
        });
        setOlpStatus('connected', 'Moving to Work Origin 0.');
        await runOlpHome(0, 100, project, null);
        setOlpStatus('connected', 'Work Origin 0 reached.');
    } catch (error) {
        setOlpExecutionForRobot(getOlpRobot(), { phase: 'error', running: false, alarm: null });
        setOlpStatus('error', 'Work Origin move failed: {error}', { error: error?.message || error });
    } finally {
        state.olp.workOriginBusy = false;
        updateOlpProgramPanelUi();
        updateMotionUiLock();
        requestRender();
    }
}

function runActiveRobotProgram() {
    const robot = state.activeProgramRobot;
    if (robot && resumePausedRobotMotions([robot])) return;
    const program = ensureMotionProgram(robot);
    if (robot && program?.steps.length) startRobotMotionPlans([{
        robot,
        steps: program.steps,
        repeat: state.motionRepeatRobot,
        reverseRepeat: state.motionReverseRepeatRobot,
        controlScope: 'robot'
    }]);
}

function runCheckedRobotPrograms() {
    const robots = getArticulatedRobots()
        .filter((robot) => ensureMotionProgram(robot).included);
    if (resumePausedRobotMotions(robots)) return;
    const plans = robots
        .map((robot) => ({ robot, program: ensureMotionProgram(robot) }))
        .filter(({ program }) => program.steps.length)
        .map(({ robot, program }) => ({
            robot,
            steps: program.steps,
            repeat: state.motionRepeat,
            reverseRepeat: state.motionReverseRepeat,
            controlScope: 'group'
        }));
    startRobotMotionPlans(plans);
}

function setMotionSessionPaused(session, paused, now = performance.now()) {
    if (!session || (paused && session.status !== 'running') || (!paused && session.status !== 'paused')) return;
    if (paused) {
        session.status = 'paused';
        session.pauseStarted = now;
    } else {
        const delay = Math.max(0, now - session.pauseStarted);
        session.startAt += delay;
        session.nextSegmentStartAt += delay;
        if (session.segment) session.segment.startTime += delay;
        const program = ensureMotionProgram(session.robot);
        if (Number.isFinite(program.cycleTimerStartedAt)) program.cycleTimerStartedAt += delay;
        session.status = 'running';
        session.pauseStarted = 0;
    }
    ensureMotionProgram(session.robot).status = session.status;
}

function pauseRobotMotions(robots) {
    const sessions = robots.map(getMotionSession).filter((session) => session?.status === 'running');
    if (!sessions.length) return false;
    const now = performance.now();
    sessions.forEach((session) => setMotionSessionPaused(session, true, now));
    setMotionProgramStatus('모션이 일시정지되었습니다.', 'working');
    renderMotionProgramPanel();
    return true;
}

function resumePausedRobotMotions(robots) {
    const sessions = robots.map(getMotionSession).filter((session) => session?.status === 'paused');
    if (!sessions.length) return false;
    const now = performance.now();
    sessions.forEach((session) => setMotionSessionPaused(session, false, now));
    setMotionProgramStatus('모션을 재개했습니다.', 'working');
    renderMotionProgramPanel();
    requestRender();
    return true;
}

function pauseActiveRobotMotion() {
    if (state.activeProgramRobot) pauseRobotMotions([state.activeProgramRobot]);
}

function pauseCheckedRobotMotions() {
    pauseRobotMotions(getArticulatedRobots().filter((robot) => ensureMotionProgram(robot).included));
}

function finalizeMotionHistoryIfIdle() {
    if (isMotionActive()) return;
    const before = state.motionHistoryBefore;
    state.motionHistoryBefore = null;
    if (before) recordHistory('멀티 로봇 모션', before, captureSceneSnapshot());
    updateMotionUiLock();
    renderMotionProgramPanel();
    scheduleMotionProjectSave();
}

function finishRobotMotionSession(session, status, message = '', replacements = {}) {
    const robot = session.robot;
    state.motionSessions.delete(robot.userData.motionInstanceId);
    const program = ensureMotionProgram(robot);
    program.runtimeReachedStepIds = new Set(session.reachedStepIds || []);
    program.status = status;
    if (status === 'error' || (status === 'completed' && !session.stepIntoStepId)) {
        program.cycleTimerStartedAt = null;
    }
    if (status === 'completed' && session.stepIntoStepId && program.steps.length) {
        const completedIndex = program.steps.findIndex((step) => step.id === session.stepIntoStepId);
        const nextIndex = completedIndex >= 0 ? (completedIndex + 1) % program.steps.length : 0;
        program.selectedStepId = program.steps[nextIndex].id;
        program.progress = nextIndex / program.steps.length;
    } else if (status === 'completed') {
        program.progress = 1;
    }
    syncJointControls(robot);
    if (robot === state.activeArticulatedModel) captureCurrentTcpTarget(robot);
    if (message) setMotionProgramStatus(message, status === 'error' ? 'error' : '', replacements);
    renderMotionProgramPanel();
    finalizeMotionHistoryIfIdle();
}

function stopRobotMotions(robots) {
    let stopped = 0;
    robots.forEach((robot) => {
        sendCollaborationRobotCommand(robot, 'stop');
        resetTcpPath(robot);
        const session = getMotionSession(robot);
        if (!session) return;
        state.motionSessions.delete(robot.userData.motionInstanceId);
        const program = ensureMotionProgram(robot);
        program.runtimeReachedStepIds = new Set(session.reachedStepIds || []);
        program.status = 'stopped';
        program.cycleTimerStartedAt = null;
        stopped += 1;
    });
    if (stopped) setMotionProgramStatus('{count}대의 로봇 모션을 정지했습니다.', '', { count: stopped });
    finalizeMotionHistoryIfIdle();
    renderMotionProgramPanel();
    requestRender();
}

function stopActiveRobotMotion() {
    if (state.activeProgramRobot) stopRobotMotions([state.activeProgramRobot]);
}

function stopCheckedRobotMotions() {
    stopRobotMotions(getArticulatedRobots().filter((robot) => ensureMotionProgram(robot).included));
}

function motionSessionProgress(session, segmentProgress = 1) {
    const stepCount = Math.max(1, session.steps.length);
    const progress = THREE.MathUtils.clamp(Number(segmentProgress) || 0, 0, 1);
    return session.direction < 0
        ? THREE.MathUtils.clamp((session.cursor + 1 - progress) / stepCount, 0, 1)
        : THREE.MathUtils.clamp((session.cursor + progress) / stepCount, 0, 1);
}

function getInterferenceCollisionRobot(root) {
    if (!root) return null;
    if (root.userData?.tcpFrame) return root;
    return root.userData?.attachmentHost?.userData?.tcpFrame
        ? root.userData.attachmentHost
        : null;
}

function isRobotInterferenceHitForRobotPair(hit, robot, otherRobots) {
    const leftRobot = getInterferenceCollisionRobot(hit?.objectA);
    const rightRobot = getInterferenceCollisionRobot(hit?.objectB);
    return (leftRobot === robot && otherRobots.has(rightRobot))
        || (rightRobot === robot && otherRobots.has(leftRobot));
}

function robotInterferencePathHits(robot, angles, collisionModels, otherRobots, changedRoots = null) {
    const system = state.collision.system;
    if (!system) return false;
    applyPlanningJointAngles(robot, angles);
    robot.updateMatrixWorld(true);
    const movingRoots = changedRoots || new Set(collisionModels.filter((model) => (
        model === robot || model.userData?.attachmentHost === robot
    )));
    const hits = system.checkAll(collisionModels, {
        changedRoots: movingRoots,
        allowWarmHitReuse: false
    });
    return asCollisionResults(hits).some((hit) => (
        isRobotInterferenceHitForRobotPair(hit, robot, otherRobots)
    ));
}

function getRobotInterferenceMotionTargetAngles(session) {
    const step = session?.steps?.[session.cursor];
    if (!step) return null;
    if (isHomeMotion(step.motion)) return validateWorkOriginMotion(session.robot, step).joints;
    const motionCommand = resolveMotionSegmentCommand(session.steps, session.cursor, session.direction);
    return ['MOVJ', 'MOVL'].includes(motionCommand?.motion) && Array.isArray(step.joints)
        ? step.joints
        : null;
}

function robotInterferenceTargetsConflict(leftRobot, leftAngles, rightRobot, rightAngles, collisionModels = null) {
    const system = state.collision.system;
    if (!system || !leftRobot || !rightRobot || !Array.isArray(leftAngles) || !Array.isArray(rightAngles)) return false;
    const models = (collisionModels || getCollisionModels()).filter((model) => {
        const owner = getInterferenceCollisionRobot(model);
        return owner === leftRobot || owner === rightRobot;
    });
    if (!models.length) return false;
    const originalLeftAngles = leftRobot.userData.joints.map((joint) => joint.angle);
    const originalRightAngles = rightRobot.userData.joints.map((joint) => joint.angle);
    try {
        applyPlanningJointAngles(leftRobot, leftAngles);
        applyPlanningJointAngles(rightRobot, rightAngles);
        leftRobot.updateMatrixWorld(true);
        rightRobot.updateMatrixWorld(true);
        const changedRoots = new Set(models.filter((model) => (
            model === leftRobot
            || model === rightRobot
            || model.userData?.attachmentHost === leftRobot
            || model.userData?.attachmentHost === rightRobot
        )));
        const hits = system.checkAll(models, {
            changedRoots,
            allowWarmHitReuse: false
        });
        return asCollisionResults(hits).some((hit) => (
            isRobotInterferenceHitForRobotPair(hit, leftRobot, new Set([rightRobot]))
        ));
    } finally {
        restoreRobotJointAngles(leftRobot, originalLeftAngles);
        restoreRobotJointAngles(rightRobot, originalRightAngles);
        leftRobot.updateMatrixWorld(true);
        rightRobot.updateMatrixWorld(true);
    }
}

function clearRobotInterferenceCheck(session) {
    const check = session?.interferenceCheck;
    if (check?.robot && Array.isArray(check.originalAngles)) {
        restoreRobotJointAngles(check.robot, check.originalAngles);
        check.robot.updateMatrixWorld(true);
    }
    if (session) session.interferenceCheck = null;
}

function getRobotInterferenceStepSignature(robot, step) {
    const workOrigin = isHomeMotion(step?.motion) ? getRobotWorkOrigin(robot) : null;
    return JSON.stringify([
        step?.id || '',
        step?.motion || '',
        step?.joints || [],
        step?.position || [],
        workOrigin?.joints || []
    ]);
}

function createRobotInterferenceCheck(session, timestamp) {
    const config = state.robotInterferenceAvoidance;
    if (!config.enabled) return { status: 'clear' };
    const { robot } = session;
    const priorityRobot = getRobotInterferencePriorityRobot();
    const step = session.steps[session.cursor];
    if (!step || (isHomeMotion(step.motion) === false && !isMotionPointMotion(step.motion))) {
        return { status: 'clear' };
    }
    const motionCommand = isHomeMotion(step.motion)
        ? { motion: 'MOVJ', speed: 100 }
        : resolveMotionSegmentCommand(session.steps, session.cursor, session.direction);
    if (!['MOVJ', 'MOVL'].includes(motionCommand?.motion)) return { status: 'clear' };
    const otherRobots = new Set(getArticulatedRobots().filter((candidate) => candidate !== robot));
    if (!otherRobots.size) return { status: 'clear' };
    const collisionModels = getCollisionModels().filter((model) => {
        const owner = getInterferenceCollisionRobot(model);
        return owner === robot || otherRobots.has(owner);
    });
    if (!collisionModels.length) return { status: 'clear' };
    const originalAngles = robot.userData.joints.map((joint) => joint.angle);
    const stepSignature = getRobotInterferenceStepSignature(robot, step);
    const changedRoots = new Set(collisionModels.filter((model) => (
        model === robot || model.userData?.attachmentHost === robot
    )));

    if (priorityRobot && robot !== priorityRobot) {
        const prioritySession = getMotionSession(priorityRobot);
        const targetAngles = getRobotInterferenceMotionTargetAngles(session);
        const priorityTargetAngles = getRobotInterferenceMotionTargetAngles(prioritySession);
        if (prioritySession?.status === 'running'
            && targetAngles
            && priorityTargetAngles
            && robotInterferenceTargetsConflict(
                robot,
                targetAngles,
                priorityRobot,
                priorityTargetAngles,
                collisionModels
            )) {
            return {
                status: 'blocked',
                stepId: step.id,
                stepSignature,
                direction: session.direction,
                retryAt: timestamp + ROBOT_INTERFERENCE_RECHECK_INTERVAL_MS
            };
        }
    }

    if (motionCommand.motion === 'MOVJ') {
        const workOrigin = isHomeMotion(step.motion) ? validateWorkOriginMotion(robot, step) : null;
        const targetAngles = isHomeMotion(step.motion) ? workOrigin.joints : step.joints;
        const bounds = autoPathJointBounds(robot);
        const segments = Math.max(1, Math.min(24, Math.ceil(targetAngles.reduce((max, target, index) => (
            Math.max(max, Math.abs(target - originalAngles[index]) / Math.max(1, bounds[index]?.sampleStep || 8))
        ), 0))));
        return {
            status: 'checking',
            stepId: step.id,
            stepSignature,
            direction: session.direction,
            robot,
            originalAngles,
            collisionModels,
            otherRobots,
            changedRoots,
            motion: 'MOVJ',
            targetAngles: [...targetAngles],
            sampleIndex: 0,
            sampleCount: segments,
            retryAt: 0
        };
    }

    const startPose = getCurrentTcpPoseBase(robot);
    const targetPose = motionStepTargetPose(step);
    const samples = Math.max(2, Math.min(24, Math.ceil(Math.max(
        startPose.position.distanceTo(targetPose.position) / MOTION_MOVL_SAMPLE_DISTANCE,
        THREE.MathUtils.radToDeg(startPose.quaternion.angleTo(targetPose.quaternion)) / MOTION_MOVL_SAMPLE_ANGLE
    ))));
    return {
        status: 'checking',
        stepId: step.id,
        stepSignature,
        direction: session.direction,
        robot,
        originalAngles,
        collisionModels,
        otherRobots,
        changedRoots,
        motion: 'MOVL',
        targetAngles: [...step.joints],
        startPose,
        targetPose,
        seed: originalAngles.slice(),
        sampleIndex: 0,
        sampleCount: samples,
        retryAt: 0
    };
}

function isRobotInterferencePathClear(session, timestamp = performance.now()) {
    const config = state.robotInterferenceAvoidance;
    if (!config.enabled) {
        clearRobotInterferenceCheck(session);
        return true;
    }
    const step = session.steps[session.cursor];
    const stepSignature = getRobotInterferenceStepSignature(session.robot, step);
    let check = session.interferenceCheck;
    if (check && (
        check.stepId !== step?.id
        || check.stepSignature !== stepSignature
        || check.direction !== session.direction
    )) {
        clearRobotInterferenceCheck(session);
        check = null;
    }
    if (check?.status === 'blocked') {
        if (timestamp < check.retryAt) return false;
        clearRobotInterferenceCheck(session);
        check = null;
    }
    if (!check) {
        check = createRobotInterferenceCheck(session, timestamp);
        if (check.status === 'clear') return true;
        session.interferenceCheck = check;
        if (check.status === 'blocked') return false;
    }

    let completed = false;
    try {
        for (let count = 0; count < ROBOT_INTERFERENCE_SAMPLES_PER_FRAME; count += 1) {
            const index = check.sampleIndex;
            const alpha = index / check.sampleCount;
            let sample = check.originalAngles.map((angle, jointIndex) => (
                angle + (check.targetAngles[jointIndex] - angle) * alpha
            ));
            if (check.motion === 'MOVL' && index > 0 && index < check.sampleCount) {
                applyPlanningJointAngles(check.robot, check.seed);
                const pose = {
                    position: new THREE.Vector3().lerpVectors(check.startPose.position, check.targetPose.position, alpha),
                    quaternion: check.startPose.quaternion.clone().slerp(check.targetPose.quaternion, alpha)
                };
                const solved = solveRobotIK(check.robot, pose, {
                    positionTolerance: 0.8,
                    rotationTolerance: THREE.MathUtils.degToRad(0.6)
                });
                if (solved.success) sample = check.robot.userData.joints.map((joint) => joint.angle);
            }
            check.seed = sample.slice();
            if (robotInterferencePathHits(
                check.robot,
                sample,
                check.collisionModels,
                check.otherRobots,
                check.changedRoots
            )) {
                check.status = 'blocked';
                check.retryAt = timestamp + ROBOT_INTERFERENCE_RECHECK_INTERVAL_MS;
                return false;
            }
            check.sampleIndex += 1;
            completed = check.sampleIndex > check.sampleCount;
            if (completed) break;
        }
    } finally {
        restoreRobotJointAngles(check.robot, check.originalAngles);
        check.robot.updateMatrixWorld(true);
    }
    if (completed) {
        clearRobotInterferenceCheck(session);
        return true;
    }
    return null;
}

function setRobotInterferenceWaiting(session, waiting) {
    const next = Boolean(waiting);
    if (session.waitingForInterference === next) return false;
    session.waitingForInterference = next;
    if (next) setMotionProgramStatus('로봇 간섭 회피 대기 중', 'working');
    return true;
}

function createMotionSegment(session, timestamp) {
    const { robot } = session;
    const step = session.steps[session.cursor];
    if (!step) return null;
    session.currentStepId = step.id;
    session.reachedStepIds.add(step.id);
    markMotionStepExecutionEdge(robot, step);
    if (step.motion === 'WAIT') {
        const targetRobot = findProgramRobot(step.waitRobotInstanceId);
        const targetProgram = ensureMotionProgram(targetRobot);
        const targetSession = getMotionSession(targetRobot);
        const targetSteps = targetSession?.steps || targetProgram?.steps || [];
        const targetStep = targetSteps[Number(step.waitLineNumber) - MIN_WAIT_LINE_NUMBER];
        return {
            type: 'WAIT',
            step,
            startTime: timestamp,
            duration: 0,
            waitEdgeSequence: getMotionStepEdgeSequence(targetProgram, targetStep?.id)
        };
    }
    if (step.motion === 'TIME_START' || step.motion === 'TIME_OUT') {
        const timerActions = getDirectionalTimerActions(step.motion, {
            cursor: session.cursor,
            direction: session.direction,
            stepCount: session.steps.length,
            repeat: session.repeat,
            reverseRepeat: session.reverseRepeat
        });
        return {
            type: timerActions[0],
            timerActions,
            step,
            startTime: timestamp
        };
    }
    if (step.motion === 'DELAY') {
        return {
            type: 'DELAY',
            step,
            startTime: timestamp,
            duration: calculateDelayDuration(step.delaySeconds) * 1000
        };
    }
    if (step.motion === 'VIEW') {
        return {
            type: 'VIEW',
            step,
            startTime: timestamp,
            duration: 0
        };
    }
    if (isGripObjectMotion(step.motion)) {
        const gripActions = getDirectionalGripActions(step.motion, {
            cursor: session.cursor,
            direction: session.direction,
            stepCount: session.steps.length,
            repeat: session.repeat,
            reverseRepeat: session.reverseRepeat
        });
        return {
            type: gripActions[0],
            gripActions,
            step,
            startTime: timestamp,
            duration: 0
        };
    }
    const isHome = isHomeMotion(step.motion);
    const motionCommand = isHome
        ? { motion: 'MOVJ', speed: 100 }
        : resolveMotionSegmentCommand(session.steps, session.cursor, session.direction);
    const motion = motionCommand?.motion;
    if (motion === 'MOVJ') {
        const workOrigin = isHome ? validateWorkOriginMotion(robot, step) : null;
        if (!isHome) validateMovjTarget(robot, step);
        const startAngles = robot.userData.joints.map((joint) => joint.angle);
        const startPose = getCurrentTcpPoseBase(robot);
        const targetAngles = isHome ? workOrigin.joints : step.joints;
        const targetPose = isHome ? workOriginTargetPose(workOrigin) : motionStepTargetPose(step);
        const robotMotionDuration = calculateMovjDuration(
            startAngles,
            targetAngles,
            robot.userData.joints,
            motionCommand.speed
        ) * 1000;
        const robotPoseChanged = hasRobotPoseChanged(startPose, targetPose, startAngles, targetAngles);
        const externalMotion = getExternalAxisSegmentState(
            robot,
            step,
            robotMotionDuration,
            robotPoseChanged
        );
        const motionDuration = robotPoseChanged
            ? robotMotionDuration
            : externalMotion.externalMotionDuration;
        const rapidMove = createRapidMoveState(
            startAngles,
            targetAngles,
            robot.userData.joints,
            motionCommand.speed,
            {
                ...(robot.userData.manifest?.rapidMove || {}),
                structure: robot.userData.manifest?.structure,
                robotType: robot.userData.manifest?.robotType
            }
        );
        return {
            type: isHome ? 'HOME' : motion,
            step,
            startAngles,
            targetAngles: [...targetAngles],
            targetPose,
            startTime: timestamp,
            motionDuration,
            rapidMove,
            ...externalMotion,
            duration: motionDuration + MOTION_SETTLING_DELAY_SECONDS * 1000
        };
    }
    const startPose = getCurrentTcpPoseBase(robot);
    const targetPose = motionStepTargetPose(step);
    const robotMotionDuration = calculateMovlDuration(
        startPose.position.distanceTo(targetPose.position),
        THREE.MathUtils.radToDeg(startPose.quaternion.angleTo(targetPose.quaternion)),
        motionCommand.speed,
        robot.userData.manifest.cartesianMotion
    ) * 1000;
    const startAngles = robot.userData.joints.map((joint) => joint.angle);
    const robotPoseChanged = hasRobotPoseChanged(startPose, targetPose, startAngles, step.joints);
    const externalMotion = getExternalAxisSegmentState(
        robot,
        step,
        robotMotionDuration,
        robotPoseChanged
    );
    const motionDuration = robotPoseChanged
        ? robotMotionDuration
        : externalMotion.externalMotionDuration;
    return {
        type: motion,
        step,
        startPose,
        targetPose,
        startTime: timestamp,
        motionDuration,
        ...externalMotion,
        duration: motionDuration + MOTION_SETTLING_DELAY_SECONDS * 1000
    };
}

function advanceMotionSegment(session, timestamp) {
    const { robot, segment } = session;
    if (segment.type === 'WAIT') {
        const waitState = getMotionWaitState(session, segment);
        if (waitState.error) throw new Error(waitState.error);
        const program = ensureMotionProgram(robot);
        program.progress = motionSessionProgress(session, 0);
        return waitState.ready;
    }
    if (segment.type === 'TIME_START' || segment.type === 'TIME_OUT') {
        const program = ensureMotionProgram(robot);
        const markerTime = segment.startTime;
        (segment.timerActions || [segment.type]).forEach((timerAction) => {
            if (timerAction === 'TIME_START') {
                program.cycleTimerStartedAt = markerTime;
                program.lastCycleTimeSeconds = null;
                return;
            }
            if (!Number.isFinite(program.cycleTimerStartedAt)) {
                throw new Error(`${segment.step.name}: TIME START must run before TIME OUT.`);
            }
            program.lastCycleTimeSeconds = calculateCycleElapsedSeconds(program.cycleTimerStartedAt, markerTime);
            program.cycleTimerStartedAt = null;
            setMotionProgramStatus(
                '{name} 사이클 타임: {seconds} s',
                '',
                {
                    name: robot.userData.motionDisplayName,
                    seconds: program.lastCycleTimeSeconds.toFixed(3)
                }
            );
        });
        program.progress = motionSessionProgress(session, 1);
        return true;
    }
    if (segment.type === 'VIEW') {
        // A running program may execute VIEW while the user is moving a model
        // with a 3D handle. Defer the camera change until the handle is
        // released so the two interactions never compete in the same frame.
        if (isAny3DTransformHandleDragging()) return false;
        applyViewPreset(segment.step.viewSlot, { announce: false });
        const program = ensureMotionProgram(robot);
        program.progress = motionSessionProgress(session, 1);
        return true;
    }
    if (isGripObjectMotion(segment.type)) {
        // Repeat controls can be changed while a session is running. Resolve
        // the boundary actions at execution time so a toggle made while the
        // endpoint command is pending cannot leave the object state inverted.
        getDirectionalGripActions(segment.step.motion, {
            cursor: session.cursor,
            direction: session.direction,
            stepCount: session.steps.length,
            repeat: session.repeat,
            reverseRepeat: session.reverseRepeat
        }).forEach((gripMotion) => {
            if (!applyProgramGripObjectAction(robot, segment.step, gripMotion)) {
                throw new Error(`${segment.step.name}: 물건 잡기/놓기 명령을 실행할 수 없습니다.`);
            }
        });
        const program = ensureMotionProgram(robot);
        program.progress = motionSessionProgress(session, 1);
        return true;
    }
    const elapsed = timestamp - segment.startTime;
    const rapidMoveEnabled = (segment.type === 'MOVJ' || segment.type === 'HOME')
        && segment.rapidMove?.enabled === true;
    let linearProgress;
    let progress;
    let rapidMoveSettling = false;
    if (rapidMoveEnabled) {
        const previousTimestamp = Number.isFinite(segment.rapidMove.lastTimestamp)
            ? segment.rapidMove.lastTimestamp
            : timestamp;
        const deltaSeconds = Math.max(0, Math.min(
            RAPID_MOVE_DEFAULTS.maxStepSeconds,
            (timestamp - previousTimestamp) / 1000
        ));
        segment.rapidMove.lastTimestamp = timestamp;
        const rapidMoveResult = advanceRapidMoveState(
            segment.rapidMove,
            deltaSeconds,
            segment.startAngles,
            segment.targetAngles,
            robot.userData.manifest?.structure,
            robot.userData.manifest?.robotType,
            1
        );
        linearProgress = rapidMoveResult.progress;
        progress = rapidMoveResult.progress;
        if (rapidMoveResult.completed && !Number.isFinite(segment.rapidMove.completedAt)) {
            segment.rapidMove.completedAt = timestamp;
            segment.motionDuration = Math.max(0, timestamp - segment.startTime);
            segment.duration = segment.motionDuration + MOTION_SETTLING_DELAY_SECONDS * 1000;
        }
        rapidMoveSettling = rapidMoveResult.completed
            && timestamp < segment.rapidMove.completedAt + MOTION_SETTLING_DELAY_SECONDS * 1000;
    } else {
        const motionDuration = Number.isFinite(segment.motionDuration)
            ? segment.motionDuration
            : segment.duration;
        linearProgress = THREE.MathUtils.clamp(elapsed / motionDuration, 0, 1);
        progress = sCurveProgress(linearProgress);
    }
    advanceRobotTravelAxis(robot, segment, elapsed, progress);
    if (segment.type === 'MOVJ' || segment.type === 'HOME') {
        segment.targetAngles.forEach((target, index) => {
            const value = THREE.MathUtils.lerp(segment.startAngles[index], target, progress);
            setJointAngle(robot.userData.joints[index], value, false);
        });
        robot.updateMatrixWorld(true);
    } else if (segment.type === 'MOVL') {
        const target = {
            position: new THREE.Vector3().fromArray(interpolateLinearPosition(
                segment.startPose.position.toArray(),
                segment.targetPose.position.toArray(),
                progress
            )),
            quaternion: new THREE.Quaternion().fromArray(slerpQuaternion(
                segment.startPose.quaternion.toArray(),
                segment.targetPose.quaternion.toArray(),
                progress
            ))
        };
        const previousAngles = robot.userData.joints.map((joint) => joint.angle);
        const result = solveRobotIK(robot, target);
        if (!result.success) {
            restoreRobotJointAngles(robot, previousAngles);
            throw new Error(`${segment.step.name}: runtime IK failed.`);
        }
        if (linearProgress >= 1) {
            segment.step.joints.forEach((angle, index) => setJointAngle(robot.userData.joints[index], angle, false));
            robot.updateMatrixWorld(true);
        }
    }
    const program = ensureMotionProgram(robot);
    program.progress = motionSessionProgress(session, linearProgress);
    if (robot === state.activeArticulatedModel) syncJointControls(robot);
    updateTcpPresentation(robot);
    if (segment.type === 'HOME' && linearProgress >= 1) syncWorkOriginOutputStates();
    appendTcpPathPoint(robot);
    return rapidMoveEnabled
        ? Boolean(segment.rapidMove.completed && !rapidMoveSettling)
        : elapsed >= segment.duration;
}

function updateMotionSessions(timestamp) {
    if (!isMotionActive()) return;
    [...state.motionSessions.values()].forEach((session) => {
        if (session.status !== 'running' || timestamp < session.startAt) return;
        try {
            let renderNeeded = false;
            for (let transition = 0; transition < MAX_MOTION_TRANSITIONS_PER_FRAME; transition += 1) {
                if (!session.segment) {
                    if (!refreshMotionSessionSteps(session)) {
                        finishRobotMotionSession(session, 'completed');
                        return;
                    }
                    const interferencePathState = isRobotInterferencePathClear(session, timestamp);
                    // A path scan is intentionally incremental. Keep the
                    // session in its current state while the remaining
                    // samples are checked on later animation frames.
                    if (interferencePathState === null) break;
                    if (!interferencePathState) {
                        renderNeeded = setRobotInterferenceWaiting(session, true) || renderNeeded;
                        break;
                    }
                    renderNeeded = setRobotInterferenceWaiting(session, false) || renderNeeded;
                    session.segment = createMotionSegment(session, session.nextSegmentStartAt);
                    renderNeeded = true;
                }
                if (!session.segment) {
                    finishRobotMotionSession(session, 'completed');
                    return;
                }
                const completedSegment = session.segment;
                if (!advanceMotionSegment(session, timestamp)) break;
                session.nextSegmentStartAt = Number.isFinite(completedSegment.duration)
                    ? completedSegment.startTime + completedSegment.duration
                    : completedSegment.startTime;
                if (!refreshMotionSessionSteps(session)) {
                    finishRobotMotionSession(session, 'completed');
                    return;
                }
                const nextPlayback = advanceMotionCursor({
                    cursor: session.cursor,
                    direction: session.direction,
                    stepCount: session.steps.length,
                    repeat: session.repeat,
                    reverseRepeat: session.reverseRepeat
                });
                session.cursor = nextPlayback.cursor;
                session.direction = nextPlayback.direction;
                session.segment = null;
                session.currentStepId = null;
                renderNeeded = true;
                if (nextPlayback.completed) {
                    finishRobotMotionSession(session, 'completed', '{name} 완료.', {
                        name: session.robot.userData.motionDisplayName
                    });
                    return;
                }
                if (nextPlayback.boundary) {
                    session.reachedStepIds.clear();
                    ensureMotionProgram(session.robot).runtimeReachedStepIds = new Set();
                    ensureMotionProgram(session.robot).progress = motionSessionProgress(session, 0);
                    break;
                }
            }
            if (renderNeeded) updateMotionProgramPlaybackUi();
        } catch (error) {
            finishRobotMotionSession(
                session,
                'error',
                '{name}: {message}',
                {
                    name: session.robot.userData.motionDisplayName,
                    message: uiText('모션 실행에 실패했습니다.')
                }
            );
        }
    });
}

function applyFBXMaterial(fbx) {
    fbx.traverse(c => {
        if (!c.isMesh) return;
        c.castShadow = c.receiveShadow = true;
        const mats = Array.isArray(c.material) ? c.material : [c.material];
        mats.forEach(m => {
            if (!m) return;
            m.vertexColors = false; // Fix generic FBX dark colors
            if (m.color && m.color.r === 0 && m.color.g === 0 && m.color.b === 0) {
                m.color.set(0xcccccc);
            }
            m.needsUpdate = true;
        });
    });
}

function isOutlineMesh(mesh) {
    return Boolean(mesh?.isMesh
        && mesh.geometry?.getAttribute?.('position')
        && mesh.geometry.getAttribute('position').count > 0
        && !mesh.userData?.outlineSource
        && !mesh.userData?.excludeFromOutline);
}

function disposeModelOutlineLine(line) {
    if (!line) return;
    if (line.parent?.userData?.outlineLine === line) {
        delete line.parent.userData.outlineLine;
    }
    line.removeFromParent();
    line.geometry?.dispose();
    const materials = Array.isArray(line.material) ? line.material : [line.material];
    materials.forEach((material) => material?.dispose());
}

function disposeModelOutlines(model) {
    const outlineLines = [];
    model?.traverse?.((object) => {
        if (object.userData?.outlineSource) outlineLines.push(object);
    });
    outlineLines.forEach(disposeModelOutlineLine);
}

function removeModelOutlines() {
    state.models.forEach(disposeModelOutlines);
}

function getModelTransparencyForObject(object, model) {
    let current = object;
    while (current && current !== model) {
        if (Number.isFinite(current.userData?.modelTransparency)) {
            return normalizeModelTransparencyPercent(current.userData.modelTransparency);
        }
        current = current.parent;
    }
    return getModelTransparencyPercent(model);
}

function isModelOutlineSelectionTarget(mesh, model) {
    if (!mesh || !model || state.selectedModel !== model) return false;
    const selectedPart = state.selectedModelPart;
    if (!selectedPart || selectedPart === model) return true;
    for (let current = mesh; current && current !== model; current = current.parent) {
        if (current === selectedPart) return true;
    }
    return false;
}

function updateModelSelectionOutlines({ ensureSelection = true } = {}) {
    // Selection feedback remains visible even when the global outline mode is
    // disabled. syncModelOutlines() creates only the selected outline in that
    // mode, then calls this function with ensureSelection=false to avoid a
    // recursive sync.
    if (!state.outlineMode && ensureSelection) {
        syncModelOutlines();
        return;
    }
    state.models.forEach((model) => {
        model.traverse((mesh) => {
            const line = mesh.userData?.outlineLine;
            if (!line) return;
            const nextColor = isModelOutlineSelectionTarget(mesh, model)
                ? MODEL_SELECTION_OUTLINE_COLOR
                : MODEL_DEFAULT_OUTLINE_COLOR;
            const material = line.material;
            if (!material?.color || material.color.getHex() === nextColor) return;
            material.color.setHex(nextColor);
            material.needsUpdate = true;
        });
    });
    requestRender();
}

function syncModelOutlines() {
    state.models.forEach((model) => {
        model.traverse((mesh) => {
            if (!isOutlineMesh(mesh)) return;
            const selected = isModelOutlineSelectionTarget(mesh, model);
            if (!state.outlineMode && !selected) {
                disposeModelOutlineLine(mesh.userData.outlineLine);
                return;
            }
            if (mesh.userData.outlineLine
                && mesh.userData.outlineLine.userData.outlineGeometrySource !== mesh.geometry) {
                disposeModelOutlineLine(mesh.userData.outlineLine);
            }
            if (!mesh.userData.outlineLine) {
                const edgeGeometry = new THREE.EdgesGeometry(mesh.geometry, 28);
                const lineMaterial = new THREE.LineBasicMaterial({
                    color: 0x000000,
                    transparent: true,
                    opacity: 0.95,
                    depthTest: true,
                    depthWrite: false,
                    toneMapped: false
                });
                const line = new THREE.LineSegments(edgeGeometry, lineMaterial);
                line.name = 'Cartoon Outline';
                line.renderOrder = 30;
                line.frustumCulled = false;
                line.userData.outlineSource = true;
                line.userData.outlineGeometrySource = mesh.geometry;
                mesh.add(line);
                mesh.userData.outlineLine = line;
            }
            const line = mesh.userData.outlineLine;
            const transparency = getModelTransparencyForObject(mesh, model);
            applyModelTransparencyToMaterial(line.material, transparency);
            line.visible = transparency < 100
                && (state.outlineMode || selected);
        });
    });
    updateModelSelectionOutlines({ ensureSelection: false });
}

function updateOutlineToggleUi() {
    const button = el.btnToggleOutline;
    if (!button) return;
    button.classList.toggle('active', state.outlineMode);
    button.setAttribute('aria-pressed', String(state.outlineMode));
    button.title = uiText(state.outlineMode ? '외곽선 끄기' : '외곽선 켜기');
    button.setAttribute('aria-label', uiText('외곽선 표시/숨김'));
}

function setModelOutlineMode(enabled) {
    state.outlineMode = Boolean(enabled);
    syncModelOutlines();
    updateOutlineToggleUi();
    scheduleMotionProjectSave();
}

function disposeObjectResources(object, disposed = null) {
    const cache = disposed || {
        geometries: new Set(),
        materials: new Set(),
        textures: new Set()
    };
    object.traverse((child) => {
        if (child.geometry && !cache.geometries.has(child.geometry)) {
            cache.geometries.add(child.geometry);
            child.geometry.dispose();
        }
        const collisionGeometry = child.userData?.collisionGeometry;
        if (collisionGeometry && !cache.geometries.has(collisionGeometry)) {
            cache.geometries.add(collisionGeometry);
            collisionGeometry.dispose();
        }
        const materials = Array.isArray(child.material) ? child.material : [child.material];
        materials.forEach((material) => {
            if (!material || cache.materials.has(material)) return;
            cache.materials.add(material);
            Object.values(material).forEach((value) => {
                if (value?.isTexture && !cache.textures.has(value)) {
                    cache.textures.add(value);
                    value.dispose();
                }
            });
            material.dispose();
        });
    });
    return cache;
}

function attachPendingToolModels(robot) {
    const mountFrame = getRobotToolMountFrame(robot);
    state.models.forEach((model) => {
        const transform = model.userData.pendingToolAttachment;
        if (transform && mountFrame) {
            mountFrame.add(model);
            model.position.fromArray(transform.position);
            model.quaternion.fromArray(transform.quaternion);
            model.scale.fromArray(transform.scale);
            model.userData.attachmentHost = robot;
            model.userData.attachmentFrame = 'flange';
            model.userData.placement = 'tcp';
            delete model.userData.pendingToolAttachment;
            model.updateMatrixWorld(true);
            return;
        }
        const gripObjectTransform = model.userData.pendingGripObjectAttachment;
        if (gripObjectTransform && mountFrame) {
            mountFrame.add(model);
            model.position.fromArray(gripObjectTransform.position);
            model.quaternion.fromArray(gripObjectTransform.quaternion);
            model.scale.fromArray(gripObjectTransform.scale);
            model.userData.attachmentHost = robot;
            model.userData.attachmentFrame = 'grip';
            model.userData.placement = 'grip-object';
            model.visible = gripObjectTransform.visible !== false;
            delete model.userData.pendingGripObjectAttachment;
            model.updateMatrixWorld(true);
            return;
        }
        const armLoadTransform = model.userData.pendingArmLoadAttachment;
        if (!armLoadTransform) return;
        const jointIndex = normalizeArmLoadJointIndex(armLoadTransform.attachmentJointIndex);
        const armLoadMountFrame = getRobotJointMountFrame(robot, jointIndex);
        if (!armLoadMountFrame) return;
        armLoadMountFrame.add(model);
        model.position.fromArray(armLoadTransform.position);
        model.quaternion.fromArray(armLoadTransform.quaternion);
        model.scale.fromArray(armLoadTransform.scale);
        model.userData.attachmentHost = robot;
        model.userData.attachmentFrame = 'joint';
        model.userData.attachmentJointIndex = jointIndex;
        model.userData.attachmentAxis = `J${jointIndex + 1}`;
        model.userData.placement = 'arm-load';
        model.userData.armLoadProperties = normalizeArmLoadProperties(armLoadTransform.armLoadProperties);
        model.visible = armLoadTransform.visible !== false;
        delete model.userData.pendingArmLoadAttachment;
        model.updateMatrixWorld(true);
    });
    syncModelTreeHiddenHost(robot);
}

function removeRobotForReplacement(robot) {
    if (!robot || !state.models.includes(robot)) return false;

    const attachedModels = state.models.filter((model) => (
        model !== robot && model.userData.attachmentHost === robot
    ));
    attachedModels.forEach((model) => {
        const toolHost = model.userData.placement === 'tcp'
            && getRobotToolMountFrame(robot);
        if (toolHost) {
            model.userData.pendingToolAttachment = {
                position: model.position.toArray(),
                quaternion: model.quaternion.toArray(),
                scale: model.scale.toArray()
            };
        }
        const gripObjectHost = model.userData.placement === 'grip-object'
            && getRobotToolMountFrame(robot);
        if (gripObjectHost) {
            model.userData.pendingGripObjectAttachment = {
                position: model.position.toArray(),
                quaternion: model.quaternion.toArray(),
                scale: model.scale.toArray(),
                visible: model.visible !== false
            };
        }
        const armLoadHost = model.userData.placement === 'arm-load'
            && getRobotJointMountFrame(robot, getArmLoadJointIndex(model));
        if (armLoadHost) {
            model.userData.pendingArmLoadAttachment = {
                position: model.position.toArray(),
                quaternion: model.quaternion.toArray(),
                scale: model.scale.toArray(),
                attachmentJointIndex: getArmLoadJointIndex(model),
                armLoadProperties: normalizeArmLoadProperties(model.userData.armLoadProperties),
                visible: model.visible !== false
            };
        }
        model.updateMatrixWorld(true);
        state.scene.attach(model);
        model.userData.attachmentHost = null;
        model.userData.attachmentFrame = null;
        model.userData.placement = 'scene';
    });

    const motionInstanceId = robot.userData.motionInstanceId;
    forgetOlpProjectForRobot(robot);
    clearTcpPathForRobot(robot);
    if (motionInstanceId) state.motionPrograms.delete(motionInstanceId);
    if (motionInstanceId) {
        getVirtualControllerSessions().slice().forEach((controller) => {
            if (controller.targetRobotId === motionInstanceId && controller.wanted) {
                disconnectVirtualController(controller);
            }
        });
        if (state.virtualController.targetRobotId === motionInstanceId) {
            state.virtualController.targetRobotId = null;
        }
    }
    if (state.activeArticulatedModel === robot) state.activeArticulatedModel = null;
    if (state.activeProgramRobot === robot) state.activeProgramRobot = null;
    if (state.baseJogGizmoRobot === robot) state.baseJogGizmoRobot = null;
    disposeCollisionDebugForModel(robot);
    disposeModelOutlines(robot);
    robot.removeFromParent();
    const index = state.models.indexOf(robot);
    if (index > -1) state.models.splice(index, 1);
    if (state.selectedModel === robot) state.selectedModel = null;
    markSceneCollisionDirty();
    return true;
}

function cleanupScene() {
    if (state.sketch.active) exitSketchMode({ restoreCamera: false });
    if (state.zeroPointEdit.active) exitZeroPointEditor();
    clearTcpPathOverlay();
    invalidateSimulationSnapCandidates();
    setBaseJogGizmoEnabled(false);
    state.transformControls.detach();
    const models = [...state.models];
    const preservedImportedModels = models.filter((model) => model.userData.uploaded);
    preservedImportedModels.forEach((model) => {
        const toolHost = model.userData.placement === 'tcp'
            && getRobotToolMountFrame(model.userData.attachmentHost);
        if (toolHost) {
            model.userData.pendingToolAttachment = {
                position: model.position.toArray(),
                quaternion: model.quaternion.toArray(),
                scale: model.scale.toArray()
            };
        }
        const gripObjectHost = model.userData.placement === 'grip-object'
            && getRobotToolMountFrame(model.userData.attachmentHost);
        if (gripObjectHost) {
            model.userData.pendingGripObjectAttachment = {
                position: model.position.toArray(),
                quaternion: model.quaternion.toArray(),
                scale: model.scale.toArray(),
                visible: model.visible !== false
            };
        }
        const armLoadHost = model.userData.placement === 'arm-load'
            && getRobotJointMountFrame(model.userData.attachmentHost, getArmLoadJointIndex(model));
        if (armLoadHost) {
            model.userData.pendingArmLoadAttachment = {
                position: model.position.toArray(),
                quaternion: model.quaternion.toArray(),
                scale: model.scale.toArray(),
                attachmentJointIndex: getArmLoadJointIndex(model),
                armLoadProperties: normalizeArmLoadProperties(model.userData.armLoadProperties),
                visible: model.visible !== false
            };
        }
        model.updateMatrixWorld(true);
        state.scene.attach(model);
        model.userData.attachmentHost = null;
        model.userData.attachmentFrame = null;
        model.userData.placement = 'scene';
    });
    models.filter((model) => !preservedImportedModels.includes(model)).forEach((model) => {
        if (model.userData.motionInstanceId) {
            forgetOlpProjectForRobot(model);
            state.motionPrograms.delete(model.userData.motionInstanceId);
        }
        disposeCollisionDebugForModel(model);
        disposeModelOutlines(model);
        if (isPrimitiveShapeModel(model) || isSketchFeatureModel(model)) disposeObjectResources(model);
        model.removeFromParent();
    });
    disposePrimitiveDimensionOverlay();
    state.models = preservedImportedModels;
    markSceneCollisionDirty();
    state.selectedModel = preservedImportedModels.includes(state.selectedModel) ? state.selectedModel : null;
    state.activeArticulatedModel = null;
    state.activeProgramRobot = null;
    hideJogPanel();
    renderModelTree();
    el.modelTransformPanel.classList.add('hidden');
    renderMotionProgramPanel();
    refreshCollisionDebugOverlays();
    checkSceneCollisions({ force: true });
}

function deleteSelectedModel({ allowDuringMotion = false } = {}) {
    const model = state.selectedModel;
    if (!model) return;
    if ((!allowDuringMotion && isRobotMotionActive())
        || (allowDuringMotion && isModelMotionActive(model))) {
        if (allowDuringMotion) {
            setStatus('현재 실행 중인 로봇은 모션을 정지한 후 삭제할 수 있습니다.', '#f59e0b');
        }
        return;
    }
    if (state.zeroPointEdit.active) exitZeroPointEditor();
    invalidateSimulationSnapCandidates();
    commitAllPendingHistories();
    setBaseJogGizmoEnabled(false);
    const historyBefore = captureSceneSnapshot();

    const attachments = state.models.filter((candidate) => candidate.userData.attachmentHost === model);
    const modelsToDelete = [model, ...attachments];
    const toolSourceMatches = modelsToDelete.map((item) => ({
        item,
        source: item.userData?.toolAttachmentSource?.mode === 'part-copy'
            ? getToolAttachmentSourcePart(item)
            : null
    }));
    if (modelsToDelete.includes(state.toolLoadInfo.selectedModel)) closeToolLoadInfoPanel();
    state.transformControls.detach();
    toolSourceMatches.forEach(({ item, source }) => {
        if (source) restoreToolAttachmentSourcePart(item);
    });
    modelsToDelete.forEach((item) => {
        clearTcpPathForRobot(item);
        if (item.userData.motionInstanceId) {
            forgetOlpProjectForRobot(item);
            state.motionPrograms.delete(item.userData.motionInstanceId);
        }
        disposeCollisionDebugForModel(item);
        disposeModelOutlines(item);
        if (item.userData?.toolAttachmentSource?.mode === 'part-copy') {
            disposeClipboardTemplateMaterials(item);
        }
        item.removeFromParent();
        if (isCad2dModel(item)) {
            state.cad2d.documents.delete(item.userData.cadDocumentId);
            if (state.cad2d.activeDocumentId === item.userData.cadDocumentId) {
                state.cad2d.activeDocumentId = [...state.cad2d.documents.keys()].at(-1) || null;
                state.cad2d.selectedEntityIds.clear();
                state.cad2d.hoveredEntityId = null;
            }
            disposeObjectResources(item);
        }
        const index = state.models.indexOf(item);
        if (index > -1) state.models.splice(index, 1);
    });
    if (isPrimitiveShapeModel(model)) disposePrimitiveDimensionOverlay();
    markSceneCollisionDirty();

    if (state.activeArticulatedModel === model) {
        state.activeArticulatedModel = [...state.models].reverse().find((item) => item.userData.tcpFrame) || null;
        if (state.activeArticulatedModel) renderJogControls(state.activeArticulatedModel);
        else hideJogPanel();
    }
    if (state.activeProgramRobot === model) state.activeProgramRobot = state.activeArticulatedModel;

    const formerHost = model.userData.attachmentHost;
    const nextSelection = formerHost && state.models.includes(formerHost)
        ? formerHost
        : state.models[state.models.length - 1] || null;
    updateUIStatus();
    selectSceneModel(nextSelection);
    renderMotionProgramPanel();
    recordHistory('모델 삭제', historyBefore, captureSceneSnapshot());
    sendCollaborationSceneCommand({
        kind: 'delete',
        workspaceModelId: ensureWorkspaceModelId(model)
    });
}

function syncEmptyStateVisibility() {
    if (!el.emptyState) return;
    const hasTrackedModel = state.models.length > 0;
    const hasSceneModel = state.scene?.children?.some((child) => (
        child?.userData?.robotName
        || child?.userData?.modelName
        || child?.userData?.uploaded
        || child?.userData?.primitiveShapeType
        || child?.userData?.sketchDocument
        || child?.userData?.cadDocumentId
    ));
    el.emptyState.classList.toggle('hidden', hasTrackedModel || Boolean(hasSceneModel));
}

function updateUIStatus() {
    updateLargeModelPerformanceMode();
    syncModelOutlines();
    const names = state.models.map(m => m.userData.modelName);
    el.statName.textContent = names.length > 1 ? `${names[0]} (+${names.length-1})` : (names[0] || '-');
    syncEmptyStateVisibility();
    renderModelTree();
    renderPrimitiveShapePanel();
    updatePrimitiveDimensionOverlay();
    renderArmLoadPanel();
    renderToolLoadInfoPanel();
    refreshImportPlacementOptions();
    updatePanelLauncher('collaboration-panel');
    refreshInterferenceZoneDialogRobotOptions();
    renderInterferenceZonePanel();
    updateInterferenceZoneVisuals();
    evaluateInterferenceZones(performance.now());
    setStatus('Ready', '#22c55e');
    requestRender();
}

const SIMULATION_MANUAL_TIMELINE = Object.freeze({
    jog: [13000, 16000],
    snap: [41500, 44500],
    programPoseA: [49500, 51000],
    programPoseB: [53100, 54500]
});

function installSimulationManualGuide() {
    if (!IS_MANUAL_GUIDE_EMBED || window.InoRobotSimulationManual) return;

    const manual = {
        preparing: null,
        prepared: false,
        paused: true,
        cue: '',
        milestone: 'blank',
        snapshots: new Map(),
        robotCatalogKey: 'robot:IR-S4-40Z15',
        homeAngles: [],
        jogAngles: [],
        snapAngles: [],
        programPoseA: [],
        programPoseB: [],
        snapSelection: null,
        snapTarget: null
    };

    const waitForManualCondition = (test, timeout = 45000, interval = 80) => new Promise((resolve, reject) => {
        const started = performance.now();
        const poll = () => {
            let result = null;
            try { result = test(); } catch { result = null; }
            if (result) {
                resolve(result);
                return;
            }
            if (performance.now() - started >= timeout) {
                reject(new Error('3D Simulation manual preparation timed out.'));
                return;
            }
            window.setTimeout(poll, interval);
        };
        poll();
    });

    const activeManualRobot = () => state.activeArticulatedModel
        || getArticulatedRobots().find((robot) => robot.userData.motionModelFolder === 'IR-S4-40Z15')
        || getArticulatedRobots()[0]
        || null;

    const clampManualAngles = (robot, values) => (robot?.userData.joints || []).map((joint, index) => (
        THREE.MathUtils.clamp(
            Number.isFinite(Number(values[index])) ? Number(values[index]) : joint.angle,
            joint.definition.min,
            joint.definition.max
        )
    ));

    const setManualJointAngles = (values) => {
        const robot = activeManualRobot();
        if (!robot) return false;
        const angles = clampManualAngles(robot, values);
        angles.forEach((angle, index) => setJointAngle(robot.userData.joints[index], angle, false));
        robot.updateMatrixWorld(true);
        syncJointControls(robot);
        captureCurrentTcpTarget(robot);
        updateTcpPresentation(robot);
        requestRender();
        return true;
    };

    const captureManualMilestone = (name) => {
        manual.snapshots.set(name, captureSceneSnapshot());
        return manual.snapshots.get(name);
    };

    const closeManualDialogs = () => {
        if (el.testModelDialog?.open) el.testModelDialog.close();
        const importDialog = document.getElementById('import-3d-dialog');
        if (importDialog?.open) importDialog.close();
        showLoading(false);
    };

    const clearManualSnapUi = () => {
        state.snapMoveMode = false;
        clearSimulationSnapFaceSelection();
        hideSimulationSnapMarker();
        resetSimulationSnapMarkerCameraScale();
        updateSimulationSnapButton();
    };

    const applyManualMilestone = (name, { fit = true } = {}) => {
        const snapshot = manual.snapshots.get(name);
        if (!snapshot) return false;
        stopRobotMotions(getArticulatedRobots());
        closeManualDialogs();
        clearManualSnapUi();
        applySceneSnapshot(snapshot);
        manual.milestone = name;
        if (el.modelSelect) el.modelSelect.value = name === 'blank' ? '' : manual.robotCatalogKey;
        if (fit && state.models.length) fitCamera();
        requestRender();
        return true;
    };

    const manualFaceEntries = (model) => {
        const entries = [];
        model?.updateMatrixWorld(true);
        model?.traverse((mesh) => {
            const position = mesh.isMesh ? mesh.geometry?.getAttribute('position') : null;
            if (!position) return;
            mesh.updateWorldMatrix?.(true, false);
            const faces = getValidatedStepBrepFaces(mesh)
                || Array.from({ length: Math.min(80, Math.floor((mesh.geometry.index?.count || position.count) / 3)) }, (_, index) => ({ first: index, last: index }));
            faces.forEach((face, faceIndex) => {
                const triangleIndex = Number(face.first);
                const indices = getSimulationSnapTriangleVertexIndices(mesh.geometry, triangleIndex);
                if (indices.some((index) => !Number.isInteger(index) || index < 0 || index >= position.count)) return;
                const points = indices.map((index) => new THREE.Vector3().fromBufferAttribute(position, index).applyMatrix4(mesh.matrixWorld));
                const normal = points[1].clone().sub(points[0]).cross(points[2].clone().sub(points[0])).normalize();
                const point = points[0].clone().add(points[1]).add(points[2]).multiplyScalar(1 / 3);
                const range = getSimulationSnapFaceTriangleRanges(mesh, triangleIndex);
                entries.push({
                    mesh,
                    point,
                    faceIndex: range.faceIndex ?? faceIndex,
                    triangleIndex,
                    key: range.key,
                    triangleRanges: range.triangleRanges,
                    upward: Math.abs(normal.z)
                });
            });
        });
        const robot = activeManualRobot();
        const pose = robot && getCurrentTcpPoseBase(robot);
        const tcpWorld = pose ? robot.localToWorld(pose.position.clone()) : new THREE.Vector3();
        return entries.sort((left, right) => (
            (left.upward >= 0.65 ? 0 : 1) - (right.upward >= 0.65 ? 0 : 1)
            || left.point.distanceToSquared(tcpWorld) - right.point.distanceToSquared(tcpWorld)
        ));
    };

    const projectManualSnapTarget = () => {
        if (!manual.snapTarget || !state.camera || !el.canvasContainer) return null;
        const bounds = state.renderer.domElement.getBoundingClientRect();
        const projected = manual.snapTarget.worldPoint.clone().project(state.camera);
        return {
            ...manual.snapTarget,
            screenX: (projected.x * 0.5 + 0.5) * bounds.width,
            screenY: (-projected.y * 0.5 + 0.5) * bounds.height,
            projected
        };
    };

    const tryManualSnapWorldPoint = (robot, startAngles, worldPoint, type = 'vertex') => {
        startAngles.forEach((angle, index) => setJointAngle(robot.userData.joints[index], angle, false));
        robot.updateMatrixWorld(true);
        if (!moveRobotTcpToSimulationSnap({ worldPoint: worldPoint.clone(), type })) return false;
        manual.snapTarget = { worldPoint: worldPoint.clone(), type };
        manual.snapAngles = robot.userData.joints.map((joint) => joint.angle);
        const visibleTarget = projectManualSnapTarget();
        if (visibleTarget) showSimulationSnapMarker(visibleTarget);
        return true;
    };

    const findManualSnapTarget = async () => {
        const robot = activeManualRobot();
        const equipment = state.models.find((model) => isTestModel(model) && model.userData.placement === 'scene');
        if (!robot || !equipment) return false;
        const startAngles = robot.userData.joints.map((joint) => joint.angle);
        const pose = getCurrentTcpPoseBase(robot);
        const tcpWorld = pose ? robot.localToWorld(pose.position.clone()) : new THREE.Vector3();
        state.snapMoveMode = true;
        updateSimulationSnapButton();

        for (const selection of manualFaceEntries(equipment).slice(0, 28)) {
            startAngles.forEach((angle, index) => setJointAngle(robot.userData.joints[index], angle, false));
            clearSimulationSnapFaceSelection();
            state.snapMoveMode = true;
            updateSimulationSnapButton();
            selectSimulationSnapFace(selection);
            try {
                await waitForManualCondition(() => state.snapCandidatesReady, 8000, 40);
            } catch {
                continue;
            }
            getSimulationSnapWorldIndex(getSimulationSnapMeshes('scene'));
            const typeOrder = new Map(['circle-center', 'rectangle-center', 'edge-midpoint', 'endpoint', 'vertex']
                .map((type, index) => [type, index]));
            const candidates = state.snapCandidates
                .filter((candidate) => candidate.snapWorldPoint || candidate.localPoint)
                .map((candidate) => ({
                    candidate,
                    worldPoint: candidate.snapWorldPoint?.clone()
                        || candidate.localPoint.clone().applyMatrix4(candidate.mesh.matrixWorld)
                }))
                .sort((left, right) => (
                    (typeOrder.get(left.candidate.type) ?? 99) - (typeOrder.get(right.candidate.type) ?? 99)
                    || left.worldPoint.distanceToSquared(tcpWorld) - right.worldPoint.distanceToSquared(tcpWorld)
                ));
            for (const item of candidates.slice(0, 60)) {
                if (!tryManualSnapWorldPoint(robot, startAngles, item.worldPoint, item.candidate.type)) continue;
                manual.snapSelection = cloneSimulationSnapFaceSelection(selection);
                return true;
            }
        }

        const bounds = new THREE.Box3().setFromObject(equipment);
        const center = bounds.getCenter(new THREE.Vector3());
        const size = bounds.getSize(new THREE.Vector3());
        const fallbackPoints = [
            center.clone().setZ(bounds.max.z),
            center.clone().add(new THREE.Vector3(size.x * 0.2, 0, size.z * 0.35)),
            center.clone().add(new THREE.Vector3(-size.x * 0.2, 0, size.z * 0.35))
        ];
        for (const worldPoint of fallbackPoints) {
            if (tryManualSnapWorldPoint(robot, startAngles, worldPoint, 'vertex')) return true;
        }

        startAngles.forEach((angle, index) => setJointAngle(robot.userData.joints[index], angle, false));
        syncJointControls(robot);
        captureCurrentTcpTarget(robot);
        updateTcpPresentation(robot);
        clearManualSnapUi();
        return false;
    };

    const prepareManualTestAssets = async () => {
        const robot = activeManualRobot();
        if (!robot) throw new Error('The manual robot is not ready.');
        const [equipmentFile, toolFile] = await Promise.all([
            loadTestModelAssetFile(TEST_MODEL_ASSET_PATHS.scene),
            loadTestModelAssetFile(TEST_MODEL_ASSET_PATHS.tcp)
        ]);
        removeExistingTestModels();
        if (!applyTestTcpProfile(robot)) throw new Error('Test TCP 1 is not available.');
        const equipment = await importTestModelFile(equipmentFile, 'scene', { testModel: true });
        const tool = await importTestModelFile(toolFile, 'tcp', {
            testModel: true,
            testToolPositionZero: true,
            testToolRotationX: robot.userData.manifest?.robotType === 'scara'
        });
        if (!equipment || !tool) throw new Error('The Test assets could not be prepared.');
        applyTestToolCollisionProfile(tool);
        fitCamera();
        requestRender();
    };

    const prepareManualProgramMilestones = () => {
        const robot = activeManualRobot();
        if (!robot) throw new Error('The manual robot is not ready.');
        const program = ensureMotionProgram(robot);
        program.steps = [];
        program.selectedStepId = null;
        program.status = 'idle';
        program.progress = 0;
        state.motionRepeatRobot = false;
        state.motionReverseRepeatRobot = false;
        syncMotionRepeatControl();
        renderMotionProgramPanel();
        captureManualMilestone('programBase');

        const center = manual.snapAngles.length
            ? manual.snapAngles
            : robot.userData.joints.map((joint) => joint.angle);
        manual.programPoseA = clampManualAngles(robot, center.map((value, index) => (
            index === 0 ? value - 24 : index === 1 ? value + 10 : value
        )));
        manual.programPoseB = clampManualAngles(robot, center.map((value, index) => (
            index === 0 ? value + 24 : index === 1 ? value - 10 : value
        )));

        setManualJointAngles(manual.programPoseA);
        captureManualMilestone('programPoseA');
        addCurrentMotionStep();
        const first = program.steps[0];
        if (first) {
            first.label = 'Pick';
            first.speed = 12;
        }
        renderMotionProgramPanel();
        captureManualMilestone('programP0');

        setManualJointAngles(manual.programPoseB);
        captureManualMilestone('programPoseB');
        addCurrentMotionStep();
        const second = program.steps[1];
        if (second) {
            second.label = 'Place';
            second.speed = 12;
        }
        program.selectedStepId = second?.id || first?.id || null;
        renderMotionProgramPanel();
        captureManualMilestone('programP1');

        state.motionRepeatRobot = true;
        state.motionReverseRepeatRobot = false;
        syncMotionRepeatControl();
        renderMotionProgramPanel();
        captureManualMilestone('programReady');
    };

    const prepare = async () => {
        if (manual.prepared) {
            applyManualMilestone('blank', { fit: false });
            return true;
        }
        if (manual.preparing) return manual.preparing;
        manual.preparing = (async () => {
            await waitForManualCondition(() => state.scene && state.renderer && state.catalog.size > 0);
            setCollisionModeState(COLLISION_MODE.OFF);
            clearCollisionStopNotice();
            updateCollisionUi();
            captureManualMilestone('blank');

            const definition = state.catalog.get(manual.robotCatalogKey)
                || [...state.catalog.values()].find((item) => item.folder === 'IR-S4-40Z15');
            if (!definition) throw new Error('IR-S4-40Z15 is not available.');
            await loadModelFromServer(definition);
            const robot = await waitForManualCondition(() => activeManualRobot(), 30000, 100);
            manual.homeAngles = robot.userData.joints.map((joint) => joint.angle);
            captureManualMilestone('robot');

            manual.jogAngles = clampManualAngles(robot, manual.homeAngles.map((value, index) => (
                index === 0 ? value + 24 : value
            )));
            setManualJointAngles(manual.jogAngles);
            captureManualMilestone('jog');

            await prepareManualTestAssets();
            captureManualMilestone('test');

            const snapped = await findManualSnapTarget();
            if (!snapped) {
                manual.snapAngles = [...manual.jogAngles];
                setManualJointAngles(manual.snapAngles);
            }
            captureManualMilestone('snap');
            prepareManualProgramMilestones();

            state.undoStack = [];
            state.redoStack = [];
            updateHistoryButtons();
            manual.prepared = true;
            applyManualMilestone('blank', { fit: false });
            return true;
        })().finally(() => {
            manual.preparing = null;
        });
        return manual.preparing;
    };

    const interpolateManualMilestone = (fromName, toAngles, startTime, endTime, time) => {
        const snapshot = manual.snapshots.get(fromName);
        const robotEntry = snapshot?.joints?.[0];
        if (!robotEntry || !toAngles.length) return;
        const raw = (Number(time) - startTime) / Math.max(1, endTime - startTime);
        const progress = sCurveProgress(THREE.MathUtils.clamp(raw, 0, 1));
        setManualJointAngles(robotEntry.angles.map((value, index) => (
            THREE.MathUtils.lerp(value, toAngles[index] ?? value, progress)
        )));
    };

    const interpolateManualJogJ1 = (time) => {
        const snapshot = manual.snapshots.get('robot');
        const robot = activeManualRobot();
        const j1 = robot?.userData.joints?.[0];
        const fromAngle = snapshot?.joints?.[0]?.angles?.[0];
        const toAngle = manual.jogAngles[0];
        if (!j1 || !Number.isFinite(fromAngle) || !Number.isFinite(toAngle)) return;
        const [startTime, endTime] = SIMULATION_MANUAL_TIMELINE.jog;
        const raw = (Number(time) - startTime) / Math.max(1, endTime - startTime);
        const progress = sCurveProgress(THREE.MathUtils.clamp(raw, 0, 1));
        const nextAngle = THREE.MathUtils.lerp(fromAngle, toAngle, progress);
        const range = j1.control?.range;
        const display = j1.control?.display || getJointJogDisplaySpec(j1);
        if (range) {
            range.value = formatJogValue(display.toDisplay(nextAngle));
            range.dispatchEvent(new Event('input', { bubbles: true }));
        } else {
            setJointAngle(j1, nextAngle);
            captureCurrentTcpTarget(robot);
        }
    };

    const setTimelineTime = (time) => {
        if (!manual.prepared) return;
        if (manual.cue === 'simulation_jog_move') {
            interpolateManualJogJ1(time);
        } else if (manual.cue === 'simulation_snap_move') {
            interpolateManualMilestone('test', manual.snapAngles, ...SIMULATION_MANUAL_TIMELINE.snap, time);
        } else if (manual.cue === 'simulation_program_pose_a') {
            interpolateManualMilestone('programBase', manual.programPoseA, ...SIMULATION_MANUAL_TIMELINE.programPoseA, time);
        } else if (manual.cue === 'simulation_program_pose_b') {
            interpolateManualMilestone('programP0', manual.programPoseB, ...SIMULATION_MANUAL_TIMELINE.programPoseB, time);
        }
    };

    const setSnapMode = (enabled) => {
        state.snapMoveMode = Boolean(enabled);
        if (enabled) {
            if (state.tcpSnapMode) setTcpSnapMode(false);
            setJogMode('base', { preserveSnapMove: true });
        } else {
            clearSimulationSnapFaceSelection();
            setBaseJogGizmoEnabled(true);
        }
        updateSimulationSnapButton();
        if (enabled) captureSimulationSnapMarkerReferenceDistance();
    };

    const showSnapSelection = () => {
        setSnapMode(true);
        if (manual.snapSelection) selectSimulationSnapFace(manual.snapSelection);
        requestRender();
    };

    const showSnapTarget = () => {
        setSnapMode(true);
        const target = projectManualSnapTarget();
        if (target) showSimulationSnapMarker(target);
        requestRender();
    };

    const showProgramPanelForManual = () => {
        showMotionProgramPanel();
        el.programPanel?.classList.remove('panel-user-hidden');
        updatePanelLauncher('program-panel');
        renderMotionProgramPanel();
    };

    const setManualPanelVisible = (panelId, visible) => {
        const panel = getPanelElement(panelId);
        if (!panel) return false;
        if (!visible) {
            if (isPanelOpenInDocument(panel)) handlePanelAction('hide', panelId);
            else panel.classList.add('panel-user-hidden');
            updatePanelLauncher(panelId);
            updatePanelStack();
            return true;
        }
        if (panelId === 'program-panel') showMotionProgramPanel();
        if (panelId === 'jog-panel') {
            const robot = activeManualRobot();
            if (robot && (panel.classList.contains('hidden') || !el.jogControls?.children.length)) {
                renderJogControls(robot);
            }
            if (robot) syncJointControls(robot);
        }
        panel.classList.remove('hidden', 'panel-user-hidden');
        updatePanelLauncher(panelId);
        bringPanelToFront(panelId);
        return true;
    };

    const focusManualRobot = () => {
        const robot = activeManualRobot();
        if (!robot || !state.camera || !state.controls) return false;
        robot.updateMatrixWorld(true);
        const box = new THREE.Box3().setFromObject(robot);
        if (box.isEmpty()) return false;
        const sphere = box.getBoundingSphere(new THREE.Sphere());
        const verticalFov = THREE.MathUtils.degToRad(state.camera.fov || 50);
        const horizontalFov = 2 * Math.atan(Math.tan(verticalFov / 2) * Math.max(0.1, state.camera.aspect || 1));
        const limitingFov = Math.max(0.1, Math.min(verticalFov, horizontalFov));
        const distance = Math.max(1, sphere.radius * 1.3 / Math.sin(limitingFov / 2));
        const direction = new THREE.Vector3(0.8, -0.8, 0.55).normalize();
        state.camera.up.set(0, 0, 1);
        state.camera.position.copy(sphere.center).addScaledVector(direction, distance);
        state.camera.lookAt(sphere.center);
        state.controls.target.copy(sphere.center);
        state.controls.update();
        requestRender();
        return true;
    };

    const startProgram = () => {
        applyManualMilestone('programReady');
        showProgramPanelForManual();
        runActiveRobotProgram();
        if (manual.paused) pauseRobotMotions([activeManualRobot()].filter(Boolean));
        requestRender();
    };

    const ensureProgramRunning = () => {
        const robot = activeManualRobot();
        if (!robot) return false;
        const program = ensureMotionProgram(robot);
        if (program.steps.length !== 2 || !state.motionRepeatRobot) {
            applyManualMilestone('programReady');
        }
        const session = getMotionSession(robot);
        if (session?.status === 'paused') resumePausedRobotMotions([robot]);
        else if (!session || session.status !== 'running') runActiveRobotProgram();
        if (manual.paused) pauseRobotMotions([robot]);
        requestRender();
        return ['running', 'paused'].includes(getMotionStatus(robot));
    };

    const setPaused = (paused) => {
        manual.paused = Boolean(paused);
        const robot = activeManualRobot();
        if (!robot) return;
        if (manual.paused) pauseRobotMotions([robot]);
        else resumePausedRobotMotions([robot]);
    };

    const reset = () => {
        manual.cue = '';
        setPaused(true);
        closeManualDialogs();
        if (manual.prepared) applyManualMilestone('blank', { fit: false });
    };

    window.InoRobotSimulationManual = Object.freeze({
        prepare,
        applyMilestone: applyManualMilestone,
        setCue: cue => { manual.cue = String(cue || ''); },
        setTimelineTime,
        setPaused,
        reset,
        showLoading: (show, text = '불러오는 중...') => showLoading(Boolean(show), uiText(text)),
        showTestDialog: () => {
            if (el.testModelDialog && !el.testModelDialog.open) el.testModelDialog.showModal();
        },
        closeTestDialog: () => { if (el.testModelDialog?.open) el.testModelDialog.close(); },
        showModelSelection: selected => {
            if (el.modelSelect) el.modelSelect.value = selected ? manual.robotCatalogKey : '';
        },
        setJogMode,
        setSnapMode,
        showSnapSelection,
        showSnapTarget,
        getSnapScreenPoint: () => {
            const target = projectManualSnapTarget();
            const bounds = state.renderer?.domElement.getBoundingClientRect();
            return target && bounds ? { x:bounds.left + target.screenX, y:bounds.top + target.screenY } : null;
        },
        showProgramPanel: showProgramPanelForManual,
        setPanelVisible: setManualPanelVisible,
        focusRobot: focusManualRobot,
        startProgram,
        ensureProgramRunning,
        getState: () => ({
            prepared: manual.prepared,
            cue: manual.cue,
            milestone: manual.milestone,
            robotName: activeManualRobot()?.userData.motionDisplayName || '',
            joints: activeManualRobot()?.userData.joints.map((joint) => joint.angle) || [],
            testScene: state.models.some((model) => isTestModel(model) && model.userData.placement === 'scene'),
            testTool: state.models.some((model) => isTestModel(model) && model.userData.placement === 'tcp'),
            snapReady: Boolean(manual.snapTarget),
            programSteps: activeManualRobot() ? ensureMotionProgram(activeManualRobot()).steps.length : 0,
            repeat: state.motionRepeatRobot,
            motionStatus: activeManualRobot() ? getMotionStatus(activeManualRobot()) : 'idle',
            modelSelectValue: el.modelSelect?.value || '',
            panels: {
                model: isPanelOpenInDocument(el.modelBrowserPanel),
                jog: isPanelOpenInDocument(el.jogPanel),
                program: isPanelOpenInDocument(el.programPanel)
            }
        })
    });
}

function requiresContinuousRendering() {
    return isViewWindowOpen()
        || isVirtualControllerActive()
        // OLP itself does not need a 60 FPS scene loop while it is waiting on
        // IO or executing non-motion lines. Motion functions call
        // requestRender() for each animation frame, so keep continuous
        // rendering only for active OLP motion/control work.
        || state.olp.workOriginBusy
        || state.olp.manualMoveBusy
        || [...(state.olp.runtimes?.values() || [])].some((runtime) => Boolean(runtime?.pendingMotions?.size))
        || [...state.motionSessions.values()].some((session) => session.status === 'running');
}

function getRenderWindow() {
    const popup = state.viewWindow?.popup;
    return popup && !popup.closed && typeof popup.requestAnimationFrame === 'function'
        ? popup
        : window;
}

function requestRender() {
    if (!state.renderer || state.renderFramePending) return;
    state.renderFramePending = true;
    // When the fixed-view panel is detached, the opener can be backgrounded by
    // the browser. Schedule the scene loop in the visible popup so camera input
    // and robot motion continue to repaint at the expected rate. Always pass the
    // opener's monotonic clock to animate because each window has its own
    // requestAnimationFrame timestamp origin.
    getRenderWindow().requestAnimationFrame(() => animate(performance.now()));
}

function animate(timestamp = performance.now()) {
    state.renderFramePending = false;
    if (!state.collision.lastCheckSkipped) captureCollisionSafeRobotPoses();
    applyVirtualControllerFrame(timestamp);
    updateMotionSessions(timestamp);
    updateCycleTimeReadout(timestamp);
    const collision = checkSceneCollisions();
    getVirtualControllerSessions().forEach((controller) => {
        updateControllerGripInference(timestamp, collision, controller);
    });
    const collisionFresh = !state.collision.lastCheckSkipped;
    if (collisionFresh) releaseClearedMotionCollisionIgnores(collision);
    const blockingMotionCollision = collisionStopsMotion()
        ? getBlockingMotionCollision(collision)
        : null;
    // Controller input (virtual or real) is simulation-only feedback. A
    // collision must not reject/restore the received pose or alter the
    // controller connection; updateCollisionStatus() above already keeps the
    // visual collision result red.
    if (collisionFresh && blockingMotionCollision && state.motionSessions.size > 0) {
        const movingRobots = [...state.motionSessions.values()].map((session) => session.robot);
        stopRobotMotions(movingRobots);
        latchCollisionStopNotice(collision, '충돌이 감지되어 모션을 정지했습니다.');
        setMotionProgramStatus('충돌이 감지되어 모션을 정지했습니다.', 'error');
    } else if (collisionFresh && blockingMotionCollision && isOlpRunning()) {
        [...(state.olp.runtimes?.values() || [])]
            .filter((runtime) => runtime?.running)
            .forEach((runtime) => runtime.stop());
        latchCollisionStopNotice(collision, '충돌이 감지되어 OLP 모션을 정지했습니다.');
        setOlpStatus('error', '충돌이 감지되어 OLP 모션을 정지했습니다.');
    } else if (collisionFresh && !asCollisionResults(collision).length) {
        captureCollisionSafeRobotPoses();
    }
    evaluateInterferenceZones(timestamp);
    state.controls.update();
    updateCameraScaledTcpAxes();
    updateCameraScaledWorkObjectAxes();
    updateSimulationSnapMarkerCameraScale();
    updateSimulationSnapCandidateMarkers();
    updateMeasurementOverlay();
    updatePrimitiveDimensionOverlay();
    updateSketchPreview();
    state.renderer.render(state.scene, state.camera);
    renderViewWindow();
    updateZeroPointCurrentMarker();
    if (requiresContinuousRendering()) requestRender();
}

function onResize() {
    const w = el.canvasContainer.clientWidth, h = el.canvasContainer.clientHeight;
    if (state.camera.isOrthographicCamera) {
        const verticalSpan = Math.max(0.001, state.camera.top - state.camera.bottom);
        const verticalCenter = (state.camera.top + state.camera.bottom) * 0.5;
        const halfHeight = verticalSpan * 0.5;
        const halfWidth = halfHeight * Math.max(0.1, w / Math.max(1, h));
        const horizontalCenter = (state.camera.left + state.camera.right) * 0.5;
        state.camera.left = horizontalCenter - halfWidth;
        state.camera.right = horizontalCenter + halfWidth;
        state.camera.top = verticalCenter + halfHeight;
        state.camera.bottom = verticalCenter - halfHeight;
    } else {
        state.camera.aspect = w / h;
    }
    state.camera.updateProjectionMatrix();
    state.renderer.setSize(w, h);
    [el.modelBrowserPanel, el.jogPanel, el.tcpProfilePanel, el.workObjectPanel, el.virtualControllerPanel, el.collaborationPanel, el.viewPresetsPanel, el.interferenceZonePanel, el.ioSimulatorPanel, el.programPanel, el.measurementPanel, el.shapePanel, el.toolLoadInfoPanel, el.workOriginDialog].forEach((panel) => {
        if (panel?.dataset.userResized === 'true') normalizePanelResizeBox(panel);
        else if (panel === el.workOriginDialog) constrainWorkOriginDialogToLayoutBounds();
    });
    resizeViewWindow();
    requestRender();
}

function fitCameraToBounds(bounds, { topOnly = false } = {}) {
    if (!bounds || bounds.isEmpty() || !state.camera || !state.controls) return false;
    const size = bounds.getSize(new THREE.Vector3());
    const center = bounds.getCenter(new THREE.Vector3());
    const aspect = Math.max(0.1, state.camera.aspect || 1);
    let distance;

    if (topOnly) {
        distance = Math.max(size.x, size.y / aspect, 10) * 1.25;
        // The top-view orientation is an explicit view command. Keep the
        // regular 3D fit path on the same Z-up camera orientation used by the
        // rest of the viewer so OrbitControls does not inherit CAD-only state.
        setCameraUpFromPreset(state.camera, [1, 0, 0]);
        state.camera.position.set(center.x, center.y, center.z + distance);
    } else {
        distance = Math.max(size.length(), 10) * 1.5;
        setCameraUpFromPreset(state.camera, [0, 0, 1]);
        state.camera.position.set(
            center.x + distance * 0.8,
            center.y - distance * 0.8,
            center.z + distance * 0.5
        );
    }

    state.controls.target.copy(center);
    state.camera.lookAt(center);
    state.controls.update();
    if (state.snapMoveMode) captureSimulationSnapMarkerReferenceDistance();
    requestRender();
    return true;
}

function fitCamera() {
    if (state.sketch.active) {
        positionSketchCameraAtScene();
        requestRender();
        return;
    }
    if (state.models.length === 0) return;
    const box = new THREE.Box3();
    state.models.forEach(m => box.expandByObject(m));
    fitCameraToBounds(box);
}

async function populateModelList() {
    try {
        const res = await fetch('./models/models.json?v=20260724-j3-angle-display-1');
        const list = await res.json();
        state.catalog.clear();
        el.modelSelect.innerHTML = `<option value="" disabled selected>${uiText('-- 로봇 모델을 선택하세요 --')}</option>`;
        let currentGroup = null;
        list.forEach(m => {
            if (m.group) {
                currentGroup = document.createElement('optgroup');
                currentGroup.label = m.group;
                el.modelSelect.appendChild(currentGroup);
            } else {
                const catalogKey = m.file || `robot:${m.folder}`;
                state.catalog.set(catalogKey, m);
                const opt = document.createElement('option');
                opt.value = catalogKey;
                opt.textContent = m.name;
                (currentGroup || el.modelSelect).appendChild(opt);
            }
        });
    } catch (e) { console.error('Failed to load model list:', e); }
}

function showLoading(show, text = uiText('불러오는 중...'), progress = null) {
    el.loadingOverlay.classList.toggle('hidden', !show);
    el.loadingText.textContent = text;
    const isIndeterminate = show && progress && typeof progress === 'object'
        && progress.indeterminate === true;
    const hasProgress = show && (isIndeterminate || Number.isFinite(Number(progress)));
    const normalizedProgress = Math.round(THREE.MathUtils.clamp(Number(progress) || 0, 0, 100));
    el.loadingProgress?.classList.toggle('hidden', !hasProgress);
    el.loadingProgressText?.classList.toggle('hidden', !hasProgress);
    if (hasProgress) {
        el.loadingProgress.classList.toggle('is-indeterminate', isIndeterminate);
        if (isIndeterminate) {
            el.loadingProgress.removeAttribute('aria-valuenow');
            el.loadingProgress.setAttribute('aria-valuetext', progress.label || uiText('변환 진행률 계산 중...'));
            el.loadingProgressText.textContent = progress.label || uiText('변환 진행률 계산 중...');
        } else {
            el.loadingProgressBar.style.width = `${normalizedProgress}%`;
            el.loadingProgress.setAttribute('aria-valuenow', String(normalizedProgress));
            el.loadingProgress.setAttribute('aria-valuetext', `${normalizedProgress}%`);
            el.loadingProgressText.textContent = `${normalizedProgress}%`;
        }
    } else {
        el.loadingProgress?.classList.remove('is-indeterminate');
    }
}

function refreshViewerStatus() {
    if (!el.statStatus || !state.viewerStatus) return;
    el.statStatus.textContent = uiFormat(state.viewerStatus.text, state.viewerStatus.replacements);
    el.statusDot.style.color = state.viewerStatus.color;
}

function setStatus(text, color, replacements = {}) {
    state.viewerStatus = { text, color, replacements };
    refreshViewerStatus();
}

init();
